INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-38394','送僧归日本国','吳融','quantangshi','','卷39','沧溟分故国，渺渺泛杯归。
天尽终期到，人生此别稀。
无风亦骇浪，未午已斜晖。
系帛何须雁，金乌日日飞。','',''),('quantangshi-38395','送僧归破山寺','吳融','quantangshi','','卷39','万里指吴山，高秋杖锡还。
别来双阙老，归去片云闲。
师在有无外，我婴尘土间。
居然本相别，不要惨离颜。','',''),('quantangshi-38396','夏夜有寄','吳融','quantangshi','','卷39','月上簟如水，轩高帘在钩。
竹声寒不夏，蛩思静先秋。
偶得清宵兴，方知白日愁。
所思何处远，斜汉欲低流。','',''),('quantangshi-38397','春词','吳融','quantangshi','','卷39','鸾镜长侵夜，鸳衾不识寒。
羞多转面语，妬极定睛看。
金市旧居近，钿车新造宽。
春期莫相悞，一日百花残。','',''),('quantangshi-38398','汴上晚泊','吳融','quantangshi','','卷39','亭上风犹急，桥边月已斜。
柳寒难吐絮，浪浊不成花。
岐路春三月，园林海一涯。
萧然正无寐，夜橹莫咿哑。','',''),('quantangshi-38399','送僧南游','吳融','quantangshi','','卷39','战鼙鸣未已，瓶屦抵何乡。
偶别尘中易，贪归物外忙。
后蝉抛鄠杜，先雁下潇湘。
不得从师去，殷勤谢草堂。','',''),('quantangshi-38400','戏','吳融','quantangshi','','卷39','恨极同填海，情长抵导江。
丁香从小结，莲子彻枝双。
整髻花当槛，吹灯月在窗。
秦台非久计，早晚降霓幢。','',''),('quantangshi-38401','雪中寄虑延让秀才','吳融','quantangshi','','卷39','苦贫皆共雪，吾子岂同悲。
永日应无食，经宵必有诗。
渚宫寒过节，华省试临期。
努力图西去，休将冻馁辞。','',''),('quantangshi-38402','花村六韵','吳融','quantangshi','','卷39','地胜非离郭，花深故号村。
已怜梁雪重，仍愧楚云繁。
山近当吟冷，泉高入梦喧。
依稀小有洞，邂逅武陵源。
月好频移座，风轻莫闭门。
流莺更多思，百啭待黄昏。','',''),('quantangshi-38403','赋雪十韵','吳融','quantangshi','','卷39','雨冻轻轻下，风乹淅淅吹。
喜胜花发处，惊似客来时。
河静胶行棹，岩空响折枝。
终无鹧鸪识，先有鹡鸰知。
马势晨争急，雕声晚更饥。
替霜严柏署，藏月上龙墀。
百尺楼堪倚，千钱酒要追。
朝归紫阁早，漏出建章迟。
腊候何曾爽，春工是所资。
遥知故溪柳，排比万条丝。','',''),('quantangshi-38404','溪边','吳融','quantangshi','','卷39','溪边花满枝，百鸟带香飞。
下有一白鹭，日斜翘石矶。','',''),('quantangshi-38405','长安逢故人','吳融','quantangshi','','卷39','岁暮长安客，相逢酒一杯。
眼前闲事静，心里故山来。
池影含新草，林芳动早梅。
如何不归去，霜鬓共风埃。','',''),('quantangshi-38406','雨夜','吳融','quantangshi','','卷39','旅夕那禁雨，梅天已思秋。
未明孤枕倦，相吊一灯愁。
有恋惭沧海，无机奈白头。
何人得浓睡，溪上钓鱼舟。','',''),('quantangshi-38407','旅中送迁客','吳融','quantangshi','','卷39','天南不可去，君去吊灵均。
落日青山路，秋风白发人。
言危无继者，道在有明神。','',''),('quantangshi-38408','寄尚颜师','吳融','quantangshi','','卷39','僧中难得静，静得是吾师。
到阙不求紫，归山秪爱诗。
临风翘雪足，向日剃霜髭。
自叹眠漳久，双林动所思。','',''),('quantangshi-38409','微雨','吳融','quantangshi','','卷39','天青织未徧，风急舞难成。
粉重低飞蝶，黄沈不语莺。
自随春霭乱，还放夕阳明。
惆怅池塘上，荷珠点点倾。','',''),('quantangshi-38410','送广利大师东归','吳融','quantangshi','','卷39','紫殿久霑恩，东归过海门。
浮荣知是梦，轻别肯销魂。
明发先晨鸟，寒栖入暝猨。
蕺山如重到，应老旧云根。','',''),('quantangshi-38411','关东献兵部刘员外','吳融','quantangshi','','卷39','昨夜星辰动，仙郎近汉关。
玳筵吟雪罢，锦帐押春还。
已到青云上，应栖绛圃间。
临卭有词赋，一为奏天颜。','',''),('quantangshi-38412','途次淮口','吳融','quantangshi','','卷39','寒流万派碧，南渡见烟光。
人向隋宫近，山盘楚塞长。
有村皆绿暗，无径不红芳。
已带伤春病，如何更异乡。','',''),('quantangshi-38413','咏柳','吳融','quantangshi','','卷39','自与莺为地，不教花作媒。
细应和雨断，轻秪爱风裁。
好拂锦步障，莫遮铜雀台。
灞陵千万树，日暮别离回。','',''),('quantangshi-38414','武牢关遇雨','吳融','quantangshi','','卷39','泽春关路迥，暮雨细霏霏。
带雾昏河浪，和尘重客衣。
望中迷去骑，愁里乱斜晖。
惆怅家山远，溟蒙湿翠微。','',''),('quantangshi-38415','春寒','吳融','quantangshi','','卷39','固教梅忍落，休与杏藏娇。
已过冬疑剩，将来暖未饶。
玉堦残雪在，罗荐暗魂销。
莫问王孙事，烟芜正寂寥。','',''),('quantangshi-38416','早发潼关','吳融','quantangshi','','卷39','天边月初落，马上梦犹残。
关树苍苍晓，玉阶澹澹寒。
宦游终自苦，身世静堪观。
争似山中隐，和云枕碧湍。','',''),('quantangshi-38417','送策上人','吳融','quantangshi','','卷39','昨来非有意，今去亦无心。
阙下抛新院，江南指旧林。
瓶添新涧绿，笠卸晚峰阴。
八字如相许，终辞尺组寻。','',''),('quantangshi-38418','和诸学士秋夕禁直偶雪','吳融','quantangshi','','卷39','大华积秋雪，禁闱生夜寒。
砚冰忧诏急，灯烬惜更残。
正遂攀稽愿，翻追访戴欢。
更为三日约，高兴未将阑。','',''),('quantangshi-38419','御沟十六韵','吳融','quantangshi','','卷39','一水终南下，何年派作沟。
穿城初北注，过苑却东流。
绕岸清波溢，连宫瑞气浮。
去应涵凤沼，来必渗龙湫。
激石珠争碎，萦堤练不收。
照花长乐曙，泛叶建章秋。
影炫金茎表，光摇绮陌头。
旁沾画眉府，斜入教箫楼。
有雨难澄镜，无萍易掷钩。
鼓宜尧女瑟，荡必蔡姬舟。
臯着通鸣鹤，津应接斗牛。
回风还潋潋，和月更悠悠。
浅忆觞堪泛，深思杖可投。
秪怀泾合虑，不带陇分愁。
自有朝宗乐，曾无溃穴忧。
不劳夸大汉，清渭贯神州。','',''),('quantangshi-38420','赴阙次留献荆南成相公三十韵','吳融','quantangshi','','卷39','分阃兼文德，持衡有武功。
荆南知独去，海内更谁同。
拔地孤峰秀，当天一鹗雄。
云生五色笔，月吐六钧弓。
骨格凌秋耸，心源见底空。
神清飡沆瀣，气逸饮洪蒙。
临事成奇策，全身仗至忠。
解鞍欺李广，煮弩笑臧洪。
往昔逢多难，来兹故统戎。
卓旗云梦泽，扑火细腰宫。
铲土楼台构，连江雉堞笼。
似平铺掌上，疑涌出壶中。
岂是劳人力，宁因役鬼工。
本遗三户在，今匝万家通。
画舸横青雀，危樯列彩虹。
席飞巫峡雨，袖拂宋亭风。
塲广盘球子，池闲引钓筒。
礼贤金璧贱，煦物雪霜融。
酒满梁尘动，棊残漏滴终。
俭常资澹静，贵绝恃穹崇。
唯要臣诚显，那求帝渥隆。
甘棠名异奭，大树姓非冯。
自念为迁客，方谐谒上公。
痛知遭止棘，频叹委飘蓬。
借宅诛茅绿，分囷指粟红。
只惭燕馆盛，宁觉阮途穷。
涣汗霑明主，沧浪别钓翁。
去曾忧塞马，归欲逐边鸿。
积感深于海，衔恩重极嵩。
行行柳门路，回首下离东。','',''),('quantangshi-38421','三峰府内矮柏十韵','吳融','quantangshi','','卷39','擢秀依黄阁，移根自碧岑。
周围虽合抱，直上岂盈寻。
远砌行窥顶，当庭坐庇阴。
短堪惊众木，高已让他林。
日转无长影，风回有细音。
不容萝茑附，只耐雪霜侵。
玉帐笼应匝，牙旗倚更禁。
叶低宜拂席，枝褭易抽簪。
绿涧支离久，朱门掩映深。
何须一千丈，方有岁寒心。','',''),('quantangshi-38422','雪十韵','吳融','quantangshi','','卷39','洒密蔽璇穹，霏霏杳莫穷。
迟于雨到地，疾甚絮随风。
四野苍茫际，千家晃朗中。
夜迷三绕鹊，昼断一行鸿。
结片飞琼树，栽花点蘂宫。
壅应边尽北，填合海无东。
高爱危峰积，低愁暖气融。
月交都浩渺，日射更𤫩珑。
送腊辞寒律，迎春入旧丛。
自怜曾末至，聊复赋玄功。','',''),('quantangshi-38423','和睦州卢中丞题茅堂十韵','吳融','quantangshi','','卷39','有士当今重，忘情自古稀。
独开青嶂路，闲掩白云扉。
石累千层险，泉分一带微。
栋危猨竞下，檐迥鸟争归。
烟冷茶铛静，波香兰舸飞。
好移钟阜蓼，莫种首阳薇。
树密含轻雾，川空漾薄晖。
芝泥看只捧，蕙带且休围。
东郭邻穿履，西林近衲衣。
琼瑶一百字，千古见清机。','',''),('quantangshi-38424','奉和御制六韵','吳融','quantangshi','','卷39','天晓密云开，亭亭翠葆来。
芰荷笼水殿，杨柳蔽风台。
恩洽三时雨，欢腾万岁雷。
日华偏照御，星彩迥分台。
苇岸萦仙棹，莲峰倒玉杯。
独惭歌圣德，不是侍臣才。','',''),('quantangshi-38425','败帘六韵','吳融','quantangshi','','卷39','有客编来久，弥年断不收。
不堪风作候，岂复燕为讐。
尽见三重阁，难迷百尺楼。
伴灯微揜梦，兼扇劣遮羞。
零落亡珠缀，殷勤谢玉钩。
凉宵何必卷，月自入轩流。','',''),('quantangshi-38426','玉堂种竹六韵','吳融','quantangshi','','卷39','当砌植檀栾，浓阴五月寒。
引风穿玉牖，摇露滴金盘。
有韵和宫漏，无香杂畹兰。
地疑云鏁易，日近雪封难。
静称围棋会，闲宜阁笔看。
他年终结实，不羡树栖鸾。','',''),('quantangshi-38427','和韩致光侍郎无题三首十四韵 一','吳融','quantangshi','','卷39','珠佩元消暑，犀簪自辟尘。
揜灯容燕宿，开镜待鸡晨。
去嬾都忘旧，来多未厌新。
每逢忧是梦，长忆故延真。
杏小双圆压，山浓两点嚬。
瘦难胜宝带，轻欲驭飙轮。
箆凤金雕翼，钗鱼玉镂鳞。
月明无睡夜，花落断肠春。
解舞何须楚，能筝可在秦。
怯探同海底，稀遇极天津。
绿柰攀宫艳，青梅弄岭珍。
管纤银字咽，梭密锦书匀。
厌胜还随俗，无疑不避人。
可怜三五夕，娬媚善为邻。','',''),('quantangshi-38428','和韩致光侍郎无题三首十四韵 二','吳融','quantangshi','','卷39','舞转轻轻雪，歌霏漠漠尘。
漫游多卜夜，慵起不知晨。
玉箸和妆裛，金莲逐步新。
凤笙追北里，鹤驭访南真。
有恨都无语，非愁亦有嚬。
戏应过蚌浦，飞合入蟾轮。
杯样成言鸟，梳文解卧鳞。
逢迎大堤晚，离别洞庭春。
似玉曾夸赵，如云不让秦。
锦收花上露，珠引月中津。
木为连枝贵，禽因比翼珍。
万峰酥点薄，五色绣妆匀。
獭髓求鱼客，鲛绡托海人。
寸肠谁与达，洞府四无邻。','',''),('quantangshi-38429','和韩致光侍郎无题三首十四韵 三','吳融','quantangshi','','卷39','绮阁临初日，铜台拂暗尘。
鷾鸸偏报晓，乌鶂惯惊晨。
鱼网裁书数，鵾弦上曲新。
病多疑厄重，语切见心真。
子母钱征笑，西南月借嚬。
捣衣嫌独杵，分袂怨双轮。
贝叶教丹觜，金刀寄赤鳞。
卷帘吟塞雪，飞楫渡江春。
解织宜名蕙，能歌合姓秦。
眼穿回雁岭，魂断饮牛津。
药自偷来绝，香从窃去珍。
茗煎云沫聚，药种玉苗匀。
草密应迷客，花繁好避人。
长干足风雨，遥夜与谁邻。','',''),('quantangshi-38430','倒次元韵','吳融','quantangshi','','卷39','南陌来寻伴，东城去卜邻。
生憎无赖客，死忆有情人。
似束腰支细，如描发彩匀。
黄鹂裁帽贵，紫燕刻钗珍。
身近从淄右，家元接观津。
雨台谁属楚，花洞不知秦。
泪滴空牀冷，妆浓满镜春。
枕凉欹琥珀，簟洁展麒麟。
茂苑廊千步，昭阳扇九轮。
阳城迷处笑，京兆画时嚬。
鱼子封牋短，蝇头学字真。
易判期已远，难讳事还新。
艇子愁冲夜，骊驹怕拂晨。
如何断岐路，免得见行尘。','',''),('quantangshi-38431','个人三十韵','吳融','quantangshi','','卷39','袅袅复盈盈，何年坠玉京。
见人还道姓，羞客不称名。
故事谙金谷，新居近石城。
脸横秋水溢，眉拂远山晴。
粉薄涂云母，簪寒篸水晶。
催来两桨送，怕起五丝萦。
髻学盘桓绾，牀依宛转成。
博山凝雾重，油壁隐车轻。
额点梅花样，心通棘刺情。
搔头邀顾遇，约指到平生。
鱼网徐徐襞，螺巵浅浅倾。
芙蓉褥已展，豆蔻水休更。
赵女怜胶腻，丁娘爱烛明。
炷香龙荐脑，辟魇虎输精。
管咽参差韵，弦嘈倰僜声。
花残春寂寂，月落漏丁丁。
柳絮联章敏，椒花属思清。
剪罗成彩字，销蜡脱珠缨。
邂逅当投佩，难难莫拊楹。
熨来身热定，舐得面痕平。
匣镜金螭怒，帘旌绣兽狞。
颈长堪鹤并，腰细任蜂争。
滴泪泉饶竭，论心石未贞。
必双成凤去，岂独化蝉鸣。
书远肠空断，楼高胆易惊。
数钱红带结，鬬草蒨裙盛。
䘧柳阑干小，侵波略彴横。
夜愁遥寄雁，晓梦半和莺。
翼秪思鹣比，根长羡藕并。
可怜衣带缓，休赋重行行。','',''),('quantangshi-38432','即席十韵','吳融','quantangshi','','卷39','住处方窥宋，平生未嫁卢。
暖金轻铸骨，寒玉细凝肤。
妬蜨长成伴，伤鸾耐得孤。
城堪迷下蔡，台合上姑苏。
弄眼难降柳，含茸欲鬬蒲。
生凉云母扇，直夜博山炉。
翡翠交妆镜，鸳鸯入画图。
无心同石转，有泪约泉枯。
猨渴应须见，鹰饥秪待呼。
银河正清浅，霓节过来无。','',''),('quantangshi-38433','追咏棠梨花十韵','吳融','quantangshi','','卷39','蜀地从来胜，棠梨第一花。
更应无软弱，别自有妍华。
不贵绡为雾，难降绮作霞。
移须归紫府，驻合饵丹砂。
密映弹琴宅，深藏卖酒家。
夜宜红蜡照，春称锦筵遮。
连庙魂栖望，飘江字绕巴。
未饶酥点薄，兼妬雪飞斜。
旧赏三年断，新期万里赊。
长安如种得，谁定牡丹夸。','',''),('quantangshi-38434','緜竹山四十韵','吳融','quantangshi','','卷39','緜竹东西隅，千峰势相属。
崚嶒压东巴，连延罗古蜀。
方者露圭角，尖者钻箭簇。
引者蛾眉弯，敛者鸢肩缩。
尾蟉青蛇盘，颈低玄兔伏。
横来突若奔，直上森如束。
岁在作噩年，铜梁摇虿毒。
相国京兆公，九命来作牧。
戎提虎仆毛，专奉狼头纛。
行府寄精庐，开窗对林麓。
是时重阳后，天气旷清肃。
兹山昏晓开，一一在人目。
霜空正泬寥，浓翠霏扑扑。
披海出珊瑚，贴天堆碧玉。
俄然阴霾作，城郭才霢霂。
绝顶已凝雪，晃朗开红旭。
初疑昆仑下，夭矫龙衔烛。
亦似蓬莱巅，金银台叠蹙。
紫霞或旁映，绮段铺繁褥。
晚照忽斜笼，赤城差断续。
又如煮吴盐，万万盆初熟。
又如濯楚练，千千匹未轴。
又如水晶宫，蛟螭结川渎。
又如钟乳洞，电雷开岩谷。
丹青画不成，造化供难足。
合有羽衣人，飘颻曳烟躅。
合有五色禽，叫啸含仙曲。
根虽限劒门，穴必通林屋。
方诸沧海隔，欲去忧沦覆。
羣玉缥缈间，未可量往复。
何如当此境，终朝旷遐瞩。
往往草檄余，吟哦思幽独。
早晚埽欃枪，笳鼓迎畅毂。
休飞霹雳车，罢系虾蟆木。
勒铭燕然山，万代垂芬郁。
然后恣逍遥，独往羣麋鹿。
不管安与危，不问荣与辱。
但乐濠梁鱼，岂怨钟山鹄。
纫兰以围腰，采芝将实腹。
石牀须卧平，一任闲云触。','',''),('quantangshi-38435','祝风三十二韵','吳融','quantangshi','','卷39','我有二顷田，长洲东百里。
环涂为之区，积葑相连纚。
松江流其旁，春夏多苦水。
堤防苟不时，泛滥即无已。
粤余病眠久，而复家无峙。
田峻不胜荒，农功皆废弛。
他稼已如云，我田方欲莳。
四际上通波，兼之葭与苇。
是时立秋后，烟露浩凄矣。
虽然遣毕功，萎约都无几。
如何海上风，连日从空起。
似欲驱沧溟，来沃具区里。
噫嘻尔风师，吴中多豪士。
囷仓过九年，一粒惜如死。
籴贱兼粜贵，凶年翻大喜。
只是疲羸苦，才饥须易子。
余仍轗轲者，进趋年二纪。
秋不安一食，春不闲一晷。
肠回为多别，骨瘦因积毁。
咳唾莫逢人，揶揄空覩鬼。
中又值干戈，遑遑常转徙。
故隐茅山西，今来笠泽涘。
荒者不复寻，葺者还有以。
将正陶令巾，又盖姜肱被。
不敢务有余，有余必骄鄙。
所期免假匄，假匄多惭耻。
骄鄙既不生，惭耻更能弭。
自可致逍遥，无妨阅经史。
吁余将四十，满望秪如此。
干泽尚多难，学稼兹复尔。
穷达虽系命，祸福生所履。
天不饥死余，飘风当自止。','',''),('quantangshi-38436','金陵怀古','吳融','quantangshi','','卷39','玉树声沉战舰收，万家冠盖入中州。
秪应江令偏惆怅，头白归来是客游。','',''),('quantangshi-38437','凉思','吳融','quantangshi','','卷39','松间小槛接波平，月澹烟沉暑气清。
半夜水禽栖不定，绿荷风动露珠倾。','',''),('quantangshi-38438','鲛绡','吳融','quantangshi','','卷39','云供片段月供光，贫女寒机枉自忙。
莫道不蚕能致此，海边何事有扶桑。','',''),('quantangshi-38439','潮','吳融','quantangshi','','卷39','暮去朝来无定期，桑田长被此声移。
蓬莱若探人间事，一日还应两度知。','',''),('quantangshi-38440','忘忧花','吳融','quantangshi','','卷39','繁红落尽始凄凉，直道忘忧也未忘。
数朵殷红似春在，春愁特此系人肠。','',''),('quantangshi-38441','忆街西所居','吳融','quantangshi','','卷39','衡门一别梦难稀，人欲归时不得归。
长忆去年寒食夜，杏花零落雨霏霏。','',''),('quantangshi-38442','云','吳融','quantangshi','','卷39','南北东西似客身，远峰高鸟自为邻。
清歌一曲犹能住，莫道无心胜得人。','',''),('quantangshi-38443','华清宫四首 一','吳融','quantangshi','','卷39','中原无鹿海无波，凤辇鸾旗出幸多。
今日故宫归寂寞，太平功业在山河。','',''),('quantangshi-38444','华清宫四首 二','吳融','quantangshi','','卷39','渔阳烽火照函关，玉辇怱怱下此山。
一曲羽衣听不尽，至今遗恨水潺潺。','',''),('quantangshi-38445','华清宫四首 三','吳融','quantangshi','','卷39','上皇銮辂重巡游，雨泪无言独倚楼。
惆怅眼前多少事，落花明月满宫秋。','',''),('quantangshi-38446','华清宫四首 四','吳融','quantangshi','','卷39','别殿和云鏁翠微，太真遗像梦依依。
玉皇揜泪频惆怅，应叹僧繇彩笔飞。','',''),('quantangshi-38447','陈琳墓','吳融','quantangshi','','卷39','冀州飞檄傲英雄，却把文辞事邺宫。
纵道笔端由我得，九泉何面见袁公。','',''),('quantangshi-38448','湖州朝阳楼','吳融','quantangshi','','卷39','十二亭亭占晓光，隋家浪说有迷藏。
仲宣题尽平生恨，别处应难看屋梁。','',''),('quantangshi-38449','卖花翁','吳融','quantangshi','','卷39','和烟和露一丛花，担入宫城许史家。
惆怅东风无处说，不教闲地着春华。','',''),('quantangshi-38450','自讽','吳融','quantangshi','','卷39','世路升沉合自安，故人何必苦相干。
涂穷始解东归去，莫过严光七里滩。','',''),('quantangshi-38451','送杜鹃花','吳融','quantangshi','','卷39','春红始谢又秋红，息国亡来入楚宫。
应是蜀冤啼不尽，更凭颜色诉西风。','',''),('quantangshi-38452','西京道中闻蛙','吳融','quantangshi','','卷39','雨余林外夕烟沉，忽有蛙声伴客吟。
莫怪闻时倍惆怅，稚圭蓬荜在山阴。','',''),('quantangshi-38453','情','吳融','quantangshi','','卷39','依依脉脉两如何，细以轻丝渺似波。
月不长圆花易落，一生惆怅为伊多。','',''),('quantangshi-38454','送荆南从事之岳州','吳融','quantangshi','','卷39','秋拂湖光一镜开，庾郎兰棹好徘徊。
遥知月落酒醒处，五十弦从波上来。','',''),('quantangshi-38455','渡淮作','吳融','quantangshi','','卷39','红杏花时辞汉苑，黄梅雨里上淮船。
雨迎花送长如此，辜负东风十四年。','',''),('quantangshi-38456','薛舍人见征恩赐香并二十八字同寄','吳融','quantangshi','','卷39','往岁知君侍武皇，今来何用紫罗囊。
都缘有意重熏裛，更洒江毫上玉堂。','',''),('quantangshi-38457','王母庙','吳融','quantangshi','','卷39','鸾龙一夜降昆丘，遗庙千年枕碧流。
赚得武皇心力尽，忍看烟草茂陵秋。','',''),('quantangshi-38458','涂中阻风','吳融','quantangshi','','卷39','洛阳寒食苦多风，扫荡春华一半空。
莫道芳蹊尽成实，野花犹有未开丛。','',''),('quantangshi-38459','楚事','吳融','quantangshi','','卷39','悲秋应亦抵伤春，屈宋当年并楚臣。
何事从来好时节，只将惆怅付词人。','',''),('quantangshi-38460','和僧咏牡丹','吳融','quantangshi','','卷39','万缘销尽本无心，何事看花恨却深。
都是支郎足情调，坠香残蘂亦成吟。','',''),('quantangshi-38461','豫让','吳融','quantangshi','','卷39','韩魏同谋反覆深，晋阳三板免成沉。
赵衰当面何须恨，不把干将访负心。','',''),('quantangshi-38462','和寄座主尚书','吳融','quantangshi','','卷39','偶逢戎旅战争日，岂是明时放逐臣。
不用裁诗苦惆怅，风雷看起卧龙身。','',''),('quantangshi-38463','江行','吳融','quantangshi','','卷39','霞低水远碧翻红，一棹无边落照中。
说示北人应不爱，锦遮泥健马追风。','',''),('quantangshi-38464','旅馆梅花','吳融','quantangshi','','卷39','清香无以敌寒梅，可爱他乡独看来。
