万一有情应有恨，一年荣落两家春。','',''),('quantangshi-38499','海棠二首 一','吳融','quantangshi','','卷39','太尉园林两树春，年年奔走探花人。
今来独倚荆山看，回首长安落战尘。','',''),('quantangshi-38500','海棠二首 二','吳融','quantangshi','','卷39','云绽霞铺锦水头，占春颜色最风流。
若教更近天街种，马上多逢醉五侯。','',''),('quantangshi-38501','送僧上峡归东蜀','吳融','quantangshi','','卷39','巴字江流一棹回，紫袈裟是禁中裁。
如从十二峰前过，莫赋佳人殊未来。','',''),('quantangshi-38502','杏花','吳融','quantangshi','','卷39','春物竞相妬，杏花应最娇。
红轻欲愁杀，粉薄似啼销。
愿作南华蝶，翩翩绕此条。','',''),('quantangshi-38503','草','吳融','quantangshi','','卷39','染亦不可成，画亦不可得。
苌弘未死时，应无此颜色。','',''),('quantangshi-38504','和杨侍郎','吳融','quantangshi','','卷39','目极家山远，身拘禁苑深。
烟霄慙暮齿，麋鹿愧初心。','',''),('quantangshi-38505','山居喜友人相访','吳融','quantangshi','','卷39','秋雨空山夜，非君不此来。
高于剡溪雪，一棹到门回。','',''),('quantangshi-38506','远山','吳融','quantangshi','','卷39','隐隐隔千里，巍巍知几重。
平时未能去，梦断一声钟。','',''),('quantangshi-38507','江树','吳融','quantangshi','','卷39','终日冲奔浪，何年坠乱风。
谢公堪入咏，目极在云中。','',''),('quantangshi-38508','蔷薇','吳融','quantangshi','','卷39','万卉春风度，繁花夏景长。
馆娃人尽醉，西子始新妆。','',''),('quantangshi-38509','梅雨','吳融','quantangshi','','卷39','浑开又密望中迷，乳燕归迟粉竹低。
扑地暗来飞野马，舞风斜去散醯鸡。
初从滴沥妨琴榭，渐到潺湲绕药畦。
少傍海边飘泊处，中庭自有两犁泥。','',''),('quantangshi-38510','登途怀友人','吳融','quantangshi','','卷39','日落野原秀，雨余云物闲。
清时正愁绝，高处正跻攀。
京洛遥天外，江河战鼓间。
孤怀欲谁寄，应望塞鸿还。','',''),('quantangshi-38511','闻蝉','吳融','quantangshi','','卷39','夏在先催过，秋赊已被迎。
自应人不会，莫道物无情。
木叶纵未落，鬓丝还易生。
西风正相乱，休上夕阳城。','',''),('quantangshi-38512','秋色','吳融','quantangshi','','卷39','染不成干画未销，霏霏拂拂又迢迢。
曾从建业城边路，蔓草寒烟鏁六朝。','',''),('quantangshi-38513','自讽','吳融','quantangshi','','卷39','本是沧洲把钓人，无端三署接清尘。
从来不解长流涕，也渡湘漓作逐臣。','',''),('quantangshi-38514','宿青云驿','吳融','quantangshi','','卷39','苍黄负谴走商颜，保得微躬出武关。
今夜青云驿前月，伴吟应到落西山。','',''),('quantangshi-38515','秋闻子规','吳融','quantangshi','','卷39','年年春恨化冤魂，血染枝红压叠繁。
正是西风花落尽，不知何处认啼痕。','',''),('quantangshi-38516','荆南席上闻歌','吳融','quantangshi','','卷39','迎愁歛黛一声分，吊屈江边日暮闻。
何事遏云翻不定，自缘踪迹爱行云。','',''),('quantangshi-38517','武关','吳融','quantangshi','','卷39','时来时去若循环，双阖平云谩鏁山。
祗道地教秦设险，不知天与汉为关。
贪生莫作千年计，到了都成一梦闲。
争得便如岩下水，从他兴废自潺潺。','',''),('quantangshi-38518','月夕追事','吳融','quantangshi','','卷39','曾听豪家碧玉歌，云牀冰簟落秋河。
月临高阁帘无影，风过回廊幕有波。
屈指尽随云雨散，满头赢得雪霜多。
此时空见清凉影，来伴蛩声咽砌莎。','',''),('quantangshi-38519','上阳宫辞','吳融','quantangshi','','卷39','苑路青青半是苔，翠华西去未知回。
景阳春漏无人报，太液秋波有雁来。
单影可堪明月照，红颜无奈落花催。
谁能赋得长门事，不惜千金奉酒杯。','',''),('quantangshi-38520','送于员外归隐蓝田','吳融','quantangshi','','卷39','曾吟工部两峰寒，今日星郎得挂冠。
吾道不行归始是，世情如此住应难。
围棋已访生云石，把钓先寻急雨滩。
若遇秦时雪髯客，紫芝兼可备朝餐。','',''),('quantangshi-38521','废宅','吳融','quantangshi','','卷39','风飘碧瓦雨摧垣，却有隣人与鏁门。
几树好花闲白昼，满庭荒草易黄昏。
放鱼池涸蛙争聚，栖燕梁空雀自喧。
不独凄凉眼前事，咸阳一火便成原。','',''),('quantangshi-38522','湖州晚望','吳融','quantangshi','','卷39','鼓角迎秋晚韵长，断虹疎雨间微阳。
两条溪水分头碧，四面人家入骨凉。
独鸟归时云鬬迥，残蝉急处日争忙。
他年若得壶中术，一簇汀洲尽贮将。','',''),('quantangshi-38523','宋玉宅','吳融','quantangshi','','卷39','草白烟寒半野陂，临江旧宅指遗基。
已怀湘浦招魂事，更忆高唐说梦时。
穿径早曾闻客住，登墙岂复见人窥。
今朝送别还经此，吟断当年几许悲。','',''),('quantangshi-38524','春晚书怀','吳融','quantangshi','','卷39','落尽红芳春意阑，绿芜空鏁辟疆园。
嫦娥断影霜轮冷，帝子无踪泪竹繁。
未达东邻还绝想，不劳南浦更销魂。
晚来虽共残莺约，争奈风凄又雨昏。','',''),('quantangshi-38525','寄杨侍郎','吳融','quantangshi','','卷39','云情鹤态莫夸慵，正上仙楼十二重。
吟逸易沈鳷鹊月，梦长先断景阳钟。
奇文已刻金书券，秘语看镌玉检封。
何事春来待归隐，探知溪畔有风松。','',''),('quantangshi-38526','杏花','吳融','quantangshi','','卷39','粉薄红轻揜歛羞，花中占断得风流。
软非因醉都无力，凝不成歌亦自愁。
独照影时临水畔，最含情处出墙头。
裴回尽日难成别，更待黄昏对酒楼。','',''),('quantangshi-38527','宪丞裴公上洛退居有寄二首 一','吳融','quantangshi','','卷39','鸿在冥冥已自由，紫芝峰下更高秋。
抛来簪绂都如梦，泥着杯香不为愁。
晚树拂檐风脱翠，夜滩当户月和流。
自嗟不得从公去，共上仙家十二楼。','',''),('quantangshi-38528','宪丞裴公上洛退居有寄二首 二','吳融','quantangshi','','卷39','瘦如仙鹤爽风篁，外却尘嚣兴绪长。
偶坐几回沈皓月，闲吟是处到残阳。
门前立使修书嬾，花下留宾压酒忙。
目断琼林攀不得，一重丹水抵三湘。','',''),('quantangshi-38529','丛祠','吳融','quantangshi','','卷39','丛祠一炬照秦川，雨散云飞二十年。
长路未归萍逐水，旧居难问草平烟。
金鞍正伴桐乡客，粉壁犹怀桂苑仙。
何必向来曾识面，拂尘看字也凄然。','',''),('quantangshi-38530','分水岭','吳融','quantangshi','','卷39','两派潺湲不暂停，岭头长泻别离情。
南随去马通巴栈，北逐归人达渭城。
澄处好窥双黛影，咽时堪寄断肠声。
紫溪旧隐还如此，清夜梁山月更明。','',''),('quantangshi-38531','赴职西川过便桥书怀寄同年','吳融','quantangshi','','卷39','平门桥下水东驰，万里从军一望时。
乡思旋生芳草见，客愁何限夕阳知。
秦陵无树烟犹鏁，汉苑空墙浪欲吹。
不是伤春爱回首，杏坛恩重马迟迟。','',''),('quantangshi-38532','太保中书令军前新楼','吳融','quantangshi','','卷39','十二阑干压锦城，半空人语落滩声。
风流近接平津阁，气色高含细柳营。
尽日卷帘江草绿，有时欹枕雪峰晴。
不知捧诏朝天后，谁此登临看月明。','',''),('quantangshi-38533','玉女庙','吳融','quantangshi','','卷39','九清何日降仙霓，掩暎荒祠路欲迷。
愁黛不开山浅浅，离心长在草萋萋。
檐横渌派王余掷，窗褭红枝杜宇啼。
若得洗头盆置此，靓妆无复碧莲西。','',''),('quantangshi-38534','坤维军前寄江南弟兄','吳融','quantangshi','','卷39','二年征战劒山秋，家在松江白浪头。
关月几时干客泪，戍烟终日起乡愁。
未知辽堞何当下，转觉燕台不易酬。
独羡一声南去雁，满天风雨到汀洲。','',''),('quantangshi-38535','浐水席上献座主侍郎','吳融','quantangshi','','卷39','暖泉宫里告虔回，略避红尘小宴开。
落絮已随流水去，啼莺还傍夕阳来。
草能缘岸侵罗荐，花不容枝蘸玉杯。
莫讶诸生中独醉，感恩伤别正难裁。','',''),('quantangshi-38536','送知古上人','吳融','quantangshi','','卷39','昔年离别浙河东，多难相逢旧楚宫。
振锡才寻三径草，登船忽挂一帆风。
几程村饭添盂白，何处山花照衲红？
不似投荒憔悴客，沧浪无际问渔翁。','',''),('quantangshi-38537','和座主尚书登布善寺楼','吳融','quantangshi','','卷39','往事何时不系肠，更堪凝睇白云乡。
楚王城垒空秋色，羊祜江山祗暝光。
林下远分南去马，渡头偏认北归航。
谁知此日凭轩处，一笔工夫胜七襄。','',''),('quantangshi-38538','金桥感事','吳融','quantangshi','','卷39','太行和雪叠晴空，二月春郊尚朔风。
饮马早闻临渭北，射雕今欲过山东。
百年徒有伊川叹，五利宁无魏绛功。
日暮长亭正愁绝，哀笳一曲戍烟中。','',''),('quantangshi-38539','萧县道中','吳融','quantangshi','','卷39','戍火三笼滞晚程，枯桑系马上寒城。
满川落照无人过，卷地飞蓬有烧明。
楚客早闻歌凤德，刘琨休更舞鸡声。
草堂旧隐终归去，寄语岩猨莫晓惊。','',''),('quantangshi-38540','题兖州泗河中石牀','吳融','quantangshi','','卷39','一片苔牀水漱痕，何人清赏动干坤。
谪仙醉后云为态，野客吟时月作魂。
光景不回波自远，风流难问石无[言]。
迩来多少登临客，千载谁将胜事论。','',''),('quantangshi-38541','禁直偶书','吳融','quantangshi','','卷39','玉皇新复五城居，仙馆词臣在碧虚。
锦砌渐看翻芍药，鏁窗还咏隔蟾蜍。
敢期林上灵乌语，贪草云间彩凤书。
争奈沧洲频入梦，白波无际落红蕖。','',''),('quantangshi-38542','送弟东归','吳融','quantangshi','','卷39','偶持麟笔侍金闺，梦想三年在故溪。
祖竹定欺檐雪折，穉杉应拂栋云齐。
谩劳筋力趋丹凤，可有文词咏碧鸡。
此别更无闲事嘱，北山高处谢猨啼。','',''),('quantangshi-38543','和座主尚书春日郊居','吳融','quantangshi','','卷39','海燕初归朔雁回，静眠深揜百花台。
春蔬已为高僧掇，腊酝还因熟客开。
檐外暖丝兼絮堕，槛前轻浪带鸥来。
谢公难避苍生意，自古风流必上台。','',''),('quantangshi-38544','僧舍白牡丹二首 一','吳融','quantangshi','','卷39','腻若裁云薄缀霜，春残独自殿羣芳。
梅妆向日霏霏暖，纨扇摇风闪闪光。
月魄照来空见影，露华凝后更多香。
天生洁白宜清净，何必殷红暎洞房。','',''),('quantangshi-38545','僧舍白牡丹二首 二','吳融','quantangshi','','卷39','侯家万朵簇霞丹，若并霜林素艳难。
合影只应天际月，分香多是畹中兰。
虽饶百卉争先发，还在三春向后残。
想得惠林凭此槛，肯将荣落意来看。','',''),('quantangshi-38546','八月十五夜禁直寄同僚','吳融','quantangshi','','卷39','中秋月满尽相寻，独入非烟宿禁林。
曾恨人间千里隔，更堪天上九门深。
明涵太液鱼龙定，静鏁圆灵象纬沈。
目断枚臯何处在，阑干十二忆登临。','',''),('quantangshi-38547','上巳日花下闲看','吳融','quantangshi','','卷39','十里香尘扑马飞，碧莲峰下踏青时。
云鬟照水和花重，罗袖抬风惹絮迟。
可便无心邀娬媚，还应有泪忆袁熙。
如烟如梦争寻得，溪柳回头万万丝。','',''),('quantangshi-38548','禅院弈棋偶题','吳融','quantangshi','','卷39','裛尘丝雨送微凉，偶出樊笼入道场。
半偈已能消万事，一枰兼得了残阳。
寻知世界都如梦，自喜身心甚不忙。
更约西风摇落后，醉来终日卧禅房。','',''),('quantangshi-38549','和张舍人','吳融','quantangshi','','卷39','玉女盆边雪未销，正多春事莫无憀。
杏花向日红匀脸，云带环山白系腰。
莺啭树头欹枕听，冻开泉眼杖藜挑。
陵迁谷变如须问，控鹤山人字子乔。','',''),('quantangshi-38550','送友赴阙','吳融','quantangshi','','卷39','故人归去指翔鸾，乐带离声可有欢。
驿路两行秋吹急，渭波千叠夕阳寒。
空郊已叹周禾熟，旧苑应寻汉火残。
遥羡从公无一事，探花先醉曲江干。','',''),('quantangshi-38551','过邓城县作','吳融','quantangshi','','卷39','不用登临足感伤，古来今往尽茫茫。
未知尧桀谁臧否，可便彭殇有短长。
楚垒万重多故事，汉波千叠更残阳。
到头一切皆身外，只觉关身是醉乡。','',''),('quantangshi-38552','文德初闻车驾东游','吳融','quantangshi','','卷39','龙斾丛丛下劒门，还将瑞气入中原。
鳌头一荡山虽没，乌足重安日不昏。
晋客已知周礼在，秦人仍喜汉官存。
自怜闲坐渔矶石，万级云台落梦魂。','',''),('quantangshi-38553','子规','吳融','quantangshi','','卷39','举国繁华委逝川，羽毛飘荡一年年。
他山叫处花成血，旧苑春来草似烟。
雨暗不离浓绿树，月斜长吊欲明天。
湘江日暮声凄切，愁杀行人归去船。','',''),('quantangshi-38554','简州归降贺京兆公','吳融','quantangshi','','卷39','分栋山前曙色开，三千铁骑简州回。
云间堕箭飞书去，风里擎竿露布来。
古谓伐谋为上策，今看静胜自中台。
功名一似淮西事，只是元臣不姓裴。','',''),('quantangshi-38555','登汉州城楼','吳融','quantangshi','','卷39','雨余秋色拂孤城，远目凝时万象清。
叠翠北来千嶂尽，漫流东去一江平。
从军固有荆州乐，怀古能无岘首情。
欲下阑干一回首，乌归帆没戍烟明。','',''),('quantangshi-38556','岐下寓居见槐花落因寄从事','吳融','quantangshi','','卷39','才开便落不胜黄，覆着庭莎衬夕阳。
只共蝉催双鬓老，可知人已十年忙。
晓窗须为吟秋兴，夜枕应教梦帝乡。
蜀国马卿看从猎，肯将闲事入凄凉。','',''),('quantangshi-38557','和人有感','吳融','quantangshi','','卷39','莫愁家住石城西，月坠星沈客到迷。
一院无人春寂寂，九原何处草萋萋。
香魂未散烟笼水，舞袖休翻柳拂堤。
兰棹一移风雨急，流莺千万莫长啼。','',''),('quantangshi-38558','春归次金陵','吳融','quantangshi','','卷39','春阴漠漠覆江城，南国归桡趂晚程。
水上驿流初过雨，树笼堤处不离莺。
迹疎冠盖兼无梦，地近乡园自有情。
便被东风动离思，杨花千里雪中行。','',''),('quantangshi-38559','途中见杏花','吳融','quantangshi','','卷39','一枝红艳出墙头，墙外行人正独愁。
长得看来犹有恨，可堪逢处更难留。
林空色暝莺先到，春浅香寒蝶未游。
更忆帝乡千万树，澹烟笼日暗神州。','',''),('quantangshi-38560','秋日经别墅','吳融','quantangshi','','卷39','别墅萧条海上村，偶期兰菊与琴尊。
檐横碧嶂秋光近，树带闲潮晚色昏。
幸有白云眠楚客，不劳芳草思王孙。
北山移去前文在，无复教人叹晓猨。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-38561','红叶','吳融','quantangshi','','卷39','露染霜干片片轻，斜阳照处转烘明。
和烟飘落九秋色，随浪泛将千里情。
几夜月中藏鸟影，谁家庭际伴蛩声。
一时衰飒无多恨，看着清风彩剪成。','',''),('quantangshi-38562','离霅溪感事献郑员外','吳融','quantangshi','','卷39','足恨饶悲不自由，萍无根蒂水长流。
庾公明月吟连曙，谢守青山看入秋。
一饭意专堪便死，千金诺在转难酬。
云沈鸟去回头否，平子才多好赋愁。','',''),('quantangshi-38563','岐州安西门','吳融','quantangshi','','卷39','安西门外彻安西，一百年前断鼓鼙。
犬解人歌曾入唱，马称龙子几来嘶。
自从辽水烟尘起，更到涂山道路迷。
今日登临须下泪，行人无个草萋萋。','',''),('quantangshi-38564','关西驿亭即事','吳融','quantangshi','','卷39','晚霞零落雨初收，关上危阑独怅留。
千里好春聊极目，五陵无事莫回头。
山犹带雪霏霏恨，柳未禁寒冉冉愁。
直是无情也肠断，鸟归帆没水空流。','',''),('quantangshi-38565','望嵩山','吳融','quantangshi','','卷39','三十六峰危似冠，晴楼百尺独登看。
高凌鸟外青冥窄，翠落人间白昼寒。
不觉衡阳遮雁过，如何钟阜鬬龙盘。
始知万岁声长在，只待东巡动玉鸾。','',''),('quantangshi-38566','题湖城县西道中槐树','吳融','quantangshi','','卷39','零落攲斜此路中，盛时曾识太平风。
晓迷天仗归春苑，暮送鸾旗指洛宫。
一自烟尘生蓟北，更无消息幸关东。
而今只有孤根在，鸟啄虫穿没乱蓬。','',''),('quantangshi-38567','东归次瀛上','吳融','quantangshi','','卷39','暖烟轻淡草霏霏，一片晴山衬夕晖。
水露浅沙无客泛，树连疎苑有莺飞。
自从身与沧浪别，长被春教寂寞归。
回首青门不知处，向人杨柳莫依依。','',''),('quantangshi-38568','偶书','吳融','quantangshi','','卷39','青牛关畔寄孤村，山当屏风石当门。
芳树绿阴连蔽芾，长河飞浪接昆仑。
苔田绿后蛙争聚，麦壠黄时雀更喧。
只此无心便无事，避人何必武陵源。','',''),('quantangshi-38569','得京中亲友书讶久无音耗以诗代谢','吳融','quantangshi','','卷39','退闲何事不忘机，况限溪云静掩扉。
马颊浪高鱼去少，鸡鸣关险雁来稀。
无才敢更期连茹，有意兼思学采薇。
珍重故人知我者，九霄休复寄音徽。','',''),('quantangshi-38570','即事','吳融','quantangshi','','卷39','抵鹊山前云掩扉，更甘终老脱朝衣。
晓窥青镜千峰入，暮倚长松独鹤归。
云里引来泉脉细，雨中移得药苗肥。
何须一筯鲈鱼脍，始挂孤帆问钓矶。','',''),('quantangshi-38571','病中宜茯苓寄李谏议','吳融','quantangshi','','卷39','千年茯菟带龙鳞，太华峰头得最珍。
金鼎晓煎云漾粉，玉瓯寒贮露含津。
南宫已借征诗客，内署今还托谏臣。
飞檄愈风知妙手，也须分药救漳滨。','',''),('quantangshi-38572','槎','吳融','quantangshi','','卷39','浪痕龙迹老敧危，流落何时别故枝。
岁月空教苔藓积，芳菲长倩薜萝知。
有文在朽人难识，无蠹藏心鸟莫窥。
家近沧浪从泛去，碧天消息不参差。','',''),('quantangshi-38573','汴上观','吳融','quantangshi','','卷39','九曲河冰半段来，严霜结出劲风裁。
非时已认蝉飘翼，到海须忧蚌失胎。
千里风清闻戛玉，几人东下忆奔雷。
殷勤莫碍星槎路，从看天津弄杼回。','',''),('quantangshi-38574','闲居有作','吳融','quantangshi','','卷39','依依芳树拂檐平，绕竹清流浸骨清。
爱弄绿苔鱼自跃，惯偷红果鸟无声。
踏青堤上烟多绿，拾翠江边月更明。
只此超然长往是，几人能遂铸金成。','',''),('quantangshi-38575','离岐下题西湖','吳融','quantangshi','','卷39','送夏迎秋几醉来，不堪行色被蝉催。
身随渭水看归远，梦挂秦云约自回。
雨细若为抛钓艇，月明谁复上歌台。
千波万浪西风急，更为红蕖把一杯。','',''),('quantangshi-38576','岐阳蒙相国对宅因抒怀投献','吳融','quantangshi','','卷39','风有危亭月有台，平津阁畔好裴回。
虽非宋玉诛茅至，且学王家种竹来。
已得静居从马歇，不堪行色被蝉催。
故园兰菊三千里，旅梦方应校嬾回。','',''),('quantangshi-38577','晚泊松江','吳融','quantangshi','','卷39','落日停桡古渡边，古今踪迹一苍然。
平沙尽处云藏树，远吹收来水定天。
正困东西千里路，可怜潇洒五湖船。
如何不及前贤事，却谢鲈鱼在洛川。','',''),('quantangshi-38578','过渑池书事','吳融','quantangshi','','卷39','渑池城郭半遗基，无限春愁挂落晖。
柳渡风轻花浪绿，麦田烟暖锦鸡飞。
相如忠烈千秋断，二主英雄一梦归。
莫道新亭人对泣，异乡殊代也霑衣。','',''),('quantangshi-38579','富春','吳融','quantangshi','','卷39','水送山迎入富春，一川如画晚晴新。
云低远渡帆来重，潮落寒沙鸟下频。
未必柳间无谢客，也应花里有秦人。
严光万古清风在，不敢停桡更问津。','',''),('quantangshi-38580','高侍御话及皮博士池中白莲因成一章寄博士兼奉呈','吳融','quantangshi','','卷39','白玉花开绿锦池，风流御史报人知。
看来应是云中堕，偷去须从月下移。
已被乱蝉催晼晚，更禁凉雨动䙰褷。
习家秋色堪图画，只欠山公倒接䍦。','',''),('quantangshi-38581','忆猿','吳融','quantangshi','','卷39','翠微云歛日沈空，叫彻青冥怨不穷。
连臂影垂溪色里，断肠声尽月明中。
静含烟峡凄凄雨，高弄霜天袅袅风。
犹有北山归意在，少惊佳树近房栊。','',''),('quantangshi-38582','红树','吳融','quantangshi','','卷39','一声南雁已先红，神女霜飞叶叶同。
自是孤根非暖地，莫惊他木耐秋风。
暖烟散去阴全薄，明月临来影半空。
长忆洞庭千万树，照山横浦夕阳中。','',''),('quantangshi-38583','新雁','吳融','quantangshi','','卷39','湘浦波春始北归，玉关摇落又南飞。
数声飘去和秋色，一字横来背晚晖。
紫阁高翻云羃羃，灞川低渡雨微微。
莫从思妇台边过，未得征人万里衣。','',''),('quantangshi-38584','海上秋怀','吳融','quantangshi','','卷39','辞无圭组隐无才，门向潮头过处开。
几度黄昏逢罔象，有时红旭见蓬莱。
碛连荒戍频频火，天绝纤云往往雷。
昨夜秋风已摇落，那堪更上望乡台。','',''),('quantangshi-38585','忆山泉','吳融','quantangshi','','卷39','穿云落石细湔湔，尽日疑闻弄管弦。
千仞洒来寒碎玉，一泓深去碧涵天。
烟迷叶乱寻难见，月好风清听不眠。
春雨正多归未得，只应流恨更潺湲。','',''),('quantangshi-38586','东归望华山','吳融','quantangshi','','卷39','碧莲重叠在青冥，落日垂鞭缓客程。
不奈春烟笼暗澹，可堪秋雨洗分明。
南边已放三千马，北面犹标百二城。
只怕仙人抚高掌，年年相见是空行。','',''),('quantangshi-38587','游华州飞泉亭','吳融','quantangshi','','卷39','走马街南百亩池，碧莲花影倒参差。
偶同人去红尘外，正值僧归落照时。
万事已为春弃置，百忧须赖酒医治。
殷勤待取前峰月，更倚阑干弄钓丝。','',''),('quantangshi-38588','池上双凫二首 一','吳融','quantangshi','','卷39','碧池悠漾小凫雏，两两依依秪自娱。
钓艇忽移还散去，寒鸱有意即相呼。
可怜翡翠归云髻，莫羡鸳鸯入画图。
幸是羽毛无取处，一生安稳老菰蒲。','',''),('quantangshi-38589','池上双凫二首 二','吳融','quantangshi','','卷39','双凫狎得傍池台，戏藻衔蒲远又回。
敢为稻粱凌险去，幸无鹰隼触波来。
万丝春雨眠时乱，一片浓萍浴处开。
不在笼栏夜仍好，月汀星沼剩裴回。','',''),('quantangshi-38590','叶落','吳融','quantangshi','','卷39','红影飘来翠影微，一辞林表不知归。
伴愁无色烟犹在，替恨成啼露未曦。
若逐水流应万里，莫因风起便孤飞。
楚郊千树秋声急，日暮纷纷惹客衣。','',''),('quantangshi-38591','和皮博士赴上京观中修灵斋赠威仪尊师兼见寄','吳融','quantangshi','','卷39','霓结双旌羽缀裙，七星坛上拜元君。
精诚有为天应感，章奏无私鬼怕闻。
鹤驭已从烟际下，凤膏还向月中焚。
白云乡路看看到，好驻流年翊圣文。','',''),('quantangshi-38592','春雨','吳融','quantangshi','','卷39','霏霏漠漠暗和春，羃翠凝红色更新。
寒入腻裘浓晓睡，细随油壁静香尘。
连云似织休迷雁，带柳如啼好赠人。
别有空堦寂寥事，绿苔狼籍落花频。','',''),('quantangshi-38593','秋池','吳融','quantangshi','','卷39','冷涵秋水碧溶溶，一片澄明见底空。
有日晴来云衬白，几时吹落叶浮红。
香啼蓼穗娟娟露，干动莲茎淅淅风。
凌晓无端照衰发，便悲霜雪镜光中。','',''),('quantangshi-38594','首阳山','吳融','quantangshi','','卷39','首阳山枕黄河水，上有两人曾饿死。
不同天下人为非，兄弟相看自为是。
遂令万古识君心，为臣贵义不贵身。
精灵长在白云里，应笑随时饱死人。','',''),('quantangshi-38595','太湖石歌','吳融','quantangshi','','卷39','洞庭山下湖波碧，波中万古生幽石。
铁索千寻取得来，奇形怪状谁能识。
初疑朝家正人立，又如战士方狙击。
又如防风死后骨，又如于菟活时额。
又如成人枫，又如害瘿柏。
雨过上停泓，风来中有隙。
想得沈潜水府时，兴云出雨蟠蛟螭。
今来硉矹林庭上，长恐忽然生白浪。
用时应不称娲皇，将去也堪随博望。
噫嘻尔石好凭依，幸有方池并钓矶。
小山丛桂且为伴，钟阜白云长自归。
何必豪家甲第里，玉阑干畔争光辉。
一朝荆棘忽流落，何异绮罗云雨飞。','',''),('quantangshi-38596','赠方干处士歌','吳融','quantangshi','','卷39','把笔尽为诗，何人敌夫子。
句满天下口，名聒天下耳。
不识朝，不识市。
旷逍遥，闲徙倚。
一杯酒，无万事。
一叶舟，无千里。
衣裳白云，坐卧流水。
霜落风高忽相忆，惠然见过留一夕。
一夕听吟十数篇，水榭林萝为岑寂。
拂旦舍我亦不辞，携筇径去随所适。
随所适，无处觅。
云半片，鹤一只。','',''),('quantangshi-38597','李周弹筝歌','吳融','quantangshi','','卷39','古人云：丝不如竹，竹不如肉。
乃知此语未必然，李周弹筝听不足。
闻君七岁八岁时，五音六律皆生知。
就中十三弦最妙，应宫出入年方少。
青騘惯走长楸日，几度承恩蒙急召。
一字雁行斜御筵，锵金戛羽凌非烟。
始似五更残月里，凄凄切切清露蝉。
又如石罅堆叶下，泠泠沥沥苍崖泉。
鸿门玉斗初向地，织女金梭飞上天。
有时上苑繁花发，有时太液秋波阔。
当头独坐摐一声，满座好风生拂拂。
天颜开，圣心悦。
紫金白珠霑赐物，出来无暇更还家。
且上青楼醉明月，年将六十艺转精。
自写梨园新曲声，近来一事还惆怅。
故里春荒烟草平，供奉供奉且听语。
自昔兴衰看乐府，秪如伊州与梁州。
尽是太平时歌舞，旦夕君王继此声，不要停弦泪如雨。','',''),('quantangshi-38598','赠{巩/言}光上人草书歌','吳融','quantangshi','','卷39','篆书朴，隶书俗，草圣贵在无羁束。
江南有僧名{巩/言}光，紫毫一管能顚狂。
人家好壁试挥拂，瞬目已流三五行。
摘如钩，挑如拨。
斜如掌，回如斡。
又如夏禹鏁淮神，波底出来手正拔。
又如朱亥锤晋鄙，袖中抬起腕欲脱。
有时软萦盈，一穗秋云曳空阔。
有时瘦巉岩，百尺枯松露槎枿。
忽然飞动更惊人，一声霹雳龙虵活。
稽山贺老昔所传，又闻能者惟张顚。
上人致功应不下，其奈飘飘沧海边。
可中一入天子国，络素裁缣洒毫墨。
不系知之与不知，须言一字千金值。','',''),('quantangshi-38599','赠李长史歌','吳融','quantangshi','','卷39','危栏压溪溪澹碧，翠褭红飘莺寂寂。
此日长亭怆别离，座中忽遇吹芦客。
双攘轻袖当高轩，含商吐羽凌非烟。
初疑一百尺瀑布，八九月落香炉巅。
又似鲛人为客罢，迸泪成珠玉盘泻。
碧珊瑚碎震泽中，金锒铛撼龟山下。
铿訇揭调初惊人，幽咽细声还感神。
紫凤将雏叫山月，玄兔丧子啼江春。
咨嗟长史出人艺，如何值此艰难际。
可中长似承平基，肯将此为闲人吹。
不是东城射雉处，即应南苑鬬鸡时。
白樱桃熟每先赏，红芍药开长有诗。
卖珠曾被武皇问，薰香不怕贾公知。
今来流落一何苦，江南江北九寒暑。
翠华犹在橐泉中，一曲梁州泪如雨。
长史长史听我语，从来艺绝多失所。
罗君赠君两首诗，半是悲君半自悲。','',''),('quantangshi-38600','赠广利大师歌','吳融','quantangshi','','卷39','化人之心固甚难，自化之心更不易。
化人可以程限之，自化元须有其志。
在心为志者何人，今日得之于广利。
三十年前识师初，正见把笔学草书。
崩云落日千万状，随手变化生空虚。
海北天南几回别，每见书踪转奇绝。
近来兼解作歌诗，言语明快有气骨。
坚如百炼钢，挺特不可屈。
又如千里马，脱缰飞灭没。
好是不雕刻，纵横冲口发。
昨来示我十余篇，咏杀江南风与月。
乃知性是天，习是人。
莫轻河边羖䍽，飞作天上麒麟。
但日新，又日新。
李太白，非通神。','',''),('quantangshi-38601','古离别','吳融','quantangshi','','卷39','紫鸾黄鹄虽别离，一举千里何难追。
犹闻啼风与叫月，流连断续令人悲。
赋情更有深缱绻，碧甃千寻尚为浅。
蟾蜍正向清夜流，蛱蝶须教堕丝罥。
莫道断丝不可续，丹穴凤凰胶不远。
莫道流水不回波，海上两潮长自返。','',''),('quantangshi-38602','风雨吟','吳融','quantangshi','','卷39','风骚骚，雨涔涔，长洲苑外荒居深。
门外流水流澶漫，河边古木鸣萧森。
敻无禽影，寂无人音。
端然拖愁坐，万感丛于心。
姑苏碧瓦十万户，中有楼台与歌舞。
寻常倚月复眠花，莫说斜风兼细雨。
应不知天地造化是何物，亦不知荣辱是何主。
吾囷长满是太平，吾乐不极是天生。
岂忧天下有大憝，四郊刁斗常铮铮。
官军扰人甚于贼，将臣怕死唯守城。
又岂复忧朝廷苦弛慢，中官转纵横。
李膺勾党即罹患，窦武忠谋又未行。
又岂忧文臣尽遭束高阁，文教从今日萧索。
若更无人稍近前，把笔到头同一恶。
可叹吴城城中人，无人与我交一言。
蓬蒿满径尘一榻，独此闵闵何其烦。
虽然小或可谋大，[嫠]妇之忧史尚存。
况我长怀丈夫志，今来流落沧溟涘。
有时惊事再咨嗟，因风因雨更憔悴。
只有闲横膝上琴，怨伤怨恨聊相寄。
伯牙海上感沧溟，何似今朝风雨思。','',''),('quantangshi-38603','江行','吳融','quantangshi','','卷39','来时风，去时雨，萧萧飒飒春江浦。
欹欹侧侧海门帆，轧轧哑哑洞庭橹。','',''),('quantangshi-38604','壁画折竹杂言','吳融','quantangshi','','卷39','枯缠藤，重欹雪，渭曲逢，湘江别。
不是从来无本根，画工取势教摧折。','',''),('quantangshi-38605','古锦裾六韵','吳融','quantangshi','','卷39','濯水经何日，随风故有人。
绿衣犹逼画，丹顶尚迷真。
暗澹云沈古，青苍藓剥新。
暎襟知惹泪，侵鞯想萦尘。
掣曳无由睹，流传久自珍。
武威应认得，牵挽几当春。','',''),('quantangshi-38606','赋得欲晓看妆面','吳融','quantangshi','','卷39','胧胧欲曙色，隐隐辨残妆。
月始云中出，花犹雾里藏。
眉边全失翠，额畔半留黄。
转入金屏影，隈侵角枕光。
有蝉隳鬓样，无燕着𨥁行。
十二峯前梦，如何不断肠。','',''),('quantangshi-38607','府试雨夜帝里闻猿声','吳融','quantangshi','','卷39','雨滴秦中夜，猿闻峡外声。
已吟何逊恨，还赋屈平情。
暗逐哀鸿泪，遥含禁漏清。
直疑游万里，不觉在重城。
霎霎侵灯乱，啾啾入梦惊。
明朝临晓镜，别有鬓丝生。','',''),('quantangshi-38608','题画柏','吳融','quantangshi','','卷39','不得月中桂，转思陵上柏。
闲取画图看，烦纡果冰释。
桂生在青冥，万古烟雾隔。
下荫玄兔窟，上暎嫦娥魄。
圆缺且不常，高低图难测。
若非假羽翰，折攀何由得。
天远眼虚穿，夜阑头自白。
未知陵上柏，一定不移易。
有意兼松茂，无情从麝食。
不在是非间，与人为愤激。
他年上缣素，今日悬屋壁。
灵怪不可知，风雨疑来逼。
明朝归故园，唯此同所适。
回首寄团枝，无劳惠消息。','',''),('quantangshi-38609','平望蚊子二十六韵','吳融','quantangshi','','卷39','天下有蚊子，候夜噆人肤。
平望有蚊子，白昼来相屠。
不避风与雨，羣飞出菰蒲。
扰扰蔽天黑，雷然随舳舻。
利嘴入人肉，微形红且濡。
振蓬亦不惧，至死贪膏腴。
舟人敢停棹，陆者亦疾趋。
南北百余里，畏之如虎貙。
噫嘻天地间，万物各有殊。
阳者阳为伍，阴者阴为徒。
蚊蚋是阴物，夜从喧墙隅。
如何正曦赫，吞噬当通衢。
人筋为尔断，人力为尔枯。
衣巾秽且甚，盘馔腥有余。
岂是阳德衰，不能使消除。
岂是有主者，此乡宜毒荼。
吾闻蛇能螫，避之则无虞。
吾闻虿有毒，见之可疾驱。
唯是此蚊子，逢人皆病诸。
江南夏景好，水木多萧疎。
此中震泽路，风月弥清虚。
前后几来往，襟怀曾未舒。
朝既蒙襞积，夜仍跧蘧蒢。
虽然好吟啸，其奈难踟蹰。
人生有不便，天意当何如。
谁能假羽翼，直上言红炉。','',''),('quantangshi-38610','桃花','吳融','quantangshi','','卷39','满树和娇烂漫红，万枝丹彩灼春融。
何当结作千年实，将示人间造化工。','',''),('quantangshi-38611','木笔花','吳融','quantangshi','','卷39','嫩如新竹管初齐，粉腻红轻样可携。
谁与诗人偎槛看，好于牋墨并分题。','',''),('quantangshi-38612','淛东筵上有寄','吳融','quantangshi','','卷39','襄王席上一神仙，眼色相当语不传。
见了又休真似梦，坐来虽近远于天。
陇禽有意犹能说，江月无心也解圆。
更被东风劝惆怅，落花时节定翩翩。','',''),('quantangshi-38613','富水驿东楹有人题诗','吳融','quantangshi','','卷39','绣缨霞翼两鸳鸯，金岛银川是故乡。
只合双飞便双死，岂悲相失与相忘。
烟花夜泊红蕖腻，兰渚春游碧草芳。
何事遽惊云雨别，秦山楚水两乖张。','',''),('quantangshi-38614','上巳日','吳融','quantangshi','','卷39','本学多情刘武威，寻花傍水看春晖。
无端遇着伤心事，赢得凄凉索漠归。','',''),('quantangshi-38615','隋堤','吳融','quantangshi','','卷39','搔首隋堤落日斜，已无余柳可藏鸦。
岸傍昔道牵龙舰，河底今来走犊车。
曾笑陈家歌玉树，却随后主看琼花。
四方正是无虞日，谁信黎阳有古家。','',''),('quantangshi-38616','寄杜先生诗','孫偓','quantangshi','','卷39','蜀国信难遇，楚乡心更愁。
我行同范蠡，师举效浮丘。
他日相逢处，多应在十洲。','',''),('quantangshi-38617','赠南岳僧全玭','孫偓','quantangshi','','卷39','窠居过后更何人，传得如来法印真。
昨日祝融峰下见，草衣便是雪山□。','',''),('quantangshi-38618','答门生王涣李德邻赵光胤王拯长句','孫偓','quantangshi','','卷39','谬持文柄得时贤，粉署清华次第迁。
昔岁策名皆健笔，今朝称职并同年。
各怀器业宁推让，俱上青霄肯后先。
何事老夫犹赋咏，欲将酬和永留传。','',''),('quantangshi-38619','句','孫偓','quantangshi','','卷39','好是步虚明月夜，瑞炉蜚下醮坛前。','',''),('quantangshi-38620','禁林闻晓莺','陸扆','quantangshi','','卷39','曙色分层汉，莺声绕上林。
报花开瑞锦，催柳绽黄金。
断续随风远，间关送月沈。
语当温树近，飞觉禁园深。
绣户惊残梦，瑶池啭好音。
愿将栖息意，从此沃天心。','',''),('quantangshi-38621','句','陸扆','quantangshi','','卷39','今秋已约天台月。','',''),('quantangshi-38622','华州牓寄诸门生','薛昭緯','quantangshi','','卷39','时君过听委平衡，粉署华灯到晓明。
开卷固难窥浩汗，执衡空欲慕公平。
机云笔舌临文健，沈宋章篇发咏清。
自笑观光辉。','',''),('quantangshi-38623','谢银工','薛昭緯','quantangshi','','卷39','一楪毡根数十皴，盘中犹更有红鳞。
早知文字多辛苦，悔不当初学冶银。','',''),('quantangshi-38624','闲居即事','陸翱','quantangshi','','卷39','衰柳迷隋苑，衡门啼暮鸦。
茅厨烟不动，书牖日空斜。
悔下东山石，贫于南阮家。
沈忧损神虑，萱草自开花。','',''),('quantangshi-38625','赵氏北楼','陸翱','quantangshi','','卷39','殷勤赵公子，良夜竟相留。
朗月生东海，仙娥在北楼。
酒阑珠露滴，歌逈石城秋。
本为愁人设，愁人到晓愁。','',''),('quantangshi-38626','题马嵬驿','狄歸昌','quantangshi','','卷39','马嵬烟柳正依依，重见銮舆幸蜀归。
泉下阿蛮应有语，这回休更怨杨妃。','',''),('quantangshi-38627','蜀中登第答李搏六韵','裴廷裕','quantangshi','','卷39','何劳问我成都事，亦报君知便纳降。
蜀柳笼堤烟矗矗，海棠当户燕双双。
富春不并穷师子，濯锦全胜旱曲江。
高卷绛纱扬氏宅，半垂红袖薛涛牕。
浣花泛鷁诗千首，静众寻梅酒百缸。
若说弦歌与风景，主人兼是碧油幢。','',''),('quantangshi-38628','偶题','裴廷裕','quantangshi','','卷39','微雨微风寒食节，半开半合木兰花。
看花倚柱终朝立，却似凄凄不在家。','',''),('quantangshi-38629','闲宵望月','李沇','quantangshi','','卷39','卷箔舒红茵，当轩翫明月。
懿哉深夜中，静听歌初发。
苔含殿华湿，竹影蟾光洁。
转扇来清风，援琴飞白雪。
行愁景候变，坐恐流芳歇。
桂影有余光，兰灯任将灭。','',''),('quantangshi-38630','醮词','李沇','quantangshi','','卷39','犬咬天关闭，彩童呼仙吏。
一封红篆书，为奏尘寰事。
八极鳌柱倾，四溟龙鬣沸。
长庚冷有芒，文曲澹无气。
乌轮不再中，黄沙瘗腥鬼。
请帝命真官，临云启金匮。
方与清华宫，重正紫极位。
旷古雨露恩，安得惜沾施。
生人血欲尽，搀抢无饱意。','',''),('quantangshi-38631','巫山高','李沇','quantangshi','','卷39','抉天心，开地脉，俘动凌霄拂蓝碧。
襄王端眸望不极，似睹瑶姬长叹息。
巫妆不治独西望，暗泣红蕉抱云帐。
君王妬妾梦荆宫，虚把金泥印仙掌。
江涛迅激如相助，十二狞龙怒行雨。
昆仑谩有通天路，九峰正在天低处。','',''),('quantangshi-38632','梦仙谣','李沇','quantangshi','','卷39','海宫蹙浪收残月，挈壶掌事传更歇。
银蟾半坠恨流咽，六鳌披月撼蓬阙。
九炁真翁骑白犀，临池静听雌蛟啼。
桂花浥露曙香冷，八窗玉朗惊晨鸡。
裁纱翦罗贴丹凤，腻霞远闭瑶山梦。
露干欲醉芙蕖塘，回首驱云朝正阳。','',''),('quantangshi-38633','秋霖歌','李沇','quantangshi','','卷39','西方龙儿口犹乳，初解驱云学行雨。
纵恣羣阴驾老虬，勺水蹄涔尽奔注。
叶破苔黄未休滴，腻光透长狂莎色。
恨无长劒一千仞，划断顽云看晴碧。','',''),('quantangshi-38634','方响歌','李沇','quantangshi','','卷39','敲金扣石声相凌，遥空冷静天正澄。
宝瓶下井辘轳急，小娃弄索伤清冰。
穿丝透管音未歇，回风绕指惊泉咽。
季伦怒击珊瑚摧，灵芸整鬓步摇折。
十六叶中侵素光，寒玲震月杂佩璫。
云和不觉罢余怨，莲峰一夜啼琴姜。
急节写商商恨促，秦愁越调逡巡足。
梦入仙楼戛残曲，飞霜棱棱上秋玉。','',''),('quantangshi-38635','答王涣','裴贄','quantangshi','','卷39','谬持文柄得时贤，粉署清华次第迁。
昔岁策名皆健笔，今朝称职并同年。
各怀器业宁推让，俱上青霄肯后先。
何事老夫犹赋咏，欲将酬和永留传。','',''),('quantangshi-38636','薄命妾','盧汝弼','quantangshi','','卷39','君恩已断尽成空，追想娇欢恨莫穷。
长为蕣花光晓日，谁知团扇送秋风。
黄金买赋心徒切，清路飞尘信莫通。
闲凭玉栏思旧事，几回春暮泣残红。','',''),('quantangshi-38637','秋夕寓居精舍书事','盧汝弼','quantangshi','','卷39','叶满苔堦杵满城，此中多恨恨难平。
疎檐看织蟏蛸网，暗隙愁听蟋蟀声。
醉卧欲抛羁客思，梦归偏动故乡情。
觉来独步长廊下，半夜西风吹月明。','',''),('quantangshi-38638','闻雁','盧汝弼','quantangshi','','卷39','秋风萧瑟静埃氛，边雁迎风响咽羣。
瀚海应嫌霜下早，湘川偏爱草初薰。
芦洲宿处依沙岸，榆塞飞时度晚云。
何处最添羁客恨，竹窗残月酒醒闻。','',''),('quantangshi-38639','鸳鸯','盧汝弼','quantangshi','','卷39','双浮双浴傍苔矶，蓼浦兰臯绣帐帏。
长羡鹭鸶能洁白，不随鸂鶒鬬毛衣。
霞侵绿渚香衾暖，楼倚青云殿瓦飞。
应笑随阳沙漠雁，洞庭烟暖又思归。','',''),('quantangshi-38640','和李秀才边庭四时怨 一','盧汝弼','quantangshi','','卷39','春风昨夜到榆关，故国烟花想已残。
少妇不知归不得，朝朝应上望夫山。','',''),('quantangshi-38641','和李秀才边庭四时怨 二','盧汝弼','quantangshi','','卷39','卢龙塞外草初肥，雁乳平芜晓不飞。
乡国近来音信断，至今犹自着寒衣。','',''),('quantangshi-38642','和李秀才边庭四时怨 三','盧汝弼','quantangshi','','卷39','八月霜飞柳半黄，蓬根吹断雁南翔。
陇头流水关山月，泣上龙堆望故乡。','',''),('quantangshi-38643','和李秀才边庭四时怨 四','盧汝弼','quantangshi','','卷39','朔风吹雪透刀瘢，饮马长城窟更寒。
半夜火来知有敌，一时齐保贺兰山。','',''),('quantangshi-38644','山居即事二首 一','陸希聲','quantangshi','','卷39','君山苍翠接青冥，东走洮湖上洞庭。
茅屋向阳梳白发，竹窓深夜诵丹经。
涌泉回泬鱼龙气，怪石惊腾鸟兽形。
为问前时金马客，此焉还作少微星。','',''),('quantangshi-38645','山居即事二首 二','陸希聲','quantangshi','','卷39','不是幽栖矫性灵，从来无意在膻腥。
满川风物供高枕，四合云山借画屏。
五鹿归来惊岳岳，孤鸿飞去入冥冥。
君阳遁叟何为乐，一炷清香两卷经。','',''),('quantangshi-38646','阳羡杂咏十九首 苦竹迳','陸希聲','quantangshi','','卷39','山前无数碧琅玕，一迳清森五月寒。
世上何人怜苦节，应须细问子猷看。','',''),('quantangshi-38647','阳羡杂咏十九首 梅花坞','陸希聲','quantangshi','','卷39','冻蘂凝香色艳新，小山深坞伴幽人。
知君有意凌寒色，羞共千花一样春。','',''),('quantangshi-38648','阳羡杂咏十九首 石兕台','陸希聲','quantangshi','','卷39','大河波浪激潼关，青兕胡为伏此山。
遥想楚王云梦泽，霓旌羽盖定空还。','',''),('quantangshi-38649','阳羡杂咏十九首 讲易台','陸希聲','quantangshi','','卷39','年逾知命志尤坚，独向青山更绝编。
天下有山山有水，养蒙肥遯正翛然。','',''),('quantangshi-38650','阳羡杂咏十九首 观鱼亭','陸希聲','quantangshi','','卷39','惠施徒自学多方，谩说观鱼理未长。
不得庄生濠上旨，江湖何以见相忘。','',''),('quantangshi-38651','阳羡杂咏十九首 绿云亭','陸希聲','quantangshi','','卷39','六月清凉绿树阴，小亭高卧涤烦襟。
羲皇向上何人到，永日时时弄素琴。','',''),('quantangshi-38652','阳羡杂咏十九首 清辉堂','陸希聲','quantangshi','','卷39','野人心地本无机，为爱茅檐倚翠微。
尽日尊前谁是客，秋山含水有清辉。','',''),('quantangshi-38653','阳羡杂咏十九首 观妙庵','陸希聲','quantangshi','','卷39','妙理难观旨甚深，欲知无欲是无心。
茅庵不异人间世，河上真人自可寻。','',''),('quantangshi-38654','阳羡杂咏十九首 西阳亭','陸希聲','quantangshi','','卷39','隔林残日照孤亭，玄[晏]先生酒未醒。
入夜莫愁迷下路，昔人犹在逐流萤。','',''),('quantangshi-38655','阳羡杂咏十九首 弄云亭','陸希聲','quantangshi','','卷39','自知无业致吾君，只向春山弄白云。
已共此山私断当，不须转辙重移文。','',''),('quantangshi-38656','阳羡杂咏十九首 伏龟堂','陸希聲','quantangshi','','卷39','盘崖蹙缩似灵龟，鬼谷先生隐遁时。
不独卷怀经世志，白云流水是心期。','',''),('quantangshi-38657','阳羡杂咏十九首 桃花谷','陸希聲','quantangshi','','卷39','君阳山下足春风，满谷仙桃照水红。
何必武陵源上去，涧边好过落花中。','',''),('quantangshi-38658','阳羡杂咏十九首 含桃圃','陸希聲','quantangshi','','卷39','小圃初晴风露光，含桃花发满山香。
看花对酒心无事，倍觉春来白日长。','',''),('quantangshi-38659','阳羡杂咏十九首 茗坡','陸希聲','quantangshi','','卷39','二月山家谷雨天，半坡芳茗露华鲜。
