岁寒本是君家事，好送清风月下来。','',''),('quantangshi-38661','阳羡杂咏十九首 桃溪','陸希聲','quantangshi','','卷39','芳草霏霏遍地齐，桃花脉脉自成溪。
也知百舌多言语，任向春风尽意啼。','',''),('quantangshi-38662','阳羡杂咏十九首 李径','陸希聲','quantangshi','','卷39','一径穠芳万蘂攒，风吹雨打未摧残。
怜君尽向高枝发，应为行人要整冠。','',''),('quantangshi-38663','阳羡杂咏十九首 鸿盘','陸希聲','quantangshi','','卷39','落落飞鸿渐始盘，青云起处剩须看。
如今天路多矰缴，纵使衔芦去也难。','',''),('quantangshi-38664','阳羡杂咏十九首 偃月岭','陸希聲','quantangshi','','卷39','山岭依稀偃月形，数层倚石叠空青。
几回雪夜寒光积，直似金光照户庭。','',''),('quantangshi-38665','寄{巩/言}光上人','陸希聲','quantangshi','','卷39','笔下龙蛇似有神，天池雷雨变逡巡。
寄言昔日不龟手，应念江头洴澼人。','',''),('quantangshi-38666','喜杜荀鹤及第','李昭象','quantangshi','','卷39','深岩贫复病，榜到见君名。
贫病浑如失，山川顿觉清。
一春新酒兴，四海旧诗声。
日使能吟者，西来步步轻。','',''),('quantangshi-38667','赴举出山留寄山居郑参军','李昭象','quantangshi','','卷39','还如费冠卿，向此振高名。
肯羡鱼须美，长夸鹤氅轻。
理琴寒指倦，试药黑髭生。
时泰难云卧，随看急诏行。','',''),('quantangshi-38668','题顾正字溪居','李昭象','quantangshi','','卷39','高敞吟轩近钓湾，尘中来似出人间。
若教明月休生桂，应得危时共掩关。
春酒夜棊难放客，短篱疎竹不遮山。
莫夸恬淡胜荣禄，雁引行高未许闲。','',''),('quantangshi-38669','寄献山中顾公员外','李昭象','quantangshi','','卷39','抽却朝簪着钓蓑，近来声迹转巍峩。
祥麟避网虽山野，丹凤衔书即薜萝。
乍隐文章情更逸，久闲经济术翻多。
深慙未副吹嘘力，竟困风埃争奈何。','',''),('quantangshi-38670','山中寄崔谏议','李昭象','quantangshi','','卷39','半生猨鸟共山居，吟月吟风两鬓疎。
新句未尝忘教化，上才争忍不吹嘘。
全家欲去干戈后，大国中兴礼乐初。
从此升腾休说命，秪希公道数封书。','',''),('quantangshi-38671','学仙词寄顾云','李昭象','quantangshi','','卷39','记得初传九转方，碧云峰下祝虚皇。
丹砂未熟心徒切，白日难留鬓欲苍。
无路洞天寻穆满，有时人世美刘郎。
仙人恩重何由报，焚尽星坛午夜香。','',''),('quantangshi-38672','寄尉迟侍御','李昭象','quantangshi','','卷39','我眠青嶂弄澄潭，君戴貂蝉白玉篸。
应向谢公楼上望，九华山色在西南。','',''),('quantangshi-38673','招西洞道者','李昭象','quantangshi','','卷39','危峰抹黛夹晴川，树簇红英草碧烟。
樵客云僧两无事，此中堪去觅灵仙。','',''),('quantangshi-38674','句','李昭象','quantangshi','','卷39','投文得仕而今少，佩印还家古所荣。','',''),('quantangshi-38675','夏雨','王駕','quantangshi','','卷39','非惟消旱暑，且喜救生民。
天地如蒸湿，园林似却春。
洗风清枕簟，换夜失埃尘。
又作丰年望，田夫笑向人。','',''),('quantangshi-38676','古意','王駕','quantangshi','','卷39','夫戍萧关妾在吴，西风吹妾妾忧夫。
一行书信千行泪，寒到君边衣到无。','',''),('quantangshi-38677','社日','王駕','quantangshi','','卷39','鹅湖山下稻粱肥，豚栅鸡栖半掩扉。
桑柘影斜春社散，家家扶得醉人归。','',''),('quantangshi-38678','雨晴','王駕','quantangshi','','卷39','雨前初见花间蘂，雨后兼无叶里花。
蛱蝶飞来过墙去，却疑春色在邻家。','',''),('quantangshi-38679','乱后曲江','王駕','quantangshi','','卷39','忆昔争游曲水滨，未春长有探春人。
游春人尽空池在，直至春深不似春。','',''),('quantangshi-38680','过故友居','王駕','quantangshi','','卷39','邻笛寒吹日落初，旧居今已别人居。
乱来儿侄皆分散，惆怅僧房认得书。','',''),('quantangshi-38681','上裴侍郎','王渙','quantangshi','','卷39','青衿七十牓三年，建礼含香次第迁。
珠彩下连星错落，桂花曾对月婵娟。
玉经磨琢多成器，剑拔沈埋更倚天。
应念衔恩最深者，春来为寿拜尊前。','',''),('quantangshi-38682','悼亡','王渙','quantangshi','','卷39','春来得病夏来加，深掩妆窗卧碧纱。
为怯暗藏秦女扇，怕惊愁度阿香车。
腰肢暗想风欺柳，粉态难忘露洗花。
今日青门葬君处，乱蝉衰草夕阳斜。','',''),('quantangshi-38683','惆怅诗十二首 一','王渙','quantangshi','','卷39','八蚕薄絮鸳鸯绮，半夜佳期并枕眠。
钟动红娘唤归去，对人匀泪拾金钿。','',''),('quantangshi-38684','惆怅诗十二首 二','王渙','quantangshi','','卷39','李夫人病已经秋，汉武看来不举头。
得所浓华销歇尽，楚魂湘血一生休。','',''),('quantangshi-38685','惆怅诗十二首 三','王渙','quantangshi','','卷39','谢家池馆花笼月，萧寺房廊竹颭风。
夜半酒醒凭槛立，所思多在别离中。','',''),('quantangshi-38686','惆怅诗十二首 四','王渙','quantangshi','','卷39','隋师战舰欲亡陈，国破应难保此身。
