蜀王殿里三更月，不见骊山私语人。','',''),('quantangshi-38688','惆怅诗十二首 六','王渙','quantangshi','','卷39','夜寒春病不胜怀，玉瘦花啼万事乖。
薄幸檀郎断芳信，惊嗟犹梦合欢鞋。','',''),('quantangshi-38689','惆怅诗十二首 七','王渙','quantangshi','','卷39','呜咽离声管吹秋，妾身今日为君休。
齐奴不说平生事，忍看花枝谢玉楼。','',''),('quantangshi-38690','惆怅诗十二首 八','王渙','quantangshi','','卷39','青丝一绺堕云鬟，金翦刀鸣不忍看。
持谢君王寄幽怨，可能从此住人间。','',''),('quantangshi-38691','惆怅诗十二首 九','王渙','quantangshi','','卷39','陈宫兴废事难期，三阁空余绿草基。
狎客沦亡丽华死，他年江令独来时。','',''),('quantangshi-38692','惆怅诗十二首 十','王渙','quantangshi','','卷39','晨肇重来路已迷，碧桃花谢武陵溪。
仙山目断无寻处，流水潺湲日渐西。','',''),('quantangshi-38693','惆怅诗十二首 十一','王渙','quantangshi','','卷39','少卿降北子卿还，朔野离觞惨别颜。
却到茂陵唯一恸，节毛零落鬓毛斑。','',''),('quantangshi-38694','惆怅诗十二首 十二','王渙','quantangshi','','卷39','梦里分明入汉宫，觉来灯背锦屏空。
紫台月落关山晓，肠断君恩信画工。','',''),('quantangshi-38695','江上雨','戴司顏','quantangshi','','卷39','非不欲前去，此情非自由。
星辰照何处，风雨送凉秋。
寒锁空江梦，声随黄叶愁。
萧萧犹未已，早晚去苹洲。','',''),('quantangshi-38696','塞上','戴司顏','quantangshi','','卷39','空迹昼苍茫，沙腥古战场。
逢春多霰雪，生计在牛羊。
冷角吹乡泪，干榆落梦牀。
从来山水客，谁谓到渔阳。','',''),('quantangshi-38697','句','戴司顏','quantangshi','','卷39','远来朝凤阙，归去恋元侯。','',''),('quantangshi-38698','投谢钱武肃','吳仁璧','quantangshi','','卷39','东门上相好知音，数尽台前郭隗金。
累重虽然容食椹，力微无计报焚林。
弊貂不称芙蓉幕，衰朽仍惭玳瑁簪。
十里溪光一山月，可堪从此负归心。','',''),('quantangshi-38699','客路','吳仁璧','quantangshi','','卷39','人寰急景如波委，客路浮云似盖轻。
回首故山天外碧，十年无计却归耕。','',''),('quantangshi-38700','南徐题友人郊居','吳仁璧','quantangshi','','卷39','门前樵径连江寺，岸下渔矶系海槎。
待到秋深好时节，与君长醉隐侯家。','',''),('quantangshi-38701','读度人经寄郑仁表','吳仁璧','quantangshi','','卷39','身虽一旦尘中老，名拟三清会里题。
二午九斋余日在，请君相伴醉如泥。','',''),('quantangshi-38702','秋日听僧弹琴','吳仁璧','quantangshi','','卷39','金徽玉轸韵泠然，言下浮生指下泉。
恰称秋风西北起，一时吹入碧湘烟。','',''),('quantangshi-38703','贾谊','吳仁璧','quantangshi','','卷39','扶持一疏满遗编，汉陛前头正少年。
谁道恃才轻绛灌，却将惆怅吊湘川。','',''),('quantangshi-38704','春雪','吳仁璧','quantangshi','','卷39','雪霁凝光入坐寒，天明犹自卧袁安。
貂裘穿后鹤氅敝，自此风流不足看。','',''),('quantangshi-38705','衰柳','吳仁璧','quantangshi','','卷39','金风渐利露珠团，广陌长堤黛色残。
水殿狂游隋炀帝，一千余里可堪看。','',''),('quantangshi-38706','凤仙花','吳仁璧','quantangshi','','卷39','香红嫩绿正开时，冷蝶饥蜂两不知。
此际最宜何处看，朝阳初上碧梧枝。','',''),('quantangshi-38707','金钱花','吳仁璧','quantangshi','','卷39','浅绛浓香几朵匀，日镕金铸万家新。
堪疑刘宠遗芳在，不许山阴父老贫。','',''),('quantangshi-38708','钱塘鹤','吳仁璧','quantangshi','','卷39','人间路霭青天半，鳌岫云生碧海涯。
虽抱雕笼密扃钥，可能长在叔伦家。','',''),('quantangshi-38709','句','吳仁璧','quantangshi','','卷39','为惜苔钱妨换砌，因怜山色旋开尊。
高阁烟霞禅客睡，满城尘土世人忙。
五龙金角向星斗，三洞玉音愁鬼神。
蒲草薄裁连蒂白，胭脂浓染半葩红。','',''),('quantangshi-38710','奉试麦垄多秀色','汪極','quantangshi','','卷39','南陌生岐穗，农家乐事多。
塍畦交茂绿，苗实际清和。
日布玲珑影，风翻浩荡波。
来牟知帝力，含哺有衢歌。','',''),('quantangshi-38711','下第戏状元崔昭纬','張曙','quantangshi','','卷39','千里江山陪骥尾，五更风水失龙鳞。
昨夜浣花溪上雨，绿杨芳草为何人。','',''),('quantangshi-38712','赠天台王处士','林嵩','quantangshi','','卷39','深隐天台不记秋，琴台长别一何愁。
茶烟岩外云初起，新月潭心钓未收。
映宇异花丛发好，穿松孤鹤一声幽。
赤城不掩高宗梦，宁久悬冠枕瀑流。','',''),('quantangshi-38713','春宫怨','杜荀鶴','quantangshi','','卷39','早被婵娟误，欲妆临镜慵。
承恩不在貌，教妾若为容。
风暖鸟声碎，日高花影重。
年年越溪女，相忆采芙蓉。','',''),('quantangshi-38714','访道者不遇','杜荀鶴','quantangshi','','卷39','寂寂白云门，寻真不遇真。
祗应松上鹤，便是洞中人。
药圃花香异，沙泉鹿迹新。
题诗留姓字，他日此相亲。','',''),('quantangshi-38715','送人游吴','杜荀鶴','quantangshi','','卷39','君到姑苏见，人家尽枕河。
古宫闲地少，水港小桥多。
夜市卖菱藕，春船载绮罗。
遥知未眠月，乡思在渔歌。','',''),('quantangshi-38716','送陈昈归麻川','杜荀鶴','quantangshi','','卷39','麻川清见底，似入武陵溪。
两岸山相向，三春鸟乱啼。
酒旗和柳动，僧屋与云齐。
即此吾乡路，怀君梦不迷。','',''),('quantangshi-38717','出山','杜荀鶴','quantangshi','','卷39','病眼看春牓，文场公道开。
朋人登第尽，白发出山来。
处世曾无过，惟天合是媒。
长安不觉远，期遂一名回。','',''),('quantangshi-38718','浙中逢诗友','杜荀鶴','quantangshi','','卷39','到处有同人，多为赋与文。
诗中难得友，湖畔喜逢君。
冻把城根雪，风开岳面云。
苦吟吟不足，争忍话离羣。','',''),('quantangshi-38719','送友游吴越','杜荀鶴','quantangshi','','卷39','去越从吴过，吴疆与越连。
有园多种橘，无水不生莲。
夜市桥边火，春风寺外船。
此中偏重客，君去必经年。','',''),('quantangshi-38720','出常山界使回有寄','杜荀鶴','quantangshi','','卷39','自小即南北，未如今日离。
封疆初尽处，人使却回时。
开口有所忌，此心无以为。
行行复垂泪，不称是男儿。','',''),('quantangshi-38721','经废宅','杜荀鶴','quantangshi','','卷39','人生当贵盛，修德可延之。
不虑有今日，争教无破时。
藓斑题字壁，花发带巢枝。
何况蒿原上，荒坟与折碑。','',''),('quantangshi-38722','登天台寺','杜荀鶴','quantangshi','','卷39','一到天台寺，高低景旋生。
共僧岩上坐，见客海边行。
野色人耕破，山根浪打鸣。
忙时向闲处，不觉有闲情。','',''),('quantangshi-38723','途中春','杜荀鶴','quantangshi','','卷39','马上览春色，丈夫慙泪垂。
一生看却老，五字未逢知。
酒力不能久，愁根无可医。
明年到今日，公道与谁期。','',''),('quantangshi-38724','入关历阳道中却寄舍弟','杜荀鶴','quantangshi','','卷39','求名日苦辛，日望日荣亲。
落叶山中路，秋霖马上人。
晨昏知汝道，诗酒卫吾身。
自笑抛麋鹿，长安拟醉春。','',''),('quantangshi-38725','赠欧阳明府','杜荀鶴','quantangshi','','卷39','贤宰宰斯邑，政闻闾里间。
都缘民讼少，长觉吏徒闲。
帆落樽前浦，钟鸣枕上山。
回舟却惆怅，数宿钓鱼湾。','',''),('quantangshi-38726','赠临上人','杜荀鶴','quantangshi','','卷39','不计禅兼律，终须入悟门。
解空非有自，所得是无言。
眼豁浮生梦，心澄大道源。
今来习师者，多鏁教中猿。','',''),('quantangshi-38727','题战岛僧居','杜荀鶴','quantangshi','','卷39','师爱无尘地，江心岛上居。
接船求化惯，登陆赴斋疎。
载士春栽树，抛生日餧鱼。
入云萧帝寺，毕竟欲何如。','',''),('quantangshi-38728','别衡州牧','杜荀鶴','quantangshi','','卷39','朝别使君门，暮投江上村。
从来无旧分，临去望何恩。
行计自不定，此心谁与论。
秋猿叫寒月，祗欲断人魂。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-38729','送人游江南','杜荀鶴','quantangshi','','卷39','满酌劝君酒，劝君君莫辞。
能禁几度别，即到白头时。
晚岫无云蔽，春帆有燕随。
男儿两行泪，不欲等闲垂。','',''),('quantangshi-38730','游茅山','杜荀鶴','quantangshi','','卷39','步步入山门，仙家鸟径分。
渔樵不到处，麋鹿自成羣。
石面迸出水，松头穿破云。
道人星月下，相次礼茅君。','',''),('quantangshi-38731','读友人诗卷','杜荀鶴','quantangshi','','卷39','冰齿味瑶轴，祗应神鬼知。
坐当羣静后，吟到月沈时。
雪峡猿声健，风柽鹤立危。
篇篇一字字，谁复更言诗。','',''),('quantangshi-38732','寄从叔','杜荀鶴','quantangshi','','卷39','三族不当路，长年犹布衣。
苦吟天与性，直道世将非。
雁夜愁痴坐，渔乡老忆归。
为儒皆可立，自是拙时机。','',''),('quantangshi-38733','寄李溥','杜荀鶴','quantangshi','','卷39','如我如君者，不妨身晚成。
但从时辈笑，自得古人情。
共莫更初志，俱期立后名。
男儿且如此，何用叹平生。','',''),('quantangshi-38734','郊居即事投李给事','杜荀鶴','quantangshi','','卷39','无禄奉晨昏，闲居几度春。
江湖苦吟士，天地最穷人。
书劒同三友，蓬蒿外四邻。
相知不相荐，何以自谋身。','',''),('quantangshi-38735','寄诗友','杜荀鶴','quantangshi','','卷39','别来春又春，相忆喜相亲。
与我为同志，如君能几人。
何时吟得力，渐老事关身。
惟有前溪水，年年濯客尘。','',''),('quantangshi-38736','题田翁家','杜荀鶴','quantangshi','','卷39','田翁真快活，婚嫁不离村。
州县供输罢，追随鼓笛喧。
盘飧同老少，家计共田园。
自说身无事，应官有子孙。','',''),('quantangshi-38737','长安冬日','杜荀鶴','quantangshi','','卷39','近腊饶风雪，闲房冻坐时。
书生教到此，天意转难知。
吟苦猿三叫，形枯柏一枝。
还应公道在，未忍与山期。','',''),('quantangshi-38738','霁后登唐兴寺水阁','杜荀鶴','quantangshi','','卷39','一雨三秋色，萧条古寺间。
无端登水阁，有处似家山。
白日生新事，何时得暂闲。
将知老僧意，未必恋松关。','',''),('quantangshi-38739','山中寄友人','杜荀鶴','quantangshi','','卷39','深山多隙地，无力及耕桑。
不是营生拙，都缘觅句忙。
破窗风翳烛，穿屋月侵牀。
吾友应相笑，辛勤道未光。','',''),('quantangshi-38740','自述','杜荀鶴','quantangshi','','卷39','四海欲行遍，不知终遇谁。
用心常合道，出语或伤时。
拟作闲人老，慙无识者嗤。
如今已无计，祗得苦于诗。','',''),('quantangshi-38741','题江山寺','杜荀鶴','quantangshi','','卷39','江上山头寺，景留吟客船。
遍游销一日，重到是何年。
沙鸟多翘足，岩僧半露肩。
为诗多语涩，喜此得终篇。','',''),('quantangshi-38742','秋日旅舍卧病呈所知','杜荀鶴','quantangshi','','卷39','秋色上庭枝，愁怀切向谁。
青云无势日，华发有狂时。
枕上闻风雨，江南系别离。
如何吟到此，此道不闻知。','',''),('quantangshi-38743','秋宿山馆','杜荀鶴','quantangshi','','卷39','山馆坐待晓，夜长吟役神。
斜风吹败叶，寒烛照愁人。
蕴蓄天然性，浇讹世恶真。
男儿出门志，不独为谋身。','',''),('quantangshi-38744','赠老僧','杜荀鶴','quantangshi','','卷39','众僧尊夏腊，灵岳遍曾登。
度水手中杖，行山溪畔藤。
心空默是印，眉白雪为棱。
自得巡方道，栖禅老未能。','',''),('quantangshi-38745','别舍弟','杜荀鶴','quantangshi','','卷39','欲住住不得，出门天气秋。
惟知偷拭泪，不忍更回头。
此日祗愁老，况身方远游。
孤寒将五字，何以动诸侯。','',''),('quantangshi-38746','雪中别诗友','杜荀鶴','quantangshi','','卷39','酒寒无小户，请满酌行杯。
若待雪消去，自然春到来。
出城人迹少，向暮鸟声哀。
未遇应关命，侯门处处开。','',''),('quantangshi-38747','题岳麓寺','杜荀鶴','quantangshi','','卷39','一簇楚江山，江山胜此难。
觅人来画取，到处得吟看。
鹤隐松声尽，鱼沈槛影寒。
自知心未了，闲话亦多端。','',''),('quantangshi-38748','怀庐岳书斋','杜荀鶴','quantangshi','','卷39','长忆在庐岳，免低尘土颜。
煮茶窗底水，采药屋头山。
是境皆游遍，谁人不羡闲。
无何一名系，引出白云间。','',''),('quantangshi-38749','题唐兴寺小松','杜荀鶴','quantangshi','','卷39','虽小天然别，难将众木同。
侵僧半窗月，向客满襟风。
枝拂行苔鹤，声分叫砌虫。
如今未堪看，须是雪霜中。','',''),('quantangshi-38750','与友人话别','杜荀鶴','quantangshi','','卷39','客路行多少，干人无易颜。
未成终老计，难致此身闲。
月兔走入海，日乌飞出山。
流年留不得，半在别离间。','',''),('quantangshi-38751','赠庐岳隐者','杜荀鶴','quantangshi','','卷39','自见来如此，未尝离洞门。
结茅遮雨雪，采药给晨昏。
古树藤缠杀，春泉鹿过浑。
悠悠无一事，不似属干坤。','',''),('quantangshi-38752','怀紫阁隐者','杜荀鶴','quantangshi','','卷39','紫阁白云端，云中有地仙。
未归蓬岛上，犹隐国门前。
洞口人无迹，花阴鹿自眠。
焚香赋诗罢，星月冷遥天。','',''),('quantangshi-38753','题会上人院','杜荀鶴','quantangshi','','卷39','鼓角城中寺，师居日得闲。
必能行大道，何用在深山。
破衲新添线，空门夜不关。
心知与眼见，终取到无间。','',''),('quantangshi-38754','送黄补阙南迁','杜荀鶴','quantangshi','','卷39','得罪非天意，分明谪去身。
一心贪谏主，开口不防人。
自古有迁客，何朝无直臣。
喧然公论在，虽滞楚南春。','',''),('quantangshi-38755','送宾贡登第后归海东','杜荀鶴','quantangshi','','卷39','归捷中华第，登船鬓未丝。
直应天上桂，别有海东枝。
国界波穷处，乡心日出时。
西风送君去，莫虑到家迟。','',''),('quantangshi-38756','近试投所知','杜荀鶴','quantangshi','','卷39','白发随梳落，吟怀说向谁。
敢辞成事晚，自是出山迟。
拟动如浮海，凡言似课诗。
终身事知己，此外复何为。','',''),('quantangshi-38757','送友人牧江州','杜荀鶴','quantangshi','','卷39','本国兵戈后，难官在此时。
远分天子命，深要使君知。
但遂生灵愿，当应雨露随。
江山胜他郡，闲赋庾楼诗。','',''),('quantangshi-38758','辞座主侍郎','杜荀鶴','quantangshi','','卷39','一饭尚怀感，况攀高桂枝。
此恩无报处，故国远归时。
祗恐兵戈隔，再趋门馆迟。
茅堂拜亲后，特地泪双垂。','',''),('quantangshi-38759','别从叔','杜荀鶴','quantangshi','','卷39','立马不忍上，醉醒天气寒。
都缘在门易，直似别家难。
世路既如此，客心须自宽。
江村亦饥冻，争及问长安。','',''),('quantangshi-38760','送人南游','杜荀鶴','quantangshi','','卷39','凡游南国者，未有不蹉跎。
到海路难尽，挂帆人更多。
潮沙分象迹，花洞响蛮歌。
纵有投文处，于君能几何。','',''),('quantangshi-38761','经贾岛墓','杜荀鶴','quantangshi','','卷39','谪宦自麻衣，衔冤至死时。
山根三尺墓，人口数联诗。
仙桂终无分，皇天似有私。
暗松风雨夜，空使老猿悲。','',''),('quantangshi-38762','秋夜晚泊','杜荀鶴','quantangshi','','卷39','一望一苍然，萧骚起暮天。
远山横落日，归鸟度平川。
家是去秋别，月当今夕圆。
渔翁似相伴，彻晓苇丛边。','',''),('quantangshi-38763','送舍弟','杜荀鶴','quantangshi','','卷39','我受羁栖惯，客情方细知。
好看前路事，不比在家时。
勉汝言须记，闻人善即师。
旅中无废业，时作一篇诗。','',''),('quantangshi-38764','将归山逢友人','杜荀鶴','quantangshi','','卷39','儒为君子儒，儒道不妨孤。
白发多生矣，青山可住乎。
徉狂宁是事，巧达又非夫。
祗此平生愿，他人肯信无。','',''),('quantangshi-38765','经九华费征君墓','杜荀鶴','quantangshi','','卷39','凡吊先生者，多伤荆棘间。
不知三尺墓，高却九华山。
天地有何外，子孙无亦闲。
当时若征起，未必得身还。','',''),('quantangshi-38766','溪居叟','杜荀鶴','quantangshi','','卷39','溪翁居静处，溪鸟入门飞。
早起钓鱼去，夜深乘月归。
见君无事老，觉我有求非。
不说风霜苦，三冬一草衣。','',''),('quantangshi-38767','与友人对酒吟','杜荀鶴','quantangshi','','卷39','凭君满酌酒，听我醉中吟。
客路如天远，侯门似海深。
新坟侵古道，白发恋黄金。
共有人间事，须怀济物心。','',''),('quantangshi-38768','送僧','杜荀鶴','quantangshi','','卷39','道了亦未了，言闲今且闲。
从来无住处，此去向何山。
片石树阴下，斜阳潭影间。
请师留偈别，恐不到人寰。','',''),('quantangshi-38769','送九华道士游茅山','杜荀鶴','quantangshi','','卷39','忽起地仙兴，飘然出旧山。
于身无切事，在世有余闲。
日月浮生外，干坤大醉间。
故园华表上，谁得见君还。','',''),('quantangshi-38770','寄舍弟','杜荀鶴','quantangshi','','卷39','世乱信难通，乡心日万重。
弟兄皆向善，天地合相容。
大野阴云重，连城杀气浓。
家山白云里，卧得最高峰。','',''),('quantangshi-38771','下第投所知','杜荀鶴','quantangshi','','卷39','若以名场内，谁无一轴诗。
纵饶生白发，岂敢怨明时。
知己虽然切，春官未必私。
宁教读书眼，不有看花期。','',''),('quantangshi-38772','寄顾云','杜荀鶴','quantangshi','','卷39','省得前年别，苹洲旅馆中。
乱离身不定，彼此信难通。
侯国兵虽敛，吾乡业已空。
秋来忆君梦，夜夜逐征鸿。','',''),('quantangshi-38773','赠宣城麋明府','杜荀鶴','quantangshi','','卷39','天下为官者，无君一轴诗。
数联同我得，当代遇谁知。
年齿吟将老，生涯说可悲。
何当抛手板，邻隐过危时。','',''),('quantangshi-38774','望远','杜荀鶴','quantangshi','','卷39','门前通大道，望远上高台。
落日人行尽，穷边信不来。
还闻战得胜，未见敕招回。
却入机中坐，新愁织不开。','',''),('quantangshi-38775','冬末投长沙裴侍郎','杜荀鶴','quantangshi','','卷39','欲露尘中事，其如不易言。
家山一离别，草树匝春暄。
吹梦风天角，啼愁雪岳猿。
伫思心觉满，何以远门轩。','',''),('quantangshi-38776','赠秋浦金明府长','杜荀鶴','quantangshi','','卷39','倚郭难为宰，非君即有私。
惟凭野老口，不立政声碑。
苦甚求名日，贫于未选时。
溪山竟如此，利得且吟诗。','',''),('quantangshi-38777','和高祕书早春对雪登楼见寄之什','杜荀鶴','quantangshi','','卷39','天有惜花意，恐花开染尘。
先教微雪下，始放满城春。
且醉登楼客，重期出郭人。
因酬郢中律，霜鬓数茎新。','',''),('quantangshi-38778','乱后山中作','杜荀鶴','quantangshi','','卷39','自从天下乱，日晚别庭闱。
兄弟团圞乐，羁孤远近归。
文章甘世薄，耕种喜山肥。
直待中兴后，方应出隐扉。','',''),('quantangshi-38779','旅寓书事','杜荀鶴','quantangshi','','卷39','日日惊身事，凄凄欲断魂。
时清不自立，发白傍谁门。
中路残秋雨，空山一夜猿。
公卿得见面，怀抱细难言。','',''),('quantangshi-38780','舟行晚泊江上寺','杜荀鶴','quantangshi','','卷39','久劳风水上，禅客喜相依。
挂衲虽无分，修心未觉非。
日沈山虎出，钟动寺禽归。
月上潮平后，谈空渐入微。','',''),('quantangshi-38781','长林山中闻贼退寄孟明府','杜荀鶴','quantangshi','','卷39','一县今如此，残民数不多。
也知贤宰切，争奈乱兵何。
皆自干戈达，咸思雨露和。
应怜住山者，头白未登科。','',''),('quantangshi-38782','泗上客思','杜荀鶴','quantangshi','','卷39','痛饮复高歌，愁终不奈何。
家山随日远，身事逐年多。
没雁云横楚，兼蝉柳夹河。
此心闲未得，到处被诗磨。','',''),('quantangshi-38783','寄同人','杜荀鶴','quantangshi','','卷39','尽与贫为患，唯余即不然。
四方无静处，百口度荒年。
白发生闲事，新诗出数联。
时情竟如此，不免却归田。','',''),('quantangshi-38784','下第出关投郑拾遗','杜荀鶴','quantangshi','','卷39','丹霄桂有枝，未折未为迟。
况是孤寒士，兼行苦涩诗。
杏园人醉日，关路独归时。
更卜深知意，将来拟荐谁。','',''),('quantangshi-38785','塞上','杜荀鶴','quantangshi','','卷39','草白河冰合，蕃戎出掠频。
戍楼三号火，探马一条尘。
战士风霜老，将军雨露新。
封侯不由此，何以慰征人。','',''),('quantangshi-38786','别敬侍郎','杜荀鶴','quantangshi','','卷39','交道有寒暑，在人无古今。
与君中夜话，尽我一生心。
所向未得志，岂惟空解吟。
何当重相见，旧隐白云深。','',''),('quantangshi-38787','送青阳李明府','杜荀鶴','quantangshi','','卷39','善政无慙色，吟归似等闲。
惟将六幅绢，写得九华山。
求理头空白，离京债未还。
仍闻猿与鹤，都在一船间。','',''),('quantangshi-38788','将游湘湖有作','杜荀鶴','quantangshi','','卷39','一家相别意，不得不澘然。
远作南方客，初登上水船。
岳钟思冷梦，湘月少残篇。
便有归来计，风波亦隔年。','',''),('quantangshi-38789','送姚庭圭','杜荀鶴','quantangshi','','卷39','脱衣将换酒，对酌话何之。
雨后秋萧索，天涯晚别离。
人生无此恨，鬓色不成丝。
未得重相见，看君马上诗。','',''),('quantangshi-38790','投李大夫','杜荀鶴','quantangshi','','卷39','自小僻于诗，篇篇恨不奇。
苦吟无暇日，华发有多时。
进取门难见，升沈命未知。
秋风夜来急，还恐到京迟。','',''),('quantangshi-38791','贻里中同志','杜荀鶴','quantangshi','','卷39','乡里为儒者，唯君见我心。
诗书常共读，雨雪亦相寻。
贫贱志气在，子孙交契深。
古人犹晚达，况未鬓霜侵。','',''),('quantangshi-38792','江上送韦彖先辈','杜荀鶴','quantangshi','','卷39','不易为离抱，江天即见鸿。
暮帆何处落，凉月与谁同。
木叶新霜后，渔灯夜浪中。
时难慎行止，吾道利于穷。','',''),('quantangshi-38793','维扬逢诗友张乔','杜荀鶴','quantangshi','','卷39','天下方多事，逢君得话诗。
直应吾道在，未觉国风衰。
生计吟消日，人情醉过时。
雅篇三百首，留作后来师。','',''),('quantangshi-38794','秋晨有感','杜荀鶴','quantangshi','','卷39','木叶落时节，旅人初梦惊。
钟才枕上尽，事已眼前生。
吟发不长黑，世交无久情。
且将公道约，未忍便归耕。','',''),('quantangshi-38795','秋日山中寄李处士','杜荀鶴','quantangshi','','卷39','吾辈道何穷，寒山细雨中。
儿童书懒读，果粟树将空。
言论关时务，篇章见国风。
升平犹可用，应不废为公。','',''),('quantangshi-38796','晚泊金陵水亭','杜荀鶴','quantangshi','','卷39','江亭当废国，秋景倍萧骚。
夕照残荒垒，寒潮涨古濠。
就田看鹤劣，隔水见僧高。
无限前朝事，醒吟易觉劳。','',''),('quantangshi-38797','钱塘别罗隐','杜荀鶴','quantangshi','','卷39','故国看看远，前程计在谁。
五更听角后，一叶渡江时。
吾道天宁丧，人情日可疑。
西陵向西望，双泪为君垂。','',''),('quantangshi-38798','山中贻同志','杜荀鶴','quantangshi','','卷39','君贫我亦贫，为善喜为邻。
到老如今日，无心愧古人。
闭门非傲世，守道是谋身。
别有同山者，其如未可亲。','',''),('quantangshi-38799','秋日怀九华旧居','杜荀鶴','quantangshi','','卷39','吾道在五字，吾身宁陆沈。
凉生中夜雨，病起故山心。
烛共寒酸影，蛩添苦楚吟。
何当遂归去，一径入松林。','',''),('quantangshi-38800','江岸秋思','杜荀鶴','quantangshi','','卷39','驱马傍江行，乡愁步步生。
举鞭挥柳色，随手失蝉声。
秋稼缘长道，寒云约古城。
家贫遇丰岁，无地可归耕。','',''),('quantangshi-38801','哭刘德仁','杜荀鶴','quantangshi','','卷39','贾岛还如此，生前不见春。
岂能诗苦者，便是命羁人。
家事因吟失，时情碍国亲。
多应衔恨骨，千古不为尘。','',''),('quantangshi-38802','经青山吊李翰林','杜荀鶴','quantangshi','','卷39','何为先生死，先生道日新。
青山明月夜，千古一诗人。
天地空销骨，声名不傍身。
谁移耒阳冢，来此作吟邻。','',''),('quantangshi-38803','下第东归别友人','杜荀鶴','quantangshi','','卷39','不得同君住，当春别帝乡。
年华落第老，岐路出关长。
芳草缘流水，残花向夕阳。
怀亲暂归去，非是钓沧浪。','',''),('quantangshi-38804','秋宿诗僧云英房因赠','杜荀鶴','quantangshi','','卷39','贾岛怜无可，都缘数句诗。
君虽是后辈，我谓过当时。
溪浪和星动，松阴带鹤移。
同吟到明坐，此道淡谁知。','',''),('quantangshi-38805','送人宰吴县','杜荀鶴','quantangshi','','卷39','海涨兵荒后，为官合动情。
字人无异术，至论不如清。
草履随船卖，绫梭隔水鸣。
唯持古人意，千里赠君行。','',''),('quantangshi-38806','读友人诗','杜荀鶴','quantangshi','','卷39','君诗通大雅，吟觉古风生。
外却浮华景，中含教化情。
名应高日月，道可润公卿。
莫以孤寒耻，孤寒达更荣。','',''),('quantangshi-38807','登山寺','杜荀鶴','quantangshi','','卷39','山半一山寺，野人秋日登。
就中偏爱石，独上最高层。
有果猿攀树，无斋鸽看僧。
儒门自多事，来此复何能。','',''),('quantangshi-38808','辞九江李郎中入关','杜荀鶴','quantangshi','','卷39','帝里无相识，何门迹可亲。
愿开言重口，荐与分深人。
卷许新诗出，家怜旧业贫。
今从九江去，应免更迷津。','',''),('quantangshi-38809','江南逢李先辈','杜荀鶴','quantangshi','','卷39','李杜复李杜，彼时逢此时。
干戈侵帝里，流落向天涯。
岁月消于酒，平生断在诗。
怀才不得志，祗恐满头丝。','',''),('quantangshi-38810','秋日寄吟友','杜荀鶴','quantangshi','','卷39','闲坐细思量，唯吟不可忘。
食无三亩地，衣绝一株桑。
蝉树生寒色，渔潭落晓光。
青云旧知己，未许钓沧浪。','',''),('quantangshi-38811','江上与从弟话别','杜荀鶴','quantangshi','','卷39','相逢尽说归，早晚遂归期。
流水多通处，孤舟少住时。
干人不得已，非我欲为之。
及此终无愧，其如道在兹。','',''),('quantangshi-38812','送友人游南海','杜荀鶴','quantangshi','','卷39','南海南边路，君游祗为贫。
山川多少地，郡邑几何人。
花鸟名皆别，寒暄气不均。
相期早晚见，莫待瘴侵身。','',''),('quantangshi-38813','赠聂尊师','杜荀鶴','quantangshi','','卷39','诗道将仙分，求之不可求。
非关从小学，应是数生修。
蟾桂云梯折，鳌山鹤驾游。
他年两成事，堪喜是邻州。','',''),('quantangshi-38814','旅感','杜荀鶴','quantangshi','','卷39','白发根丛出，镊频愁不开。
自怜空老去，谁信苦吟来。
客路东西阔，家山早晚回。
翻思钓鱼处，一雨一层苔。','',''),('quantangshi-38815','寄益阳武灌明府','杜荀鶴','quantangshi','','卷39','县称诗人理，无嫌日寂寥。
溪山入城郭，户口半渔樵。
月满弹琴夜，花香漉酒朝。
相思不相见，烟水路迢迢。','',''),('quantangshi-38816','湘中秋日呈所知','杜荀鶴','quantangshi','','卷39','四海无寸土，一生惟苦吟。
虚垂异乡泪，不滴别人心。
雨色凋湘树，滩声下塞禽。
求归归未得，不是掷光阴。','',''),('quantangshi-38817','苦吟','杜荀鶴','quantangshi','','卷39','世间何事好，最好莫过诗。
一句我自得，四方人已知。
生应无辍日，死是不吟时。
始拟归山去，林泉道在兹。','',''),('quantangshi-38818','闽中别所知','杜荀鶴','quantangshi','','卷39','触目生归思，那堪路七千。
腊中离此地，马上见明年。
郡邑溪山巧，寒暄日月偏。
自疑双鬓雪，不似到南天。','',''),('quantangshi-38819','塞上伤战士','杜荀鶴','quantangshi','','卷39','战士说辛勤，书生不忍闻。
三边远天子，一命信将军。
野火烧人骨，阴风卷阵云。
其如禁城里，何以重要勋。','',''),('quantangshi-38820','春日访独孤处士','杜荀鶴','quantangshi','','卷39','地僻春来静，深宜长者居。
好花都待晚，修竹不妨疎。
雁入湘江食，人侵晓色锄。
似君无学处，头白道如初。','',''),('quantangshi-38821','哭友人','杜荀鶴','quantangshi','','卷39','病向名场得，终为善误身。
无儿承后嗣，有女托何人。
葬礼难求备，交情好者贫。
惟余旧文集，一览一沾巾。','',''),('quantangshi-38822','新栽竹','杜荀鶴','quantangshi','','卷39','斸破苍苔色，因栽十数茎。
窗风从此冷，诗思当时清。
酒入杯中影，棊添局上声。
不同桃与李，潇洒伴书生。','',''),('quantangshi-38823','送吴蜕下第入蜀','杜荀鶴','quantangshi','','卷39','下第言之蜀，那愁举别杯。
难兄方在幕，上相复怜才。
鸟径盘春霭，龙湫发夜雷。
临邛无久恋，高桂待君回。','',''),('quantangshi-38824','乱后归山','杜荀鶴','quantangshi','','卷39','乱世归山谷，征鼙喜不闻。
诗书犹满架，弟侄未为军。
山犬眠红叶，樵童唱白云。
此心非此志，终拟致明君。','',''),('quantangshi-38825','题着禅师','杜荀鶴','quantangshi','','卷39','大道本无幻，常情自有魔。
人皆迷着此，师独悟如何。
为岳开窗阔，因虫长草多。
说空空说得，空得到维摩。','',''),('quantangshi-38826','春日闲居即事','杜荀鶴','quantangshi','','卷39','未得青云志，春同秋日情。
花开如叶落，莺语似蝉鸣。
道合和贫守，诗堪与命争。
饥寒是吾事，断定不归耕。','',''),('quantangshi-38827','秋宿栖贤寺怀友人','杜荀鶴','quantangshi','','卷39','一宿三秋寺，闲忙与晓分。
细泉山半落，孤客夜深闻。
鹤去巢盛月，龙潜穴拥云。
苦吟方见景，多恨不同君。','',''),('quantangshi-38828','乱后再逢汪处士','杜荀鶴','quantangshi','','卷39','如君真道者，乱世有闲情。
每别不知处，见来长后生。
药非因病服，酒不为愁倾。
笑我于身苦，吟髭白数茎。','',''),('quantangshi-38829','山中喜与故交宿话','杜荀鶴','quantangshi','','卷39','远地能相访，何慙事力微。
山中深夜坐，海内故交稀。
村酒沽来浊，溪鱼钓得肥。
贫家只如此，未可便言归。','',''),('quantangshi-38830','观碁','杜荀鶴','quantangshi','','卷39','对面不相见，用心同用兵。
算人常欲杀，顾己自贪生。
得势侵吞远，乘危打劫赢。
有时逢敌手，当局到深更。','',''),('quantangshi-38831','送人宰德清','杜荀鶴','quantangshi','','卷39','乱世人多事，耕桑或失时。
不闻宽赋敛，因此转流离。
天意未如是，君心无自欺。
能依四十字，可立德清碑。','',''),('quantangshi-38832','寄窦处士','杜荀鶴','quantangshi','','卷39','漳水醉中别，今来犹未醒。
半生因酒废，大国几时宁。
海畔将军柳，天边处士星。
游人不可见，春入乱山青。','',''),('quantangshi-38833','题历山舜祠','杜荀鶴','quantangshi','','卷39','昔舜曾耕地，遗风日寂寥。
世人那肯祭，大圣不兴妖。
殿宇秋霖坏，杉松野火烧。
时讹竞淫祀，丝竹醉山魈。','',''),('quantangshi-38834','赠李蒙叟','杜荀鶴','quantangshi','','卷39','在我成何事，逢君更劝吟。
纵饶不得力，犹胜别劳心。
凡事有兴废，诗名无古今。
百年能几日，忍不惜光阴。','',''),('quantangshi-38835','维扬冬末寄幕中二从事','杜荀鶴','quantangshi','','卷39','闻道长溪尉，相留一馆闲。
□□□□□，尚隔几重山。
为旅春风外，怀人夜雨间。
年来疎览镜，怕见减朱颜。','',''),('quantangshi-38836','和吴太守罢郡山村偶题二首 一','杜荀鶴','quantangshi','','卷39','罢郡饶山兴，村家不惜过。
官情随日薄，诗思入秋多。
野兽眠低草，池禽浴动荷。
眼前余政在，不似有干戈。','',''),('quantangshi-38837','和吴太守罢郡山村偶题二首 二','杜荀鶴','quantangshi','','卷39','快活田翁辈，常言化育时。
纵饶稽岁月，犹说向孙儿。
茅屋梁和节，茶盘果带枝。
相传终不忘，何必立生祠。','',''),('quantangshi-38838','乱后送友人归湘中','杜荀鶴','quantangshi','','卷39','家枕三湘岸，门前即钓矶。
渔竿壮岁别，鹤发乱时归。
岳暖无猿叫，江春有燕飞。
平生书劒在，莫便学忘机。','',''),('quantangshi-38839','送紫阳僧归庐岳旧寺','杜荀鶴','quantangshi','','卷39','紫衣明主赠，归寺感先师。
受业恩难报，开堂影不知。
松风欹枕夜，山雪下楼时。
此际无人会，微吟复歛眉。','',''),('quantangshi-38840','和刘评事送海禅和归山','杜荀鶴','quantangshi','','卷39','衲外元无象，言寻那路寻。
问禅将底说，传印得何心。
未了羣山浅，难休一室深。
伏魔宁是兽，巢顶亦非禽。
观色风驱雾，听声雪洒林。
凡归是归处，不必指高岑。','',''),('quantangshi-38841','御沟柳','杜荀鶴','quantangshi','','卷39','律到御沟春，沟边柳色新。
细笼穿禁水，轻拂入朝人。
日近韶光早，天低圣泽匀。
谷莺栖未稳，宫女画难真。
楚国空摇浪，隋堤暗惹尘。
如何帝城里，先得覆龙津。','',''),('quantangshi-38842','冬末同友人泛潇湘','杜荀鶴','quantangshi','','卷39','残腊泛舟何处好，最多吟兴是潇湘。
就船买得鱼偏美，踏雪沽来酒倍香。
猿到夜深啼岳麓，雁知春近别衡阳。
与君剩采江山景，裁取新诗入帝乡。','',''),('quantangshi-38843','赠李镡','杜荀鶴','quantangshi','','卷39','君行君文天合知，见君如此我兴悲。
秪残三口兵戈后，才到孤村雨雪时。
着卧衣裳难办洗，旋求粮食莫供炊。
地炉不暖柴枝湿，犹把蒙求授小儿。','',''),('quantangshi-38844','旅中卧病','杜荀鶴','quantangshi','','卷39','秋来谁料病相萦，枕上心犹算去程。
风射破窗灯易灭，月穿疎屋梦难成。
故园何啻三千里，新雁才闻一两声。
我自与人无旧分，非干人与我无情。','',''),('quantangshi-38845','旅泊遇郡中叛乱示同志','杜荀鶴','quantangshi','','卷39','握手相看谁敢言，军家刀劒在腰边。
遍搜宝货无藏处，乱杀平人不怕天。
古寺拆为修寨木，荒坟开作甃城塼。
郡侯逐出浑闲事，正是銮舆幸蜀年。','',''),('quantangshi-38846','赠秋浦张明府','杜荀鶴','quantangshi','','卷39','君为秋浦三年宰，万虑关心两鬓知。
人事旋生当路县，吏才难展用兵时。
农夫背上题军号，贾客船头插战旗。
他日亲知问官况，但教吟取杜家诗。','',''),('quantangshi-38847','雪','杜荀鶴','quantangshi','','卷39','风搅长空寒骨生，光于晓色报窗明。
江湖不见飞禽影，岩谷时闻折竹声。
巢穴几多相似处，路岐兼得一般平。
拥袍公子休言冷，中有樵夫跣足行。','',''),('quantangshi-38848','题庐岳刘处士草堂','杜荀鶴','quantangshi','','卷39','仙境闲寻采药翁，草堂留话一宵同。
若看山下云深处，直是人间路不通。
泉领藕花来洞口，月将松影过溪东。
求名心在闲难遂，明日马蹄尘土中。','',''),('quantangshi-38849','山中寄诗友','杜荀鶴','quantangshi','','卷39','山深长恨少同人，览景无时不忆君。
庭果自从霜后熟，野猿频向屋边闻。
琴临秋水弹明月，酒就东山酌白云。
仙桂算攀攀合得，平生心力尽于文。','',''),('quantangshi-38850','秋宿临江驿','杜荀鶴','quantangshi','','卷39','南来北去二三年，年去年来两鬓斑。
举世尽从愁里老，谁人肯向死前闲。
渔舟火影寒归浦，驿路铃声夜过山。
身事未成归未得，听猿鞭马入长关。','',''),('quantangshi-38851','题瓦棺寺真上人院矮桧','杜荀鶴','quantangshi','','卷39','天生仙桧是长材，栽桧希逢此最低。
一自旧山来砌畔，几番凡木与云齐。
回无斜影教僧踏，免有闲枝引鹤栖。
今日偶题题似着，不知题后更谁题。','',''),('quantangshi-38852','江下初秋寓泊','杜荀鶴','quantangshi','','卷39','蒙蒙烟雨蔽江村，江馆愁人好断魂。
自别家来生白发，为侵星起谒朱门。
也知柳欲开春眼，争奈萍无入土根。
兄弟无书雁归北，一声声觉苦于猿。','',''),('quantangshi-38853','投从叔补阙','杜荀鶴','quantangshi','','卷39','吾宗不谒谒诗宗，常仰门风继国风。
空有篇章传海内，更无亲族在朝中。
其来虽愧源流浅，所得须怜雅颂同。
三十年吟到今日，不妨私荐亦成公。','',''),('quantangshi-38854','赠张员外儿','杜荀鶴','quantangshi','','卷39','张公一子才三岁，闻客吟声便出来。
唤物舌头犹未稳，诵诗心孔迥然开。
天生便是成家庆，年长终为间世才。
月里桂枝知有分，不劳诸丈作梯媒。','',''),('quantangshi-38855','重阳日有作','杜荀鶴','quantangshi','','卷39','一为重阳上古台，乱时谁见菊花开。
偷𢸧白发真堪笑，牢鏁黄金实可哀。
是个少年皆老去，争知荒冢不荣来。
大家拍手高声唱，日未沈山且莫回。','',''),('quantangshi-38856','入关寄九华友人','杜荀鶴','quantangshi','','卷39','坐牀难稳露蝉新，便作东西马上身。
醲酒却输耽睡客，好山翻对不吟人。
无多志气禁离别，强半年光属苦辛。
箧里篇章头上雪，未知谁恋杏园春。','',''),('quantangshi-38857','送李镡游新安','杜荀鶴','quantangshi','','卷39','邯郸李镡才峥嵘，酒狂诗逸难干名。
气直不与儿辈洽，醉来拟共天公争。
孤店夜烧枯叶坐，乱时秋踏早霜行。
一间茅屋住不稳，刚出为人平不平。','',''),('quantangshi-38858','冬末自长沙游桂岭留献所知','杜荀鶴','quantangshi','','卷39','家隔重湖归未期，更堪南去别深知。
前程笑到山多处，上马愁逢岁尽时。
四海内无容足地，一生中有苦心诗。
朱门秪见朱门事，独把孤寒问阿谁。','',''),('quantangshi-38859','送福昌周繇少府归宁兼谋隐','杜荀鶴','quantangshi','','卷39','少见古人无远虑，如君真得古人情。
登科作尉官虽小，避世安亲禄已荣。
一路水云生隐思，几山猿鸟认吟声。
知君未作终焉计，要着文章待太平。','',''),('quantangshi-38860','贺顾云侍御府主与子弟奏官','杜荀鶴','quantangshi','','卷39','青桂朱袍不贺兄，贺兄荣是见儿荣。
孝经始向堂前彻，官诰当从幕下迎。
戏把蓝袍包果子，娇将竹笏恼先生。
自慙乱世无知己，弟侄鞭牛傍陇耕。','',''),('quantangshi-38861','舟行即事','杜荀鶴','quantangshi','','卷39','年少髭须雪欲侵，别家三日几般心。
朝随贾客忧风色，夜逐渔翁宿苇林。
秋水鹭飞红蓼晚，暮山猿叫白云深。
重阳酒熟茱萸紫，却向江头倚棹吟。','',''),('quantangshi-38862','乱后山居','杜荀鶴','quantangshi','','卷39','从乱移家拟傍山，今来方办买山钱。
九州有路休为客，百岁无愁即是仙。
野叟竝田锄暮雨，溪禽同石立寒烟。
他人似我还应少，如此安贫亦荷天。','',''),('quantangshi-38863','山居寄同志','杜荀鶴','quantangshi','','卷39','茅斋深僻绝轮蹄，门径缘莎细接溪。
垂钓石台依竹垒，待宾茶竈就岩泥。
风生谷口猿相叫，月照松头鹤竝栖。
不是无端过时日，拟从窗下蹑云梯。','',''),('quantangshi-38864','将入关安陆遇兵寇','杜荀鶴','quantangshi','','卷39','家贫无计早离家，离得家来蹇滞多。
已是数程行雨雪，更堪中路阻兵戈。
几州户口看成血，一旦天心却许和。
四面烟尘少无处，不知吾土自如何。','',''),('quantangshi-38865','夏日登友人书斋林亭','杜荀鶴','quantangshi','','卷39','暑天长似秋天冷，带郭林亭画不如。
蝉噪槛前遮日竹，鹭窥池面弄萍鱼。
抛山野客横琴醉，种药家僮踏雪锄。
众惜君才堪上第，莫因居此与名疎。','',''),('quantangshi-38866','寄临海姚中丞','杜荀鶴','quantangshi','','卷39','夏辞旌斾已秋深，永夕思量泪满襟。
风月易斑搜句鬓，星霜难改感恩心。
寻花洞里连春醉，望海楼中彻晓吟。
虽有梦魂知处所，去来多被角声侵。','',''),('quantangshi-38867','秋日闲居寄先达','杜荀鶴','quantangshi','','卷39','到头身事欲何为，窗下工夫鬓上知。
乍可百年无称意，难教一日不吟诗。
风驱早雁冲湖色，雨挫残蝉点柳枝。
自古书生也如此，独堪惆怅是明时。','',''),('quantangshi-38868','题觉禅和','杜荀鶴','quantangshi','','卷39','少见修行得似师，茅堂佛像亦随时。
禅衣衲后云藏线，夏腊高来雪印眉。
耕地诫侵连冢土，伐薪教护带巢枝。
有时问着经中事，却道山僧总不知。','',''),('quantangshi-38869','感秋','杜荀鶴','quantangshi','','卷39','年年名路谩辛勤，襟袖空多马上尘。
画戟门前难作客，钓鱼船上易安身。
冷烟黏柳蝉声老，寒渚澄星雁叫新。
自是侬家无住处，不关天地窄于人。','',''),('quantangshi-38870','题德玄上人院','杜荀鶴','quantangshi','','卷39','刳得心来忙处闲，闲中方寸阔于天。
浮生自是无空性，长寿何曾有百年。
罢定磬敲松罅月，解眠茶煮石根泉。
我虽未似师披衲，此理同师悟了然。','',''),('quantangshi-38871','春日山居寄友人','杜荀鶴','quantangshi','','卷39','野吟何处最相宜，春景暄和好入诗。
高下麦苗新雨后，浅深山色晚晴时。
半岩云脚风牵断，平野花枝鸟踏垂。
倒载干戈是何日，近来麋鹿欲相随。','',''),('quantangshi-38872','怀庐岳旧隐','杜荀鶴','quantangshi','','卷39','一别三年长在梦，梦中时蹑石棱层。
泉声入夜方堪听，山色逢秋始好登。
岩鹿惯随锄药叟，溪鸥不怕洗苔僧。
人间有许多般事，求要身闲直未能。','',''),('quantangshi-38873','投长沙裴侍郎','杜荀鶴','quantangshi','','卷39','此身虽贱道长存，非谒朱门谒孔门。
秪望至公将卷读，不求朝士致书论。
垂纶雨结渔乡思，吹木风传雁夜魂。
男子受恩须有地，平生不受等闲恩。','',''),('quantangshi-38874','和友人见题山居','杜荀鶴','quantangshi','','卷39','避时多喜葺居成，七字君题万象清。
开户晓云连地白，访人秋月满山明。
庭前树瘦霜来影，洞口泉喷雨后声。
有景供吟且如此，算来何必躁于名。','',''),('quantangshi-38875','献长沙王侍郎','杜荀鶴','quantangshi','','卷39','文星渐见射台星，皆仰为霖沃众情。
天泽逼来逢圣主，辞林盛去得书生。
云妆岳色供吟景，月浩湘流递政声。
美化事多难讽诵，未如耕钓口分明。','',''),('quantangshi-38876','春日登楼遇雨','杜荀鶴','quantangshi','','卷39','忽地晴天作雨天，全无暑气似秋间。
看看水没来时路，渐渐云藏望处山。
风趁鹭鸶双出苇，浪催渔父尽归湾。
一心准拟闲登眺，却被诗情使不闲。','',''),('quantangshi-38877','春日行次钱塘却寄台州姚中丞','杜荀鶴','quantangshi','','卷39','岂为无心求上第，难安帝里为家贫。
江南江北闲为客，潮去潮来老却人。
两岸雨收莺语柳，一楼风满角吹春。
花前不独垂乡泪，曾是朱门寄食身。','',''),('quantangshi-38878','投江上崔尚书','杜荀鶴','quantangshi','','卷39','此生何路出尘埃，犹把中才谒上才。
闭户十年专笔砚，仰天无处认梯媒。
马前霜叶催归去，枕上边鸿唤觉来。
若许登门换鬐鬣，必应辛苦事风雷。','',''),('quantangshi-38879','书事投所知','杜荀鶴','quantangshi','','卷39','古陌寒风来去吹，马蹄尘旋上麻衣。
虽然干禄无休意，争奈趋时不见机。
诗思趁云从岳涌，乡心随雁遶湖飞。
肯将骨肉轻离别，未遇人知未得归。','',''),('quantangshi-38880','秋日湖外书事','杜荀鶴','quantangshi','','卷39','十五年来笔砚功，秪今犹在苦贫中。
三秋客路湖光外，万里乡关楚邑东。
鸟迳杖藜山翳雨，猿林欹枕树摇风。
朱门处处若相似，此命到头通不通。','',''),('quantangshi-38881','题宗上人旧院','杜荀鶴','quantangshi','','卷39','此院重来事事乖，半欹茅屋草侵堦。
啄生鸦忆啼松枿，接果猿思啸石崖。
壁上尘黏蒲叶扇，牀前苔烂笋皮鞋。
分明记得谈空日，不向秋风更怆怀。','',''),('quantangshi-38882','乱后出山逢高员外','杜荀鶴','quantangshi','','卷39','自从乱后别京关，一入烟萝十五年。
重出故山生白发，却装新卷谒清贤。
窗回旅梦城头角，柳结乡愁雨后蝉。
名姓暗投心暗祝，永期收拾向门前。','',''),('quantangshi-38883','赠友人罢举赴交趾辟命','杜荀鶴','quantangshi','','卷39','罢却名场拟入秦，南行无罪似流人。
纵经商岭非驰驿，须过长沙吊逐臣。
舶载海奴镮硾耳，象驼蛮女彩缠身。
如何待取丹霄桂，别赴嘉招作上宾。','',''),('quantangshi-38884','山中寡妇','杜荀鶴','quantangshi','','卷39','夫因兵死守蓬茅，麻苎衣衫鬓发焦。
桑柘废来犹纳税，田园荒后尚征苗。
时挑野菜和根煮，旋斫生柴带叶烧。
任是深山更深处，也应无计避征徭。','',''),('quantangshi-38885','访蔡融因题','杜荀鶴','quantangshi','','卷39','杖藜时复过荒郊，来到君家不忍抛。
每见苦心修好事，未尝开口怨平交。
一溪寒色渔收网，半树斜阳鸟傍巢。
必若天工主人事，肯交吾子委衡茅。','',''),('quantangshi-38886','闲居书事','杜荀鶴','quantangshi','','卷39','竹门茅屋带村居，数亩生涯自有余。
鬓白祗应秋炼句，眼昏多为夜抄书。
雁惊风浦渔灯动，猿叫霜林橡实疎。
待得功成即西去，时清不问命何如。','',''),('quantangshi-38887','友人赠舍弟依韵戏和','杜荀鶴','quantangshi','','卷39','吾家此弟有何知，多愧君开道业基。
不觉裹头成大汉，昨来竹马作童儿。
还缘世遇兵戈闹，祗恐身修礼乐迟。
及见和诗诗自好，碢公不到更何时。','',''),('quantangshi-38888','乱后逢村叟','杜荀鶴','quantangshi','','卷39','经乱衰翁居破村，村中何事不伤魂。
因供寨木无桑柘，为着乡兵绝子孙。
还似平宁征赋税，未尝州县畧安存。
至于鸡犬皆星散，日落前山独倚门。','',''),('quantangshi-38889','赠元上人','杜荀鶴','quantangshi','','卷39','多少僧中僧行高，偈成流落遍僧抄。
经窗月静滩声到，石迳人稀藓色交。
垂露竹黏蝉落壳，窣云松载鹤栖巢。
煮茶童子闲胜我，犹得依时把磬敲。','',''),('quantangshi-38890','下第东归道中作','杜荀鶴','quantangshi','','卷39','一回落第一宁亲，多是途中过却春。
心火不销双鬓雪，眼泉难濯满衣尘。
苦吟风月唯添病，遍识公卿未免贫。
马壮金多有官者，荣归却笑读书人。','',''),('quantangshi-38891','夏日留题张山人林亭','杜荀鶴','quantangshi','','卷39','此中偏称夏中游，时有风来暑气收。
涧底松摇千尺雨，庭中竹撼一窗秋。
求猿句寄山深寺，乞鹤书传海畔洲。
闲与先生话身事，浮名薄宦总悠悠。','',''),('quantangshi-38892','伤病马','杜荀鶴','quantangshi','','卷39','此马堪怜力壮时，细匀行步恐尘知。
骑来未省将鞭触，病后长教觅药医。
顾主强抬和泪眼，就人轻刷带疮皮。
祗今筋骨浑全在，春暖莎青放未迟。','',''),('quantangshi-38893','馆舍秋夕','杜荀鶴','quantangshi','','卷39','寒雨萧萧灯焰青，灯前孤客难为情。
兵戈闹日别乡国，鸿雁过时思弟兄。
冷极睡无离枕梦，苦多吟有彻云声。
出门便作还家计，直至如今计未成。','',''),('quantangshi-38894','送僧赴黄山沐汤泉兼参禅宗长老','杜荀鶴','quantangshi','','卷39','闻有汤泉独去寻，一瓶一钵一无金。
不愁乱世兵相害，却喜寒山路入深。
野老祷神鸦噪庙，猎人冲雪鹿惊林。
患身是幻逢禅主，水洗皮肤语洗心。','',''),('quantangshi-38895','哭山友','杜荀鶴','quantangshi','','卷39','十载同栖庐岳云，寒烧枯叶夜论文。
在生未识公卿面，至死不离麋鹿羣。
从见蓬蒿丛坏屋，长忧雨雪透荒坟。
把君诗句高声读，想得天高也合闻。','',''),('quantangshi-38896','献池州牧','杜荀鶴','quantangshi','','卷39','池阳今日似渔阳，大变凶年作小康。
江路静来通客货，郡城安后绝戎装。
分开野色收新麦，惊断莺声摘嫩桑。
纵有逋民归未得，远闻仁政旋还乡。','',''),('quantangshi-38897','送韦书记归京','杜荀鶴','quantangshi','','卷39','韦杜相逢眼自明，事连恩地倍牵情。
闻归帝里愁攀送，知到师门话姓名。
朝客半修前辈礼，古人多重晚年荣。
从来有泪非无泪，未似今朝泪满缨。','',''),('quantangshi-38898','献郑给事','杜荀鶴','quantangshi','','卷39','化行邦域二年春，樵唱渔歌日日新。
未降诏书酬善政，不知天泽答何人。
秋登岳寺云随步，夜宴江楼月满身。
他日朱门恐难扫，沙堤新筑必无尘。','',''),('quantangshi-38899','赠休禅和','杜荀鶴','quantangshi','','卷39','为僧难得不为僧，僧戒僧仪未是能。
弟子自知心了了，吾师应为醉腾腾。
多生觉悟非关衲，一点分明不在灯。
祗道诗人无佛性，长将二雅入三乘。','',''),('quantangshi-38900','送李先辈从知塞上','杜荀鶴','quantangshi','','卷39','去草军书出帝乡，便从城外学戎装。
好随汉将收胡土，莫遣胡兵近汉疆。
洒碛雪黏旗力重，冻河风揭角声长。
此行也是男儿事，莫向征人恃桂香。','',''),('quantangshi-38901','和友人送弟','杜荀鶴','quantangshi','','卷39','君说无家祗弟兄，此中言别若为情。
干戈闹日分头去，山水寒时信路行。
月下断猿空有影，雪中孤雁却无声。
我今骨肉虽饥冻，幸喜团圆过乱兵。','',''),('quantangshi-38902','酬张员外见寄','杜荀鶴','quantangshi','','卷39','分应天与吟诗老，如此兵戈不废诗。
生在世间人不识，死于泉下鬼应知。
啼花蜀鸟春同苦，叫雪巴猿昼共饥。
今日逢君惜分手，一枝何校一年迟。','',''),('quantangshi-38903','献新安于尚书','杜荀鶴','quantangshi','','卷39','九土雄师竟若何，未如良牧与天和。
月留清俸资家少，岁计阴功及物多。
四野绿云笼稼穑，千山明月静干戈。
行人耳满新安事，尽是无愁父老歌。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-38904','乱后书事寄同志','杜荀鶴','quantangshi','','卷39','九土如今尽用兵，短戈长戟困书生。
思量在世头堪白，画度归山计未成。
皇泽正霑新将士，侯门不是旧公卿。
到头诗卷须藏却，各向渔樵混姓名。','',''),('quantangshi-38905','中山临上人院观牡丹寄诸从事','杜荀鶴','quantangshi','','卷39','闲来吟遶牡丹丛，花艳人生事畧同。
半雨半风三月内，多愁多病百年中。
开当韶景何妨好，落向僧家即是空。
一境别无唯此有，忍教醒坐对支公。','',''),('quantangshi-38906','投宣谕张侍郎乱后遇毗陵','杜荀鶴','quantangshi','','卷39','此生今日似前生，重着麻衣特地行。
经乱后囊新卷轴，出山来见旧公卿。
雨笼蛬壁吟灯影，风触蝉枝噪浪声。
闻道中兴重人物，不妨西去马蹄轻。','',''),('quantangshi-38907','下第投所知','杜荀鶴','quantangshi','','卷39','落第愁生晓鼓初，地寒才薄欲何如。
不辞更写公卿卷，却是难修骨肉书。
御苑早莺啼暖树，钓乡春水浸贫居。
拟离门馆东归去，又恐重来事转疎。','',''),('quantangshi-38908','哭方干','杜荀鶴','quantangshi','','卷39','何言寸禄不沾身，身没诗名万古存。
况有数篇关教化，得无余庆及儿孙。
渔樵共垒坟三尺，猿鹤同栖月一村。
天下未宁吾道丧，更谁将酒酹吟魂。','',''),('quantangshi-38909','秋日泊浦江','杜荀鶴','quantangshi','','卷39','一帆程歇九秋时，漠漠芦花拂浪飞。
寒浦更无船竝宿，暮山时见鸟双归。
照云烽火惊离抱，剪叶风霜逼暑衣。
江月渐明汀露湿，静驱吟魄入玄微。','',''),('quantangshi-38910','白发吟','杜荀鶴','quantangshi','','卷39','一茎两茎初似丝，不妨惊度少年时。
几人乱世得及此，今我满头何足悲。
九转灵丹那胜酒，五音清乐未如诗。
家山苍翠万余尺，藜杖楮冠输老儿。','',''),('quantangshi-38911','下第寄池州郑员外','杜荀鶴','quantangshi','','卷39','省出蓬蒿修谒初，蒙知曾不见生疎。
侯门数处将书荐，帝里经年借宅居。
未必有诗堪讽诵，祗怜无援过吹嘘。
如今足得成持取，莫使江湖却钓鱼。','',''),('quantangshi-38912','塞上','杜荀鶴','quantangshi','','卷39','旌旗鬣鬣汉将军，闲出巡边帝命新。
沙塞旋收饶帐幕，犬戎时杀少烟尘。
冰河夜渡偷来马，雪岭朝飞猎去人。
独作书生疑不稳，软弓轻劒也随身。','',''),('quantangshi-38913','赠题兜率寺闲上人院','杜荀鶴','quantangshi','','卷39','人间寺应诸天号，真行僧禅此寺中。
百岁有涯头上雪，万般无染耳边风。
挂帆波浪惊心白，上马尘埃翳眼红。
毕竟浮生谩劳役，算来何事不成空。','',''),('quantangshi-38914','别四明钟尚书','杜荀鶴','quantangshi','','卷39','九华天际碧嵯峨，无奈春来入梦何。
难与英雄论教化，却思猿鸟共烟萝。
风前柳态闲时少，雨后花容淡处多。
都大人生有离别，且将诗句代离歌。','',''),('quantangshi-38915','题护国大师塔','杜荀鶴','quantangshi','','卷39','莫认双林是佛林，禅栖无地亦无金。
塔前尽礼灰来相，衲下谁宗印了心。
笠象胤明双不见，线源分派寸难寻。
吾师觉路余知处，大藏经门一夜吟。','',''),('quantangshi-38916','春日山中对雪有作','杜荀鶴','quantangshi','','卷39','竹树无声或有声，霏霏漠漠散还凝。
岭梅谢后重妆蘂，岩水铺来却结冰。
牢系鹿儿防猎客，满添茶鼎候吟僧。
好将膏雨同功力，松径莓苔又一层。','',''),('quantangshi-38917','山中对雪有作','杜荀鶴','quantangshi','','卷39','一浑干坤万象收，唯应不壅大江流。
虎狼遇猎难藏迹，松柏因风易举头。
玉帐英雄携妓赏，山村鸟雀共民愁。
岂堪久蔽苍苍色，须放三光照九州。','',''),('quantangshi-38918','戏题王处士书斋','杜荀鶴','quantangshi','','卷39','先生高兴似樵渔，水鸟山猿一处居。
石径可行苔色厚，钓竿时斫竹丛疎。
欺春祗爱和醅酒，讳老犹看夹注书。
莫道无金空有寿，有金无寿欲何如。','',''),('quantangshi-38919','早发','杜荀鶴','quantangshi','','卷39','东窗未明尘梦苏，呼童结束登征途。
落叶铺霜马蹄滑，寒猿啸月人心孤。
时逆帽檐风刮顶，旋呵鞭手冻粘须。
青云快活一未见，争得安闲钓五湖。','',''),('quantangshi-38920','题仇处士郊居','杜荀鶴','quantangshi','','卷39','江南景簇此林亭，手板蓝裾自可轻。
洞里客来无俗话，郭中人到有公情。
闲敲岩果呼猿接，时钓溪鱼引鹤争。
笑我有诗三百首，马蹄红日急于名。','',''),('quantangshi-38921','依韵次同年张曙先辈见寄之什','杜荀鶴','quantangshi','','卷39','天上诗名天下传，引来齐列玉皇前。
大仙录后头无雪，至药成来竈绝烟。
笑蹑紫云金作阙，梦抛尘世铁为船。
九华山叟惊凡骨，同到蓬莱岂偶然。','',''),('quantangshi-38922','乱后逢李昭象叙别','杜荀鶴','quantangshi','','卷39','李生李生何所之，家山窣云胡不归。
兵戈到处弄性命，礼乐向人生是非。
却与野猿同橡坞，还将溪鸟共渔矶。
也知不是男儿事，争奈时情贱布衣。','',''),('quantangshi-38923','晚春寄同年张曙先辈','杜荀鶴','quantangshi','','卷39','莫将时态破天真，祗合高歌醉过春。
易落好花三个月，难留浮世百年身。
无金润屋浑闲事，有酒扶头是了人。
恩地未酬闲未得，一回醒话一沾巾。','',''),('quantangshi-38924','长安春感','杜荀鶴','quantangshi','','卷39','出京无计住京难，深入东风转索然。
满眼有花寒食下，一家无信楚江边。
此时晴景愁于雨，是处莺声苦却蝉。
公道算来终达去，更从今日望明年。','',''),('quantangshi-38925','登灵山水阁贻钓者','杜荀鶴','quantangshi','','卷39','江上见僧谁是了，修斋补衲日劳身。
未胜渔父闲垂钓，独背斜阳不采人。
纵有风波犹得睡，总无蓑笠始为贫。
瓦瓶盛酒瓷瓯酌，荻浦芦湾是要津。','',''),('quantangshi-38926','赠溧水崔少府','杜荀鶴','quantangshi','','卷39','庭户萧条燕雀喧，日高窗下枕书眠。
祗闻留客教沽酒，未省逢人说料钱。
洞口礼星披鹤氅，溪头吟月上渔船。
九华山叟心相许，不计官卑赠一篇。','',''),('quantangshi-38927','读张仆射诗','杜荀鶴','quantangshi','','卷39','秋吟一轴见心胷，万象搜罗咏欲空。
才大却嫌天上桂，世危翻立阵前功。
廉颇解武文无说，谢朓能文武不通。
双美总输张太守，二南章句六钧弓。','',''),('quantangshi-38928','题所居村舍','杜荀鶴','quantangshi','','卷39','家随兵尽屋空存，税额宁容减一分。
衣食旋营犹可过，赋输长急不堪闻。
蚕无夏织桑充寨，田废春耕犊劳军。
如此数州谁会得，杀民将尽更邀勋。','',''),('quantangshi-38929','献钱塘县罗着作判官','杜荀鶴','quantangshi','','卷39','还乡夫子遇贤侯，抚字情知不自由。
莫把一名专懊恼，放教双眼绝冤讐。
猩袍懒着辞公宴，鹤氅闲披访道流。
犹有九华知己在，羡君高卧早回头。','',''),('quantangshi-38930','遣怀','杜荀鶴','quantangshi','','卷39','驱驰岐路共营营，祗为人间利与名。
红杏园中终拟醉，白云山下懒归耕。
题桥每念相如志，佩印当期季子荣。
谩道彊亲堪倚赖，到头须是有前程。','',''),('quantangshi-38931','长安道中有作','杜荀鶴','quantangshi','','卷39','回头不忍看羸僮，一路行人我最穷。
马迹蹇于槐影里，钓船抛在月明中。
帽檐晓滴淋蝉露，衫袖时飘卷雁风。
子细寻思底模样，腾腾又过玉关东。','',''),('quantangshi-38932','题开元寺门合','杜荀鶴','quantangshi','','卷39','一登高阁眺清秋，满目风光尽胜游。
何处画桡寻绿水，几家鸣笛咽红楼。
云山已老应长在，岁月如波祗暗流。
唯有禅居离尘俗，了无荣辱挂心头。','',''),('quantangshi-38933','出关投孙侍御','杜荀鶴','quantangshi','','卷39','东归还着旧麻衣，争免花前有泪垂。
每岁春光九十日，一生年少几多时。
青云寸禄心耕早，明月仙枝分种迟。
不为感恩酬未得，五湖闲作钓鱼师。','',''),('quantangshi-38934','送项山人归天台','杜荀鶴','quantangshi','','卷39','因话天台归思生，布囊藤杖笑离城。
不教日月拘身事，自与烟萝结野情。
龙镇古潭云色黑，露淋秋桧鹤声清。
此中是处堪终隐，何要世人知姓名。','',''),('quantangshi-38935','题衡阳隐士山居','杜荀鶴','quantangshi','','卷39','闲居不问世如何，云起山门日已斜。
放鹤去寻三岛客，任人来看四时花。
松醪腊酝安神酒，布水宵煎觅句茶。
毕竟金多也头白，算来争得似君家。','',''),('quantangshi-38936','题江寺禅和','杜荀鶴','quantangshi','','卷39','江寺禅僧似悟禅，坏衣芒履住茅轩。
懒求施主修真像，翻说经文是妄言。
出浦钓船惊宿雁，伐岩樵斧迸寒猿。
行人莫问师宗旨，眼不浮华耳不喧。','',''),('quantangshi-38937','题弟侄书堂','杜荀鶴','quantangshi','','卷39','何事居穷道不穷，乱时还与静时同。
家山虽在干戈地，弟侄常修礼乐风。
窗竹影摇书案上，野泉声入砚池中。
少年辛苦终身事，莫向光阴惰寸功。','',''),('quantangshi-38938','和友人寄长林孟明府','杜荀鶴','quantangshi','','卷39','为政为人渐见心，长才聊屈宰长林。
莫嫌月入无多俸，须喜秋来不废吟。
寒雨旋疎丛菊艳，晚风时动小松阴。
讼庭闲寂公书少，留客看山索酒斟。','',''),('quantangshi-38939','戏赠渔家','杜荀鶴','quantangshi','','卷39','见君生计羡君闲，求食求衣有底难。
养一箔蚕供钓线，种千茎竹作渔竿。
葫芦杓酌春浓酒，舴艋舟流夜涨滩。
却笑农家最辛苦，听蝉鞭马入长安。','',''),('quantangshi-38940','登城有作','杜荀鶴','quantangshi','','卷39','上得孤城向晚春，眼前何事不伤神。
遍看原上累累冢，曾是城中汲汲人。
尽谓黄金堪润屋，谁思荒骨旋成尘。
一名一宦平生事，不放愁侵易过身。','',''),('quantangshi-38941','秋日山中寄池州李常侍','杜荀鶴','quantangshi','','卷39','近来参谒陡生疎，因向云山僻处居。
出为羁孤营粝食，归同弟侄读生书。
风凋古木秋阴薄，月满寒山夜景虚。
但得中兴知己在，算应身未老樵渔。','',''),('quantangshi-38942','辞杨侍郎','杜荀鶴','quantangshi','','卷39','春在门阑秋未离，不因人荐只因诗。
半年宾馆成前事，一日侯门失旧知。
霜岛树凋猿叫夜，湖田谷熟雁来时。
西风万里东归去，更把愁心说向谁。','',''),('quantangshi-38943','题汪氏茅亭','杜荀鶴','quantangshi','','卷39','茅亭客到多称奇，茅亭之上难题诗。
出尘景物不可状，小手篇章徒尔为。
牛畔稻苗新雨后，鹤边松韵晚风时。
君今酷爱人间事，争得安闲老在兹。','',''),('quantangshi-38944','喜从弟雪中远至有作','杜荀鶴','quantangshi','','卷39','深山大雪懒开门，门迳行踪自尔新。
无酒御寒虽寡况，有书供读且资身。
便均情爱同诸弟，莫更生疎似外人。
昼短夜长须强学，学成贫亦胜他贫。','',''),('quantangshi-38945','送僧归国清寺','杜荀鶴','quantangshi','','卷39','吟送越僧归海涯，僧行浑不觉程赊。
路沿山脚潮痕出，睡倚松根日色斜。
撼锡度冈猿抱树，挈瓶盛浪鹭翘沙。
到参禅后知无事，看引秋泉灌藕花。','',''),('quantangshi-38946','题汪明府山居','杜荀鶴','quantangshi','','卷39','不似当官祗似闲，野情终日不离山。
方知薄宦难拘束，多与高人作往还。
牛笛漫吹烟雨里，稻苗平入水云间。
羡君公退归欹枕，免向他门厚客颜。','',''),('quantangshi-38947','下第东归将及故园有作','杜荀鶴','quantangshi','','卷39','平生操立有天知，何事谋身与志违。
上国献诗还不遇，故园经乱又空归。
山城欲暮人烟歛，江月初寒钓艇归。
且把风寒作闲事，懒能和泪拜庭闱。','',''),('quantangshi-38948','宿东林寺题愿公院','杜荀鶴','quantangshi','','卷39','古寺沈沈僧未眠，搘颐将客说闲缘。
一溪月色非尘世，满洞松声似雨天。
檐底水涵抄律烛，窗间风引煮茶烟。
无由住得吟相伴，心系青云十五年。','',''),('quantangshi-38949','山居自遣','杜荀鶴','quantangshi','','卷39','茅屋周回松竹阴，山翁时挈酒相寻。
无人开口不言利，只我白头空爱吟。
月在钓潭秋睡重，云横樵迳野情深。
此中一日过一日，有底闲愁得到心。','',''),('quantangshi-38950','赠友人罢举赴辟命','杜荀鶴','quantangshi','','卷39','连天一水浸吴东，十幅帆飞二月风。
好景采抛诗句里，别愁驱入酒杯中。
渔依岸柳眠圆影，鸟傍岩花戏暖红。
不是桂枝终不得，自缘年少好从戎。','',''),('quantangshi-38951','乱后旅中遇友人','杜荀鶴','quantangshi','','卷39','念子为儒道未亨，依依心向十年兄。
莫依乱世轻依托，须学前贤隐姓名。
大国未知何日静，旧山犹可入云耕。
不如自此同归去，帆挂秋风一信程。','',''),('quantangshi-38952','赠休粮僧','杜荀鶴','quantangshi','','卷39','自言因病学休粮，本意非求不死方。
徒有至人传道术，更无斋客到禅房。
雨中林鸟归巢晚，霜后岩猨拾橡忙。
争似吾师无一事，稳披云衲坐藤牀。','',''),('quantangshi-38953','维扬春日再遇孙侍御','杜荀鶴','quantangshi','','卷39','本为荣家不为身，读书谁料转家贫。
三年行却千山路，两地思归一主人。
络岸柳丝悬细雨，绣田花朵弄残春。
多情御史应嗟见，未上青云白发新。','',''),('quantangshi-38954','乱后宿南陵废寺寄沈明府','杜荀鶴','quantangshi','','卷39','祗共寒灯坐到明，塞鸿冲雪一声声。
乱时为客无人识，废寺吟诗有鬼惊。
且把酒杯添志气，已将身事托公卿。
男儿仗劒酬恩在，未肯徒然过一生。','',''),('quantangshi-38955','投郑先辈','杜荀鶴','quantangshi','','卷39','匣中长劒未酬恩，不遇男儿不合论。
闷向酒杯吞日月，闲将诗句问干坤。
宁辞马足劳关路，肯为渔竿忆水村。
两鬓欲斑三百首，更教装写傍谁门。','',''),('quantangshi-38956','途中有作','杜荀鶴','quantangshi','','卷39','无论南北与西东，名利牵人处处同。
枕上事仍多马上，山中心更甚关中。
川原晚结阴沈气，草树秋生索漠风。
百岁此身如且健，大家闲作卧云翁。','',''),('quantangshi-38957','和舍弟题书堂','杜荀鶴','quantangshi','','卷39','兄弟将知大自强，乱时同葺读书堂。
岩泉遇雨多还闹，溪竹唯风少即凉。
藉草醉吟花片落，傍山闲步药苗香。
团圆便是家肥事，何必盈仓与满箱。','',''),('quantangshi-38958','送蜀客游维扬','杜荀鶴','quantangshi','','卷39','见说西川景物繁，维扬景物胜西川。
青春花柳树临水，白日绮罗人上船。
夹岸画楼难惜醉，数桥明月不教眠。
送君嬾问君回日，才子风流正少年。','',''),('quantangshi-38959','旅寓','杜荀鶴','quantangshi','','卷39','暗筭乡程隔数州，欲归无计泪空流。
已违骨肉来时约，更束琴书何处游。
画角引风吹断梦，垂杨和雨结成愁。
去年今日还如此，似与青春有旧讐。','',''),('quantangshi-38960','途中春','杜荀鶴','quantangshi','','卷39','年光身事旋成空，毕竟何门遇至公。
人世鹤归双鬓上，客程蛇遶乱山中。
牧童向日眠春草，渔父隈岩避晚风。
一醉未醒花又落，故乡回首楚关东。','',''),('quantangshi-38961','维扬冬末寄幕中二从事','杜荀鶴','quantangshi','','卷39','江上数株桑枣树，自从离乱更荒凉。
那堪旅馆经残腊，祗把空书寄故乡。
典尽客衣三尺雪，炼精诗句一头霜。
故人多在芙蓉幕，应笑孜孜道未光。','',''),('quantangshi-38962','辞郑员外入关','杜荀鶴','quantangshi','','卷39','男儿三十尚蹉跎，未遂青云一桂科。
在客易为销岁月，到家难住似经过。
帆飞楚国风涛润，马度蓝关雨雪多。
长把行藏信天道，不知天道竟如何。','',''),('quantangshi-38963','书斋即事','杜荀鶴','quantangshi','','卷39','时清祗合力为儒，不可家贫与善疎。
卖却屋边三亩地，添成窗下一牀书。
沿溪摘果霜晴后，出竹吟诗月上初。
乡里老农多见笑，不知稽古胜耕锄。','',''),('quantangshi-38964','隽阳道中','杜荀鶴','quantangshi','','卷39','客路客路何悠悠，蝉声向背槐花愁。
争知百岁不百岁，未合白头今白头。
四五朵山妆雨色，两三行雁帖云秋。
输他江上垂纶者，祗在船中老便休。','',''),('quantangshi-38965','入关因别舍弟','杜荀鶴','quantangshi','','卷39','吾今别汝汝听言，去住人情足可安。
百口度荒均食易，数年经乱保家难。
莫愁寒族无人荐，但愿春官把卷看。
天道不欺心意是，帝乡吾土一般般。','',''),('quantangshi-38966','赠彭蠡钓者','杜荀鶴','quantangshi','','卷39','偏坐渔舟出苇林，苇花零落向秋深。
祗将波上鸥为侣，不把人间事系心。
傍岸歌来风欲起，卷丝眠去月初沈。
若教我似君闲放，赢得湖山到老吟。','',''),('quantangshi-38967','送友人入关','杜荀鶴','quantangshi','','卷39','此去青云莫更疑，出人才行足人知。
况当朝野搜贤日，正是孤寒取士时。
仙岛烟霞通鹤信，早春雷雨与龙期。
我今不得同君去，两鬓霜欺桂一枝。','',''),('quantangshi-38968','送友人宰浔阳','杜荀鶴','quantangshi','','卷39','高兴那言去路长，非君不解爱浔阳。
有时猨鸟来公署，到处烟霞是道乡。
钓艇满江鱼贱菜，纸窑连岳楮多桑。
陶潜旧隐依稀在，好继高踪结草堂。','',''),('quantangshi-38969','秋日卧病','杜荀鶴','quantangshi','','卷39','浮世浮名能几何，致身流落向天涯。
少年心壮轻为客，一日病来思在家。
山顶老猨啼古木，渡头新雁下平沙。
不堪吟罢西风起，黄叶满庭寒日斜。','',''),('quantangshi-38970','叙吟','杜荀鶴','quantangshi','','卷39','多慙到处有诗名，转觉吟诗僻性成。
度水却嫌船着岸，过山翻恨马贪程。
如讐雪月年年景，似梦笙歌处处声。
未合白头今已白，自知非为别愁生。','',''),('quantangshi-38971','行次荥阳却寄诸弟','杜荀鶴','quantangshi','','卷39','难把归书说远情，奉亲多阙拙为兄。
早知寸禄荣家晚，悔不深山共汝耕。
枕上算程关月落，帽前搜景岳云生。
如今已作长安计，祗得辛勤取一名。','',''),('quantangshi-38972','登石壁禅师水阁有作','杜荀鶴','quantangshi','','卷39','石壁早闻僧说好，今来偏与我相宜。
有山有水堪吟处，无雨无风见景时。
渔父晚船分浦钓，牧童寒笛倚牛吹。
画人画得从他画，六幅应输八句诗。','',''),('quantangshi-38973','赠袒肩和尚','杜荀鶴','quantangshi','','卷39','山衣草屐染莓苔，双眼犹慵向俗开。
若比吾师居世上，何如野客卧岩隈。
才闻锡杖离三楚，又说随缘向五台。
乘醉吟诗问禅理，为谁须去为谁来。','',''),('quantangshi-38974','闲居即事','杜荀鶴','quantangshi','','卷39','形觉清羸道觉肥，竹门前径静相宜。
一壶村酒无求处，数朵庭花见落时。
章句偶为前辈许，话言多被俗人疑。
一枝仙桂如攀得，祗此山前是老期。','',''),('quantangshi-38975','自叙','杜荀鶴','quantangshi','','卷39','酒瓮琴书伴病身，熟谙时事乐于贫。
宁为宇宙闲吟客，怕作干坤窃禄人。
诗旨未能忘救物，世情奈值不容真。
平生肺腑无言处，白发吾唐一逸人。','',''),('quantangshi-38976','空闲二公递以禅律相鄙因而解之','杜荀鶴','quantangshi','','卷39','一教谁云辟二途，律禅禅律智归愚。
念珠在手隳禅衲，禅衲披肩坏念珠。
象外空分空外象，无中有作有中无。
有无无有师穷取，山到平来海亦枯。','',''),('quantangshi-38977','寄温州朱尚书并呈军倅崔太傅','杜荀鶴','quantangshi','','卷39','永嘉名郡昔推名，连属荀家弟与兄。
教化静师龚渤海，篇章高体谢宣城。
山从海岸妆吟景，水自城根演政声。
今日老输崔博士，不妨疎逸伴双旌。','',''),('quantangshi-38978','恩门致书远及山居因献之','杜荀鶴','quantangshi','','卷39','时难转觉保身难，难向师门欲继颜。
若把白衣轻易脱，却成青桂偶然攀。
身居劒戟争雄地，道在干坤未丧间。
必许酬恩酬未晚，且须容到九华山。','',''),('quantangshi-38979','寄温州崔博士','杜荀鶴','quantangshi','','卷39','怀君劳我写诗情，窣窣阴风有鬼听。
县宰不仁工部饿，酒家无识翰林醒。
眼昏经史天何在，心尽英雄国未宁。
好向贤侯话吟侣，莫教辜负少微星。','',''),('quantangshi-38980','李昭象云与二三同人见访有寄','杜荀鶴','quantangshi','','卷39','得君书后病颜开，云拉同人访我来。
在路不妨冲雨雪，到山还免踏尘埃。
吟沈水阁何宵月，坐破松岩几处苔。
贫舍款宾无别物，止于空战大尊罍。','',''),('quantangshi-38981','自江西归九华','杜荀鶴','quantangshi','','卷39','他乡终日忆吾乡，及到吾乡值乱荒。
云外好山看不见，马头歧路去何忙。
无衣织女桑犹小，阙食农夫麦未黄。
许大干坤吟未了，挥鞭回首出陵阳。','',''),('quantangshi-38982','和友人见题山居水阁八韵','杜荀鶴','quantangshi','','卷39','池阁初成眼豁开，眼前霁景属微才。
试攀檐果猨先见，才把渔竿鹤即来。
修竹已多犹可种，艳花虽少不劳栽。
南昌一榻延徐孺，楚国千钟逼老莱。
未称执鞭奔紫陌，惟宜策杖步苍苔。
笼禽岂是摩霄翼，润木元非涧下材。
鉴己每将天作镜，陶情常以海为杯。
和君诗句吟声大，虫豸闻之谓蛰雷。','',''),('quantangshi-38983','感寓','杜荀鶴','quantangshi','','卷39','大海波涛浅，小人方寸深。
海枯终见底，人死不知心。','',''),('quantangshi-38984','春闺怨','杜荀鶴','quantangshi','','卷39','朝喜花艳春，暮悲花委尘。
不悲花落早，悲妾似花身。','',''),('quantangshi-38985','马上行','杜荀鶴','quantangshi','','卷39','五里复五里，去时无住时。
日将家渐远，犹恨马行迟。','',''),('quantangshi-38986','钓叟','杜荀鶴','quantangshi','','卷39','茅屋深湾里，钓船横竹门。
经营衣食外，犹得弄儿孙。','',''),('quantangshi-38987','再经胡城县','杜荀鶴','quantangshi','','卷39','去岁曾经此县城，县民无口不冤声。
今来县宰加朱绂，便是生灵血染成。','',''),('quantangshi-38988','读诸家诗','杜荀鶴','quantangshi','','卷39','辞赋文章能者稀，难中难者莫过诗。
直应吟骨无生死，祗我前身是阿谁。','',''),('quantangshi-38989','春来燕','杜荀鶴','quantangshi','','卷39','我屋汝嫌低不住，雕梁画阁也知宽。
大须稳择安巢处，莫道巢成却不安。','',''),('quantangshi-38990','清溪来明府出二子请诗因遗一绝','杜荀鶴','quantangshi','','卷39','珠明玉润尽惊人，不称寒门不称贫。
若向吾唐作双瑞，便同祥凤与祥麟。','',''),('quantangshi-38991','哭陈陶','杜荀鶴','quantangshi','','卷39','耒阳山下伤工部，采石江边吊翰林。
两地荒坟各三尺，却成开解哭君心。','',''),('quantangshi-38992','哭贝韬','杜荀鶴','quantangshi','','卷39','交朋来哭我来歌，喜傍山家葬荔萝。
四海十年人杀尽，似君埋少不埋多。','',''),('quantangshi-38993','蚕妇','杜荀鶴','quantangshi','','卷39','粉色全无饥色加，岂知人世有荣华。
年年道我蚕辛苦，底事浑身着苎麻。','',''),('quantangshi-38994','山寺老僧','杜荀鶴','quantangshi','','卷39','草靸无尘心地闲，静随猿鸟过寒暄。
眼昏齿落看经遍，却向僧中总不言。','',''),('quantangshi-38995','闽中秋思','杜荀鶴','quantangshi','','卷39','雨匀紫菊丛丛色，风弄红蕉叶叶声。
北畔是山南畔海，祗堪图画不堪行。','',''),('quantangshi-38996','八骏图','杜荀鶴','quantangshi','','卷39','丹雘传真未得真，那知筋骨与精神。
祗今恃骏凭毛色，绿耳骅骝赚杀人。','',''),('quantangshi-38997','赠僧','杜荀鶴','quantangshi','','卷39','利门名路两何凭，百岁风前短焰灯。
祗恐为僧僧不了，为僧得了总输僧。','',''),('quantangshi-38998','秋夕','杜荀鶴','quantangshi','','卷39','世间多少能诗客，谁是无愁得睡人。
自我夜来霜月下，到头吟魄始终身。','',''),('quantangshi-38999','溪兴','杜荀鶴','quantangshi','','卷39','山雨溪风卷钓丝，瓦瓯篷底独斟时。
醉来睡着无人唤，流下前溪也不知。','',''),('quantangshi-39000','过巢湖','杜荀鶴','quantangshi','','卷39','世人贪利复贪荣，来向湖边始至诚。
男子登舟与登陆，把心何不一般行。','',''),('quantangshi-39001','伤硖石县病叟','杜荀鶴','quantangshi','','卷39','无子无孙一病翁，将何筋力事耕农。
官家不管蓬蒿地，须勒王租出此中。','',''),('quantangshi-39002','赠老僧','杜荀鶴','quantangshi','','卷39','童子为僧今白首，暗锄心地种闲情。
时将旧衲添新线，披坐披行过一生。','',''),('quantangshi-39003','钓叟','杜荀鶴','quantangshi','','卷39','田不曾耕地不锄，谁人闲散得如渠。
渠将底物为香饵，一度抬竿一个鱼。','',''),('quantangshi-39004','溪岸秋思','杜荀鶴','quantangshi','','卷39','桑柘穷头三四家，挂罾垂钓是生涯。
秋风忽起溪滩白，零落岸边芦荻花。','',''),('quantangshi-39005','春日旅寓','杜荀鶴','quantangshi','','卷39','满城罗绮拖春色，几处笙歌揭画楼。
江上有家归未得，眼前花是眼前愁。','',''),('quantangshi-39006','田翁','杜荀鶴','quantangshi','','卷39','白发星星筋力衰，种田犹自伴孙儿。
官苗若不平平纳，任是丰年也受饥。','',''),('quantangshi-39007','秋江雨夜逢诗友','杜荀鶴','quantangshi','','卷39','故友别来三四载，新诗吟得百余篇。
夜来江上秋无月，恨不相逢在雪天。','',''),('quantangshi-39008','感春','杜荀鶴','quantangshi','','卷39','无况青云有恨身，眼前花似梦中春。
浮生七十今三十，已是人间半世人。','',''),('quantangshi-39009','题花木障','杜荀鶴','quantangshi','','卷39','不假东风次第吹，笔匀春色一枝枝。
由来画看胜栽看，免见朝开暮落时。','',''),('quantangshi-39010','顾云侍御出二子请诗因遗一绝','杜荀鶴','quantangshi','','卷39','二雏毛骨秀仍奇，小小能吟大大诗。
想得月中仙桂树，各从生日长新枝。','',''),('quantangshi-39011','秋夕病中','杜荀鶴','quantangshi','','卷39','坏屋不眠风雨夜，故园无信水云秋。
病中枕上谁相问，一一蝉声槐树头。','',''),('quantangshi-39012','宿栾城驿却寄常山张书记','杜荀鶴','quantangshi','','卷39','一更更尽到三更，吟破离心句不成。
数树秋风满庭月，忆君时复下堦行。','',''),('quantangshi-39013','湘江秋夕','杜荀鶴','quantangshi','','卷39','三湘月色三湘水，浸骨寒光似练铺。
一夜寒鸿来不住，故乡书信半年无。','',''),('quantangshi-39014','旅怀','杜荀鶴','quantangshi','','卷39','蒹葭月冷时闻雁，杨柳风和日听莺。
水涉山行二年客，就中偏怕雨船声。','',''),('quantangshi-39015','赠崔道士','杜荀鶴','quantangshi','','卷39','四海兵戈无静处，人家废业望烽烟。
九华道士浑如梦，犹向尊前笑揭天。','',''),('quantangshi-39016','题道林寺','杜荀鶴','quantangshi','','卷39','身未立间终日苦，身当立后几年荣。
万般不及僧无事，共水将山过一生。','',''),('quantangshi-39017','赠质上人','杜荀鶴','quantangshi','','卷39','枿坐云游出世尘，兼无瓶钵可随身。
逢人不说人间事，便是人间无事人。','',''),('quantangshi-39018','泾溪','杜荀鶴','quantangshi','','卷39','泾溪石险人兢慎，终岁不闻倾覆人。
却是平流无石处，时时闻说有沈沦。','',''),('quantangshi-39019','夏日题悟空上人院','杜荀鶴','quantangshi','','卷39','三伏闭门披一衲，兼无松竹荫房廊。
安禅不必须山水，灭得心中火自凉。','',''),('quantangshi-39020','经严陵钓台','杜荀鶴','quantangshi','','卷39','苍翠云峰开俗眼，泓澄烟水浸尘心。
唯将道业为芳饵，钓得高名直至今。','',''),('quantangshi-39021','关试后筵上别同人','杜荀鶴','quantangshi','','卷40','日午离筵到夕阳，明朝秦地与吴乡。
同年多是长安客，不信行人欲断肠。','',''),('quantangshi-39022','鸬鷀','杜荀鶴','quantangshi','','卷40','一般毛羽结羣飞，雨岸烟汀好景时。
深水有鱼衔得出，看来却是鹭鹚饥。','',''),('quantangshi-39023','宿村舍','杜荀鶴','quantangshi','','卷40','野人于我有何情，半掩柴门向月明。
深夜欲眠眠未着，一丛寒木一猿声。','',''),('quantangshi-39024','题新雁','杜荀鶴','quantangshi','','卷40','暮天新雁起汀洲，红蓼花疎水国秋。
想得故园今夜月，几人相忆在江楼。','',''),('quantangshi-39025','离家','杜荀鶴','quantangshi','','卷40','丈夫三十身如此，疲马离乡懒着鞭。
槐柳路长愁杀我，一枝蝉到一枝蝉。','',''),('quantangshi-39026','旅舍遇雨','杜荀鶴','quantangshi','','卷40','月华星彩坐来收，岳色江声暗结愁。
半夜灯前十年事，一时和雨到心头。','',''),('quantangshi-39027','送人归淝上','杜荀鶴','quantangshi','','卷40','巢湖春涨喻溪深，才过东关见故林。
莫道南来总无利，水亭山寺二年吟。','',''),('quantangshi-39028','自遣','杜荀鶴','quantangshi','','卷40','粝食麤衣随分过，堆金积帛欲如何。
百年身后一丘土，贫富高低争几多。','',''),('quantangshi-39029','闻子规','杜荀鶴','quantangshi','','卷40','楚天空阔月成轮，蜀魄声声似告人。
啼得血流无用处，不如缄口过残春。','',''),('quantangshi-39030','秋夜苦吟','杜荀鶴','quantangshi','','卷40','吟尽三更未着题，竹风松雨共凄凄。
此时若有人来听，始觉巴猿不解啼。','',''),('quantangshi-39031','秋夜闻砧','杜荀鶴','quantangshi','','卷40','荒凉客舍眠秋色，砧杵家家弄月明。
不及巴山听猿夜，三声中有不愁声。','',''),('quantangshi-39032','将过湖南经马当山庙因书三绝 一','杜荀鶴','quantangshi','','卷40','人说马当波浪险，我经波浪似通衢。
大凡君子行藏是，自有龙神卫过湖。','',''),('quantangshi-39033','将过湖南经马当山庙因书三绝 二','杜荀鶴','quantangshi','','卷40','贪残官吏虔诚谒，毒害商人沥胆过。
祗怕马当山下水，不知平地有风波。','',''),('quantangshi-39034','将过湖南经马当山庙因书三绝 三','杜荀鶴','quantangshi','','卷40','九江连海一般深，未必船经庙下沈。
头上苍苍没瞒处，不如平取一生心。','',''),('quantangshi-39035','梁王坐上赋无云雨','杜荀鶴','quantangshi','','卷40','同是干坤事不同，雨丝飞洒日轮中。
若教阴郎长相似，争表梁王造化功。','',''),('quantangshi-39036','小松','杜荀鶴','quantangshi','','卷40','自小刺头深草里，而今渐觉出蓬蒿。
时人不识凌云木，直待凌云始道高。','',''),('quantangshi-39037','醉书僧壁','杜荀鶴','quantangshi','','卷40','九华山色真堪爱，留得高僧尔许年。
听我吟诗供我酒，不曾穿得判斋钱。','',''),('quantangshi-39038','寄李隐居','杜荀鶴','quantangshi','','卷40','自小栖玄到老闲，如云如鹤住应难。
溪山不必将钱买，赢得来来去去看。','',''),('quantangshi-39039','句','杜荀鶴','quantangshi','','卷40','旧衣灰絮絮，新酒竹篘篘。
只知断送豪家酒，不解安排旅客情。','',''),('quantangshi-39040','上蜀王','張道古','quantangshi','','卷40','封章才达冕旒前，黜诏俄离玉座端。
二乱岂由明主用，五危终被佞臣弹。
西巡凤府非为固，东播銮舆卒未安。
谏疏至今如可在，谁能更与读来看。','',''),('quantangshi-39041','咏雨','張道古','quantangshi','','卷40','亢阳今已久，嘉雨自云倾。
一点不斜去，极多时下成。','',''),('quantangshi-39042','杨岐山','廩','quantangshi','','卷40','逗竹穿花越几村，还从旧路入云门。
翠微不闭楼台出，清吹频回水石喧。
天外鹤归松自老，岩间僧逝塔空存。
重来白首良堪喜，朝露浮生不足言。','',''),('quantangshi-39043','吹笙引','王轂','quantangshi','','卷40','娲皇遗音寄玉笙，双成传得何凄清。
丹穴娇雏七十只，一时飞上秋天鸣。
水泉迸泻急相续，一束宫商裂寒玉。
旖旎香风绕指生，千声妙尽神仙曲。
曲终满席悄无语，巫山冷碧愁云雨。','',''),('quantangshi-39044','鸿门宴','王轂','quantangshi','','卷40','寰海沸兮争战苦，风云愁兮会龙虎。
四百年汉欲开基，项庄一剑何虚舞。
殊不知人心去暴秦，天意归明主。
项王足底踏汉土，席上相看浑未悟。','',''),('quantangshi-39045','玉树曲','王轂','quantangshi','','卷40','陈宫内宴明朝日，玉树新妆逞娇逸。
三阁霞明天上开，灵鼍振攂神仙出。
天花数朵风吹绽，对舞轻盈瑞香散。
金管红弦旖旎随，霓旌玉佩参差转。
璧月夜满楼风轻，莲舌泠泠词调新。
当行狎客尽持禄，直谏犯颜无一人。
歌舞未终乐未阕，晋王剑上黏腥血。
君臣犹在醉乡中，一面已无陈日月。
圣唐御宇三百祀，濮上桑间宜禁止。
请停此曲归正声，愿将雅乐调元气。','',''),('quantangshi-39046','苦热行','王轂','quantangshi','','卷40','祝融南来鞭火龙，火旗焰焰烧天红。
日轮当午凝不去，万国如在洪炉中。
五岳翠干云彩灭，阳侯海底愁波竭。
何当一夕金风发，为我扫却天下热。','',''),('quantangshi-39047','暑日题道边树','王轂','quantangshi','','卷40','火轮迸焰烧长空，浮埃扑面愁朦朦。
羸童走马喘不进，忽逢碧树含清风。
清风留我移时住，满地浓阴嬾前去。
却叹人无及物功，不似团团道边树。','',''),('quantangshi-39048','红蔷薇歌','王轂','quantangshi','','卷40','红霞烂泼猩猩血，阿母瑶池晒仙缬。
晚日春风夺眼明，蜀机锦彩浑疑黦。
公子亭台香触人，百花懡㦬无精神。
苎罗西子见应妬，风光占断年年新。','',''),('quantangshi-39049','刺桐花','王轂','quantangshi','','卷40','南国清和烟雨辰，刺桐夹道花开新。
林梢簇簇红霞烂，暑天别觉生精神。
穠英鬬火欺朱槿，栖鹤惊飞翅忧烬。
直疑青帝去怱怱，收拾春风浑不尽。','',''),('quantangshi-39050','赠苍溪王明府有文在手曰长生','王轂','quantangshi','','卷40','执手长生在，人皆号地仙。
水云真遂性，龟鹤足齐年。
但以酒养气，何言命在天。
况无婚嫁累，应拍尚平肩。','',''),('quantangshi-39051','逢道者神和子','王轂','quantangshi','','卷40','珍重神和子，闻名五十年。
童颜终不改，绿发尚依然。
酒里消闲日，人间作散仙。
长生如可慕，相逐隐林泉。','',''),('quantangshi-39052','送友人归闽','王轂','quantangshi','','卷40','东南归思切，把酒且留连。
再会知何处，相看共黯然。
猨啼棃岭路，月白建溪船。
莫恋家乡住，酬身在少年。','',''),('quantangshi-39053','春草碧色','王轂','quantangshi','','卷40','习习东风扇，萋萋草色新。
浅深千里碧，高下一时春。
嫩叶舒烟际，微香动水滨。
金塘明夕照，辇路惹芳尘。
造化功何广，阳和力自均。
今当发生日，沥恳祝良辰。','',''),('quantangshi-39054','梦仙谣三首 一','王轂','quantangshi','','卷40','前程渐觉风光好，琪花片片粘瑶草。
有人遗我五色丹，一粒吞之后天老。','',''),('quantangshi-39055','梦仙谣三首 二','王轂','quantangshi','','卷40','青童递酒金觞疾，列坐红霞神气逸。
笑说留连数日间，已是人间一千日。','',''),('quantangshi-39056','梦仙谣三首 三','王轂','quantangshi','','卷40','瑶台绛节游皆遍，异果奇花香扑面。
松窗梦觉却神清，残月林前三两片。','',''),('quantangshi-39057','后魏行','王轂','quantangshi','','卷40','力微皇帝谤天嗣，太武凶残人所畏。
一朝𦍩䍽飞上天，子孙尽作河鱼饵。','',''),('quantangshi-39058','秋','王轂','quantangshi','','卷40','蝉噪古槐疏叶下，树衔斜日映孤城。
欲知潘鬓愁多少，一夜新添白数茎。','',''),('quantangshi-39059','燕','王轂','quantangshi','','卷40','海燕双飞意若何，曲梁呕嘎语声多。
茅檐不必嫌卑陋，犹胜吴宫爇尔窠。','',''),('quantangshi-39060','牡丹','王轂','quantangshi','','卷40','牡丹妖艳乱人心，一国如狂不惜金。
曷若东园桃与李，果成无语自垂阴。','',''),('quantangshi-39061','古意二首 一','孫郃','quantangshi','','卷40','屈子生楚国，七雄知其材。
介洁世不容，迹合藏蒿莱。
道废固命也，瓢饮亦贤哉。
何事葬江水，空使后人哀。','',''),('quantangshi-39062','古意二首 二','孫郃','quantangshi','','卷40','魏礼段干木，秦王乃止戈。
小国有其人，大国奈之何。
贤哲信为美，兵甲岂云多。
君子战必胜，斯言闻孟轲。','',''),('quantangshi-39063','哭方玄英先生','孫郃','quantangshi','','卷40','牛斗文星落，知是先生死。
湖上闻哭声，门前见弹指。
官无一寸禄，名传千万里。
死着弊衣裳，生谁顾朱紫。
我心痛其语，泪落不能已。
犹喜韦补阙，扬名荐天子。','',''),('quantangshi-39064','句','孫郃','quantangshi','','卷40','仕宦类商贾，终日常东西。','',''),('quantangshi-39065','投节度邢公','褚載','quantangshi','','卷40','西风昨夜坠红兰，一宿邮亭事万般。
无地可耕归不得，有恩堪报死何难。
流年怕老看将老，百计求安未得安。
一卷新书满怀泪，频来门馆诉饥寒。','',''),('quantangshi-39066','贺赵观文重试及第','褚載','quantangshi','','卷40','一枝仙桂两回春，始觉文章可致身。
已把色丝要上第，又将彩笔冠羣伦。
龙泉再淬方知利，火浣重烧转更新。
今日街头看御牓，大能荣耀苦心人。','',''),('quantangshi-39067','赠道士','褚載','quantangshi','','卷40','簪星曳月下蓬壶，曾见东臯种白榆。
六甲威灵藏瑞检，五龙雷电遶霜都。
惟教鹤探丹丘信，不使人窥太乙炉。
闻说葛陂风浪恶，许骑青鹿从行无。','',''),('quantangshi-39068','晓发','褚載','quantangshi','','卷40','贪路贪名须早发，枕前无计暂裴回。
才闻鸡唱呼童起，已有铃声过驿来。
衣湿乍惊霑雾露，马行仍未见尘埃。
朝朝陌上侵星去，待得酬身了便回。','',''),('quantangshi-39069','晓感','褚載','quantangshi','','卷40','晓鼓冬冬星汉微，佩金鸣玉鬬光辉。
出门各自争岐路，至老何人免是非。
大道不应由曲取，浮生还要畧知机。
故园华表高高在，可得不如丁令威。','',''),('quantangshi-39070','南徐晚望','褚載','quantangshi','','卷40','芳草铺香晚岸晴，岸头含醉去来行。
僧归岳外残钟寺，日下江边调角城。
入浙孤帆知楚信，过淮疎雨带潮声。
如今未免风尘役，宁敢怱怱便濯缨。','',''),('quantangshi-39071','移石','褚載','quantangshi','','卷40','磷𥒘一片溪中石，恰称幽人弹素琴。
浪侵多年苔色在，洗来今日碏痕深。
磨看粹色何殊玉，敲有奇声直异金。
不是不堪为器用，都缘良匠未留心。','',''),('quantangshi-39072','瀑布','褚載','quantangshi','','卷40','泻雾倾烟撼撼雷，满山风雨助喧豗。
争知不是青天阙，扑下银河一半来。','',''),('quantangshi-39073','定鼎门','褚載','quantangshi','','卷40','郏鄏城高门倚天，九重踪迹尚依然。
须知道德无关锁，一闭干坤一万年。','',''),('quantangshi-39074','陈仓驿','褚載','quantangshi','','卷40','锦翼花冠安在哉，雄飞雌伏尽尘埃。
一双童子应惆怅，不见真人更猎来。','',''),('quantangshi-39075','长城','褚載','quantangshi','','卷40','秦筑长城比铁牢，蕃戎不敢过临洮。
焉知万里连云色，不及尧阶三尺高。','',''),('quantangshi-39076','吊秦叟','褚載','quantangshi','','卷40','市西楼店金千秤，渭北田园粟万钟。
儿被杀伤妻被虏，一身随驾到三峰。','',''),('quantangshi-39077','云','褚載','quantangshi','','卷40','尽日看云首不回，无心都大似无才。
可怜光彩一片玉，万里晴天何处来。','',''),('quantangshi-39078','鹤','褚載','quantangshi','','卷40','欲洗霜翎下涧边，却嫌菱刺汚香泉。
沙鸥浦雁应惊讶，一举扶摇直上天。','',''),('quantangshi-39079','句','褚載','quantangshi','','卷40','相逢多是醉醺然，应有囊中子母钱。
有兴欲沽红麴酒，无人同上翠旌楼。
星斗离披烟霭收，玉蟾蜍耀海东头。
鹿胎冠子水晶簪，长啸欹眠紫桂阴。
躞蹀马摇金络脑，婵娟人坠玉搔头。
狂歌放饮浑成性，知道逍遥出俗笼。
除却洛阳才子后，更谁封恨吊怀沙。
莲浦浪澄堪倚钓，柳堤风暖好垂鞭。
上马等闲销白日，出门轻薄倚黄金。
净名方丈虽然病，曼倩年涯未有多。','',''),('quantangshi-39080','代寄边人','鄭準','quantangshi','','卷40','君去不来久，悠悠昏又明。
片心因卜解，残梦过桥惊。
圣泽如垂饵，沙场会息兵。
凉风当为我，一一送砧声。','',''),('quantangshi-39081','江南清明','鄭準','quantangshi','','卷40','吴山楚驿四年中，一见清明一改容。
旅恨共风连夜起，韶光随酒着人浓。
延兴门外攀花别，采石江头带雨逢。
无限归心何计是，路边戈甲正重重。','',''),('quantangshi-39082','题宛陵北楼','鄭準','quantangshi','','卷40','雨来风静绿芜藓，凭着朱阑思浩然。
人语独耕烧后岭，鸟飞斜没望中烟。
松梢半露藏云寺，滩势横流出浦船。
若遣谢宣城不死，必应吟尽夕阳川。','',''),('quantangshi-39083','寄进士崔鲁范','鄭準','quantangshi','','卷40','洛阳才子旧交知，别后干戈积咏思。
百战市朝千里梦，三年风月几篇诗。
山高雁断音书绝，谷背莺寒变化迟。
会待路宁归得去，酒楼渔浦重相期。','',''),('quantangshi-39084','云','鄭準','quantangshi','','卷40','片片飞来静又闲，楼头江上复山前。
飘零尽日不归去，点破清光万里天。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-39085','句','鄭準','quantangshi','','卷40','护犊横身立，逢人揭尾跳。','',''),('quantangshi-39086','游九鲤湖','陳乘','quantangshi','','卷40','汗漫乘春至，林峦雾雨生。
洞莓黏屐重，岩雪溅衣轻。
窟宅分三岛，烟霞接五城。
却怜饶药物，欲辨不知名。','',''),('quantangshi-39087','章台夜思','韋莊','quantangshi','','卷40','清瑟怨遥夜，遶弦风雨哀。
孤灯闻楚角，残月下章台。
芳草已云暮，故人殊未来。
乡书不可寄，秋雁又南回。','',''),('quantangshi-39088','延兴门外作','韋莊','quantangshi','','卷40','芳草五陵道，美人金犊车。
绿奔穿内水，红落过墙花。
马足倦游客，鸟声欢酒家。
王孙归去晚，宫树欲栖鸦。','',''),('quantangshi-39089','刘得仁墓','韋莊','quantangshi','','卷40','至公遗至艺，终抱至冤沈。
名有诗家业，身无戚里心。
桂和秋露滴，松带夜风吟。
冥寞知春否，坟蒿日已深。','',''),('quantangshi-39090','下第题青龙寺僧房','韋莊','quantangshi','','卷40','千蹄万毂一枝芳，要路无媒果自伤。
题柱未期归蜀国，曳裾何处谒吴王。
马嘶春陌金羁闹，鸟睡花林绣羽香。
酒薄恨浓消不得，却将惆怅问支郎。','',''),('quantangshi-39091','虢州涧东村居作','韋莊','quantangshi','','卷40','东南骑马出郊坰，回首寒烟隔郡城。
清涧涨时翘鹭喜，绿桑疎处哺牛鸣。
儿童见少生于客，奴仆骄多倨似兄。
试望家田还自适，满畦秋水稻苗平。','',''),('quantangshi-39092','送日本国僧敬龙归','韋莊','quantangshi','','卷40','扶桑已在渺茫中，家在扶桑东更东。
此去与师谁共到，一船明月一帆风。','',''),('quantangshi-39093','对酒','韋莊','quantangshi','','卷40','何用岩栖隐姓名，一壶春酎可忘形。
伯伦若有长生术，直到如今醉未醒。','',''),('quantangshi-39094','尹喜宅','韋莊','quantangshi','','卷40','荒原秋殿柏萧萧，何代风烟占寂寥。
紫气已随仙仗去，白云空向帝乡消。
蒙蒙暮雨春鸡唱，漠漠寒芜雪兔跳。
欲问灵踪无处所，十洲空阔阆山遥。','',''),('quantangshi-39095','途中望雨怀归','韋莊','quantangshi','','卷40','满空寒雨漫霏霏，去路云深锁翠微。
牧竖远当烟草立，饥禽闲傍渚田飞。
谁家树压红榴折，几处篱悬白菌肥。
对此不堪乡外思，荷蓑遥羡钓人归。','',''),('quantangshi-39096','古离别','韋莊','quantangshi','','卷40','晴烟漠漠柳毵毵，不那离情酒半酣。
更把玉鞭云外指，断肠春色在江南。','',''),('quantangshi-39097','柳谷道中作却寄','韋莊','quantangshi','','卷40','马前红叶正纷纷，马上离情断杀魂。
晓发独辞残月店，暮程遥宿隔云村。
心如岳色留秦地，梦逐河声出禹门。
莫怪苦吟鞭拂地，有谁倾盖待王孙。','',''),('quantangshi-39098','灞陵道中作','韋莊','quantangshi','','卷40','春桥南望水溶溶，一桁晴山倒碧峰。
秦苑落花零露湿，灞陵新酒拨醅浓。
青龙夭矫盘双阙，丹凤䙰褷隔九重。
万古行人离别地，不堪吟罢夕阳钟。','',''),('quantangshi-39099','秋日早行','韋莊','quantangshi','','卷40','上马萧萧襟袖凉，路穿禾黍绕宫墙。
半山残月露华冷，一岸野风莲萼香。
烟外驿楼红隐隐，渚边云树暗苍苍。
行人自是心如火，兔走乌飞不觉长。','',''),('quantangshi-39100','叹落花','韋莊','quantangshi','','卷40','一夜霏微露湿烟，晓来和泪丧婵娟。
不随残雪埋芳草，尽逐香风上舞筵。
西子去时遗笑靥，谢娥行处落金钿。
飘红堕白堪惆怅，少别穠华又隔年。','',''),('quantangshi-39101','宫怨','韋莊','quantangshi','','卷40','一辞同辇闭昭阳，耿耿寒宵禁漏长。
钗上翠禽应不返，镜中红艳岂重芳。
萤低夜色栖瑶草，水咽秋声傍粉墙。
展转令人思蜀赋，解将惆怅感君王。','',''),('quantangshi-39102','关河道中','韋莊','quantangshi','','卷40','槐陌蝉声柳市风，驿楼高倚夕阳东。
往来千里路长在，聚散十年人不同。
但见时光流似箭，岂知天道曲如弓。
平生志业匡尧舜，又拟沧浪学钓翁。','',''),('quantangshi-39103','题盘豆驿水馆后轩','韋莊','quantangshi','','卷40','极目晴川展画屏，地从桃塞接蒲城。
滩头鹭占清波立，原上人侵落照耕。
去雁数行天际没，孤云一点净中生。
冯轩尽日不回首，楚水吴山无限情。','',''),('quantangshi-39104','梁氏水斋','韋莊','quantangshi','','卷40','独醉任腾腾，琴棊亦自能。
卷帘山对客，开户犬迎僧。
看蚁移苔穴，闻蛙落石层。
夜窗风雨急，松外一庵灯。','',''),('quantangshi-39105','曲池作','韋莊','quantangshi','','卷40','细雨曲池滨，青袍草色新。
咏诗行信马，载酒喜逢人。
性为无机率，家因守道贫。
若无诗自遣，谁奈寂寥春。','',''),('quantangshi-39106','嘉会里闲居','韋莊','quantangshi','','卷40','岂知城阙内，有地出红尘。
草占一方绿，树藏千古春。
马嘶游寺客，犬吠探花人。
寂寂无钟鼓，槐行接紫宸。','',''),('quantangshi-39107','夏夜','韋莊','quantangshi','','卷40','傍水迁书榻，开襟纳夜凉。
星繁愁昼热，露重觉荷香。
蛙吹鸣还息，蛛罗灭又光。
正吟秋兴赋，桐景下西墙。','',''),('quantangshi-39108','早发','韋莊','quantangshi','','卷40','早雾浓于雨，田深黍稻低。
出门鸡未唱，过客马频嘶。
树色遥藏店，泉声暗傍畦。
独吟三十里，城月尚如圭。','',''),('quantangshi-39109','寓言','韋莊','quantangshi','','卷40','黄金日日销还铸，仙桂年年折又生。
兔走乌飞如未息，路尘终见泰山平。','',''),('quantangshi-39110','对雪献薛常侍','韋莊','quantangshi','','卷40','璚林瑶树忽珊珊，急带西风下晚天。
皓鹤䙰褷飞不辨，玉山重叠冻相连。
松装粉穗临窗亚，水结冰锥簇溜悬。
门外寒光利如劒，莫推红袖诉金船。','',''),('quantangshi-39111','题裴端公郊居','韋莊','quantangshi','','卷40','暂随红斾佐藩方，高迹终期卧故乡。
已近水声开涧户，更侵山色架书堂。
蒲生岸脚青刀利，柳拂波心绿带长。
莫夺野人樵牧兴，白云不识绣衣郎。','',''),('quantangshi-39112','登咸阳县楼望雨','韋莊','quantangshi','','卷40','乱云如兽出山前，细雨和风满渭川。
尽日空蒙无所见，雁行斜去字联联。','',''),('quantangshi-39113','贵公子','韋莊','quantangshi','','卷40','大道青楼御苑东，玉栏仙杏压枝红。
金铃犬吠梧桐月，朱鬣马嘶杨柳风。
流水带花穿巷陌，夕阳和树入帘栊。
瑶池宴罢归来醉，笑说君王在月宫。','',''),('quantangshi-39114','听赵秀才弹琴','韋莊','quantangshi','','卷40','满匣冰泉咽又鸣，玉音闲澹入神清。
巫山夜雨弦中起，湘水清波指下生。
蜂簇野花吟细韵，蝉移高柳迸残声。
不须更奏幽兰曲，卓氏门前月正明。','',''),('quantangshi-39115','观猎','韋莊','quantangshi','','卷40','苑墙东畔欲斜晖，傍苑穿花兔正肥。
公子喜逢朝罢日，将军夸换战时衣。
鹘翻锦翅云中落，犬带金铃草上飞。
直待四郊高鸟尽，掉鞍齐向国门归。','',''),('quantangshi-39116','三堂东湖作','韋莊','quantangshi','','卷40','满塘秋水碧泓澄，十亩菱花晚镜清。
景动新桥横蝃蝀，岸铺芳草睡䴔䴖。
蟾投夜魄当湖落，岳倒秋莲入浪生。
何处最添诗客兴，黄昏烟雨乱蛙声。','',''),('quantangshi-39117','放榜日作','韋莊','quantangshi','','卷40','一声天鼓辟金扉，三十仙材上翠微。
葛水雾中龙乍变，缑山烟外鹤初飞。
邹阳暖艳催花发，太皞春光簇马归。
回首便辞尘土世，彩云新换六铢衣。','',''),('quantangshi-39118','寄薛先辈','韋莊','quantangshi','','卷40','悬知回日彩衣荣，仙籍高标第一名。
瑶树带风侵物冷，玉山和雨射人清。
龙翻瀚海波涛壮，鹤出金笼燕雀惊。
不说文章与门地，自然毛骨是公卿。','',''),('quantangshi-39119','访含弘山僧不遇留题精舍','韋莊','quantangshi','','卷40','满院桐花鸟雀喧，寂寥芳草茂芊芊。
吾师正遇归山日，闲客空题到寺年。
池竹闭门教鹤守，琴书开箧任僧传。
人间不自寻行迹，一片孤云在碧天。','',''),('quantangshi-39120','寄从兄遵','韋莊','quantangshi','','卷40','江上秋风正钓鲈，九重天子梦翘车。
不将高卧邀刘主，自吐清谈护汉储。
沧海十年龙景断，碧云千里雁行疎。
相逢莫话归山计，明日东封待直庐。','',''),('quantangshi-39121','渔塘十六韵','韋莊','quantangshi','','卷40','洛水分余脉，穿岩出石棱。
碧经岚气重，清带露华澄。
莹澈通三岛，岩梧积万层。
巢由应共到，刘阮想同登。
壁峻苔如画，山昏雾似蒸。
撼松衣有雪，题石砚生冰。
路熟云中客，名留域外僧。
饥猿寻落橡，鬬鼠堕高藤。
嶮树临溪亚，残莎带岸崩。
持竿聊藉草，待月好垂罾。
对景思任父，开图想不兴。
晚风轻浪叠，暮雨湿烟凝。
似泛灵槎出，如迎羽客升。
仙源终不测，胜概自相仍。
欲别诚堪恋，长归又未能。
他时操史笔，为尔着良称。','',''),('quantangshi-39122','冬日长安感志寄献虢州崔郎中二十韵','韋莊','quantangshi','','卷40','帝里无成久滞淹，别家三度见新蟾。
郄诜丹桂无人指，阮籍青襟有泪霑。
溪上却思云满屋，镜中惟怕雪生髯。
病如原宪谁能疗，蹇似刘桢岂用占。
雾雨十年同隐遁，风雷何日振沈潜。
吁嗟每被更声引，歌咏还因酒思添。
客舍正甘愁寂寂，郡楼遥想醉恹恹。
已闻铃阁悬新诏，即向纶闱副具瞻。
济物便同川上檝，慰心还似邑中黔。
观星始觉中郎贵，问俗方知太守廉。
宅后绿波栖画鷁，马前红袖簇丹襜。
闲招好客斟香蚁，闷对琼花咏散盐。
积冻慢封寒溜细，暮云高拔远峰尖。
讼堂无事冰生印，水榭高吟月透帘。
松下围棋期褚胤，笔头飞箭荐陶谦。
未知匣劒何时跃，但恐铅刀不再銛。
虽有远心长拥彗，耻将新劒学编苫。
才惊素节移铜律，又见玄冥变玉签。
百口似萍依广岸，一身如燕恋高檐。
如今正困风波力，更向人中问宋纤。','',''),('quantangshi-39123','和薛先辈见寄初秋寓怀即事之作二十韵','韋莊','quantangshi','','卷40','玉律初移候，清风乍远襟。
一声蝉到耳，千炬火然心。
岳静云堆翠，楼高日半沈。
引愁憎暮角，惊梦怯残砧。
露白凝湘簟，风篁韵蜀琴。
鸟喧从果烂，堦净任苔侵。
柿叶添红景，槐柯减绿阴。
采珠逢宝窟，阅石见瑶林。
鲁殿铿寒玉，苔山激碎金。
郄堂流桂景，陈巷集车音。
名自张华显，词因葛亮吟。
水深龙易失，天远鹤难寻。
鉴貌宁慙乐，论才岂谢任。
义心孤劒直，学海怒涛深。
既覩文兼质，翻疑古在今。
慙闻纡绿绶，即候挂朝簪。
晚树连秋坞，斜阳映暮岑。
夜虫方唧唧，疲马正骎骎。
托迹同吴燕，依仁似越禽。
会随仙羽化，香蚁且同斟。','',''),('quantangshi-39124','同旧韵','韋莊','quantangshi','','卷40','大火收残暑，清光渐惹襟。
谢庄千里思，张翰五湖心。
暮角迎风急，孤钟向暝沈。
露滋三径草，日动四邻砧。
簟委班姬扇，蝉悲蔡琰琴。
方愁丹桂远，已怯二毛侵。
甃石回泉脉，移棊就竹阴。
触丝蛛堕网，避隼鸟投林。
貌愧潘郎璧，文慙吕相金。
但埋酆狱气，未发爨桐音。
静笑刘琨舞，闲思阮籍吟。
野花和雨斸，怪石入云寻。
迹竟终非切，幽闲且自任。
趋时慙艺薄，托质仰恩深。
美价方稀古，清名已绝今。
既闻留缟带，讵肯掷蓍簪。
迟客虚高阁，迎僧出乱岑。
壮心徒戚戚，逸足自骎骎。
安羡仓中鼠，危同幕上禽。
期君调鼎鼐，他日俟羊斟。','',''),('quantangshi-39125','三用韵','韋莊','quantangshi','','卷40','素律初回驭，商飙暗触襟。
乍伤诗客思，还动旅人心。
蝉噪因风断，鳞游见鹭沈。
笛声随晚吹，松韵激遥砧。
地覆青袍草，窗横绿绮琴。
烟霄难自致，岁月易相侵。
涧柳横孤彴，岩藤架密阴。
潇湘期钓侣，鄠杜别家林。
遗愧虞卿璧，言依季布金。
铮鏦闻郢唱，次第发巴音。
萤影冲帘落，虫声拥砌吟。
楼高思共钓，寺远想同寻。
入夜愁难遣，逢秋恨莫任。
蜗游苔径滑，鹤步翠塘深。
莫问荣兼辱，宁论古与今。
固穷怜瓮牖，感旧惜蒿簪。
晚日舒霞绮，遥天倚黛岑。
鸳鸾方翽翽，骅骥整骎骎。
未化投陂竹，空思出谷禽。
感多聊自遣，桑落且闲斟。','',''),('quantangshi-39126','惊秋','韋莊','quantangshi','','卷40','不向烟波狎钓舟，强亲文墨事儒丘。
长安十二槐花陌，曾负秋风多少秋。','',''),('quantangshi-39127','登汉高庙闲眺','韋莊','quantangshi','','卷40','独寻仙境上高原，云雨深藏古帝坛。
天畔晚峰青簇簇，槛前春树碧团团。
参差郭外楼台小，断续风中鼓角残。
一带远光何处水，钓舟闲系夕阳滩。','',''),('quantangshi-39128','耒阳县浮山神庙','韋莊','quantangshi','','卷40','一郡皆传此庙灵，庙前松桂古今青。
山曾尧代浮洪水，地有唐臣奠绿醽。
遶坐香风吹宝盖，傍檐烟雨湿岩扃。
为霖自可成农岁，何用兴师远伐邢。','',''),('quantangshi-39129','愁','韋莊','quantangshi','','卷40','避愁愁又至，愁至事难忘。
夜坐心中火，朝为鬓上霜。
不经公子梦，偏入旅人肠。
借问高轩客，何乡是醉乡。','',''),('quantangshi-39130','村居书事','韋莊','quantangshi','','卷40','年年耕与钓，鸥鸟已相依。
砌长苍苔厚，藤抽紫蔓肥。
风莺移树啭，雨燕入楼飞。
不觉春光暮，遶篱红杏稀。','',''),('quantangshi-39131','三堂早春','韋莊','quantangshi','','卷40','独倚危楼四望遥，杏花春陌马声骄。
池边冰刃暖初落，山上雪棱寒未销。
溪送绿波穿郡宅，日移红影度村桥。
主人年少多情味，笑换金龟解珥貂。','',''),('quantangshi-39132','雨霁晚眺','韋莊','quantangshi','','卷40','入谷路萦纡，岩巅日欲晡。
岭云寒埽盖，溪雪冻黏须。
卧草跧如兔，听冰怯似狐。
仍闻关外火，昨夜彻皇都。','',''),('quantangshi-39133','立春日作','韋莊','quantangshi','','卷40','九重天子去蒙尘，御柳无情依旧春。
今日不关妃妾事，始知辜负马嵬人。','',''),('quantangshi-39134','赠云阳裴明府','韋莊','quantangshi','','卷40','南北三年一解携，海为深谷岸为蹊。
已闻陈胜心降汉，谁为田横国号齐。
暴客至今犹战鹤，故人何处尚驱鸡。
归来能作烟波伴，我有鱼舟在五溪。','',''),('quantangshi-39135','贼中与萧韦二秀才同卧重疾二君寻愈余独加焉恍惚之中因有题','韋莊','quantangshi','','卷40','与君同卧疾，独我渐弥留。
弟妹不知处，兵戈殊未休。
胸中疑晋竖，耳下鬬殷牛。
纵有秦医在，怀乡亦泪流。','',''),('quantangshi-39136','重围中逢萧校书','韋莊','quantangshi','','卷40','相逢俱此地，此地是何乡。
侧目不成语，抚心空自伤。
劒高无鸟度，树暗有兵藏。
底事征西将，年年戍洛阳。','',''),('quantangshi-39137','咸通','韋莊','quantangshi','','卷40','咸通时代物情奢，欢杀金张许史家。
破产竞留天上乐，铸山争买洞中花。
诸郎宴罢银灯合，仙子游回璧月斜。
人意似知今日事，急催弦管送年华。','',''),('quantangshi-39138','白樱桃','韋莊','quantangshi','','卷40','王母堦前种几株，水精帘外看如无。
只应汉武金盘上，泻得珊珊白露珠。','',''),('quantangshi-39139','夜景','韋莊','quantangshi','','卷40','满庭松桂雨余天，宋玉秋声韵蜀弦。
乌兔不知多事世，星辰长似太平年。
谁家一笛吹残暑，何处双砧捣暮烟。
欲把伤心问明月，素娥无语泪娟娟。','',''),('quantangshi-39140','宿山家','韋莊','quantangshi','','卷40','山行侵夜到，云窦一星灯。
草动蛇寻穴，枝摇鼠上藤。
背风开药竈，向月展渔罾。
明日前溪路，烟萝更几层。','',''),('quantangshi-39141','长年','韋莊','quantangshi','','卷40','长年方悟少年非，人道新诗胜旧诗。
十亩野塘留客钓，一轩春雨对僧棊。
花间醉任黄莺语，亭上吟从白鹭窥。
大盗不将炉冶去，有心重筑太平基。','',''),('quantangshi-39142','辛丑年','韋莊','quantangshi','','卷40','九衢漂杵已成川，塞上黄云战马闲。
但有羸兵填渭水，更无奇士出商山。
田园已没红尘里，弟妹相逢白刃间。
西望翠华殊未返，泪痕空湿劒文斑。','',''),('quantangshi-39143','思归','韋莊','quantangshi','','卷40','暖丝无力自悠扬，牵引东风断客肠。
外地见花终寂寞，异乡闻乐更凄凉。
红垂野岸樱还熟，绿染回汀草又芳。
旧里若为归去好，子期凋谢吕安亡。','',''),('quantangshi-39144','忆昔','韋莊','quantangshi','','卷40','昔年曾向五陵游，子夜歌清月满楼。
银烛树前长似昼，露桃华里不知秋。
西园公子名无忌，南国佳人号莫愁。
今日乱离俱是梦，夕阳唯见水东流。','',''),('quantangshi-39145','合欢莲花','韋莊','quantangshi','','卷40','虞舜南巡去不归，二妃相誓死江湄。
空留万古香魂在，结作双葩合一枝。','',''),('quantangshi-39146','览萧必先卷','韋莊','quantangshi','','卷40','满轴编新句，翛然大雅风。
名因五字得，命合一言通。
景尽才难尽，吟终意未终。
似逢曹与谢，烟雨思何穷。','',''),('quantangshi-39147','和人岁宴旅舍见寄','韋莊','quantangshi','','卷40','积雪满前除，寒光夜皎如。
老忧新岁近，贫觉故交疎。
意合论文后，心降得句初。
莫言常郁郁，天道有盈虚。','',''),('quantangshi-39148','宿泊孟津寄三堂友人','韋莊','quantangshi','','卷40','解缆西征未有期，槐花又逼桂花时。
鸿胪陌上归耕晚，金马门前献赋迟。
只恐愁苗生两鬓，不堪离恨入双眉。
分明昨夜南池梦，还把渔竿咏楚词。','',''),('quantangshi-39149','对酒赋友人','韋莊','quantangshi','','卷40','多病仍多感，君心自我心。
浮生都是梦，浩叹不如吟。
白雪篇篇丽，清酤盏盏深。
乱离俱老大，强醉莫霑襟。','',''),('quantangshi-39150','天井关','韋莊','quantangshi','','卷40','太行山上云深处，谁向云中筑女墙。
短绠讵能垂玉甃，缭垣何用学金汤。
斸开岚翠为高垒，截断云霞作巨防。
守吏不教飞鸟过，赤眉何路到吾乡。','',''),('quantangshi-39151','赠边将','韋莊','quantangshi','','卷40','昔因征远向金微，马出榆关一鸟飞。
万里只携孤劒去，十年空逐塞鸿归。
手招都护新降虏，身着文皇旧赐衣。
只待烟尘报天子，满头霜雪为兵机。','',''),('quantangshi-39152','春日','韋莊','quantangshi','','卷40','忽觉东风景渐迟，野梅山杏暗芳菲。
落星楼上吹残角，偃月营中挂夕晖。
旅梦乱随蝴蝶散，离魂渐逐杜鹃飞。
红尘遮断长安陌，芳草王孙暮不归。','',''),('quantangshi-39153','早秋夜作','韋莊','quantangshi','','卷40','翠簟初清暑半销，[撇]帘松韵送轻飙。
莎庭露永琴书润，山郭月明砧杵遥。
傍砌绿苔鸣蟋蟀，遶檐红树织蟏蛸。
不须更作悲秋赋，王粲辞家鬓已凋。','',''),('quantangshi-39154','寄江南逐客','韋莊','quantangshi','','卷40','二年音信阻湘潭，花下相思酒半酣。
记得竹斋风雨夜，对牀孤枕话江南。','',''),('quantangshi-39155','冬夜','韋莊','quantangshi','','卷40','睡觉寒炉酒半消，客情乡梦两遥遥。
无人为我磨心剑，割断愁肠一寸苗。','',''),('quantangshi-39156','又闻湖南荆渚相次陷没','韋莊','quantangshi','','卷40','几时闻唱凯旋歌，处处屯兵未倒戈。
天子只凭红斾壮，将军空恃紫髯多。
尸填汉水连荆阜，血染湘云接楚波。
莫问流离南越事，战余空有旧山河。','',''),('quantangshi-39157','家叔南游却归因献贺','韋莊','quantangshi','','卷40','缭绕江南一岁归，归来行色满戎衣。
长闻凤诏征兵急，何事龙韬献捷稀。
旅梦远依湘水阔，离魂空伴越禽飞。
遥知倚棹思家处，泽国烟深暮雨微。','',''),('quantangshi-39158','楚行吟','韋莊','quantangshi','','卷40','章华台下草如烟，故郢城头月似弦。
惆怅楚宫云雨后，露啼花笑一年年。','',''),('quantangshi-39159','洛阳吟','韋莊','quantangshi','','卷40','万户千门夕照边，开元时节旧风烟。
宫官试马游三市，舞女乘舟上九天。
胡骑北来空进主，汉皇西去竟升仙。
如今父老偏垂泪，不见承平四十年。','',''),('quantangshi-39160','过旧宅','韋莊','quantangshi','','卷40','华轩不见马萧萧，廷尉门人久寂寥。
朱槛翠楼为卜肆，玉栏仙杏作春樵。
堦前雨落鸳鸯瓦，竹里苔封螮蝀桥。
莫问此中销歇寺，娟娟红泪滴芭蕉。','',''),('quantangshi-39161','喻东军','韋莊','quantangshi','','卷40','四年龙驭守峨嵋，铁马西来步步迟。
五运未教移汉鼎，六韬何必待秦师。
几时鸾凤归丹阙，到处乌鸢从白旗。
独把一樽和泪酒，隔云遥奠武侯祠。','',''),('quantangshi-39162','清河县楼作','韋莊','quantangshi','','卷40','有客微吟独凭楼，碧云红树不胜愁。
盘雕迥印天心没，远水斜牵日脚流。
千里战尘连上苑，九江归路隔东周。','',''),('quantangshi-39163','北原闲眺','韋莊','quantangshi','','卷40','春城回首树重重，立马平原夕照中。
五凤灰残金翠灭，六龙游去市朝空。
千年王气浮清洛，万古坤灵镇碧嵩。
欲问向来陵谷事，野桃无语泪花红。','',''),('quantangshi-39164','赠戍兵','韋莊','quantangshi','','卷40','汉皇无事暂游汾，底事狐狸啸作羣。
夜指碧天占晋分，晓磨孤劒望秦云。
红旌不卷风长急，画角闲吹日又曛。
止竟有征须有战，洛阳何用久屯军。','',''),('quantangshi-39165','覩军回戈','韋莊','quantangshi','','卷40','关中羣盗已心离，关外犹闻羽檄飞。
御苑绿莎嘶战马，禁城寒月捣征衣。
漫教韩信兵涂地，不及刘琨啸解围。
昨日屯军还夜遁，满车空载洛神归。','',''),('quantangshi-39166','中渡晚眺','韋莊','quantangshi','','卷40','魏王堤畔草如烟，有客伤时独扣舷。
妖气欲昏唐社稷，夕阳空照汉山川。
千重碧树笼春苑，万缕红霞衬碧天。
家寄杜陵归不得，一回回首一潸然。','',''),('quantangshi-39167','河内别村业闲题','韋莊','quantangshi','','卷40','阮氏清风竹巷深，满溪松竹似山阴。
门当谷路多樵客，地带河声足水禽。
闲伴尔曹虽适意，静思吾道好霑襟。
邻翁莫问伤时事，一曲高歌夕照沈。','',''),('quantangshi-39168','闻官军继至未覩凯旋','韋莊','quantangshi','','卷40','嫖姚何日破重围，秋草深来战马肥。
已有孔明传将略，更闻王导得神机。
阵前鼙鼓晴应响，城上乌鸢饱不飞。
何事小臣偏注目，帝乡遥羡白云归。','',''),('quantangshi-39169','和集贤侯学士分司丁侍御秋日雨霁之作','韋莊','quantangshi','','卷40','洛岸秋晴夕照长，凤楼龙阙倚清光。
玉泉山净云初散，金谷树多风正凉。
席上客知蓬岛路，坐中寒有柏台霜。
多慙十载游梁士，却伴宾鸿入帝乡。','',''),('quantangshi-39170','题安定张使君','韋莊','quantangshi','','卷40','器度风标合出尘，桂宫何负一枝新。
成丹始见金无滓，冲斗方知劒有神。
愤气不销头上雪，政声空布海边春。
中兴若继开元事，堪向龙池作近臣。','',''),('quantangshi-39171','颍阳县','韋莊','quantangshi','','卷40','琴堂连少室，故事即仙踪。
树老风声壮，山高腊候浓。
雪多庭有鹿，县僻寺无钟。
何处留诗客，茆檐倚后峰。','',''),('quantangshi-39172','寄园林主人','韋莊','quantangshi','','卷40','主人常不在，春物为谁开。
桃艳红将落，梨华雪又摧。
晓莺闲自啭，游客暮空回。
尚有余芳在，犹堪载酒来。','',''),('quantangshi-39173','洛北村居','韋莊','quantangshi','','卷40','十亩松篁百亩田，归来方属大兵年。
岩边石室低临水，云外岚峰半入天。
鸟势去投金谷树，钟声遥出上阳烟。
无人说得中兴事，独倚斜晖忆仲宣。','',''),('quantangshi-39174','对梨花赠皇甫秀才','韋莊','quantangshi','','卷40','林上梨花雪压枝，独攀琼艳不胜悲。
依前此地逢君处，还是去年今日时。
且恋残阳留绮席，莫推红袖诉金巵。
腾腾战鼓正多事，须信明朝难重持。','',''),('quantangshi-39175','立春','韋莊','quantangshi','','卷40','青帝东来日驭迟，暖烟轻逐晓风吹。
罽袍公子樽前觉，锦帐佳人梦里知。
雪圃乍开红菜甲，彩幡新翦绿[杨]丝。
殷勤为作宜春曲，题向花牋帖绣楣。','',''),('quantangshi-39176','村笛','韋莊','quantangshi','','卷40','箫韶九奏韵凄锵，曲度虽高调不伤。
却见孤村明月夜，一声牛笛断人肠。','',''),('quantangshi-39177','题李斯传','韋莊','quantangshi','','卷40','蜀魄湘魂万古悲，未悲秦相死秦时。
临刑莫恨仓中鼠，上蔡东门去自迟。','',''),('quantangshi-39178','赠薛秀才','韋莊','quantangshi','','卷40','相辞因避世，相见尚兵戈。
乱后故人少，别来新话多。
但闻哀痛诏，未覩凯旋歌。
欲结岩栖伴，何山好薜萝。','',''),('quantangshi-39179','和元秀才别业书事','韋莊','quantangshi','','卷40','僻居春事好，水曲乱花阴。
浪过河移岸，雏成鸟别林。
绿钱榆贯重，红障杏篱深。
莫饮宜城酒，愁多醉易沈。','',''),('quantangshi-39180','纪村事','韋莊','quantangshi','','卷40','绿蔓映双扉，循墙一径微。
雨多庭果烂，稻熟渚禽肥。
酿酒迎新社，遥砧送暮晖。','',''),('quantangshi-39181','题许仙师院','韋莊','quantangshi','','卷40','地古多乔木，游人到且吟。
院开金鏁涩，门映绿篁深。
山色不离眼，鹤声长在琴。
往来谁与熟，乳鹿住前林。','',''),('quantangshi-39182','离筵诉酒','韋莊','quantangshi','','卷40','感君情重惜分离，送我殷勤酒满巵。
不是不能判酩酊，却忧前路酒醒时。','',''),('quantangshi-39183','不寐','韋莊','quantangshi','','卷40','不寐天将晓，心劳转似灰。
蚊吟频到耳，鼠鬬竞缘台。
户暗知蟾落，林喧觉雨来。
马嘶朝客过，知是禁门开。','',''),('quantangshi-39184','赠武处士','韋莊','quantangshi','','卷40','一身唯一室，高静若僧家。
扫地留疎影，穿池浸落霞。
绿萝临水合，白道向村斜。
卖药归来醉，吟诗倚钓查。','',''),('quantangshi-39185','题吉涧卢拾遗庄','韋莊','quantangshi','','卷40','主人西游去不归，满溪春雨长春薇。
怪来马上诗情好，印破青山白鹭飞。','',''),('quantangshi-39186','题颍源庙','韋莊','quantangshi','','卷40','曾是巢由栖隐地，百川唯说颍源清。
微波乍向云根吐，去浪遥冲雪嶂横。
万木倚檐疎干直，羣峰当户晓岚晴。
临川试问尧年事，犹被封人劝濯缨。','',''),('quantangshi-39187','东游远归','韋莊','quantangshi','','卷40','扣角干名计已疎，劒歌休恨食无鱼。
辞家柳絮三春半，临路槐花七月初。
江上欲寻渔父醉，日边时得故人书。
青云不识杨生面，天子何由问子虚。','',''),('quantangshi-39188','新正日商南道中作寄李明府','韋莊','quantangshi','','卷40','相看又见岁华新，依旧杨朱拭泪巾。
踏雪偶因寻戴客，论文还比聚星人。
嵩山不改千年色，洛邑长生一路尘。
今日与君同避世，却怜无事是家贫。','',''),('quantangshi-39189','春暮','韋莊','quantangshi','','卷40','一春春事好，病酒起常迟。
流水绿萦砌，落花红堕枝。
楼高喧乳燕，树密鬬雏鹂。
不学山公醉，将何自解颐。','',''),('quantangshi-39190','哭麻处士','韋莊','quantangshi','','卷40','却到歌吟地，闲门草色中。
百年流水尽，万事落花空。
繐帐扃秋月，诗楼鏁夜虫。
少微何处堕，留恨白杨风。','',''),('quantangshi-39191','春早','韋莊','quantangshi','','卷40','闻莺才觉晓，闭户已知晴。
一带窗间月，斜穿枕上生。','',''),('quantangshi-39192','和友人','韋莊','quantangshi','','卷40','闭门同隐士，不出动经时。
静阅王维画，闲翻褚胤棋。
落泉当户急，残月下窗迟。
却想从来意，谯周亦自嗤。','',''),('quantangshi-39193','春愁','韋莊','quantangshi','','卷40','寓思本多伤，逢春恨更长。
露霑湘竹泪，花堕越梅妆。
睡怯交加梦，闲倾潋滟觞。
后庭人不到，斜月上松篁。','',''),('quantangshi-39194','晚春','韋莊','quantangshi','','卷40','花开疑乍富，花落似初贫。
万物不如酒，四时唯爱春。
峨峨秦氏髻，皎皎洛川神。
风月应相笑，年年醉病身。','',''),('quantangshi-39195','题许浑诗卷','韋莊','quantangshi','','卷40','江南才子许浑诗，字字清新句句奇。
十斛明珠量不尽，惠[休]虚作碧云词。','',''),('quantangshi-39196','赠礼佛名者','韋莊','quantangshi','','卷40','何用辛勤礼佛名，我从无得到真庭。
寻思六祖传心印，可是从来读藏经。','',''),('quantangshi-39197','残花','韋莊','quantangshi','','卷40','和烟和露雪离披，金蘂红须尚满枝。
十日笙歌一宵梦，苎萝因雨失西施。','',''),('quantangshi-39198','上元县','韋莊','quantangshi','','卷40','南朝三十六英雄，角逐兴亡尽此中。
有国有家皆是梦，为龙为虎亦成空。
残花旧宅悲江令，落日青山吊谢公。
止竟霸图何物在，石麟无主卧秋风。','',''),('quantangshi-39199','江上逢史馆李学士','韋莊','quantangshi','','卷40','前年分袂陕城西，醉凭征轩日欲低。
去浪指期鱼必变，出门回首马空嘶。
关河自此为征垒，城阙于今陷战鼙。
谁谓世途陵是谷，燕来还识旧巢泥。','',''),('quantangshi-39200','金陵图','韋莊','quantangshi','','卷40','谁谓伤心画不成，画人心逐世人情。
君看六幅南朝事，老木寒云满故城。','',''),('quantangshi-39201','谒蒋帝庙','韋莊','quantangshi','','卷40','建业城边蒋帝祠，素髯清骨旧风姿。
江声似激秦军破，山势如匡晋祚危。
残雪岭头明组练，晚霞檐外簇旌旗。
金陵客路方流落，空祝回銮奠酒巵。','',''),('quantangshi-39202','闻再幸梁洋','韋莊','quantangshi','','卷40','才喜中原息战鼙，又闻天子幸巴西。
延烧魏阙非关燕，大狩陈仓不为鸡。
兴庆玉龙寒自跃，昭陵石马夜空嘶。
遥思万里行宫梦，太白山前月欲低。','',''),('quantangshi-39203','王道者','韋莊','quantangshi','','卷40','五云遥指海中央，金鼎曾传肘后方。
三岛路岐空有月，十洲花木不知霜。
因携竹杖闻龙气，为使仙童带橘香。
应笑我曹身是梦，白头犹自学诗狂。','',''),('quantangshi-39204','陪金陵府相中堂夜宴','韋莊','quantangshi','','卷40','满耳笙歌满眼花，满楼珠翠胜吴娃。
因知海上神仙窟，只似人间富贵家。
绣户夜攒红烛市，舞衣晴曳碧天霞。
却愁宴罢青蛾散，杨子江头月半斜。','',''),('quantangshi-39205','和侯秀才同友生泛舟溪中相招之作','韋莊','quantangshi','','卷40','嵇阮相将棹酒船，晚风侵浪水侵舷。
轻如控鲤初离岸，远似乘槎欲上天。
雨外鸟归吴苑树，镜中人入洞庭烟。
凭君不用回舟疾，今夜西江月正圆。','',''),('quantangshi-39206','赠野童','韋莊','quantangshi','','卷40','羡尔无知野性真，乱搔蓬发笑看人。
闲冲暮雨骑牛去，肯问中兴社稷臣。','',''),('quantangshi-39207','代书寄马','韋莊','quantangshi','','卷40','驱驰曾在五侯家，见说初生自渥洼。
鬃白似披梁苑雪，颈肥如扑杏园花。
休嫌绿绶嘶贫舍，好着红缨入使衙。
稳上云衢千万里，年年长踏魏堤沙。','',''),('quantangshi-39208','题淮阴侯庙','韋莊','quantangshi','','卷40','满把椒浆奠楚祠，碧幢黄钺旧英威。
能扶汉代成王业，忍见唐民陷战机。
云梦去时高鸟尽，淮阴归日故人稀。
如何不借平齐策，空看长星落贼围。','',''),('quantangshi-39209','送崔郎中往使西川行在','韋莊','quantangshi','','卷40','拜书辞玉帐，万里劒关长。
新马杏花色，绿袍春草香。
一身朝玉陛，几日过铜梁。
莫恋炉边醉，仙宫待侍郎。','',''),('quantangshi-39210','润州显济阁晓望','韋莊','quantangshi','','卷40','清晓水如镜，隔江人似鸥。
远烟藏海岛，初日照扬州。
地壮孙权气，云凝庾信愁。
一篷何处客，吟凭钓鱼舟。','',''),('quantangshi-39211','观淛西府相畋游','韋莊','quantangshi','','卷40','十里旌旗十万兵，等闲游猎出军城。
紫袍日照金鹅鬬，红斾风吹画虎狞。
带箭彩禽云外落，避雕寒兔月中惊。
归来一路笙歌满，更有仙娥载酒迎。','',''),('quantangshi-39212','官庄','韋莊','quantangshi','','卷40','谁氏园林一簇烟，路人遥指尽长叹。
桑田稻泽今无主，新犯香醪没入官。','',''),('quantangshi-39213','解维','韋莊','quantangshi','','卷40','又解征帆落照中，暮程还过秣陵东。
二年辛苦烟波里，赢得风姿似钓翁。','',''),('quantangshi-39214','雨霁池上作呈侯学士','韋莊','quantangshi','','卷40','鹿巾藜杖葛衣轻，雨歇池边晚吹清。
正是如今江上好，白鳞红稻紫莼羹。','',''),('quantangshi-39215','寓言','韋莊','quantangshi','','卷40','为儒逢世乱，吾道欲何之。
学劒已应晚，归山今又迟。
故人三载别，明月两乡悲。
惆怅沧江上，星星鬓有丝。','',''),('quantangshi-39216','哭同舍崔员外','韋莊','quantangshi','','卷40','却到同游地，三年一电光。
池塘春草在，风烛故人亡。
祭罢泉声急，斋余磬韵长。
碧天应有恨，斜日吊松篁。','',''),('quantangshi-39217','题姑苏凌处士庄','韋莊','quantangshi','','卷40','一簇林亭返照间，门当官道不曾关。
花深远岸黄莺闹，雨急春塘白鹭闲。
载酒客寻吴苑寺，倚楼僧看洞庭山。
怪来话得仙中事，新有人从物外还。','',''),('quantangshi-39218','过当涂县','韋莊','quantangshi','','卷40','客过当涂县，停车访旧游。
谢公山有墅，李白酒无楼。
采石花空发，乌江水自流。
夕阳谁共感，寒鹭立汀洲。','',''),('quantangshi-39219','江亭酒醒却寄维扬饯客','韋莊','quantangshi','','卷40','别筵人散酒初醒，江步黄昏雨雪零。
满坐绮罗皆不见，觉来红树背银屏。','',''),('quantangshi-39220','台城','韋莊','quantangshi','','卷40','江雨霏霏江草齐，六朝如梦鸟空啼。
无情最是台城柳，依旧烟笼十里堤。','',''),('quantangshi-39221','赠渔翁','韋莊','quantangshi','','卷40','草衣荷笠鬓如霜，自说家编楚水阳。
满岸秋风吹枳橘，遶陂烟雨种菰蒋。
芦刀夜鲙红鳞腻，水甑朝蒸紫芋香。
曾向五湖期范蠡，尔来空阔久相忘。','',''),('quantangshi-39222','过扬州','韋莊','quantangshi','','卷40','当年人未识兵戈，处处青楼夜夜歌。
花发洞中春日永，月明衣上好风多。
淮王去后无鸡犬，炀帝归来葬绮罗。
二十四桥空寂寂，绿杨摧折旧官河。','',''),('quantangshi-39223','寄右省李起居','韋莊','quantangshi','','卷40','已向鸳行接雁行，便应双拜紫薇郎。
才闻阙下征书急，已觉回朝草诏忙。
白马似怜朱绂贵，彩衣遥惹御炉香。
多慙十载游梁客，未换青襟侍素王。','',''),('quantangshi-39224','镊白','韋莊','quantangshi','','卷40','白发太无情，朝朝镊又生。
始因丝一缕，渐至雪千茎。
不避佳人笑，唯慙稚子惊。
新年过半百，犹叹未休兵。','',''),('quantangshi-39225','漳亭驿小樱桃','韋莊','quantangshi','','卷40','当年此树正花开，五马仙郎载酒来。
李白已亡工部死，何人堪伴玉山颓。','',''),('quantangshi-39226','酬吴秀才霅川相送','韋莊','quantangshi','','卷40','一叶南浮去似飞，楚乡云水本无依。
离心不忍闻春鸟，病眼何堪送落晖。
掺袂客从花下散，棹舟人向镜中归。
夫君别我应惆怅，十五年来识素衣。','',''),('quantangshi-39227','对雨独酌','韋莊','quantangshi','','卷40','榴花新酿绿于苔，对雨闲倾满满杯。
荷锸醉翁真达者，卧云逋客竟悠哉。
能诗岂是经时策，爱酒原非命世才。
门外绿萝连洞口，马嘶应是步兵来。','',''),('quantangshi-39228','夏初与侯补阙江南有约同泛淮汴西赴行朝庄自九驿路先至甬桥补阙由淮楚续至泗上寝病旬日遽闻捐馆回首悲恸因成长句四韵吊之','韋莊','quantangshi','','卷40','本约同来谒帝阍，忽随川浪去东奔。
九重圣主方虚席，千里高堂尚倚门。
世德只应荣伯仲，诗名终自付儿孙。
遥怜月落清淮上，寂寞何人吊旅魂。','',''),('quantangshi-39229','汴堤行','韋莊','quantangshi','','卷40','欲上隋堤举步迟，隔云烽燧呌非时。
才闻破虏将休马，又道征辽再出师。
朝见西来为过客，暮看东去作浮尸。
绿杨千里无飞鸟，日落空投旧店基。','',''),('quantangshi-39230','旅次甬西见儿童以竹枪纸旗戏为阵列主人叟曰斯子也三世没于阵思所袭祖父讐余因感之','韋莊','quantangshi','','卷40','已闻三世没军营，又见儿孙学战争。
见尔此言堪恸哭，遣予何日望时平。','',''),('quantangshi-39231','自孟津舟西上雨中作','韋莊','quantangshi','','卷40','秋烟漠漠与蒙蒙，不卷征帆任晚风。
百口寄安沧海上，一身逃难绿林中。
来时楚岸杨花白，去日隋堤蓼穗红。
却到故园翻似客，归心迢递秣陵东。','',''),('quantangshi-39232','含山店梦觉作','韋莊','quantangshi','','卷40','曾为流离惯别家，等闲挥袂客天涯。
灯前一觉江南梦，惆怅起来山月斜。','',''),('quantangshi-39233','题貂黄岭官军','韋莊','quantangshi','','卷40','散骑萧萧下太行，远从吴会去陈仓。
斜风细雨江亭上，尽日凭栏忆楚乡。','',''),('quantangshi-39234','过内黄县','韋莊','quantangshi','','卷40','相州吹角欲斜阳，匹马摇鞭宿内黄。
僻县不容投刺客，野陂时遇射雕郎。
云中粉堞新城垒，店后荒郊旧战场。
犹指去程千万里，秣陵烟树在何乡。','',''),('quantangshi-39235','杂感','韋莊','quantangshi','','卷40','莫悲建业荆榛满，昔日繁华是帝京。
莫爱广陵台榭好，也曾芜没作荒城。
鱼龙爵马皆如梦，风月烟花岂有情。
行客不劳频怅望，古来朝市叹衰荣。','',''),('quantangshi-39236','垣县山中寻李书记山居不遇留题河次店','韋莊','quantangshi','','卷40','白云红树𡵻㟍东，名鸟羣飞古画中。
仙吏不知何处隐，山南山北雨蒙蒙。','',''),('quantangshi-39237','送人游并汾','韋莊','quantangshi','','卷40','风雨萧萧欲暮秋，独携孤劒塞垣游。
如今虏骑方南牧，莫过阴关第一州。','',''),('quantangshi-39238','李氏小池亭十二韵','韋莊','quantangshi','','卷40','积石乱巉巉，庭莎绿不芟。
小桥低跨水，危槛半依岩。
花落鱼争唼，樱红鸟竞鹐。
引泉疏地脉，扫絮积山嵌。
古柳红绡织，新篁紫绮缄。
养猿秋啸月，放鹤夜栖杉。
枕簟溪云腻，池塘海雨咸。
语窗鸡逞辨，舐鼎犬偏馋。
踏藓青粘屐，攀萝绿映衫。
访僧舟北渡，贳酒日西衔。
迟客登高阁，题诗遶翠岩。
家藏何所宝，清韵满琅函。','',''),('quantangshi-39239','遣兴','韋莊','quantangshi','','卷40','如幻如泡世，多愁多病身。
乱来知酒圣，贫去觉钱神。
异国清明节，空江寂寞春。
声声林上鸟，唤我北归秦。','',''),('quantangshi-39240','婺州和陆谏议将赴阙怀阳羡山居','韋莊','quantangshi','','卷40','望阙路仍远，子牟魂欲飞。
道开烧药鼎，僧寄卧云衣。
故国饶芳草，他山挂夕晖。
东阳虽胜地，王粲奈思归。','',''),('quantangshi-39241','江上题所居','韋莊','quantangshi','','卷40','故人相别尽朝天，苦竹江头独闭关。
落日乱蝉萧帝寺，碧云归鸟谢家山。
青州从事来偏熟，泉布先生老渐悭。
不是对花长酩酊，永嘉时代不如闲。','',''),('quantangshi-39242','婺州屏居蒙右省王拾遗车枉降访病中延候不得因成寄谢','韋莊','quantangshi','','卷40','三年流落卧漳滨，王粲思家拭泪频。
画角莫吹残月夜，病心方忆故园春。
自为江上樵苏客，不识天边侍从臣。
怪得白鸥惊去尽，绿萝门外有朱轮。','',''),('quantangshi-39243','将卜兰芷村居留别郡中在仕','韋莊','quantangshi','','卷40','兰芷江头寄断蓬，移家空载一颿风。
伯伦嗜酒还因乱，平子归田不为穷。
避世漂零人境外，结茅依约画屏中。
从今隐去应难觅，深入芦花作钓翁。','',''),('quantangshi-39244','和陆谏议避地寄东阳进退未决见寄','韋莊','quantangshi','','卷40','未归天路紫云深，暂驻东阳岁月侵。
入洛声华当世重，闵周章句满朝吟。
开炉夜看黄芽鼎，卧瓮闲欹白玉簪。
读易草玄人不会，忧君心是致君心。','',''),('quantangshi-39245','山墅闲题','韋莊','quantangshi','','卷40','逦迤前冈压后冈，一川桑柘好残阳。
主人馈饷炊红黍，邻父携竿钓紫鲂。
静极却嫌流水闹，闲多翻笑野云忙。
有名不那无名客，独闭衡门避建康。','',''),('quantangshi-39246','江上逢故人','韋莊','quantangshi','','卷40','前年送我曲江西，红杏园中醉似泥。
今日逢君越溪上，杜鹃花发鹧鸪啼。
来时旧里人谁在，别后沧波路几迷。
江畔玉楼多美酒，仲宣怀土莫凄凄。','',''),('quantangshi-39247','旅中感遇寄呈李秘书昆仲','韋莊','quantangshi','','卷40','南望愁云鏁翠微，谢家楼阁雨霏霏。
刘桢病后新诗少，阮籍贫来好客稀。
犹喜故人天外至，许将孤劒日边归。
怀乡不怕严陵笑，只待秋风别钓矶。','',''),('quantangshi-39248','送范评事入关','韋莊','quantangshi','','卷40','寂寥门户寡相亲，日日频来只有君。
正喜琴尊长作伴，忽携书劒远辞羣。
伤心柳色离亭见，聒耳蝉声故国闻。
为报明年杏园客，与留绝艳待终军。','',''),('quantangshi-39249','东阳酒家赠别二绝句 一','韋莊','quantangshi','','卷40','送君同上酒家楼，酩酊翻成一笑休。
正是落花饶怅望，醉乡前路莫回头。','',''),('quantangshi-39250','东阳酒家赠别二绝句 二','韋莊','quantangshi','','卷40','天涯方叹异乡身，又向天涯别故人。
明日五更孤店月，醉醒何处泪霑巾。','',''),('quantangshi-39251','江上村居','韋莊','quantangshi','','卷40','本无踪迹恋柴扃，世乱须教识道情。
顚倒梦魂愁里得，撅奇诗句望中生。
花缘艳绝栽难好，山为看多咏不成。
闻道汉军新破虏，使来仍说近离京。','',''),('quantangshi-39252','江外思乡','韋莊','quantangshi','','卷40','年年春日异乡悲，杜曲黄莺可得知。
更被夕阳江岸上，断肠烟柳一丝丝。','',''),('quantangshi-39253','和郑拾遗秋日感事一百韵','韋莊','quantangshi','','卷40','祸乱天心厌，流离客思伤。
有家抛上国，无罪谪遐方。
负笈将辞越，扬帆欲泛湘。
避时难驻足，感事易回肠。
雅道何销德，妖星忽耀芒。
中原初纵燎，下国竟探汤。
盗据三秦地，兵缠八水乡。
战尘轻犯阙，羽斾远巡梁。
自此修文代，俄成讲武场。
熊罴驱涿鹿，犀象走昆阳。
御马迷新栈，宫娥改旧妆。
五丁功再覩，八难事难忘。
凤引金根疾，兵环玉弩彊。
建牙虽可恃，摩垒讵能防。
霍庙神遐远，圯桥路杳茫。
出师威似虎，御敌狠如羊。
眉画犹思赤，巾裁未厌黄。
晨趋鸣铁骑，夜舞挹琼觞。
僭侈彤襜乱，喧呼绣𩭪攘。
但闻争曳组，讵见学垂缰。
鹊印提新篆，龙泉夺晓霜。
军威徒逗挠，我武自维扬。
负扆劳天眷，凝旒念国章。
绣旗张画兽，宝马跃红鸯。
但欲除妖气，宁思蔽耿光。
晓烟生帝里，夜火入春坊。
鸟怪巢宫树，狐骄上苑墙。
设危终在德，视履岂无祥。
气激雷霆怒，神驱岳渎忙。
功高分虎节，位下耻龙骧。
遍命登坛将，巡封异姓王。
志求扶坠典，力未振颓纲。
汉路闲雕鹗，云衢驻驌驦。
宝装军器丽，麝裛战袍香。
日覩兵书捷，时闻虏骑亡。
人心惊獬豸，雀意伺螳螂。
上略咸推妙，前锋讵可当。
纡金光照耀，执玉意藏昂。
覆餗非无谓，奢华事每详。
四民皆组绶，九土堕耕桑。
飞骑黄金勒，香车翠钿装。
八珍罗膳府，五采鬬筐牀。
宴集喧华第，歌钟簇画梁。
永期传子姓，宁误犯天狼。
未覩君除侧，徒思玉在傍。
窜身奚可保，易地喜相将。
国运方夷险，天心讵测量。
九流虽暂蔽，三柄岂相妨。
小孽乖躔次，中兴系昊苍。
法尧功已普，罪己德非凉。
帝念惟思理，臣心岂自遑。
诏催青琐客，时待紫微郎。
定难输宸算，胜灾减御粱。
皇恩思荡荡，睿泽转洋洋。
偃卧虽非晚，艰难亦备尝。
舜庭招谏鼓，汉殿上书囊。
俭德遵三尺，清朝俟一匡。
世随渔父醉，身效接舆狂。
窜逐同天宝，遭罹异建康。
道孤悲海澨，家远隔天潢。
卒岁贫无褐，经秋病泛漳。
似鱼甘去乙，比蟹未成筐。
守道慙无补，趋时愧不臧。
殷牛常在耳，晋竖欲潜肓。
忸恨山思板，怀归海欲航。
角吹魂悄悄，笛引泪浪浪。
乱觉干坤窄，贫知日月长。
势将随鹤列，忽喜遇鸳行。
已报新回驾，仍闻近纳隍。
文风销劒楯，礼物换旗裳。
紫闼重开序，青衿再设庠。
黑头期命爵，頳尾尚忧鲂。
吴坂嘶骐骥，岐山集凤皇。
词源波浩浩，谏署玉锵锵。
饲雀曾传庆，烹蛇讵有殃。
[弢]弓挥劲镞，匣劒淬神铓。
谔谔宁慙直，堂堂不谢张。
晓风趋建礼，夜月直文昌。
去国时虽久，安邦志不常。
良金炉自跃，美玉椟难藏。
北望心如斾，西归律变商。
迹随江燕去，心逐塞鸿翔。
晚翠笼桑坞，斜晖挂竹堂。
路愁千里月，田爱万斯箱。
伴钓歌前浦，随樵上远冈。
鹭眠依晚屿，鸟浴上枯杨。
惊梦缘欹枕，多吟为倚廊。
访僧红叶寺，题句白云房。
颿外青枫老，尊前紫菊芳。
夜灯银耿耿，晓露玉瀼瀼。
异国慙倾盖，归涂俟并粮。
身虽留震泽，心已过雷塘。
执友知谁在，家山各已荒。
海边登桂檝，烟外泛云樯。
巢树禽思越，嘶风马恋羌。
寒声愁听杵，空馆厌闻螿。
望阙飞华盖，趋朝振玉璫。
米慙无薏苡，面喜有桄榔。
话别心重结，伤时泪一滂。
伫归蓬岛后，纶诏润青缃。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-39254','梦入关','韋莊','quantangshi','','卷40','梦中乘传过关亭，南望莲峰簇簇青。
马上正吟归去好，觉来江月满前庭。','',''),('quantangshi-39255','送人归上国','韋莊','quantangshi','','卷40','送君江上日西斜，泣向江边满树花。
若见青云旧相识，为言流落在天涯。','',''),('quantangshi-39256','闻春鸟','韋莊','quantangshi','','卷40','云晴春鸟满江村，还似长安旧日闻。
红杏花前应笑我，我今顦顇亦羞君。','',''),('quantangshi-39257','樱桃树','韋莊','quantangshi','','卷40','记得初生雪满枝，和蜂和蝶带花移。
而今花落游蜂去，空作主人惆怅诗。','',''),('quantangshi-39258','独鹤','韋莊','quantangshi','','卷40','夕阳滩上立裴回，红蓼风前雪翅开。
应为不知栖宿处，几回飞去又飞来。','',''),('quantangshi-39259','新栽竹','韋莊','quantangshi','','卷40','寂寞堦前见此君，遶栏吟罢却沾巾。
异乡流落谁相识，唯有丛篁似主人。','',''),('quantangshi-39260','稻田','韋莊','quantangshi','','卷40','绿波春浪满前陂，极目连云䆉稏肥。
更被鹭鷀千点雪，破烟来入画屏飞。','',''),('quantangshi-39261','稻田','韋莊','quantangshi','','卷40','浪波春稻满前坡，极目连云𥝧稏肥。
更被鹭鸶千㸃白，披烟来入画屏飞。','',''),('quantangshi-39262','庭前菊','韋莊','quantangshi','','卷40','为忆长安烂熳开，我今移尔满庭栽。
红兰莫笑青青色，曾向龙山泛酒来。','',''),('quantangshi-39263','燕来','韋莊','quantangshi','','卷40','去岁辞巢别近邻，今来空讶草堂新。
花开对语应相问，不是村中旧主人。','',''),('quantangshi-39264','倚柴关','韋莊','quantangshi','','卷40','杖策无言独倚关，如痴如醉又如闲。
孤吟尽日何人会，依约前山似故山。','',''),('quantangshi-39265','题七步廊','韋莊','quantangshi','','卷40','席门无计那残阳，更接檐前七步廊。
不羡东都丞相宅，每行吟得好篇章。','',''),('quantangshi-39266','语松竹','韋莊','quantangshi','','卷40','庭前芳草绿于袍，堂上诗人欲二毛。
多病不禁秋寂寞，雨松风竹莫骚骚。','',''),('quantangshi-39267','不出院楚公','韋莊','quantangshi','','卷40','一自蝉关闭，心猿日渐驯。
不知城郭路，稀识市朝人。
履带堦前雪，衣无寺外尘。
却嫌山翠好，诗客往来频。','',''),('quantangshi-39268','江边吟','韋莊','quantangshi','','卷40','江边烽燧几时休，江上行人雪满头。
谁信乱离花不见，只应惆怅水东流。
陶潜政事千杯酒，张翰生涯一叶舟。
若有片颿归去好，可堪重倚仲宣楼。','',''),('quantangshi-39269','江南送李明府入关','韋莊','quantangshi','','卷40','雨花烟柳傍江邨，流落天涯酒一罇。
分首不辞多下泪，回头唯恐更消魂。
我为孟馆三千客，君继宁王五代孙。
正是中兴磐石重，莫将顦顇入都门。','',''),('quantangshi-39270','送福州王先辈南归','韋莊','quantangshi','','卷40','豫章城下偶相逢，自说今方遇至公。
八韵赋吟梁苑雪，六铢衣惹杏园风。
名标玉籍仙坛上，家寄闽山画障中。
明日一杯何处别，绿杨烟岸雨蒙蒙。','',''),('quantangshi-39271','夜雪泛舟游南溪','韋莊','quantangshi','','卷40','大江西面小溪斜，入竹穿松似若耶。
两岸严风吹玉树，一滩明月晒银砂。
因寻野渡逢渔舍，更泊前湾上酒家。
去去不知归路远，棹声烟里独呕哑。','',''),('quantangshi-39272','江行西望','韋莊','quantangshi','','卷40','西望长安白日遥，半年无事驻兰桡。
欲将张翰秋江雨，画作屏风寄鲍昭。','',''),('quantangshi-39273','铜仪','韋莊','quantangshi','','卷40','铜仪一夜变葭灰，暖律还吹岭上梅。
已喜汉官今再覩，更惊尧历又重开。
窗中远岫青如黛，门外长江绿似苔。
谁念闭关张仲蔚，满庭春雨长蒿莱。','',''),('quantangshi-39274','含香','韋莊','quantangshi','','卷40','含香高步已难陪，鹤到清霄势未回。
遇物旋添芳草句，逢春宁滞碧云才。
微红几处花心吐，嫩绿谁家柳眼开。
却去金銮为近侍，便辞鸥鸟不归来。','',''),('quantangshi-39275','春云','韋莊','quantangshi','','卷40','春云春水两溶溶，倚郭楼台晚翠浓。
山好只因人化石，地灵曾有劒为龙。
官辞凤阙频经岁，家住峨嵋第几峰。
王粲不知多少恨，夕阳吟断一声钟。','',''),('quantangshi-39276','云散','韋莊','quantangshi','','卷40','云散天边落照和，关关春树鸟声多。
刘伶避世唯沈醉，甯戚伤时亦浩歌。
已恨岁华添皎镜，更悲人事逐颓波。
青云自有鵷鸿待，莫说他山好薜萝。','',''),('quantangshi-39277','袁州作','韋莊','quantangshi','','卷40','家家生计只琴书，一郡清风似鲁儒。
山色东南连紫府，水声西北属洪都。
烟霞尽入新诗卷，郭邑闲开古画图。
正是江村春酒熟，更闻春鸟劝提壶。','',''),('quantangshi-39278','题袁州谢秀才所居','韋莊','quantangshi','','卷40','主人年少已能诗，更有松轩挂夕晖。
芳草似袍连径合，白云如鸟傍檐飞。
但将竹叶消春恨，莫遣杨花上客衣。
若有前山好烟雨，与君吟到暝钟归。','',''),('quantangshi-39279','谒巫山庙','韋莊','quantangshi','','卷40','乱猿啼处访高唐，路入烟霞草木香。
山色未能忘宋玉，水声犹似哭襄王。
朝朝暮暮阳台下，为雨为云楚国亡。
惆怅庙前无限柳，春来空鬬画眉长。','',''),('quantangshi-39280','鹧鸪','韋莊','quantangshi','','卷40','南禽无侣似相依，锦翅双双傍马飞。
孤竹庙前啼暮雨，汨罗祠畔吊残晖。
秦人只解歌为曲，越女空能画作衣。
懊恼泽家非有恨，年年长忆凤城归。','',''),('quantangshi-39281','宿蓬船','韋莊','quantangshi','','卷40','夜来江雨宿蓬船，卧听淋铃不忍眠。
却忆紫微情调逸，阻风中酒过年年。','',''),('quantangshi-39282','送李秀才归荆溪','韋莊','quantangshi','','卷40','八月中秋月正圆，送君吟上木兰船。
人言格调胜玄度，我爱篇章敌浪仙。
晚渡去时冲细雨，夜滩何处宿寒烟。
楚王宫去阳台近，莫倚风流滞少年。','',''),('quantangshi-39283','洪州送西明寺省上人游福建','韋莊','quantangshi','','卷40','记得初骑竹马年，送师来往御沟边。
荆榛已失当时路，槐柳全无旧日烟。
远自嵇山游楚泽，又从庐岳去闽川。
新春阙下应相见，红杏花中觅酒仙。','',''),('quantangshi-39284','建昌渡暝吟','韋莊','quantangshi','','卷40','月照临官渡，乡情独浩然。
鸟栖彭蠡树，月上建昌船。
市散渔翁醉，楼深贾客眠。
隔江何处笛，吹断绿杨烟。','',''),('quantangshi-39285','岁除对王秀才作','韋莊','quantangshi','','卷40','我惜今宵促，君愁玉漏频。
岂知新岁酒，犹作异乡身。
雪向寅前冻，花从子后春。
到明追此会，俱是隔年人。','',''),('quantangshi-39286','酒渴爱江清','韋莊','quantangshi','','卷40','酒渴何方疗，江波一掬清。
泻瓯如练色，漱齿作泉声。
味带他山雪，光含白露精。
只应千古后，长称伯伦情。','',''),('quantangshi-39287','和李秀才郊墅早春吟兴十韵','韋莊','quantangshi','','卷40','暖律变寒光，东君景渐长。
我悲游海峤，君说住柴桑。
雪色随高岳，冰声陷古塘。
草根微吐翠，梅朵半含霜。
酒市多逋客，渔家足夜航。
匡庐云傍屋，彭蠡浪冲牀。
绿摆杨枝嫩，红挑菜甲香。
凤皇城已尽，鹦鹉赋应狂。
伫见龙辞沼，宁忧雁失行。
不应双劒气，长在斗牛傍。','',''),('quantangshi-39288','泛鄱阳湖','韋莊','quantangshi','','卷40','四顾无边鸟不飞，大波惊隔楚山微。
纷纷雨外灵均过，瑟瑟云中帝子归。
迸鲤似梭投远浪，小舟如叶傍斜晖。
鸱夷去后何人到，爱者虽多见者稀。','',''),('quantangshi-39289','黄藤山下闻猿','韋莊','quantangshi','','卷40','黄藤山下驻归程，一夜号猿吊旅情。
入耳便能生百恨，断肠何必待三声。
穿云宿处人难见，望月啼时兔正明。
好笑五陵年少客，壮心无事也沾缨。','',''),('quantangshi-39290','章江作','韋莊','quantangshi','','卷40','杜陵归客正裴回，玉笛谁家呌落梅。
之子棹从天外去，故人书自日边来。
杨花慢惹霏霏雨，竹叶闲倾满满杯。
欲问维扬旧风月，一江红树乱猿哀。','',''),('quantangshi-39291','南游富阳江中作','韋莊','quantangshi','','卷40','南去又南去，此行非自期。
一帆云作伴，千里月相随。
浪迹花应笑，衰容镜每知。
乡园不可问，禾黍正离离。','',''),('quantangshi-39292','饶州余干县琵琶洲有故韩宾客宣城裴尚书修行李侍郎旧居遗址犹存客有过之感旧因以和吟','韋莊','quantangshi','','卷40','琵琶洲近斗牛星，鸾凤曾于此放情。
已觉地灵因昴降，更闻川媚有珠生。
一滩红树留佳气，万古清弦续政声。
戟户尽移天上去，里人空说旧簪缨。','',''),('quantangshi-39293','九江逢卢员外','韋莊','quantangshi','','卷40','前年风月宿琴堂，大媚仙山近帝乡。
别后几沾新雨露，乱来犹记旧篇章。
陶潜岂是铜符吏，田凤终为锦帐郎。
莫怪相逢倍惆怅，九江烟月似潇湘。','',''),('quantangshi-39294','南昌晚眺','韋莊','quantangshi','','卷40','南昌城郭枕江烟，章水悠悠浪拍天。
芳草绿遮仙尉宅，落霞红衬贾人船。
霏霏阁上千山雨，嘒嘒云中万树蝉。
怪得地多章句客，庾家楼在斗牛边。','',''),('quantangshi-39295','衢州江上别李秀才','韋莊','quantangshi','','卷40','千山红树万山云，把酒相看日又曛。
一曲离歌两行泪，更知何地再逢君。','',''),('quantangshi-39296','湘中作','韋莊','quantangshi','','卷40','千重烟树万重波，因便何妨吊汨罗。
楚地不知秦地乱，南人空怪北人多。
臣心未肯教迁鼎，天道还应欲止戈。
否去泰来终可待，夜寒休唱饭牛歌。','',''),('quantangshi-39297','桐庐县作','韋莊','quantangshi','','卷40','钱塘江尽到桐庐，水碧山青画不如。
白羽鸟飞严子濑，绿蓑人钓季鹰鱼。
潭心倒影时开合，谷口闲云自卷舒。
此境只应词客爱，投文空吊木玄虚。','',''),('quantangshi-39298','东阳赠别','韋莊','quantangshi','','卷40','绣袍公子出旌旗，送我摇鞭入翠微。
大抵行人难诉酒，就中辞客易沾衣。
去时此地题桥去，归日何年佩印归。
无限别情言不得，回看溪柳恨依依。','',''),('quantangshi-39299','寄湖州舍弟','韋莊','quantangshi','','卷40','半年江上怆离襟，把得新诗喜又吟。
多病似逢秦氏药，久贫如得顾家金。
云烟但有穿杨志，尘土多无作吏心。
何况别来词转丽，不愁明代少知音。','',''),('quantangshi-39300','信州西三十里山名仙人城下有月岩山其状秀拔中有山门如满月之状余因行役过其下聊赋是诗','韋莊','quantangshi','','卷40','驱车过闽越，路出饶阳西。
仙山翠如画，簇簇生虹霓。
羣峰若侍从，众阜如婴提。
岩峦互吞吐，岭岫相追携。
中有月轮满，皎洁如圆圭。
玉皇恣游览，到此神应迷。
常娥曳霞帔，引我同攀跻。
腾腾上天半，玉镜悬飞梯。
瑶池何悄悄，鸾鹤烟中栖。
回头望尘世，露下寒凄凄。','',''),('quantangshi-39301','婺州水馆重阳日作','韋莊','quantangshi','','卷40','异国逢佳节，凭高独苦吟。
一杯今日醉，万里故园心。
水馆红兰合，山城紫菊深。
白衣虽不至，鸥鸟自相寻。','',''),('quantangshi-39302','避地越中作','韋莊','quantangshi','','卷40','避世移家远，天涯岁已周。
岂知今夜月，还是去年愁。
露果珠沈水，风萤烛上楼。
伤心潘骑省，华发不禁秋。','',''),('quantangshi-39303','抚州江口雨中作','韋莊','quantangshi','','卷40','江上闲冲细雨行，满衣风洒绿荷声。
金骝掉尾横鞭望，犹指庐陵半日程。','',''),('quantangshi-39304','信州溪岸夜吟作','韋莊','quantangshi','','卷40','夜倚临溪店，怀乡独苦吟。
月当山顶出，星倚水湄沈。
雾气渔灯冷，钟声谷寺深。
一城人悄悄，琪树宿仙禽。','',''),('quantangshi-39305','访浔阳友人不遇','韋莊','quantangshi','','卷40','不见安期悔上楼，寂寥人对鹭鸶愁。
芦花雨急江烟暝，何处潺潺独棹舟。','',''),('quantangshi-39306','东林寺再遇僧益大德','韋莊','quantangshi','','卷40','见师初事懿皇朝，三殿归来白马骄。
上讲每教倾国听，承恩偏得内官饶。
当时可爱人如画，今日相逢鬓已凋。
若向君门逢旧友，为传音信到云霄。','',''),('quantangshi-39307','西塞山下作','韋莊','quantangshi','','卷40','西塞山前水似蓝，乱云如絮满澄潭。
孤峰渐映湓城北，片月斜生梦泽南。
爨动晓烟烹紫蕨，露和香蔕摘黄柑。
他年却棹扁舟去，终傍芦花结一庵。','',''),('quantangshi-39308','齐安郡','韋莊','quantangshi','','卷40','弥棹齐安郡，孤城百战残。
傍村林有虎，带郭县无官。
暮角梅花怨，清江桂影寒。
黍离缘底事，撩我起长叹。','',''),('quantangshi-39309','夏口行寄婺州诸弟','韋莊','quantangshi','','卷40','回头烟树各天涯，婺女星边远寄家。
尽眼楚波连梦泽，满衣春雪落江花。
双双得伴争如雁，一一归巢却羡鵶。
谁道我随张博望，悠悠空外泛仙槎。','',''),('quantangshi-39310','南省伴直','韋莊','quantangshi','','卷40','文昌二十四仙曹，尽倚红檐种露桃。
一洞烟霞人迹少，六行槐柳鸟声高。
星分夜彩寒侵帐，兰惹春香绿映袍。
何事爱留诗客宿，满庭风雨竹萧骚。','',''),('quantangshi-39311','鄠杜旧居二首 一','韋莊','quantangshi','','卷40','却到山阳事事非，谷云溪鸟尚相依。
阮咸贫去田园尽，向秀归来父老稀。
秋雨几家红稻熟，野塘何处锦鳞肥？
年年为献东堂策，长是芦花别钓矶。','',''),('quantangshi-39312','鄠杜旧居二首 二','韋莊','quantangshi','','卷40','一径寻村渡碧溪，稻花香泽水千畦。
云中寺远磬难识，竹里巢深鸟易迷。
紫菊乱开连井合，红榴初绽拂檐低。
归来满把如渑酒，何用伤时叹凤兮。','',''),('quantangshi-39313','寄江南诸弟','韋莊','quantangshi','','卷40','万里逢归雁，乡书忍泪封。
吾身不自保，尔道各何从。
性拙唯多蹇，家贫半为慵。
祗思溪影上，卧看玉华峰。','',''),('quantangshi-39314','投寄旧知','韋莊','quantangshi','','卷40','却将顦顇入都门，自喜青霄足故人。
万里有家留百越，十年无路到三秦。
摧残不是当时貌，流落空余旧日贫。
多谢青云好知己，莫教归去重沾巾。','',''),('quantangshi-39315','癸丑年下第献新先辈','韋莊','quantangshi','','卷40','五更残月省墙边，绛斾霓旌卓晓烟。
千炬火中莺出谷，一声钟后鹤冲天。
皆乘骏马先归去，独被羸童笑晚眠。
对酒暂时情豁尔，见花依旧涕潸然。
未酬阚泽佣书债，犹欠君平卖卜钱。
何事欲休休不得，来年公道似今年。','',''),('quantangshi-39316','题汧阳县马跑泉李学士别业','韋莊','quantangshi','','卷40','水满寒塘菊满篱，篱边无限彩禽飞。
西园夜雨红樱熟，南亩清风白稻肥。
草色自留闲客住，泉声如待主人归。
九霄岐路忙于火，肯恋斜阳守钓矶。','',''),('quantangshi-39317','绛州过夏留献郑尚书','韋莊','quantangshi','','卷40','朝朝沈醉引金船，不觉西风满树蝉。
光景暗消银烛下，梦魂长寄玉轮边。
因循每被时流诮，奋发须由国士怜。
明月客肠何处断，绿槐风里独扬鞭。','',''),('quantangshi-39318','绥州作','韋莊','quantangshi','','卷40','雕阴无树水难流，雉堞连云古帝州。
带雨晚驼鸣远戍，望乡孤客倚高楼。
明妃去日花应笑，蔡琰归时鬓已秋。
一曲单于暮烽起，扶苏城上月如钩。','',''),('quantangshi-39319','与东吴生相遇','韋莊','quantangshi','','卷40','十年身事各如萍，白首相逢泪满缨。
老去不知花有态，乱来唯觉酒多情。
贫疑陋巷春偏少，贵想豪家月最明。
且对一尊开口笑，未衰应见泰阶平。','',''),('quantangshi-39320','庭前桃','韋莊','quantangshi','','卷40','曾向桃源烂漫游，也同渔父泛仙舟。
皆言洞里千株好，未胜庭前一树幽。
带露似垂湘女泪，无言如伴息妫愁。
五陵公子饶春恨，莫引香风上酒楼。','',''),('quantangshi-39321','丙辰年鄜州遇寒食城外醉吟五首 一','韋莊','quantangshi','','卷40','满街杨柳绿丝烟，画出清明二月天。
好是隔帘花树动，女郎撩乱送秋千。','',''),('quantangshi-39322','丙辰年鄜州遇寒食城外醉吟五首 二','韋莊','quantangshi','','卷40','雕阴寒食足游人，金凤罗衣湿麝薰。
肠断入城芳草路，淡红香白一羣羣。','',''),('quantangshi-39323','丙辰年鄜州遇寒食城外醉吟五首 三','韋莊','quantangshi','','卷40','开元坡下日初斜，拜扫归来走钿车。
可惜数株红艳好，不知今夜落谁家。','',''),('quantangshi-39324','丙辰年鄜州遇寒食城外醉吟五首 四','韋莊','quantangshi','','卷40','马骄风疾玉鞭长，过去唯留一阵香。
闲客不须烧破眼，好花皆属富家郎。','',''),('quantangshi-39325','丙辰年鄜州遇寒食城外醉吟五首 五','韋莊','quantangshi','','卷40','雨丝烟柳欲清明，金屋人闲暖凤笙。
永日迢迢无一事，隔街闻筑气球声。','',''),('quantangshi-39326','宜君县比卜居不遂留题王秀才别墅二首 一','韋莊','quantangshi','','卷40','本期同此卧林丘，榾柮炉前拥布裘。
何事却骑羸马去，白云红树不相留。','',''),('quantangshi-39327','宜君县比卜居不遂留题王秀才别墅二首 二','韋莊','quantangshi','','卷40','明月严霜扑皂貂，羡君高卧正逍遥。
门前积雪深三尺，火满红炉酒满瓢。','',''),('quantangshi-39328','鄜州留别张员外','韋莊','quantangshi','','卷40','江南相送君山下，塞北相逢朔漠中。
三楚故人皆是梦，十年陈事只如风。
莫言身世他时异，且喜琴尊数日同。
惆怅却愁明日别，马嘶山店雨蒙蒙。','',''),('quantangshi-39329','病中闻相府夜宴戏赠集贤卢学士','韋莊','quantangshi','','卷40','满筵红蜡照香钿，一夜歌钟欲沸天。
花里乱飞金错落，月中争认绣连干。
尊前莫话诗三百，醉后宁辞酒十千。
无那两三新进士，风流长得饮徒怜。','',''),('quantangshi-39330','出关','韋莊','quantangshi','','卷40','马嘶烟岸柳阴斜，东去关山路转赊。
到处因循缘嗜酒，一生惆怅为判花。
危时祗合身无着，白日那堪事有涯。
正是灞陵春酬绿，仲宣何事独辞家。','',''),('quantangshi-39331','过樊川旧居','韋莊','quantangshi','','卷40','却到樊川访旧游，夕阳衰草杜陵秋。
应刘去后苔生阁，稽阮归来雪满头。
能说乱离惟有燕，解偷闲暇不如鸥。
千桑万海无人见，横笛一声空泪流。','',''),('quantangshi-39332','长安旧里','韋莊','quantangshi','','卷40','满目墙匡春草深，伤时伤事更伤心。
车轮马迹今何在，十二玉楼无处寻。','',''),('quantangshi-39333','过渼陂怀旧','韋莊','quantangshi','','卷40','辛勤曾寄玉峰前，一别云溪二十年。
三径荒凉迷竹树，四邻凋谢变桑田。
渼陂可是当时事，紫阁空余旧日烟。
多少乱离无处问，夕阳吟罢涕潸然。','',''),('quantangshi-39334','汧阳间','韋莊','quantangshi','','卷40','汧水悠悠去似絣，远山如画翠眉横。
僧寻野渡归吴岳，雁带斜阳入渭城。
边静不收蕃帐马，地贫惟卖陇山鹦。
牧童何处吹羌笛，一曲梅花出塞声。','',''),('quantangshi-39335','焦崖阁','韋莊','quantangshi','','卷40','李白曾歌蜀道难，长闻白日上青天。
今朝夜过焦崖阁，始信星河在马前。','',''),('quantangshi-39336','鸡公帻','韋莊','quantangshi','','卷40','石状虽如帻，山形可类鸡。
向风疑欲鬬，带雨似闻啼。
蔓织青笼合，松长翠羽低。
不鸣非有意，为怕客奔齐。','',''),('quantangshi-39337','平陵老将','韋莊','quantangshi','','卷40','白羽金仆姑，腰悬双辘轳。
前年葱岭北，独战云中胡。
匹马塞垣老，一身如鸟孤。
归来辞第宅，却占平陵居。','',''),('quantangshi-39338','即事','韋莊','quantangshi','','卷40','乱世时偏促，阴天日易昏。
无言搔白首，憔悴倚东门。','',''),('quantangshi-39339','姬人养蚕','韋莊','quantangshi','','卷40','昔年爱笑蚕家妇，今日辛勤自养蚕。
仍道不愁罗与绮，女郎初解织桑篮。','',''),('quantangshi-39340','长干塘别徐茂才','韋莊','quantangshi','','卷40','乱离时节别离轻，别酒应须满满倾。
才喜相逢又相送，有情争得似无情。','',''),('quantangshi-39341','勉儿子','韋莊','quantangshi','','卷40','养尔逢多难，常忧学已迟。
辟彊为上相，何必待从师。','',''),('quantangshi-39342','乞彩牋歌','韋莊','quantangshi','','卷40','浣花溪上如花客，绿暗红藏人不识。
留得溪头瑟瑟波，泼成纸上猩猩色。
手把金刀擘彩云，有时翦破秋天碧。
不使红霓段段飞，一时驱上丹霞壁。
蜀客才多染不供，卓文醉后开无力。
孔雀衔来向日飞，翩翩压折黄金翼。
我有歌诗一千首，磨砻山岳罗星斗。
开卷长疑雷电惊，挥毫只怕龙蛇走。
班班布在时人口，满袖松花都未有。
人间无处买烟霞，须知得自神仙手。
也知价重连城璧，一纸万金犹不惜。
薛涛昨夜梦中来，殷勤劝向君边觅。','',''),('quantangshi-39343','白牡丹','韋莊','quantangshi','','卷40','闺中莫妬新妆归，陌上须惭傅粉郎。
昨夜月明浑似水，入门唯觉一庭香。','',''),('quantangshi-39344','悯耕者','韋莊','quantangshi','','卷40','何代何王不战争，尽从离乱见清平。
如今暴骨多于土，犹点乡兵作戍兵。','',''),('quantangshi-39345','壶关道中作','韋莊','quantangshi','','卷40','处处兵戈路不通，却从山北去江东。
黄昏欲到壶关寨，匹马寒嘶野草中。','',''),('quantangshi-39346','题酒家','韋莊','quantangshi','','卷40','酒绿花红客爱诗，落花春岸酒家旗。
寻思避世为逋客，不醉长醒也是痴。','',''),('quantangshi-39347','寄舍弟','韋莊','quantangshi','','卷40','每吟富贵他人合，不觉丸澜又湿衣。
万里日边乡树远，何年何路得同归。','',''),('quantangshi-39348','仆者杨金','韋莊','quantangshi','','卷40','半年辛苦葺荒居，不独单寒腹亦虚。
努力且为田舍客，他年为尔觅金鱼。','',''),('quantangshi-39349','春陌二首 一','韋莊','quantangshi','','卷40','满街芳草卓香车，仙子门前白日斜。
肠断东风各回首，一枝春雪冻梅花。','',''),('quantangshi-39350','春陌二首 二','韋莊','quantangshi','','卷40','嫩烟轻染柳丝黄，句引花枝笑凭墙。
马上王孙莫回首，好风偏逐羽林郎。','',''),('quantangshi-39351','赠姬人','韋莊','quantangshi','','卷40','莫恨红裙破，休嫌白屋低。
请看京与洛，谁在旧香闺。','',''),('quantangshi-39352','中酒','韋莊','quantangshi','','卷40','南邻酒熟爱相招，蘸甲倾来绿满瓢。
一醉不知三日事，任他童穉作渔樵。','',''),('quantangshi-39353','暴雨','韋莊','quantangshi','','卷40','江村入夏多雷雨，晓作狂霖晚又晴。
波浪不知深几许，南湖今与北湖平。','',''),('quantangshi-39354','悼亡姬','韋莊','quantangshi','','卷40','凤去鸾归不可寻，十洲仙路彩云深。
若无少女花应老，为有姮娥月易沈。
竹叶岂能消积恨，丁香空解结同心。','',''),('quantangshi-39355','独吟','韋莊','quantangshi','','卷40','默默无言恻恻悲，闲吟独傍菊花篱。
只今已作经年别，此后如为几岁期。
开箧每寻遗念物，倚楼空缀悼亡诗。
夜来孤枕空肠断，窗月斜辉梦觉时。','',''),('quantangshi-39356','悔恨','韋莊','quantangshi','','卷40','六七年来春又秋，也同欢笑也同愁。
才闻及第心先喜，试说求婚泪便流。
几为妒来频敛黛，每思闲事不梳头。
如今悔恨将何益，肠断千休与万休。','',''),('quantangshi-39357','虚席','韋莊','quantangshi','','卷40','一闭香闺后，罗衣尽施僧。
鼠偷筵上果，蛾扑帐前灯。
土蚀钗无凤，尘生镜少菱。
有时还影响，花叶曳香缯。','',''),('quantangshi-39358','旧居','韋莊','quantangshi','','卷40','芳草又芳草，故人杨子家。
青云容易散，白日等闲斜。
皓质留残雪，香魂逐断霞。
不知何处笛，一夜呌梅花。','',''),('quantangshi-39359','晏起','韋莊','quantangshi','','卷40','尔来中酒起常迟，卧看南山改旧诗。
开户日高春寂寂，数声啼鸟上花枝。','',''),('quantangshi-39360','幽居春思','韋莊','quantangshi','','卷40','绿映红藏江上村，一声鸡犬似山源。
闭门尽日无人到，翠羽春禽满树喧。','',''),('quantangshi-39361','思归引','韋莊','quantangshi','','卷40','越鸟南翔雁北飞，两乡云路各言归。
如何我是飘飘者，独向江头恋钓矶。','',''),('quantangshi-39362','与小女','韋莊','quantangshi','','卷40','见人初解语呕哑，不肯归眠恋小车。
一夜娇啼缘底事，为嫌衣少缕金华。','',''),('quantangshi-39363','虎迹','韋莊','quantangshi','','卷40','白额频频夜到门，水边踪迹渐成羣。
我今避世栖岩穴，岩穴如何又见君。','',''),('quantangshi-39364','买酒不得','韋莊','quantangshi','','卷40','停尊待尔怪来迟，手挈空瓶毷氉归。
满面春愁消不得，更看溪鹭寂寥飞。','',''),('quantangshi-39365','得故人书','韋莊','quantangshi','','卷40','正向溪头自采苏，青云忽得故人书。
殷勤问我归来否，双阙而今画不如。','',''),('quantangshi-39366','洪州送僧游福建','韋莊','quantangshi','','卷40','八月风波似鼓鼙，可堪波上各东西。
殷勤早作归来计，莫恋猿声住建溪。','',''),('quantangshi-39367','闻回戈军','韋莊','quantangshi','','卷40','上将鏖兵又欲旋，翠华巡幸已三年。
营中不用栽杨柳，愿戴儒冠为控弦。','',''),('quantangshi-39368','南邻公子','韋莊','quantangshi','','卷40','南邻公子夜归声，数炬银灯隔竹明。
醉凭马鬃扶不起，更邀红袖出门迎。','',''),('quantangshi-39369','忆小女银娘','韋莊','quantangshi','','卷40','睦州江上水门西，荡桨扬帆各解携。
今日天涯夜深坐，断肠偏忆阿银犂。','',''),('quantangshi-39370','女仆阿汪','韋莊','quantangshi','','卷40','念尔辛勤岁已深，乱离相失又相寻。
他年待我门如市，报尔千金与万金。','',''),('quantangshi-39371','河清县河亭','韋莊','quantangshi','','卷40','由来多感莫凭高，竟日衷肠似有刀。
人事任成陵与谷，大河东去自滔滔。','',''),('quantangshi-39372','钟陵夜阑作','韋莊','quantangshi','','卷40','钟陵风雪夜将深，坐对寒江独苦吟。
流落天涯谁见问，少卿应识子卿心。','',''),('quantangshi-39373','悼杨氏妓琴弦','韋莊','quantangshi','','卷40','魂归寥廓魄归烟，只住人间十八年。
昨日施僧裙带上，断肠犹系琵琶弦。','',''),('quantangshi-39374','残花','韋莊','quantangshi','','卷40','江头沈醉泥斜晖，却向花前恸哭归。
惆怅一年春又去，碧云芳草两依依。','',''),('quantangshi-39375','岁晏同左生作','韋莊','quantangshi','','卷40','岁暮乡关远，天涯手重携。
雪埋江树短，云压夜城低。
宝瑟湘灵怨，清砧杜魄啼。
不须临皎镜，年长易凄凄。','',''),('quantangshi-39376','咸阳怀古','韋莊','quantangshi','','卷40','城边人倚夕阳楼，城上云凝万古愁。
山色不知秦苑废，水声空傍汉宫流。
李斯不向仓中悟，徐福应无物外游。
莫怪楚吟偏断骨，野烟踪迹似东周。','',''),('quantangshi-39377','和同年韦学士华下途中见寄','韋莊','quantangshi','','卷40','绿杨城郭雨凄凄，过尽千轮与万蹄。
送我独游三蜀路，羡君新上九霄梯。
马惊门外山如活，花笑尊前客似泥。
正是清和好时节，不堪离恨剑门西。','',''),('quantangshi-39378','春愁','韋莊','quantangshi','','卷40','自有春愁正断魂，不堪芳草思王孙。
落花寂寂黄昏雨，深院无人独倚门。','',''),('quantangshi-39379','伤灼灼','韋莊','quantangshi','','卷40','尝闻灼灼丽于花，云髻盘时未破瓜。
桃脸曼长横绿水，玉肌香腻透红纱。
多情不住神仙界，薄命曾嫌富贵家。
流落锦江无处问，断魂飞作碧天霞。','',''),('quantangshi-39380','汉州','韋莊','quantangshi','','卷40','比侬初到汉州城，郭邑楼台触目惊。
松桂影中旌斾色，芰荷风里管弦声。
人心不似经离乱，时运还应却太平。
十日醉眠金雁驿，临岐无恨脸波横。','',''),('quantangshi-39381','长安清明','韋莊','quantangshi','','卷40','蚤是伤春梦雨天，可堪芳草更芊芊。
内官初赐清明火，上相闲分白打钱。
紫陌乱嘶红叱拨，绿[杨]高映画秋千。
游人记得承平事，暗喜风光似昔年。','',''),('quantangshi-39382','秋霁晚景','韋莊','quantangshi','','卷40','秋霁禁城晚，六街烟雨残。
墙头山色健，林外鸟声欢。
翘日楼台丽，清风劒佩寒。
玉人襟袖薄，斜凭翠阑干。','',''),('quantangshi-39383','和人春暮书事寄崔秀才','韋莊','quantangshi','','卷40','半掩朱门白日长，晚风轻堕落梅妆。
不知芳草情何限，只怪游人思易伤。
才见早春莺出谷，已惊新夏燕巢梁。
相逢只赖如渑酒，一曲狂歌入醉乡。','',''),('quantangshi-39384','古离别','韋莊','quantangshi','','卷40','一生风月供惆怅，到处烟花恨别离。
止竟多情何处好，少年长抱少年悲。','',''),('quantangshi-39385','边上逢薛秀才话旧','韋莊','quantangshi','','卷40','前年同醉武陵亭，绝倒闲谭坐到明。
也有绛唇歌白雪，更怜红袖夺金觥。
秦云一散如春梦，楚市千烧作故城。
今日皤然对芳草，不胜东望涕交横。','',''),('quantangshi-39386','饮散呈主人','韋莊','quantangshi','','卷40','梦觉笙歌散，空堂寂寞秋。
更闻城角弄，烟雨不胜愁。','',''),('quantangshi-39387','使院黄葵花','韋莊','quantangshi','','卷40','薄妆新着澹黄衣，对捧金炉侍醮迟。
向月似矜倾国貌，倚风如唱步虚词。
乍开檀炷疑闻语，试与云和必解吹。
为报同人看来好，不禁秋露即离披。','',''),('quantangshi-39388','摇落','韋莊','quantangshi','','卷40','摇落秋天酒易醒，凄凄长似别离情。
黄昏倚柱不归去，肠断绿荷风雨声。','',''),('quantangshi-39389','奉和观察郎中春暮忆花言怀见寄四韵之什','韋莊','quantangshi','','卷40','天畔峨嵋簇簇青，楚云何处隔重扃。
落花带雪埋芳草，春雨和风湿画屏。
对酒莫辞冲暮角，望乡谁解倚南亭。
惟君信我多惆怅，只愿陶陶不愿醒。','',''),('quantangshi-39390','奉和左司郎中春物暗度感而成章','韋莊','quantangshi','','卷40','才喜新春已暮春，夕阳吟杀倚楼人。
锦江风散霏霏雨，花市香飘漠漠尘。
今日尚追巫峡梦，少年应遇洛川神。
有时自患多情病，莫是生前宋玉身。','',''),('quantangshi-39391','少年行','韋莊','quantangshi','','卷40','五陵豪客多，买酒黄金𧣴。
醉下酒家楼，美人双翠幰。
挥劒邯郸市，走马梁王苑。
乐事殊未央，年华已云晚。','',''),('quantangshi-39392','令狐亭','韋莊','quantangshi','','卷40','若非天上神仙宅，须是人间将相家。
想得当时好烟月，管弦吹杀后庭花。','',''),('quantangshi-39393','闺月','韋莊','quantangshi','','卷40','明月照前除，烟华蕙兰湿。
清风行处来，白露寒蝉急。
美人情易伤，暗上红楼立。
欲言无处言，但向姮娥泣。','',''),('quantangshi-39394','闺怨','韋莊','quantangshi','','卷40','戚戚彼何人，明眸利于月。
啼妆晓不干，素面凝香雪。
良人去淄右，镜破金簪折。
空藏兰蕙心，不忍琴中说。','',''),('quantangshi-39395','上春词','韋莊','quantangshi','','卷40','曈昽赫日东方来，禁城烟暖蒸青苔。
金楼美人花屏开，晨妆未罢车声催。
幽兰报暖紫芽折，夭花愁艳蝶飞回。
五陵年少惜花落，酒浓歌极翻如哀。
四时轮环终又始，百年不见南山摧。
游人陌上骑生尘，颜子门前吹死灰。','',''),('quantangshi-39396','捣练篇','韋莊','quantangshi','','卷40','月华吐艳明烛烛，青楼妇唱捣衣曲。
白袷丝光织鱼目，菱花绶带鸳鸯簇。
临风缥缈叠秋雪，月下丁冬捣寒玉。
楼兰欲寄在何乡，凭人与系征鸿足。','',''),('quantangshi-39397','杂体联锦','韋莊','quantangshi','','卷40','携手重携手，夹江金线柳。
江上柳能长，行人恋尊酒。
尊酒意何深，为郎歌玉簪。
玉簪声断续，钿轴鸣双毂。
双毂去何方，隔江春树绿。
树绿酒旗高，泪痕沾绣袍。
袍缝紫鹅湿，重持金错刀。
错刀何灿烂，使我肠千断。
肠断欲何言，帘动真珠繁。
真珠缀秋露，秋露沾金盘。
金盘湛琼液，仙子无归迹。
无迹又无言，海烟空寂寂。
寂寂古城道，马嘶芳岸草。
岸草接长堤，长堤人解携。
解携忽已久，缅邈空回首。
回首隔天河，恨唱莲塘歌。
莲塘在何许，日暮西山雨。','',''),('quantangshi-39398','长安春','韋莊','quantangshi','','卷40','长安二月多香尘，六街车马声辚辚。
家家楼上如花人，千枝万枝红艳新。
帘间笑语自相问，何人占得长安春。
长安春色本无主，古来尽属红楼女。
如今无奈杏园人，骏马轻车拥将去。','',''),('quantangshi-39399','抚盈歌','韋莊','quantangshi','','卷40','凤縠兮鸳绡，霞疏兮绮寮。
玉庭兮春昼，金屋兮秋宵。
愁瞳兮月皎，笑颊兮花娇。
罗轻兮浓麝，室暖兮香椒。
銮舆去兮萧屑，七丝断兮泬寥。
主父卧兮漳水，君王幸兮云轺。
铅华窅窈兮穠姿，棠公肸蠁兮靡依。
翠华长逝兮莫追，晏相望门兮空悲。','',''),('quantangshi-39400','赠峨嵋山弹琴李处士','韋莊','quantangshi','','卷40','峨嵋山下能琴客，似醉似狂人不测。
何须见我眼偏青，未见我身头已白。
茫茫四海本无家，一片愁云扬秋碧。
壶中醉卧日月明，世上长游天地窄。
晋朝叔夜旧相知，蜀郡文君小来识。
后生常建彼何人，赠我篇章苦雕刻。
名卿名相尽知音，遇酒遇琴无间隔。
如今世乱独翛然，天外鸿飞招不得。
余今正泣杨朱泪，八月边城风刮地。
霓旌绛斾忽相寻，为我尊前横绿绮。
一弹猛雨随手来，再弹白雪连天起。
凄凄清清松上风，咽咽幽幽陇头水。
吟蜂遶树去不来，别鹤引雏飞又止。
锦麟不动惟侧头，白马仰听空竖耳。
广陵故事无人知，古人不说今人疑。
子期子野俱不见，乌啼鬼哭空伤悲。
坐中词客悄无语，帘外月华庭欲午。
为君吟作听琴歌，为我留名系仙谱。','',''),('quantangshi-39401','江臯赠别','韋莊','quantangshi','','卷40','金管多情恨解携，一声歌罢客如泥。
江亭系马绿杨短，野岸维舟春草齐。
帝子梦魂烟水阔，谢公诗思碧云低。
风前不用频挥手，我有家山白日西。','',''),('quantangshi-39402','南阳小将张彦硖口镇税人场射虎歌','韋莊','quantangshi','','卷40','海内昔年狎太平，横目穰穰何峥嵘。
天生天杀岂天怒，忍使朝朝喂猛虎。
关东驿路多丘荒，行人最忌税人场。
张彦雄特制残暴，见之叱起如叱羊。
鸣弦霹雳越幽阻，往往依林犹抵拒。
草际旋看委锦茵，腰间不更抽白羽。
老饕已毙众雏恐，童稚揶揄皆自勇。
忠良效顺势亦然，一劒猜狂敢轻动。
有文有武方为国，不是英雄伏不得。
试征张彦作将军，几个将军愿策勋。','',''),('quantangshi-39403','下邽感旧','韋莊','quantangshi','','卷40','昔为童稚不知愁，竹马闲乘遶县游。
曾为看花偷出郭，也因逃学暂登楼。
招他邑客来还醉，儳得先生去始休。
今日故人何处问，夕阳衰草尽荒丘。','',''),('quantangshi-39404','涂次逢李氏兄弟感旧','韋莊','quantangshi','','卷40','御沟四面朱门宅，记得当时好弟兄。
晓傍柳阴骑竹马，夜隈灯影弄先生。
巡街趂蝶衣裳破，上屋探雏手脚轻。
今日相逢俱老大，忧家忧国尽公卿。','',''),('quantangshi-39405','龙潭','韋莊','quantangshi','','卷40','激石悬流雪满湾，九龙潜处野云闲。
欲行甘雨四天下，且隐澄潭一顷间。
浪引浮槎依北岸，波分晚日见东山。
垂髯傥遇穆王驾，阆苑周流应未还。','',''),('quantangshi-39406','江上别李秀才','韋莊','quantangshi','','卷40','前年相送灞陵春，今日天涯各避秦。
莫向尊前惜沈醉，与君俱是异乡人。','',''),('quantangshi-39407','句','韋莊','quantangshi','','卷40','印将金鏁鏁，帘用玉钩钩。
不随妖艳开，独媚玄冥节。
岂是为穷常见隔，只应嫌酒不相过。','',''),('quantangshi-39408','拟塞外征行','王貞白','quantangshi','','卷40','寇骑满鸡田，都护欲临边。
青泥方绝漠，怀剑始辞燕。
旌旗挂龙虎，壮士募鹰鹯。
长城威十万，高岭奋三千。
行行向马邑，去去指祁连。
鼓声遥赤塞，兵气远冲天。
对阵云初上，临城月始悬。
风惊烽易灭，沙暗马难前。
恩重恒思报，劳心屡损年。
微功一可立，身轻不自怜。','',''),('quantangshi-39409','芦苇','王貞白','quantangshi','','卷40','高士想江湖，湖闲庭植芦。
清风时有至，绿竹兴何殊。
嫩喜日光薄，疎忧雨点麤。
惊蛙跳得过，鬬雀袅如无。
未织巴篱护，几抬邛竹扶。
惹烟轻弱柳，蘸水漱清蒲。
溉灌情偏重，琴樽赏不孤。
穿花思钓叟，吹叶少羌雏。
寒色暮天映，秋声远籁俱。
郎吟应有趣，潇洒十余株。','',''),('quantangshi-39410','田舍曲','王貞白','quantangshi','','卷40','古今利名路，只在侬门前。
至老不离家，一生常晏眠。
牛羊晚自归，儿童戏野田。
岂思封侯贵，唯只待丰年。
征赋岂辞苦，但愿时官贤。
时官苟贪浊，田舍生忧煎。','',''),('quantangshi-39411','妾薄命','王貞白','quantangshi','','卷40','薄命头欲白，频年嫁不成。
秦娥未十五，昨夜事公卿。
岂有机杼力，空传歌舞名。
妾专修妇德，媒氏却相轻。','',''),('quantangshi-39412','湘妃怨','王貞白','quantangshi','','卷40','舜欲省蛮陬，南巡非逸游。
九江沉白日，二女泣沧洲。
目极楚云断，恨深湘水流。
至今闻鼓瑟，咽绝不胜愁。','',''),('quantangshi-39413','长门怨二首 一','王貞白','quantangshi','','卷40','寂寞故宫春，残灯晓尚存。
从来非妾过，偶尔失君恩。
花落伤容鬓，莺啼惊梦魂。
翠华如可待，应免老长门。','',''),('quantangshi-39414','长门怨二首 二','王貞白','quantangshi','','卷40','叶落长门静，苔生永巷幽。
相思对明月，独坐向空楼。
銮驾迷终转，蛾眉老自愁。
昭阳歌舞伴，此夕未知秋。','',''),('quantangshi-39415','有所思','王貞白','quantangshi','','卷40','芙蓉出水时，偶尔便分离。
自此无因见，长教挂所思。
残春不入梦，芳信欲传谁。
寂寞秋堂下，空吟小谢诗。','',''),('quantangshi-39416','短歌','王貞白','quantangshi','','卷40','物候来相续，新蝉送晚莺。
百年休倚赖，一梦甚分明。
金鼎神仙隐，铜壶昼夜倾。
不如早立德，万古有其名。','',''),('quantangshi-39417','御沟水','王貞白','quantangshi','','卷40','一带御沟水，绿槐相荫清。
此中涵帝泽，无处濯尘缨。
鸟道来虽险，龙池到自平。
朝宗本心切，愿向急流倾。','',''),('quantangshi-39418','少年行二首 一','王貞白','quantangshi','','卷40','游宴不知厌，杜陵狂少年。
花时轻暖酒，春服薄装绵。
戏马上林苑，鬬鸡寒食天。
鲁儒甘被笑，对策鬓皤然。','',''),('quantangshi-39419','少年行二首 二','王貞白','quantangshi','','卷40','弱冠投边急，驱兵夜渡河。
追奔铁马走，杀虏宝刀讹。
威静黑山路，气含清海波。
常闻为突骑，天子赐长戈。','',''),('quantangshi-39420','塞上曲','王貞白','quantangshi','','卷40','岁岁但防虏，西征早晚休。
匈奴不系颈，汉将但封侯。
夕照低烽火，寒笳咽戍楼。
燕然山上字，男子见须羞。','',''),('quantangshi-39421','长安道','王貞白','quantangshi','','卷40','晓鼓人已行，暮鼓人未息。
梯航万国来，争先贡金帛。
不问贤与愚，但论官与职。
如何贫书生，只献安边策。','',''),('quantangshi-39422','洛阳道','王貞白','quantangshi','','卷40','喧喧洛阳路，奔走争先步。
唯恐着鞭迟，谁能更回顾。
覆车虽在前，润屋何曾惧。
贤哉只二疏，东门挂冠去。','',''),('quantangshi-39423','度关山','王貞白','quantangshi','','卷40','只领千余骑，长驱碛邑间。
云州多警急，雪夜度关山。
石响铃声远，天寒弓力悭。
秦楼休怅望，不日凯歌还。','',''),('quantangshi-39424','出自蓟北门行','王貞白','quantangshi','','卷40','蓟北连极塞，塞色昼冥冥。
战地骸骨满，长时风雨腥。
沙河留不定，春草冻难青。
万户封侯者，何谋静虏庭。','',''),('quantangshi-39425','从军行','王貞白','quantangshi','','卷40','从军朔方久，未省用干戈。
秪以恩信及，自然戎虏和。
边声动白草，烧色入枯河。
每度因看猎，令人勇气多。','',''),('quantangshi-39426','古悔从军行','王貞白','quantangshi','','卷40','忆昔仗孤剑，十年从武威。
论兵亲玉帐，逐虏过金微。
陇水秋先冻，关云寒不飞。
辛勤功业在，麟阁志犹违。','',''),('quantangshi-39427','胡笳曲','王貞白','quantangshi','','卷40','陇底悲笳引，陇头鸣北风。
一轮霜月落，万里塞天空。
戍卒泪应尽，胡儿哭未终。
争教班定远，不念玉关中。','',''),('quantangshi-39428','入塞','王貞白','quantangshi','','卷40','玉殿论兵事，君王诏出征。
新除羽林将，曾破月支兵。
惯历塞垣险，能分部落情。
从今一战胜，不使虏尘生。','',''),('quantangshi-39429','游仙','王貞白','quantangshi','','卷40','我家三岛上，洞户眺波涛。
醉背云屏卧，谁知海日高。
露香红玉树，风绽碧蟠桃。
悔与仙子别，思归梦钓鳌。','',''),('quantangshi-39430','歌','王貞白','quantangshi','','卷40','谁唱关西曲，寂寞夜景深。
一声长在耳，万恨重经心。
调古清风起，曲终凉月沉。
却应筵上客，未必是知音。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-39431','经故洛城','王貞白','quantangshi','','卷40','卜世何久远，由来仰圣明。
山河徒自壮，周召不长生。
几主任奸谄，诸侯各战争。
但余崩垒在，今古共伤情。','',''),('quantangshi-39432','金陵','王貞白','quantangshi','','卷40','六代江山在，繁华古帝都。
乱来城不守，战后地多芜。
寒日随潮落，归帆与鸟孤。
兴亡多少事，回首一长吁。','',''),('quantangshi-39433','金陵怀古','王貞白','quantangshi','','卷40','恃险不种德，兴亡叹数穷。
石城几换主，天堑谩连空。
御路叠民冢，台基聚牧童。
折碑犹有字，多记晋英雄。','',''),('quantangshi-39434','商山','王貞白','quantangshi','','卷40','商山名利路，夜亦有人行。
四皓卧云处，千秋叠藓生。
昼烧笼涧黑，残雪隔林明。
我待酬恩了，来听水石声。','',''),('quantangshi-39435','庐山','王貞白','quantangshi','','卷40','岳立镇南楚，雄名天下闻。
五峰高阂日，九叠翠连云。
夏谷雪犹在，阴岩昼不分。
唯应嵩与华，清峻得为羣。','',''),('quantangshi-39436','终南山','王貞白','quantangshi','','卷40','终朝异五岳，列翠满长安。
地去搜扬近，人谋隐遁难。
水穿诸苑过，雪照一城寒。
为问红尘里，谁同驻马看。','',''),('quantangshi-39437','寄郑谷','王貞白','quantangshi','','卷40','五百首新诗，缄封寄去时。
秪凭夫子鉴，不要俗人知。
火鼠重收布，冰蚕乍吐丝。
直须天上手，裁作领巾披。','',''),('quantangshi-39438','题严陵钓台','王貞白','quantangshi','','卷40','山色四时碧，溪声七里清。
严陵爱此景，下视汉公卿。
垂钓月初上，放歌风正轻。
应怜渭滨叟，匡国正论兵。','',''),('quantangshi-39439','晓泊汉阳渡','王貞白','quantangshi','','卷40','落月临古渡，武昌城未开。
残灯明市井，晓色辨楼台。
云自苍梧去，水从嶓冢来。
芳洲号鹦鹉，用记禰生才。','',''),('quantangshi-39440','随计','王貞白','quantangshi','','卷40','徒步随计吏，辛勤鬓易凋。
归期无定日，乡思羡回潮。
冒雨投前驿，侵星过断桥。
何堪穆陵路，霜叶更潇潇。','',''),('quantangshi-39441','白牡丹','王貞白','quantangshi','','卷40','谷雨洗纤素，裁为白牡丹。
异香开玉合，轻粉泥银盘。
晓贮露华湿，宵倾月魄寒。
家人淡妆罢，无语倚朱栏。','',''),('quantangshi-39442','述松','王貞白','quantangshi','','卷40','远谷呈材干，何由入栋粱。
岁寒虚胜竹，功绩不如桑。
秋露落松子，春深裛嫩黄。
虽蒙匠者顾，樵采日难防。','',''),('quantangshi-39443','宫池产瑞莲','王貞白','quantangshi','','卷40','雨露及万物，嘉祥有瑞莲。
香飘鸡树近，荣占凤池先。
圣日临双丽，恩波照并妍。
愿同指佞草，生向帝尧前。','',''),('quantangshi-39444','送友人南归','王貞白','quantangshi','','卷40','南国菖蒲老，知君忆钓船。
离京近残暑，归路有新蝉。
岘首白云起，洞庭秋月悬。
若教吟兴足，西笑是何年。','',''),('quantangshi-39445','送马明府归山','王貞白','quantangshi','','卷40','辞秩入匡庐，重修靖节居。
免遭黑绶束，不与白云疎。
送吏各献酒，羣儿自担书。
到时看瀑布，为我谢清虚。','',''),('quantangshi-39446','送韩从事归本道','王貞白','quantangshi','','卷40','献捷灵州倅，归时宠拜新。
论边多称旨，许国誓亡身。
马渴黄河冻，雁回青冢春。
到蕃唯促战，应不肯和亲。','',''),('quantangshi-39447','秋日旅怀寄右省郑拾遗','王貞白','quantangshi','','卷40','永夕愁不寐，草虫喧客庭。
半窗分晓月，当枕落残星。
鬓发游梁白，家山近越青。
知音在谏省，苦调有谁听。','',''),('quantangshi-39448','赠刘凝评事','王貞白','quantangshi','','卷40','棘寺官初罢，梁园静掩扉。
春深颜子巷，花映老莱衣。
谈史曾无滞，攻书已造微。
即膺新宠命，称庆向庭闱。','',''),('quantangshi-39449','忆张处士','王貞白','quantangshi','','卷40','天台张处士，诗句造玄微。
古药知音少，名言与俗违。
山风入松径，海月上岩扉。
毕世唯高卧，无人说是非。','',''),('quantangshi-39450','云居长老','王貞白','quantangshi','','卷40','巘路蹑云上，来参出世僧。
松高半岩雪，竹覆一溪冰。
不说有为法，非传无尽灯。
了然方寸内，应秪见南能。','',''),('quantangshi-39451','洗竹','王貞白','quantangshi','','卷40','道院竹繁教畧洗，鸣琴酌酒看扶疎。
不图结实来双凤，且要长竿钓巨鱼。
锦箨裁冠添散逸，玉芽修馔称清虚。
有时记得三天事，自向琅玕节下书。','',''),('quantangshi-39452','庾楼晓望','王貞白','quantangshi','','卷40','独凭朱槛亦凌晨，山色初明水色新。
竹雾晓笼衔岭月，苹风暖送过江春。
子城阴处犹残雪，衙鼓声前未有尘。
三百年来庾楼上，曾经多少望乡人。','',''),('quantangshi-39453','送芮尊师','王貞白','quantangshi','','卷40','石上菖蒲节节灵，先生服食得长生。
早知避世忧身老，近日登山觉步轻。
黄鹤待传蓬岛信，丹书应换蘂宫名。
他年控鲤升天去，庐岳逋民愿从行。','',''),('quantangshi-39454','折杨柳三首 一','王貞白','quantangshi','','卷40','枝枝交影锁长门，嫩色曾沾雨露恩。
凤辇不来春欲尽，空留莺语到黄昏。','',''),('quantangshi-39455','折杨柳三首 二','王貞白','quantangshi','','卷40','水殿年年占早芳，柔条风里御炉香。
如今万乘多巡狩，辇路无阴绿草长。','',''),('quantangshi-39456','折杨柳三首 三','王貞白','quantangshi','','卷40','嫩叶初齐不耐寒，风和时拂玉栏干。
征人去日曾攀折，泣雨伤春翠黛残。','',''),('quantangshi-39457','远闻本郡行春到旧山二首 一','王貞白','quantangshi','','卷40','一身从宦留京邑，五马遥闻到旧山。
已领烟霞光野径，深慙老幼候柴关。','',''),('quantangshi-39458','远闻本郡行春到旧山二首 二','王貞白','quantangshi','','卷40','清风借响松筠外，画隼停晖水石间。
定掩溪名在图传，共知轩盖此登攀。','',''),('quantangshi-39459','宿新安村步','王貞白','quantangshi','','卷40','淅淅寒流涨浅沙，月明空渚徧芦花。
离人偶宿孤邨下，永夜闻砧一两家。','',''),('quantangshi-39460','仙岩二首 一','王貞白','quantangshi','','卷40','白烟昼起丹竈，红叶秋书篆文。
二十四岩天上，一鸡啼破晴云。','',''),('quantangshi-39461','仙岩二首 二','王貞白','quantangshi','','卷40','风呼山鬼服役，月照衡薇结花。
江暖客寻瑶草，洞深人咽丹霞。','',''),('quantangshi-39462','雨后从陶郎中登庾楼','王貞白','quantangshi','','卷40','庾楼逢霁色，夏日欲西曛。
虹截半江雨，风驱大泽云。
岛边渔艇聚，天畔鸟行分。
此景堪谁画，文翁请缀文。','',''),('quantangshi-39463','九日长安作','王貞白','quantangshi','','卷40','无酒泛金菊，登高但忆秋。
归心随旅雁，万里在沧洲。
残照明天阙，孤砧隔御沟。
谁能思落帽，两鬓已添愁。','',''),('quantangshi-39464','晓发萧关','王貞白','quantangshi','','卷40','早发长风里，边城曙色间。
数鸿寒背碛，片月落临关。
陇上明星没，沙中夜探还。
归程不可问，几日到家山。','',''),('quantangshi-39465','钓台','王貞白','quantangshi','','卷40','异代有巢许，方知严子情。
旧交虽建国，高卧不求荣。
溪鸟寒来浴，汀兰暖重生。
何颜吟过此，辛苦得浮名。','',''),('quantangshi-39466','寄天台叶尊师','王貞白','quantangshi','','卷40','师住天台久，长闻过石桥。
晴峯见沧海，深洞彻丹霄。
采药霞衣湿，煎芝古鼎焦。
念予无俗骨，频与鹤书招。','',''),('quantangshi-39467','御试后进诗','王貞白','quantangshi','','卷40','三时赐食天厨近，再宿偷吟禁漏清。
二十五家齐拔宅，人间已写上升名。','',''),('quantangshi-39468','春日咏梅花','王貞白','quantangshi','','卷40','靓妆才罢粉痕新，迨晓风回散玉尘。
若遣有情应怅望，已兼残雪又兼春。','',''),('quantangshi-39469','句','王貞白','quantangshi','','卷40','太阳虽不照，梁栋每重阴。
白发未逢媒，对景且裴回。
别酒莫辞今夜醉，故人知我几时来。
改贯永留乡党额，减租重感郡侯恩。','',''),('quantangshi-39470','登单于台','張蠙','quantangshi','','卷40','边兵春尽回，独上单于台。
白日地中出，黄河天外来。
沙翻痕似浪，风急响疑雷。
欲向阴关度，阴关晓不开。','',''),('quantangshi-39471','寄友人','張蠙','quantangshi','','卷40','恋道欲何如，东西远索居。
长疑即见面，翻致久无书。
甸麦深藏雉，淮苔浅露鱼。
相思不我会，明月几盈虚。','',''),('quantangshi-39472','和崔监丞春游郑仆射东园','張蠙','quantangshi','','卷40','春兴随花尽，东园自养闲。
不离三亩地，似入万重山。
白鸟穿萝去，清泉抵石远。
岂同秦代客，无位隐商山。','',''),('quantangshi-39473','过萧关','張蠙','quantangshi','','卷40','出得萧关北，儒衣不称身。
陇狐来试客，沙鹘下欺人。
晓戍残烽火，晴原起猎尘。
边戎莫相忌，非是霍家亲。','',''),('quantangshi-39474','盆池','張蠙','quantangshi','','卷40','圆内陶化功，外绝众流通。
选处离松影，穿时减药丛。
别疑天在地，长对月当空。
每使登门客，烟波入梦中。','',''),('quantangshi-39475','野泉','張蠙','quantangshi','','卷40','远出白云中，长年听不同。
清声萦乱石，寒色入长空。
挂壁聊成雨，穿林别起风。
温泉非尔数，源发在深空。','',''),('quantangshi-39476','送成州牧','張蠙','quantangshi','','卷40','清时为塞郡，自古有儒流。
素望知难惬，新恩且用酬。
犬牙连蜀国，兵额贯秦州。
秪作三年别，谁能听邑留。','',''),('quantangshi-39477','蓟北书事','張蠙','quantangshi','','卷40','度碛如经海，茫然但见空。
戍楼承落日，沙塞碍惊蓬。
暑过燕僧出，时平虏客通。
逢人皆上将，谁有定边功。','',''),('quantangshi-39478','送徐州薛尚书','張蠙','quantangshi','','卷40','上将出儒中，论诗拟立功。
州从禹后别，军自汉来雄。
远驿销寒日，严城肃暮空。
龙颜有遗庙，犹得奠英风。','',''),('quantangshi-39479','贻曹郎中','張蠙','quantangshi','','卷40','所作高前古，封章自曲台。
细看明主意，终用出人才。
省印寻僧锁，书楼领鹤开。
南山有旧友，时向白云来。','',''),('quantangshi-39480','送缙云尉','張蠙','quantangshi','','卷40','释褐从仙尉，之官兴若何。
去程唯水石，公署在云萝。
野饭楼中迥，晴峰案上多。
三年罢趋府，应更战高科。','',''),('quantangshi-39481','送董卿赴台州','張蠙','quantangshi','','卷40','九陌除书出，寻僧问海城。
家从中路挈，吏隔数州迎。
夜蚌侵灯影，春禽杂橹声。
开图见异迹，思上石桥行。','',''),('quantangshi-39482','送友人赴泾州幕','張蠙','quantangshi','','卷40','杏园沈饮散，荣别就佳招。
日月相期尽，山川独去遥。
府楼明蜀雪，关碛转胡雕。
纵有烟尘动，应随上策销。','',''),('quantangshi-39483','逢漳州崔使君北归','張蠙','quantangshi','','卷40','在郡多殊称，无人不望回。
离城携客去，度岭担猿来。
障写经冬蘂，瓶缄落暑梅。
长安有归宅，归见锁青苔。','',''),('quantangshi-39484','云朔逢山友','張蠙','quantangshi','','卷40','会面却生疑，居然似梦归。
塞深行客少，家远识人稀。
战马分旗牧，惊禽曳箭飞。
将军虽异礼，难便脱麻衣。','',''),('quantangshi-39485','别后寄友生','張蠙','quantangshi','','卷40','上马如飞鸟，飘然隔去尘。
共看今夜月，独作异乡人。
就养江南熟，移居井赋新。
襄阳曾卜隐，应与孟家邻。','',''),('quantangshi-39486','边游别友人','張蠙','quantangshi','','卷40','欲别不止泪，当杯难强歌。
家贫随日长，身病涉寒多。
雨雪迷燕路，田园隔楚波。
良时未自致，归去欲如何。','',''),('quantangshi-39487','边庭送别','張蠙','quantangshi','','卷40','一生虽达理，远别亦相悲。
白发无修处，青松有老时。
暮烟传戍起，寒日隔沙垂。
若是长安去，何难定后期。','',''),('quantangshi-39488','将之京师留别亲友','張蠙','quantangshi','','卷40','达命何劳问，西游且自期。
至公如有日，知我岂无时。
野迥蝉相答，堤长柳对垂。
酣歌一举袂，明发不堪思。','',''),('quantangshi-39489','赠别山友','張蠙','quantangshi','','卷40','从容无限意，不独为离羣。
年长惊黄叶，时清厌白云。
旧山回马见，寒瀑别家闻。
相与存吾道，穷通各自分。','',''),('quantangshi-39490','途次绩溪先寄陈明府','張蠙','quantangshi','','卷40','入境风烟好，幽人不易传。
新居多是客，旧隐半成仙。
山断云冲骑，溪长柳拂船。
何当许过县，闻有箧中篇。','',''),('quantangshi-39491','送友人归武陵','張蠙','quantangshi','','卷40','闻近桃源住，无村不是花。
戍旗招海客，庙鼓集江鸦。
别岛垂橙实，闲田长荻[芽]。
游秦未得意，看即更离家。','',''),('quantangshi-39492','乱中寄友人','張蠙','quantangshi','','卷40','别来难觅信，何处避艰危。
鬓黑无多日，尘清是几时。
人情将厌武，王泽即兴诗。
若便怀深隐，还应圣主知。','',''),('quantangshi-39493','哭建州李员外','張蠙','quantangshi','','卷40','诗名不易出，名出又何为。
捷到重科早，官终一郡卑。
素风无后嗣，遗迹有生祠。
自罢羊公市，溪猿哭旧时。','',''),('quantangshi-39494','吊孟浩然','張蠙','quantangshi','','卷40','每每樵家说，孤坟亦夜吟。
若重生此世，应更苦前心。
名与襄阳远，诗同汉水深。
亲栽鹿门树，犹盖石牀阴。','',''),('quantangshi-39495','送友人及第归','張蠙','quantangshi','','卷40','家林沧海东，未晓日先红。
作贡诸蕃别，登科几国同。
远声鱼呷浪，层气蜃迎风。
乡俗稀攀桂，争来问月宫。','',''),('quantangshi-39496','次韵和友人冬月书斋','張蠙','quantangshi','','卷40','四季多花木，穷冬亦不凋。
薄冰行处断，残火睡来消。
象版签书帙，蛮藤络酒[瓢]。
公卿有知己，时得一相招。','',''),('quantangshi-39497','过山家','張蠙','quantangshi','','卷40','避暑得探幽，忘言遂久留。
云深窗失曙，松合径先秋。
响谷传人语，鸣泉洗客愁。
家山不在此，至此可归休。','',''),('quantangshi-39498','宿山驿','張蠙','quantangshi','','卷40','驿在千峰里，寒宵独此身。
古坟时见火，荒壁悄无隣。
月白翻惊鸟，云闲欲就人。
秪应明日鬓，更与老相亲。','',''),('quantangshi-39499','宿开照寺光泽上人院','張蠙','quantangshi','','卷40','静室谭玄旨，清宵独细听。
真身非有像，至理本无经。
钟定遥闻水，楼高别见星。
不教人触秽，偏说此山灵。','',''),('quantangshi-39500','宿山寺','張蠙','quantangshi','','卷40','中峰半夜起，忽觉有青冥。
此界自生雨，上方犹有星。
楼高钟尚远，殿古像多灵。
好是潺湲水，房房伴诵经。','',''),('quantangshi-39501','题紫阁院','張蠙','quantangshi','','卷40','上方人海外，苔径上千层。
洞壑有灵药，房廊无老僧。
古岩雕素像，乔木挂寒灯。
每到思修隐，将回苦不能。','',''),('quantangshi-39502','白菊','張蠙','quantangshi','','卷40','秋天木叶干，犹有白花残。
举世稀栽得，豪家却画看。
片苔相应绿，诸卉独宜寒。
几度携佳客，登高欲折难。','',''),('quantangshi-39503','丛苇','張蠙','quantangshi','','卷40','丛丛寒水边，曾折打鱼船。
忽与亭台近，翻嫌岛屿偏。
花明无月夜，声急正秋天。
遥忆巴陵渡，残阳一望烟。','',''),('quantangshi-39504','郑毂补阙山松','張蠙','quantangshi','','卷40','心将积雪欺，根与白云离。
远寄僧犹忆，高看鹤未知。
影交新长叶，皴匝旧生枝。
多少同时种，深山不得移。','',''),('quantangshi-39505','新竹','張蠙','quantangshi','','卷40','新鞭暗入庭，初长两三茎。
不是他山少，无如此地生。
垂梢丛上出，柔叶箨间成。
何用高唐峡，风枝埽月明。','',''),('quantangshi-39506','和友人送赵能卿东归','張蠙','quantangshi','','卷40','一第时难得，归期日已过。
相看玄鬓少，共忆白云多。
楚阔天垂草，吴空月上波。
无人不有遇，之子独狂歌。','',''),('quantangshi-39507','送人归南中','張蠙','quantangshi','','卷40','有家谁不别，经乱独难寻。
远路波涛恶，穷荒雨雾深。
烧惊山象出，雷触海鳌沉。
为问南迁客，何人在瘴林。','',''),('quantangshi-39508','塞下曲','張蠙','quantangshi','','卷40','边事多更变，天心亦为忧。
胡兵来作寇，汉将也封侯。
夜烧冲星赤，寒尘翳日愁。
无门展微畧，空上望西楼。','',''),('quantangshi-39509','边将二首 一','張蠙','quantangshi','','卷40','历战燕然北，功高劒有威。
闻名外国惧，轻命故人稀。
角怨星芒动，尘愁日色微。
从为汉都护，未得脱征衣。','',''),('quantangshi-39510','边将二首 二','張蠙','quantangshi','','卷40','按劒立城楼，西看极海头。
承家为上将，开地得边州。
碛迥兵难伏，天寒马易收。
胡风一度猎，吹裂锦貂裘。','',''),('quantangshi-39511','朔方书事','張蠙','quantangshi','','卷40','秋尽角声苦，逢人唯荷戈。
城池向陇少，岐路出关多。
雁远行垂地，烽高影入河。
仍闻黑山寇，又觅汉家和。','',''),('quantangshi-39512','经荒驿','張蠙','quantangshi','','卷40','古驿成幽境，云萝隔四隣。
夜灯移宿鸟，秋雨禁行人。
废巷荆丛合，荒庭虎迹新。
昔年经此地，终日是红尘。','',''),('quantangshi-39513','赠栖白大师','張蠙','quantangshi','','卷40','剃发得时名，僧应别应星。
偶题皆有诏，闲论便成经。
埽叶寒烧鼎，融冰晓注瓶。
长因内斋出，多客叩禅扃。','',''),('quantangshi-39514','赠闻一上人','張蠙','quantangshi','','卷40','见面虽年少，闻名似白头。
玄谈穷释旨，清思掩诗流。
果落痕生砌，松高影上楼。
坛场在三殿，应召入焚修。','',''),('quantangshi-39515','赠可伦上人','張蠙','quantangshi','','卷40','师教本于空，流来不自东。
修从多劫后，行出众人中。
衲冷湖山雨，幡轻海甸风。
游吴累夏讲，还与虎溪同。','',''),('quantangshi-39516','寄法干寺令諲太师','張蠙','quantangshi','','卷40','师居中禁寺，外请已无缘。
望幸唯修偈，承恩不乱禅。
院多喧种药，池有化生莲。
何日龙宫里，相寻借法船。','',''),('quantangshi-39517','寄太白禅师','張蠙','quantangshi','','卷40','何年万仞顶，独有坐禅僧。
客上应无路，人传或见灯。
斋厨唯有橡，讲石任生藤。
遥想东林社，如师谁复能。','',''),('quantangshi-39518','遇道者','張蠙','quantangshi','','卷40','数里白云里，身轻无履踪。
故寻多不见，偶到即相逢。
古井生云水，高坛出异松。
聊看杏花酌，便似换颜容。','',''),('quantangshi-39519','赠道者','張蠙','quantangshi','','卷40','得道疑人识，都城独闭关。
头从白后黑，心向闹中闲。
饥渴唯调气，儿孙亦驻颜。
始知仙者隐，殊不在深山。','',''),('quantangshi-39520','雨','張蠙','quantangshi','','卷40','半夜西亭雨，离人独启关。
桑麻荒旧国，雷电照前山。
细滴高槐底，繁声叠漏间。
唯应孤镜里，明月长愁颜。','',''),('quantangshi-39521','长安春望','張蠙','quantangshi','','卷40','明时不敢卧烟霞，又见秦城换物华。
残雪未销双凤阙，新春已发五侯家。
甘贫祗拟长缄酒，忍病犹期强采花。
故国别来桑柘尽，十年兵践海西艖。','',''),('quantangshi-39522','过黄牛峡','張蠙','quantangshi','','卷40','黄牛来势泻巴川，叠日孤舟逐峡前。
雷电夜惊猿落树，波涛愁恐客离船。
盘涡逆入嵌空地，断壁高分缭绕天。
多少人经过此去，一生魂梦怕潺湲。','',''),('quantangshi-39523','逢道者','張蠙','quantangshi','','卷40','纵意出山无远近，还如孤鹤在空虚。
昔年亲种树皆老，此世相逢人自疎。
野叶细苞深洞药，岩萝闲束古仙书。
秪寻隐迹归何处，方说烟霞不定居。','',''),('quantangshi-39524','边情','張蠙','quantangshi','','卷40','穷荒始得静天骄，又说天兵拟渡辽。
圣主尚嫌蕃界近，将军莫恨汉庭遥。
草枯朔野春难发，冰结河源夏半销。
惆怅临戎皆効国，岂无人似霍嫖姚。','',''),('quantangshi-39525','赠李司徒','張蠙','quantangshi','','卷40','承家拓定陇关西，勋贵名应上将齐。
金库夜开龙甲冷，玉堂秋闭凤笙低。
欢筵每恕娇娥醉，闲枥犹惊战马嘶。
长怪鲁儒头枉白，不亲弓劒觅丹梯。','',''),('quantangshi-39526','送卢尚书赴灵武','張蠙','quantangshi','','卷40','西北正传烽候急，灵州共喜信臣居。
从军尽是清才去，属郡无非大将除。
新地进图移汉界，古城遗碣见蕃书。
山川不异江湖景，宾馆常闻食有鱼。','',''),('quantangshi-39527','投翰林张侍郎','張蠙','quantangshi','','卷40','举家贫拾海边樵，来认仙宗在碧霄。
丹穴虽无凡羽翼，灵椿还向细枝条。
九衢马识他门少，十载身辞故国遥。
愿与吾君作霖雨，且应平地活枯苗。','',''),('quantangshi-39528','投翰林萧侍郎','張蠙','quantangshi','','卷40','九仞墙边绝路岐，野才非合自求知。
灵湫岂要鱼栖浪，仙桂那容鸟寄枝。
纤草不销春气力，微尘还助岳形仪。
从来为学投文镜，文镜如今更有谁。','',''),('quantangshi-39529','宴驸马宅','張蠙','quantangshi','','卷40','牙香禁乐镇相携，日日君恩降紫泥。
红药院深人半醉，绿杨门掩马频嘶。
座中古物多仙意，壁上新诗有御题。
别向庭芜置吟石，不教宫妓踏成蹊。','',''),('quantangshi-39530','边将','張蠙','quantangshi','','卷40','上马乘秋欲建勋，飞弧夜阙出师频。
若无紫塞烟尘事，谁识青楼歌舞人。
战骨沙中金镞在，贺筵花畔玉蝉新。
由来边卒皆如此，只是君门合杀身。','',''),('quantangshi-39531','赠水军都将','張蠙','quantangshi','','卷40','平生为有安邦术，便别秋曹最上阶。
战舰却容儒客卧，公厅唯伴野僧斋。
裁书榭迥冰胶笔，养药堂深藓惹鞋。
直待门前见幢节，始应高惬圣君怀。','',''),('quantangshi-39532','赠九江太守','張蠙','quantangshi','','卷40','江头蹔驻木兰船，渔父来夸太守贤。
二邑旋添新户口，四营渐废旧戈鋋。
笙歌不似经荒后，礼乐犹如未战前。
昨日西亭从游骑，信旗风里说诗篇。','',''),('quantangshi-39533','赠信安太守','張蠙','quantangshi','','卷40','三衢正对福星时，喜得君侯妙抚绥。
甲士散教耕壠亩，书生闲许从旌旗。
条章最是贫家喜，禾黍仍防别郡饥。
昨日中官说天意，即飞丹诏立新碑。','',''),('quantangshi-39534','赠江都郑明府','張蠙','quantangshi','','卷40','他人岂是称才术，才术须观力有余。
兵乱几年临剧邑，公清终日似闲居。
牀头怪石神仙画，箧里华牋将相书。
更欲栖踪近彭泽，香炉峰下结茅庐。','',''),('quantangshi-39535','赠南昌宰','張蠙','quantangshi','','卷40','假邑邀真邑命分，明庭元有至公存。
每锄奸弊同荆棘，唯抚孤惸似子孙。
折狱不曾偏下笔，灵襟长是大开门。
新衔便合兼朱绂，应待苍生更举论。','',''),('quantangshi-39536','赠丘衙推','張蠙','quantangshi','','卷40','仙都高处掩柴扉，人世闻名见者稀。
诗逸不拘凡对属，易穷皆达圣玄微。
偶携童穉离青嶂，便被君侯换白衣。
任醉宾筵莫深隐，绮罗丝竹胜渔矶。','',''),('quantangshi-39537','献所知','張蠙','quantangshi','','卷40','迹熟荀家见弟兄，九霄同与指前程。
吹嘘渐觉馨香出，梦寐长疑羽翼生。
住僻骅骝皆识路，来频鹦鹉亦知名。
登龙不敢怀他愿，祗望为霖致太平。','',''),('quantangshi-39538','投所知','張蠙','quantangshi','','卷40','十五年看帝里春，一枝头白未酬身。
自闻离乱开公道，渐数孤平少屈人。
劣马再寻商岭路，扁舟重寄越溪滨。
省郎门似龙门峻，应借风雷变涸鳞。','',''),('quantangshi-39539','南康夜宴东溪留别郡守陆郎中','張蠙','quantangshi','','卷40','飘然野客才无取，多谢君侯独见知。
竹叶樽前教驻乐，桃花纸上待君诗。
香迷蛱蝶投红烛，舞拂蒹葭倚翠帷。
明发别愁何处去，片帆天际酒醒时。','',''),('quantangshi-39540','言怀','張蠙','quantangshi','','卷40','十载声沈觉自非，贱身元合衣荷衣。
岂能得路陪先达，却拟还家望少微。
战马到秋长泪落，伤禽无夜不魂飞。
平生祗学穿杨箭，更向何门是见机。','',''),('quantangshi-39541','喜友人日南回','張蠙','quantangshi','','卷40','南游曾去海南涯，此去游人不易归。
白日雾昏张夜烛，穷冬气暖着春衣。
溪荒毒鸟随船啅，洞黑冤蛇出树飞。
重入帝城何[寂]寞，共回迁客半轻肥。','',''),('quantangshi-39542','下第述怀','張蠙','quantangshi','','卷40','十载长安迹未安，杏花还是看人看。
名从近事方知险，诗到穷玄更觉难。
世薄不惭云路晚，家贫唯怯草堂寒。
如何直道为身累，坐月眠霜思枉干。','',''),('quantangshi-39543','华阳道者','張蠙','quantangshi','','卷40','华阳洞里持真经，心嫌来客风尘腥。
惟餐白石过白日，拟骑青竹上青冥。
翔螭岂作汉武驾，神娥徒降燕昭庭。
长生不必论贵贱，却是幽人骨主灵。','',''),('quantangshi-39544','夏日题老将林亭','張蠙','quantangshi','','卷40','百战功成翻爱静，侯门渐欲似仙家。
墙头雨细垂纤草，水面风回聚落花。
井放辘轳闲侵酒，笼开鹦鹉报煎茶。
几人图在凌烟阁，曾不交锋向塞沙。','',''),('quantangshi-39545','观江南牡丹','張蠙','quantangshi','','卷40','北地花开南地风，寄根还与客心同。
羣芳尽怯千般态，几醉能消一番红。
举世秪将华胜实，真禅元喻色为空。
近年明主思王道，不许新栽满六宫。','',''),('quantangshi-39546','钱塘夜宴留别郡守','張蠙','quantangshi','','卷40','四方骚动一州安，夜列罇罍伴客懽。
觱栗调高山阁迥，虾蟆更促海声寒。
屏间佩响藏歌妓，幕外刀光立从官。
沈醉不愁归棹远，晚风吹上子陵滩。','',''),('quantangshi-39547','送薛郎中赴江州','張蠙','quantangshi','','卷40','几州闻出刺，谣美有江民。
正面传天旨，悬心祷岳神。
尺书先假路，红斾旋烧尘。
郡显山川别，衙开将吏新。
散招僧坐暑，闲载客行春。
听事棊忘着，探题酒乱巡。
好编高隐传，多貌上升真。
近日居清近，求人在此人。','',''),('quantangshi-39548','送南海僧游蜀','張蠙','quantangshi','','卷40','真修绝故乡，一衲度暄凉。
此世能先觉，他生岂再忘。
定中船过海，腊后路沿湘。
野迥鸦随笠，山深虎背囊。
瀑流垂石室，萝蔓盖铜梁。
却后何年会，西方有上房。','',''),('quantangshi-39549','和友人许裳题宣平里古藤','張蠙','quantangshi','','卷40','欲结千年茂，生来便近松。
迸根通井润，交叶覆庭穠。
历代频更主，盘空渐变龙。
昼风圆影乱，宵雨细声重。
盖密胜丹桂，层危类远峰。
嫩条悬野鼠，枯节呌秋蛩。
翠老霜难蚀，皴多藓乍封。
几家遥共翫，何寺不堪容。
客对忘离榻，僧看误过钟。
顷因陪预作，终夕遶枝筇。','',''),('quantangshi-39550','十五夜与友人对月','張蠙','quantangshi','','卷40','每到月圆思共醉，不宜同醉不成欢。
一千二百如轮夜，浮世谁能得尽看。','',''),('quantangshi-39551','青冢','張蠙','quantangshi','','卷40','倾国可能胜效国，无劳冥寞更思回。
太真虽是承恩死，祗作飞尘向马嵬。','',''),('quantangshi-39552','古战场','張蠙','quantangshi','','卷40','荒骨潜销垒已平，汉家曾说此交兵。
如何万古冤魂在，风雨时闻有战声。','',''),('quantangshi-39553','赠段逸人','張蠙','quantangshi','','卷40','长筇自担药兼琴，话着名山即拟寻。
从听世人权似火，不能烧得卧云心。','',''),('quantangshi-39554','赠郑司业','張蠙','quantangshi','','卷40','晚学更求来世达，正怀非与百邪侵。
古人名在今人口，不合于名不苦心。','',''),('quantangshi-39555','上所知','張蠙','quantangshi','','卷40','初向众中留姓氏，敢期言下致时名。
而今马亦知人意，每到门前不肯行。','',''),('quantangshi-39556','别郑仁表','張蠙','quantangshi','','卷40','春雷醉别镜湖边，官显才狂正少年。
红烛满汀歌舞散，美人迎上木兰船。','',''),('quantangshi-39557','言怀','張蠙','quantangshi','','卷40','不将高盖竟烟尘，自向蓬茅认此身。
唐祖本来成大业，岂非姚宋是平人。','',''),('quantangshi-39558','叙怀','張蠙','quantangshi','','卷40','月里路从何处上，江边身合几时归。
十年九陌寒风夜，梦扫芦花絮客衣。','',''),('quantangshi-39559','抒怀','張蠙','quantangshi','','卷40','几出东堂谢不才，便甘闲望故山回。
翻思未是离家久，更有人从外国来。','',''),('quantangshi-39560','自讽','張蠙','quantangshi','','卷40','鹿鸣筵上强称贤，一送离家十四年。
同隐海山烧药伴，不求丹桂却登仙。','',''),('quantangshi-39561','伤贾岛','張蠙','quantangshi','','卷40','生为明代苦吟身，死作长江一逐臣。
可是当时少知己，不知知己是何人。','',''),('quantangshi-39562','再游西山赠许尊师','張蠙','quantangshi','','卷40','别后已闻师得道，不期犹在此山头。
昔时霜鬓今如漆，疑是年光却倒流。','',''),('quantangshi-39563','宫词','張蠙','quantangshi','','卷40','日透珠帘见冕旒，六宫争逐百花球。
回看不觉君王去，已听笙歌在远楼。','',''),('quantangshi-39564','经范蠡旧居','張蠙','quantangshi','','卷40','一变姓名离百越，越城犹在范家无。
他人不见扁舟意，却笑轻生泛五湖。','',''),('quantangshi-39565','题嘉陵驿','張蠙','quantangshi','','卷40','嘉陵路恶石和泥，行到长亭日已西。
独倚阑干正惆怅，海棠花里鹧鸪啼。','',''),('quantangshi-39566','龟山寺晚望','張蠙','quantangshi','','卷40','四面湖光绝路岐，䴙鹈飞起暮钟时。
渔舟不用悬帆席，归去乘风插柳枝。','',''),('quantangshi-39567','华山孤松','張蠙','quantangshi','','卷40','石罅引根非土力，冒寒犹助岳莲光。
绿槐生在膏腴地，何得无心拒雪霜。','',''),('quantangshi-39568','吊万人冢','張蠙','quantangshi','','卷40','兵罢淮边客路通，乱鸦来去噪寒空。
可怜白骨攒孤冢，尽为将军觅战功。','',''),('quantangshi-39569','送友尉蜀中','張蠙','quantangshi','','卷40','故友汉中尉，请为西蜀吟。
人家多种橘，风土爱弹琴。
水向昆明阔，山通大夏深。
理闲无别事，时寄一登临。','',''),('quantangshi-39570','长安寓怀','張蠙','quantangshi','','卷40','九衢秋雨掩闲扉，不似干名似息机。
贫病却慙墙上土，年来犹自换新衣。','',''),('quantangshi-39571','费征君旧居','張蠙','quantangshi','','卷40','浮世抛身外，栖踪入九华。
遗篇补乐府，旧籍隶仙家。
池静龟升树，庭荒鹤隐花。
古来天子命，还少到烟霞。','',''),('quantangshi-39572','晨兴','翁承贊','quantangshi','','卷40','晨起竹轩外，逍遥清兴多。
早凉生户牖，孤月照关河。
旅食甘藜藿，归心忆薜萝。
一尊如有地，放意且狂歌。','',''),('quantangshi-39573','题莒潭安闽院','翁承贊','quantangshi','','卷40','祧宗营祀舍，幽异胜珠林。
名士穿云访，飞禽傍竹吟。
牕含孤岫影，牧卧断霞阴。
景福滋闽壤，芳名亘古今。','',''),('quantangshi-39574','华下霁后晓眺','翁承贊','quantangshi','','卷40','结茅幽寂近禅林，霁景烟光着柳阴。
千嶂华山云外秀，万重乡思望中深。
老嫌白发还偷镊，贫对春风亦强吟。
花畔水边人不会，腾腾闲步一披襟。','',''),('quantangshi-39575','喜弟承检登科','翁承贊','quantangshi','','卷40','两篇佳句敌琼瑰，怜我三清道路开。
荆璞献多还得售，桂堂恩在敢轻回。
花繁不怕寻香客，榜到应倾贺喜杯。
知尔苦心功业就，早携长策出山来。','',''),('quantangshi-39576','蒙闽王改赐乡里','翁承贊','quantangshi','','卷40','乡名文秀里光贤，别向钧台造化权。
阀阅便因今日贵，德音兼与后人传。
自从受赐身无力，向未酬恩骨肯镌。
归阙路遥心更切，不嫌扶病倚旌旃。','',''),('quantangshi-39577','访建阳马驿僧亚齐','翁承贊','quantangshi','','卷40','萧萧风雨建阳溪，溪畔维舟访亚齐。
一轴新诗劒潭北，十年旧识华山西。
吟魂惜向江村老，空性元知世路迷。
应笑乘轺青琐客，此时无暇听猿啼。','',''),('quantangshi-39578','题景祥院','翁承贊','quantangshi','','卷40','一溪拖碧遶崔嵬，瓶钵偏宜向此隈。
农罢树阴黄犊卧，斋时山下白衣来。
松多往日门人种，路是前朝释子开。
三卷贝多金粟语，可能心炼得成灰。','',''),('quantangshi-39579','寄舍弟承裕员外','翁承贊','quantangshi','','卷40','江花岸草晚萋萋，公子王孙思合迷。
无主园林饶采伐，忘情鸥鸟恣高低。
长江月上鱼翻鬣，荒圃人稀獭印蹄。
何事斜阳再回首，休愁离别岘山西。','',''),('quantangshi-39580','文明殿受册封闽王','翁承贊','quantangshi','','卷40','龙墀班听漏声长，竹帛昭勋扑御香。
鸣佩洞庭辞帝主，登车故里册闽王。
一千年改江山瑞，十万军蒙雨露光。
吟寄短篇追往事，留文功业不寻常。','',''),('quantangshi-39581','御命归乡蒙赐锦衣','翁承贊','quantangshi','','卷40','九重宣旨下丹墀，面对天颜赐锦衣。
中使擎来三殿晓，宝箱开处五云飞。
德音耳聆君恩重，金印腰悬已力微。
更待临轩陈鼓吹，星轺便指故乡归。','',''),('quantangshi-39582','奉使封闽王归京洛','翁承贊','quantangshi','','卷40','泥缄紫诰御恩光，信马嘶风出洛阳。
此去愿言归梓里，预凭魂梦展维桑。
客程回首瞻文陛，驿路乘轺忆故乡。
指日还家堪自重，恩荣昼锦贺封王。','',''),('quantangshi-39583','奉使封王次宜春驿','翁承贊','quantangshi','','卷40','微宦淹留鬓已斑，此心长忆旧林泉。
不因列土封千乘，争得衔恩拜二天。
云断自宜乡树出，月高犹伴客心悬。
夜来梦到南台上，徧看江山胜往年。','',''),('quantangshi-39584','甲子岁衔命到家至榕城册封次日闽王降旌旗于新丰市堤饯别','翁承贊','quantangshi','','卷40','登庸楼上方停乐，新市堤边又举杯。
正是离情伤远别，忽闻台旨许重来。
此时暂与交亲好，今日还将简册回。
争得长房犹在世，缩教地近钓鱼台。','',''),('quantangshi-39585','寄示儿孙','翁承贊','quantangshi','','卷40','力学烧丹二十年，辛勤方得遇真仙。
便随羽客归三岛，旋听霓裳适九天。
得路自能酬造化，立身何必恋林泉。
予家药鼎分明在，好把仙方次第传。','',''),('quantangshi-39586','天佑元年以右拾遗使册闽王而作','翁承贊','quantangshi','','卷40','蓬莱宫阙晓光匀，红案舁麻降紫宸。
鸾奏八音谐律吕，凤衔五色显丝纶。
萧何相印钧衡重，韩信斋坛雨露新。
得侍丹墀官异宠，此身何幸沐恩频。','',''),('quantangshi-39587','汉上登舟忆闽','翁承贊','quantangshi','','卷40','汉臯亭畔起西风，半挂征帆立向东。
久客自怜归路近，筭程不怕酒觞空。
参差雁阵天初碧，零落渔家蓼欲红。
一片归心随去棹，愿言指日拜文翁。','',''),('quantangshi-39588','对雨述怀示弟承检','翁承贊','quantangshi','','卷40','淋淋霎霎结秋霖，欲使秦城叹陆沈。
晓势遮回朝客马，夜声滴破旅人心。
青苔重叠封颜巷，白发萧疎引越吟。
不有惠连同此景，江南归思几般深。','',''),('quantangshi-39589','题壶山','翁承贊','quantangshi','','卷40','井邑斜连北，蓬瀛直倚东。
秋高岩溜白，日上海波红。','',''),('quantangshi-39590','题故居','翁承贊','quantangshi','','卷40','一为鹅子二连花，三望青湖四石斜。
惟有岭湖居第五，山前却是宰臣家。','',''),('quantangshi-39591','题槐','翁承贊','quantangshi','','卷40','雨中妆点望中黄，句引蝉声送夕阳。
忆昔当年随计吏，马蹄终日为君忙。','',''),('quantangshi-39592','擢进士','翁承贊','quantangshi','','卷40','霓旌引上大罗天，别领新衔意自怜。
蝴蝶流莺莫先去，满城春色属羣仙。','',''),('quantangshi-39593','擢探花使三首 一','翁承贊','quantangshi','','卷40','洪崖差遣探花来，检点芳丛饮数杯。
深紫浓香三百朵，明朝为我一时开。','',''),('quantangshi-39594','擢探花使三首 二','翁承贊','quantangshi','','卷40','九重烟暖折槐芽，自是升平好物华。
今日始知春气味，长安虚过四年花。','',''),('quantangshi-39595','擢探花使三首 三','翁承贊','quantangshi','','卷40','探花时节日偏长，恬淡春风称意忙。
每到黄昏醉归去，紵衣惹得牡丹香。','',''),('quantangshi-39596','书斋谩兴二首 一','翁承贊','quantangshi','','卷40','池塘四五尺深水，篱落两三般样花。
过客不须频问姓，读书声里是吾家。','',''),('quantangshi-39597','书斋谩兴二首 二','翁承贊','quantangshi','','卷40','官事归来衣雪埋，儿童灯火小茅斋。
人家不必论贫富，惟有读书声最佳。','',''),('quantangshi-39598','辞闽王归朝寄倪先辈','翁承贊','quantangshi','','卷40','时人莫讶再还乡，简册分明劒佩光。
驷马高车太常乐，登庸门下忆贤良。','',''),('quantangshi-39599','晓望','翁承贊','quantangshi','','卷40','清霜散漫似轻岚，玉阙参差万象涵。
独上秦台最高处，旧山依约在东南。','',''),('quantangshi-39600','万寿寺牡丹','翁承贊','quantangshi','','卷40','烂熳香风引贵游，高僧移步亦迟留。
可怜殿角长松色，不得王孙一举头。','',''),('quantangshi-39601','松','翁承贊','quantangshi','','卷40','倚涧临溪自屈蟠，雪花销尽藓花干。
幽枝好折为谈柄，入手方知有岁寒。','',''),('quantangshi-39602','柳 一','翁承贊','quantangshi','','卷40','斜拂中桥远映楼，翠光骀荡晓烟收。
洛阳才子多情思，横把金鞭约马头。','',''),('quantangshi-39603','柳 二','翁承贊','quantangshi','','卷40','高出营门远出墙，朱阑门闭绿成行。
将军宴罢东风急，闲衬旌旗簇画堂。','',''),('quantangshi-39604','柳 三','翁承贊','quantangshi','','卷40','彭泽先生酒满船，五株栽向九江边。
长条细叶无穷尽，管领春风不计年。','',''),('quantangshi-39605','柳 四','翁承贊','quantangshi','','卷40','炀帝东游意绪多，宫娃眉翠两相和。
一声水调春风暮，千里交阴锁汴河。','',''),('quantangshi-39606','柳 五','翁承贊','quantangshi','','卷40','缠绕春情卒未休，秦娥萧史两相求。
玉句阑内朱帘卷，瑟瑟丝笼十二楼。','',''),('quantangshi-39607','隋堤柳','翁承贊','quantangshi','','卷40','春半烟深汴水东，黄金丝软不胜风。
轻笼行殿迷天子，抛掷长安似梦中。','',''),('quantangshi-39608','句','翁承贊','quantangshi','','卷40','烟萝况逼神仙窟，丹竈还应许独寻。','',''),('quantangshi-39609','送僧归北岩寺','黃滔','quantangshi','','卷40','北岩泉石清，本自高僧住。
新松五十年，藤萝成古树。
题诗昔佳士，清风二林喻。
上智失扣关，多被浮名误。
莲扃压月涧，空美黄金布。
江翻岛屿沈，木落楼台露。
伊余东还际，每起烟霞慕。
旋为俭府招，未得穷野步。
西轩白云阁，师辞洞庭寓。
越城今送归，心到焚香处。','',''),('quantangshi-39610','寓言','黃滔','quantangshi','','卷40','流年五十前，朝朝倚少年。
流年五十后，日日侵皓首。
非通非介人，谁论四十九。
贤哉蘧伯玉，清风独不朽。','',''),('quantangshi-39611','长安书事','黃滔','quantangshi','','卷40','终不离青山，谁道云无心。
却是白云士，有时出中林。
昨日擎紫泥，明日要黄金。
炎夏羣木死，北海惊波深。
伏蒲无一言，草疏贺德音。','',''),('quantangshi-39612','贾客','黃滔','quantangshi','','卷40','大舟有深利，沧海无浅波。
利深波也深，君意竟如何。
鲸鲵齿上路，何如少经过。','',''),('quantangshi-39613','寄友人','黃滔','quantangshi','','卷40','君爱桃李花，桃李花易飘。
妾怜松柏色，松柏色难凋。
当年识君初，指期非一朝。
今辰见君意，日暮何萧条。
入门有势利，孰能无嚣嚣。','',''),('quantangshi-39614','落花','黃滔','quantangshi','','卷40','落花辞高树，最是愁人处。
一一旋成泥，日暮有风雨。
不如沙上蓬，根断随长风。
飘然与道俱，无情任西东。','',''),('quantangshi-39615','寄徐正字夤','黃滔','quantangshi','','卷40','八月月如冰，登楼见姑射。
美人隔千里，相思无羽驾。
红兰裛露衰，谁以流光讶。
何当诗一句，同吟祝玄化。','',''),('quantangshi-39616','秋夕贫居','黃滔','quantangshi','','卷40','听歌桂席阑，下马槐烟里。
豪门腐粱肉，穷巷思糠秕。
孤灯照独吟，半壁秋花死。
迟明亦如晦，鸡唱徒为尔。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-39617','书怀寄友人','黃滔','quantangshi','','卷40','此生如孤灯，素心挑易尽。
不及如顽石，非与磨砻近。
常思扬子云，五藏曾离身。
寂寞一生中，千载空清芬。','',''),('quantangshi-39618','闺怨','黃滔','quantangshi','','卷40','妾家五岭南，君戍三城北。
雁来虽有书，衡阳越不得。
别久情易料，岂在窥翰墨。
塞上无烟花，宁思妾颜色。','',''),('quantangshi-39619','喜翁文尧员外病起','黃滔','quantangshi','','卷40','卫玠羊车悬，长卿驷马姿。
天嫌太端正，神乃减风仪。
饮冰俾消渴，断谷皆清羸。
越僧夸艾炷，秦女隔花枝。
自能论苦器，不假求良医。
惊杀漳滨鬼，错与刘生随。
昨日已如虎，今朝谒荀池。
扬鞭入王门，四面人熙熙。
青桂任霜霰，尺璧无瑕疵。
回尘却惆怅，归阙难迟迟。','',''),('quantangshi-39620','寄郑县李侍御','黃滔','quantangshi','','卷40','古县新烟火，东西入客诗。
静长如假日，贫更甚闲时。
僧借松萝住，人将雨雪期。
三年一官罢，岳石看成碑。','',''),('quantangshi-39621','上李补阙','黃滔','quantangshi','','卷40','十洲非暂别，龙尾肯慵登。
谏草封山药，朝衣施衲僧。
月留江客待，句历钓船征。
终恐林栖去，飡霞叶上升。','',''),('quantangshi-39622','送李山人往湘中','黃滔','quantangshi','','卷40','汉渚往湘川，乘流入远天。
新秋无岸水，明月有琴船。
露坐应通晓，萍居恐隔年。
岳峰千万仞，知上啸猿巅。','',''),('quantangshi-39623','书崔少府居','黃滔','quantangshi','','卷40','鲁史蜀琴旁，陶然举一觞。
夕阳明岛屿，秋水浅池塘。
世乱怜官替，家贫值岁荒。
前峰亦曾宿，知有辟寒方。','',''),('quantangshi-39624','敷水卢校书','黃滔','quantangshi','','卷40','九霄无诏下，何事近清尘。
宅带松萝僻，日唯猿鸟亲。
吟高仙掌月，期有洞庭人。
莫问烟霞句，悬知见岳神。','',''),('quantangshi-39625','寄汉上友人','黃滔','quantangshi','','卷40','襄汉多清景，东游已不能。
蒹葭照流水，风雨扑孤灯。
献赋闻新雁，思山见去僧。
知君北来日，惆怅亦难胜。','',''),('quantangshi-39626','贻林铎','黃滔','quantangshi','','卷40','终被春闱屈，低回至白头。
寄家僧许岳，钓浦雨移洲。
战士曾怜善，豪门不信愁。
王孙草还绿，何处拟羁游。','',''),('quantangshi-39627','书怀','黃滔','quantangshi','','卷40','退耕逢歉岁，逐贡愧行朝。
道在愁虽浅，吟劳鬓欲凋。
破村虹入井，孤馆客投魈。
谁怕秋风起，听蝉度渭桥。','',''),('quantangshi-39628','送陈明府归衡阳','黃滔','quantangshi','','卷40','鶵鹤兼留下，单车出柳烟。
三年两殊考，一日数离筵。
久别湖波绿，相思岳月圆。
翠萝曾隐处，定恐却求仙。','',''),('quantangshi-39629','秋辞江南','黃滔','quantangshi','','卷40','灞陵桥上路，难负一年期。
积雨鸿来夜，重江客去时。
劳生多故疾，渐老少新知。
惆怅都堂内，无门雪滞遗。','',''),('quantangshi-39630','入关旅次言怀','黃滔','quantangshi','','卷40','寸心唯自切，上国与谁期。
月晦时风雨，秋深日别离。
便休终未肯，已苦不能疑。
独愧商山路，千年四皓祠。','',''),('quantangshi-39631','贻李山人','黃滔','quantangshi','','卷40','野步爱江滨，江僧得见频。
新文无古集，往事有清尘。
松竹寒时雨，池塘胜处春。
定应云雨内，陶谢是前身。','',''),('quantangshi-39632','寄边上从事','黃滔','quantangshi','','卷40','斜日下孤城，长吟出点兵。
羽书和客卷，边思杂诗情。
朔雪定鸿翼，西风严角声。
吟余多独坐，沙月对楼生。','',''),('quantangshi-39633','题东林寺元佑上人院','黃滔','quantangshi','','卷40','庐阜东林寺，良游耻未曾。
半生随计吏，一日对禅僧。
泉远携茶看，峰高结伴登。
迷津出门是，子细问三乘。','',''),('quantangshi-39634','送陈樵下第东归','黃滔','quantangshi','','卷40','青山烹茗石，沧海寄家船。
虽得重吟历，终难任意眠。
砧疎连寺柳，风爽彻城泉。
送目红蕉外，来期已杳然。','',''),('quantangshi-39635','寄陈磻隐居','黃滔','quantangshi','','卷40','道经前辈许，名拔后时喧。
虚左中兴榜，无先北海尊。
新文汉氏史，别墅谢公村。
须到三征处，堂堂谒帝阍。','',''),('quantangshi-39636','寄林宽','黃滔','quantangshi','','卷40','相知四十年，故国与长安。
俱喜今辰在，休论往岁难。
海鸣秋日黑，山直夏风寒。
终始前儒道，升沈尽一般。','',''),('quantangshi-39637','退居','黃滔','quantangshi','','卷40','老归江上村，孤寂欲何言。
世乱时人物，家贫后子孙。
青山寒带雨，古木夜啼猿。
惆怅西川举，戎装度剑门。','',''),('quantangshi-39638','送友人边游','黃滔','quantangshi','','卷40','衔杯国门外，分手见残阳。
何日还南越，今朝往北荒。
砂城经雨坏，虏骑入秋狂。
亲咏关山月，归吟鬓的霜。','',''),('quantangshi-39639','下第出京','黃滔','quantangshi','','卷40','还失礼官求，花时出雍州。
一生为远客，几处未曾游。
故疾江南雨，单衣蓟北秋。
茫茫数年事，今日泪俱流。','',''),('quantangshi-39640','游东林寺','黃滔','quantangshi','','卷40','平生爱山水，下马虎溪时。
已到终嫌晚，重游预作期。
寺寒三伏雨，松偃数朝枝。
翻译如曾见，白莲开旧池。','',''),('quantangshi-39641','赠怀光上人','黃滔','quantangshi','','卷40','谢城还拥入，师以接人劳。
过午休斋惯，离经吐论高。
顶寒拳素发，珠锐走红绦。
终忆泉山寺，听猨看海涛。','',''),('quantangshi-39642','忆庐山旧游','黃滔','quantangshi','','卷40','前年入庐岳，数宿在灵溪。
残烛松堂掩，孤峰月狖啼。
平生为客老，胜境失云栖。
纵有重游日，烟霞会恐迷。','',''),('quantangshi-39643','别友人','黃滔','quantangshi','','卷40','莫恨东墙下，频伤命不通。
苦心如有感，他日自推公。
雨夜扁舟发，花时别酒空。
越山烟翠在，终愧卧云翁。','',''),('quantangshi-39644','陈侍御新居','黃滔','quantangshi','','卷40','幕客开新第，词人遍有诗。
山怜九仙近，石买太湖奇。
树势想高日，地形夸得时。
自然成避俗，休与白云期。','',''),('quantangshi-39645','寄从兄璞','黃滔','quantangshi','','卷40','纵徴终不起，相与避烟尘。
待到中兴日，同看上国春。
新诗说人尽，旧宅落花频。
移觅深山住，啼猿作四邻。','',''),('quantangshi-39646','寄李校书游简寂观','黃滔','quantangshi','','卷40','古观云溪上，孤怀永夜中。
梧桐四更雨，山水一庭风。
诗得如何句，仙游最胜宫。
却愁逢羽客，相与入烟空。','',''),('quantangshi-39647','寄友人山居','黃滔','quantangshi','','卷40','断峤沧江上，相思恨阻寻。
高斋秋不掩，几夜月当吟。
落石有泉滴，盈庭无树阴。
茫茫名利内，何以拂尘襟。','',''),('quantangshi-39648','上刑部卢员外','黃滔','quantangshi','','卷40','谁识在官意，开门树色间。
寻幽频宿寺，乞假拟归山。
半白侵吟鬓，微红见药颜。
不知琴月夜，几客得同闲。','',''),('quantangshi-39649','送友人游边','黃滔','quantangshi','','卷40','虏酒不能浓，纵倾愁亦重。
关河初落日，霜雪下穷冬。
野烧枯蓬旋，沙风匹马冲。
蓟门无易过，千里断人踪。','',''),('quantangshi-39650','和友人酬寄','黃滔','quantangshi','','卷40','新发烟霞咏，高人得以传。
吟销松际雨，冷咽石间泉。
大国兵戈日，故乡饥馑年。
相逢江海上，宁免一潸然。','',''),('quantangshi-39651','下第','黃滔','quantangshi','','卷40','昨夜孤灯下，阑干泣数行。
辞家从早岁，落第在初场。
青草湖田改，单车客路忙。
何人立功业，新命到封王。','',''),('quantangshi-39652','过商山','黃滔','quantangshi','','卷40','燕雁一来后，人人尽到关。
如何冲腊雪，独自过商山。
羸马高坡下，哀猿绝壁间。
此心无处说，鬓向少年斑。','',''),('quantangshi-39653','旅怀','黃滔','quantangshi','','卷40','萧飒闻风叶，惊时不自堪。
宦名中夜切，人事长年谙。
古画僧留与，新知客遇谈。
乡心随去雁，一一到江南。','',''),('quantangshi-39654','冬暮山舍喜标上人见访','黃滔','quantangshi','','卷40','寂寞三冬杪，深居业尽抛。
迳松开雪后，砌竹忽僧敲。
茗汲冰销溜，炉烧鹊去巢。
共谈慵僻意，微日下林梢。','',''),('quantangshi-39655','关中言怀','黃滔','quantangshi','','卷40','三秦五岭意，不得不依然。
迹寓枯槐曲，业芜芳草川。
花当落第眼，雨暗出城天。
层阁浮云外，何人动管弦。','',''),('quantangshi-39656','题友人山居','黃滔','quantangshi','','卷40','到君栖迹所，竹迳与衡门。
亦在干坤内，独无尘俗喧。
新泉浮石藓，崩壁露松根。
更说寻僧处，孤峰上啸猿。','',''),('quantangshi-39657','寄敷水卢校书','黃滔','quantangshi','','卷40','谏省垂清论，仙曹岂久临。
虽专良史业，未畏直臣心。
路入丹霄近，家藏华岳深。
还如韩吏部，谁不望知音。','',''),('quantangshi-39658','赠明州霍员外','黃滔','quantangshi','','卷40','惠化如施雨，邻州亦可依。
正衙无吏近，高会觉人稀。
海日旗边出，沙禽角外归。
四明多隐客，闲约到岩扉。','',''),('quantangshi-39659','题友人山斋','黃滔','quantangshi','','卷40','疎竹漏斜晖，庭间阴复遗。
句成苔石茗，吟弄雪窗碁。
沙草泉经涩，林斋客集迟。
西风虚见逼，未拟问京师。','',''),('quantangshi-39660','书事','黃滔','quantangshi','','卷40','望岁心空切，耕夫尽把弓。
千家数人在，一税十年空。
没阵风沙黑，烧城水陆红。
飞章奏西蜀，明诏与殊功。','',''),('quantangshi-39661','题山居逸人','黃滔','quantangshi','','卷40','十亩余芦苇，新秋看雪霜。
世人谁到此，尘念自应忘。
斜日风收钓，深秋雨信梁。
不知双阙下，何以谓轩裳。','',''),('quantangshi-39662','题郑山人居','黃滔','quantangshi','','卷40','履迹遍莓苔，幽枝间药裁。
枯杉[擎]雪朵，破牖触风开。
泉自孤峰落，人从诸洞来。
终期宿清夜，斟茗说天台。','',''),('quantangshi-39663','秋晚山居','黃滔','quantangshi','','卷40','爽气遍搜空，难堪倚望中。
孤烟愁落日，高木病西风。
山寂樵声出，露凉蝉思穷。
此时尘外事，幽默几人同。','',''),('quantangshi-39664','游山','黃滔','quantangshi','','卷40','洞门穿瀑布，尘世岂能通。
曾有游山客，来逢采药翁。
异花寻复失，幽迳蹑还穷。
拟作经宵计，风雷立满空。','',''),('quantangshi-39665','题王侍御宅内亭子','黃滔','quantangshi','','卷40','俗间尘外境，郭内宅中亭。
或有人家创，还无莲幕馨。
石曾湖岸见，琴误岳楼听。
来客频频说，终须作画屏。','',''),('quantangshi-39666','题道成上人院','黃滔','quantangshi','','卷40','花宫城郭内，师住亦清凉。
何必天台寺，幽蝉瀑布房。
簟舒湘竹滑，茗煮蜀芽香。
更看道高处，居侯题翠梁。','',''),('quantangshi-39667','贫居冬杪','黃滔','quantangshi','','卷40','数塞未求通，吾非学养蒙。
穷居岁杪雨，孤坐夜深风。
年长慙昭代，才微辱至公。
还愁把春酒，双泪汚杯中。','',''),('quantangshi-39668','贻张蠙','黃滔','quantangshi','','卷40','梦思非一日，携手却凄凉。
诗见江南雹，游经塞北霜。
驱车先五漏，把菊后重阳。
惆怅天边桂，谁教岁岁香。','',''),('quantangshi-39669','晚春关中','黃滔','quantangshi','','卷40','忍历通庄出，东风舞酒旗。
百花无看处，三月到残时。
游塞闻兵起，还吴值岁饥。
定唯荒寺里，坐与噪蝉期。','',''),('quantangshi-39670','河梁','黃滔','quantangshi','','卷40','五原人走马，昨夜到京师。
绣户新夫妇，河梁生别离。
陇花开不艳，羌笛静犹悲。
惆怅良哉辅，铿锵立凤池。','',''),('quantangshi-39671','送翁拾遗','黃滔','quantangshi','','卷40','还家俄赴阙，别思肯凄凄。
山坐轺车看，诗持谏笔题。
天开中国大，地设四维低。
拜舞吾君后，青云更有梯。','',''),('quantangshi-39672','逢友人','黃滔','quantangshi','','卷40','彼此若飘蓬，二年何所从。
帝都秋未入，江馆夜相逢。
瘴岭行冲夏，边沙住隔冬。
旅愁论未尽，古寺扣晨钟。','',''),('quantangshi-39673','寄湘中郑明府','黃滔','quantangshi','','卷40','县与白云连，沧洲况县前。
岳僧同夜坐，江月看秋圆。
琴拂莎庭石，茶担乳洞泉。
莫耽云水兴，疲俗待君痊。','',''),('quantangshi-39674','寄少常卢同年','黃滔','quantangshi','','卷40','官拜少常休，青緺换鹿裘。
狂歌离乐府，醉梦到瀛洲。
古器岩耕得，神方客谜留。
清溪莫沈钓，王者或畋游。','',''),('quantangshi-39675','伤翁外甥','黃滔','quantangshi','','卷40','江头去时路，归客几纷纷。
独在异乡殁，若为慈母闻。
青春成大夜，新雨坏孤坟。
应作芝兰出，泉台月桂分。','',''),('quantangshi-39676','东山之游未遂渐逼行期作四十字奉寄翁文尧员外','黃滔','quantangshi','','卷40','轺车难久驻，须到别离时。
北阙定归去，东山空作期。
绿苔劳扫径，丹凤欲衔词。
杨柳开帆岸，今朝泪已垂。','',''),('quantangshi-39677','送林宽下第东归','黃滔','quantangshi','','卷40','为君惆怅惜离京，年少无人有屈名。
积雪未开移发日，鸣蝉初急说来程。
楚天去路过飞雁，灞岸归尘触锁城。
又得新诗几章别，烟村竹迳海涛声。','',''),('quantangshi-39678','商山赠隐者','黃滔','quantangshi','','卷40','谁不相逢话息机，九重城里自依依。
蓬莱水浅有人说，商洛山高无客归。
数只珍禽寒月在，千株古木热时稀。
西窓昨夜鸣蛩尽，知梦芝翁起扣扉。','',''),('quantangshi-39679','送二友游湘中','黃滔','quantangshi','','卷40','千里楚江新雨晴，同征肯恨迹如萍。
孤舟泊处联诗句，八月中旬宿洞庭。
为客早悲烟草绿，移家晚失岳峯青。
今来无计相从去，归日汀洲乞画屏。','',''),('quantangshi-39680','塞下','黃滔','quantangshi','','卷40','匹马萧萧去不前，平芜千里见穷边。
关山色死秋深日，鼓角声沈霜重天。
荒骨或衔残铁露，惊风时掠暮沙旋。
陇头冤气无归处，化作阴云飞杳然。','',''),('quantangshi-39681','下第东归留辞刑部郑郎中諴','黃滔','quantangshi','','卷40','去违知己住违亲，欲发羸蹄进退频。
万里家山归养志，数年门馆受恩身。
莺声历历秦城晓，柳色依依灞水春。
明日蓝田关外路，连天风雨一行人。','',''),('quantangshi-39682','寄怀南北故人','黃滔','quantangshi','','卷40','秋风昨夜落芙蕖，一片离心到外区。
南海浪高书堕水，北州城破客降胡。
玉窗挑凤佳人老，绮陌啼莺碧树枯。
岭上青风陇头月，时通魂梦出来无。','',''),('quantangshi-39683','关中言怀','黃滔','quantangshi','','卷40','事事朝朝委一尊，自知无复解趋奔。
试期交后犹为客，公道开时敢说冤。
穷巷住来经积雨，故山归去见荒村。
举头尽到断肠处，何必秋风江上猿。','',''),('quantangshi-39684','闺怨','黃滔','quantangshi','','卷40','寸心杳与马蹄随，如蜕形容在锦帷。
江上月明船发后，花间日暮信回时。
五陵夜作酬恩计，四塞秋为破虏期。
待到乘轺入门处，泪珠流尽玉颜衰。','',''),('quantangshi-39685','旅怀','黃滔','quantangshi','','卷40','未吃金丹看十洲，乃将身世作仇雠。
羁游数地值兵乱，宿在孤城闻雨秋。
东越云山却思隐，西秦霜霰苦频留。
他人折尽月中桂，惆怅当年江上鸥。','',''),('quantangshi-39686','别友人','黃滔','quantangshi','','卷40','已喜相逢又怨嗟，十年飘泊在京华。
大朝多事还停举，故国经荒未有家。
鸟带夕阳投远树，人冲腊雪往边沙。
梦魂空系潇湘岸，烟水茫茫芦苇花。','',''),('quantangshi-39687','寄罗浮山道者二首 一','黃滔','quantangshi','','卷40','天际双山压海濆，天漫绝顶海漫根。
时闻雷雨惊樵客，长有龙蛇护洞门。
泉石暮含朱槿书，烟霞冬闭木绵温。
林间学道如容我，今便辞他宠辱喧。','',''),('quantangshi-39688','寄罗浮山道者二首 二','黃滔','quantangshi','','卷40','有人曾见洞中仙，才到人间便越年。
金鼎药成龙入海，玉函书发鹤归天。
楼开石脉千寻直，山拆鳌鳞一半膻。
谁到月明朝礼处，翠岩深锁荔枝烟。','',''),('quantangshi-39689','喜侯舍人蜀中新命三首 一','黃滔','quantangshi','','卷40','八都词客漫喧然，谁解飞扬诰誓间。
五色彩毫裁凤诏，九重天子豁龙颜。
巴山月在趋朝去，锦水烟生入合还。
谋及中兴多少事，莫愁明月不收关。','',''),('quantangshi-39690','喜侯舍人蜀中新命三首 二','黃滔','quantangshi','','卷40','却搜文学起吾唐，暂失都城亦未妨。
锦里幸为丹凤阙，幕宾徴出紫微郎。
来时走马随中使，到日援毫定外方。
若以掌言看谏猎，相如从此病辉光。','',''),('quantangshi-39691','喜侯舍人蜀中新命三首 三','黃滔','quantangshi','','卷40','贾谊才承宣室召，左思唯预秘书流。
赋家达者无过此，翰苑今朝是独游。
立被御炉烟气逼，吟经栈阁雨声秋。
内人未识江淹笔，竟问当时不早求。','',''),('quantangshi-39692','经安州感故郑郎中二首 一','黃滔','quantangshi','','卷40','云梦江头见故城，人间四十载垂名。
马蹄践处东风急，鸡舌销时北阙惊。
岳客出来寻古剑，野猨相聚呌孤茔。
腾身飞上凤凰阁，惆怅终乖吾党情。','',''),('quantangshi-39693','经安州感故郑郎中二首 二','黃滔','quantangshi','','卷40','锦帐先生作牧州，干戈缺后见荒丘。
兼无姓贾儿童在，空有还珠烟水流。
江句行人吟刻石，月肠是处象登楼。
旅魂频此归来否，千载云山属一游。','',''),('quantangshi-39694','出京别崔学士','黃滔','quantangshi','','卷40','一从门馆遍投文，旋忝恩知骤出羣。
不道鹤鸡殊羽翼，许依龙虎借风云。
命奇未便乘东律，言重终期雪北军。
欲逐飘蓬向岐路，数宵垂泪恋清芬。','',''),('quantangshi-39695','雁','黃滔','quantangshi','','卷40','楚岸花晴塞柳衰，年年南北去来期。
江城日暮见飞处，旅馆月明闻过时。
万里风霜休更恨，满川烟草且须疑。
洞庭云水潇湘雨，好把寒更一一知。','',''),('quantangshi-39696','寄越从事林嵩侍御','黃滔','quantangshi','','卷40','子虚词赋动君王，谁不期君入对敭。
莫恋兔园留看雪，已乘骢马合凌霜。
路归天上行方别，道在人间久便香。
应念都城旧吟客，十年踪迹委沧浪。','',''),('quantangshi-39697','长安书事','黃滔','quantangshi','','卷40','一年年课数千言，口祝心祠挈出门。
孤进难时谁肯荐，主司通处不须论。
频秋入自边城雪，昨日听来岭树猨。
若有水田过十亩，早应归去狄江村。','',''),('quantangshi-39698','旅怀寄友人','黃滔','quantangshi','','卷40','重叠愁肠只自知，苦于吞蘖乱于丝。
一船风雨分襟处，千里烟波回首时。
故国田园经战后，穷荒日月逼秋期。
鸣蝉似会悠扬意，陌上声声怨柳衰。','',''),('quantangshi-39699','寄蒋先辈','黃滔','quantangshi','','卷40','夫差宫苑悉苍苔，携客朝游夜未回。
冢上题诗苏小见，江头酹酒伍员来。
秋风急处烟花落，明月中时水寺开。
千载三吴有高迹，虎丘山翠益崔嵬。','',''),('quantangshi-39700','旅怀','黃滔','quantangshi','','卷40','雪貌潜凋雪发生，故园魂断弟兼兄。
十年除夜在孤馆，万里一身求大名。
空有新诗高华岳，已无丹恳出秦城。
侯门莫问曾游处，槐柳影中肝胆倾。','',''),('quantangshi-39701','放榜日','黃滔','quantangshi','','卷40','吾唐取士最堪夸，仙榜标名出曙霞。
白马嘶风三十辔，朱门秉烛一千家。
郄诜联臂升天路，宣圣飞章奏日华。
岁岁人人来不得，曲江烟水杏园花。','',''),('quantangshi-39702','二月二日宴中贻同年封先辈渭','黃滔','quantangshi','','卷40','帝尧城里日衔杯，每倚嵇康到玉颓。
桂苑五更听榜后，蓬山二月看花开。
垂名入甲成龙去，列姓如丁作鹤来。
同戴大恩何处报，永言交道契陈雷。','',''),('quantangshi-39703','新野道中','黃滔','quantangshi','','卷40','野堂如雪草如茵，光武城边一水滨。
越客归遥春有雨，杜鹃啼苦夜无人。
东堂岁去衔杯嬾，南浦期来落泪频。
莫道还家不惆怅，苏秦羁旅长卿贫。','',''),('quantangshi-39704','酬俞钧','黃滔','quantangshi','','卷40','乡书一忝荐延恩，二纪三朝泣省门。
虽忝立名经圣鉴，敢期兴咏叠嘉言。
莫论蟾月无梯接，大底龙津有浪翻。
今日朝廷推草泽，伫君承诏出云根。','',''),('quantangshi-39705','寄同年崔学士','黃滔','quantangshi','','卷40','半因同醉杏花园，尘忝鸿炉与铸颜。
已脱素衣酬素发，敢持青桂爱青山。
虽知珠树悬天上，终赖银河接世间。
毕使海涯能拔宅，三秦二十四畿寰。','',''),('quantangshi-39706','御试二首 一','黃滔','quantangshi','','卷40','已表隋珠各自携，更从琼殿立丹梯。
九华灯作三条烛，万乘君悬四首题。
灵凤敢期翻雪羽，洞箫应或讽金闺。
明朝莫惜场场醉，青桂新香有紫泥。','',''),('quantangshi-39707','御试二首 二','黃滔','quantangshi','','卷40','六曹三省列簪裾，丹诏宣来试士初。
不是玉皇疑羽客，要教金榜带天书。
词臣假寐题黄绢，宫女敲铜奏子虚。
御目四篇酬九百，敢从灯下畧踌躇。','',''),('quantangshi-39708','寄陈侍御','黃滔','quantangshi','','卷40','千年二相未全夸，犹阙闽城贺降麻。
何必锦衣须太守，别无莲幕胜王家。
醴泉涌处休论水，黄菊开时独是花。
九级燕金满尊酒，却愁随诏谒承华。','',''),('quantangshi-39709','酬徐正字夤','黃滔','quantangshi','','卷40','已免蹉跎负岁华，敢辞霜鬓雪呈花。
名从两榜考升第，官自三台追起家。
疋马有期归辇毂，故山无计恋桑麻。
莫言蓬阁从容久，披处终知金在砂。','',''),('quantangshi-39710','辞相府','黃滔','quantangshi','','卷40','从汉至唐分五州，谁为将相作诸侯。
闽江似镜正堪恋，秦客如蓬难久留。
匹马忍辞藩屏去，小才宁副庙堂求。
今朝拜别幡幢下，双泪如珠滴不休。','',''),('quantangshi-39711','寄罗郎中隐','黃滔','quantangshi','','卷40','休向中兴雪至冤，钱塘江上看涛翻。
三征不起时贤议，九转终成道者言。
绿酒千杯肠已烂，新诗数首骨犹存。
瑶蟾若使知人事，仙桂应遭蠹却根。','',''),('quantangshi-39712','江行遇王侍御','黃滔','quantangshi','','卷40','数年分散秦吴隔，暂泊官船浦柳中。
新草军书名更重，久辞山迳业应空。
渡头潮落将行客，天际风高未宿鸿。
此日相逢魂合断，赖君身事渐飞冲。','',''),('quantangshi-39713','客舍秋晚夜怀故山','黃滔','quantangshi','','卷40','寥寥深巷客中居，况值穷秋百事疎。
孤枕忆山千里外，破窗闻雨五更初。
经年荒草侵幽迳，几树西风锁弊庐。
长系寸心归未得，起挑残烛独踌躇。','',''),('quantangshi-39714','绛州郑尚书','黃滔','quantangshi','','卷40','旌旗日日展东风，云稼连山雪刃空。
剖竹已知垂凤食，摘珠何必到龙宫。
谏垣虚位期飞步，翰苑含毫待纪公。
谁谓唐城诸父老，今时得见蜀文翁。','',''),('quantangshi-39715','喜陈先辈及第','黃滔','quantangshi','','卷40','今年春已到京华，天与吾曹雪怨嗟。
甲乙中时公道复，朝廷看处主司夸。
飞离海浪从烧尾，咽却金丹定易牙。
不是驾前偏落羽，锦城争得杏园花。','',''),('quantangshi-39716','延福里居和林宽何绍余醻寄','黃滔','quantangshi','','卷40','长说愁吟逆旅中，一庭深雪一窗风。
眼前道路无心觅，象外烟霞有句通。
几度相留侵鼓散，频闻会宿着僧同。
高情未以干时废，属和因知兴不穷。','',''),('quantangshi-39717','赠宿松杨明府','黃滔','quantangshi','','卷40','溪上家家礼乐新，始知为政异常伦。
若非似水清无底，争得如冰凛拂人。
月狖声和琴调咽，烟村景接柳条春。
宦游兼得逍遥趣，休忆三吴旧钓津。','',''),('quantangshi-39718','送僧','黃滔','quantangshi','','卷40','才年七岁便从师，犹说辞家学佛迟。
新斸松萝还不住，爱寻云水拟何之。
孤溪雪满维舟夜，叠嶂猿啼过寺时。
鸟道泷湫悉行后，岂将翻译负心期。','',''),('quantangshi-39719','赠郑明府','黃滔','quantangshi','','卷40','庭罗衙吏眼看山，真恐风流是谪仙。
垂柳五株春娅姹，鸣琴一弄水潺湲。
援毫断狱登殊考，驻乐题诗得出联。
莫起陶潜折腰叹，才高位下始称贤。','',''),('quantangshi-39720','江州夜宴献陈员外','黃滔','quantangshi','','卷40','多少欢娱簇眼前，浔阳江上夜开筵。
数枝红蜡啼香泪，两面青娥拆瑞莲。
清管彻时斟玉醑，碧筹回处掷金船。
因知往岁楼中月，占得风流是偶然。','',''),('quantangshi-39721','湘中赠张逸人','黃滔','quantangshi','','卷40','羽衣零落帽欹斜，不自孤峰即海沙。
曾为蜀山成寓迹，又因湘水拟营家。
鸣琴坐见燕鸿没，曳履吟忘野迳赊。
更爱扁舟宿寒夜，独听风雨过芦花。','',''),('quantangshi-39722','寓题','黃滔','quantangshi','','卷40','纷纷墨勅除官日，处处红旗打贼时。
竿底得璜犹未用，梦中吞鸟拟何为。
损生莫若攀丹桂，免俗无过咏紫芝。
两岸芦花一江水，依前且把钓鱼丝。','',''),('quantangshi-39723','题陈山人居','黃滔','quantangshi','','卷40','犹自莓苔马迹重，石嵌泉冷嬾移峰。
空垂凤食檐前竹，漫拔龙形涧底松。
隔岸青山秋见寺，半牀明月夜闻钟。
谁能惆怅磻溪事，今古悠悠不再逢。','',''),('quantangshi-39724','宿李少府园林','黃滔','quantangshi','','卷40','一壶浊酒百家诗，住此园林守选期。
深院月凉留客夜，古杉风细似泉时。
尝频异茗尘心净，议罢名山竹影移。
明日绿苔浑扫后，石庭吟坐复容谁。','',''),('quantangshi-39725','送人明经及第东归','黃滔','quantangshi','','卷40','十问九通离义牀，今时登第信非常。
亦从南院看新榜，旋束春关归故乡。
水到吴门方见海，树侵闽岭渐无霜。
知君已塞平生愿，日与交亲醉几场。','',''),('quantangshi-39726','断酒','黃滔','quantangshi','','卷40','未老先为百病仍，醉杯无计接宾朋。
免遭拽盏郎君谑，还被簪花录事憎。
丝管合时思索马，池塘晴后独留僧。
何因浇得离肠烂，南浦东门恨不胜。','',''),('quantangshi-39727','南海幕和段先辈送韦侍御赴阙','黃滔','quantangshi','','卷40','树色川光入暮秋，使车西发不胜愁。
璧连标格惊分散，雪课篇章互唱酬。
魏阙别当飞羽翼，燕台独且占风流。
满园歌管凉宵月，此后相思几上楼。','',''),('quantangshi-39728','寄南海黄尚书','黃滔','quantangshi','','卷40','五羊城下驻行车，此事如今八载余。
燕颔已知飞食肉，龙门犹自退为鱼。
红楼入夜笙歌合，白社惊秋草木疎。
西望清光寄消息，万重烟水一封书。','',''),('quantangshi-39729','送人往苏州觐其兄','黃滔','quantangshi','','卷40','阖闾城外越江头，两地烟涛一叶舟。
到日荆枝应便茂，别时珠泪不须流。
迎欢酒醒山当枕，咏古诗成月在楼。
明日尊前若相问，为言今访赤松游。','',''),('quantangshi-39730','游东林寺','黃滔','quantangshi','','卷40','长生犹自重无生，言让仙祠佛寺成。
碑折谁忘康乐制，山灵表得远公名。
松形入汉藤萝短，僧语离经耳目清。
莫怪迟迟不归去，童年已梦遶林行。','',''),('quantangshi-39731','赠旌德吕明府','黃滔','quantangshi','','卷40','渥洼步数太阿姿，争遣王侯不奉知。
花作城池入官处，锦随刀尺少年时。
两衙断狱兼留客，三考论功合树碑。
须信隔帘看刺史，锦章朱绂已葳蕤。','',''),('quantangshi-39732','贺清源仆射新命','黃滔','quantangshi','','卷40','虽言嵩岳秀崔嵬，少降连枝命世才。
南史两荣唯百揆，东闽双拜有三台。
二天在顶家家咏，丹凤衔书岁岁来。
虚说古贤龙虎盛，谁攀荆树上金台。','',''),('quantangshi-39733','浙幕李端公泛建溪','黃滔','quantangshi','','卷40','越城吴国结良姻，交发芙蓉幕内宾。
自顾幽沈槐省迹，得陪清显谏垣臣。
分题晓并兰舟远，对坐宵听月狖频。
更爱延平津上过，一双神剑是龙鳞。','',''),('quantangshi-39734','贻宋评事','黃滔','quantangshi','','卷40','河阳城里谢城中，入曳长裾出佩铜。
燕国金台无别客，陶家柳下有清风。
数踪篆隶书新得，一竈屯蒙火细红。
时说三吴欲归处，绿波洲渚紫蒲藂。','',''),('quantangshi-39735','催妆','黃滔','quantangshi','','卷40','北府迎尘南郡来，莫将芳意更迟回。
虽言天上光阴别，且被人间更漏催。
烟树逈垂连蔕杏，彩童交捧合欢杯。
吹箫不是神仙曲，争引秦娥下凤台。','',''),('quantangshi-39736','寓题','黃滔','quantangshi','','卷40','每忆家山即涕零，定须归老旧云扃。
银河水到人间浊，丹桂枝垂月里馨。
霜雪不飞无翠竹，鲸鲵犹在有青萍。
三千九万平生事，却恨南华说北溟。','',''),('quantangshi-39737','伤蒋校书德山','黃滔','quantangshi','','卷40','谁到双溪溪岸傍，与招魂魄上苍苍。
世间无树胜青桂，陇上有花唯白杨。
秦苑火然新赋在，越城山秀故居荒。
如何万古雕龙手，独是相如识汉皇。','',''),('quantangshi-39738','寄杨赞图学士','黃滔','quantangshi','','卷40','东堂第一领春风，时怪关西小骥慵。
华表柱头还有鹤，华歆名下别无龙。
君恩凤阁含毫数，诗景珠宫列肆供。
今日江南驻舟处，莫言归计为云峰。','',''),('quantangshi-39739','酬杨学士','黃滔','quantangshi','','卷40','神仙簿上愧非夫，诏作疑丹两入炉。
诗里几曾吟芍药，花中方得见菖蒲。
阳春唱后应无曲，明月圆来别是珠。
莫下蓬山不回首，东风犹待重抟扶。','',''),('quantangshi-39740','寄同年李侍郎龟正','黃滔','quantangshi','','卷40','石门南面泪浪浪，自此东西失帝乡。
昆璞要疑方卓绝，大鹏须息始开张。
已归天上趋双阙，忽喜人间捧八行。
莫道秋霜不滋物，菊花还借后时黄。','',''),('quantangshi-39741','钟陵故人','黃滔','quantangshi','','卷40','滕王阁下昔相逢，此地今难访所从。
唯爱金笼贮鹦鹉，谁论铁柱锁蛟龙。
荆榛翠是钱神染，河岳期须国士钟。
一筯鲈鱼千古美，后人终少继前踪。','',''),('quantangshi-39742','故山','黃滔','quantangshi','','卷40','支颐默省旧林泉，石径茅堂到目前。
衰碧鸣蛩莎有露，浓阴歇鹿竹无烟。
水从井底通沧海，山在窗中倚远天。
何事苍髯不归去，燕昭台上一年年。','',''),('quantangshi-39743','塞上','黃滔','quantangshi','','卷40','塞门关外日光微，角怨单于雁驻飞。
冲水路从冰解断，逾城人到月明归。
燕山腊雪销金甲，秦苑秋风脆锦衣。
欲吊昭君倍惆怅，汉家甥舅竟相违。','',''),('quantangshi-39744','乌石村','黃滔','quantangshi','','卷40','往日江村今物华，一回登览一悲嗟。
故人殁后城头月，新鸟啼来壠上花。
卖剑钱销知绝俗，闻蝉诗苦即思家。
谢公古郡青山在，三尺孤坟扑海沙。','',''),('quantangshi-39745','寄同年卢员外','黃滔','quantangshi','','卷40','听尽鸎声出雍州，秦吴烟月十经秋。
龙门在地从人上，郎省连天须鹤游。
休恋一台惟妙绝，已经三字入精求。
当年甲乙皆华显，应念槐宫今雪头。','',''),('quantangshi-39746','寄同年封舍人渭','黃滔','quantangshi','','卷40','唐城接轸赴秦川，忧合懽离骤十年。
龙颔摘珠同泳海，凤衔辉翰别升天。
八行真迹虽收拾，四户高扃奈隔悬。
能使丘门终始雪，莫教华发独潸然。','',''),('quantangshi-39747','遇罗员外衮','黃滔','quantangshi','','卷40','灞陵桥外驻征辕，此一分飞十六年。
豸角戴时垂素发，鸡香含处隔青天。
绮园难贮林栖意，班马须持笔削权。
可忘自初相识地，秋风明月客鄜延。','',''),('quantangshi-39748','送翁员外承赞','黃滔','quantangshi','','卷40','谁言吾党命多奇，荣美如君历数稀。
衣锦还乡翻是客，回车谒帝却为归。
凤旋北阙虚丹穴，星复南宫逼紫微。
已分十旬无急诏，天涯相送只沾衣。','',''),('quantangshi-39749','奉和翁文尧十九员外中谢日蒙恩赐金紫之什','黃滔','quantangshi','','卷40','面蒙君赐自龙墀，谁是还乡一袭衣。
三品易悬鳞鬣赫，八丝展起彩章飞。
敻为胜事垂千古，题作新诗启七微。
严助买臣精魄在，定应羞着昔年归。','',''),('quantangshi-39750','翁文尧员外捧金紫还乡之命雅发篇章将原交情远为嘉贶洎燕鸿陆犬楚水荆山又吐琼瑶逮之幽鄙虽涌泉思触逸兴皆虚而强韵押难非才颇愧輙兹酬和以质奖私','黃滔','quantangshi','','卷40','抟将盛事更无余，还向桥边看旧书。
东越独推生竹箭，北溟喜足贮鲲鱼。
两回谁解归华表，午夜兼能荐子虚。
须把头冠弹尽日，怜君不与故人疎。','',''),('quantangshi-39751','奉和翁文尧员外经过七林书堂见寄之什','黃滔','quantangshi','','卷40','朱旗引入昔茆堂，半日从容尽日忙。
驷马宝车行锡礼，金章紫绶带天香。
山从南国添烟翠，龙起东溟认夜光。
定恐故园留不住，竹风松韵漫凄锵。','',''),('quantangshi-39752','奉酬翁文尧员外驻南台见寄之什','黃滔','quantangshi','','卷40','人指南台山与川，大惊喜气异当年。
花迎金册非时拆，月对琼杯此夜圆。
我爱藏冰从夏结，君怜修竹到冬鲜。
殷勤更抱鸣琴抚，为忆秦儿识断弦。','',''),('quantangshi-39753','翁文尧员外拥册礼之归一路有诗名昼锦集先将寄示因书五十六字','黃滔','quantangshi','','卷40','六窠只佩诸侯印，争比从天拥册归。
一轴郢人歌处雪，两重朱氏着来衣。
闽山秀已钟君尽，洛水波应溅我稀。
明日陪尘迎驷马，定淮斋沐看光辉。','',''),('quantangshi-39754','奉和翁文尧员外文秀光贤昼锦之什 一','黃滔','quantangshi','','卷40','乡名里号一朝新，乃觉台恩重万钧。
建水闽山无故事，长卿严助是前身。
清泉引入旁添润，嘉树移来别带春。
莫凭栏干剩留驻，内庭虚位待才臣。','',''),('quantangshi-39755','奉和翁文尧员外文秀光贤昼锦之什 二','黃滔','quantangshi','','卷40','虽言闽越系生贤，谁是还家宠自天。
山简愧兼诸郡命，郑玄慙秉六经权。
鸟行去没孤烟树，渔唱还从碧岛川。
休说迟回未能去，夜来新梦禁中泉。','',''),('quantangshi-39756','奉和翁文尧员外文秀光贤昼锦之什 三','黃滔','quantangshi','','卷40','君王面赐紫还乡，金紫中推是甲裳。
华构便将垂美号，故山重更发清光。
水澄此日兰宫镜，树忆当年栢署霜。
珍重朱栏兼翠拱，来来皆自读书堂。','',''),('quantangshi-39757','奉酬翁文尧员外神泉之游见寄嘉什','黃滔','quantangshi','','卷40','含鸡假豸喜同游，野外嘶风并紫骝。
松竹回寻青障寺，姓名题向白云楼。
泉源出石清消暑，僧语离经妙破愁。
争奈爱山尤恋阙，古来能有几人休。','',''),('quantangshi-39758','輙吟七言四韵攀寄翁文尧拾遗','黃滔','quantangshi','','卷40','唐设高科表用文，吾曹谁作谏垣臣。
甄山秀气旷千古，凤阙华恩钟二人。
起草便论天上事，如君不是世间身。
龙头龙尾前年梦，今日须怜应若神。','',''),('quantangshi-39759','塞上','黃滔','quantangshi','','卷40','掘地破重城，烧山搜伏兵。
金徽互呜咽，玉笛自凄清。
使发西都耸，尘空北岳横。
长河涉有路，旷野宿无程。
沙雨黄莺啭，辕门青草生。
马归秦苑牧，人在虏云耕。
落日牛羊聚，秋风鼓角鸣。
如何汉天子，青冢杳含情。','',''),('quantangshi-39760','寄献梓幢山侯侍御','黃滔','quantangshi','','卷40','汉宫行庙略，簪笏落民间。
直道三湘水，高情四皓山。
赐衣僧脱去，奏表主批还。
地得松萝坞，泉通雨雪湾。
东门添故事，南省缺新班。
片石秋从露，幽窗夜不关。
梦余蟾隐映，吟次鸟绵蛮。
可惜相如作，当时事悉闲。','',''),('quantangshi-39761','壬癸岁书情','黃滔','quantangshi','','卷40','故园招隐客，应便笑无成。
谒帝逢移国，投文值用兵。
孤松怜鹤在，疎柳恶蝉鸣。
匹马迷归处，青云失曩情。
江头寒夜宿，壠上歉年耕。
冠盖新人物，渔樵旧弟兄。
易生唯白发，难立是浮名。
惆怅灞桥路，秋风谁入行。','',''),('quantangshi-39762','河南府试秋夕闻新雁','黃滔','quantangshi','','卷40','湘南飞去日，蓟北乍惊秋。
呌出陇云夜，闻为客子愁。
一声初触梦，半白已侵头。
旅馆移欹枕，江城起倚楼。
余灯依古壁，片月下沧洲。
寂听良宵彻，踌躇感岁流。','',''),('quantangshi-39763','省试奉诏涨曲江池','黃滔','quantangshi','','卷40','地脉寒来浅，恩波住后新。
引将诸派水，别贮大都春。
幽咽疏通处，清泠迸入辰。
渐平连杏岸，旋阔映楼津。
沙没迷行径，洲宽恣跃鳞。
愿当舟檝便，一附济川人。','',''),('quantangshi-39764','题宣一僧正院','黃滔','quantangshi','','卷40','五级凌虚塔，三生落发师。
都僧须有托，孤峤遂无期。
井邑焚香待，君侯减俸资。
山衣随叠破，莱骨逐年羸。
茶取寒泉试，松于远涧移。
吾曹来顶手，不合不题诗。','',''),('quantangshi-39765','和吴学士对春雪献韦令公次韵','黃滔','quantangshi','','卷40','春雪下盈空，翻疑腊未穷。
连天宁认月，堕地屡兼风。
忽误边沙上，应平火岭中。
林间妨走兽，云际落飞鸿。
梁苑还吟客，齐都省创宫。
掩扉皆墐北，移律愧居东。
书幌飘全湿，茶铛入旋融。
奔川半留滞，叠树互玲珑。
出户行瑶砌，开园见粉丛。
高才兴咏处，真宰答殊功。','',''),('quantangshi-39766','省试一一吹竽','黃滔','quantangshi','','卷40','齐竽今历试，真伪不难知。
欲使声声别，须令个个吹。
后先无错杂，能否立参差。
次第教单进，宫商乃异宜。
凡音皆窜迹，至艺始呈奇。
以此论文学，终凭一一窥。','',''),('quantangshi-39767','明月照高楼','黃滔','quantangshi','','卷40','月满长空朗，楼侵碧落横。
波文流藻井，桂魄拂雕楹。
深鉴罗纨薄，寒搜户牖清。
冰铺梁燕噤，霜覆瓦松倾。
卓午收全影，斜悬转半明。
佳人当此夕，多少别离情。','',''),('quantangshi-39768','广州试越台怀古','黃滔','quantangshi','','卷40','南越千年事，兴怀一旦来。
歌钟非旧俗，烟月有层台。
北望人何在，东流水不回。
吹窗风杂瘴，沾槛雨经梅。
壮气曾难揖，空名信可哀。
不堪登览处，花落与花开。','',''),('quantangshi-39769','襄州试白云归帝乡','黃滔','quantangshi','','卷40','杳杳复霏霏，应缘有所依。
不言天路远，终望帝乡归。
高岳和霜过，遥关带月飞。
渐怜双阙近，宁恨众山违。
阵触银河乱，光连粉署微。
旅人随计日，自笑比麻衣。','',''),('quantangshi-39770','省试内出白鹿宣示百官','黃滔','quantangshi','','卷40','上瑞何曾乏，毛羣表色难。
推于五灵少，宣示百寮观。
形夺场驹洁，光交月兔寒。
已驯瑶草别，孤立雪花团。
戴豸慙端士，抽毫跃史官。
贵臣歌咏日，皆作白麟看。','',''),('quantangshi-39771','出关言怀','黃滔','quantangshi','','卷40','又乞书题出，关西谒列侯。
寄家僧许岳，钓浦雨移洲。
卖马登长陆，沾衣逐胜游。
菜肠终日馁，霜鬓度年秋。
诗苦无人爱，言公是世仇。
却怜庭际草，中有号忘忧。','',''),('quantangshi-39772','壶公山','黃滔','quantangshi','','卷40','八面峰峦秀，孤高可偶然。
数人游顶上，沧海见东边。
不信无灵洞，相传有古仙。
橘如珠夏在，池象月垂穿。
仿髴尝闻乐，岧嶤半插天。
山寒彻三伏，松偃出千年。
樵牧时迷所，仓箱岁叠川。
严祠风雨管，怪木薜萝缠。
青草方中药，苍苔石里钱。
琼津流乳窦，春色驻芝田。
乌兔中时近，龙蛇蛰处膻。
嘉名光列土，秀气产羣贤。
瀑锁瑶台路，溪升钓浦船。
鳌头擎恐没，地轴压应旋。
蠲疾寒甘露，藏珍起瑞烟。
画工飞梦寐，诗客寄林泉。
掘地多云母，缘霜欠木绵。
井通䲡吐脉，僧隔虎栖禅。
危磴千寻拔，奇花四季鲜。
鹤归悬圃少，凤下碧梧偏。
桃易炎凉熟，茶推醉醒煎。
邨家蒙枣栗，俗骨爽猨蝉。
谷语升乔鸟，陂开共蔕莲。
落枫丹叶舞，新蕨紫芽拳。
翠竹雕羌笛，悬藤煮蜀牋。
白云长掩映，流水别潺湲。
作赋前儒阙，冲虚南国先。
省郎求牧看，野老葺斋眠。
寺立兴衰创，碑须一二镌。
清吟思却隐，簪绂奈萦牵。','',''),('quantangshi-39773','和王舍人崔补阙题天王寺','黃滔','quantangshi','','卷40','郭内青山寺，难论此崛奇。
白云生院落，流水下城池。
石像雷霆启，江沙鼎鼐期。
岳僧来坐夏，秦客会题诗。
冈转泉根滑，门升藓级危。
紫微今日句，黄绢昔年碑。
歇鹤松低阁，鸣蛩径出篱。
粉垣千堵束，金塔九层支。
啼鸟笙簧韵，开花锦绣姿。
清斋奔井邑，玄发剃熊罴。
极浦征帆小，平芜落日迟。
风篁清却暑，烟草绿无时。
信士三公作，灵踪四绝推。
良游如不宿，明月拟何之。','',''),('quantangshi-39774','投翰长赵侍郎','黃滔','quantangshi','','卷40','禹门西面逐飘蓬，忽喜仙都得入踪。
贾氏许频趋季虎，荀家因敢谒头龙。
手扶日月重轮起，数是干坤正气钟。
五色笔驱神出没，八花塼接帝从容。
诗酬御制风骚古，论似人情鼎鼐浓。
岂有地能先凤掖，别无山更胜鳌峰。
攀鸿日浅魂飞越，为鲤年深势噞喁。
泽国雨荒三径草，秦关雪折一枝筇。
吹成暖景犹葭律，引上纤萝在岳松。
愿向明朝荐幽滞，免教号泣触登庸。','',''),('quantangshi-39775','鄜畤李相公','黃滔','quantangshi','','卷40','秦城择日发征辕，斋戒来投节制尊。
分虎名高初命相，攀龙迹下愧登门。
夜听讴咏销尘梦，晓拜旌幢战旅魂。
华舍未开宁有碍，彩毫虽乏敢无言。
生兼文武为人杰，出应干坤静帝阍。
计吐六奇谁敢敌，学穷三略不须论。
功高马卸黄金甲，台逈宾懽白玉樽。
九穗嘉禾垂绮陌，四时甘雨带雕轩。
推恩每觉东溟浅，吹律能令北陆暄。
青草连沙无血溅，黄榆鏁塞有莺翻。
笙歌合沓春风郭，鸡犬连延碧岫邨。
游子不缘贪献赋，永依棠树托蓬根。','',''),('quantangshi-39776','成名后呈同年','黃滔','quantangshi','','卷40','业诗攻赋荐乡书，二纪如鸿历九衢。
待得至公搜草泽，如从平陆到蓬壶。
虽慙锦鲤成穿额，忝获骊龙不寐珠。
蒙楚数疑休下泣，师刘大喝已为卢。
人间灰管供红杏，天上烟花应白榆。
一字连镳巡甲族，千般唱罚赏皇都。
名推颜柳题金塔，饮自燕秦索玉姝。
退愧单寒终预此，敢将恩岳怠斯须。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-39777','投刑部裴郎中','黃滔','quantangshi','','卷40','两牓驱牵别海涔，佗门不合觅知音。
瞻恩虽隔云雷赐，向主终知犬马心。
礼闱后人窥作镜，庙堂前席待为霖。
已齐日月悬千古，肯误风尘使陆沉。
拜首敢将诚吐血，蜕形唯待诺如金。
愁闻南院看期到，恐被东墙旧恨侵。
缁化衣空难抵雪，黑销头尽不胜簪。
数行泪里依投志，直比沧溟未是深。','',''),('quantangshi-39778','辇下寓题','黃滔','quantangshi','','卷40','对酒何曾醉，寻僧未觉闲。
无人不惆怅，终日见南山。','',''),('quantangshi-39779','寄题崔校书郊舍','黃滔','quantangshi','','卷40','一片寒塘水，寻常立鹭鸶。
主人贫爱客，沽酒往吟诗。','',''),('quantangshi-39780','秋思','黃滔','quantangshi','','卷40','碧嶂猿啼夜，新秋雨霁天。
谁人爱明月，露坐洞庭船。','',''),('quantangshi-39781','芳草','黃滔','quantangshi','','卷40','泽国多芳草，年年长自春。
应从屈平后，更苦不归人。','',''),('quantangshi-39782','辇下书事','黃滔','quantangshi','','卷40','北阙新王业，东城入羽书。
秋风满林起，谁道有鲈鱼。','',''),('quantangshi-39783','入关言怀','黃滔','quantangshi','','卷40','背将踪迹向京师，出在先春入后时。
落日灞桥飞雪里，已闻南院有看期。','',''),('quantangshi-39784','过长江','黃滔','quantangshi','','卷40','曾搜景象恐通神，地下还应有主人。
若把长江比湘浦，离骚不合自灵均。','',''),('quantangshi-39785','题灵峰僧院','黃滔','quantangshi','','卷40','系马松间不忍归，数巡香茗一枰棋。
拟登绝顶留人宿，犹待沧溟月满时。','',''),('quantangshi-39786','司马长卿','黃滔','quantangshi','','卷40','一自梁园失意回，无人知有掞天才。
汉宫不鏁陈皇后，谁肯量金买赋来。','',''),('quantangshi-39787','归思','黃滔','quantangshi','','卷40','蓟北风烟空汉月，湘南云水半蛮边。
寒为旅雁暖还去，秦越离家可十年。','',''),('quantangshi-39788','东林寺贯休上人篆隶题诗','黃滔','quantangshi','','卷40','师名自越彻秦中，秦越难寻师所从。
墨迹两般诗一首，香炉峰下似相逢。','',''),('quantangshi-39789','寓江州李使君','黃滔','quantangshi','','卷40','使君曾被蝉声苦，每见词文即为愁。
况是楚江鸿到后，可堪西望发孤舟。','',''),('quantangshi-39790','游南寓题','黃滔','quantangshi','','卷40','江山节被雪霜遗，毒草过秋未拟衰。
天不当时命邹衍，亦将寒律入南吹。','',''),('quantangshi-39791','和同年赵先辈观文','黃滔','quantangshi','','卷40','玉兔轮中方是树，金鳌顶上别无山。
虽然回首见烟水，事主酬恩难便闲。','',''),('quantangshi-39792','出京别同年','黃滔','quantangshi','','卷40','一枝仙桂已攀援，归去烟涛浦口邨。
虽恨别离还有意，槐花黄日出青门。','',''),('quantangshi-39793','木芙蓉三首 一','黃滔','quantangshi','','卷40','黄鸟啼烟二月朝，若教开即牡丹饶。
天嫌青帝恩光盛，留与秋风雪寂寥。','',''),('quantangshi-39794','木芙蓉三首 二','黃滔','quantangshi','','卷40','却假青腰女剪成，绿罗囊绽彩霞呈。
谁怜不及黄花菊，只遇陶潜便得名。','',''),('quantangshi-39795','木芙蓉三首 三','黃滔','quantangshi','','卷40','须到露寒方有态，为经霜裛稍无香。
移根若在秦宫里，多少佳人泣晓妆。','',''),('quantangshi-39796','九日','黃滔','quantangshi','','卷40','阳数重时阴数残，露浓风硬欲成寒。
莫言黄菊花开晚，独占樽前一日欢。','',''),('quantangshi-39797','夏州道中','黃滔','quantangshi','','卷40','陇雁南飞河水流，秦城千里忍回头。
征行浑与求名背，九月中旬往夏州。','',''),('quantangshi-39798','经慈州感谢郎中','黃滔','quantangshi','','卷40','金声乃是古诗流，况有池塘春草俦。
莫遣宣城独垂号，云山彼此谢公游。','',''),('quantangshi-39799','寓题','黃滔','quantangshi','','卷40','吴中烟水越中山，莫把渔樵谩自宽。
归泛扁舟可容易，五湖高士是抛官。','',''),('quantangshi-39800','寄宋明府','黃滔','quantangshi','','卷40','北阙秋期南国身，重关烟月五溪云。
风蝉已有数声急，赖在陶家柳下闻。','',''),('quantangshi-39801','灵均','黃滔','quantangshi','','卷40','莫问灵均昔日游，江蓠春尽岸枫秋。
至今此事何人雪，月照楚山湘水流。','',''),('quantangshi-39802','马嵬','黃滔','quantangshi','','卷40','锦江晴碧劒锋奇，合有千年降圣时。
天意从来知幸蜀，不关胎祸自蛾眉。','',''),('quantangshi-39803','和陈先辈陪陆舍人春日游曲江','黃滔','quantangshi','','卷40','刘超游召郄诜陪，为忆池亭旧赏来。
红杏花旁见山色，诗成因触鼓声回。','',''),('quantangshi-39804','花','黃滔','quantangshi','','卷40','莫道颜色如渥丹，莫道馨香过𦶜兰。
东风吹绽还吹落，明日谁为今日看。','',''),('quantangshi-39805','卷帘','黃滔','quantangshi','','卷40','绿鬟侍女手纤纤，新捧嫦娥出素蟾。
卫玠官高难久立，莫辞双卷水精帘。','',''),('quantangshi-39806','启帐','黃滔','quantangshi','','卷40','得人憎定绣芙蓉，爱鏁嫦娥出月踪。
侍女莫嫌抬素手，拔开珠翠待相逢。','',''),('quantangshi-39807','去扇','黃滔','quantangshi','','卷40','城上风生蜡炬寒，锦帷开处露翔鸾。
已知秦女升仙态，休把圆轻隔牡丹。','',''),('quantangshi-39808','别后','黃滔','quantangshi','','卷40','梦里相逢无后期，烟中解佩杳何之。
亏蟾便是陈宫镜，莫吐清光照别离。','',''),('quantangshi-39809','严陵钓台','黃滔','quantangshi','','卷40','终向烟霞作野夫，一竿竹不换簪裾。
直钩犹逐熊罴起，独是先生真钓鱼。','',''),('quantangshi-39810','马嵬二首 一','黃滔','quantangshi','','卷40','铁马嘶风一渡河，泪珠零便作惊波。
鸣泉亦感上皇意，流下陇头呜咽多。','',''),('quantangshi-39811','马嵬二首 二','黃滔','quantangshi','','卷40','龙脑移香凤辇留，可能千古永悠悠。
夜台若使香魂在，应作烟花出陇头。','',''),('quantangshi-39812','闰八月','黃滔','quantangshi','','卷40','无人不爱今年闰，月看中秋两度圆。
唯恐雨师风伯意，至时还夺上楼天。','',''),('quantangshi-39813','奉和翁文尧戏寄','黃滔','quantangshi','','卷40','掘兰宫里数名郎，好是乘轺出帝乡。
两度还家还未有，别论光彩向冠裳。','',''),('quantangshi-39814','奉和文尧对庭前千叶石榴','黃滔','quantangshi','','卷40','一朵千英绽晓枝，彩霞堪与别为期。
移根若在芙蓉苑，岂向当年有醒时。','',''),('quantangshi-39815','翁文尧以美疹暂滞令公大王益得异礼观今日宠待之盛輙成一章','黃滔','quantangshi','','卷40','滋赋諴文侯李盛，终求一袭锦衣难。
如何两度还州里，兼借乡人更剩观。','',''),('quantangshi-39816','赠友人','黃滔','quantangshi','','卷40','超达陶子性，留琴不设弦。
觅句朝忘食，倾杯夜废眠。
爱月影为伴，吟风声自连。
听此莺飞谷，心怀迷远川。','',''),('quantangshi-39817','八月十五夜','殷文圭','quantangshi','','卷40','万里无云镜九州，最团圆夜是中秋。
满衣冰彩拂不落，遍地水光凝欲流。
华岳影寒清露掌，海门风急白潮头。
因君照我丹心事，减得愁人一夕愁。','',''),('quantangshi-39818','省试夜投献座主','殷文圭','quantangshi','','卷40','辟开公道选时英，神镜高悬鉴百灵。
混沌分来融间气，欃枪灭处炫文星。
烛然兰省三条白，山束龙门万仞青。
圣教中兴周礼在，不劳干羽舞明庭。','',''),('quantangshi-39819','观贺皇太子册命','殷文圭','quantangshi','','卷40','嗣册储皇帝命行，万方臣妾跃欢声。
鸾旃再立星辰正，雉扇双开日月明。
自有汉元争翊戴，不劳商皓定欹倾。
春宫保傅皆周召，致主何忧不太平。','',''),('quantangshi-39820','行朝早春侍师门宴西溪席上作','殷文圭','quantangshi','','卷40','西溪水色净于苔，画鷁横风绛帐开。
弦管旋飘蓬岛去，公卿皆是蘂宫来。
金鳞掷浪钱翻荇，玉爵黏香雪泛梅。
三榜生徒逾七十，岂期龙坂纳非才。','',''),('quantangshi-39821','贺同年第三人刘先辈咸辟命','殷文圭','quantangshi','','卷40','甲门才子鼎科人，拂地蓝衫榜下新。
脱俗文章笑鹦鹉，凌云头角压麒麟。
金壶藉草溪亭晚，玉勒穿花野寺春。
多愧受恩同阙里，不嫌师僻与颜贫。','',''),('quantangshi-39822','寄广南刘仆射','殷文圭','quantangshi','','卷40','战国从今却尚文，品流才子作将军。
画船清宴蛮溪雨，粉阁闲吟瘴峤云。
暴客卸戈归惠政，史官调笔待儒勋。
汉仪一化南人后，牧马无因更夜闻。','',''),('quantangshi-39823','题吴中陆龟蒙山斋','殷文圭','quantangshi','','卷40','万卷图书千户贵，十洲烟景四时和。
花心露洗猩猩血，水面风披瑟瑟罗。
庄叟静眠清梦永，客儿芳意小诗多。
天麟不触人间网，拟把公卿换得麽。','',''),('quantangshi-39824','经李翰林墓','殷文圭','quantangshi','','卷40','诗中日月酒中仙，平地雄飞上九天。
身谪蓬莱金籍外，宝装方丈玉堂前。
虎靴醉索将军脱，鸿笔悲无令子传。
十字遗碑三尺墓，只应吟客吊秋烟。','',''),('quantangshi-39825','鹦鹉','殷文圭','quantangshi','','卷40','丹觜如簧翠羽轻，随人呼物旋知名。
金笼夜黯山西梦，玉枕晓憎帘外声。
才子爱奇吟不足，美人怜尔绣初成。
应缘是我邯郸客，相顾咬咬别有情。','',''),('quantangshi-39826','边将别','殷文圭','quantangshi','','卷40','地角天涯倍苦辛，十年铅椠未酬身。
朱门泣别同鲛客，紫塞旅游随雁臣。
汉将出师冲晓雪，胡儿奔马扑征尘。
行行独止干戈域，毳帐望谁为主人。','',''),('quantangshi-39827','江南秋日','殷文圭','quantangshi','','卷40','水国由来称道情，野人经此顿神清。
一篷秋雨睡初起，半砚冷云吟未成。
青笠渔儿筒钓没，蒨衣菱女画桡轻。
冰绡写上江南景，寄与金銮马长卿。','',''),('quantangshi-39828','题友人庭竹','殷文圭','quantangshi','','卷40','丛篁萧瑟拂清阴，贵地栽成碧玉林。
尽待花开添凤食，可怜风击状龙吟。
钿竿离立霜文静，锦箨飘零粉节深。
何事子猷偏寄赏，此君心似古人心。','',''),('quantangshi-39829','览陆龟蒙旧集','殷文圭','quantangshi','','卷40','先生文价沸三吴，白雪千编酒一壶。
吟去星辰笔下动，醉来嵩华眼中无。
峭如谢桧虬蟠活，清似缑山凤路孤。
身后独遗封禅草，何人寻得佐鸿图。','',''),('quantangshi-39830','玉仙道中','殷文圭','quantangshi','','卷40','莼鲈方美别吴江，笔阵诗魔两未降。
山势北蟠龙偃蹇，泉声东漱玉琤瑽。
古陂狐兔穿蛮冢，破寺荆榛拥佛幢。
信马冷吟迷路处，隔溪烟雨吠村厖。','',''),('quantangshi-39831','赵侍郎看红白牡丹因寄杨状头赞图','殷文圭','quantangshi','','卷40','迟开都为让羣芳，贵地栽成对玉堂。
红艳褭烟疑欲语，素华映月只闻香。
翦裁偏得东风意，淡薄似矜西子妆。
雅称花中为首冠，年年长占断春光。','',''),('quantangshi-39832','题胡州太学丘光庭博士幽居','殷文圭','quantangshi','','卷40','舜轨尧文混九垓，明堂宏构集良材。
江边云卧如龙稳，天外泥书遣鹤来。
五夜药苗滋沆瀣，四时花影荫莓苔。
草玄门似山中静，不是公卿到不开。','',''),('quantangshi-39833','初秋留别越中幕客','殷文圭','quantangshi','','卷40','魂梦飘零落叶洲，北辕南柁几时休。
月中青桂渐看老，星畔白榆还报秋。
鹤禁有知须强进，稽峰无事莫相留。
吴花越柳饶君醉，直待功成始举头。','',''),('quantangshi-39834','送道者朝见后归山','殷文圭','quantangshi','','卷40','暂随蒲帛谒金銮，萧洒风仪傲汉官。
天马难将朱索绊，海鳌宁觉碧涛宽。
松坛月作尊前伴，竹箧书为教外欢。
神鼎已干龙虎伏，一条真气出云端。','',''),('quantangshi-39835','赠战将','殷文圭','quantangshi','','卷40','绿沈枪利雪峰尖，犀甲军装称紫髯。
威慑万人长凛凛，礼延羣客每谦谦。
阵前战马黄金勒，架上兵书白玉签。
不为已为儒弟子，好依门下学韬钤。','',''),('quantangshi-39836','九华贺雨吟','殷文圭','quantangshi','','卷40','陶公焦思念生灵，变旱为丰合杳冥。
雷劈老松疑虎怒，雨冲阴洞觉龙腥。
万畦香稻蓬葱绿，九朵奇峰扑亚青。
吟贺西成饶旅兴，散丝飞洒满长亭。','',''),('quantangshi-39837','赠池州张太守','殷文圭','quantangshi','','卷40','神珠无纇玉无瑕，七叶簪貂汉相家。
阵面奔星破犀象，笔头飞电跃龙蛇。
绛帏夜坐穷三史，红斾春行到九华。
只怕池人留不住，别迁征镇拥高牙。','',''),('quantangshi-39838','中秋自宛陵寄池阳太守','殷文圭','quantangshi','','卷40','出山三见月如眉，蝶梦终宵遶戟枝。
旅客思归鸿去日，贤侯行化子来时。
郡楼遐想刘琨啸，相合方窥谢傅棊。
按部况闻秋稼熟，马前迎拜羡并儿。','',''),('quantangshi-39839','次韵九华杜先辈重阳寄投宛陵丞相','殷文圭','quantangshi','','卷40','日下飞声彻不毛，酒醒时得广离骚。
先生鬓为吟诗白，上相心因治国劳。
千乘信回鱼榼重，九华秋逈凤巢高。
强酬小谢重阳句，沙恨无金尽日淘。','',''),('quantangshi-39840','寄贺杜荀鹤及第','殷文圭','quantangshi','','卷40','一战平畴五字劳，昼归乡去锦为袍。
大鹏出海翎犹湿，骏马辞天气正豪。
九子旧山增秀绝，二南新格变风骚。
由来稽古符公道，平地丹梯甲乙高。','',''),('quantangshi-39841','春草碧色','殷文圭','quantangshi','','卷40','细草含愁碧，芊绵南浦滨。
萋萋如恨别，苒苒共伤春。
疎雨烟华润，斜阳细彩匀。
花黏繁鬬锦，人藉软胜茵。
浅映宫池水，轻遮辇路尘。
杜回如可结，誓作报恩身。','',''),('quantangshi-39842','和友人送衡尚书赴池阳副车','殷文圭','quantangshi','','卷40','淮王上将例分忧，玉帐参承半列侯。
次第选材如创厦，别离排宴向藏舟。
鵾鹏变化知难测，龙蠖升沈各有由。
躞蹀行牵金鋄重，婵娟立唱翠娥愁。
筑头勋业谐三阵，满腹诗书究九流。
金海珠韬乘月读，肉芝牙茗拨云收。
赤鳞斾卷鸥汀晚，青雀船横雁阵秋。
十字细波澄镜面，九华残雪露峰头。
醉沈北海千尊酒，吟上南荆百尺楼。
况是昭明食鱼郡，不妨闲掷钓璜钩。','',''),('quantangshi-39843','贻李南平','殷文圭','quantangshi','','卷40','紫殿西头月欲斜，曾草临淮上相麻。
润笔已曾经奏谢，更飞章句问张华。','',''),('quantangshi-39844','句','殷文圭','quantangshi','','卷40','龙舒太守人中杰，风韵堂中心似月。
众口声光夸汉将，筑头勋业佐淮王。','',''),('quantangshi-39845','钓台','徐夤','quantangshi','','卷40','金门谁奉诏，碧岸独垂钩。
旧友秪樵叟，新交惟野鸥。
嘉名悬日月，深谷化陵丘。
便可招巢父，长川好饮牛。','',''),('quantangshi-39846','旅次寓题','徐夤','quantangshi','','卷40','胡为名利役，来往老关河。
白发随梳少，青山入梦多。
途穷怜抱疾，世乱耻登科。
却起渔舟念，春风钓绿波。','',''),('quantangshi-39847','赠严司直','徐夤','quantangshi','','卷40','承家居阙下，避世出关东。
有酒刘伶醉，无儿伯道穷。
新诗吟阁赏，旧业钓台空。
雨雪还相访，心怀与我同。','',''),('quantangshi-39848','赠东方道士','徐夤','quantangshi','','卷40','葫芦窗畔挂，是物在其间。
雪色老人鬓，桃花童子颜。
祭星秋卜日，采药晓登山。
旧放长生鹿，时衔瑞草还。','',''),('quantangshi-39849','题僧壁','徐夤','quantangshi','','卷40','香厨流瀑布，独院锁孤峯。
绀发青螺长，文茵紫豹重。
卵枯皆化燕，蜜老却成蜂。
明月留人宿，秋声夜着松。','',''),('quantangshi-39850','和人经隋唐间战处','徐夤','quantangshi','','卷40','孤军前度战，一败一成功。
卷斾早归国，卧尸犹臂弓。
草间腥半在，沙上血残红。
伤魄何为者，五湖垂钓翁。','',''),('quantangshi-39851','追和常建叹王昭君','徐夤','quantangshi','','卷40','红颜如朔雪，日烁忽成空。
泪尽黄云雨，尘消白草风。
君心争不悔，恨思竟何穷。
愿化南飞燕，年年入汉宫。','',''),('quantangshi-39852','赠董先生','徐夤','quantangshi','','卷40','寿岁过于百，时闲到上京。
餐松双鬓嫩，绝粒四支轻。
雨雪思中岳，云霞梦赤城。','',''),('quantangshi-39853','河流','徐夤','quantangshi','','卷40','洪流盘砥柱，淮济不同波。
莫讶清时少，都缘曲处多。
远能通玉塞，高复接银河。
大禹成门嶮，为龙始得过。','',''),('quantangshi-39854','题南寺','徐夤','quantangshi','','卷40','久别猨啼寺，流年刦逝波。
旧僧归塔尽，古瓦长松多。
壁藓昏题记，窗萤散薜萝。
平生英壮节，何故旋消磨。','',''),('quantangshi-39855','北山秋晚','徐夤','quantangshi','','卷40','十载衣裘尽，临寒隐薜萝。
心闲缘事少，身老爱山多。
玉露催收菊，金风促翦禾。
燕秦正戎马，林下好婆娑。','',''),('quantangshi-39856','昔游','徐夤','quantangshi','','卷40','昔游红杏苑，今隐刺桐村。
岁计悬僧债，科名负国恩。
不书胝渐稳，频镊鬓无根。
惟有经邦事，年年志尚存。','',''),('quantangshi-39857','酒胡子','徐夤','quantangshi','','卷40','红筵丝竹合，用尔作欢娱。
直指宁偏党，无私绝觊觎。
当歌谁擐袖，应节渐轻躯。
恰与真相似，毡裘满颔须。','',''),('quantangshi-39858','吊崔补阙','徐夤','quantangshi','','卷40','近来吾道少，恸哭博陵君。
直节岩前竹，孤魂岭上云。
缙绅传确论，丞相取遗文。
废却中兴策，何由免用军。','',''),('quantangshi-39859','吊赤水李先生','徐夤','quantangshi','','卷40','三年悲过隙，一室类销冰。
妻病入仙观，子穷随岳僧。
荒丘寒有雨，古屋夜无灯。
往日清猷着，金门几欲徴。','',''),('quantangshi-39860','香鸭','徐夤','quantangshi','','卷40','不假陶镕妙，谁教羽翼全。
五金池畔质，百和口中烟。
觜钝鱼难啄，心空火自燃。
御炉如有阙，须进圣君前。','',''),('quantangshi-39861','鸡','徐夤','quantangshi','','卷40','名参十二属，花入羽毛深。
守信催朝日，能鸣送晓阴。
峨冠装瑞璧，利爪削黄金。
徒有稻粱感，何由报德音。','',''),('quantangshi-39862','白鸽','徐夤','quantangshi','','卷40','举翼凌空碧，依人到大邦。
粉翎栖画阁，雪影拂琼窗。
振鹭堪为侣，鸣鸠好作双。
狎鸥归未得，覩尔忆晴江。','',''),('quantangshi-39863','龟','徐夤','quantangshi','','卷40','行止竟何从，深溪与古峰。
青荷巢瑞质，绿水返灵踪。
钻骨神明应，酬恩感激重。
仙翁求一卦，何日脱龙钟。','',''),('quantangshi-39864','银结条冠子','徐夤','quantangshi','','卷40','日下徴良匠，宫中赠阿娇。
瑞莲开二孕，琼缕织千条。
蝉翼轻轻结，花纹细细挑。
舞时红袖举，纤影透龙绡。','',''),('quantangshi-39865','蜀葵','徐夤','quantangshi','','卷40','剑门南面树，移向会仙亭。
锦水饶花艳，岷山带叶青。
文君惭婉娩，神女让娉婷。
烂熳红兼紫，飘香入绣扃。','',''),('quantangshi-39866','华清宫','徐夤','quantangshi','','卷40','十二琼楼鏁翠微，暮霞遗却六铢衣。
桐枯丹穴凤何去，天在鼎湖龙不归。
帘影罢添新翡翠，露华犹湿旧珠玑。
君王魂断骊山路，且向蓬瀛伴贵妃。','',''),('quantangshi-39867','再幸华清宫','徐夤','quantangshi','','卷40','肠断将军改葬归，锦囊香在忆当时。
年来却恨相思树，春至不生连理枝。
雪女冢头瑶草合，贵妃池里玉莲衰。
霓裳旧曲飞霜殿，梦破魂惊绝后期。','',''),('quantangshi-39868','喜雨上主人尚书','徐夤','quantangshi','','卷40','天皇攘袂勅神龙，雨我公田兆岁丰。
几日淋漓侵暮角，数宵滂沛彻晨钟。
细如春雾笼平野，猛似秋风击古松。
门下十年耕稼者，坐来偏忆翠微峰。','',''),('quantangshi-39869','回文诗二首 一','徐夤','quantangshi','','卷40','飞书一幅锦文回，恨写深情寄雁来。
机上月残香阁掩，树梢烟澹绿窗开。
霏霏雨罢歌终曲，漠漠云深酒满杯。
归日几人行问卜，徽音想望倚高台。','',''),('quantangshi-39870','回文诗二首 二','徐夤','quantangshi','','卷40','轻帆数点千峰碧，水接云山四望遥。
晴日海霞红霭霭，晓天江树绿迢迢。
清波石眼泉当槛，小迳松门寺对桥。
明月钓舟渔浦远，倾山雪浪暗随潮。','',''),('quantangshi-39871','不把渔竿','徐夤','quantangshi','','卷40','不把渔竿不灌园，策筇吟遶绿芜村。
得争野老眠云乐，倍感闽王与善恩。
鸟趂竹风穿静户，鱼吹烟浪喷晴轩。
何人买我安贫趣，百万黄金未可论。','',''),('quantangshi-39872','古往今来','徐夤','quantangshi','','卷40','古往今来恨莫穷，不如沈醉卧春风。
雀儿无角长穿屋，鹦鹉能言却入笼。
柳惠岂嫌居下位，朱云直去指三公。
闲思郭令长安宅，草没匡墙旧事空。','',''),('quantangshi-39873','十里烟笼','徐夤','quantangshi','','卷40','十里烟笼一径分，故人迢遰久离羣。
白云明月皆由我，碧水青山忽赠君。
浮世宦名浑似梦，半生勤苦谩为文。
北邙坡上青松下，尽是锵金佩玉坟。','',''),('quantangshi-39874','偶书','徐夤','quantangshi','','卷40','巧者多为拙者资，良筹第一在乘时。
市门逐利终身饱，谷口躬耕尽日饥。
琼玖鬻来燕石贵，蓬蒿芳处楚兰衰。
高皇冷笑重瞳客，盖世拔山何所为。','',''),('quantangshi-39875','润屋','徐夤','quantangshi','','卷40','润屋丰家莫妄求，眼看多是与身讐。
百禽罗得皆黄口，四皓山居始白头。
玉烁火光争肯变，草芳崎岸不曾秋。
朱门粉署何由到，空寄新诗谢列侯。','',''),('quantangshi-39876','退居','徐夤','quantangshi','','卷40','鹤性松心合在山，五侯门馆怯趋攀。
三年卧病不能免，一日受恩方得还。
明月送人沿驿路，白云随马入柴关。
笑他范蠡贪惏甚，相罢金多始退闲。','',''),('quantangshi-39877','闭门','徐夤','quantangshi','','卷40','闭却闲门卧小窗，更何人与疗膏肓。
一生有酒唯知醉，四大无根可预量。
骨冷欲针先觉痛，肉顽频炙不成疮。
漳滨伏枕文园渴，盗跖纵横似虎狼。','',''),('quantangshi-39878','开窗','徐夤','quantangshi','','卷40','闭户开窗寝又兴，三更时节也如冰。
长闲便是忘机者，不出真如过夏僧。
环堵岂惭蜗作舍，布衣宁假鹤为翎。
蔷薇花尽薰风起，绿叶空随满架藤。','',''),('quantangshi-39879','灯花','徐夤','quantangshi','','卷40','点蜡烧银却胜栽，九华红艳吐玫瑰。
独含冬夜寒光拆，不傍春风暖处开。
难见只因能送喜，莫挑唯恐堕成灰。
贪膏附热多相误，为报飞蛾罢拂来。','',''),('quantangshi-39880','东归出城留别知己','徐夤','quantangshi','','卷40','韦蒙屈指许非才，三载长安共酒杯。
欲别未攀杨柳赠，相留拟待牡丹开。
寒随御水波光散，暖逐衡阳雁影来。
他日因书问衰飒，东溪须访子陵台。','',''),('quantangshi-39881','咏怀','徐夤','quantangshi','','卷40','愁花变出白髭须，半世辛勤一事无。
道在或期君梦想，贫来争奈鬼揶揄。
马卿自愧长婴疾，颜子谁怜不是愚。
借取秦宫台上镜，为时开照汉妖狐。','',''),('quantangshi-39882','郊村独游','徐夤','quantangshi','','卷40','岁闰堪怜历候迟，出门惟与野云期。
惊鱼掷上绿荷芰，栖鸟啄余红荔枝。
末路可能长薄命，修途应合有良时。
市头相者休相戏，蹙膝先生半自知。','',''),('quantangshi-39883','经故翰林杨左丞池亭','徐夤','quantangshi','','卷40','八角红亭荫绿池，一朝青草盖遗基。
蔷薇藤老开花浅，翡翠巢空落羽奇。
春榜几深门下客，乐章多取集中诗。
平生德义人间诵，身后何劳更立碑。','',''),('quantangshi-39884','经故广平员外旧宅','徐夤','quantangshi','','卷40','门巷萧条引涕涕，遗孤三岁着麻衣。
绿杨树老垂丝短，翠竹林荒着笋稀。
结社僧因秋朔吊，买书船近葬时归。
平生欲献匡君策，抱病犹言未息机。','',''),('quantangshi-39885','潘丞相旧宅','徐夤','quantangshi','','卷40','绿树垂枝荫四邻，春风还似旧时春。
年年燕是雕梁主，处处花随落月尘。
七贵竟为长逝客，五侯寻作不归人。
秋槐影薄蝉声尽，休谓龙门待化鳞。','',''),('quantangshi-39886','门外闲田数亩长有泉源因筑直堤分为两沼','徐夤','quantangshi','','卷40','左右澄漪小槛前，直堤高筑古平川。
十分春水双檐影，一片秋空两月悬。
前岸好山摇细浪，夹门嘉树合晴烟。
坐来暗起江湖思，速问溪翁买钓船。','',''),('quantangshi-39887','北园','徐夤','quantangshi','','卷40','北园干叶旋空枝，兰蕙还将众草衰。
笼鸟上天犹有待，病龙兴雨岂无期。
身闲不厌频来客，年老偏怜最小儿。
生事罢求名与利，一窗书策是年支。','',''),('quantangshi-39888','溪上要一只白簟扇盖头垂钓去年就节推侍御请之蒙惠一柄紫花纹者虽则鳞华具甚纰薄不及清源所出因就南郡陈常侍请之遂成拙句','徐夤','quantangshi','','卷40','难求珍箑过炎天，远就金貂乞月圆。
直在引风欹角枕，且图遮日上渔船。
但令织取无花簟，不用挑为饮露蝉。
莫道如今时较晚，也应留得到明年。','',''),('quantangshi-39889','招隐','徐夤','quantangshi','','卷40','齿发那能敌岁华，早知休去避尘沙。
鬼神只阚高明里，倚伏不干栖隐家。
陶景岂全轻组绶，留侯非独爱烟霞。
赠君吉语堪铭座，看取朝开暮落花。','',''),('quantangshi-39890','忆山中友人','徐夤','quantangshi','','卷40','忆得当年接善邻，苦将闲事强夫君。
鬬开碧沼分明月，各领青山占白云。
近日药方多缮写，旧来诗草半烧焚。
金门几欲言西上，惆怅关河正用军。','',''),('quantangshi-39891','溪隐','徐夤','quantangshi','','卷40','将名将利已无缘，深隐清溪拟学仙。
绝却腥膻胜服药，断除杯酒合延年。
蜗牛壳漏宁同舍，榆荚花开不是钱。
鸾鹤久从笼槛闭，春风却放纸为鸢。','',''),('quantangshi-39892','酒醒','徐夤','quantangshi','','卷40','酒醒欲得适闲情，骑马那胜策杖行。
天暖天寒三月暮，溪南溪北两村名。
沙澄浅水鱼知钓，花落平田鹤见耕。
望断长安故交远，来书未说九河清。','',''),('quantangshi-39893','梦断','徐夤','quantangshi','','卷40','梦断纱窗半夜雷，别君花落又花开。
渔阳路远书难寄，衡岳山高月不来。
玄燕有情穿绣户，灵龟无应祝金杯。
人生若得长相对，萤火生烟草化灰。','',''),('quantangshi-39894','人事','徐夤','quantangshi','','卷40','人事飘如一炷烟，且须求佛与求仙。
丰年甲子春无雨，良夜庚申夏足眠。
颜氏岂嫌瓢里饮，孟光非取镜中妍。
平生生计何为者，三迳苍苔十亩田。','',''),('quantangshi-39895','休说','徐夤','quantangshi','','卷40','休说人间有陆沈，一樽闲待月明斟。
时来不怕沧溟阔，道大却忧潢潦深。
白首钓鱼应是分，青云干禄已无心。
梓桐赋罢相如隐，谁为君前永夜吟。','',''),('quantangshi-39896','嘉运','徐夤','quantangshi','','卷40','嘉运良时两阻修，钓竿蓑笠乐林丘。
家无寸帛浑闲事，身似浮云且自由。
庭际鸟啼花旋落，潭心月在水空流。
晨炊一箸红银粒，忆着长安索米秋。','',''),('quantangshi-39897','绿鬓','徐夤','quantangshi','','卷40','绿鬓先生自出林，孟光同乐野云深。
躬耕为食古人操，非织不衣贤者心。
眼众岂能分瑞璧，舌多须信烁良金。
君看黄阁南迁客，一过泷州绝好音。','',''),('quantangshi-39898','骄侈','徐夤','quantangshi','','卷40','骄侈阽危俭素牢，镜中形影岂能逃。
石家恃富身还灭，颜子非贫道不遭。
蝙蝠亦能知日月，鸾凤那肯啄腥臊。
古今人事惟堪醉，好脱霜裘换绿醪。','',''),('quantangshi-39899','龙蛰二首 一','徐夤','quantangshi','','卷40','龙蛰蛇蟠却待伸，和光何惜且同尘。
伍员岂是吹箫者，冀缺非同执耒人。
神剑触星当变化，良金成器在陶钧。
穰侯休忌关东客，张禄先生竟相秦。','',''),('quantangshi-39900','龙蛰二首 二','徐夤','quantangshi','','卷40','休说雄才间代生，到头难与运相争。
时通有诏征枚乘，世乱无人荐禰衡。
逐日莫矜驽马步，司晨谁要牝鸡鸣。
中林且作烟霞侣，尘满关河未可行。','',''),('quantangshi-39901','逐臭苍蝇','徐夤','quantangshi','','卷40','逐臭苍蝇岂有为，清蝉吟露最高奇。
多藏苟得何名富，饱食嗟来未胜饥。
穷寂不妨延寿考，贪狂总待算毫厘。
首阳山翠千年在，好奠冰壶吊伯夷。','',''),('quantangshi-39902','牡丹花二首 一','徐夤','quantangshi','','卷40','看徧花无胜此花，翦云披雪蘸丹砂。
开当青律二三月，破却长安千万家。
天纵穠华刳鄙吝，春教妖艳毒豪奢。
不随寒令同时放，倍种双松与辟邪。','',''),('quantangshi-39903','牡丹花二首 二','徐夤','quantangshi','','卷40','万万花中第一流，浅霞轻染嫩银瓯。
能狂绮陌千金子，也惑朱门万户侯。
朝日照开携酒看，暮风吹落遶栏收。
诗书满架尘埃扑，尽日无人畧举头。','',''),('quantangshi-39904','尚书座上赋牡丹花得轻字韵其花自越中移植','徐夤','quantangshi','','卷40','流苏凝作瑞华精，仙阁开时丽日晴。
霜月冷销银烛焰，宝瓯圆印彩云英。
娇含嫩脸春妆薄，红蘸香绡艳色轻。
早晚有人天上去，寄他将赠董双成。','',''),('quantangshi-39905','依韵和尚书再赠牡丹花','徐夤','quantangshi','','卷40','烂银基地薄红妆，羞杀千花百卉芳。
紫陌昔曾游寺看，朱门今在遶栏望。
龙分夜雨资娇态，天与春风发好香。
多着黄金何处买，轻桡挑过镜湖光。','',''),('quantangshi-39906','郡庭惜牡丹','徐夤','quantangshi','','卷40','肠断东风落牡丹，为祥为瑞久留难。
青春不驻堪垂泪，红艳已空犹倚栏。
积藓下销香蘂尽，晴阳高照露华干。
明年万叶千枝长，倍发芳菲借客看。','',''),('quantangshi-39907','追和白舍人咏白牡丹','徐夤','quantangshi','','卷40','蓓蕾抽开素练囊，琼葩薰出白龙香。
裁分楚女朝云片，翦破姮娥夜月光。
雪句岂须徴柳絮，粉腮应恨帖梅妆。
槛边几笑东篱菊，冷折金风待降霜。','',''),('quantangshi-39908','忆牡丹','徐夤','quantangshi','','卷40','绿树多和雪霰栽，长安一别十年来。
王侯买得价偏重，桃李落残花始开。
宋玉邻边腮正嫩，文君机上锦初裁。
沧洲春暮空肠断，画看犹将劝酒杯。','',''),('quantangshi-39909','惜牡丹','徐夤','quantangshi','','卷40','今日狂风揭锦筵，预愁吹落夕阳天。
闲看红艳只须醉，谩惜黄金岂是贤。
南国好偷夸粉黛，汉宫宜摘赠神仙。
良时虽作莺花主，白马王孙恰少年。','',''),('quantangshi-39910','览柳浑汀洲采白苹之什因成一章','徐夤','quantangshi','','卷40','采尽汀苹恨别离，鸳鸯鸂鶒总双飞。
月明南浦梦初断，花落洞庭人未归。
天远有书随驿使，夜长无烛照寒机。
年来泣泪知多少，重叠成痕在绣衣。','',''),('quantangshi-39911','司直巡官无诸移到玫瑰花','徐夤','quantangshi','','卷40','芳菲移自越王台，最似蔷薇好并栽。
穠艳尽怜胜彩绘，嘉名谁赠作玫瑰。
春藏锦绣风吹拆，天染琼瑶日照开。
为报朱衣早邀客，莫教零落委苍苔。','',''),('quantangshi-39912','梅花','徐夤','quantangshi','','卷40','琼瑶初绽岭头葩，蘂粉新妆姹女家。
举世更谁怜洁白，痴心皆尽爱繁华。
玄冥借与三冬景，谢氏输他六出花。
结实和羹知有日，肯随羌笛落天涯。','',''),('quantangshi-39913','茘枝二首 一','徐夤','quantangshi','','卷40','朱弹星丸粲日光，绿琼枝散小香囊。
龙绡壳绽红纹粟，鱼目珠涵白膜浆。
梅熟已过南岭雨，橘酸空待洞庭霜。
蛮山蹋晓和烟摘，拜捧金盘奉越王。','',''),('quantangshi-39914','茘枝二首 二','徐夤','quantangshi','','卷40','日日薰风卷瘴烟，南园珍菓茘枝先。
灵鸦啄破琼津滴，宝器盛来蚌腹圆。
锦里只闻销醉客，蘂宫惟合赠神仙。
何人刺出[猩猩]血，深染罗纹遍壳鲜。','',''),('quantangshi-39915','菊花','徐夤','quantangshi','','卷40','桓景登高事可寻，黄花开处绿畦深。
消灾辟恶君须采，冷露寒霜我自禁。
篱物早荣还早谢，涧松同德复同心。
陶公岂是居贫者，剩有东篱万朵金。','',''),('quantangshi-39916','画松','徐夤','quantangshi','','卷40','涧底阴森验笔精，笔闲开展觉神清。
曾当月照还无影，若许风吹合有声。
枝偃只应玄鹤识，根深且与茯苓生。
天台道士频来见，说似株株倚赤城。','',''),('quantangshi-39917','草木','徐夤','quantangshi','','卷40','草木无情亦可嗟，重开明镜照无涯。
菊英空折罗含宅，榆荚不生原宪家。
天命岂凭医药石，世途还要辟虫沙。
仙翁乞取金盘露，洗却苍苍两鬓华。','',''),('quantangshi-39918','松','徐夤','quantangshi','','卷40','涧底青松不染尘，未逢良匠竞谁分。
龙盘劲节岩前见，鹤唳翠梢天上闻。
大厦可营谁择木，女萝相附欲凌云。
皇王自有增封日，修竹徒劳号此君。','',''),('quantangshi-39919','竹','徐夤','quantangshi','','卷40','翠染琅玕粉渐开，东南移得会稽栽。
游丝挂处渔竿去，绿水夹时龙影来。
风触有声含六律，露沾如洗绝浮埃。
王猷旧宅无人到，抱却清阴盖绿苔。','',''),('quantangshi-39920','尚书打球小骢步骤最奇因有所赠','徐夤','quantangshi','','卷40','善价千金未可论，燕王新寄小龙孙。
逐将白日驰青汉，衔得流星入画门。
步骤最能随手转，性灵多恐会人言。
桃花雪点多虽贵，全假当场一顾恩。','',''),('quantangshi-39921','尚书惠蜡面茶','徐夤','quantangshi','','卷40','武夷春暖月初圆，采摘新芽献地仙。
飞鹊印成香蜡片，啼猿溪走木兰船。
金槽和碾沈香末，冰椀轻涵翠缕烟。
分赠恩深知最异，晚铛宜煮北山泉。','',''),('quantangshi-39922','劝酒','徐夤','quantangshi','','卷40','休向尊前愬羽觥，百壶清酌与君倾。
身同绿树年年老，事比红尘日日生。
六国英雄徒反覆，九原松柏甚分明。
醉乡路与干坤隔，岂信人间有利名。','',''),('quantangshi-39923','断酒','徐夤','quantangshi','','卷40','因论沈湎觉前非，便碎金罍与羽巵。
采茗早驰三蜀使，看花甘负五侯期。
窗间近火刘伶传，坐右新铭管仲辞。
此事十年前已说，匡庐山下老僧知。','',''),('quantangshi-39924','忆旧山','徐夤','quantangshi','','卷40','涧竹岩云有旧期，二年频长鬓边丝。
游鱼不爱金杯水，栖鸟敢求琼树枝。
陶景恋深松桧影，留侯抛却帝王师。
龙争虎攫皆闲事，数叠山光在梦思。','',''),('quantangshi-39925','西华','徐夤','quantangshi','','卷40','五千仞有余神秀，一一排云上泬㵳。
叠嶂出关分二陕，残冈过水作中条。
巨灵庙破生春草，毛女峰高入绛[霄]。
拜祝金天乞阴德，为民求主降神尧。','',''),('quantangshi-39926','岚似屏风','徐夤','quantangshi','','卷40','岚似屏风草似茵，草边时脍锦花鳞。
山中宰相陶弘景，谷口耕夫郑子真。
宦达到头思野逸，才多未必笑清贫。
君看东洛平泉宅，只有年年百卉春。','',''),('quantangshi-39927','忆潼关','徐夤','quantangshi','','卷40','洞壑双扉入到初，似从深穽覩高墟。
天开白日临军国，山夹黄河护帝居。
隋炀远游宜不反，奉春长策竟何如。
须知皇汉能扃鐍，延得年过四百余。','',''),('quantangshi-39928','忆潼关早行','徐夤','quantangshi','','卷40','行客起看仙掌月，落星斜照浊河泥。
故山远处高飞雁，去马鸣时先早鸡。
关柳不知谁氏种，岳碑犹见圣君题。
蒭荛十轴僮三尺，岂谓青云便有梯。','',''),('quantangshi-39929','鸿门','徐夤','quantangshi','','卷40','耨月耕烟水国春，薄徒应笑作农人。
皇王尚法三推礼，白社宁忘四体勤。
雨洒蓑衣芳草暗，鸟啼云树小村贫。
犹胜堕力求飧者，五斗低腰走世尘。','',''),('quantangshi-39930','忆长安行','徐夤','quantangshi','','卷40','旧历关中忆废兴，僭奢须戒俭须凭。
火光只是烧秦冢，贼眼何曾视灞陵。
钟鼓煎催人自急，侯王更换恨难胜。
不如坐钓清溪月，心共寒潭一片澄。','',''),('quantangshi-39931','忆长安上省年','徐夤','quantangshi','','卷40','忽忆关中逐计车，历坊骑马信空虚。
三秋病起见新雁，八月夜长思旧居。
宗伯帐前曾献赋，相君门下再投书。
如今说着犹堪泣，两宿都堂过岁除。','',''),('quantangshi-39932','长安述怀','徐夤','quantangshi','','卷40','黄河冰合尚来游，知命知时肯躁求。
词赋有名堪自负，春风落第不曾羞。
风尘色里凋双鬓，[鼙]鼓声中历几州。
十载公卿早言屈，何须课夏更冥搜。','',''),('quantangshi-39933','长安即事三首 一','徐夤','quantangshi','','卷40','抛掷清溪旧钓钩，长安寒暑再环周。
便随莺羽三春化，只说蝉声一度愁。
扫雪自怜窗纸照，上天宁愧海槎流。
明时则待金门诏，肯羡班超万户侯。','',''),('quantangshi-39934','长安即事三首 二','徐夤','quantangshi','','卷40','无酒穷愁结自舒，饮河求满不求余。
身登霄汉平时第，家得干戈定后书。
富贵敢期苏季子，清贫方见马相如。
明时用即匡君去，不用何妨却钓鱼。','',''),('quantangshi-39935','长安即事三首 三','徐夤','quantangshi','','卷40','拖紫腰金不要论，便堪归隐白云村。
更无名籍强金榜，岂有花枝胜杏园。
绮席促时皆国器，羽觥飞处尽王孙。
高眠亦是前贤事，争报春闱莫大恩。','',''),('quantangshi-39936','东京次新安道中','徐夤','quantangshi','','卷40','贼去兵来岁月长，野蒿空满坏墙匡。
旋从古辙成深谷，几见金舆过上阳。
洛水送年催代谢，嵩山擎日拂穹苍。
殊时异世为儒者，不见文皇与武皇。','',''),('quantangshi-39937','山阴故事','徐夤','quantangshi','','卷40','坦腹夫君不可逢，千年犹在播英风。
红鹅化鹤青天远，彩笔成龙绿水空。
爱竹只应怜直节，书裙多是为奇童。
吹笙缑岭登山后，东注清流岂有穷。','',''),('quantangshi-39938','温陵即事','徐夤','quantangshi','','卷40','早年师友教为文，卖却鱼舟网典坟。
国有安危期日谏，家无担石暂从军。
非才岂合攀丹桂，多病犹堪伴白云。
争得千钟季孙粟，沧洲归与故人分。','',''),('quantangshi-39939','温陵残腊书怀寄崔尚书','徐夤','quantangshi','','卷40','济川无楫拟何为，三杰还从汉祖推。
心学庭槐空发火，鬓同门柳即垂丝。
中兴未遇先怀策，除夜相催也课[诗]。
江上年年接君子，一杯春酒一枰棊。','',''),('quantangshi-39940','义通里寓居即事','徐夤','quantangshi','','卷40','家住寒梅翠岭东，长安时节咏途穷。
牡丹窠小春余雨，杨柳丝疎夏足风。
愁鬓已还年纪白，衰容宁藉酒杯红。
长卿甚有凌云作，谁与清吟遶帝宫。','',''),('quantangshi-39941','上阳宫词','徐夤','quantangshi','','卷40','点点苔钱上玉墀，日斜空望六龙西。
妆台尘暗青鸾掩，宫树月明黄鸟啼。
庭草可怜分雨露，君恩深恨隔云泥。
银蟾借与金波路，得入重轮伴羿妻。','',''),('quantangshi-39942','西寨寓居 一','徐夤','quantangshi','','卷40','闲读南华对酒杯，醉携筇竹画苍苔。
豪门有利人争去，陋巷无权客不来。
解报可能医病雀，重燃谁肯照寒灰。
严陵万古清风在，好棹东溪咏钓台。','',''),('quantangshi-39943','西寨寓居 二','徐夤','quantangshi','','卷40','功智争驰澹薄空，犹怀忠信拟何从。
鸱鸢啄腐疑雏凤，神鬼欺贫笑伯龙。
烈日不融双鬓雪，病身全仰竹枝筇。
崇侯入辅严陵退，堪忆啼猨万仞峯。','',''),('quantangshi-39944','题福州天王阁','徐夤','quantangshi','','卷40','绝境宜栖独角仙，金张到此亦忘还。
三门里面千层阁，万井中心一朵山。
江拗碧湾盘洞府，石排青壁护禅关。
有时海上看明月，辗出冰轮叠浪间。','',''),('quantangshi-39945','忆荐福寺南院','徐夤','quantangshi','','卷40','忆昔长安落第春，佛宫南院独游频。
灯前不动惟金像，壁上曾题尽古人。
鶗鴂声中双阙雨，牡丹花际六街尘。
啼猨溪上将归去，合问升平诣秉钧。','',''),('quantangshi-39946','塔院小屋四壁皆是卿相题名因成四韵','徐夤','quantangshi','','卷40','雁塔搀空映九衢，每看华宇每踟蹰。
题名尽是台衡迹，满壁堪为宰辅图。
鸾凤岂巢荆棘树，虬龙多蛰帝王都。
谁知远客思归梦，夜夜无船自过湖。','',''),('quantangshi-39947','题名琉璃院','徐夤','quantangshi','','卷40','一条溪遶翠岩隈，行脚僧言胜五台。
农罢树阴黄犊卧，斋时山下白衣来。
松因往日门人种，路是前生长老开。
三卷贝多金粟语，可能长诵免轮回。','',''),('quantangshi-39948','寺中偶题','徐夤','quantangshi','','卷40','听话金仙眉相毫，每来皆得解尘劳。
鹤栖云路看方贵，僧倚松门见始高。
名利罢烧心内火，雪霜偏垢鬓边毛。
银蟾未出金乌在，更上层楼眺海涛。','',''),('quantangshi-39949','山寺寓居','徐夤','quantangshi','','卷40','高卧东林最上方，水声山翠剔愁肠。
白云送雨笼僧阁，黄叶随风入客堂。
终去四明成大道，暂从双鬓许秋霜。
披缁学佛应无分，鹤氅谈空亦不妨。','',''),('quantangshi-39950','寄僧寓题','徐夤','quantangshi','','卷40','佛顶抄经忆惠休，众人皆谓我悠悠。
浮生真个醉中梦，闲事莫添身外愁。
百岁付于花暗落，四时随却水奔流。
安眠静笑思何报，日夜焚修祝郡侯。','',''),('quantangshi-39951','游灵隐天竺二寺','徐夤','quantangshi','','卷40','丹井冷泉虚易到，两山真界实难名。
石和云雾莲华气，月过楼台桂子清。
腾踏回桥巡像设，罗穿曲洞出龙成。
更怜童子呼猿去，飒飒萧萧下树行。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-39952','醉题邑宰南塘屋壁','徐夤','quantangshi','','卷40','万古清淮照远天，黄河浊浪不相关。
县留东道三千客，宅锁南塘一片山。
草色净经秋雨绿，烧痕寒入晓窗斑。
闽王美锦求贤制，未许陶公解印还。','',''),('quantangshi-39953','题泗洲塔','徐夤','quantangshi','','卷40','十年前事已悠哉，旋被钟声早暮催。
明月似师生又没，白云如客去还来。
烟笼瑞阁僧经静，风打虚窗佛幌开。
惟有南边山色在，重重依旧上高台。','',''),('quantangshi-39954','东归题屋壁','徐夤','quantangshi','','卷40','尘埃归去五湖东，还是衡门一亩宫。
旧业旋从征赋失，故人多逐乱离空。
因悲尽室如悬罄，却拟携家学转蓬。
见说武王天上梦，无情曾与傅岩通。','',''),('quantangshi-39955','寓题','徐夤','quantangshi','','卷40','酒壶棋局似闲人，竹笏蓝衫老此身。
托客买书重得卷，爱山移宅近为邻。
鸣蛩阁上风吹病，落叶庭中月照贫。
见说天池波浪阔，也应涓滴溅穷鳞。','',''),('quantangshi-39956','偶题','徐夤','quantangshi','','卷40','闲补亡书见废兴，偶然前古也填膺。
秦宫犹自拜张禄，楚幕不知留范增。
大道岂全关历数，雄图强半属贤能。
燕台财力知多少，谁筑黄金到九层。','',''),('quantangshi-39957','寓题述怀','徐夤','quantangshi','','卷40','大道真风早晚还，妖讹成俗污干坤。
宣尼既没苏张起，凤鸟不来鸡雀喧。
刍少可能供骥子，草多谁复访兰荪。
尧廷忘却徴元凯，天阙重关十二门。','',''),('quantangshi-39958','将入城灵口道中作','徐夤','quantangshi','','卷40','路上长安惟咫尺，灞陵西望接秦源。
依稀日下分天阙，隐映云边是国门。
锦袖臂鹰河北客，青桑鸣雉渭南村。
高风九万程途近，与报沧洲欲化鲲。','',''),('quantangshi-39959','新屋','徐夤','quantangshi','','卷40','耳顺何为土木勤，叔孙墙屋有前闻。
纵然一世如红叶，犹得十年吟白云。
性逸且图称野客，才难非敢傲明君。
清甜数尺沙泉井，平与邻家昼夜分。','',''),('quantangshi-39960','新葺茆堂 一','徐夤','quantangshi','','卷40','翦竹诛茆就水滨，静中还得保天真。
只闻神鬼害盈满，不见古今争贱贫。
树影便为廊庑屋，草香权当绮罗茵。
堦前一片泓澄水，借与汀禽活紫鳞。','',''),('quantangshi-39961','新葺茆堂 二','徐夤','quantangshi','','卷40','耨水耕山息故林，壮图嘉话负前心。
素丝鬓上分愁色，络纬牀头和苦吟。
笔研不才当付火，方书多诳罢烧金。
同年二十八君子，游楚游秦断好音。','',''),('quantangshi-39962','茆亭','徐夤','quantangshi','','卷40','鸳瓦虹梁计已疎，织茅编竹称贫居。
翦平恰似山僧笠，扫静真同道者庐。
秋晚卷帘看过雁，月明凭槛数跳鱼。
重门公子应相笑，四壁风霜老读书。','',''),('quantangshi-39963','客厅','徐夤','quantangshi','','卷40','移却松筠致客堂，净泥环堵贮荷香。
衡茅只要免风雨，藻梲不须高栋梁。
丰蔀仲尼明演易，作歌五子恨雕墙。
燕台汉阁王侯事，青史千年播耿光。','',''),('quantangshi-39964','咏写真','徐夤','quantangshi','','卷40','写得衰容似十全，闲开僧舍静时悬。
瘦于南国从军日，老却东堂射策年。
潭底看身宁有异，镜中引影更无偏。
借将前辈真仪比，未愧金銮李谪仙。','',''),('quantangshi-39965','放榜日','徐夤','quantangshi','','卷40','喧喧车马欲朝天，人探东堂榜已悬。
万里便随金鸑鷟，三台仍借玉连钱。
花浮酒影彤霞烂，日照衫光瑞色鲜。
十二街前楼阁上，卷帘谁不看神仙。','',''),('quantangshi-39966','曲江宴日呈诸同年','徐夤','quantangshi','','卷40','鹪鹩惊与凤皇同，忽向中兴遇至公。
金榜连名升碧落，紫花封勅出琼宫。
天知惜日迟迟暮，春为催花旋旋红。
好是慈恩题了望，白云飞尽塔连空。','',''),('quantangshi-39967','渤海宾贡高元固先辈闽中相访云本国人写得夤斩蛇剑御沟水人生几何赋家皆以金书列为屏障因而有赠','徐夤','quantangshi','','卷40','折桂何年下月中，闽山来问我雕虫。
肯销金翠书屏上，谁把刍荛过日东。
郯子昔时遭孔圣，繇余往代讽秦宫。
嗟嗟大国金门士，几个人能振素风。','',''),('quantangshi-39968','偶吟','徐夤','quantangshi','','卷40','千卷长书万首诗，朝蒸藜藿暮烹葵。
清时名立难皆我，晚岁途穷亦问谁。
碧岸钓归惟独笑，青山耕徧亦何为。
寻常抖擞怀中策，可便降他两鬓丝。','',''),('quantangshi-39969','赠表弟黄校书辂','徐夤','quantangshi','','卷40','产破身穷为学儒，我家诸表爱诗书。
严陵虽说临溪隐，晏子还闻近市居。
佳句丽偷红菡萏，吟窗冷落白蟾蜍。
闲来共话无生理，今古悠悠事总虚。','',''),('quantangshi-39970','辇下赠屯田何员外','徐夤','quantangshi','','卷40','封章频得帝咨嗟，报国唯将直破邪。
身到西山书几达，官登南省鬓初华。
厨非寒食还无火，菊待重阳拟泛茶。
内翰好才兼好古，秋来应数到君家。','',''),('quantangshi-39971','赠月君','徐夤','quantangshi','','卷40','出水莲花比性灵，三生尘梦一时醒。
神传尊胜陀罗咒，佛授金刚般若经。
懿德好书添女诫，素容堪画上银屏。
鸣梭轧轧纤纤手，窗户流光织女星。','',''),('quantangshi-39972','赠垂光同年','徐夤','quantangshi','','卷40','丹桂攀来十七春，如今始见茜袍新。
须知红杏园中客，终作金銮殿里臣。
逸少家风惟笔札，玄成世业是陶钧。
他时黄阁朝元处，莫忘同年射策人。','',''),('quantangshi-39973','赠杨着','徐夤','quantangshi','','卷40','藻丽荧煌冠士林，白华荣养有曾参。
十年去里荆门改，八岁能诗相座吟。
李广不侯身渐老，子山操赋恨何深。
钓鱼台上频相访，共说长安泪满襟。','',''),('quantangshi-39974','赠黄校书先辈璞闲居','徐夤','quantangshi','','卷40','驭得骊龙第四珠，退依僧寺卜贫居。
青山入眼不干禄，白发满头犹着书。
东涧野香添碧沼，南园夜雨长秋蔬。
月明扫石吟诗坐，讳却全无儋石储。','',''),('quantangshi-39975','尚书荣拜恩命夤疾中輙课恶诗二首以申攀赞 一','徐夤','quantangshi','','卷40','明公家凿凤皇池，弱冠封侯四海推。
富贵有期天授早，关河多难勅来迟。
昴星人杰当王佐，黄石仙翁识帝师。
昨日诏书犹漏缺，未言商也最能诗。','',''),('quantangshi-39976','尚书荣拜恩命夤疾中輙课恶诗二首以申攀赞 二','徐夤','quantangshi','','卷40','东郊迎入紫泥封，此日天仙下九重。
三五月明临阚泽，百千人众看王恭。
旗傍绿树遥分影，马蹋浮云不见踪。
借问乘轺何处客，相庭雄幕卷芙蓉。','',''),('quantangshi-39977','府主仆射王[抟]生日','徐夤','quantangshi','','卷40','熊罴先兆庆垂休，天地氤氲瑞气浮。
李树影笼周柱史，昴星光照汉酇侯。
数钟龟鹤千年算，律正干坤八月秋。
勋业定应归鼎鼐，生灵岂独化东瓯。','',''),('quantangshi-39978','献内翰杨侍郎','徐夤','quantangshi','','卷40','窗开青琐见瑶台，冷拂星辰逼上台。
丹凤诏成中使取，白龙香近圣君来。
欲言温署三缄口，闲赋宫词八斗才。
莫拟吟云避荣贵，庙堂玉铉待盐梅。','',''),('quantangshi-39979','送刘常侍','徐夤','quantangshi','','卷40','怀君何计更留连，忍送文星上碧天。
杜预注通三十卷，汉皇枝绍几千年。
言端信义如明月，笔下篇章似涌泉。
他日有书随雁足，东溪无令访渔船。','',''),('quantangshi-39980','送卢拾遗归华山','徐夤','quantangshi','','卷40','紫殿谏多防佞口，清秋假满别明君。
惟忧急诏归青琐，不得经时卧白云。
千载茯苓携鹤斸，一峰仙掌与僧分。
门前旧客期相荐，犹望飞书及主文。','',''),('quantangshi-39981','春末道陈先辈之清源','徐夤','quantangshi','','卷40','贫中惟是长年华，每羡君行自叹嗟。
归日捧持明月宝，去时期刻刺桐花。
春风避酒多游寺，晓骑听鸡早入衙。
千乘侯王若相问，飞书与报白云家。','',''),('quantangshi-39982','上卢三拾遗以言见黜','徐夤','quantangshi','','卷40','骨鲠如君道尚存，近来人事不须论。
疾危必厌神明药，心惑多嫌正直言。
冷眼静看真好笑，倾怀与说却为冤。
因思周庙当时诫，金口三缄示后昆。','',''),('quantangshi-39983','送王校书往清源','徐夤','quantangshi','','卷40','南国贤侯待德风，长途仍借九花骢。
清歌早贯骊龙[颔]，丹桂曾攀玉兔宫。
杨柳堤边梅雨熟，鹧鸪声里麦田空。
吟诗台上如相问，与说蟠溪直钓翁。','',''),('quantangshi-39984','岳州端午日送人游郴连','徐夤','quantangshi','','卷40','五月巴陵值积阴，送君千里客于郴。
北风吹雨黄梅落，西日过湖青草深。
竞渡岸傍人挂锦，采芳城上女遗簪。
九嶷云阔苍梧暗，与说重华旧德音。','',''),('quantangshi-39985','贺清源太保王延[彬] 一','徐夤','quantangshi','','卷40','蘂珠宫里谪神仙，八载温陵万户闲。
心地阔于云梦泽，官资高却太行山。
姜牙兆寄熊罴内，陶侃文成掌握间。
应笑清溪旧门吏，年年扶病掩柴关。','',''),('quantangshi-39986','贺清源太保王延[彬] 二','徐夤','quantangshi','','卷40','武荣江畔荫祥云，宠拜天人庆郡人。
五色鹤绫花上勅，九霄龙尾道边臣。
英雄达处谁言命，富贵来时自逼身。
更待春风飞吉语，紫泥分付与陶钧。','',''),('quantangshi-39987','病中春日即事寄主人尚书二首 一','徐夤','quantangshi','','卷40','身比秋荷觉渐枯，至君经国堕前图。
层冰照日犹能暖，病骨逢春却未苏。
镜里白须挦又长，枝头黄鸟静还呼。
庾楼恩化通神圣，何计能教掷得卢。','',''),('quantangshi-39988','病中春日即事寄主人尚书二首 二','徐夤','quantangshi','','卷40','风拍衰肌久未蠲，破窗频见月团圆。
更无旧日同人问，只有多情太守怜。
腊内送将三折股，岁阴分与五铢钱。
玄穹若假年龄在，愿捧铜盘为国贤。','',''),('quantangshi-39989','寄华山司空侍郎二首 一','徐夤','quantangshi','','卷40','金阙争权竞献功，独逃徴诏卧三峰。
鸡羣未必容于鹤，蛛网何繇捕得龙。
清论尽应书国史，静筹皆可息边烽。
风霜落满千林木，不近青青涧底松。','',''),('quantangshi-39990','寄华山司空侍郎二首 二','徐夤','quantangshi','','卷40','非云非鹤不从容，谁敢轻量傲世踪。
紫殿几徴王佐业，青山未拆诏书封。
闲吟每待秋空月，早起长先野寺钟。
前古负材多为国，满怀经济欲何从。','',''),('quantangshi-39991','寄卢端公同年仁烱时迁都洛阳新立幼主','徐夤','quantangshi','','卷40','上阳宫阙翠华归，百辟伤心序汉仪。
昆岳有炎琼玉碎，洛川无竹凤皇饥。
须簪白笔匡明主，莫许黄㼐博少师。
惆怅宸居远于日，长吁空摘鬓边丝。','',''),('quantangshi-39992','寄天台陈希畋','徐夤','quantangshi','','卷40','阴山冰冻尝迎夏，蛰户云雷只待春。
吕望岂嫌垂钓老，西施不恨浣纱贫。
坐为羽猎车中相，飞作君王掌上身。
拍手相思惟大笑，我曹宁比等闲人。','',''),('quantangshi-39993','寄两浙罗书记','徐夤','quantangshi','','卷40','进即湮沈退却升，钱塘风月过金陵。
鸿才入贡无人换，白首从军有诏徴。
博簿集成时辈駡，谗书编就薄徒憎。
怜君道在名长在，不到慈恩最上层。','',''),('quantangshi-39994','邑宰相访翼日有寄','徐夤','quantangshi','','卷40','渊明深念郤诜贫，踏破莓苔看甑尘。
碧沼共攀红菡萏，金鞍不卸紫麒麟。
残阳妬害催归客，薄酒甘尝罚主人。
夜半梦醒追复想，欲长攀接有何因。','',''),('quantangshi-39995','白酒两瓶送崔侍御','徐夤','quantangshi','','卷40','雪化霜融好泼醅，满壶冰冻向春开。
求从白石洞中得，携向百花岩畔来。
几夕露珠寒贝齿，一泓银水冷琼杯。
湖边送与崔夫子，谁见嵇山尽日颓。','',''),('quantangshi-39996','依韵酬常循州','徐夤','quantangshi','','卷40','早年花县拜潘郎，寻忝飞鸣出桂堂。
日走登天长似箭，人同红树岂经霜。
帆分南浦知离别，驾在东州更可伤。
公论一麾将塞诏，且随徴令过潇湘。','',''),('quantangshi-39997','谢主人惠绿酒白鱼','徐夤','quantangshi','','卷40','早起雀声送喜频，白鱼芳酒寄来珍。
馨香乍揭春风瓮，拨刺初辞夜雨津。
樽阔最宜澄桂液，网疎殊未损霜鳞。
不曾垂钓兼亲酝，堪愧金台醉饱身。','',''),('quantangshi-39998','蜀','徐夤','quantangshi','','卷40','虽倚关张敌万夫，岂胜恩信作良图。
能均汉祚三分业，不负荆州六尺孤。
绿水有鱼贤已得，青桑如盖瑞先符。
君王幸是中山后，建国如何号蜀都。','',''),('quantangshi-39999','魏','徐夤','quantangshi','','卷40','伐罪书勋令不常，争教为帝与为王。
十年小怨诛桓邵，一檄深讐怨孔璋。
在井蛰龙如屈伏，食槽骄马忽腾骧。
奸雄事过分明见，英识空怀许子将。','',''),('quantangshi-40000','吴','徐夤','quantangshi','','卷40','一主参差六十年，父兄犹庆授孙权。
不迎曹操真长策，终谢张昭见硕贤。
建业龙盘虽可贵，武昌鱼味亦何偏。
秦嬴谩作东游计，紫气黄旗岂偶然。','',''),('quantangshi-40001','两晋','徐夤','quantangshi','','卷40','三世深谋启帝基，可怜孀妇与孤儿。
罪归成济皇天恨，戈犯明君万古悲。
巴蜀削平轻似纸，勾吴吞却美如饴。
谁知高鼻能知数，竞向中原簸战旗。','',''),('quantangshi-40002','宋二首 一','徐夤','quantangshi','','卷40','天爵休将儋石论，一身恭俭万邦尊。
赌将金带惊寰海，留得耕衣诫子孙。
缔构不应饶汉祖，奸雄何足数王敦。
草中求活非吾事，岂啻横身向庙门。','',''),('quantangshi-40003','宋二首 二','徐夤','quantangshi','','卷40','百万人甘一掷输，玄穹惟与道相符。
岂知紫殿新天子，只是丹徒旧啬夫。
五色龙章身早见，六终鸿业数难逾。
三年未得分明梦，却为兰陵起霸图。','',''),('quantangshi-40004','陈','徐夤','quantangshi','','卷40','三惑昏昏中紫宸，万机抛却醉临春。
书中不礼隋文帝，井底常携张贵嫔。
玉树歌声移入哭，金陵天子化为臣。
兵戈半渡前江水，狎客犹闻争酒巡。','',''),('quantangshi-40005','读史','徐夤','quantangshi','','卷40','亚父凄凉别楚营，天留三杰翼龙争。
高才无主不能用，直道有时方始平。
喜愠子文何頴悟，卷藏蘧瑗甚分明。
须知饮啄繇天命，休问黄河早晚清。','',''),('quantangshi-40006','汉宫新宠','徐夤','quantangshi','','卷40','位在嫔妃最上头，笑他长信女悲秋。
日中月满可能久，花落色衰殊未忧。
公主镜中争翠羽，君王袖底夺金钩。
妾家兄弟知多少，恰要同时拜列侯。','',''),('quantangshi-40007','开元即事','徐夤','quantangshi','','卷40','曲江真宰国中讹，寻奏渔阳忽荷戈。
堂上有兵天不用，幄中无策印空多。
尘惊骑透潼关锁，云护龙游渭水波。
未必蛾眉能破国，千秋休恨马嵬坡。','',''),('quantangshi-40008','李翰林','徐夤','quantangshi','','卷40','谪下三清列八仙，获调羹鼎侍龙颜。
吟开锁闼窥天近，醉卧金銮待诏闲。
旧隐不归刘备国，旅魂长寄谢公山。
遗编往简应飞去，散入祥云瑞日间。','',''),('quantangshi-40009','闻长安庚子岁事','徐夤','quantangshi','','卷40','羽檄交驰触冕旒，函关飞入铁兜鍪。
皇王去国未为恨，寰海失君方是忧。
五色大云凝蜀郡，几般妖气扑神州。
唐尧纵禅干坤位，不是重华莫谩求。','',''),('quantangshi-40010','公子行','徐夤','quantangshi','','卷40','十五辕门学控弦，六街骑马去如烟。
金多倍着牡丹价，发白未知章甫贤。
有耳不闻经国事，拜官方买谢恩笺。
相如谩说凌云赋，四壁何曾有一钱。','',''),('quantangshi-40011','依韵赠严司直','徐夤','quantangshi','','卷40','曾转双蓬到玉京，宣尼恩奏乐卿名。
歌残白石扣牛角，赋换黄金爱马卿。
沧海二隅身渐老，太行千叠路难行。
夫君才大官何小，堪恨人间事不平。','',''),('quantangshi-40012','伤前翰林杨左丞','徐夤','quantangshi','','卷40','飞上鳌头侍玉皇，三台遗耀换余光。
人间搦管穷苍颉，地上修文待卜商。
真魄肯随金石化，真风留伴蕙兰香。
皇天未启升平运，不使伊臯相禹汤。','',''),('quantangshi-40013','日月无情','徐夤','quantangshi','','卷40','日月无情也有情，朝升夕没照均平。
虽催前代英雄死，还促后来贤圣生。
三尺灵乌金借耀，一轮飞镜水饶清。
凭谁筑断东溟路，龙影蝉光免运行。','',''),('quantangshi-40014','新月','徐夤','quantangshi','','卷40','云际[婵娟]出又藏，美人肠断拜金方。
姮娥一只眉先扫，织女三分镜未光。
珠箔寄钩悬杳霭，白龙遗爪印穹苍。
更期十五圆明夜，与破阴霾照八荒。','',''),('quantangshi-40015','和尚书咏烟','徐夤','quantangshi','','卷40','无根无蒂结还融，曾触岚光彻底空。
不散几知离毕雨，欲飞须待落花风。
玲珑薄展蛟绡片，羃历轻含凤竹丛。
琼什捧来思旧隐，扑窗穿户晓溟蒙。','',''),('quantangshi-40016','宫鸎','徐夤','quantangshi','','卷40','领得春光在帝家，早从深谷出烟霞。
闲栖仙禁日边柳，饥啄御园天上花。
睍睆只宜陪阁凤，间关多是问宫娃。
可怜鹦鹉矜言语，长闭雕笼岁月赊。','',''),('quantangshi-40017','鬓发','徐夤','quantangshi','','卷40','鬓添华发数茎新，罗雀门前绝故人。
减食为缘疎五味，不眠非是守庚申。
深园竹绿齐抽笋，古木蛇青自脱鳞。
天地有炉长铸物，浊泥遗块待陶钧。','',''),('quantangshi-40018','春入鲤湖','徐夤','quantangshi','','卷40','到来峭壁白云齐，载酒春游渡九溪。
铁嶂有楼霾欲堕，石门无锁路还迷。
湖头鲤去轰雷在，树杪猨啼落日低。
回首浮生真幻梦，何如斯地傍幽栖。','',''),('quantangshi-40019','双鹭','徐夤','quantangshi','','卷40','双鹭雕笼昨夜开，月明飞出立庭隈。
但教绿水池塘在，自有碧天鸿雁来。
清韵叫霜归岛树，素翎遗雪落渔台。
何人为我追寻得，重劝溪翁酒一杯。','',''),('quantangshi-40020','鹧鸪','徐夤','quantangshi','','卷40','绣仆梅兼羽翼全，楚鸡非瑞莫争先。
啼归明月落边树，飞入百花深处烟。
避烧几曾遗远岫，引雏时见饮晴川。
茘枝初熟无人际，啄破红苞坠野田。','',''),('quantangshi-40021','鹰','徐夤','quantangshi','','卷40','害物伤生性岂驯，且宜笼罩待知人。
惟擒燕雀啖腥血，却笑鸾皇啄翠筠。
狡兔穴多非尔识，鸣鸠脰短罚君身。
豪门不读诗书者，走马平原放翫频。','',''),('quantangshi-40022','蝴蝶二首 一','徐夤','quantangshi','','卷41','缥缈青虫脱壳微，不堪烟重雨霏霏。
一枝穠艳留教住，几处春风借与飞。
防患每忧鸡雀口，怜香偏遶绮罗衣。
无情岂解关魂梦，莫信庄周说是非。','',''),('quantangshi-40023','蝴蝶二首 二','徐夤','quantangshi','','卷41','拂绿穿红丽日长，一生心事住春光。
最嫌神女来行雨，爱伴西施去采香。
风定只应攒蘂粉，夜寒长是宿花房。
鸣蝉性分殊迂阔，空解三秋噪夕阳。','',''),('quantangshi-40024','郡侯坐上观琉璃瓶中游鱼','徐夤','quantangshi','','卷41','宝器一泓银汉水，锦鳞才动即先知。
似涵明月波宁隔，欲上轻冰律未移。
薄雾罩来分咫尺，碧绡笼处较毫厘。
文翁未得沈香饵，拟置金盘召左慈。','',''),('quantangshi-40025','翦刀','徐夤','quantangshi','','卷41','宝持多用绣为囊，双日交加两鬓霜。
金匣掠平花翡翠，绿窗裁破锦鸳鸯。
初栽连理枝犹短，误绾同心带不长。
欲制緼袍先把看，质非纨绮愧銛铓。','',''),('quantangshi-40026','纸被','徐夤','quantangshi','','卷41','文采鸳鸯罢合欢，细柔轻缀好鱼牋。
一牀明月盖归梦，数尺白云笼冷眠。
披对劲风温胜酒，拥听寒风暖于绵。
赤眉豪客见皆笑，却问儒生直几钱。','',''),('quantangshi-40027','纸帐','徐夤','quantangshi','','卷41','几笑文园四壁空，避寒深入剡藤中。
误悬谢守澄江练，自宿嫦娥白兔宫。
几叠玉山开洞壑，半岩春雾结房栊。
针罗截锦饶君侈，争及蒙茸暖避风。','',''),('quantangshi-40028','贡余秘色茶盏','徐夤','quantangshi','','卷41','捩翠融青瑞色新，陶成先得贡吾君。
功剜明月染春水，轻旋薄冰盛绿云。
古镜破苔当席上，嫩荷涵露别江濆。
中山竹叶醅初发，多病那堪中十分。','',''),('quantangshi-40029','笋鞭','徐夤','quantangshi','','卷41','筇竹岩边剔翠苔，锦江波冷洗琼瑰。
累累节转苍龙骨，寸寸珠联巨蚌胎。
须向广场驱驵骏，莫从闲处挞驽骀。
宁同晋帝环营日，抛赚中途后骑来。','',''),('quantangshi-40030','咏帘','徐夤','quantangshi','','卷41','素节轻盈珠影匀，何人巧思间成文。
闲垂别殿风应度，半掩行宫麝欲薰。
绣户远笼寒焰重，玉楼高挂曙光分。
无情几恨黄昏月，才到如钩便堕云。','',''),('quantangshi-40031','咏灯','徐夤','quantangshi','','卷41','分影由来恨不同，绿窗孤馆两何穷。
荧煌短焰长疑暗，零落残花旋委空。
几处隔帘愁夜雨，谁家当户怯秋风。
莫言明灭无多事，曾比人生一世中。','',''),('quantangshi-40032','咏扇','徐夤','quantangshi','','卷41','为发凉飙满玉堂，每亲襟袖便难忘。
霜浓雪暗知何在，道契时来忽自扬。
曾伴一樽临小槛，几遮残日过回廊。
汉宫如有秋风起，谁信班姬泪数行。','',''),('quantangshi-40033','咏笔二首 一','徐夤','quantangshi','','卷41','秦代将军欲建功，截龙搜兔助英雄。
用多谁念毛皆拔，抛却更嫌心不中。
史氏只应归道直，江淹何独偶灵通。
班超握管不成事，投掷翻从万里戎。','',''),('quantangshi-40034','咏笔二首 二','徐夤','quantangshi','','卷41','君子三归擅一名，秋毫虽细握非轻。
军书羽檄教谁录，帝命王言待我成。
势健岂饶淝水阵，锋銛还学历山耕。
毛干时有何人润，尽把烧焚恨始平。','',''),('quantangshi-40035','咏钱','徐夤','quantangshi','','卷41','多蓄多藏岂足论，有谁还议济王孙。
能于祸处翻为福，解向讐家买得恩。
几怪邓通难免饿，须知夷甫不曾言。
朝争暮竞归何处，尽入权门与幸门。','',''),('quantangshi-40036','尚书筵中咏红手帕','徐夤','quantangshi','','卷41','鹤绫三尺晓霞浓，送与东家二八容。
罗带绣裙轻好系，藕丝红缕细初缝。
别来拭泪遮桃脸，行去包香坠粉胸。
无事把将缠皓腕，为君池上折芙蓉。','',''),('quantangshi-40037','尚书新造花笺','徐夤','quantangshi','','卷41','浓染红桃二月花，只宜神笔纵龙蛇。
浅澄秋水看云母，碎擘轻苔间粉霞。
写赋好追陈后宠，题诗堪送窦滔家。
使君即入金銮殿，夜直无非草白麻。','',''),('quantangshi-40038','钓车','徐夤','quantangshi','','卷41','荻湾渔客巧妆成，硾铸银星一点轻。
抛过碧江鸂[鶒]岸，轧残金井辘轳声。
轴磨騂角冰光滑，轮卷春丝水面平。
把向严滩寻辙迹，渔台基在辗难倾。','',''),('quantangshi-40039','柳','徐夤','quantangshi','','卷41','漠漠金条引线微，年年先翠报春归。
解笼飞霭延芳景，不逐乱花飘夕晖。
啼鸟噪蝉堪怅望，舞烟摇水自因依。
五株名显陶家后，见说辞荣种者稀。','',''),('quantangshi-40040','愁','徐夤','quantangshi','','卷41','夜长偏觉漏声迟，往往随歌惨翠眉。
黄叶落催砧杵日，子规啼破梦魂时。
明妃去泣千行泪，蔡琰归梳两鬓丝。
四皓入山招不得，无家归客最堪欺。','',''),('quantangshi-40041','草','徐夤','quantangshi','','卷41','废苑荒堦伴绿苔，恩疎长信恨难开。
姑苏麋鹿食思食，楚泽王孙来不来。
色嫩似将蓝汁染，叶齐如把翦刀裁。
燕昭没后多卿士，千载流芳郭隗台。','',''),('quantangshi-40042','萤','徐夤','quantangshi','','卷41','月坠西楼夜影空，透帘穿幕达房栊。
流光堪在珠玑列，为火不生榆柳中。
一一照通黄卷字，轻轻化出绿芜丛。
欲知应候何时节，六月初迎大暑风。','',''),('quantangshi-40043','水','徐夤','quantangshi','','卷41','火性何如水性柔，西来东出几时休。
莫言通海能通汉，虽解浮舟也覆舟。
湘浦暮沈尧女怨，汾河秋泛汉皇愁。
洪波激湍归何处，二月桃花满眼流。','',''),('quantangshi-40044','苔','徐夤','quantangshi','','卷41','印留麋鹿野禽踪，岩壁渔矶几处逢。
金谷晓凝花影重，章华春映柳阴浓。
石桥羽客遗前迹，陈阁才人没旧容。
归去扫除阶砌下，藓痕残绿一重重。','',''),('quantangshi-40045','晓','徐夤','quantangshi','','卷41','水尽铜龙滴渐微，景阳钟动梦魂飞。
潼关鸡唱促归骑，金殿烛残求御衣。
窗下寒机犹自织，梁间栖燕欲双飞。
羲和晴耸扶桑辔，借与寰瀛看早晖。','',''),('quantangshi-40046','别','徐夤','quantangshi','','卷41','酒尽歌终问后期，泛萍浮梗不胜悲。
东门匹马夜归处，南浦片帆飞去时。
赋罢江淹吟更苦，诗成苏武思何迟。
可怜范陆分襟后，空折梅花寄所思。','',''),('quantangshi-40047','夜','徐夤','quantangshi','','卷41','日坠虞渊烛影开，沈沈烟雾压浮埃。
剡川雪满子猷去，汉殿月生王母来。
檐挂蛛丝应渐织，风吹萤火不成灰。
愁人莫道何时旦，自有钟鸣漏滴催。','',''),('quantangshi-40048','雨','徐夤','quantangshi','','卷41','引电随龙密又轻，酒杯闲噀得嘉名。
千山草木如云暗，陆地波澜接海平。
洒竹几添春睡重，滴檐偏遣夜愁生。
阴妖冷孽成何怪，敢蔽高天日月明。','',''),('quantangshi-40049','萍','徐夤','quantangshi','','卷41','为实随流瑞色新，泛风萦草护游鳞。
密行碧水澄涵月，澁滞轻桡去采苹。
比物何名腰下剑，无根堪并镜中身。
平湖春渚知何限，拨破闲投独茧纶。','',''),('quantangshi-40050','恨','徐夤','quantangshi','','卷41','事与时违不自由，如烧如刺寸心头。
乌江项籍忍归去，雁塞李陵长系留。
燕国飞霜将破夏，汉宫纨扇岂禁秋。
须知入骨难销处，莫比人间取次愁。','',''),('quantangshi-40051','鸿','徐夤','quantangshi','','卷41','行如兄弟影连空，春去秋来燕不同。
紫塞别当秋露白，碧山飞入暮霞红。
宣王德美周诗内，苏武书传汉苑中。
况解衔芦避弓箭，一声归唳楚天风。','',''),('quantangshi-40052','鹤','徐夤','quantangshi','','卷41','阆苑瑶台岁月长，一归华表好增伤。
新声乍警初零露，折羽闲飞几片霜。
要伴神仙归碧落，岂随龟雁住方塘。
三山顶上无人处，琼树堪巢不死乡。','',''),('quantangshi-40053','鹊','徐夤','quantangshi','','卷41','神化难源瑞即开，雕陵毛羽出尘埃。
香闺报喜行人至，碧汉填河织女回。
明月解随乌绕树，青铜宁愧雀为台。
琼枝翠叶庭前植，从待翩翩去又来。','',''),('quantangshi-40054','霜','徐夤','quantangshi','','卷41','应节谁穷造化端，菊黄豺祭问应难。
红窗透出鸳衾冷，白草飞时雁塞寒。
露结芝兰琼屑厚，日干葵藿粉痕残。
世间无比催摇落，松竹何人肯更看。','',''),('quantangshi-40055','风','徐夤','quantangshi','','卷41','城上寒来思莫穷，土囊萍末两难同。
飘成远浪江湖际，吹起暮尘京洛中。
飞雪萧条残腊节，落花狼藉古行宫。
春能和煦秋摇落，生杀还同造化功。','',''),('quantangshi-40056','帆','徐夤','quantangshi','','卷41','岂劳孤棹送行舟，轻过天涯势未休。
断岸晓看残月挂，远湾寒背夕阳收。
川平直可追飞箭，风健还能溯急流。
幸遇济川恩不浅，北溟东海更何愁。','',''),('quantangshi-40057','梦','徐夤','quantangshi','','卷41','月落灯前闭北堂，神魂交入杳冥乡。
文通毫管醒来异，武帝蘅芜觉后香。
傅说已徴贤可辅，周公不见恨何长。
生松十八年方应，通塞人间岂合忙。','',''),('quantangshi-40058','东','徐夤','quantangshi','','卷41','紫气天元出故关，大明先照九垓间。
鳌山海上秦娥去，鲈鲙江边齐掾还。
青帝郊坰平似砥，主人阶级峻如山。
蟠桃树在烟涛水，解冻风高未得攀。','',''),('quantangshi-40059','西','徐夤','quantangshi','','卷41','密云郊外已回秋，日下崦嵫景懒收。
秦帝城高坚似铁，李斯书上曲如钩。
宁惟东岳凌天秀，更有长庚瞰曙流。
见说山傍偏出将，犬戎降尽复何愁。','',''),('quantangshi-40060','南','徐夤','quantangshi','','卷41','罩罩嘉鱼忆此方，送君前浦恨难量。
火山远照苍梧郡，铜柱高标碧海乡。
陆贾几时来越岛，三闾何日濯沧浪。
钟仪冠带归心阻，蝴蝶飞园万草芳。','',''),('quantangshi-40061','北','徐夤','quantangshi','','卷41','雪满湖天日影微，李君降虏失良时。
穷溟驾浪鵾鹏化，极海寄书鸿雁迟。
□□□来犹未启，残兵奔去杳难追。
可怜燕谷花[开]晚，邹律如何为一吹。','',''),('quantangshi-40062','云','徐夤','quantangshi','','卷41','漠漠沈沈向夕晖，苍梧巫峡两相依。
天心白日休空蔽，海上故山应自归。
似盖好临千乘载，如罗堪翦六铢衣。
为霖须救苍生旱，莫向西郊作雨稀。','',''),('quantangshi-40063','燕','徐夤','quantangshi','','卷41','从待衔泥溅客衣，百禽灵性比他稀。
何嫌何恨秋须去，无约无期春自归。
雕鹗不容应不怪，栋梁相庇愿相依。
吴王宫女娇相袭，合整双毛预奋飞。','',''),('quantangshi-40064','蝉','徐夤','quantangshi','','卷41','寒鸣宁与众虫同，翼鬓緌冠岂道穷。
壳蜕已从今日化，声愁何似去年中。
朝催篱菊花开露，暮促庭槐叶坠风。
从此最能惊赋客，计居何处转飞蓬。','',''),('quantangshi-40065','露','徐夤','quantangshi','','卷41','鹤鸣先警雁来天，洗竹沾花处处鲜。
散彩几当蝉饮际，凝光宜对蚌胎前。
朝垂苑草烟犹重，夜滴宫槐月正圆。
怵惕与霜同降日，苹蘩思荐独凄然。','',''),('quantangshi-40066','霞','徐夤','quantangshi','','卷41','天际何人濯锦归，偏宜残照与晨晖。
流为洞府千年酒，化作灵山几袭衣。
野烧焰连殊赫奕，愁云阴隔乍依稀。
劳生愿学长生术，飡尽红桃上汉飞。','',''),('quantangshi-40067','蒲','徐夤','quantangshi','','卷41','濯秀盘根在碧流，紫茵含露向晴抽。
编为细履随君步，织作轻帆送客愁。
疎叶稍为投饵钓，密丛还碍采莲舟。
鸳鸯鸂鶒多情甚，日日双双遶傍游。','',''),('quantangshi-40068','泉','徐夤','quantangshi','','卷41','非凿非疏出洞门，源深流嶮合还分。
高成瀑布漱逋客，清入御沟朝圣君。
迸滴几山穿破石，迅飞层峤喷开云。
旧斋一带连松竹，明月窗前枕上闻。','',''),('quantangshi-40069','烟','徐夤','quantangshi','','卷41','燎野焚林见所从，惹空横水展形容。
能滋甘雨随车润，不并行云逐梦踪。
晴鸟回笼嘉树薄，春亭娇幕好花浓。
有时片片风吹去，海碧山清过几重。','',''),('quantangshi-40070','闲','徐夤','quantangshi','','卷41','不管人间是与非，白云流水自相依。
一瓢挂树傲时代，五柳种门吟落晖。
江上翠娥遗佩去，岸边红袖采莲归。
客星辞得汉光武，却坐东江旧藓矶。','',''),('quantangshi-40071','忙','徐夤','quantangshi','','卷41','双竞龙舟疾似风，一星球子两明同。
平吴破蜀三除里，灭楚图秦百战中。
春近杜鹃啼不断，寒催归雁去何穷。
兵还失路旌旗乱，惊起红尘似转蓬。','',''),('quantangshi-40072','泪','徐夤','quantangshi','','卷41','发事牵情不自繇，偶然惆怅即难收。
已闻抱玉沾衣湿，见说迷途满目流。
滴尽绮筵红烛暗，坠残妆阁晓花羞。
世间何处偏留得，万点分明湘水头。','',''),('quantangshi-40073','月','徐夤','quantangshi','','卷41','碧落谁分造化权，结霜凝雪作婵娟。
寒蝉若不开三穴，狡兔何从上九天。
莫见团圆明处远，须看湾曲鉴时偏。
郄诜树老尧蓂换，惆怅今年似去年。','',''),('quantangshi-40074','依御史温飞卿华清宫二十二韵','徐夤','quantangshi','','卷41','地灵蒸水暖，天气待宸游。
岳拱莲花秀，峯高玉蘂秋。
朝元雕翠阁，乞巧绣琼楼。
碧海供骊岭，黄金络马头。
五王更入帐，七贵迭封侯。
夕雨鸣鸳瓦，朝阳晔柘裘。
伊臯争负鼎，舜禹让垂旒。
堕珥闲应拾，遗钗醉不收。
飞烟笼剑戟，残月照旌斿。
履朔求衣早，临阳解佩羞。
宫词裁锦段，御笔落银钩。
帝里新丰县，长安旧雍州。
雪衣传贝叶，蝉鬓插山榴。
对景瞻瑶兔，升天驾彩虬。
丹书陈北虏，玄甲擐犀牛。
圣诰多屯否，生灵少怨尤。
穹旻当有辅，帷幄岂无筹。
凤态伤红艳，鸾舆缓紫骝。
树名端正在，人欲梦魂休。
谶语山旁鬼，尘销陇畔丘。
重来芳草恨，往事落花愁。
五十年鸿业，东凭渭水流。','',''),('quantangshi-40075','尚书命题瓦砚','徐夤','quantangshi','','卷41','远向端溪得，皆因郢匠成。
凿山青霭断，琢石紫花轻。
散墨松香起，濡毫藻句清。
入台知价重，着匣恐尘生。
守黑还全器，临池早着名。
春闱携就处，军幕载将行。
不独雄文阵，兼能助笔耕。
莫嫌涓滴润，深染古今情。
洗处无瑕玷，添时识满盈。
兰亭如见用，敲戛有金声。','',''),('quantangshi-40076','东风解冻省试','徐夤','quantangshi','','卷41','暖气飘苹末，冻痕销水中。
扇冰初觉泮，吹海旋成空。
入律三春照，朝宗万里通。
岸分天影阔，色照日光融。
波起轻摇绿，鳞游乍跃红。
殷勤排弱羽，飞翥趂和风。','',''),('quantangshi-40077','和仆射二十四丈牡丹八韵','徐夤','quantangshi','','卷41','帝王城里看，无故亦无新。
忍摘都缘借，移栽未有因。
光阴嫌太促，开落一何频。
羞杀登墙女，饶将解佩人。
蘂堪灵凤啄，香许白龙亲。
素练笼霞晓，红妆带脸春。
莫辞终夕醉，易老少年身。
买取归天上，宁教逐世尘。','',''),('quantangshi-40078','钓丝竹','徐夤','quantangshi','','卷41','藋藋拂清流，堪维舴艋舟。
野虫悬作饵，溪月曲为钩。
雨润摇堦长，风吹绕指柔。
若将诸树比，还使绿杨羞。
蚕妇非尧女，渔人是子猷。
湖边旧栽处，长映读书楼。','',''),('quantangshi-40079','尚书会仙亭咏蔷薇夤坐中联四韵晚归补缉所联因成一篇','徐夤','quantangshi','','卷41','结绿根株翡翠茎，句芒中夜刺猩猩。
景阳妆赴严钟出，楚峡神教暮雨晴。
踯躅岂能同日语，玫瑰方可一时呈。
风吹嫩带香苞展，露洒啼思泪点轻。
阿母蘂宫期索去，昭君榆塞阙赍行。
藂高恐碍含泥燕，架隐宜栖报曙莺。
鬬日只忧烧密叶，映阶疑欲让双旌。
含烟散缬佳人惜，落地遗钿少妓争。
丹渥不因输绣段，钱圆谁把买花声。
海棠若要分流品，秋菊春兰两恰平。','',''),('quantangshi-40080','和尚书咏泉山瀑布十二韵','徐夤','quantangshi','','卷41','名齐火浣溢山椒，谁把惊虹挂一条。
天外倚来秋水刃，海心飞上白龙绡。
民田凿断云根引，僧圃穿通竹影浇。
喷石似烟轻漠漠，溅崖如雨冷潇潇。
水中蚕绪缠苍壁，日里虹精挂绛霄。
寒漱绿阴仙桂老，碎流红艳野桃夭。
千寻练写长年在，六出花开夏日消。
急恐划分青嶂骨，久应䙀裂翠微腰。
濯缨便可讥渔父，洗耳还宜傲帝尧。
林际猨猱偏得饭，岸边乌鹊拟为桥。
赤城未到诗先寄，庐阜曾游梦已遥。
数夜积霖声更远，郡楼欹枕听良宵。','',''),('quantangshi-40081','自咏十韵','徐夤','quantangshi','','卷41','只合沧洲钓与耕，忽依萤烛愧功成。
未游宦路叨卑宦，才到名场得大名。
梁苑二年陪众客，温陵十载佐双旌。
钱财尽是侯王惠，骨肉偕承里巷荣。
拙赋偏闻镌印卖，恶诗亲见画图呈多栽桃李期春色，阔凿池塘许月明。
寒益轻裯饶美寝，出乘车马免徒行。
麤支菽粟防饥歉，薄有杯盘备送迎。
僧俗共邻栖隐乐，妻孥同爱水云清。
如今便死还甘分，莫更嫌他白发生。','',''),('quantangshi-40082','镜中览怀','徐夤','quantangshi','','卷41','晨起梳头忽自悲，镜中亲见数茎丝。
从今休说龙泉剑，世上恩讐报已迟。','',''),('quantangshi-40083','楚国史','徐夤','quantangshi','','卷41','六国商于恨最多，良弓休绾剑休磨。
君王不翦如簧舌，再得张仪欲奈何。','',''),('quantangshi-40084','张仪','徐夤','quantangshi','','卷41','荆楚南来又北归，分明舌在不应违。
怀王本是无心者，笼得苍蝇却放飞。','',''),('quantangshi-40085','蔷薇','徐夤','quantangshi','','卷41','朝露洒时如濯锦，晚风飘处似遗钿。
重门剩着黄金锁，莫被飞琼摘上天。','',''),('quantangshi-40086','大夫松','徐夤','quantangshi','','卷41','五树旌封许岁寒，挽柯攀叶也无端。
争如涧底凌霜节，不受秦皇乱世官。','',''),('quantangshi-40087','杏园','徐夤','quantangshi','','卷41','杏苑箫声好醉乡，春风嘉宴更无双。
凭谁为谑穆天子，莫把瑶池并曲江。','',''),('quantangshi-40088','蕉叶','徐夤','quantangshi','','卷41','绿绮新裁织女机，摆风摇日影离披。
只应青帝行春罢，闲倚东墙卓翠旗。','',''),('quantangshi-40089','路旁草','徐夤','quantangshi','','卷41','楚甸秦原万里平，谁教根向路傍生。
轻蹄绣毂长相蹋，合是荣时不得荣。','',''),('quantangshi-40090','读汉纪','徐夤','quantangshi','','卷41','布衣空手取中原，劲卒雄师不足论。
楚国八千秦百万，豁开胸臆一时吞。','',''),('quantangshi-40091','李夫人二首 一','徐夤','quantangshi','','卷41','不望金舆到锦帷，人间乐极即须悲。
若言要识愁中貌，也似君恩日日衰。','',''),('quantangshi-40092','李夫人二首 二','徐夤','quantangshi','','卷41','招得香魂爵少翁，九华灯烛晓还空。
汉王不及吴王乐，且与西施死处同。','',''),('quantangshi-40093','明妃','徐夤','quantangshi','','卷41','不用牵心恨画工，帝家无策及边戎。
香魂若得升明月，夜夜还应照汉宫。','',''),('quantangshi-40094','马嵬','徐夤','quantangshi','','卷41','二百年来事远闻，从龙谁解尽如云。
张均兄弟皆何在，却是杨妃死报君。','',''),('quantangshi-40095','依韵赠南安方处士五首 一','徐夤','quantangshi','','卷41','七贵五侯生肯退，利尘名网死当抛。
黔娄寂寞严陵卧，借问何人与结交。','',''),('quantangshi-40096','依韵赠南安方处士五首 二','徐夤','quantangshi','','卷41','休把羸蹄蹋霜雪，书成何处献君王。
嵩山好与浮丘约，三十六峰云外乡。','',''),('quantangshi-40097','依韵赠南安方处士五首 三','徐夤','quantangshi','','卷41','百万僧中不为僧，比君知道仅谁能。
无家寄泊南安县，六月门前也似冰。','',''),('quantangshi-40098','依韵赠南安方处士五首 四','徐夤','quantangshi','','卷41','两鬓当春却似秋，僻居夸近野僧楼。
落花明月皆临水，明月不流花自流。','',''),('quantangshi-40099','依韵赠南安方处士五首 五','徐夤','quantangshi','','卷41','晋楚忙忙起战尘，龚黄门外有高人。
一畦云薤三株竹，席上先生未是贫。','',''),('quantangshi-40100','依韵答黄校书','徐夤','quantangshi','','卷41','慈恩雁塔参差榜，杏苑莺花次第游。
白日有愁犹可散，青山高卧况无愁。','',''),('quantangshi-40101','伤进士谢庭皓','徐夤','quantangshi','','卷41','献书犹未达明君，何事先游岱岳云。
惟有春风护冤魄，与生青草盖孤坟。','',''),('quantangshi-40102','闻司空侍郎讣音','徐夤','quantangshi','','卷41','园绮生虽逢汉室，巢由死不谒尧阶。
夫君殁去何人葬，合取夷齐隐处埋。','',''),('quantangshi-40103','偶题二首 一','徐夤','quantangshi','','卷41','买骨须求骐骥骨，爱毛宜采凤皇毛。
驽骀燕雀堪何用，仍向人前价例高。','',''),('quantangshi-40104','偶题二首 二','徐夤','quantangshi','','卷41','赋就长安振大名，斩蛇功与乐天争。
归来延寿溪头坐，终日无人问一声。','',''),('quantangshi-40105','猨','徐夤','quantangshi','','卷41','宿有乔林饮有溪，生来踪迹远尘泥。
不知心更愁何事，每向深山夜夜啼。','',''),('quantangshi-40106','追和贾浪仙古镜','徐夤','quantangshi','','卷41','谁开黄帝桥山冢，明月飞光出九泉。
狼藉藓痕磨不尽，黑云残点污秋天。','',''),('quantangshi-40107','蝴蝶三首 一','徐夤','quantangshi','','卷41','不并难飞茧里蛾，有花芳处定经过。
天风相送轻飘去，却笑[蜘蛛]谩织罗。','',''),('quantangshi-40108','蝴蝶三首 二','徐夤','quantangshi','','卷41','苒苒双双拂画栏，佳人偷眼再三看。
莫欺翼短飞长近，试就花间扑已难。','',''),('quantangshi-40109','蝴蝶三首 三','徐夤','quantangshi','','卷41','栩栩无因系得他，野园荒径一何多。
不闻丝竹谁教舞，应仗流莺为唱歌。','',''),('quantangshi-40110','新刺袜','徐夤','quantangshi','','卷41','素手春溪罢浣纱，巧裁明月半弯斜。
齐宫合赠东昏宠，好步黄金菡萏花。','',''),('quantangshi-40111','寄华山司空侍郎','徐夤','quantangshi','','卷41','山掌林中第一人，鹤书时或问眠云。
莫言疎野全无事，明月清风肯放君。','',''),('quantangshi-40112','初夏戏题','徐夤','quantangshi','','卷41','长养薰风拂晓吹，渐开荷芰落蔷薇。
青虫也学庄周梦，化作南园蛱蝶飞。','',''),('quantangshi-40113','客舍寓怀','錢珝','quantangshi','','卷41','洒洒滩声晚霁时，客亭风袖半披垂。
野云行止谁相待，明月襟怀祗自知。
无伴偶吟溪上路，有花偷笑腊前枝。
牵情景物潜惆怅，忽似伤春远别离。','',''),('quantangshi-40114','送王郎中','錢珝','quantangshi','','卷41','惜别远相送，却成惆怅多。
独归回首处，争那暮山何。','',''),('quantangshi-40115','江行无题一百首 一','錢珝','quantangshi','','卷41','倾酒向涟漪，乘流欲去时。
寸心同尺璧，投此报冯夷。','',''),('quantangshi-40116','江行无题一百首 二','錢珝','quantangshi','','卷41','江曲全萦楚，云飞半自秦。
