耕蓑钓笠取未暇，秋田有望从淋漓。','',''),('quantangshi-40290','溪上遇雨二首 二','崔道融','quantangshi','','卷41','坐看黑云衔猛雨，喷洒前山此独晴。
忽惊云雨在头上，却是山前晚照明。','',''),('quantangshi-40291','长门怨','崔道融','quantangshi','','卷41','长门花泣一枝春，争奈君恩别处新。
错把黄金买词赋，相如自是薄情人。','',''),('quantangshi-40292','秋夕','崔道融','quantangshi','','卷41','自怜三十未西游，傍山寻水过却秋。
一夜雨声多少事，不思量尽到心头。','',''),('quantangshi-40293','过隆中','崔道融','quantangshi','','卷41','玄德苍黄起卧龙，鼎分天下一言中。
可怜蜀国关张后，不见商量徐庶功。','',''),('quantangshi-40294','关下','崔道融','quantangshi','','卷41','百二山河壮帝畿，关门何事更开迟。
应从漏却田文后，每度闻鸡不免疑。','',''),('quantangshi-40295','寒食客中有怀','崔道融','quantangshi','','卷41','江上闻莺禁火时，百花开尽柳依依。
故园兄弟别来久，应到清明犹望归。','',''),('quantangshi-40296','溪夜','崔道融','quantangshi','','卷41','积雪消来溪水宽，满楼明月碎琅玕。
渔人抛得钓筒尽，却放轻舟下急滩。','',''),('quantangshi-40297','山居卧疾广利大师见访','崔道融','quantangshi','','卷41','桐谷孙枝已上弦，野人犹卧白云边。
九天飞锡应相诮，三到行朝二十年。','',''),('quantangshi-40298','村墅','崔道融','quantangshi','','卷41','正月二月村墅闲，余粮未乏人心宽。
南邻雨中揭屋笑，酒熟数家来相看。','',''),('quantangshi-40299','悲李拾遗二首 一','崔道融','quantangshi','','卷41','故友从来匪石心，谏多难得主恩深。
行朝半夜烟尘起，晓殿吁嗟一镜沈。','',''),('quantangshi-40300','悲李拾遗二首 二','崔道融','quantangshi','','卷41','天涯时有北来尘，因话它人及故人。
也是先皇能罪己，殿前频得触龙鳞。','',''),('quantangshi-40301','题李将军传','崔道融','quantangshi','','卷41','猨臂将军去似飞，弯弓百步虏无遗。
汉文自与封侯得，何必伤嗟不遇时。','',''),('quantangshi-40302','酒醒','崔道融','quantangshi','','卷41','酒醒拨剔残灰火，多少凄凉在此中。
炉畔自斟还自醉，打窗深夜雪兼风。','',''),('quantangshi-40303','郊居友人相访','崔道融','quantangshi','','卷41','柴门深掩古城秋，背郭缘溪一径幽。
不有小园新竹色，君来那肯暂淹留。','',''),('quantangshi-40304','镜湖雪霁贻方干','崔道融','quantangshi','','卷41','天外晓岚和雪望，月中归棹带冰行。
相逢半醉吟诗苦，应抵寒猨褭树声。','',''),('quantangshi-40305','秋霁','崔道融','quantangshi','','卷41','雨霁长空荡涤清，远山初出未知名。
夜来江上如钩月，时有惊鱼掷浪声。','',''),('quantangshi-40306','谢朱常侍寄贶蜀茶剡纸二首 一','崔道融','quantangshi','','卷41','瑟瑟香尘瑟瑟泉，惊风骤雨起炉烟。
一瓯解却山中醉，便觉身轻欲上天。','',''),('quantangshi-40307','谢朱常侍寄贶蜀茶剡纸二首 二','崔道融','quantangshi','','卷41','百幅轻明雪未融，薛家凡纸漫深红。
不应点染闲言语，留记将军盖世功。','',''),('quantangshi-40308','读杜紫微集','崔道融','quantangshi','','卷41','紫微才调复知兵，长觉风雷笔下生。
还有枉抛心力处，多于五柳赋闲情。','',''),('quantangshi-40309','寓题','崔道融','quantangshi','','卷41','海上乘查便合仙，若无仙骨未如船。
人间亦有支机石，虚被声名到洞天。','',''),('quantangshi-40310','寓吟集','崔道融','quantangshi','','卷41','陶集篇篇皆有酒，崔诗句句不无杯。
醉来已共身安约，让却诗人作酒魁。','',''),('quantangshi-40311','溪居即事','崔道融','quantangshi','','卷41','篱外谁家不系船，春风吹入钓鱼湾。
小童疑是有村客，急向柴门去却关。','',''),('quantangshi-40312','鸡','崔道融','quantangshi','','卷41','买得晨鸡共鸡语，常时不用等闲鸣。
深山月黑风雨夜，欲近晓天啼一声。','',''),('quantangshi-40313','献浙东柳大夫','崔道融','quantangshi','','卷41','属城甘雨几经春，圣主全分付越人。
俗眼不知青琐贵，江头争看碧油新。','',''),('quantangshi-40314','杨柳枝词','崔道融','quantangshi','','卷41','雾拈烟搓一索春，年年长似染来新。
应须唤作风流线，系得东西南北人。','',''),('quantangshi-40315','楚怀王','崔道融','quantangshi','','卷41','宫花一朵掌中开，缓急翻为敌国媒。
六里江山天下笑，张仪容易去还来。','',''),('quantangshi-40316','对早梅寄友人二首 一','崔道融','quantangshi','','卷41','忆得前年君寄诗，海边三见早梅词。
与君犹是海边客，又见早梅花发时。','',''),('quantangshi-40317','对早梅寄友人二首 二','崔道融','quantangshi','','卷41','忆得去年有遗恨，花前未醉到无花。
清芳一夜月通白，先脱寒衣送酒家。','',''),('quantangshi-40318','句','崔道融','quantangshi','','卷41','万里一点白，长空鸟不飞。
如今却羡相如富，犹有人间四壁居。','',''),('quantangshi-40319','苦吟','盧延讓','quantangshi','','卷41','莫话诗中事，诗中难更无。
吟安一个字，拈断数茎须。
险觅天应闷，狂搜海亦枯。
不同文赋易，为着者之乎。','',''),('quantangshi-40320','雪','盧延讓','quantangshi','','卷41','瑞雪落纷华，随风一向斜。
地平铺作月，天迥撒成花。
客满烧烟舍，牛牵卖炭车。
吾皇忧挟纩，犹自问君家。','',''),('quantangshi-40321','松寺','盧延讓','quantangshi','','卷41','山寺取凉当夏夜，共僧蹲坐石堦前。
两三条电欲为雨，七八个星犹在天。
衣汗稍停牀上扇，茶香时拨涧中泉。
通宵听论莲华义，不藉松窗一觉眠。','',''),('quantangshi-40322','赠僧','盧延讓','quantangshi','','卷41','浮世浮华一断空，偶抛烦恼到莲宫。
高僧解语牙无水，老鹤能飞骨有风。
野色吟余生竹外，山阴坐久入池中。
禅师莫问求名苦，滋味过于食蓼虫。','',''),('quantangshi-40323','逢友人赴阙','盧延讓','quantangshi','','卷41','正当天下待雍熙，丹诏徴来早为迟。
倚马才高犹爱艺，问牛心在肯容私。
吏开黄阁排班处，民拥青门看入时。
却笑郡人留不得，感恩唯拟立生祠。','',''),('quantangshi-40324','哭李郢端公','盧延讓','quantangshi','','卷41','军门半掩槐花宅，每过犹闻哭临声。
北固暴亡兼在路，东都权葬未归茔。
渐穷老仆慵看马，着惨佳人暗理筝。
诗侣酒徒消散尽，一场春梦越王城。','',''),('quantangshi-40325','谢杨尚书惠樱桃','盧延讓','quantangshi','','卷41','满合虚红怕动摇，尚书知重赐樱桃。
揉蓝尚带新鲜叶，泼血犹残旧折条。
万颗真珠轻触破，一团甘露软含消。
春来老病尤珍荷，并食中肠似火烧。','',''),('quantangshi-40326','寒食日戏赠李侍御','盧延讓','quantangshi','','卷41','十二街如市，红尘咽不开。
洒蹄骢马汗，没处看花来。','',''),('quantangshi-40327','樊川寒食二首 一','盧延讓','quantangshi','','卷41','寒食权豪尽出行，一川如画雨初晴。
谁家络络游春盛，担入花间轧轧声。','',''),('quantangshi-40328','樊川寒食二首 二','盧延讓','quantangshi','','卷41','鞍马和花总是尘，歌声处处有佳人。
五陵年少麤于事，栲栳量金买断春。','',''),('quantangshi-40329','句','盧延讓','quantangshi','','卷41','只讹些子缘，应耗没多光。
臂鹰健卒悬毡帽，骑马佳人卷画衫。
每过私第邀看鹤，长着公裳送上驴。
名纸毛生五门下，家僮骨立六街中。
云间闹铎骡驼至，雪里残骸虎拽来。
树上谘诹批颊鸟，窗间壁驳叩头虫。
莫欺零落残牙齿，曾吃红绫饼餤来。
渡水蹇驴双耳直，避风羸仆一肩高。
高据襄阳播盛名，问人人道是诗星。
凉雨打低残菡萏，急风吹散小蜻蜓。','',''),('quantangshi-40330','示门生马侍郎胤孙','裴皞','quantangshi','','卷41','宦途最重是文衡，天与愚夫着盛名。
三主礼闱年八十，门生门下见门生。','',''),('quantangshi-40331','赠杜荀鹤','王希羽','quantangshi','','卷41','金榜晓悬生世日，玉书潜记上升时。
九华山色高千尺，未必高于第八枝。','',''),('quantangshi-40332','宫怨二首 一','柯崇','quantangshi','','卷41','尘满金炉不炷香，黄昏独自立重廊。
笙歌何处承恩宠，一一随风入上阳。','',''),('quantangshi-40333','宫怨二首 二','柯崇','quantangshi','','卷41','长门槐柳半萧疎，玉辇沈思恨有余。
红泪渐消倾国态，黄金谁为达相如。','',''),('quantangshi-40334','早春池亭独游三首 一','劉象','quantangshi','','卷41','春意送残腊，春晴融小洲。
蒲茸才簇岸，柳颊已遮楼。
便有杯觞兴，可摅羁旅愁。
凫鹥亦相狎，尽日戏清流。','',''),('quantangshi-40335','早春池亭独游三首 二','劉象','quantangshi','','卷41','清流环绿筱，清景媚虹桥。
莺刷初迁羽，莎拳拟拆苗。
细沙擢暖岸，淑景动和飙。
倍忆同袍侣，相欢倒一瓢。','',''),('quantangshi-40336','早春池亭独游三首 三','劉象','quantangshi','','卷41','一瓢欢自足，一日兴偏多。
幽意人先赏，疎丛蝶未过。
知音新句苦，窥沼醉颜酡。
万虑从相拟，今朝欲奈何。','',''),('quantangshi-40337','鹭鸶','劉象','quantangshi','','卷41','洁白孤高生不同，顶丝清软冷摇风。
窥鱼翘立荷香里，慕侣低翻柳影中。
几日下巢辞紫阁，多时凝目向晴空。
摩霄志在潜修羽，会接銮凰别苇丛。','',''),('quantangshi-40338','春夜二首 一','劉象','quantangshi','','卷41','几处兵戈阻路岐，忆山心切与山违。
时难何处披怀抱，日日日斜空醉归。','',''),('quantangshi-40339','春夜二首 二','劉象','quantangshi','','卷41','一别杜陵归未期，秪凭魂梦接亲知。
近来欲睡兼难睡，夜夜夜深闻子规。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-40340','晓登迎春阁','劉象','quantangshi','','卷41','未栉凭栏眺锦城，烟笼万井二江明。
香风满阁花盈户，树树树梢啼晓莺。','',''),('quantangshi-40341','咏仙掌','劉象','quantangshi','','卷41','万古亭亭倚碧霄，不成擎亦不成招。
何如掬取天池水，洒向人间救旱苗。','',''),('quantangshi-40342','郪中感旧','劉象','quantangshi','','卷41','顷年曾住此中来，今日重游事可哀。
忆得几家欢宴处，家家家业尽成灰。','',''),('quantangshi-40343','白髭','劉象','quantangshi','','卷41','到处逢人求至药，几回染了又成丝。
素丝易染髭难染，墨翟当时合泣髭。','',''),('quantangshi-40344','题县令范传真化洽亭','沈顏','quantangshi','','卷41','前有浅山，屹然如屏。
后有卑岭，缭然如城。
跨池左右，足以建亭。
斯亭何名，化洽而成。','',''),('quantangshi-40345','书怀寄友人','沈顏','quantangshi','','卷41','江湖劳遍寻，祗自长愁襟。
到处慵开口，何人可话心。
登楼得句远，望月抒情深。
却忆山斋后，猿声相伴吟。','',''),('quantangshi-40346','题壁','楊凝式','quantangshi','','卷41','院似禅心静，花如觉性圆。
自然知了义，争肯学神仙。','',''),('quantangshi-40347','赠张全义','楊凝式','quantangshi','','卷41','洛阳风景实堪哀，昔日曾为瓦子堆。
不是我公重葺理，至今犹是一堆灰。','',''),('quantangshi-40348','题怀素酒狂贴后','楊凝式','quantangshi','','卷41','十年挥素学临池，始识王公学卫非。
草圣未须因酒发，笔端应解化龙飞。','',''),('quantangshi-40349','句','楊凝式','quantangshi','','卷41','押引蝗虫到洛京，合消郡守远相迎。
到此今经三纪春。','',''),('quantangshi-40350','奉试诏用拓拔思恭为京北收复都统','李琪','quantangshi','','卷41','飞骑经巴栈，鸿恩及夏台。
将从天上去，人自日边来。
此处金门远，何时玉辇回。
早平关右贼，莫待诏书催。','',''),('quantangshi-40351','题广爱寺楞伽山','李琪','quantangshi','','卷41','善高天外远，方丈海中遥。
自有山神护，应无劫火烧。
坏文侵古壁，飞剑出寒霄。
何似苍苍色，严妆十七朝。','',''),('quantangshi-40352','句','李琪','quantangshi','','卷41','哀痛不下诏，登封谁上书。','',''),('quantangshi-40353','寄桂帅','劉崇龜','quantangshi','','卷41','碧幢仁施合洪钧，桂树林前倍得春。
莫恋此时好风景，磻溪不是钓渔人。','',''),('quantangshi-40354','席上吟','劉崇魯','quantangshi','','卷41','南行忽见李深之，手舞如蜚令不疑。
任有风流兼蕴藉，天生不似郑都知。','',''),('quantangshi-40355','寄孙储','孫定','quantangshi','','卷41','行行血泪洒尘襟，事逐东流渭水深。
秋跨蹇驴风尚紧，静投孤店日初沈。
一枝犹挂东堂梦，千里空驰北巷心。
明月悲歌又前去，满城烟树噪春禽。','',''),('quantangshi-40356','江南行','許晝','quantangshi','','卷41','江南萧洒地，本自与君宜。
固节还同我，虚心欲待谁。
涧泉傍借响，山木共含滋。
粉腻虫难篆，丛疎鸟易窥。
尽应逢野渡，中忽见村祠。
叶扫秋空静，根横古堑危。
影迷寒霭里，声出夜风时。
客棹深深过，人家远远移。
游边曾结念，到此数题诗。
莫恨成龙晚，成龙会有期。','',''),('quantangshi-40357','中秋月','許晝','quantangshi','','卷41','应是蟾宫别有情，每逢秋半倍澄清。
清光不向此中见，白发争教何处生？
闲地占将真可惜，幽窗分得始为明。
殷勤好长来年桂，莫遣平人道不平。','',''),('quantangshi-40358','临终诗','薛凖','quantangshi','','卷41','旧国深恩不易酬，又离继母出他州。
谁知天怒无因息，积愧终身乞速休。','',''),('quantangshi-40359','观修处士画桃花图歌','裴諧','quantangshi','','卷41','一从天宝王维死，于今始遇修夫子。
能向鲛绡四幅中，丹青暗与春争工。
勾芒若见应羞杀，晕绿匀红渐分别。
堪怜彩笔似东风，一朵一枝随手发。
燕支乍湿如含露，引得娇莺痴不去。
多少游蜂尽日飞，看遍花心求入处。
工夫妙丽实奇绝，似对韶光好时节。
偏宜留着待深冬，铺向楼前殛霜雪。','',''),('quantangshi-40360','句','裴諧','quantangshi','','卷41','风回山火断，朝落岸冰高。
名终埋不得，骨任朽何妨。','',''),('quantangshi-40361','长安春日','曹松','quantangshi','','卷41','浩浩看花晨，六街扬远尘。
尘中一丈日，谁是晏眠人。
御柳舞着水，野鸎啼破春。
徒云多失意，犹自惜离秦。','',''),('quantangshi-40362','慈恩寺贻楚霄上人','曹松','quantangshi','','卷41','在秦生楚思，波浪接禅关。
塔碍高林鸟，窗开白日山。
树阴移草上，岸色透庭间。
入内谈经彻，空携讲疏还。','',''),('quantangshi-40363','崇义里言怀','曹松','quantangshi','','卷41','马蹄京洛岐，复此少闲时。
老积沧洲梦，秋乖白阁期。
平生五字句，一夕满头丝。
把向侯门去，侯门未可知。','',''),('quantangshi-40364','僧院松','曹松','quantangshi','','卷41','此木韵弥全，秋霄学瑟弦。
空知百余尺，未定几多年。
古甲磨云拆，孤根捉地坚。
何当抛一干，作盖道场前。','',''),('quantangshi-40365','贻世','曹松','quantangshi','','卷41','富者非义取，朴风争肯还。
红尘不待晓，白首有谁闲。
浅度四溟水，平看诸国山。
只消年作劫，俱到总无间。','',''),('quantangshi-40366','南游','曹松','quantangshi','','卷41','直到南箕下，方谙涨海头。
君恩过铜柱，戎节限交州。
犀占花阴卧，波冲瘴色流。
远夷非不乐，自是北人愁。','',''),('quantangshi-40367','送胡中丞使日东','曹松','quantangshi','','卷41','辞天理玉簪，指日使鸡林。
犹有中华恋，方同积浪深。
张帆度鲸口，衔命见臣心。
渥泽遐宣后，归期抵万金。','',''),('quantangshi-40368','哭陈陶处士','曹松','quantangshi','','卷41','园里先生冢，鸟啼春更伤。
空余八封树，尚对一茅堂。
白日埋杜甫，皇天无耒阳。
如何稽古力，报答甚茫茫。','',''),('quantangshi-40369','言怀','曹松','quantangshi','','卷41','冥心坐似痴，寝食亦如遗。
为觅出人句，秪求当路知。
岂能穷到老，未信达无时。
此道须天付，三光幸不私。','',''),('quantangshi-40370','月','曹松','quantangshi','','卷41','寥寥天地内，夜魄爽何轻。
频见此轮满，即应华发生。
不圆争得破，才正又须倾。
人事还如此，因知倚伏情。','',''),('quantangshi-40371','答匡山僧赠榔栗杖','曹松','quantangshi','','卷41','栗杖出匡顶，百中无一枝。
虽因野僧得，犹畏岳神知。
画月冷光在，指云秋片移。
宜留引蹇步，他日访峨嵋。','',''),('quantangshi-40372','商山夜闻泉','曹松','quantangshi','','卷41','泻月声不断，坐来心益闲。
无人知落处，万木冷空山。
远忆云容外，幽疑石缝间。
那辞通曙听，明日度蓝关。','',''),('quantangshi-40373','书怀','曹松','quantangshi','','卷41','默默守吾道，望荣来替愁。
吟诗应有罪，当路却如讐。
陆海傥难溺，九霄争便休。
敢言名誉出，天未白吾头。','',''),('quantangshi-40374','道中','曹松','quantangshi','','卷41','出门嗟世路，何日朴风归。
是处太行险，□□应解飞。
主人厚薄礼，客子新故衣。
所以浇浮态，多令行者违。','',''),('quantangshi-40375','夏云','曹松','quantangshi','','卷41','势能成岳仞，顷刻长崔嵬。
瞑鸟飞不到，野风吹得开。
一天分万态，立地看忘回。
欲结暑宵雨，先闻江上雷。','',''),('quantangshi-40376','塞上行','曹松','quantangshi','','卷41','上将拥黄须，安西逐指呼。
离乡俱少壮，到碛减肌肤。
风雪夜防塞，腥膻朝系胡。
为君乐战死，谁喜作征夫。','',''),('quantangshi-40377','晨起','曹松','quantangshi','','卷41','晓色教不睡，卷帘清气中。
林残数枝月，发冷一梳风。
竝鸟含钟语，欹荷隔雾空。
莫疑营白日，道路本无穷。','',''),('quantangshi-40378','感世','曹松','quantangshi','','卷41','触目尽如幻，幻中能几时。
愁来舍行乐，事去莫吞悲。
白发不由己，黄金留待谁。
耕烟得铭志，翻为古人思。','',''),('quantangshi-40379','观华夷图','曹松','quantangshi','','卷41','落笔胜缩地，展图当晏宁。
中华属贵分，远裔占何星。
分寸辨诸岳，斗升观四溟。
长疑未到处，一一似曾经。','',''),('quantangshi-40380','山上寒夜呈进士许棠','曹松','quantangshi','','卷41','山寒草堂暖，寂夜有良朋。
读易分高烛，煎茶取折冰。
庭垂河半角，窗露月微棱。
俱入论心地，争无俗者憎。','',''),('quantangshi-40381','滕王阁春日晚眺','曹松','quantangshi','','卷41','凌春帝子阁，偶眺日移西。
浪势平花坞，帆阴上柳堤。
凝岚藏宿翼，叠鼓碎归蹄。
只此长吟咏，因高思不迷。','',''),('quantangshi-40382','钟陵野步','曹松','quantangshi','','卷41','冈扉聊自启，信步出波边。
野火风吹阔，春冰鹤啄穿。
渚樯齐驿树，山鸟入公田。
未创孤云势，空思白阁年。','',''),('quantangshi-40383','哭胡处士','曹松','quantangshi','','卷41','故人江阁在，重到事悠悠。
无尔向潭上，为吾倾瓮头。
空余赤枫叶，堕落钓鱼舟。
疑是冲虚去，不为天地囚。','',''),('quantangshi-40384','青龙寺赠云颢法师','曹松','quantangshi','','卷41','紫檀衣且香，春殿日尤长。
此地开新讲，何山鏁旧房。
僧名喧北阙，师印续南方。
莫惜青莲喻，秦人听未忘。','',''),('quantangshi-40385','荐福寺赠应制白公','曹松','quantangshi','','卷41','才子紫檀衣，明君宠顾时。
讲升高座懒，书答重臣迟。
瓶势倾圆顶，刀声落碎髭。
还闻穿内去，随驾进新诗。','',''),('quantangshi-40386','观山寺僧穿井','曹松','quantangshi','','卷41','云僧凿山井，寒碧在中庭。
况是分嵓眼，同来下石瓶。
旁痕终变藓，圆影即澄星。
异夜天龙蛰，应闻说叶经。','',''),('quantangshi-40387','送德光禅师','曹松','quantangshi','','卷41','天涯缘事了，又造石霜微。
不以千峰险，唯将独影归。
有为嫌假佛，无境是真机。
到后流沙锡，何时更有飞。','',''),('quantangshi-40388','赠南陵李主簿','曹松','quantangshi','','卷41','外邑官同隐，宁劳短吏趋。
看云情自足，爱酒逸应无。
簟席弹碁子，衣裳惹印朱。
仍闻陂水近，亦拟掉菰蒲。','',''),('quantangshi-40389','慈恩寺东楼','曹松','quantangshi','','卷41','寺楼凉出竹，非与曲江赊。
野火流穿苑，秦山叠入巴。
风梢离众叶，岸角积虚沙。
此地钟声近，令人思未涯。','',''),('quantangshi-40390','古冢','曹松','quantangshi','','卷41','代远已难问，累累次古城。
民田侵不尽，客路踏还平。
作穴蛇分蛰，依冈鹿绕行。
唯应风雨夕，鬼火出林明。','',''),('quantangshi-40391','访山友','曹松','quantangshi','','卷41','一迳通高屋，重云翳两原。
山寒初宿顶，泉落未知根。
急雨洗荒壁，惊风开静门。
听君吟废夜，苦却建溪猿。','',''),('quantangshi-40392','林下书怀寄建州李频员外','曹松','quantangshi','','卷41','一从诸事嬾，海上迹宜沉。
吾道不当路，鄙人甘入林。
云垂方觅鹤，月湿始收琴。
水石南州好，谁陪刻骨吟。','',''),('quantangshi-40393','猿','曹松','quantangshi','','卷41','曾宿三巴路，今来不愿听。
云根啼片白，峰顶掷尖青。
护果憎禽啄，栖霜觑叶零。
唯应卧岚客，怜尔傍岩扃。','',''),('quantangshi-40394','秋日送方干游上元','曹松','quantangshi','','卷41','天高淮泗白，料子趋修程。
汲水疑山动，扬帆觉岸行。
云离京口树，雁入石头城。
后夜分遥念，诸峰霜露生。','',''),('quantangshi-40395','哭李频员外','曹松','quantangshi','','卷41','出麾临建水，下世在公堂。
苦集休开箧，清资罢转郎。
瘴中无子奠，岭外一妻孀。
定是浮香骨，东归就故乡。','',''),('quantangshi-40396','山中言事','曹松','quantangshi','','卷41','岚霭润窗棂，吟诗得冷症。
教餐有效药，多愧独行僧。
云湿煎茶火，冰封汲井绳。
片扉深着掩，经国自无能。','',''),('quantangshi-40397','送左协律京西从事','曹松','quantangshi','','卷41','辟书来几日，遂喜就嘉招。
犹向风沙浅，非于甸服遥。
时平无探骑，秋静见盘雕。
若遣关中使，烦君问寂寥。','',''),('quantangshi-40398','望九华寄池阳太守','曹松','quantangshi','','卷41','造化峰峰异，宜教岳德谦。
灵踪载籍古，怪刃刺云尖。
盘蹙陵阳壮，孤标建邺瞻。
霁余堪洗目，青出谢家檐。','',''),('quantangshi-40399','上广州支使王拾遗','曹松','quantangshi','','卷41','明时应不谏，天幕称仙才。
聘入关中去，人从帝侧来。
诗窗盛岛屿，檄盾照风雷。
几度陪旄节，营巡海色回。','',''),('quantangshi-40400','题僧松禅','曹松','quantangshi','','卷41','空山涧畔枯松树，禅老堂头甲乙身。
传是昔朝僧种着，下头应有茯苓神。','',''),('quantangshi-40401','赠华阴李明府','曹松','quantangshi','','卷41','佩墨县兼清，约关西近城。
三峰岂不重，厚地戴犹轻。
雪筱欹难直，风泉喷易横。
须知高枕外，长是劝民耕。','',''),('quantangshi-40402','送人庭鹤','曹松','quantangshi','','卷41','度岁休笼闭，身轻好羽仪。
白云□是伴，沧海得因谁。
唳起遗残食，盘余在逈枝。
条风频雨去，只恐更相随。','',''),('quantangshi-40403','信州闻通寺题僧砌下泉','曹松','quantangshi','','卷41','细声从峤足，幽淡浸香墀。
此境未开日，何人初见时。
耗痕延黑藓，净罅吐微澌。
应有乔梢鹤，下来当饮之。','',''),('quantangshi-40404','山中','曹松','quantangshi','','卷41','此地似商岭，云霞空往还。
衰条难定鸟，缺月易依山。
野色耕不尽，溪容钓自闲。
分因多卧退，百计少相关。','',''),('quantangshi-40405','寄崇圣寺僧','曹松','quantangshi','','卷41','不醉长安酒，冥心只似师。
望山吟过日，伴鹤立多时。
沟远流声细，林寒绿色迟。
庵西萝月夕，重约语空期。','',''),('quantangshi-40406','金陵道中寄','曹松','quantangshi','','卷41','忍苦待知音，无时省废吟。
始为分路客，莫问向隅心。
峤翠藏幽瀑，枝风下晓禽。
忆君秋欲尽，马上秣陵砧。','',''),('quantangshi-40407','都门送许棠东归','曹松','quantangshi','','卷41','旧客东归远，长安诗少朋。
去愁分碛雁，行计逐乡僧。
华岳无时雪，黄河漫处冰。
知辞国门路，片席认西陵。','',''),('quantangshi-40408','送进士喻坦之游太原','曹松','quantangshi','','卷41','北鄙征难尽，诗愁满去程。
废巢侵烧色，荒冢入锄声。
逗野河流浊，离云碛日明。
并州戎垒地，角动引风生。','',''),('quantangshi-40409','九江暮春书事','曹松','quantangshi','','卷41','杨柳城初鏁，轮蹄息去踪。
春流无旧岸，夜色失诸峰。
影动渔边火，声迟话后钟。
明朝廻去雁，谁向北郊逢。','',''),('quantangshi-40410','再到洪州望西山','曹松','quantangshi','','卷41','洪州向西顾，不忍暂忘君。
记得瀑泉落，省同幽鸟闻。
一廻经雨雹，长有剩风云。
未定却栖息，前头江海分。','',''),('quantangshi-40411','与胡汾坐月期贯休上人不至','曹松','quantangshi','','卷41','扫庭秋漏滴，接话贵忘眠。
静夜人相语，低枝鸟暗迁。
星围南极定，月照断河连。
后会花宫子，应开石上禅。','',''),('quantangshi-40412','赠胡处士','曹松','quantangshi','','卷41','年光离岳色，带疾卧南原。
白日与无事，俗人嗔闭门。
樵鱼临片水，野鹿入荒园。
莫问荣华事，清霜点发根。','',''),('quantangshi-40413','铅山写怀','曹松','quantangshi','','卷41','天涯兵火后，风景畏临门。
骨肉到时节，团圆因梦魂。
池塘营水眼，岭峤结花根。
耳纵听歌吹，中心不可论。','',''),('quantangshi-40414','书翠岩寺壁','曹松','quantangshi','','卷41','何年话尊宿，瞻礼此堂中。
入郭非无路，归林自学空。
溅瓶云峤水，逆磬雪川风。
时说南庐事，知师用意同。','',''),('quantangshi-40415','江西题东湖','曹松','quantangshi','','卷41','凿出江湖思，凉多□□间。
无风触微浪，半日□秋山。
客袖沙光满，船窗荻影闲。
时人见黄绶，应笑狎鸥还。','',''),('quantangshi-40416','题湖南岳麓寺','曹松','quantangshi','','卷41','海云山上寺，每到每开襟。
万木长不住，细泉听更深。
蜩沾高雨断，鸟遇夕岚沈。
此地良宵月，秋怀隔楚砧。','',''),('quantangshi-40417','赠衡山麋明府','曹松','quantangshi','','卷41','为县潇湘水，门前树配苔。
晚吟公籍少，春醉积林开。
涤砚松香起，擎茶岳影来。
任官当此境，更莫梦天台。','',''),('quantangshi-40418','塞上','曹松','quantangshi','','卷41','边寒来所阔，今日复明朝。
河凌坚通马，胡云缺见雕。
砂中程独泣，乡外隐谁招。
廻首若经岁，灵州生柳条。','',''),('quantangshi-40419','送邵安石及第归连州觐省','曹松','quantangshi','','卷41','及第兼归觐，宜忘涉驿劳。
青云重庆少，白日一飞高。
转楚闻啼狖，临湘见叠涛。
海阳沈饮罢，何地佐旌旄。','',''),('quantangshi-40420','边上送友人归宁','曹松','quantangshi','','卷41','乡路穿京过，宁心去少同。
日斜寻阔碛，春尽逐归鸿。
独树河声外，凝笳塞色中。
怜君到此处，却背老莱风。','',''),('quantangshi-40421','除夜','曹松','quantangshi','','卷41','残腊即又尽，东风应渐闻。
一宵犹几许，两岁欲平分。
燎暗倾时斗，春通绽处芬。
明朝遥捧酒，先合祝尧君。','',''),('quantangshi-40422','题甘露寺','曹松','quantangshi','','卷41','香门接巨垒，画角间清钟。
北固一何峭，西僧多此逢。
天垂无际海，云白久晴峰。
旦暮然灯外，涛头振蛰龙。','',''),('quantangshi-40423','贻住山僧','曹松','quantangshi','','卷41','罢讲巡岩坞，无穷得野情。
腊高犹伴鹿，夏满不归城。
云朵缘崖发，峰阴截水清。
自然双洗耳，唯任白毫生。','',''),('quantangshi-40424','题鹤鸣泉','曹松','quantangshi','','卷41','仙鹤曾鸣处，泉兼半井苔。
直峰抛影入，片月泻光来。
潋滟侵颜冷，深沉慰眼开。
何因值舟顶，满汲石瓶廻。','',''),('quantangshi-40425','吊贾岛二首 一','曹松','quantangshi','','卷41','先生不折桂，谪去抱何冤。
已葬离燕骨，难招入劒魂。
旅坟低却草，稚子哭胜猿。
冥寞如搜句，宜邀贺监论。','',''),('quantangshi-40426','吊贾岛二首 二','曹松','quantangshi','','卷41','青斾低寒水，清笳出晓风。
鸟来伤贾傅，马立葬滕公。
松柏青山上，城池白日中。
一朝今古隔，惟有月明同。','',''),('quantangshi-40427','忆江西并悼亡友','曹松','quantangshi','','卷41','前心奈兵阻，悔作豫章分。
芳草未归日，故人多是坟。
帆行出岫雨，马践过江云。
此地一罇酒，当时皆以文。','',''),('quantangshi-40428','九江送方干归镜湖','曹松','quantangshi','','卷41','一樯悬五两，此日动归风。
客路抛湓口，家林入镜中。
谭余云出峤，咏苦月欹空。
更若看鳷鹊，何人夜坐同。','',''),('quantangshi-40429','庐山访贾匡','曹松','quantangshi','','卷41','西城疾病日，此地少寻君。
古迹春犹在，遥泉夜尽闻。
片时三处雨，九叠几重云。
到者皆忘寐，神精与俗分。','',''),('quantangshi-40430','顾少府池上','曹松','quantangshi','','卷41','池上分行种，公庭觉少尘。
根离潮水岸，韵爽判曹人。
正午廻鱼影，方昏息鹭身。
无时不动咏，沧岛思方频。','',''),('quantangshi-40431','喜友人归上元别业','曹松','quantangshi','','卷41','一樯千里外，隐者兴宜孤。
落日长边海，秋风满故都。
掩关苔色老，盘迳叶声枯。
匡岳来时过，迟廻绝顶无。','',''),('quantangshi-40432','曲江暮春雪霁','曹松','quantangshi','','卷41','霁动江池色，春残一去游。
菰风生马足，槐雪滴人头。
北阙尘未起，南山青欲流。
如何多别地，却得醉汀洲。','',''),('quantangshi-40433','立春日','曹松','quantangshi','','卷41','春饮一杯酒，便吟春日诗。
木梢寒未觉，地脉暖先知。
鸟啭星沈后，山分雪薄时。
赏心无处说，怅望曲江池。','',''),('quantangshi-40434','宿溪僧院','曹松','quantangshi','','卷41','少年云溪里，禅心夜更闲。
煎茶留静者，靠月坐苍山。
露白钟寻定，萤多户未关。
嵩阳大石室，何日译经还。','',''),('quantangshi-40435','石头怀古','曹松','quantangshi','','卷41','日月出又没，台城空白云。
虽宽百姓土，渐缺六朝坟。
禾黍是亡国，山河归圣君。
松声骤雨足，几寺晚钟闻。','',''),('quantangshi-40436','浙右赠陆处士','曹松','quantangshi','','卷41','静节灌园余，得非成隐居。
长当庚子日，独拜五经书。
白浪吹亡国，秋霜洗大虚。
门前是京口，身外不营储。','',''),('quantangshi-40437','哭胡处士','曹松','quantangshi','','卷41','丘中久不起，将谓诏书来。
及见凌云说，方知掩夜台。
白衣归北路，玄造亦遗才。
世上亡君后，诗声更大哉。','',''),('quantangshi-40438','赠余干袁明府','曹松','quantangshi','','卷41','一雨西城色，陶家心自清。
山衔中郭分，云卷下湖程。
公署闻流木，人烟入废城。
难忘楚尽处，新有越吟生。','',''),('quantangshi-40439','赠雷乡张明府','曹松','quantangshi','','卷41','任官征战后，度日寄闲身。
封卷还高客，飞书问野人。
废田教种糓，生路遣寻薪。
若起柴桑兴，无先漉酒巾。','',''),('quantangshi-40440','岳阳晚泊','曹松','quantangshi','','卷41','轻帆下阔流，便泊此沙洲。
湖影撼山朵，日阳烧野愁。
白波争起倒，青屿或沈浮。
是际船中望，东南仞仞秋。','',''),('quantangshi-40441','览春牓喜孙鄠成名','曹松','quantangshi','','卷41','门外报春牓，喜君天子知。
旧愁浑似雪，见日总消时。
塔下牡丹气，江头杨柳丝。
风光若有分，无处不相宜。','',''),('quantangshi-40442','己亥岁二首 一','曹松','quantangshi','','卷41','泽国江山入战图，生民何计乐樵苏。
凭君莫话封侯事，一将功成万骨枯。','',''),('quantangshi-40443','己亥岁二首 二','曹松','quantangshi','','卷41','传闻一战百神愁，两岸彊兵过未休。
谁道沧江总无事，近来长共血争流。','',''),('quantangshi-40444','乱后入洪州西山','曹松','quantangshi','','卷41','寂寂阴溪水漱苔，尘中将得苦吟来。
东峰道士如相问，县令而今不姓梅。','',''),('quantangshi-40445','送僧入庐山','曹松','quantangshi','','卷41','若到江州二林寺，遍游应未出云霞。
庐山瀑布三千仞，画破青霄始落斜。','',''),('quantangshi-40446','送僧入蜀过夏','曹松','quantangshi','','卷41','师言结夏入巴峰，云水廻头几万重。
五月峨眉须近火，木皮领重只如冬。','',''),('quantangshi-40447','江西逢僧省文 一','曹松','quantangshi','','卷41','闽地高僧楚地逢，僧游蛮锡挂垂松。
白云逸性都无定，才出双峰爱五峰。','',''),('quantangshi-40448','江西逢僧省文 二','曹松','quantangshi','','卷41','高僧不负雪峰期，却伴青霞入翠微。
百叶岩前霜欲降，九枝松上鹤初归。
风生碧涧鱼龙跃，威振金楼燕雀飞。
想得白莲花上月，满山犹带旧光辉。','',''),('quantangshi-40449','水精念珠','曹松','quantangshi','','卷41','等量红缕贯晶荧，尽道匀圆别未胜。
凿断玉潭盈尺水，琢成金地两条冰。
轮时秪恐星侵佛，挂处常疑露滴僧。
几度夜深寻不着，瑠[瓈]为殿月为灯。','',''),('quantangshi-40450','南海旅次','曹松','quantangshi','','卷41','忆归休上越王台，归思临高不易裁。
为客正当无雁处，故园谁道有书来。
城头早角吹霜尽，郭里残潮荡月回。
心似百花开未得，年年争发被春催。','',''),('quantangshi-40451','春草','曹松','quantangshi','','卷41','不独满池塘，梦中佳句香。
春风有余力，引上古城墙。','',''),('quantangshi-40452','金谷园','曹松','quantangshi','','卷41','当年歌舞时，不说草离离。
今日歌舞尽，满园秋露垂。','',''),('quantangshi-40453','夏日东斋','曹松','quantangshi','','卷41','三庚到秋伏，偶来松槛立。
热少清风多，开门放山入。','',''),('quantangshi-40454','南朝','曹松','quantangshi','','卷41','三篱盖驰道，风烈一无取。
时见牧牛童，嗔牛吃禾黍。','',''),('quantangshi-40455','言怀','曹松','quantangshi','','卷41','出山不得意，谒帝值戈鋋。
岂料为文日，翻成用武年。','',''),('quantangshi-40456','寒食日题杜鹃花','曹松','quantangshi','','卷41','一朵又一朵，并开寒食时。
谁家不禁火，总在此花枝。','',''),('quantangshi-40457','钟陵寒食日郊外闲游','曹松','quantangshi','','卷41','可怜时节足风情，杏子粥香如冷饧。
无奈春风输旧火，遍教人唤作山樱。','',''),('quantangshi-40458','中秋对月','曹松','quantangshi','','卷41','无云世界秋三五，共看蟾盘上海涯。
直到天头天尽处，不曾私照一人家。','',''),('quantangshi-40459','陪湖南李中丞宴隐溪','曹松','quantangshi','','卷41','竹林啼鸟不知休，罗列飞桥水乱流。
触散柳丝回玉勒，约开莲叶上兰舟。
酒边旧侣真何逊，云里新声是莫愁。
若值主人嫌昼短，应陪秉烛夜深游。','',''),('quantangshi-40460','别湖上主人','曹松','quantangshi','','卷41','门系钓舟云满岸，借君幽致坐移旬。
湖村夜呌白芜雁，菱市晓喧深浦人。
远水日边重作雪，寒林烧后别生春。
不辞更住醒还醉，太一东峰归梦频。','',''),('quantangshi-40461','赠广宣大师','曹松','quantangshi','','卷41','忆昔同游紫阁云，别来三十二回春。
白头相见双林下，犹是清朝未退人。','',''),('quantangshi-40462','钟陵寒食日与同年裴颜李先辈郑校书郊外闲游','曹松','quantangshi','','卷41','寒节钟陵香骑随，同年相命楚江湄。
云间影过秋千女，地上声喧蹴踘儿。
何处寄烟归草色，谁家送火在花枝。
银瓶冷酒皆倾尽，半卧垂杨自不知。','',''),('quantangshi-40463','江外除夜','曹松','quantangshi','','卷41','千门庭燎照楼台，总为年光急急催。
半夜腊因风卷去，五更春被角吹来。
宁无好鸟思花发，应有游鱼待冻开。
不是多歧渐平稳，谁能呼酒祝昭回。','',''),('quantangshi-40464','七夕','曹松','quantangshi','','卷41','牛女相期七夕秋，相逢俱喜鹊横流。
彤云缥缈廻金辂，明月婵娟挂玉钩。
燕羽几曾添别恨，花容终不更含羞。
更残便是分襟处，晓箭东来射翠楼。','',''),('quantangshi-40465','罗浮山下书逸人壁','曹松','quantangshi','','卷41','海上亭台山下烟，买时幽邃不争钱。
莫言白日催华发，自有丹砂驻少年。
渔钓未归深竹里，琴壶犹恋落花边。
可中更践无人境，知是罗浮第几天。','',''),('quantangshi-40466','天台瀑布','曹松','quantangshi','','卷41','万仞得名云瀑布，远看如织挂天台。
休疑宝尺难量度，直恐金刀易剪裁。
喷向林梢成夏雪，倾来石上作春雷。
欲知便是银河水，堕落人间合却廻。','',''),('quantangshi-40467','桂江','曹松','quantangshi','','卷41','未识佳人寻桂水，水云先解傍壶觞。
笋林次第添斑竹，雏鸟参差护锦囊。
乳洞此时连越井，石楼何日到仙乡。
如飞似堕皆青壁，画手不强元化强。','',''),('quantangshi-40468','南海','曹松','quantangshi','','卷41','倾腾界汉沃诸蛮，立望何如画此看。
无地不同方觉远，共天无别始知宽。
文魮隔雾朝含碧，老蚌凌波夜吐丹。
万状千形皆得意，长鲸独自转身难。','',''),('quantangshi-40469','洞庭湖','曹松','quantangshi','','卷41','东西南北各连空，波上唯留小朵峰。
长与岳阳翻鼓角，不离云梦转鱼龙。
吸廻日月过千顷，铺尽星河剩一重。
直到劫余还作陆，是时应有羽人逢。','',''),('quantangshi-40470','霍山','曹松','quantangshi','','卷41','七千七百七十丈，丈丈藤萝势入天。
未必展来空似翅，不妨开去也成莲。
月将河汉分岩转，僧与龙蛇共窟眠。
直是画工须阁笔，况无名画可流传。','',''),('quantangshi-40471','巫峡','曹松','quantangshi','','卷41','巫山苍翠峡通津，下有仙宫楚女真。
不逐彩云归碧落，却为暮雨扑行人。
年年旧事音容在，日日谁家梦想频。
应是荆山留不住，至今犹得覩芳尘。','',''),('quantangshi-40472','送陈樵校书归泉州','曹松','quantangshi','','卷41','巨塔列名题，诗心亦罕齐。
除官京下阙，乞假海门西。
别席侵残漏，归程避战鼙。
关遥秦雁断，家近瘴云低。
候马春风馆，迎船晓月溪。
帝京须早入，莫被刺桐迷。','',''),('quantangshi-40473','赠镜湖处士方干二首 一','曹松','quantangshi','','卷41','包含教化剩搜罗，句出东瓯奈峭何。
世路不妨平处少，才人唯是屈声多。
云来岛上便幽石，月到湖心忌白波。
后辈难为措机杼，先生织字得龙梭。','',''),('quantangshi-40474','赠镜湖处士方干二首 二','曹松','quantangshi','','卷41','秪拟应星眠越绝，唯将丽什当高勋。
磨砻清浊人难会，织络虚无帝亦闻。
鸟道未知山足雨，渔家已没镜中云。
他时莫为三徴起，门外沙鸥解笑君。','',''),('quantangshi-40475','拜访陆处士','曹松','quantangshi','','卷41','万卷书边人半白，再来惟恐降玄纁。
性灵比鹤争多少，气力登山较几分。
吟鬓渐无前度漆，寝衣犹有昨宵云。
将知谷口耕烟者，低视齐梁楚赵君。','',''),('quantangshi-40476','岭南道中','曹松','quantangshi','','卷41','百花成实未成归，未必归心与志违。
但有壶觞资逸咏，尽交风景入清机。
半川阴雾藏高木，一道晴霓杂落晖。
游子马前芳草合，鹧鸪啼歇又南飞。','',''),('quantangshi-40477','春日自吴门之阳羡道中书事','曹松','quantangshi','','卷41','胜异恣游应未遍，路岐犹去几时还。
浪花湖阔虹霓断，柳线村深鸟雀闲。
千室绮罗浮画檝，两州丝竹会茶山。
眼前便是神仙事，何必须言洞府间。','',''),('quantangshi-40478','将入关行次湘阴','曹松','quantangshi','','卷41','背顾秦城在何处，图书作伴过湘东。
神鵶乱噪黄陵近，候雁斜沈梦泽空。
打桨天连晴水白，烧田云隔夜山红。
也知渐老岩栖稳，争奈文闱有至公。','',''),('quantangshi-40479','题昭州山寺常寂上人水阁','曹松','quantangshi','','卷41','常寂常居常寂里，年年月月是空空。
堦前未放岩根断，屋下长教海眼通。
本为入来寻佛窟，不期行处踏龙宫。
他时忆着堪图画，一朵云山二水中。','',''),('quantangshi-40480','广州贻匡绪法师','曹松','quantangshi','','卷41','口宣微密不思议，不是除贪即诫痴。
祗待外方缘了日，争看内殿诏来时。
周廻海树侵阶疾，迢递江潮应井迟。
必竟懒过高坐寺，未能全让法云师。','',''),('quantangshi-40481','赠道人','曹松','quantangshi','','卷41','住山因以福为庭，便向山中隐姓名。
阆苑驾将雕羽去，洞天赢得绿毛生。
日边肠胃餐霞火，月里肌肤饮露英。
顾我从来断浮浊，拟驱鸡犬上三清。','',''),('quantangshi-40482','送乞雨禅师临遇南游','曹松','quantangshi','','卷41','活得枯樵耕者知，巡方又欲向天涯。
珠穿闽国菩提子，杖把灵峰榔栗枝。
春藓任封降虎石，夜雷从傍养龙池。
生缘在地南浮去，自此孤云不可期。','',''),('quantangshi-40483','南海陪郑司空游荔园','曹松','quantangshi','','卷41','荔枝时节出旌斿，南国名园尽兴游。
乱结罗纹照襟袖，别含琼露爽咽喉。
叶中新火欺寒食，树上丹砂胜锦州。
他日为霖不将去，也须图画取风流。','',''),('quantangshi-40484','李郎中林亭','曹松','quantangshi','','卷41','秪向砌边流野水，樽前上下看鱼儿。
笋蹊已长过人竹，藤径从添拂面丝。
若许白猿垂近户，即无红果压低枝。
大才必拟逍遥去，更遣何人佐盛时。','',''),('quantangshi-40485','夜饮','曹松','quantangshi','','卷41','良宵公子宴兰堂，浓麝薰人兽吐香。
云带金龙衔画烛，星罗银凤泻琼浆。
满屏珠树开春景，一曲歌声遶翠梁。
席上未知帘幕晓，青娥低语指东方。','',''),('quantangshi-40486','驸马宅宴罢','曹松','quantangshi','','卷41','粉墙残月照宫祠，宴阕银瓶一半欹。
学语鸎儿飞未稳，放身斜坠绿杨枝。','',''),('quantangshi-40487','吊建州李员外','曹松','quantangshi','','卷41','铭旌归故里，猿鸟亦凄然。
已葬桐江月，空廻建水船。
客传为郡日，僧说读书年。
恐有吟魂在，深山古木边。','',''),('quantangshi-40488','吊李翰林','曹松','quantangshi','','卷41','李白虽然成异物，逸名犹与万方传。
昔朝曾侍玄宗侧，大夜应归贺监边。
山木易高迷故壠，国风长在见遗篇。
投金渚畔春杨柳，自此何人系酒船。','',''),('quantangshi-40489','山中','曹松','quantangshi','','卷41','要路豪家非往还，岩门先有不曾关。
众心惟恐地无剩，吾意亦忧天惜闲。
白练曳泉窗下石，绛罗垂果枕前山。
樵夫岂解营生业，贵欲自安麋鹿间。','',''),('quantangshi-40490','山寺引泉','曹松','quantangshi','','卷41','劈碎琅玕意有余，细泉高引入香厨。
山僧未肯言根本，莫是银河漏泄无。','',''),('quantangshi-40491','友人池上咏芦','曹松','quantangshi','','卷41','秋声谁种得，萧瑟在池栏。
叶涩栖蝉稳，丛疎宿鹭难。
歛烟宜下□，飒吹省先寒。
此物生苍岛，令人忆钓竿。','',''),('quantangshi-40492','商山','曹松','quantangshi','','卷41','垂白商于原下住，儿孙共死一身忙。
木弓未得长离手，犹与官家射麝香。','',''),('quantangshi-40493','荆南道中','曹松','quantangshi','','卷41','十月荒郊雪气催，依稀愁色认阳台。
游秦分系三条烛，出楚心殊一寸灰。
高柳莫遮寒月落，空桑不放夜风廻。
如何住在猿声里，却被蝉吟引下来。','',''),('quantangshi-40494','武德殿朝退望九衢春色','曹松','quantangshi','','卷41','玉殿朝初退，天街一看春。
南山初过雨，北阙净无尘。
夹道夭桃满，连沟御柳新。
苏舒同舜泽，煦妪竝尧仁。
佳气浮轩盖，和风袭缙绅。
自兹怜万物，同入发生辰。','',''),('quantangshi-40495','吊北邙','曹松','quantangshi','','卷41','山下望山上，夕阳看又曛。
无人医白发，少地着新坟。
岁代殊相远，贤愚旋不分。
东归聊一吊，乱木倚寒云。','',''),('quantangshi-40496','及第勅下宴中献座主杜侍郎','曹松','quantangshi','','卷41','得召丘墙泪却频，若无公道也无因。
门前送勅朱衣吏，席上衔杯碧落人。
半夜笙歌教泥月，平明桃杏放烧春。
南山虽有归溪路，争那酬恩未杀身。','',''),('quantangshi-40497','梢云','曹松','quantangshi','','卷41','殊质资灵贶，陵空发瑞云。
梢梢含树影，郁郁动霞文。
不比因风起，全非触石分。
叶光闲泛滟，枝彩静氛氲。
隐见心无宰，裴回庆自君。
翻飞如可托，长愿在横汾。','',''),('quantangshi-40498','白角簟','曹松','quantangshi','','卷41','角簟工夫已到头，夏来全占满牀秋。
若言保惜归华屋，秪合封题寄列侯。
学卷晓冰长怕绽，解铺寒水不教流。
蒲桃锦是潇湘底，曾得王孙价倍酬。','',''),('quantangshi-40499','碧角簟','曹松','quantangshi','','卷41','细皮重叠织霜纹，滑腻铺牀胜锦茵。
八尺碧天无点翳，一方青玉绝纤尘。
蝇行只恐烟黏足，客卧混疑水浸身。
五月不教炎气入，满堂秋色冷龙鳞。','',''),('quantangshi-40500','滕王阁春日晚望','曹松','quantangshi','','卷41','凌春帝子阁，偶眺日移西。
浪势平花坞，帆阴上柳堤。','',''),('quantangshi-40501','句','曹松','quantangshi','','卷41','追游若遇三清乐，行从应妨一日春。
石脉水流泉滴沙，鬼灯然点松柏花。
鹿眠荒圃寒芜白，鸦噪残阳败叶飞。
华岳影寒清露掌，海门风急白潮头。','',''),('quantangshi-40502','颂鲁','蘇拯','quantangshi','','卷41','天推鲁仲尼，周游布典坟。
游遍七十国，不令遇一君。
一国如一遇，单车不转轮。
良由至化力，为国不为身。
礼乐行未足，邅回厄于陈。
礼乐今有余，衮旒当圣人。
伤哉绝粮议，千载误云云。','',''),('quantangshi-40503','医人','蘇拯','quantangshi','','卷41','古人医在心，心正药自真。
今人医在手，手滥药不神。
我愿天地炉，多衔扁鹊身。
遍行君臣药，先从冻馁均。
自然六合内，少闻贫病人。','',''),('quantangshi-40504','西施','蘇拯','quantangshi','','卷41','吴王从骄佚，天产西施出。
岂徒伐一人，所希救羣物。
良由上天意，恶盈戒奢侈。
不独破吴国，不独生越水。
在周名襃姒，在纣名妲己。
变化本多涂，生杀亦如此。
君王政不修，立地生西子。','',''),('quantangshi-40505','金谷园','蘇拯','quantangshi','','卷41','积金累作山，山高小于址。
栽花比绿珠，花落还相似。
徒有敌国富，不能买东市。
徒有绝世容，不能楼上死。
秪此上高楼，何如在平地。','',''),('quantangshi-40506','巫山','蘇拯','quantangshi','','卷41','昔时亦云雨，今时亦云雨。
自是荒淫多，梦得巫山女。
从来圣明君，可听妖魅语。
只今峰上云，徒自生容与。','',''),('quantangshi-40507','贾客','蘇拯','quantangshi','','卷41','长帆挂短舟，所愿疾如箭。
得丧一惊飘，生死无良贱。
不谓天不佑，自是人苟患。
尝言海利深，利深不如浅。','',''),('quantangshi-40508','狡兔行','蘇拯','quantangshi','','卷41','秋来无骨肥，鹰犬遍原野。
草中三穴无处藏，何况平田无穴者。','',''),('quantangshi-40509','长城','蘇拯','quantangshi','','卷41','嬴氏设防胡，烝沙筑冤垒。
蒙公取勋名，岂算生民死。
运畚力不禁，碎身砂碛里。
黔黎欲半空，长城舂未已。
皇天潜鼓怒，力化一女子。
遂使万雉崩，不尽数行泪。
自古进身者，本非陷物致。
当时文德修，不到三世地。','',''),('quantangshi-40510','织妇女','蘇拯','quantangshi','','卷41','伊余尽少女，一种饰螓首。
徒能事机杼，与之作歌舞。
歌舞片时间，黄金翻袖取。
秪看舞者乐，岂念织者苦。
感此尝忆古人言，一妇不织天下寒。','',''),('quantangshi-40511','古塞下','蘇拯','quantangshi','','卷41','百战已休兵，寒云愁未歇。
血染长城沙，马踏征人骨。
早得用蛾眉，免陷边戍卒。
始知髦头星，不在弯弓没。','',''),('quantangshi-40512','水旱祷','蘇拯','quantangshi','','卷41','祷祈勿告天，酒浆勿浇地。
阴阳和也无妖气，阴阳愆期乃人致。
病生心腹不自医，古屋澄潭何神祟。','',''),('quantangshi-40513','邹律','蘇拯','quantangshi','','卷41','邹律暖燕谷，青史徒编录。
人心不变迁，空吹闲草木。
世患有三惑，尔律莫能抑。
边苦有长征，尔律莫能息。
斯术未济时，斯律亦何益。
争如至公一开口，吹起贤良霸邦国。','',''),('quantangshi-40514','蜘蛛谕','蘇拯','quantangshi','','卷41','春蚕吐出丝，济世功不绝。
蜘蛛吐出丝，飞虫成聚血。
蚕丝何专利，尔丝何专孽。
映日张网罗，遮天亦何别。
傥居要地门，害物可堪说。
网成虽福己，网败还祸尔。
小人与君子，利害一如此。','',''),('quantangshi-40515','猎犬行','蘇拯','quantangshi','','卷41','猎犬未成行，狐兔无奈何。
猎犬今盈羣，狐兔依旧多。
自尔初跳跃，人言多拏躩。
常指天外狼，立可口中嚼。
骨长毛衣重，烧残烟草薄。
狡兔何曾擒，时把家鸡捉。
食尽者饭翻，增养者恶壮。
可嗟猎犬壮复壮，不堪兔绝良弓丧。','',''),('quantangshi-40516','断火谣','蘇拯','quantangshi','','卷41','谁谓之推贤，于世何功果。
绝尔晋侯交，禁我唐虞火。
国闭檀榆烟，大礼成隳堕。
暗室枯槁饭，冷面相看坐。
阳升既非佑，阴伏若为佐。
焉冻羣生腹，将止天下祸。
但究冤滥刑，天道无不可。
鄙哉前朝翊赞臣，訏谟之规何琐琐。','',''),('quantangshi-40517','思妇吟','蘇拯','quantangshi','','卷41','秋风雁又归，边信一何早。
揽衣出门望，落叶满长道。
一从秉箕箒，十载孤怀抱。
可堪日日醉宠荣，不说思君令人老。','',''),('quantangshi-40518','雉兔者','蘇拯','quantangshi','','卷41','所猎一何酷，终年耗林麓。
飞走如未空，贪残岂知足。
尝闻猎书史，可以鉴荣辱。
尝闻猎贤良，可以霸邦国。
如何纵网罗，空成肥骨肉。
和济俱不闻，曷所禳颠覆。
谁能为扣天地炉，铸此伤生其可乎。','',''),('quantangshi-40519','药草','蘇拯','quantangshi','','卷41','天子恤疲瘵，坤灵奉其职。
年年济世功，贵贱相兼植。
因产众草中，所希采者识。
一枝当若神，千金亦何直。
生草不生药，无以彰土德。
生药不生草，无以彰奇特。
国忠在臣贤，民患凭药力。
灵草犹如此，贤人岂多得。','',''),('quantangshi-40520','凡草诫','蘇拯','quantangshi','','卷41','野草凡不凡，亦应生和出。
鉏夫耘药栏，根不留其一。
良由本芜秽，着地成弃物。
人生行不修，何门可容膝。
不唯不尔容，得无凡草嫉。
贤愚偃仰间，鉴之宜日日。','',''),('quantangshi-40521','明禁忌','蘇拯','quantangshi','','卷41','阴阳家有书，卜筑多禁忌。
土中若有神，穴处何无祟。
我识先贤意，本诫骄侈地。
恣欲剏楼台，率情染朱翠。
四面兴土功，四时妨农事。
可以没凶灾，四隅通一二。
一年省修营，万民停困踬。
动若契于理，福匪神之遗。
动若越于常，祸乃身之致。
神在虚无间，土中非神位。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-40522','伤彩饰','蘇拯','quantangshi','','卷41','朝见亦光彩，暮见亦光彩。
一旦风雨飘，十分无一在。
尔形才似削，尔貌不如昨。
本为是凡姿，谁教染丹雘。
虚饰片时间，天意以为恶。
物假犹如此，人假争堪作。','',''),('quantangshi-40523','世迷','蘇拯','quantangshi','','卷41','乌兔日夜行，与人运枯荣。
为善不常缺，为恶不常盈。
天道无阿党，人心自覆倾。
所以多迁变，宁合天地情。
我愿造化手，莫放狐兔走。
恣海产珍奇，纵地生花柳。
美者一齐美，丑者一齐丑。
民心归大朴，战争亦何有。','',''),('quantangshi-40524','鸱枭','蘇拯','quantangshi','','卷41','为害未为害，其如汚物类。
斯言之一玷，流传极天地。
良木不得栖，清波不得戏。
曾戏水堪疑，曾栖树终弃。
天不歼尔族，与夫恶相济。
地若默尔声，与夫妖为讳。
一时怀害心，千古不能替。
伤哉丑行人，兹禽亦为譬。','',''),('quantangshi-40525','山中道者','蘇拯','quantangshi','','卷41','筇杖六尺许，坐石流泉所。
举头看古松，似对仙鹤语。
是时天气清，四迥无尘侣。
顾我笑相迎，知有丹砂异。','',''),('quantangshi-40526','渔人','蘇拯','quantangshi','','卷41','垂竿朝与暮，披蓑卧横楫。
不问清平时，自乐沧波业。
长畏不得闲，几度避游畋。
当笑钓台上，逃名名却传。','',''),('quantangshi-40527','闻猨','蘇拯','quantangshi','','卷41','秋风飒飒猨声起，客恨猨哀一相似。
漫向孤危惊客心，何曾解入笙歌耳。','',''),('quantangshi-40528','经马嵬坡','蘇拯','quantangshi','','卷41','一从杀贵妃，春来花无意。
此地纵千年，土香犹破鼻。
宠既出常理，辱岂同常死。
一等异于众，倾覆皆如此。','',''),('quantangshi-40529','经鹤台','蘇拯','quantangshi','','卷41','筑台非谓贤，独聚乘轩鹤。
六马不能驭，九臯欲何托。
一旦敌兵来，万民同陨濩。
如何警露禽，不似衔环雀。
一物欲误时，众类皆成恶。
至今台基上，飞鸟不至泊。','',''),('quantangshi-40530','寄远','蘇拯','quantangshi','','卷41','游子虽惜别，一去何时见。
飞鸟犹恋巢，万里亦何远。
妾愿化为霜，日日下河梁。
若能侵鬓色，先染薄情郎。','',''),('quantangshi-40531','芭蕉','路德延','quantangshi','','卷41','一种灵苗异，天然体性虚。
叶如斜界纸，心似倒抽书。','',''),('quantangshi-40532','感旧诗','路德延','quantangshi','','卷41','初骑竹马咏芭蕉，尝忝名卿诵满朝。
五字便容趋绛帐，一枝寻许折丹霄。
岂知流落萍蓬远，不觉推迁岁月遥。
国境未安身未立，至今颜巷守箪瓢。','',''),('quantangshi-40533','小儿诗','路德延','quantangshi','','卷41','情态任天然，桃红两颊鲜。
乍行人共看，初语客多怜。
臂膊肥如瓠，肌肤软胜绵。
长头才覆额，分角渐垂肩。
散诞无尘虑，逍遥占地仙。
排衙朱阁上，喝道画堂前。
合调歌杨柳，齐声踏采莲。
走堤行细雨，奔巷趁轻烟。
嫩竹乘为马，新蒲折作鞭。
莺雏金镟系，猫自彩丝牵。
拥鹤归晴岛，驱鹅入暖泉。
杨花争弄雪，榆叶共收钱。
锡镜当胸挂，银珠对耳悬。
头依苍鹘裹，袖学柘枝揎。
酒殢丹砂暖，茶催小玉煎。
频邀筹箸挣，时乞绣针穿。
宝箧拏红豆，妆奁拾翠钿。
戏袍披按褥，劣帽戴靴毡。
展画趍三圣，开屏笑七贤。
贮怀青杏小，垂额绿荷圆。
惊滴霑罗泪，娇流汚锦涎。
倦书饶娅姹，憎药巧迁延。
弄帐鸾绡映，藏衾凤绮缠。
指敲迎使鼓，筋拨赛神弦。
帘拂鱼钩动，筝推雁柱偏。
碁图添路画，笛管欠声镌。
恼客初酣睡，惊僧半入禅。
寻蛛穷屋瓦，探雀遍楼椽。
抛果忙开口，藏钩乱出拳。
夜分围榾柮，朝聚打秋千。
折竹装泥燕，添丝放纸鸢。
互夸轮水碓，相教放风旋。
旗小裁红绢，书幽截碧牋。
远铺张鸽网，低控射蝇弦。
詀语时时道，谣歌处处传。
匿牕眉乍曲，遮路臂相连。
鬬草当春迳，争球出晚田。
柳傍慵独坐，花底困横眠。
等鹊前篱畔，听蛩伏砌边。
傍枝粘舞蝶，隈树捉鸣蝉。
平岛夸趫上，层崖逞捷缘。
嫩苔车迹小，深雪履痕全。
竞指云生岫，齐呼月上天。
蚁窠寻迳斸，蜂穴遶阶填。
樵唱回深岭，牛歌下远川。
垒柴为屋木，和土作盘筵。
险砌高台石，危跳峻塔砖。
忽升隣舍树，偷上后池船。
项橐称师日，甘罗作相年。
明时方任德，劝尔减狂颠。','',''),('quantangshi-40534','句','路德延','quantangshi','','卷41','不是上台知姓字，五花宾馆敢从容。','',''),('quantangshi-40535','及第后呈朝中知己','李旭','quantangshi','','卷41','凌晨晓鼓奏嘉音，雷拥龙迎出陆沈。
金榜高悬当玉阙，锦衣即着到家林。
真珠每被尘泥陷，病鹤多遭蝼蚁侵。
今日始知天有意，还教雪得一生心。','',''),('quantangshi-40536','题惠严寺','崔庸','quantangshi','','卷41','人莫嫌山小，僧还爱寺灵。
殿高神气力，龙活客丹青。','',''),('quantangshi-40537','经费拾遗旧隐','胡駢','quantangshi','','卷41','林下茅斋已半倾，九华幽迳少人行。
不将冠劒为荣事，只向烟萝寄此生。
松竹渐荒池上色，琴书徒立世间名。
白杨风起秋山暮，时复哀猨啼一声。','',''),('quantangshi-40538','失题','周祚','quantangshi','','卷41','莫道春花独照人，秋花未必怯青春。
四时风雨没时节，共保松筠根底尘。','',''),('quantangshi-40539','蛱蝶行','盧頻','quantangshi','','卷41','东园宫草绿，上下飞相逐。
君恩不禁春，昨夜花中宿。','',''),('quantangshi-40540','东西行','盧頻','quantangshi','','卷41','种荷玉盆里，不及沟中水。
养雉黄金笼，见草心先喜。','',''),('quantangshi-40541','失题 一','盧頻','quantangshi','','卷41','春泪烂罗绮，泣声抽恨多。
莫滴芙蓉池，愁伤连蔕荷。','',''),('quantangshi-40542','失题 二','盧頻','quantangshi','','卷41','一朵花叶飞，一枝花光彩。
美人惜花心，但愿春长在。','',''),('quantangshi-40543','晚泊汉江渡','劉畋','quantangshi','','卷41','末秋云木轻，莲折晚香清。
雨下侵苔色，云凉出浪声。
叠帆依岸尽，微照夹堤明。
渡吏已头白，遥知客姓名。','',''),('quantangshi-40544','句','劉畋','quantangshi','','卷41','残阳来霁岫，独兴起沧洲。','',''),('quantangshi-40545','游洞庭湖','裴說','quantangshi','','卷41','楚云团翠八百里，澧兰吹香堕春水。
白头渔子摇苍烟，鸂鶒眠沙晓惊起。
沙头龙叟夜叹忧，铁笛未响春风羞。
露寒紫藟结新愁，城角泣断关河秋。
谪仙欲识雷斧手，刬却古今愁共丑。
鲸游碧落杳无踪，作诗三叹君知否。
瀛洲一棹何时还，满江宫锦看湖山。','',''),('quantangshi-40546','怀素台歌','裴說','quantangshi','','卷41','我呼古人名，鬼神侧耳听。
杜甫李白与怀素，文星酒星草书星。
永州东郭有奇怪，笔冢墨池遗迹在。
笔冢低低高如山，墨池浅浅深如海。
我来恨不已，争得青天化为一张纸。
高声唤起怀素书，搦管研朱点湘水。
欲归家，重叹嗟。
眼前有三个字，枯树槎，乌梢蛇，墨老鵶。','',''),('quantangshi-40547','闻砧','裴說','quantangshi','','卷41','深闺乍冷鉴开箧，玉筯微微湿红颊。
一阵霜风杀柳条，浓烟半夜成黄叶。
垂垂白练明如雪，独下闲堦转凄切。
祗知抱杵捣秋砧，不觉高楼已无月。
时闻寒雁声相唤，纱窓只有灯相伴。
几展齐纨又嬾裁，离肠恐逐金刀断。
细想仪形执牙尺，回刀剪破澄江色。
愁捻银针信手缝，惆怅无人试宽窄。
时时举袖匀红泪，红牋谩有千行字。
书中不尽心中事，一片殷勤寄边使。','',''),('quantangshi-40548','春早寄华下同人','裴說','quantangshi','','卷41','正是花时节，思君寝复兴。
市沽终不醉，春梦亦无凭。
岳面悬青雨，河心走浊冰。
东门一条路，离恨镇相仍。','',''),('quantangshi-40549','赠衡山令','裴說','quantangshi','','卷41','君吟十二载，辛苦必能官。
造化犹难隐，生灵岂易谩。
猿跳高岳静，鱼摆大江宽。
与我为同道，相留夜话阑。','',''),('quantangshi-40550','南中县令','裴說','quantangshi','','卷41','寂寥虽下邑，良宰有清威。
苦节长如病，为官岂肯肥。
山多村地狭，水浅客舟稀。
上国搜贤急，陶公早晚归。','',''),('quantangshi-40551','寄曹松','裴說','quantangshi','','卷41','莫怪苦吟迟，诗成鬓亦丝。
鬓丝犹可染，诗病却难医。
山暝云横处，星沈月侧时。
冥搜不可得，一句至公知。','',''),('quantangshi-40552','赠宾贡','裴說','quantangshi','','卷41','惟君怀至业，万里信悠悠。
路向东[溟]出，枝来北阙求。
家无一夜梦，帆挂隔年秋。
鬓发争禁得，孤舟往复愁。','',''),('quantangshi-40553','汉南邮亭','裴說','quantangshi','','卷41','高阁水风清，开门日送迎。
帆张独鸟起，乐奏大鱼惊。
骤雨拖山过，微风拂面生。
闲吟虽得句，留此谢多情。','',''),('quantangshi-40554','棋','裴說','quantangshi','','卷41','十九条平路，言平又嶮巇。
人心无算处，国手有输时。
势逈流星远，声干下雹迟。
临轩才一局，寒日又西垂。','',''),('quantangshi-40555','夏日即事','裴說','quantangshi','','卷41','僻居门巷静，竟日坐阶墀。
鹊喜虽传信，蛩吟不见诗。
笋抽通旧竹，梅落立闲枝。
此际无尘挠，僧来称所宜。','',''),('quantangshi-40556','送人宰邑','裴說','quantangshi','','卷41','官小任还重，命官难偶然。
皇恩轻一邑，赤子病三年。
瘦马稀飡粟，羸童不识钱。
如君清苦节，到处有人传。','',''),('quantangshi-40557','春暖送人下第','裴說','quantangshi','','卷41','相送短亭前，知君愚复贤。
事多凭夜梦，老为待明年。
春树添山脊，晴云学晓烟。
雄文有公道，此别莫澘然。','',''),('quantangshi-40558','湖外送何崇入阁','裴說','quantangshi','','卷41','因诗相识久，忽此告临途。
便是有船发，也须容市沽。
精吟五个字，稳泛两重湖。
长短逢公道，清名振帝都。','',''),('quantangshi-40559','送进士苏瞻乱后出家','裴說','quantangshi','','卷41','因乱事空王，孤心亦不伤。
梵僧为骨肉，柏寺作家乡。
眼闭千行泪，头梳一把霜。
诗书不得力，谁与问苍苍。','',''),('quantangshi-40560','秋日送河北从事','裴說','quantangshi','','卷41','北风沙漠地，吾子远从军。
官路虽非远，诗名要且闻。
蝉悲欲落日，雕下拟阴云。
此去难相恋，前山掺袂分。','',''),('quantangshi-40561','喜友人再面','裴說','quantangshi','','卷41','一别几寒暄，迢迢隔塞垣。
相思长有事，及见却无言。
静坐将茶试，闲书把叶翻。
依依又留宿，圆月上东轩。','',''),('quantangshi-40562','对雪','裴說','quantangshi','','卷41','大片向空舞，出门肌骨寒。
路岐平即易，沟壑满应难。
兔穴归时失，禽枝宿处干。
豪家宁肯厌，五月画图看。','',''),('quantangshi-40563','冬日后作','裴說','quantangshi','','卷41','寂寞掩荆扉，昏昏坐欲痴。
事无前定处，愁有并来时。
日影才添线，鬓根已半丝。
明庭正公道，应许苦心诗。','',''),('quantangshi-40564','冬日作','裴說','quantangshi','','卷41','粝食拥败絮，苦吟吟过冬。
稍寒人却健，太饱事多慵。
树老生烟薄，墙阴贮雪重。
安能只如此，公道会相容。','',''),('quantangshi-40565','中秋月','裴說','quantangshi','','卷41','一岁几盈亏，当轩重此期。
幸无偏照处，刚有不明时。
色静云归早，光寒鹤睡迟。
相看吟未足，皎皎下疎篱。','',''),('quantangshi-40566','塞上曲','裴說','quantangshi','','卷41','极目望空阔，马羸程又赊。
月生方见树，风定始无沙。
楚水辞鱼窟，燕山到雁家。
如斯名利役，争不老天涯。','',''),('quantangshi-40567','终南山','裴說','quantangshi','','卷41','九衢南面色，苍翠绝纤尘。
寸步有闲处，百年无到人。
禁林寒对望，太华净相邻。
谁与羣峰并，祥云瑞露频。','',''),('quantangshi-40568','访道士','裴說','quantangshi','','卷41','高冈微雨后，木脱草堂新。
惟有疎慵者，来看淡薄人。
竹牙生碍路，松子落敲巾。
麤得玄中趣，当期宿话频。','',''),('quantangshi-40569','道林寺','裴說','quantangshi','','卷41','独立凭危阑，高低落照间。
寺分一派水，僧锁半房山。
对面浮世隔，垂帘到老闲。
烟云与尘土，寸步不相关。','',''),('quantangshi-40570','般若寺','裴說','quantangshi','','卷41','南岳古般若，自来天下知。
翠笼无价寺，光射有名诗。
一水涌兽迹，五峰排凤仪。
高僧引闲步，昼出夕阳归。','',''),('quantangshi-40571','兜率寺','裴說','quantangshi','','卷41','一片无尘地，高连梦泽南。
僧居跨鸟道，佛影照鱼潭。
朽枿云斜映，平芜日半涵。
行行不得住，回首望烟岚。','',''),('quantangshi-40572','鹿门寺','裴說','quantangshi','','卷41','鹿门山上寺，突兀尽无尘。
到此修行者，应非取次人。
鸟过惊石磬，日出碍金身。
何计生烦恼，虚空是四邻。','',''),('quantangshi-40573','题岳州僧舍','裴說','quantangshi','','卷41','喜到重湖北，孤州横晚烟。
鹭衔鱼入寺，鵶接饭随船。
松桧君山逈，菰蒲梦泽连。
与师吟论处，秋水浸遥天。','',''),('quantangshi-40574','过洞庭湖','裴說','quantangshi','','卷41','浪高风力大，挂席亦言迟。
及到堪忧处，争如未济时。
鱼龙侵莫测，雷雨动须疑。
此际情无赖，何门寄所思。','',''),('quantangshi-40575','旅行闻寇','裴說','quantangshi','','卷41','动步忧多事，将行问四邻。
深山不畏虎，当路却防人。
豪富田园废，疲羸屋舍新。
自慙为旅客，无计避烟尘。','',''),('quantangshi-40576','旅中作','裴說','quantangshi','','卷41','妄动远抛山，其如馁与寒。
投人言去易，开口说贫难。
泽国云千片，湘江竹一竿。
时明未忍别，犹待计穷看。','',''),('quantangshi-40577','旅次衡阳','裴說','quantangshi','','卷41','欲往几经年，今来意豁然。
江风长借客，岳雨不因天。
戏鹭飞轻雪，惊鸿呌乱烟。
晚秋红藕里，十宿寄渔船。','',''),('quantangshi-40578','不出院僧','裴說','quantangshi','','卷41','四远参寻徧，修行却不行。
耳边无俗语，门外是前生。
塔见移来影，钟闻过去声。
一斋唯默坐，应笑我营营。','',''),('quantangshi-40579','湖外寄处宾上人','裴說','quantangshi','','卷41','怪得意相亲，高携一轴新。
能搜大雅句，不似小乘人。
岳麓擎枯桧，潇湘吐白苹。
他年遇同道，为我话风尘。','',''),('quantangshi-40580','寄贯休','裴說','quantangshi','','卷41','忆昔与吾师，山中静论时。
总无方是法，难得始为诗。
冻犬眠干叶，饥禽啄病梨。
他年白莲社，犹许重相期。','',''),('quantangshi-40581','寄僧尚颜','裴說','quantangshi','','卷41','曾居五老峰，所得共谁同。
才大天全与，吟精楚欲空。
客来庭减日，鸟过竹生风。
早晚摇轻拂，重归瀑布中。','',''),('quantangshi-40582','哭处默上人','裴說','quantangshi','','卷41','凄凉繐幕下，香吐一灯分。
鬬老输寒桧，留闲与白云。
挈盂曾几度，传衲不教焚。
泣罢重回首，暮山钟半闻。','',''),('quantangshi-40583','庐山瀑布','裴說','quantangshi','','卷41','静景凭高望，光分翠嶂开。
嶮飞千尺雪，寒扑一声雷。
过去云冲断，旁来烧隔廻。
何当住峰下，终岁绝尘埃。','',''),('quantangshi-40584','华山上方','裴說','quantangshi','','卷41','独上上方上，立高聊称心。
气冲云易黑，影落县多阴。
有云草不死，无风松自吟。
会当求大药，他日复追寻。','',''),('quantangshi-40585','咏鹦鹉','裴說','quantangshi','','卷41','常贵西山鸟，衔恩在玉堂。
语传明主意，衣拂美人香。
缓步寻珠网，高飞上画梁。
长安频道乐，何日从君王。','',''),('quantangshi-40586','鹭鸶','裴說','quantangshi','','卷41','秋江清浅时，鱼过亦频窥。
却为分明极，翻成所得迟。
浴偎红日色，栖压碧芦枝。
会共鵷同侣，翺翔应可期。','',''),('quantangshi-40587','牡丹','裴說','quantangshi','','卷41','数朵欲倾城，安同桃李荣。
未尝贫处见，不似地中生。
此物疑无价，当春独有名。
游蜂与蝴蝶，来往自多情。','',''),('quantangshi-40588','见王贞白','裴說','quantangshi','','卷41','共贺登科后，明宣入紫宸。
又看重试榜，还见苦吟人。
此得名浑别，归来话亦新。
分明一枝桂，堪动楚江滨。','',''),('quantangshi-40589','经杜工部坟','裴說','quantangshi','','卷41','骚人久不出，安得国风清。
拟掘孤坟破，重教大雅生。
皇天高莫问，白酒恨难平。
悒怏寒江上，谁人知此情。','',''),('quantangshi-40590','寄僧知干','裴說','quantangshi','','卷41','貌高清入骨，帝里旧临坛。
出语经相似，行心佛证安。','',''),('quantangshi-40591','乱中偷路入故乡','裴說','quantangshi','','卷41','愁看贼火起诸烽，偷得余程怅望中。
一国半为亡国烬，数城俱作古城空。','',''),('quantangshi-40592','蔷薇','裴說','quantangshi','','卷41','一架长条万朵春，嫩红深绿小窠匀。
只应根下千年土，曾葬西川织锦人。','',''),('quantangshi-40593','春日山中竹','裴說','quantangshi','','卷41','数竿苍翠拟龙形，峭拔须教此地生。
无限野花开不得，半山寒色与春争。','',''),('quantangshi-40594','柳','裴說','quantangshi','','卷41','高拂危楼低拂尘，灞桥攀折一何频。
思量却是无情树，不解迎人只送人。','',''),('quantangshi-40595','岳阳兵火后题僧舍','裴說','quantangshi','','卷41','十年兵火真多事，再到禅扉却破颜。
唯有两般烧不得，洞庭湖水老僧闲。','',''),('quantangshi-40596','句','裴說','quantangshi','','卷41','读书贫里乐，搜句静中忙。
苦吟僧入定，得句将成功。
是事精皆易，唯诗会却难。
因携一家住，赢得半年吟。
吟余潮入浦，坐久烧移山。
三年清似水，六月冷如冰。
一通红锦重，三事紫罗轻。
瘦肌寒带粟，病眼馁生花。
避乱一生多，雪留寒竹寺舍冷。
风撼早梅城郭香，画球轻蹴壶中地。
彩索高飞掌上身。','',''),('quantangshi-40597','赠唐山人','李洞','quantangshi','','卷41','垂须长似发，七十色如黳。
醉眼青天小，吟情太华低。
千年松绕屋，半夜雨连溪。
邛蜀路无限，往来琴独携。','',''),('quantangshi-40598','送云卿上人游安南','李洞','quantangshi','','卷41','春往海南边，秋闻半夜蝉。
鲸吞洗钵水，犀触点灯船。
岛屿分诸国，星河共一天。
长安却回日，松偃旧房前。','',''),('quantangshi-40599','郑补阙山居','李洞','quantangshi','','卷41','高节谏垣客，白云居静坊。
马饥餐落叶，鹤病晒残阳。
野雾昏朝烛，溪牋惹御香。
相招倚蒲壁，论句夜何长。','',''),('quantangshi-40600','送曹郎中南归时南中用军','李洞','quantangshi','','卷41','桂水净和天，南归似谪仙。
系绦轻象笏，买布接蛮船。
海气蒸鼙软，江风激箭偏。
罢郎吟乱里，帝远岂知贤。','',''),('quantangshi-40601','锦江陪兵部郑侍郎话诗着棊','李洞','quantangshi','','卷41','落叶溅吟身，会棊云外人。
海枯搜不尽，天定着长新。
月上分题遍，钟残布子匀。
忘餐二绝境，取意铸陶钧。','',''),('quantangshi-40602','中秋月','李洞','quantangshi','','卷41','四十五秋宵，月分千里毫。
冷沈中岳短，光溢太行高。
不寐清人眼，移栖湿鹤毛。
露华台上别，吟望十年劳。','',''),('quantangshi-40603','送沈光赴福幕','李洞','quantangshi','','卷41','泉齐岭鸟飞，雨熟荔枝肥。
南斗看应近，北人来恐稀。
潮浮廉使宴，珠照岛僧归。
幕下逢迁拜，何官着茜衣。','',''),('quantangshi-40604','鄠郊山舍题赵处士林亭','李洞','quantangshi','','卷41','圭峰秋后叠，乱叶落寒墟。
四五百竿竹，二三千卷书。
云深猿拾栗，雨霁蚁缘蔬。
只隔门前水，如同万里余。','',''),('quantangshi-40605','赋得送贾岛谪长江','李洞','quantangshi','','卷41','敲驴吟雪月，谪出国西门。
行傍长江影，愁深汨水魂。
筇携过竹寺，琴典在花村。
饥拾山松子，谁知贾傅孙。','',''),('quantangshi-40606','河阳道中','李洞','quantangshi','','卷41','冲风仍蹑冻，提辔手频呵。
得事应须早，愁人不在多。
雪田平入塞，烟郭曲随河。
飜忆江涛里，船中睡盖蓑。','',''),('quantangshi-40607','送知己赴濮州','李洞','quantangshi','','卷41','中路行僧谒，邮亭话海涛。
劒摇林狖落，旗闪岳禽高。
苔长空州狱，花开梦省曹。
濮阳流政化，一半布风骚。','',''),('quantangshi-40608','送行脚僧','李洞','quantangshi','','卷41','瓶枕绕腰垂，出门何所之。
毳衣霑雨重，椶笠看山欹。
夜观入枯树，野眠逢断碑。
邻房母泪下，相课别离词。','',''),('quantangshi-40609','龙州送人赴举','李洞','quantangshi','','卷41','献策赴招携，行宫积翠西。
挈囊秋卷重，转栈晚峰齐。
踏月趋金阙，拂云看御题。
飞鸣岂回顾，独鹤困江泥。','',''),('quantangshi-40610','送安抚从兄夷偶中丞','李洞','quantangshi','','卷41','奉诏向军前，朱袍暎雪鲜。
河桥吹角冻，岳月卷旗圆。
僧救焚经火，人修着钓船。
六州安抚后，万户解衣眠。','',''),('quantangshi-40611','送远上人','李洞','quantangshi','','卷41','海岳两无边，去来都偶然。
齿因吟后冷，心向静中圆。
虫网花间井，鸿鸣雨后天。
叶书归旧寺，应附载钟船。','',''),('quantangshi-40612','宿凤翔天柱寺穷易玄上人房','李洞','quantangshi','','卷41','天柱暮相逢，吟思天柱峰。
墨研青露月，茶吸白云钟。
卧语身黏藓，行禅顶拂松。
探玄为一决，明日去临邛。','',''),('quantangshi-40613','下第送张霞归觐江南','李洞','quantangshi','','卷41','此道背于时，携归一轴诗。
树沈孤鸟远，风逆蹇驴迟。
草入吟房坏，潮冲钓石移。
恐伤欢觐意，半路摘愁髭。','',''),('quantangshi-40614','送人之天台','李洞','quantangshi','','卷41','行李一枝藤，云边晓扣冰。
丹经如不谬，白发亦何能。
浅井仙人镜，明珠海客灯。
乃知真隐者，笑就汉廷徴。','',''),('quantangshi-40615','维摩畅林居','李洞','quantangshi','','卷41','诸方游几腊，五夏五峰销。
越讲迎骑象，蕃斋忏射雕。
冷筇和雪倚，朽栎带云烧。
从此西林老，瞥然三万朝。','',''),('quantangshi-40616','送张乔下第归宣州','李洞','quantangshi','','卷41','诗道世难通，归宁楚浪中。
早程残岳月，夜泊隔淮钟。
一镜随双鬓，全家老半峰。
无成来往过，折尽谢亭松。','',''),('quantangshi-40617','送卢郎中赴金州','李洞','quantangshi','','卷41','云明天岭高，刺郡辍仙曹。
危栈窥猿顶，公庭埽鹤毛。
出军青壁罅，话道白眉毫。
远集歌谣客，州前泊几艘。','',''),('quantangshi-40618','江干即事','李洞','quantangshi','','卷41','病卧四更后，愁闻报早衙。
隔关沈水鸟，侵郭噪园鸦。
吏瘦餐溪栢，身羸凭海槎。
满朝吟五字，应不老烟霞。','',''),('quantangshi-40619','寄贺郑常侍','李洞','quantangshi','','卷41','山亦怀恩地，高禽尽下飞。
吏穿霞片望，僧埽月棱归。
省拜墀烟近，林居玉漏微。
曾令驻锡话，聊用慰攀依。','',''),('quantangshi-40620','登楼','李洞','quantangshi','','卷41','川上值楼开，寒山四面来。
竹吹人语远，峰碍鸟飞回。
生死别离陌，朝昏云雨堆。
谁知独立意，溅泪落莓苔。','',''),('quantangshi-40621','赠禅友','李洞','quantangshi','','卷41','散花留内殿，宫女梦谈禅。
树杪开楼锁，云中认岳莲。
溪声过长耳，筇节出羸肩。
飞句相招宿，多逢有月天。','',''),('quantangshi-40622','早春友人访别南归','李洞','quantangshi','','卷41','南归来取别，穷巷坐青苔。
一盏薄醨酒，数枝零落梅。
潮生楚驿闭，星在越楼开。
明日望君处，前临风月台。','',''),('quantangshi-40623','题云际寺','李洞','quantangshi','','卷41','开门风雪顶，上彻困飞禽。
猿戏青冥里，人行紫阁阴。
腊泉冰下出，夜磬月中寻。
尽欲居岩室，如何不住心。','',''),('quantangshi-40624','山寺老僧','李洞','quantangshi','','卷41','云际众僧里，独攒眉似愁。
护茶高夏腊，爱火老春秋。
海浪南曾病，河冰北苦游。
归来诸弟子，白徧后生头。','',''),('quantangshi-40625','同僧宿道者院','李洞','quantangshi','','卷41','携文过水宿，拂席四廊尘。
坠果敲楼瓦，高萤暎鹤身。
点灯吹叶火，谈佛悟山人。
尽有栖霞志，好谋三教邻。','',''),('quantangshi-40626','古栢','李洞','quantangshi','','卷41','手植知何代，年齐偃盖松。
结根生别树，吹子落邻峰。
古干经龙嗅，高烟过雁冲。
可佳繁叶尽，声不碍秋钟。','',''),('quantangshi-40627','赠王凤二山人','李洞','quantangshi','','卷41','山兄望鹤信，山弟听乌占。
养药同开鼎，休棊各枕奁。
相逢九江底，共到五峰尖。
愿许为三友，羞将白发挦。','',''),('quantangshi-40628','避地冬夜与二三禅侣吟集茅斋','李洞','quantangshi','','卷41','四海通禅客，搜吟会草亭。
拈髭孤烛白，闭目众山青。
松挂敲冰杖，罏温注月瓶。
独愁悬旧斾，笏冷立残星。','',''),('quantangshi-40629','赠道微禅师','李洞','quantangshi','','卷41','铜瓶涩泻水，出碛蹑莲层。
猛虎降低鼠，盘雕望小蝇。
通禅五天日，照祖几朝灯。
短发归林白，何妨剃未能。','',''),('quantangshi-40630','吊草堂禅师','李洞','quantangshi','','卷41','杖屦疑师在，房关四壁蛬。
贮瓶经腊水，响塔隔山钟。
乳鸽沿苔井，斋猿散雪峰。
如何不见性，倚徧寺前松。','',''),('quantangshi-40631','宿长安苏雍主簿厅','李洞','quantangshi','','卷41','县对数峰云，官清主簿贫。
听更池上鹤，伴值岳阳人。
井锁煎茶水，厅关捣药尘。
往来多屣步，同舍即诸邻。','',''),('quantangshi-40632','秋宿润州刘处士江亭','李洞','quantangshi','','卷41','北梦风吹断，江边处士亭。
吟生万井月，见尽一天星。
浪静鱼冲锁，窗高鹤听经。
东西渺无际，世界半沧溟。','',''),('quantangshi-40633','秋日曲江书事','李洞','quantangshi','','卷41','门摇枯苇影，落日共鸥归。
园近鹿来熟，江寒人到稀。
片云穿塔过，枯叶入城飞。
翻怕宾鸿至，无才动礼闱。','',''),('quantangshi-40634','秋宿经上人房','李洞','quantangshi','','卷41','江房无叶落，松影带山高。
满寺中秋月，孤窗入夜涛。
旧真悬石壁，衰发落铜刀。
卧听晓耕者，与师知苦劳。','',''),('quantangshi-40635','冬日题觉公牛头兰若','李洞','quantangshi','','卷41','天寒高木静，一磬隔川闻。
鼎水看山汲，台香埽雪焚。
鹤归惟认刹，僧步不离云。
石室开禅后，轮珠谢圣君。','',''),('quantangshi-40636','送皇甫校书自蜀下峡归觐襄阳','李洞','quantangshi','','卷41','蜀道波不竭，巢乌出浪痕。
松阴盖巫峡，雨色彻荆门。
宿寺青山尽，归林彩服翻。
苦吟怀冻馁，为吊浩然魂。','',''),('quantangshi-40637','题西明寺攻文僧林复上人房','李洞','quantangshi','','卷41','谁寄湘南信，阴窗砚起津。
烧痕碑入集，海角寺留真。
楼憩长空鸟，钟惊半阙人。
御沟圆月会，似在草堂身。','',''),('quantangshi-40638','寄翠微无可上人','李洞','quantangshi','','卷41','远近众心归，居然占翠微。
展经猿识字，听法虎知非。
泉注城池梦，霞生侍卫衣。
玄机不可学，何似总无机。','',''),('quantangshi-40639','喜鸾公自蜀归','李洞','quantangshi','','卷41','禁院对生台，寻师到绿槐。
寺高猿看讲，钟动鸟知斋。
埽石月盈箒，滤泉花满筛。
归来逢圣节，吟步上尧阶。','',''),('quantangshi-40640','题新安国寺','李洞','quantangshi','','卷41','佛亦遇艰难，重兴叠废坛。
偃松枝旧折，画竹粉新干。
开讲宫娃听，抛生禁鸟餐。
钟声入帝梦，天竺化长安。','',''),('quantangshi-40641','蕃寇侵逼南归道中','李洞','quantangshi','','卷41','云州三万骑，南走疾飞鹰。
回碛星低雁，孤城月伴僧。
敲关通汉节，倾府守河冰。
无处论边事，归溪夜结罾。','',''),('quantangshi-40642','送东宫贾正字之蜀','李洞','quantangshi','','卷41','南朝献晋史，东蜀瞰巴楼。
长栈怀宫树，疎峰露劒州。
半空飞雪化，一道白云流。
若次江边邑，宗诗为徧搜。','',''),('quantangshi-40643','吊侯圭常侍','李洞','quantangshi','','卷41','我重君能赋，君褒我解诗。
三堂一拜遇，四海两心知。
影挂僧挑烛，名传鹤拂碑。
涪江吊孤冢，片月下峨嵋。','',''),('quantangshi-40644','颜上人房','李洞','quantangshi','','卷41','御沟临岸行，远岫见云生。
松下度三伏，磬中销五更。
雨淋经阁白，日闪剃刀明。
海畔终须去，烧灯老国清。','',''),('quantangshi-40645','题薛少府庄','李洞','quantangshi','','卷41','何须凿井饮，门占古溪居。
寂寞苔牀卧，寒虚玉柄书。
有期登白阁，又得赏红蕖。
清浅蒲根水，时看鹭啄鱼。','',''),('quantangshi-40646','寄太白隐者','李洞','quantangshi','','卷41','开辟已来雪，为山长欠春。
高遮辞碛雁，寒噤入川人。
栈阁交冰柱，耕樵隔日轮。
此中栖息者，不识两京尘。','',''),('quantangshi-40647','秋宿青龙禅阁','李洞','quantangshi','','卷41','前山不可望，暮色渐沉规。
日转须弥北，蟾来渤海西。
风铃乱僧语，霜枿欠猿啼。
阁外千家月，分明见里迷。','',''),('quantangshi-40648','登圭峰旧隐寄荐福栖白上人','李洞','quantangshi','','卷41','返照塔轮边，残霖滴几悬。
夜寒吟病甚，秋健讲声圆。
粟穗干灯焰，苔根浊水泉。
西峰埋藓石，秋月即师禅。','',''),('quantangshi-40649','将之蜀别友人','李洞','quantangshi','','卷41','嘉陵雨色青，澹别酌参苓。
到蜀高诸岳，窥天合四溟。
书来应隔雪，梦觉已无星。
若遇多吟友，何妨勘竺经。','',''),('quantangshi-40650','吊膳曹从叔郎中','李洞','quantangshi','','卷41','华省支残俸，寒蔬办祭稀。
安坟对白阁，买石折朱衣。
蜀客弹琴哭，江鸥入宅飞。
帆吹佳句远，不独徧王畿。','',''),('quantangshi-40651','乱后龙州送郑郎中兼寄郑侍御','李洞','quantangshi','','卷41','待车登叠嶂，经乱集鸰原。
省坏兰终洁，台寒栢有根。
县清江入峡，楼静雪连村。
莫隐匡山社，机云受晋恩。','',''),('quantangshi-40652','段秀才溪居送从弟游泾陇','李洞','quantangshi','','卷41','抱疾寒溪卧，因循草木青。
相留开夏蜜，辞去见秋萤。
朔雪痕侵雍，边烽焰照泾。
烟沈陇山色，西望涕交零。','',''),('quantangshi-40653','题刘相公光德里新构茅亭','李洞','quantangshi','','卷41','野色迷亭晓，龙墀待押班。
带涎移海木，兼雪写湖山。
月白吟牀冷，河清直印闲。
唐封三万里，人偃翠微间。','',''),('quantangshi-40654','江峡寇乱寄怀吟僧','李洞','quantangshi','','卷41','半锡探寒流，别师猿鹤洲。
二三更后雨，四十字边秋。
立塞吟霞石，敲鼙看雪楼。
扶亲何处隐，惊梦入嵩丘。','',''),('quantangshi-40655','贺昭国从叔员外转本曹郎中','李洞','quantangshi','','卷41','苔砌塔阴浓，朝回尚叫蛬。
粟徴山县欠，官转水曹重。
灯照楼中雨，书求海上峰。
诗家无骤显，一一古人踪。','',''),('quantangshi-40656','赠宋校书','李洞','quantangshi','','卷41','曾伴元戎猎，寒来梦北军。
闲身不计日，病鹤放归[云]。
石上铺碁势，船中赌酒分。
长言买天姥，高卧谢人羣。','',''),('quantangshi-40657','越公上人洛中归寄南孟家兄弟','李洞','quantangshi','','卷41','洛下因归去，官西忆二龙。
笠漫河岸雪，衣着虢城钟。
睡鸭浮寒水，樵人出远峰。
贺当化闾俗，护取草堂松。','',''),('quantangshi-40658','龙州送裴秀才','李洞','quantangshi','','卷41','违拜斾旗前，松阴路半千。
楼冲高雪会，驿闭乱云眠。
牓挂临江省，名题赴宅筵。
人求新蜀赋，应贵浣花牋。','',''),('quantangshi-40659','题慈恩友人房','李洞','quantangshi','','卷41','贾生耽此寺，胜事入诗多。
鹤宿星千树，僧归烧一坡。
塔棱垂雪水，江色暎茶锅。
长久堪栖息，休言忆镜波。','',''),('quantangshi-40660','寄窦禅山薛秀才','李洞','quantangshi','','卷41','窦岭吟招隐，新诗满集贤。
白衫春絮暖，红纸夏云鲜。
琴缠江丝细，棊分海石圆。
因知醉公子，虚写世人传。','',''),('quantangshi-40661','西蜀与崔先生话东洛旧游','李洞','quantangshi','','卷41','王屋峭难名，三刀梦四更。
日升当地缺，星尽未天明。
度雪云林湿，穿松角韵清。
崔家开锦浪，忆着水窗声。','',''),('quantangshi-40662','上昭国水部从叔郎中','李洞','quantangshi','','卷41','极南极北游，东泛复西流。
行匝中华地，魂销四海秋。
题诗在琼府，附舶出青州。
不遇一公子，弹琴吊古丘。','',''),('quantangshi-40663','题玉芝赵尊师院','李洞','quantangshi','','卷41','晓起磬房前，真经诵百篇。
漱流星入齿，照镜石差肩。
静闭街西观，存思海上仙。
闲听说五岳，穷徧一根莲。','',''),('quantangshi-40664','送卢少府之任巩洛','李洞','quantangshi','','卷41','从知东甸尉，铨注似恩除。
带土移嵩术，和泉送尹鱼。
印牀寒鹭宿，壁记醉僧书。
堂下诸昆在，无妨候起居。','',''),('quantangshi-40665','送人归觐河中','李洞','quantangshi','','卷41','青门冢前别，道路武关西。
有寺云连石，无僧叶满溪。
河长随鸟尽，山远与人齐。
觐省波涛县，寒窗响曙鸡。','',''),('quantangshi-40666','锦城秋寄怀弘播上人','李洞','quantangshi','','卷41','极顶云兼冻，孤城露洗初。
共辞嵩少雪，久绝贝多书。
远照雁行细，寒条狖挂虚。
分泉煎月色，忆就茗林居。','',''),('quantangshi-40667','圭峰溪居寄怀韦曲曹秀才','李洞','quantangshi','','卷41','南北飞山雪，万片寄相思。
东西曲流水，千声泻别离。
巴猿学导引，陇鸟解吟诗。
翻羡家林赏，世人那得知。','',''),('quantangshi-40668','送舍弟之山南','李洞','quantangshi','','卷41','南山入谷游，去彻山南州。
下马云未尽，听猿星正稠。
印茶泉遶石，封国角吹楼。
远宦有何兴，贫兄无计留。','',''),('quantangshi-40669','题南鉴公山房','李洞','quantangshi','','卷41','竹房开处峭，迥挂半山灯。
石磬敲来穴，不知何代僧。
讲归双袖雪，禅起一盂冰。
唯说黄桑屐，当时着秣陵。','',''),('quantangshi-40670','送知己','李洞','quantangshi','','卷41','郡清官舍冷，枕席溅山泉。
药气来人外，灯光到鹤边。
梦秦书印斗，思越画渔船。
掷笏南归去，波涛路几千。','',''),('quantangshi-40671','送人赴职湘潭','李洞','quantangshi','','卷41','南征虽赴辟，其奈负高科。
水合湘潭住，山分越国多。
梅花雪共下，文□□相和。
白发陪官宴，红旗影里歌。','',''),('quantangshi-40672','过野叟居','李洞','quantangshi','','卷41','野人居止处，竹色与山光。
留客羞蔬饭，洒泉开草堂。
雨余松子落，风过术苗香。
尽日无炎暑，眠君青石牀。','',''),('quantangshi-40673','吊郑宾客','李洞','quantangshi','','卷41','朝行丧名节，岳色惨天风。
待漏秋吟断，焚香夜直空。
骨寒依壠草，家尽逐边鸿。
一吊知音后，归来碎峄桐。','',''),('quantangshi-40674','送从叔书记山阴隐居','李洞','quantangshi','','卷41','山顶绝茅居，云泉遶枕虚。
烧移僧影瘦，风展鹭行疎。
卷箔清江月，敲松紫阁书。
由来簪组贵，不信教猿锄。','',''),('quantangshi-40675','避暑庄严禅院','李洞','quantangshi','','卷41','定里无烦热，吟中达性情。
入林逢客话，上塔接僧行。
八水皆知味，诸翁尽得名。
常论冰井近，莫便厌浮生。','',''),('quantangshi-40676','寄清演','李洞','quantangshi','','卷41','忽闻清演病，可料苦吟身。
不见近诗久，徒言华发新。
别来山已破，住处月为邻。
几遶庭前树，于今四十春。','',''),('quantangshi-40677','迁村居二首 一','李洞','quantangshi','','卷41','移居入村宇，树阙见城隍。
云水虽堪画，恩私不可忘。
猿涎滴鹤氅，麈尾拂僧牀。
弃逐随樵牧，何由报稻粱。','',''),('quantangshi-40678','迁村居二首 二','李洞','quantangshi','','卷41','歌乐听常稀，茅亭静掩扉。
槎来垂钓次，月落问安归。
远客传烧研，幽禽看衲衣。
眼前无俗事，松雨蜀山辉。','',''),('quantangshi-40679','出山覩春牓','李洞','quantangshi','','卷41','未老鬓毛焦，心归向石桥。
指霞辞二纪，吟雪遇三朝。
连席频登相，分廊尚祝尧。
回眸旧行侣，免使负嵩樵。','',''),('quantangshi-40680','贾岛墓','李洞','quantangshi','','卷41','一第人皆得，先生岂不销。
位卑终蜀士，诗绝占唐朝。
旅葬新坟小，魂归故国遥。
我来因奠洒，立石用为标。','',''),('quantangshi-40681','观水墨障子','李洞','quantangshi','','卷41','若非神助笔，砚水恐藏龙。
研尽一寸墨，埽成千仞峰。
壁根堆乱石，牀罅插枯松。
岳麓穿因鼠，湘江绽为蛬。
挂衣岚气湿，梦枕浪头舂。
只为少颜色，时人着意慵。','',''),('quantangshi-40682','对棊','李洞','quantangshi','','卷41','小槛明高雪，幽人鬬智棊。
日斜抛作劫，月午蹙成迟。
倚杖湘僧筭，翘松野鹤窥。
侧楸敲醒睡，片石夹吟诗。
雨点匳中渍，灯花局上吹。
秋涛寒竹寺，此兴谢公知。','',''),('quantangshi-40683','题竹溪禅院','李洞','quantangshi','','卷41','溪边山一色，水拥竹千竿。
鸟触翠微湿，人居酷暑寒。
风摇瓶影碎，沙陷履痕端。
爽极青崖树，平流绿峡滩。
闲来披衲数，涨后卷经看。
三境通禅寂，嚣尘染着难。','',''),('quantangshi-40684','投献吏部张侍郎十韵','李洞','quantangshi','','卷41','苔染马蹄青，何曾似在城。
不于僧院宿，多傍御沟行。
隐岫侵巴叠，租田带渭平。
肩囊寻省寺，袖轴徧公卿。
梦入连涛郡，书来积雪营。
泪随边雁堕，魂逐夜蝉惊。
发愤巡江塔，无眠数县更。
玄都一病客，兴善几回莺。
贡艺披沙细，酬恩戴岳轻。
心期公子念，滴酒在雕楹。','',''),('quantangshi-40685','终南山二十韵','李洞','quantangshi','','卷41','关内平田窄，东西截杳冥。
雨侵诸县黑，云破九门青。
暂看犹无暇，长栖信有灵。
古苔秋渍斗，积雾夜昏萤。
怒恐撞天漏，深疑隐地形。
盘根连北岳，转影落南溟。
穷穴何山出，遮蛮上国宁。
残阳高照蜀，败叶远浮泾。
斸竹烟岚冻，偷湫雨雹腥。
闲房僧灌顶，浴涧鹤遗翎。
梯滑危缘索，云深静唱经。
放泉惊鹿睡，闻磬得人醒。
踏着神仙宅，敲开洞府扃。
棊残秦士局，字缺晋公铭。
一谷势当午，孤峰耸起丁。
远平丹凤阙，冷射五侯厅。
万丈冰声折，千寻树影停。
望中仙岛动，行处月轮馨。
叠石移临砌，研胶泼上屏。
明时献君寿，不假老人星。','',''),('quantangshi-40686','秋日同觉公上人眺慈恩塔六韵','李洞','quantangshi','','卷41','九级耸莲宫，晴登袖拂虹。
房廊窥井底，世界出笼中。
照牖三山火，吹铃八极风。
细闻槎客语，遥辨海鱼冲。
禁静声连北，江寒影在东。
谒师开秘锁，尘日闭虚空。','',''),('quantangshi-40687','感知上刑部郑侍郎','李洞','quantangshi','','卷41','寄掩白云司，蜀都高卧时。
邻僧照寒竹，宿鸟动秋池。
帝诵嘉莲表，人吟宝劒诗。
石渠流月断，画角截江吹。
闲出黄金勒，前飞白鹭鹚。
公心外国说，重望两朝推。
静藓斜圭影，孤窗响锡枝。
兴幽松雪见，心苦砚冰知。
缘杖虫声切，过门马足迟。
漏残终卷读，日下大名垂。
平碛容雕上，仙山许狖窥。
数联金口出，死免愧丘为。','',''),('quantangshi-40688','叙事寄荐福栖白','李洞','quantangshi','','卷41','险倚石屏风，秋涛梦越中。
前朝吟会散，故国讲流终。
北地闻巴狖，南山见碛鸿。
楼高惊雨阔，木落觉城空。
兔满期姚监，蝉稀别楚公。
净瓶光照客，拄杖朽生虫。
平地塔千尺，半空灯一笼。
祝尧谈几句，旋泻海涛东。','',''),('quantangshi-40689','送龙州田使君旧诗家','李洞','quantangshi','','卷41','御札轸西陲，龙州出牧时。
度关云作雪，挂栈水成澌。
劒淬号猿岸，弓悬宿鹤枝。
江灯混星斗，山木乱枪旗。
锁库休秤药，开楼又见诗。
无心陪宴集，吟苦忆京师。','',''),('quantangshi-40690','和知己赴任华州','李洞','quantangshi','','卷41','东门罢相郡，此拜动京华。
落日开宵印，初灯见早麻。
鹤身红斾拂，仙掌白云遮。
塞色侵三县，河声聒两衙。
松根醒客酒，莲座隐僧家。
一道帆飞直，中筵岳影斜。
书名寻雪石，澄鼎露金沙。
锁合眠关吏，杯寒啄庙鸦。
分台话嵩洛，赛雨恋烟霞。
树谷期招隐，吟诗煮栢茶。','',''),('quantangshi-40691','题咸阳楼','李洞','quantangshi','','卷41','晚亚古城门，凭高黯客魂。
塞侵秦旧国，河浸汉荒村。
客路扬书烬，人家带水痕。
猎频虚冢穴，耕苦露松根。
墙外峰黏汉，冰中日晃原。
断碑移作砌，广第灌成园。
北马疑眠碛，南人忆钓湓。
桥闲野鹿过，街静禁鸦翻。
滩鼓城隍动，云冲太白昏。
标衣多吕裔，荷锸或刘孙。
吊问难知主，登攀强滴罇。
不能扶壮势，冠劒惜干坤。','',''),('quantangshi-40692','赠兴善彻公上人','李洞','quantangshi','','卷41','师资怀劒外，徒步管街东。
九里山横烧，三条木落风。
古池曾看鹤，新塔未吟虫。
夜久龙髯冷，年多麈尾空。
心宗本无碍，问学岂难同。','',''),('quantangshi-40693','龙池春草','李洞','quantangshi','','卷41','龙池清禁里，芳草傍池春。
旋长方遮岸，全生不染尘。
和风轻动色，湛露静流津。
浅得承天步，深疑遶御轮。
鱼寻倒影没，花带湿光新。
肯学长河畔，绵绵思远人。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-40694','秋宿梓州牛头寺','李洞','quantangshi','','卷41','月去檐三尺，川云入寺楼。
灵山顿离众，列宿不多稠。
篆字焚初缺，翻经诵若流。
窗闲二江冷，帘卷半空秋。
诏散松梢别，棊终竹节收。
静增双阙念，高并五翁游。
鹤梦生红日，云闲锁梓州。
望空工部眼，搔乱广文头。
石室僧调马，银河客问牛。
晓楼归下界，大地一浮沤。','',''),('quantangshi-40695','送韦太尉自坤维除广陵','李洞','quantangshi','','卷41','全蜀拜扬州，征东辍武侯。
直来万里月，旁到五峰秋。
幢冷遮高雪，旗闲卓乱流。
谢朝明主喜，登省旧寮愁。
隔海城通舶，连河市响楼。
千官倚元老，虚梦法云游。','',''),('quantangshi-40696','赠曹郎中崇贤所居','李洞','quantangshi','','卷41','闲坊宅枕穿宫水，听水分衾盖蜀缯。
药杵声中捣残梦，茶铛影里煮孤灯。
刑曹树荫千年井，华岳楼开万仞冰。
诗句变风官渐紧，夜涛舂断海边藤。','',''),('quantangshi-40697','赠昭应沈少府','李洞','quantangshi','','卷41','行宫接县判云泉，袍色虽青骨且仙。
鄠杜忆过梨栗墅，潇湘曾棹雪霜天。
华山僧别留茶鼎，渭水人来锁钓船。
东送西迎终几考，新诗觅得两三联。','',''),('quantangshi-40698','上司空员外','李洞','quantangshi','','卷41','禅心高卧似疎慵，诗客经过不厌重。
藤杖几携量碛雪，玉鞭曾把数嵩峰。
夜眠古巷当城月，秋直清曹入省钟。
禹凿故山归未得，河声暗老两三松。','',''),('quantangshi-40699','叙旧游寄栖白','李洞','quantangshi','','卷41','老着重袍坐石房，竺经休讲白眉长。
省冲鼍没投江岛，曾看鱼飞倚海樯。
晓炙冻盂原日气，夜挑莲椀禁灯光。
吟诗五岭寻无可，倏忽如今四十霜。','',''),('quantangshi-40700','哭栖白供奉','李洞','quantangshi','','卷41','闻说孤窗坐化时，白莎萝雨滴空池。
吟诗堂里秋关影，礼佛灯前夜照碑。
贺雪已成金殿梦，看涛终负石桥期。
逢山对月还惆怅，争得无言似祖师。','',''),('quantangshi-40701','赠入内供奉僧','李洞','quantangshi','','卷41','内殿谈经惬帝怀，沃州归隐计全乖。
数条雀尾来南海，一道蝉声噪御街。
石枕纹含山里叶，铜瓶口塞井中柴。
因逢夏日西明讲，不觉宫人拔凤钗。','',''),('quantangshi-40702','感恩书事寄上集义司徒相公','李洞','quantangshi','','卷41','积雪峰西遇奖称，半家寒骨起沟塍。
镇时贤相回人镜，报德慈亲点佛灯。
授钺已闻诸国静，坐筹重见大河澄。
功居第一图烟阁，依旧终南满杜陵。','',''),('quantangshi-40703','赠永崇李将军充襄阳制置使','李洞','quantangshi','','卷41','拜官门外发辉光，宿卫阴符注几行。
行处近天龙尾滑，猎时陪帝马鬃香。
九城王气生旗队，万里寒风入箭疮。
从此浩然声价歇，武中还有李襄阳。','',''),('quantangshi-40704','寄淮海惠泽上人','李洞','quantangshi','','卷41','海涛痕满旧征衣，长忆初程宿翠微。
竹里桥鸣知马过，塔中灯露见鸿飞。
眉毫别后应盈尺，岩木居来定几围。
他日愿师容一榻，煎茶埽地学忘机。','',''),('quantangshi-40705','春日隐居官舍感怀','李洞','quantangshi','','卷41','风吹烧烬杂汀沙，还似青溪旧寄家。
入户竹生牀下叶，隔窗莲谢镜中花。
苔房毳客论三学，雪岭巢禽看两衙。
销得人间无限事，江亭月白诵南华。','',''),('quantangshi-40706','春日即事寄一二知己','李洞','quantangshi','','卷41','浴马池西一带泉，开门景物似樊川。
朱衣暎水人归县，白羽遗泥鹤上天。
索米夜烧风折木，无车春养雪藏鞭。
缙绅处士知章句，忍使孤窗枕泪眠。','',''),('quantangshi-40707','废寺闲居寄怀一二罢举知己','李洞','quantangshi','','卷41','病居废庙冷吟烟，无力争飞类病蝉。
槐省老郎蒙主弃，月陂孤客望谁怜。
税房兼得调猿石，租地仍分浴鹤泉。
处世堪惊又堪愧，一坡山色不论钱。','',''),('quantangshi-40708','题尼大德院','李洞','quantangshi','','卷41','云鬟早岁断金刀，戒律曾持五百条。
台上灯红莲叶密，眉间毫白黛痕销。
绣成佛国银为地，画出王城雪覆桥。
清净高楼松桧寺，世雄翻愧自低腰。','',''),('quantangshi-40709','怀张乔张霞','李洞','quantangshi','','卷41','西风吹雨叶还飘，忆我同袍隔海涛。
江塔眺山青入佛，边城履雪白连雕。
身离世界归天竺，影挂虚空度石桥。
应念无成独流转，嬾磨铜片鬓毛焦。','',''),('quantangshi-40710','赠徐山人','李洞','quantangshi','','卷41','徐生何代降坤维，曾伴园公采紫芝。
瓦砾变黄忧世换，髭须放白怕人疑。
山房古竹麄于树，海岛灵童寿等龟。
知叹有唐三百载，光阴未抵一先棊。','',''),('quantangshi-40711','寄南岳僧','李洞','quantangshi','','卷41','新秋日后晒书天，白日当松影却圆。
五字句求方寸佛，一条街擘两行蝉。
不曾着事于机内，长合教山在眼前。
花落俦公房外石，调猿弄虎叹无缘。','',''),('quantangshi-40712','华山','李洞','quantangshi','','卷41','碧山长冻地长秋，日夕泉源聒华州。
万户烟侵关令宅，四时云在使君楼。
风驱雷电临河震，鹤引神仙出月游。
峰顶高眠灵药熟，自无霜雪上人头。','',''),('quantangshi-40713','和曹监春晴见寄','李洞','quantangshi','','卷41','竺庙邻钟震晓鸦，春阴盖石似仙家。
兰台架列排书目，顾渚香浮瀹茗花。
胶溜石松粘鹤氅，泉离冰井熨僧牙。
功成名着扁舟去，愁覩前题罩碧纱。','',''),('quantangshi-40714','赠三惠大师','李洞','quantangshi','','卷41','枫猿峤角别多时，二教兼修内学师。
药树影中频缀偈，莲峰朵下几窥棊。
游归笋长齐童子，病起巢成露鹤儿。
诏落五天开夏讲，两街人竞礼长眉。','',''),('quantangshi-40715','送醉画王处士','李洞','quantangshi','','卷41','几年乘兴住南吴，狂醉兰舟夜落湖。
别后鹤毛描转细，近来牛角饮还麄。
同餐夏果山何处，共钓秋涛石在无。
关下相逢怪予老，篇章役思绕寰区。','',''),('quantangshi-40716','闻杜鹃','李洞','quantangshi','','卷41','万古潇湘波上云，化为流血杜鹃身。
长疑啄破青山色，秪恐啼穿白日轮。
花落玄宗回蜀道，雨收工部宿江津。
声声犹得到君耳，不见千秋一甑尘。','',''),('quantangshi-40717','赋得送轩辕先生归罗浮山','李洞','quantangshi','','卷41','旧山归隐浪摇青，绿鬓山童一帙经。
诗帖布帆猿鸟看，药煎金鼎鬼神听。
洞深头上聆仙语，船静鼻中闻海腥。
此处先生应不住，吾君南望漫劳形。','',''),('quantangshi-40718','送包处士','李洞','quantangshi','','卷41','秋思枕月卧潇湘，寄宿慈恩竹里房。
性急却于棊上慢，身闲未免药中忙。
休抛手网惊龙睡，曾挂头巾拂鸟行。
闻说石门君旧隐，寒峰溅瀑坏书堂。','',''),('quantangshi-40719','赠庞炼师','李洞','quantangshi','','卷41','家住涪江汉语娇，一声歌戛玉楼箫。
睡融春日柔金缕，妆发秋霞战翠翘。
两脸酒醺红杏妬，半胸酥嫩白云饶。
若能携手随仙令，皎皎银河渡鹊桥。','',''),('quantangshi-40720','送友罢举赴边职','李洞','quantangshi','','卷41','出剡篇章入洛文，无人细读叹俱焚。
莫辞秉笏随红斾，便好携家住白云。
过水象浮蛮境见，隔江猿呌汉州闻。
高谈阔略陈从事，盟誓边庭壮我军。','',''),('quantangshi-40721','病猿','李洞','quantangshi','','卷41','瘦缠金锁惹朱楼，一别巫山树几秋。
寒想蜀门清露滴，暖怀湘岸白云流。
罢抛檐果沉僧井，休拗崖冰溅客舟。
啼过三声应有泪，画堂深不彻王侯。','',''),('quantangshi-40722','毙驴','李洞','quantangshi','','卷41','蹇驴秋毙瘗荒田，忍把敲吟旧竹鞭。
三尺焦桐背残月，一条藜杖卓寒烟。
通吴白浪宽围果，倚蜀青山峭入天。
如画海门搘肘望，阿谁家卖钓鱼船。','',''),('quantangshi-40723','宿叶公棋阁','李洞','quantangshi','','卷41','带风棊阁竹相敲，局莹无尘拂树梢。
日到长天征未断，钟来岳顶劫须抛。
挑灯雪客栖寒店，供茗溪僧爇废巢。
因悟修身试贪教，不须焚火向三茅。','',''),('quantangshi-40724','送郄先辈归觐华阴','李洞','quantangshi','','卷41','桂枝博得凤栖枝，欢觐家僮舞翠微。
僧向瀑泉声里贺，鸟穿仙掌指间飞。
休停砚笔吟荒庙，永别灯笼赴锁闱。
骚雅近来颓丧甚，送君傍觉有光辉。','',''),('quantangshi-40725','赠可上人','李洞','quantangshi','','卷41','寺门和鹤倚香杉，月吐秋光到思嚵。
将法传来穿泱漭，把诗吟去入嵌岩。
糢糊书卷烟岚滴，狼籍衣裳瀑布缄。
不断清风牙底嚼，无因内殿得名衔。','',''),('quantangshi-40726','东川高仆射','李洞','quantangshi','','卷41','油幢影里拜清风，十里貔貅一片雄。
三印锁开霜满地，四门关定月当空。
泉浮山叶人家过，诏惹罏香鸟道通。
新起画楼携客上，弦歌筵内海榴红。','',''),('quantangshi-40727','宿成都松溪院','李洞','quantangshi','','卷41','松持节操溪澄性，一炷烟岚压寺隅。
翡翠鸟飞人不见，琉璃瓶贮水疑无。
夜闻子落真山雨，晓汲波圆入画图。
尘拥蜀城抽锁后，此中犹梦在江湖。','',''),('quantangshi-40728','吊曹监','李洞','quantangshi','','卷41','宅上愁云吹不散，桂林诗骨葬云根。
满楼山色供邻里，一洞松声付子孙。
甘露施衣封泪点，秘书取集印苔痕。
吟魂醉魄归何处，御水呜呜夜遶门。','',''),('quantangshi-40729','赠长安毕郎中','李洞','quantangshi','','卷41','高门寒沼水连云，鹭识朱衣傍主人。
地肺半边晴带雪，天街一面静无尘。
朝回座客酬琴价，衙退留僧写鹤真。
从此几迁为计相，蓬莱三刻奏东巡。','',''),('quantangshi-40730','寄东蜀幕中友','李洞','quantangshi','','卷41','官亭池碧海榴殷，遥想清才倚画栏。
柳絮涨天笼地暖，角声经雨透云寒。
晓侵台座香烟湿，夜草军书蜡炬干。
为话门人吟太苦，风摧兰秀一枝残。','',''),('quantangshi-40731','曲江渔父','李洞','quantangshi','','卷41','儿孙闲弄雪霜髯，浪颭南山影入檐。
卧稳篷舟龟作枕，病来茅舍网为帘。
值春游子怜莼滑，通蜀行人说鲙甜。
数尺寒丝一竿竹，岂知浮世有猜嫌。','',''),('quantangshi-40732','和刘驾博士赠庄严律禅师','李洞','quantangshi','','卷41','人言紫绶有光辉，不二心观似草衣。
尘劫自营还自坏，禅门无住亦无归。
松根穴蚁通山远，塔顶巢禽见海微。
每话南游偏起念，五峰波上入船扉。','',''),('quantangshi-40733','智新上人话旧','李洞','quantangshi','','卷41','蟋蟀灯前话旧游，师经几夏我经秋。
金陵市合月光里，甘露门开峰朵头。
晴眺远帆飞入海，夜禅阴火吐当楼。
相看未得东归去，满壁寒涛泻白鸥。','',''),('quantangshi-40734','和淮南太尉留题凤州王氏别业','李洞','quantangshi','','卷41','清秋看长鹭雏成，说向湘僧亦动情。
节屋折将松上影，印龛移锁月中声。
野人陪赏增诗价，太尉因居着谷名。
闲想此中遗胜事，宿斋吟遶凤池行。','',''),('quantangshi-40735','乙酉岁自蜀随计趂试不及','李洞','quantangshi','','卷41','客卧涪江蘸月厅，知音唤起进趋生。
寒梅折后方离蜀，腊月圆前未到京。
风卷坏亭羸仆病，雪糊危栈蹇驴行。
文昌一试应关分，岂校褒斜两日程。','',''),('quantangshi-40736','龙州韦郎中先梦六赤后因打叶子以诗上','李洞','quantangshi','','卷41','红蜡香烟扑画楹，梅花落尽庾楼清。
光辉圆魄衔山冷，彩镂方牙着腕轻。
宝帖牵来狮子镇，金盆引出凤凰倾。
微黄喜兆庄周梦，六赤重新掷印成。','',''),('quantangshi-40737','和寿中丞伤猿','李洞','quantangshi','','卷41','遗挂朱栏锁半寻，清声难买恨黄金。
悬崖接果今何在，浅井窥星影已沉。
归宅叶铺曾睡石，入朝灯照旧啼林。
小山罢遶随湘客，高树休升对岳禽。
天竺省怜伤倍切，亲知宽和思难任。
相门恩重无由报，竟托仙郎日夜吟。','',''),('quantangshi-40738','上灵州令狐相公','李洞','quantangshi','','卷41','征蛮破虏汉功臣，提劒归来万里身。
笑倚凌烟金柱看，形容憔悴老于真。','',''),('quantangshi-40739','寓言','李洞','quantangshi','','卷41','三千宫女露蛾眉，笑煮黄金日月迟。
麟凤隔云攀不及，空山惆怅夕阳时。','',''),('quantangshi-40740','客亭对月','李洞','quantangshi','','卷41','游子离魂陇上花，风飘浪卷遶天涯。
一年十二度圆月，十一回圆不在家。','',''),('quantangshi-40741','宿鄠郊赠罗处士','李洞','quantangshi','','卷41','川静星高栎已枯，南山落石水声麤。
白云钓客窗中宿，卧数嵩峰听五湖。','',''),('quantangshi-40742','有寄','李洞','quantangshi','','卷41','爱酒耽棊田处士，弹琴咏史贾先生。
御沟临岸有云石，不见鹤来何处行。','',''),('quantangshi-40743','送三藏归西天国','李洞','quantangshi','','卷41','十万里程多少碛，沙中弹舌授降龙。
五天到日应头白，月落长安半夜钟。','',''),('quantangshi-40744','金陵怀古','李洞','quantangshi','','卷41','古来无此战争功，日日戈船卷海风。
一遇灵鳌开睡眼，六朝灰尽九江空。','',''),('quantangshi-40745','长安县厅','李洞','quantangshi','','卷41','主人寂寞客屯邅，愁绝终南满案前。
乞取中庭藤五尺，为君高斸扣青天。','',''),('quantangshi-40746','题晰上人贾岛诗卷','李洞','quantangshi','','卷41','贾生诗卷惠休装，百叶莲花万里香。
供得半年吟不足，长须字字顶司仓。','',''),('quantangshi-40747','送僧清演归山','李洞','quantangshi','','卷41','毛褐斜肩背负经，晓思吟入窦山青。
峰前野水横官道，踏着秋天三四星。','',''),('quantangshi-40748','赠僧','李洞','quantangshi','','卷41','不羡王公与贵人，唯将云鹤自相亲。
闲来石上观流水，欲洗禅衣未有尘。','',''),('quantangshi-40749','题学公院池莲','李洞','quantangshi','','卷41','竹引山泉玉甃池，栽莲莫怪藕生丝。
如何不似麻衣客，坐对秋风待一枝。','',''),('quantangshi-40750','山居喜友人见访','李洞','quantangshi','','卷41','入云晴斸茯苓还，日暮逢迎木石间。
看待诗人无别物，半潭秋水一房山。','',''),('quantangshi-40751','秋宿长安韦主簿厅','李洞','quantangshi','','卷41','水木清凉夜直厅，愁人楼上唱寒更。
坐劳同步帘前月，鼠动牀头印锁声。','',''),('quantangshi-40752','冬忆友人','李洞','quantangshi','','卷41','吟上山前数竹枝，叶翻似雪落霏霏。
枕前明月谁动影，睡里惊来不觉归。','',''),('quantangshi-40753','怀圭峰影林泉','李洞','quantangshi','','卷41','吾家旧物贾生传，入内遥分锡杖泉。
鹤去帝移宫女散，更堪呜咽过楼前。','',''),('quantangshi-40754','赠青龙印禅师','李洞','quantangshi','','卷41','雨涩秋刀剃雪时，庵前曾礼草堂师。
居人昨日相过说，鹤已生孙竹满池。','',''),('quantangshi-40755','戏赠侯常侍','李洞','quantangshi','','卷41','葛洪卷与江淹赋，名动天边傲石居。
两蜀词人多载后，同君讳却马相如。','',''),('quantangshi-40756','绣岭宫词','李洞','quantangshi','','卷41','春日迟迟春草绿，野棠开尽飘香玉。
绣岭宫前鹤发翁，犹唱开元太平曲。','',''),('quantangshi-40757','中秋月','李洞','quantangshi','','卷41','九十日秋色，今秋已半分。
孤光吞列宿，四面绝微云。
众木排疎影，寒流叠细纹。
遥遥望丹桂，心绪更纷纷。','',''),('quantangshi-40758','宿书僧院','李洞','quantangshi','','卷41','夜水笔前澄，时推外学能。
书成百个字，庭转几遭灯。
寄墨大坛吏，分牋蜀国僧。
为题江寺塔，牌挂入云层。','',''),('quantangshi-40759','雪','李洞','quantangshi','','卷41','迢迢来极塞，连阙谓风吹。
禅客呵金锡，征人擘冻旗。
细填虫穴满，重压鹤巢欹。
有影晴飘野，无声夜落池。
正繁秦甸暖，渐厚楚宫饥。
冻挹分泉涩，光凝二阁痴。
踏遗兰署迹，听起石门思。
用表丰年瑞，无令埽玉墀。','',''),('quantangshi-40760','述怀二十韵献覃怀相公','李洞','quantangshi','','卷41','帝梦求良弼，生申属圣明。
青云县器业，白日贯忠贞。
霭霭随春动，忻忻共物荣。
静宜浮竞息，坐觉好风生。
万国闻应跃，千门望尽倾。
瑞含杨柳色，气变管弦声。
百辟寻知度，三阶正有程。
鲁儒规蕴藉，周诰美和平。
碧水遗幽抱，朱丝寄远情。
风流秦印绶，仪表汉公卿。
忠谠期登用，回邪自震惊。
云开长劒倚，路绝一峰横。
九野方无事，沧溟本不争。
国将身共计，心与众为城。
早晚中条下，红尘一顾清。
南潭容伴鹤，西笑忽迁莺。
折树恩难报，怀仁命甚轻。
二年犹困辱，百口望经营。
未在英侯选，空劳短羽征。
知音初相国，从此免长鸣。','',''),('quantangshi-40761','岁暮自广江至新兴往复中题峡山寺','李洞','quantangshi','','卷41','薄暮缘西峡，停桡一访僧。
鹭巢行卧柳，猿饮倒垂藤。
水曲岩千叠，云深树百层。
山风寒殿磬，溪雨夜船灯。
滩涨危槎没，泉冲怪石崩。
中台一襟泪，岁杪别良朋。','',''),('quantangshi-40762','冬日送凉州刺史','李洞','quantangshi','','卷41','宠饯西门外，双旌出汉陵。
未辞金殿日，已梦雪山灯。
地远终峰尽，天寒朔气凝。
新年行已到，旧典听难胜。
吏扫盘雕影，人遮散马乘。
移军驼驮角，下塞掾河冰。
猎近昆仑兽，吟招碛石僧。
重输右藏实，方见左车能。
兵聚边风急，城宽夜月澄。
连营烟火岭，望诏几回登。','',''),('quantangshi-40763','过贾浪仙旧地','李洞','quantangshi','','卷41','鹤外唐来有谪星，长江东注冷沧溟。
境搜松雪仙人岛，吟歇林泉主簿厅。
片月已能临榜黑，遥天何益抱坟青。
年年谁不登高第，未胜骑驴入画屏。','',''),('quantangshi-40764','句','李洞','quantangshi','','卷41','公道此时如不得，昭陵恸哭一生休。','',''),('quantangshi-40765','酬友生早秋','求','quantangshi','','卷41','彤云将欲罢，蝉柳响如秋。
雾散九霄近，日程三伏愁。
残阳宿雨霁，高浪碎沙沤。
祛足余旬后，分襟任自由。','',''),('quantangshi-40766','晓发','求','quantangshi','','卷41','旅馆候天曙，整车趋远程。
几处晓钟断，半桥残月明。
沙上鸟犹在，渡头人未行。
去去古时道，马嘶三两声。','',''),('quantangshi-40767','客行','求','quantangshi','','卷41','上山下山去，千里万里愁。
树色野桥暝，雨声孤馆秋。
南北眼前道，东西江畔舟。
世人重金玉，无金徒远游。','',''),('quantangshi-40768','题郑处士隐居','求','quantangshi','','卷41','不信最清旷，及来愁已空。
数点石泉雨，一溪霜叶风。
业在有山处，道成无事中。
酌尽一尊酒，病夫颜亦红。','',''),('quantangshi-40769','古寺','求','quantangshi','','卷41','路傍古时寺，寥落藏金容。
破塔有寒草，坏楼无晓钟。
乱纸失经偈，断碑分篆踪。
日暮月光吐，绕门千树松。','',''),('quantangshi-40770','赠着上人','求','quantangshi','','卷41','掩门江上住，尽日更无为。
古木坐禅处，残星鸣磬时。
水浇冰滴滴，珠数落累累。
自有闲行伴，青藤杖一枝。','',''),('quantangshi-40771','马嵬感事','求','quantangshi','','卷41','冷气生深殿，狼星渡远关。
九城鼙鼓内，千骑道途间。
凤髻随秋草，銮舆入暮山。
恨多留不得，悲泪满龙颜。','',''),('quantangshi-40772','赠行如上人','求','quantangshi','','卷41','不知名利苦，念佛老岷峨。
衲补云千片，香烧印一窠。
恋山人事少，怜客道心多。
日日斋钟后，高悬滤水罗。','',''),('quantangshi-40773','送友人归邛州','求','quantangshi','','卷41','鹤鸣山下去，满箧荷瑶琨。
放马荒田草，看碑古寺门。
渐寒沙上雨，欲暝水边村。
莫忘分襟处，梅花扑酒尊。','',''),('quantangshi-40774','和舒上人山居即事','求','quantangshi','','卷41','败叶填溪路，残阳过野亭。
仍弹一滴水，更读两张经。
暝鸟烟中见，寒钟竹里听。
不多山下去，人世尽膻腥。','',''),('quantangshi-40775','发邛州寄友人','求','quantangshi','','卷41','茫茫驱一马，自叹又何之。
出郭见山处，待船逢雨时。
晓鸡鸣野店，寒叶堕秋枝。
寂寞前程去，闲吟欲共谁。','',''),('quantangshi-40776','舟行夜泊夔州','求','quantangshi','','卷41','维舟镜面中，回对白盐峰。
夜静沙堤月，天寒水寺钟。
故园何日到，旧友几时逢。
欲作还家梦，青山一万重。','',''),('quantangshi-40777','山东兰若遇静公夜归','求','quantangshi','','卷41','松门一径微，苔滑往来稀。
半夜闻钟后，浑身带雪归。
问寒僧接杖，辨语犬衔衣。
又是安禅去，呼童闭竹扉。','',''),('quantangshi-40778','边将','求','quantangshi','','卷41','三千护塞儿，独自滞边陲。
老向二毛见，秋从一叶知。
地寒乡思苦，天暮角声悲。
却被交亲笑，封侯未有期。','',''),('quantangshi-40779','秋寄□江舒公','求','quantangshi','','卷41','故人何处望，秋色满江濆。
入水溪虫乱，过桥山路分。
鹤归松上月，僧入竹间云。
莫惜中宵磬，从教梦里闻。','',''),('quantangshi-40780','题杨山人隐居','求','quantangshi','','卷41','深山道者家，门户带烟霞。
绿缀沿岩草，红飘落水花。
半庭栽小树，一径扫平沙。
往往溪边坐，持竿到日斜。','',''),('quantangshi-40781','夜上隐居寺','求','quantangshi','','卷41','寻师拟学空，空住虎磎东。
千里照山月，一枝惊鹤风。
年如流去水，山似转来蓬。
尽日都无事，安禅石窟中。','',''),('quantangshi-40782','友人见访不值因寄','求','quantangshi','','卷41','门户寒江近，篱墙野树深。
晚风摇竹影，斜日转山阴。
砌觉披秋草，牀惊倒古琴。
更闻邻舍说，一只鹤来寻。','',''),('quantangshi-40783','涂次偶作','求','quantangshi','','卷41','岁月客中销，崎岖力自招。
问人寻野寺，牵马渡危桥。
为雨疑天晚，因山觉路遥。
前程何处是，一望又迢迢。','',''),('quantangshi-40784','送友人江行之庐山肄业','求','quantangshi','','卷41','蜀国初开棹，庐峰拟拾萤。
兽皮裁褥暖，莲叶制衣馨。
楚水秋来碧，巫山雨后青。
莫教衔凤诏，三度到中庭。','',''),('quantangshi-40785','山居偶作','求','quantangshi','','卷41','趋名逐利身，终日走风尘。
还到水边宅，却为山下人。
僧教开竹户，客许戴纱巾。
且喜琴书在，苏生未厌贫。','',''),('quantangshi-40786','赠道者','求','quantangshi','','卷41','披霞戴鹿胎，岁月不能催。
饭把琪花煮，衣将藕叶裁。
鹤从归日养，松是小时栽。
往往樵人见，溪边洗药来。','',''),('quantangshi-40787','邛州水亭夜宴送顾非熊之官','求','quantangshi','','卷41','寂寞邛城夜，寒塘对庾楼。
蜀关蝉已噪，秦树叶应秋。
道路连天远，笙歌到晓愁。
不堪分袂后，残月正如鈎。','',''),('quantangshi-40788','题青城山范贤观','求','quantangshi','','卷41','数里缘山不厌难，为寻真诀问黄冠。
苔铺翠点仙桥滑，松织香梢古道寒。
昼傍绿畦薅嫩玉，夜开红竈拈新丹。
钟声已断泉声在，风动茅花月满坛。','',''),('quantangshi-40789','送僧讲罢归山','求','quantangshi','','卷41','休将如意辩真空，吹尽天花任晓风。
共看玉蟾三皎洁，独悬金锡一玲珑。
岩间松桂秋烟白，江上楼台晚日红。
依旧曹溪念经处，野泉声在草堂东。','',''),('quantangshi-40790','题友人寓居','求','quantangshi','','卷41','寓居无不在天涯，莫恨秦关道路赊。
缭绕城边山是蜀，弯环门外水名巴。
黄头卷席宾初散，白鼻嘶风日欲斜。
何处一声金磬发，古松南畔有僧家。','',''),('quantangshi-40791','伤张玖秀才','求','quantangshi','','卷41','铜梁剑阁几区区，十上探珠不见珠。
卞玉影沈沙草暗，骅骝声断陇城孤。
入关词客秋怀友，出户孀妻晓望夫。
吴水楚山千万里，旅魂归到故乡无。','',''),('quantangshi-40792','题李少府别业','求','quantangshi','','卷41','寻得仙家不姓梅，马嘶人语出尘埃。
竹和庭上春烟动，花带溪头晓露开。
绕岸白云终日在，傍松黄鹤有时来。
何年亦作围碁伴，一到松间醉一回。','',''),('quantangshi-40793','赠楚公','求','quantangshi','','卷41','曾闻半偈雪山中，贝叶飜时理尽通。
般若恒添持戒力，落叉谁算念经功。
云间晓月应难染，海上虚舟自信风。
长说满庭花色好，一枝红是一枝空。','',''),('quantangshi-40794','赠王山人','求','quantangshi','','卷41','红藤一柱脚常轻，日日缘溪入谷行。
山下有家身未老，竈前无火药初成。
经秋少见闲人说，带雨多闻野鹤鸣。
知到蓬莱难再访，问何方法得长生。','',''),('quantangshi-40795','庭竹','求','quantangshi','','卷41','月笼翠叶秋承露，风亚繁梢暝扫烟。
知道雪霜终不变，永留寒色在庭前。','',''),('quantangshi-40796','题常乐寺','求','quantangshi','','卷41','桂冷香闻十里间，殿台浑不似人寰。
日斜回首江头望，一片晴云落后山。','',''),('quantangshi-40797','题刘炼师归山','求','quantangshi','','卷41','风急云轻鹤背寒，洞天谁道却归难。
千山万水瀛洲路，何处烟飞是醮坛。','',''),('quantangshi-40798','酬舒公见寄','求','quantangshi','','卷41','无客不言云外见，为文长遣世间知。
一声松径寒吟后，正是前山雪下时。','',''),('quantangshi-40799','巫山下作','求','quantangshi','','卷41','细腰宫尽旧城摧，神女归山更不来。
唯有楚江斜日里，至今犹自绕阳台。','',''),('quantangshi-40800','句','求','quantangshi','','卷41','恰似有龙深处卧，被人惊起黑云生。','',''),('quantangshi-40801','书怀','于鄴','quantangshi','','卷41','长安多路岐，西去欲何依。
浮世祗如此，旧山长忆归。
自离京国久，应已故人稀。
好与孤云住，孤云无是非。','',''),('quantangshi-40802','书情','于鄴','quantangshi','','卷41','负郭有田在，年年长废耕。
欲磨秋镜净，恐见白头生。
未作一旬别，已过千里程。
不知书与劒，十载两无成。','',''),('quantangshi-40803','涂中作','于鄴','quantangshi','','卷41','西南千里程，处处有车声。
若使地无利，始应人不营。
天涯犹马到，石迹尚尘生。
如此未曾息，蜀山终冀平。','',''),('quantangshi-40804','春过函谷关','于鄴','quantangshi','','卷41','几度作游客，客行长苦辛。
愁看函谷路，老尽布衣人。
岁远关犹固，时移草亦春。
何当名利息，遣此绝征轮。','',''),('quantangshi-40805','褒中即事','于鄴','quantangshi','','卷41','风吹残雨歇，云去有烟霞。
南浦足游女，绿苹应发花。
远钟当半夜，明月入千家。
不作故乡梦，始知京洛赊。','',''),('quantangshi-40806','岁暮还家','于鄴','quantangshi','','卷41','东西流不驻，白日与车轮。
残雪半成水，微风应欲春。
几经他国岁，已减故乡人。
回首长安道，十年空苦辛。','',''),('quantangshi-40807','还家','于鄴','quantangshi','','卷41','为客忆归舍，归来还寂寥。
壮时看欲过，白首固非遥。
独酌几回醉，此愁终不销。
犹残鸡与犬，驱去住山椒。','',''),('quantangshi-40808','题华山麻处士所居','于鄴','quantangshi','','卷41','贵贱各扰扰，皆逢朝市间。
到此马无迹，始知君独闲。
冰破听敷水，雪晴看华山。
西风寂寥地，唯我坐忘还。','',''),('quantangshi-40809','天南怀故人','于鄴','quantangshi','','卷41','独行千里尘，轧轧转征轮。
一别已多日，总看成老人。
洞庭雪不下，故国草应春。
三月烟波暖，南风生绿苹。','',''),('quantangshi-40810','路傍草','于鄴','quantangshi','','卷41','春至始青青，香车碾已平。
不知山下处，来向路傍生。
每岁有人在，何时无马行。
应随尘与土，吹满洛阳城。','',''),('quantangshi-40811','秋夕闻雁','于鄴','quantangshi','','卷41','星汉欲沈尽，谁家砧未休。
忽闻梁雁至，如报杜陵秋。
千树又黄叶，几人新白头。
洞庭今夜客，一半却登舟。','',''),('quantangshi-40812','洛中有怀','于鄴','quantangshi','','卷41','潺潺伊洛河，寂寞少恩波。
銮驾久不幸，洛阳春草多。','',''),('quantangshi-40813','送魏山韦处士','于鄴','quantangshi','','卷41','阴阴亭际间，相顾惨离颜。
一片云飞去，嵯峨空魏山。','',''),('quantangshi-40814','白樱桃','于鄴','quantangshi','','卷41','王母阶前种几株，水晶帘内看如无。
只应汉武金盘上，泻得珊珊白露珠。','',''),('quantangshi-40815','白樱树','于鄴','quantangshi','','卷41','记得花开雪满枝，和蜂和蝶带花移。
如今花落游蜂去，空作主人惆怅诗。','',''),('quantangshi-40816','下第不胜其忿题路左佛庙','于鄴','quantangshi','','卷41','雀儿未逐扬风高，下视鹰鹯意气豪。
自谓能生千里足，黄昏依旧委蓬蒿。','',''),('quantangshi-40817','感怀','于鄴','quantangshi','','卷41','东风吹草色，空使客蹉跎。
不设太平险，更应游子多。
几伤行处泪，一曲醉中歌。
尽向青门外，东随渭水波。','',''),('quantangshi-40818','游中梁山','于鄴','quantangshi','','卷41','僻地好泉石，何人曾陆沈。
不知青嶂外，更有白云深。
因此见乔木，几回思旧林。
殷勤猨与鸟，唯我独何心。','',''),('quantangshi-40819','寻山','于鄴','quantangshi','','卷41','到此绝车轮，萋萋草树春。
青山如有利，白石亦成尘。
水阔应无路，松深不见人。
如知巢与许，千载迹犹新。','',''),('quantangshi-40820','宿江口','于鄴','quantangshi','','卷41','南渡人来绝，喧喧雁满沙。
自生江上月，长有客思家。
半夜下霜岸，北风吹荻花。
自惊归梦断，不得到天涯。','',''),('quantangshi-40821','秋夜达萧关','于鄴','quantangshi','','卷41','扰扰浮梁路，人忙月自闲。
去年为塞客，今夜宿萧关。
辞国几经岁，望乡空见山。
不知江叶下，又作布衣还。','',''),('quantangshi-40822','斜谷道','于鄴','quantangshi','','卷41','乱峰连叠嶂，千里绿峨峨。
蜀国路如此，游人车亦过。
远烟当驿歛，骤雨逐风多。
独忆紫芝叟，临风歌旧歌。','',''),('quantangshi-40823','过百牢关贻舟中者','于鄴','quantangshi','','卷41','蜀国少平地，方思京洛间。
远为千里客，来度百牢关。
帆影清江水，铃声碧草山。
不因名与利，尔我各应闲。','',''),('quantangshi-40824','客中览镜','于鄴','quantangshi','','卷41','何当开此镜，即见发如丝。
白日急于水，少年能几时。
每逢芳草处，长返故园迟。
所以多为客，蹉跎欲怨谁。','',''),('quantangshi-40825','长安逢隐者','于鄴','quantangshi','','卷41','征车千里至，碾遍六街尘。
向此有营地，忽逢无事人。
昔时颜未改，浮世路多新。
且脱衣沽酒，终南山欲春。','',''),('quantangshi-40826','与僧话旧','于鄴','quantangshi','','卷41','草堂前有山，一见一相宽。
处世贵僧静，青松因岁寒。
他山逢旧侣，尽日话长安。
所以闲行迹，千回绕药栏。','',''),('quantangshi-40827','赠王道士','于鄴','quantangshi','','卷41','日日市朝路，何时无苦辛。
不随丹竈客，终作白头人。
浮世度千载，桃源方一春。
归来华表上，应笑北邙尘。','',''),('quantangshi-40828','匣中琴','于鄴','quantangshi','','卷41','世人无正心，虫网匣中琴。
何以经时废，非为娱耳音。
独令高韵在，谁感隙尘深。
应是南风曲，声声不合今。','',''),('quantangshi-40829','友人亭松','于鄴','quantangshi','','卷41','俛仰不能去，如逢旧友同。
曾因春雪散，见在华山中。
何处有明月，访君听远风。
相将归未得，各占石岩东。','',''),('quantangshi-40830','过洛阳城','于鄴','quantangshi','','卷41','古来利与名，俱在洛阳城。
九陌鼓初起，万车轮已行。
周秦时几变，伊洛水犹清。
二月中桥路，鸟啼春草生。','',''),('quantangshi-40831','客中月','于鄴','quantangshi','','卷41','离家凡几宵，一望一寥寥。
新魄又将满，故乡应渐遥。
独临彭蠡水，远忆洛阳桥。
更有乘舟客，凄然亦驻桡。','',''),('quantangshi-40832','王将军宅夜听歌','于鄴','quantangshi','','卷41','朱槛满明月，美人歌落梅。
忽惊尘起处，疑有凤飞来。
一曲听初彻，几年愁暂开。
东南正云雨，不得见阳台。','',''),('quantangshi-40833','长信宫','于鄴','quantangshi','','卷41','莫问古宫名，古宫空有城。
惟应东去水，不改旧时声。','',''),('quantangshi-40834','高楼','于鄴','quantangshi','','卷41','远天明月出，照此谁家楼。
上有罗衣裳，凉风吹不休。','',''),('quantangshi-40835','和三乡诗','陸貞洞','quantangshi','','卷41','惆怅残花怨暮春，孤鸾舞镜倍伤神。
清词好个干人事，疑是文姬第二身。','',''),('quantangshi-40836','和三乡诗','劉谷','quantangshi','','卷41','兰蕙芬香见玉姿，路傍花笑景迟迟。
苎萝山下无穷意，并在三乡惜别时。','',''),('quantangshi-40837','和三乡诗','王祝','quantangshi','','卷41','女几山前岚气低，佳人留恨此中题。
不知云雨归何处，空使王孙见即迷。','',''),('quantangshi-40838','和三乡诗','王滌','quantangshi','','卷41','浣纱游女出关东，旧迹新词一梦中。
槐陌柳亭何限事，年年回首向春风。','',''),('quantangshi-40839','和三乡诗','韋冰','quantangshi','','卷41','来时欢笑去时哀，家国迢迢向越台。
待写百年幽思尽，故宫流水莫相催。','',''),('quantangshi-40840','和三乡诗','李昌鄴','quantangshi','','卷41','红粉萧娘手自题，分明幽怨发云闺。
不应更学文君去，泣向残花归剡溪。','',''),('quantangshi-40841','和三乡诗','王碩','quantangshi','','卷41','无姓无名越水滨，芳词空怨路傍人。
莫教才子偏惆怅，宋玉东家是旧邻。','',''),('quantangshi-40842','和三乡诗','李縞','quantangshi','','卷41','会稽王谢两风流，王子沉沦谢女愁。
归思若随文字在，路傍空为感千秋。','',''),('quantangshi-40843','和三乡诗','張綺','quantangshi','','卷41','洛川依旧好风光，莲帐无因见女郎。
云雨散来音信断，此生遗恨寄三乡。','',''),('quantangshi-40844','和三乡诗','高衢','quantangshi','','卷41','南北千山与万山，轩车谁不思乡关。
独留芳翰悲前迹，陌上恐伤桃李颜。','',''),('quantangshi-40845','复覩三乡题处留赠','賈馳','quantangshi','','卷41','壁古字未灭，声长响不绝。
蕙质本如云，松心应耐雪。
耿耿离幽谷，悠悠望瓯越。
杞妇哭夫时，城崩无此说。','',''),('quantangshi-40846','秋入关','賈馳','quantangshi','','卷41','河上微风来，关头树初湿。
今朝关城吏，又见孤客入。
上国谁与期，西来徒自急。','',''),('quantangshi-40847','咏手二首 一','趙光遠','quantangshi','','卷41','妆成皓腕洗凝脂，背接红巾掬水时。
薄雾袖中拈玉斝，斜阳屏上拈青丝。
唤人急拍临前槛，摘杏高揎近曲池。
好是琵琶弦畔见，细圆无节玉参差。','',''),('quantangshi-40848','咏手二首 二','趙光遠','quantangshi','','卷41','拈玉搓琼软复圆，绿窗谁见上琴弦。
慢笼彩笔闲书字，斜指瑶阶笑打钱。
炉面试香添麝炷，舌头轻点贴金钿。
象床珍簟宫棊处，拈定文楸占角边。','',''),('quantangshi-40849','题妓莱儿壁','趙光遠','quantangshi','','卷41','鱼钥兽环斜掩门，萋萋芳草忆王孙。
醉凭青琐窥韩寿，闲掷金梭恼谢鲲。
不夜珠光连玉匣，辟寒钗影落瑶尊。
欲知肠断相思处，役尽江淹别后魂。','',''),('quantangshi-40850','题兴化高田院桥亭','鄭良士','quantangshi','','卷41','到此溪亭上，浮生始觉非。
野僧还惜别，游客亦忘归。
月满千岩静，风清一磬微。
何时脱尘役，杖履愿相依。','',''),('quantangshi-40851','游九鲤湖','鄭良士','quantangshi','','卷41','仄径倾崖不可通，湖岚林霭共溟蒙。
九溪瀑影飞花外，万树春声细雨中。
覆石云闲丹竈冷，采芝人去洞门空。
我来不乞邯郸梦，取醉聊乘郑国风。','',''),('quantangshi-40852','寄富洋院禅者','鄭良士','quantangshi','','卷41','画破青山路一条，走鞭飞盖去何遥。
碍天岩树春先冷，锁院溪云昼不销。
霅上茗芽因客煮，海南沈屑为斋烧。
谁能学得空门士，冷却心灰守寂寥。','',''),('quantangshi-40853','赠翁承赞漆林书堂诗','蕭項','quantangshi','','卷41','轺车故国世应稀，昔日书堂二纪归。
手植松筠同茂盛，身荣金紫倍光辉。
入门邻里喧迎接，列坐儿童见等威。
却对芸窗勤苦处，举头全是锦为衣。','',''),('quantangshi-40854','喜韩少府见访','胡令能','quantangshi','','卷41','忽闻梅福来相访，笑着荷衣出草堂。
儿童不惯见车马，走入芦花深处藏。','',''),('quantangshi-40855','观郑州崔郎中诸妓绣样','胡令能','quantangshi','','卷41','日暮堂前花蘂娇，争拈小笔上牀描。
绣成安向春园里，引得黄莺下柳条。','',''),('quantangshi-40856','小儿垂钓','胡令能','quantangshi','','卷41','蓬头穉子学垂纶，侧坐莓苔草映身。
路人借问遥招手，怕得鱼惊不应人。','',''),('quantangshi-40857','王昭君','胡令能','quantangshi','','卷41','胡风似劒锼人骨，汉月如钩钓胃肠。
魂梦不知身在路，夜来犹自到昭阳。','',''),('quantangshi-40858','望夫石','嚴郾','quantangshi','','卷41','何代提戈去不还，独留形影白云间。
肌肤销尽雪霜色，罗绮点成苔藓斑。
江燕不能传远信，野花空解妬愁颜。
近来岂少征人妇，笑采蘼芜上北山。','',''),('quantangshi-40859','赋百舌鸟','嚴郾','quantangshi','','卷41','此禽轻巧少同伦，我听长疑舌满身。
星未没河先报晓，柳犹黏雪便迎春。
频嫌海燕巢难定，却讶林莺语不真。
莫倚春风便多事，玉楼还有晏眠人。','',''),('quantangshi-40860','永州陪郑太守登舟夜宴席上各赋诗','蔣肱','quantangshi','','卷41','江头朱绂间青衿，岂是仙舟不可寻。
谁敢强登徐稚榻，自怜还学谢安吟。
月凝兰棹轻风起，妓劝金罍尽醉斟。
剪尽蜡红人未觉，归时城郭晓烟深。','',''),('quantangshi-40861','寄远','張逈','quantangshi','','卷41','锦字凭谁达，闲庭草又枯。
夜长灯影灭，天远雁声孤。
蝉鬓凋将尽，虬髯白也无。
几回愁不语，因看朔方图。','',''),('quantangshi-40862','春草凝露','張友正','quantangshi','','卷41','苍苍芳草色，含露对青春。
已赖阳和长，仍慙润泽频。
日临残未滴，风度欲成津。
蕙叶垂偏重，兰丛洗转新。
将行愁裛迳，欲采畏濡身。
独爱池塘畔，清华远袭人。','',''),('quantangshi-40863','锦带佩吴钩','張友正','quantangshi','','卷41','带劒谁家子，春朝紫陌游。
结边霞聚锦，悬处月随钩。
彩缕回文出，雄芒练影浮。
叶依花里艳，霜向锷中秋。
的皪宜骢马，斓斒映绮裘。
应须待报国，一刎月支头。','',''),('quantangshi-40864','山中卧寄卢郎中','伍唐珪','quantangshi','','卷41','十年耕钓水云间，住僻家贫少往还。
一径绿苔凝晓露，满头白发对青山。
野僧采药来医病，樵客携觞为解颜。
空恋旧时恩奖地，无因匍匐出柴关。','',''),('quantangshi-40865','寒食日献郡守','伍唐珪','quantangshi','','卷41','入门堪笑复堪怜，三径苔荒一钓船。
慙愧四隣教断火，不知厨里久无烟。','',''),('quantangshi-40866','上苏使君','伍唐珪','quantangshi','','卷41','江西昔日推韩注，袁水今朝数赵祥。
纵使文翁能待客，终栽桃李不成行。','',''),('quantangshi-40867','赠妓人王福娘','孫棨','quantangshi','','卷41','彩翠仙衣红玉肤，轻盈年在破瓜初。
霞杯醉劝刘郎赌，云髻慵邀阿母梳。
不怕寒侵缘带宝，每忧风举倩持裾。
谩图西子晨妆样，西子元来未得如。','',''),('quantangshi-40868','题妓王福娘墙 一','孫棨','quantangshi','','卷41','移壁回窗费几朝，指镮偷解博红椒。
无端鬬草输邻女，更被拈将玉步摇。','',''),('quantangshi-40869','题妓王福娘墙 二','孫棨','quantangshi','','卷41','寒绣衣裳饷阿娇，新团香兽不禁烧。
东邻起样裙腰阔，剩蹙黄金线几条。','',''),('quantangshi-40870','题妓王福娘墙 三','孫棨','quantangshi','','卷41','试共卿卿语笑初，画堂连遣侍儿呼。
寒肌不耐金如意，白獭为膏郎有无。','',''),('quantangshi-40871','戏李文远','孫棨','quantangshi','','卷41','引君来访洞中仙，新月如眉拂户前。
领取嫦娥攀取桂，便从陵谷一时迁。','',''),('quantangshi-40872','题刘泰娘舍','孫棨','quantangshi','','卷41','寻常凡木最轻樗，今日寻樗桂不如。
汉高新破咸阳后，英俊奔波遂吃虚。','',''),('quantangshi-40873','戏张道人不饮酒','顏蕘','quantangshi','','卷41','言自云山访我来，每闻奇秘觉叨陪。
吾师不饮人间酒，应待流霞即举杯。','',''),('quantangshi-40874','句','顏蕘','quantangshi','','卷41','爽籁尽成鸣凤曲，游人多是弄珠仙。','',''),('quantangshi-40875','秋醉歌','張爲','quantangshi','','卷41','金风飒已起，还是招渔翁。
携酒天姥岑，自弹峄阳桐。
脱却登山履，赤脚翘青筇。
泉声扫残暑，猨臂攀长松。
翠微泛罇绿，苔藓分烟红。
造化处术内，相对数壶空。
醉眠岭上草，不觉夜露浓。
一梦到天晓，始觉一醉中。
皎然梦中路，直到瀛洲东。
初平把我臂，相与骑白龙。
三留对上帝，玉楼十二重。
上帝赐我酒，送我敲金钟。
宝阁香敛苒，琪树寒玲珑。
动叶如笙篁，音律相怡融。
珍重此一醉，百骸出天地。
长如此梦魂，永谢名与利。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-40876','谢别毛仙翁','張爲','quantangshi','','卷41','羸形感神药，削骨生丰肌。
兰炷飘灵烟，妖怪立诛夷。
重覩日月光，何报父母慈。
黄河浊衮衮，别泪流澌澌。
黄河清有时，别泪无收期。','',''),('quantangshi-40877','渔阳将军','張爲','quantangshi','','卷41','霜髭拥颔对穷秋，着白貂裘独上楼。
向北望星提劒立，一生长为国家忧。','',''),('quantangshi-40878','句','張爲','quantangshi','','卷41','到处即闭户，逢君方展眉。','',''),('quantangshi-40879','岑公岩','馬冉','quantangshi','','卷41','南溪有仙涧，咫尺非人间。
泠泠松风下，日暮空苍山。','',''),('quantangshi-40880','诸暨五泄山','周鏞','quantangshi','','卷41','路入苍烟九过溪，九穿岩曲到招提。
天分五溜寒倾北，地秀诸峰翠插西。
凿径破崖来木杪，驾泉鸣竹落榱题。
当年老默无消息，犹有词堂一杖藜。','',''),('quantangshi-40881','赠罗隐','劉贊','quantangshi','','卷41','人皆言子屈，独我谓君非。
明主既难谒，青山何不归？
年虚侵雪鬓，尘枉汚麻衣。
自古逃名者，至今名岂微。','',''),('quantangshi-40882','句','劉贊','quantangshi','','卷41','絮花飞起雪漫漫，长得宫娥带笑看。','',''),('quantangshi-40883','洛阳道','任翻','quantangshi','','卷41','憧憧洛阳道，尘下生青草。
行者岂无家，无人在家老。
鸡鸣前结束，争去恐不早。
百年路傍尽，白日车中晓。
求富江海狭，取贵山岳小。
二端立在途，奔走无由了。','',''),('quantangshi-40884','春晴','任翻','quantangshi','','卷41','楚国多春雨，柴门喜晚晴。
幽人临水坐，好鸟隔花鸣。
野色临空阔，江流接海平。
门前到溪路，今夜月分明。','',''),('quantangshi-40885','秋晚郊居','任翻','quantangshi','','卷41','远声霜后树，秋色水边村。
野径无来客，寒风自动门。
海山藏日影，江月落潮痕。
惆怅高飞晚，年年别故园。','',''),('quantangshi-40886','秋晚途次','任翻','quantangshi','','卷41','秋色满行路，此时心不闲。
孤贫游上国，少壮有衰颜。
众鸟已归树，旅人犹过山。
萧条远林外，风急水潺潺。','',''),('quantangshi-40887','葛仙井','任翻','quantangshi','','卷41','古井碧沈沈，分明见百寻。
味甘传邑内，脉冷应山心。
圆入月轮净，直涵峰影深。
自从仙去后，汲引到如今。','',''),('quantangshi-40888','桐柏观','任翻','quantangshi','','卷41','飘飘云外者，蹔宿聚仙堂。
半夜人无语，中宵月送凉。
鹤归高树静，萤过小池光。
不得多时住，门开是事忙。','',''),('quantangshi-40889','冬暮野寺','任翻','quantangshi','','卷41','江东寒近腊，野寺水天昏。
无酒可销夜，随僧早闭门。
照墙灯影短，着瓦雪声繁。
飘泊仍千里，清吟欲断魂。','',''),('quantangshi-40890','赠济禅师','任翻','quantangshi','','卷41','碧峰秋寺内，禅客已无情。
半顶发根白，一生心地清。
竹房侵月静，石径到门平。
山下尘嚣路，终年誓不行。','',''),('quantangshi-40891','经堕泪碑','任翻','quantangshi','','卷41','羊公传化地，千古事空存。
碑已无文字，人犹敬子孙。
岘山长闭恨，汉水自流恩。
数处烟岚色，分明是泪痕。','',''),('quantangshi-40892','长安冬夜书事','任翻','quantangshi','','卷41','忧来长不寐，往事重思量。
清渭几年客，故衣今夜霜。
春风谁识面，水国但牵肠。
十二门车马，昏明各自忙。','',''),('quantangshi-40893','越江渔父','任翻','quantangshi','','卷41','借问钓鱼者，持竿多少年。
眼明汀岛畔，头白子孙前。
棹入花时浪，灯留雨夜船。
越江深见底，谁识此心坚。','',''),('quantangshi-40894','哭友人','任翻','quantangshi','','卷41','逢着南州史，江边哭问君。
送终时有雪，归葬处无云。
官库惟留劒，隣僧共结坟。
儿孙未成立，谁与集遗文。','',''),('quantangshi-40895','送李衡','任翻','quantangshi','','卷41','羁栖亲故少，远别惜清才。
天畔出相送，路长知未回。
欲销今日恨，强把异乡杯。
君去南堂后，应无客到来。','',''),('quantangshi-40896','宫怨','任翻','quantangshi','','卷41','泪干红落脸，心尽白垂头。
自此方知怨，从来岂信愁。','',''),('quantangshi-40897','惜花','任翻','quantangshi','','卷41','无语与花别，细看枝上红。
明年又相见，还恐是愁中。','',''),('quantangshi-40898','宿巾子山禅寺','任翻','quantangshi','','卷41','绝顶新秋生夜凉，鹤翻松露滴衣裳。
前峰月映半江水，僧在翠微开竹房。','',''),('quantangshi-40899','再游巾子山寺','任翻','quantangshi','','卷41','灵江江上帻峰寺，三十年来两度登。
野鹤尚巢松树徧，竹房不见旧时僧。','',''),('quantangshi-40900','三游巾子山寺感述','任翻','quantangshi','','卷41','清秋绝顶竹房开，松鹤何年去不回。
惟有前峰明月在，夜深犹过半江来。','',''),('quantangshi-40901','画山水图答大愚','荆浩','quantangshi','','卷41','恣意纵横埽，峰峦次第成。
笔尖寒树瘦，墨澹野云轻。
岩石喷泉窄，山根到水平。
禅房时一展，兼称苦空情。','',''),('quantangshi-40902','宿顾城二首 一','張直','quantangshi','','卷41','绿草展青裀，樾影连春树。
茅屋八九家，农器六七具。
主人有好怀，搴衣留我住。
春酒新泼醅，香美连糟滤。
一醉卧花阴，明朝送君去。','',''),('quantangshi-40903','宿顾城二首 二','張直','quantangshi','','卷41','醉卧夜将半，土底闻鸡啼。
惊骇问主人，为我剖荒迷。
武汤东伐韦，固君含悲凄。
神夺悔悟魄，幻化为石鸡。
形骸仅盈寸，咿喔若啁霓。
吾村耕耘叟，多获于锄犂。','',''),('quantangshi-40904','题桃源僧','陳光','quantangshi','','卷41','桃源有僧舍，跬步异人天。
花乱似无主，鹤鸣疑有仙。
轩廊明野色，松桧湿春烟。
定拟辞尘境，依师过晚年。','',''),('quantangshi-40905','吟叙','周曇','quantangshi','','卷41','历代兴亡亿万心，圣人观古贵知今。
古今成败无多事，月殿花台幸一吟。','',''),('quantangshi-40906','闲吟','周曇','quantangshi','','卷41','考摭妍媸用破心，翦裁千古献当今。
闲吟不是闲吟事，事有闲思闲要吟。','',''),('quantangshi-40907','唐虞门 唐尧','周曇','quantangshi','','卷41','祆氛不起瑞烟轻，端拱垂衣日月明。
传事四方无外役，茅茨深处土堦平。','',''),('quantangshi-40908','唐虞门 虞舜','周曇','quantangshi','','卷41','进善惩奸立帝功，功成揖让益温恭。
满朝卿士多元凯，为黜兜苗与四凶。','',''),('quantangshi-40909','唐虞门 舜妃','周曇','quantangshi','','卷41','苍梧一望隔重云，帝子悲寻不记春。
何事泪痕偏在竹，贞姿应念节高人。','',''),('quantangshi-40910','唐虞门 再吟','周曇','quantangshi','','卷41','潇湘何代泣幽魂，骨化重泉志尚存。
若道地中休下泪，不应新竹有啼痕。','',''),('quantangshi-40911','三代门 夏禹','周曇','quantangshi','','卷41','尧违天孽赖询谟，顿免洪波浸碧虚。
海内生灵微伯禹，尽应随浪化为鱼。','',''),('quantangshi-40912','三代门 再吟','周曇','quantangshi','','卷41','万古龙门一旦开，无成甘死作黄能。
司空定有匡尧术，九载之前何处来。','',''),('quantangshi-40913','三代门 太康','周曇','quantangshi','','卷41','师保何人为琢磨，安知父祖苦辛多。
酒酣禽色方为乐，讵肯闲听五子歌。','',''),('quantangshi-40914','三代门 后稷','周曇','quantangshi','','卷41','人惟邦本本由农，旷古谁高后稷功。
百谷且繁三曜在，牲牢郊祀信无穷。','',''),('quantangshi-40915','三代门 文王','周曇','quantangshi','','卷41','昭然明德报天休，禴祭惟馨胜杀牛。
二老五侯何所诈，不归商受尽归周。','',''),('quantangshi-40916','三代门 武王','周曇','quantangshi','','卷41','文王寝膳武王随，内竖言安色始怡。
七载岂堪囚羑里，一夫为报亦何疑。','',''),('quantangshi-40917','三代门 太公','周曇','quantangshi','','卷41','昌猎关西纣猎东，纣怜崇虎弃非熊。
危邦自谓多麟凤，肯把王纲取钓翁。','',''),('quantangshi-40918','三代门 再吟','周曇','quantangshi','','卷41','东邻不事事西邻，御物卑和物自亲。
天下言知天下者，兆人无主属贤人。','',''),('quantangshi-40919','三代门 又吟','周曇','quantangshi','','卷41','千妖万态逞妍姿，破国亡家更是谁。
匡政必能除苟媚，去邪当断勿狐疑。','',''),('quantangshi-40920','三代门 子牙妻','周曇','quantangshi','','卷41','陵柏无心竹变秋，不能同戚拟同休。
岁寒焉在空垂涕，覆水如何欲再收。','',''),('quantangshi-40921','三代门 周公','周曇','quantangshi','','卷41','文武传芳百代基，几多贤哲守成规。
