宾降未免俱为戮，一死安能谢益仁。','',''),('quantangshi-41091','六朝门 谢举','周曇','quantangshi','','卷42','叛奴逃数岂堪留，忠节曾无肯到头。
朱异早能同远见，青衫宁假帝登楼。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-41092','六朝门 朱异','周曇','quantangshi','','卷42','徒览儒书不学兵，彦和虚得不廉名。
四郊多垒犹相罪，国破将何谢太清。','',''),('quantangshi-41093','六朝门 傅昭','周曇','quantangshi','','卷42','为政残苛兽亦饥，除饥机在养疲羸。
人能善政兽何暴，焉用劳人以槛为。','',''),('quantangshi-41094','六朝门 宣帝','周曇','quantangshi','','卷42','宣帝骄奢恣所为，后宫升降略无时。
乘危自有妻公在，安许鸾凰是尉迟。','',''),('quantangshi-41095','六朝门 李集','周曇','quantangshi','','卷42','忠谏能坚信正臣，三沈三屈竟何云。
每沈良久方能语，及语还呼桀纣君。','',''),('quantangshi-41096','隋门 隋文帝','周曇','quantangshi','','卷42','孤儿寡妇忍同欺，辅政刚教篡夺为。
矫诏必能疎昉译，直臣诚合重颜仪。','',''),('quantangshi-41097','隋门 独孤后','周曇','quantangshi','','卷42','腹生奚强有亲疎，怜者为贤弃者愚。
储贰不遭谗构死，隋亡宁便在江都。','',''),('quantangshi-41098','隋门 炀帝','周曇','quantangshi','','卷42','拒谏劳兵作祸基，穷奢极武向戎夷。
兆人疲弊不堪命，天下嗷嗷新主资。','',''),('quantangshi-41099','隋门 贺若弼','周曇','quantangshi','','卷42','破敌江军意气豪，请除倾国斩妖娆。
红绡忍染娇春雪，瞪目看行切玉刀。','',''),('quantangshi-41100','上清辞五首 一','李九齡','quantangshi','','卷42','入海浮生汗漫秋，紫皇高宴五云楼。
霓裳曲罢天风起，吹散仙香满十洲。','',''),('quantangshi-41101','上清辞五首 二','李九齡','quantangshi','','卷42','楼鏁彤霞地绝尘，碧桃花发九天春。
东皇近日慵游宴，闲煞瑶池五色麟。','',''),('quantangshi-41102','上清辞五首 三','李九齡','quantangshi','','卷42','上清仙路有丹梯，影响行人到即迷。
不会无端个渔父，阿谁教入武陵溪。','',''),('quantangshi-41103','上清辞五首 四','李九齡','quantangshi','','卷42','本来方朔是真仙，偶别丹台未得还。
何事玉皇消息晚，忍教顦顇向人间。','',''),('quantangshi-41104','上清辞五首 五','李九齡','quantangshi','','卷42','新拜天官上玉都，紫皇亲授五灵符。
羣仙个个来相问，人世风光似此无。','',''),('quantangshi-41105','读三国志','李九齡','quantangshi','','卷42','有国由来在得贤，莫言兴废是循环。
武侯星落周瑜死，平蜀降吴似等闲。','',''),('quantangshi-41106','山舍南溪小桃花','李九齡','quantangshi','','卷42','一树繁英夺眼红，开时先合占东风。
可怜地僻无人赏，抛掷深山乱木中。','',''),('quantangshi-41107','春行遇雨','李九齡','quantangshi','','卷42','夹路轻风撼柳条，雨侵春态动无憀。
采香陌上谁家女，湿损钗头翡翠翘。','',''),('quantangshi-41108','登楼寄远','李九齡','quantangshi','','卷42','满城春色花如雪，极目烟光月似钩。
总是动人乡思处，更堪容易上高楼。','',''),('quantangshi-41109','望思台','李九齡','quantangshi','','卷42','汉武年高慢帝图，任人曾不问贤愚。
直饶四老依前出，消得江充宠佞无。','',''),('quantangshi-41110','山舍偶题','李九齡','quantangshi','','卷42','门掩松萝一迳深，偶携藜杖出前林。
谁知尽日看山坐，万古兴亡总在心。','',''),('quantangshi-41111','荆溪夜泊','李九齡','quantangshi','','卷42','点点渔灯照浪清，水烟疎碧月胧明。
小滩惊起鸳鸯处，一只采莲船过声。','',''),('quantangshi-41112','旅舍卧病','李九齡','quantangshi','','卷42','家隔西秦无远信，身随东洛度流年。
病来旅馆谁相问，牢落闲庭一树蝉。','',''),('quantangshi-41113','登昭福寺楼','李九齡','quantangshi','','卷42','旅怀秋兴正无涯，独倚危楼四望赊。
谷变陵迁何处问，满川空有旧烟霞。','',''),('quantangshi-41114','代边将','李九齡','quantangshi','','卷42','雪冻阴河半夜风，战回狂虏血漂红。
据鞍遥指长安路，须刻麟台第一功。','',''),('quantangshi-41115','夜与张舒话别','李九齡','quantangshi','','卷42','愁听南楼角又吹，晓鸡啼后更分离。
如何销得凄凉思，更劝灯前酒一巵。','',''),('quantangshi-41116','寒梅词','李九齡','quantangshi','','卷42','霜梅先拆岭头枝，万卉千花冻不知。
留得和羹滋味在，任他风雪苦相欺。','',''),('quantangshi-41117','题灵泉寺','李九齡','quantangshi','','卷42','入谷先生一阵香，异花奇木簇禅堂。
可怜门外高低路，万毂千蹄日日忙。','',''),('quantangshi-41118','宿张正字别业','李九齡','quantangshi','','卷42','茅屋萧寥烟暗后，松窗寂历月明初。
此时谁念孤吟客，唯有黄公一帙书。','',''),('quantangshi-41119','鹤','李九齡','quantangshi','','卷42','天上瑶池覆五云，玉麟金凤好为羣。
不须更饮人间水，直是清流也汗君。','',''),('quantangshi-41120','过相思谷','李九齡','quantangshi','','卷42','悠悠信马春山曲，芳草和烟铺嫩绿。
正被离愁着莫人，那堪更过相思谷。','',''),('quantangshi-41121','写庄子','李九齡','quantangshi','','卷42','圣泽安排当散地，贤侯优贷借新居。
闲中亦有闲生计，写得南华一部书。','',''),('quantangshi-41122','山中寄友人','李九齡','quantangshi','','卷42','乱云堆里结茅庐，已共红尘迹渐疎。
莫问野人生计事，窗前流水枕前书。','',''),('quantangshi-41123','津亭','胡宿','quantangshi','','卷42','津亭欲阕戒棠舟，五两风来不暂留。
西北浮云连魏阙，东南初日满秦楼。
层城渺渺人伤别，芳草萋萋客倦游。
平乐旧欢收不得，更凭飞梦到瀛洲。','',''),('quantangshi-41124','古别','胡宿','quantangshi','','卷42','长道何年祖軷休，风帆不断岳阳楼。
佳人挟瑟漳河晓，壮士悲歌易水秋。
九帐[青]油徒自负，百壶芳醑岂消忧。
至今长乐坡前水，不啻秦人怨陇头。','',''),('quantangshi-41125','塞上','胡宿','quantangshi','','卷42','汉家神箭定天山，烟火相望万里间。
契利请盟金匕酒，将军归卧玉门关。
云沈老上妖氛断，雪照回中探骑闲。
五饵已行王道胜，绝无刁斗至阗颜。','',''),('quantangshi-41126','寄昭潭王中立','胡宿','quantangshi','','卷42','高弦一弄武陵深，六幕天空万里心。
吴苑歌骊成久别，楚峰回雁好归音。
十千美酒花期隔，三百枯棋弈思沈。
莫上孤城频送目，浮云西北是家林。','',''),('quantangshi-41127','雪','胡宿','quantangshi','','卷42','屏翳驱云结夜阴，素花飘坠恶氛沈。
色欺曹国麻衣浅，寒入荆王翠被深。
天上明河银作水，海中仙树玉为林。
日高独拥鸘裘卧，谁乞长安取酒金。','',''),('quantangshi-41128','冲虚观','胡宿','quantangshi','','卷42','五粒青松护翠苔，石门岑寂断纤埃。
水浮花片知仙路，风递鸾声认啸台。
桐井晓寒千乳歛，茗园春嫩一旗开。
驰烟未勒山亭字，可是英灵许再来。','',''),('quantangshi-41129','淮南发运赵邢州被诏归阙','胡宿','quantangshi','','卷42','天台封诏紫泥馨，马首前瞻北斗城。
人在函关先望气，帝于京兆最知名。
一区东第趋晨近，数刻西厢接昼荣。
正是两宫裁化日，百金双璧拜虞卿。','',''),('quantangshi-41130','天街晓望','胡宿','quantangshi','','卷42','长乐才闻一叩钟，百官初谒未央宫。
金波穆穆沙堤月，玉树琤琤上苑风。
香重椒兰横结雾，气寒龙虎远浮空。
嗟余索米无人问，行避霜台御史骢。','',''),('quantangshi-41131','淮南王','胡宿','quantangshi','','卷42','贪铸金钱盗写符，何曾七国戒前车。
长生不待炉中药，鸿宝谁收箧里书。
碧井牀空天影在，小山人去桂丛疎。
云中鸡犬无消息，麦秀渐渐徧故墟。','',''),('quantangshi-41132','赵宗道归辇下','胡宿','quantangshi','','卷42','沿牒相逢楚水湄，竹林文酒此攀嵇。
半毡未暖还伤别，一臂初交又解携。
江浦呕哑风送樐，河桥勃窣柳垂堤。
明年四月秦关到，洗眼扬州看马[蹄]。','',''),('quantangshi-41133','忆荐福寺牡丹','胡宿','quantangshi','','卷42','十日春风隔翠岑，秪应繁朵自成阴。
樽前可要人颓玉，树底遥知地侧金。
花界三千春渺渺，铜盘十二夜沈沈。
雕盘分篸何由得，空作西州拥鼻吟。','',''),('quantangshi-41134','次韵和朱况雨中之什','胡宿','quantangshi','','卷42','苍野迷云黯不归，远风吹雨入岩扉。
石牀润极琴丝缓，水阁寒多酒力微。
夕梦将成还滴滴，春心欲断正霏霏。
忧花惜月长如此，争得东阳病骨肥。','',''),('quantangshi-41135','感旧','胡宿','quantangshi','','卷42','千里青云未致身，马蹄空踏几年尘。
曾迷玉洞花光老，欲过金城柳眼新。
粉壁已沈题凤字，酒垆犹记姓黄人。
坞中横笛偏多感，一涕阑干白角巾。','',''),('quantangshi-41136','城南','胡宿','quantangshi','','卷42','昨夜轻阴结夕霏，城南十里有香泥。
初闻山鸟惊新哢，遥见林花识旧蹊。
荡桨远从芳草渡，垫巾还傍绿杨堤。
罗敷正苦桑蚕事，惆怅南来五马蹄。','',''),('quantangshi-41137','早夏','胡宿','quantangshi','','卷42','井辖投多思不禁，密垂珠箔昼沈沈。
睡惊燕语频移枕，病起蛛丝半在琴。
雨径乱花埋宿艳，月轩修竹转凉阴。
一春酒费知多少，探尽囊中换赋金。','',''),('quantangshi-41138','侯家','胡宿','quantangshi','','卷42','洞户春迟漏箭长，短辕初返雒阳傍。
彩云按曲青岑醴，沈水薰衣白璧堂。
前槛兰苕依玉树，后园桐叶护银牀。
宴残红烛长庚烂，还促朝珂谒未央。','',''),('quantangshi-41139','函谷关','胡宿','quantangshi','','卷42','天开函谷壮关中，万古惊尘向此空。
望气竟能知老子，弃繻何不识终童。
慢持白马先生论，未抵鸣鸡下客功。
符命已归如掌地，一丸曾误隗王东。','',''),('quantangshi-41140','残花','胡宿','quantangshi','','卷42','雨压残红一夜凋，晓来帘外正飘摇。
数枝翠叶空相对，万片香魂不可招。
长乐梦回春寂寂，武陵人去水迢迢。
愁将玉笛传遗恨，苦被芳风透绮寮。','',''),('quantangshi-41141','次韵徐爽见寄','胡宿','quantangshi','','卷42','五两青丝帝渥深，平时可敢叹英沈。
侏儒自是长三尺，澼絖都来直数金。
寂寞死灰人丧偶，婆娑生意树交阴。
年来想见琼枝色，久梦蘧蘧到竹林。','',''),('quantangshi-41142','华清宫','杜常','quantangshi','','卷42','行尽江南数十程，晓星残月入华清。
朝元阁上西风急，都入长杨作雨声。','',''),('quantangshi-41143','华清宫','杜常','quantangshi','','卷42','一别家山十六程，晓来和月到华清。
朝元阁上西风急，都入长杨作雨声。','',''),('quantangshi-41144','题文川村居','滕白','quantangshi','','卷42','种茶岩接红霞坞，灌稻泉生白石根。
皤腹老翁眉似雪，海棠花下戏儿孙。','',''),('quantangshi-41145','燕','滕白','quantangshi','','卷42','短羽新来别海阳，真珠高卷语雕梁。
佳人未必全听尔，正把金针绣凤凰。','',''),('quantangshi-41146','题严君观','王嵒','quantangshi','','卷42','寒云古木罩星台，凡骨仙踪信可哀。
二十年前曾此到，一千年内未归来。','',''),('quantangshi-41147','山中有所思','王嵒','quantangshi','','卷42','零零夜雨渍愁根，触物伤离好断魂。
莫怪杜鹃飞去尽，紫微花里有啼猨。','',''),('quantangshi-41148','燕','王嵒','quantangshi','','卷42','一巢功绩破春光，絮落花残两翅狂。
月树风枝不栖去，强来言语泥雕梁。','',''),('quantangshi-41149','贫女','王嵒','quantangshi','','卷42','难把菱花照素颜，试临春水插花看。
木兰船上游春子，笑指荆钗下远滩。','',''),('quantangshi-41150','杪春寄友人','王嵒','quantangshi','','卷42','何处相逢万事忙，卓家楼上百淘香。
明朝渐近山僧寺，更为残花醉一场。','',''),('quantangshi-41151','回旧山','王嵒','quantangshi','','卷42','庾家楼上谢家池，处处风烟少旧知。
明日落花谁共醉，野溪猨鸟恨归迟。','',''),('quantangshi-41152','感巫州荠菜','高力士','quantangshi','','卷42','两京作筋卖，五溪无人采。
夷夏虽有殊，气味都不改。','',''),('quantangshi-41153','句','高力士','quantangshi','','卷42','烟熏眼落膜，瘴染面朱虞。','',''),('quantangshi-41154','使至灊山','王越賓','quantangshi','','卷42','碧坞烟霞昼未开，游人到处尽裴回。
凭谁借问岩前叟，曾托吾皇一梦来。','',''),('quantangshi-41155','和武相公中秋夜西蜀锦楼望月得清字','王良會','quantangshi','','卷42','德星摇此夜，珥月满重城。
杳霭烟氛色，飘颻砧杵声。
令行秋气爽，乐感素风轻。
共赏千年圣，长歌四海清。','',''),('quantangshi-41156','星回节游避风台与清平官赋','南詔驃信','quantangshi','','卷42','避风善阐台，极目见藤越。
悲哉古与今，依然烟与月。
自我居震旦，翊卫类夔契。
伊昔颈皇运，艰难仰忠烈。
不觉岁云暮，感极星回节。
元昶同一心，子孙堪贻厥。','',''),('quantangshi-41157','星回节避风台骠信命赋','趙叔達','quantangshi','','卷42','法驾避星回，波罗毗勇猜。
河润冰难合，地暖梅先开。
下令俚柔洽，献賝弄栋来。
愿将不才质，千载侍游台。','',''),('quantangshi-41158','途中诗','楊奇鯤','quantangshi','','卷42','□□□□□□□，□□□□□□□。
风里浪花吹更白，雨中山色洗还青。
海鸥聚处窗前见，林狖啼时枕上听。
此际自然无限趣，王程不敢暂留停。','',''),('quantangshi-41159','听妓洞云歌','布燮','quantangshi','','卷42','嵇叔夜，鼓琴饮酒无闲暇。
若使当时闻此歌，抛掷广陵都不藉。
刘伯伦，虚生浪死过青春。
一饮一硕犹自醉，无人为尔卜深尘。','',''),('quantangshi-41160','思乡作','布燮','quantangshi','','卷42','泸北行人绝，云南信未还。
庭前花不埽，门外柳谁攀。
坐久销银烛，愁多减玉颜。
悬心秋夜月，万里照关山。','',''),('quantangshi-41161','衔命还国作','朝衡','quantangshi','','卷42','衔命将辞国，非才忝侍臣。
天中恋明主，海外忆慈亲。
伏奏违金阙，騑骖去玉津。
蓬莱乡路远，若木故园林。
西望怀恩日，东归感义辰。
平生一宝劒，留赠结交人。','',''),('quantangshi-41162','绣袈裟衣缘','長屋','quantangshi','','卷42','山川异域，风月同天。
寄诸佛子，共结来缘。','',''),('quantangshi-41163','愤怨诗','王巨仁','quantangshi','','卷42','于公恸哭三年旱，邹衍含愁五月霜。
今我幽愁还似古，皇天无语但苍苍。','',''),('quantangshi-41164','立木海上刻诗','李贊華','quantangshi','','卷42','小山压大山，大山全无力。
羞见故乡人，从此投外国。','',''),('quantangshi-41165','戏语','成輔端','quantangshi','','卷42','秦地城池二百年，何期如此贱田园。
一顷麦苗硕伍米，三间堂屋二千钱。','',''),('quantangshi-41166','万寿寺歌词','張隱','quantangshi','','卷42','位乖燮理致伤残，四面墙匡不忍看。
正是花时堪下泪，相公何必更追欢。','',''),('quantangshi-41167','迎孙刺史','朱元','quantangshi','','卷42','昔日郎君今刺史，朱元依旧守朱门。
今朝竹马诸童子，尽是当时竹马孙。','',''),('quantangshi-41168','临刑诗','陳璠','quantangshi','','卷42','积玉堆金官又崇，祸来倏忽变成空。
五年荣贵今何在，不异南柯一梦中。','',''),('quantangshi-41169','诗','捧劒僕','quantangshi','','卷42','青鸟衔葡萄，飞上金井栏。
美人恐惊去，不敢卷帘看。','',''),('quantangshi-41170','题牡丹','捧劒僕','quantangshi','','卷42','一种芳菲出后庭，却输桃李得佳名。
谁能为向天人说，从此移根近太清。','',''),('quantangshi-41171','将窜留诗','捧劒僕','quantangshi','','卷42','珍重郭四郎，临行不得别。
晓漏动离心，轻车冒残雪。
欲出主人门，零涕暗呜咽。
万里隔关山，一心思汉月。','',''),('quantangshi-41172','淮阳感怀','李密','quantangshi','','卷42','金风荡初节，玉露凋晚林。
此夕穷涂士，郁陶伤寸心。
野平葭苇合，村荒藜藿深。
眺听良多感，徙倚独霑襟。
霑襟何所为，怅然怀古意。
秦俗犹未平，汉道将何翼。
樊哙市井徒，萧何刀笔吏。
一朝时运会，千古传名諡。
寄言世上雄，虚生真可愧。','',''),('quantangshi-41173','南隐游泉山','孔德紹','quantangshi','','卷42','名山狎招隐，俗外远相求。
还如倒景望，忽似阆风游。
临崖俯大壑，披雾仰飞流。
岁积松方偃，年深椿欲秋。
野花开石镜，云叶掩山楼。
何须问方士，此处即瀛洲。','',''),('quantangshi-41174','行经太华','孔德紹','quantangshi','','卷42','纷吾世网暇，灵岳展幽寻。
寥廊风尘远，杳冥川谷深。
山昏五里雾，日落二华阴。
疎峰起莲叶，危塞隐桃林。
何必东都外，此处可抽簪。','',''),('quantangshi-41175','夜宿荒村','孔德紹','quantangshi','','卷42','绵绵夕漏深，客恨转伤心。
抚弦无人听，对酒时独斟。
故乡万里绝，穷愁百虑侵。
秋草思边马，遶枝惊夜禽。
风度谷余响，月斜山半阴。
劳歌欲叙意，终是白头吟。','',''),('quantangshi-41176','王泽岭遭洪水','孔德紹','quantangshi','','卷42','地籁风声急，天津云色愁。
悠然万顷满，俄尔百川浮。
远似金堤溢，翻如碧海流。
惊涛遥起鹭，回岸不分牛。
徒知怀赵景，终是倦阳侯。
木梗诚无托，芦灰岂暇求。
思得乘槎便，萧然河汉游。','',''),('quantangshi-41177','登白马山护明寺','孔德紹','quantangshi','','卷42','名岳标形胜，危峰远郁纡。
成象建环极，大壮阐规模。
层台从灵鹫，高殿迩阳乌。
暂同游阆苑，还类入仙都。
三休开碧岭，万户洞金铺。
摄心罄前礼，访道挹中虚。
遥瞻尽地轴，长望极天隅。
白云起梁栋，丹霞映栱栌。
露花疑濯锦，泉月似沈珠。
今日桃源客，相顾失归涂。','',''),('quantangshi-41178','送舍利宿定普岩','孔德紹','quantangshi','','卷42','仁祠表虚旷，祗园展肃恭。
栖息翠微岭，登顿白云峰。
映流看夜月，临峰听晓钟。
涧芳十步草，崖阴百丈松。
萧然遥路绝，无复市朝踪。','',''),('quantangshi-41179','观太常奏新乐','孔德紹','quantangshi','','卷42','大君膺宝历，出豫表功成。
钧天金石响，洞庭弦管清。
八音动繁会，九变叶希声。
和云留睿赏，熏风悦圣情。
盛烈光韶濩，易俗迈咸英。
窃吹良无取，率舞拚羣生。','',''),('quantangshi-41180','赋得涉江采芙蓉','孔德紹','quantangshi','','卷42','莲舟泛锦碛，极目眺江干。
沿流渡檝易，逆浪取花难。
有雾疑川广，无风见水宽。
朝来采摘倦，讵得久盘桓。','',''),('quantangshi-41181','赋得华亭鹤','孔德紹','quantangshi','','卷42','华亭失侣鹤，乘轩宠遂终。
三山凌苦雾，千里激悲风。
心危白露下，声断彩弦中。
何言斯物变，翻复似辽东。','',''),('quantangshi-41182','送蔡君知入蜀二首 一','孔德紹','quantangshi','','卷42','金陵已去国，铜梁忽背飞。
失路远相送，他乡何日归。','',''),('quantangshi-41183','送蔡君知入蜀二首 二','孔德紹','quantangshi','','卷42','灵关九折险，蜀道二星遥。
乘槎若有便，希泛广陵潮。','',''),('quantangshi-41184','落叶','孔德紹','quantangshi','','卷42','早秋惊叶落，飘零似客心。
翻飞未肯下，犹言惜故林。','',''),('quantangshi-41185','句','孔德紹','quantangshi','','卷42','谁分菱花影，还看蓬鬓秋。','',''),('quantangshi-41186','临刑诗','鄭頲','quantangshi','','卷42','幻生还幻灭，大幻莫过身。
安心自有处，求人无有人。','',''),('quantangshi-41187','和谒孔子庙','劉斌','quantangshi','','卷42','性与虽天纵，主世乃无由。
何言泰山毁，空惊逝水流。
及门思往烈，入室想前修。
寂寞荒堦暮，摧残古木秋。
遗风暧如此，聊以慰蒸求。','',''),('quantangshi-41188','和许给事伤牛尚书','劉斌','quantangshi','','卷42','名臣不世出，百工之所求。
况乃非常器，遭逢兴运秋。
符彩照千里，铨衡综九流。
经纶资百物，樽俎寄皇猷。
韶濩倾复理，典礼紊还修。
虽贞栋梁任，兼好艺文游。
伫闻和鼎实，行当奉介丘。
高衢翻税驾，阅水遽迁舟。
传呼更何日，曳履闻无由。
归魂藐修路，征棹舣邗沟。
林薄长风惨，江上寒云愁。
夜台终不曙，遗芳徒自留。','',''),('quantangshi-41189','送刘散员同赋陈思王诗得好鸟鸣高枝','劉斌','quantangshi','','卷42','春林已自好，时鸟复和鸣。
枝交难奋翼，谷静易流声。
间关才得性，[矰]缴遽相惊。
安知背飞远，拂雾独晨征。','',''),('quantangshi-41190','咏山','劉斌','quantangshi','','卷42','灵山峙千仞，蔽日且嵯峨。
紫盖云阴远，香炉烟气多。
石梁高鸟路，瀑水近天河。
欲知闻道里，别自有仙歌。','',''),('quantangshi-41191','登楼望月二首 一','劉斌','quantangshi','','卷42','圆月当新霁，高楼见最明。
素波流粉壁，丹桂拂飞甍。
下瞰千门静，旁观万象生。
梧桐窗下影，鸟鹊槛前声。
啸逸刘琨兴，吟资庾亮情。
游人莫登眺，迢递故乡程。','',''),('quantangshi-41192','登楼望月二首 二','劉斌','quantangshi','','卷42','皎洁三秋月，巍峨百丈楼。
下分征客路，上有美人愁。
帐卷芙蓉带，帘褰玳瑁钩。
倚窗情渺渺，凭槛思悠悠。
末得金波转，俄成玉筯流。
不堪三五夕，夫壻在边州。','',''),('quantangshi-41193','题菊花','黃巢','quantangshi','','卷42','飒飒西风满院栽，蘂寒香冷蝶难来。
他年我若为青帝，报与桃花一处开。','',''),('quantangshi-41194','不第后赋菊','黃巢','quantangshi','','卷42','待到秋来九月八，我花开后百花杀。
冲天香阵透长安，满城尽带黄金甲。','',''),('quantangshi-41195','自题像','黃巢','quantangshi','','卷42','记得当年草上飞，铁衣着尽着僧衣。
天津桥上无人识，独倚栏干看落晖。','',''),('quantangshi-41196','柳','羅紹威','quantangshi','','卷42','妆点青春更有谁，青春常许占先知。
亚夫营畔风轻处，元亮门前日暖时。
花密宛如飘六出，叶繁何惜借双眉。
交情别绪论多少，好向仁人赠一枝。','',''),('quantangshi-41197','白菊','羅紹威','quantangshi','','卷42','虽被风霜竞欲催，皎然颜色不低摧。
已疑素手能妆出，又似金钱未染来。
香散自宜飘渌酒，叶交仍得荫苍苔。
寻思闭户中宵见，应认寒窗雪一堆。','',''),('quantangshi-41198','句','羅紹威','quantangshi','','卷42','楼前澹澹云头日，帘外萧萧雨脚风。','',''),('quantangshi-41199','清明登奉先城楼','羅衮','quantangshi','','卷42','年来年去只艰危，春半尧山草尚衰。
四海清平耆旧见，五陵寒食小臣悲。
烟销井邑隈楼槛，雪满川原泥酒巵。
拭尽贾生无限泪，一行归雁远参差。','',''),('quantangshi-41200','清明赤水寺居','羅衮','quantangshi','','卷42','榆火轻烟处处新，旋从闲望到诸邻。
浮生浮世祗多事，野水野花娱病身。
浊酒不禁云外景，碧峰犹冷寺前春。
蓑衣毳衲诚吾党，自结村园一社贫。','',''),('quantangshi-41201','赠罗隐','羅衮','quantangshi','','卷42','平日时风好涕流，谗书虽盛一名休。
寰区叹屈瞻天问，夷貊闻诗过海求。
向夕便思青琐拜，近年寻伴赤松游。
何当世祖从人望，早以公台命卓侯。','',''),('quantangshi-41202','哭赵州和尚二首 一','王鎔','quantangshi','','卷42','师离㴲水动王侯，心印光潜麈尾收。
碧落雾霾松岭月，沧溟浪覆济人舟。
一灯乍灭波旬喜，双眼重昏道侣愁。
纵是了然云外客，每瞻瓶几泪还流。','',''),('quantangshi-41203','哭赵州和尚二首 二','王鎔','quantangshi','','卷42','佛日西倾祖印隳，珠沈丹沼月沈辉。
影敷丈室炉烟惨，风起禅堂松韵微。
只履乍来留化迹，五天何处又逢归。
解空弟子绝悲喜，犹自潸然对雪帏。','',''),('quantangshi-41204','答同年李昉见赠次韵','鄧洵美','quantangshi','','卷42','词场几度让长鞭，又向清朝贺九迁。
品秩虽然殊此日，岁寒终不改当年。
驰名早已超三院，侍直仍忻步八砖。
今日相逢翻自愧，闲吟对酒倍潸然。','',''),('quantangshi-41205','除夜长安作','李京','quantangshi','','卷42','长安朔风起，穷巷掩双扉。
新岁明朝是，故乡何路归。
鬓丝饶镜色，隙雪夺灯辉。
却羡秦州雁，逢春尽北飞。','',''),('quantangshi-41206','登岭望','許鼎','quantangshi','','卷42','淼淼三江水，悠悠五岭关。
雁飞犹不度，人去若为还。','',''),('quantangshi-41207','㟧岭四望','許鼎','quantangshi','','卷42','汉家仙仗在咸阳，洛水东流出建章。
野老至今犹望辛，离宫秋树独苍苍。','',''),('quantangshi-41208','官左拾遗归隐作','王易簡','quantangshi','','卷42','汨没朝班愧不才，谁能低折向尘埃。
青山得去且归去，官职有来还自来。','',''),('quantangshi-41209','悼杨氏妓琴弦','朱褒','quantangshi','','卷42','魂归寥廊魄归泉，只住人间十五年。
昨日施僧裙带上，断肠犹系琵琶弦。','',''),('quantangshi-41210','公子行','黃損','quantangshi','','卷42','春草绿绵绵，骄骖骤暖烟。
微风飘乐韵，半日醉花边。
打鹊抛金盏，招人举玉鞭。
田翁与蚕妇，平地看神仙。','',''),('quantangshi-41211','读史','黃損','quantangshi','','卷42','逐鹿走红尘，炎炎火德新。
家肥生孝子，国霸有余臣。
帝道云龙合，民心草木春。
须知烟阁上，一半老儒真。','',''),('quantangshi-41212','出山吟','黃損','quantangshi','','卷42','来书初出白云扃，乍蹑秋风马走轻。
远近留连分岳色，别离呜咽乱泉声。
休将巢许争喧杂，自共伊臯论太平。
昨夜细看云色里，进贤星座甚分明。','',''),('quantangshi-41213','书壁','黃損','quantangshi','','卷42','一别人间岁月多，归来人事已销磨。
惟有门前鉴池水，春风不改旧时波。','',''),('quantangshi-41214','句','黃損','quantangshi','','卷42','机关才运动，胜败便相随。
忽遇南迁客，若为西入心。
往来三岛近，活计一囊空。
三通明主诏，一片白云心。
扫地待明月，踏花迎野僧。
水谙彭泽阔，山忆武陵深。
金镫冷光风宛转，锦袍红润雨霏微。
高齐日月方为道，动合干坤始是心。
傍水野禽通体白，飣盘山菓半边红。
而今世上多离别，莫向相思树下啼。','',''),('quantangshi-41215','梁郊祀乐章 庆肃','張衮','quantangshi','','卷42','笾豆簠簋，黍稷非馨。
懿兹彝器，厥德惟明。
金石匏革，以和以平。
由此无疆，期乎永宁。','',''),('quantangshi-41216','梁郊祀乐章 庆熙','張衮','quantangshi','','卷42','哲后躬享，旨酒斯陈。
王恭无斁，严祀惟寅。
皇祖以配，大孝以振。
宜锡景福，永休下民。','',''),('quantangshi-41217','梁郊祀乐章 庆隆','張衮','quantangshi','','卷42','恭祀上帝，于国之阳。
爵醴是荷，鸿基永昌。','',''),('quantangshi-41218','梁郊祀乐章 庆融','張衮','quantangshi','','卷42','导和气兮袭氤氲，宣皇使兮彰圣神。
服遐裔兮敷质文，格苗扈兮息烟尘。','',''),('quantangshi-41219','梁郊祀乐章 庆休','張衮','quantangshi','','卷42','大业来四夷，仁风和万国。
白日体无私，皇天辅有德。
七旬罪已服，六旬师方克。
伟哉帝道隆，终始常作则。','',''),('quantangshi-41220','梁郊祀乐章 庆和','張衮','quantangshi','','卷42','烟燎升，礼容彻。
诚感达，人神悦。
灵贶彰，圣情结。
玉座寂，金罏歇。','',''),('quantangshi-41221','梁郊祀乐章 庆和 一','趙光逢','quantangshi','','卷42','就阳位，升圜丘。
佩双玉，御大裘。
膺天命，拥神休。
万灵感，百禄遒。','',''),('quantangshi-41222','梁郊祀乐章 庆和 二','趙光逢','quantangshi','','卷42','秉黄钺，建朱旗。
震八表，清二仪。
帝业显，王道夷。
受景命，启皇基。','',''),('quantangshi-41223','梁郊祀乐章 庆和 三','趙光逢','quantangshi','','卷42','开九门，怀百神。
通肸蠁，接氤氲。
明粢荐，广乐陈。
奠嘉璧，燎芳薪。','',''),('quantangshi-41224','梁郊祀乐章 庆和 四','趙光逢','quantangshi','','卷42','膺宝图，执左契。
德应天，圣飨帝。
荐表衷，荷灵惠。
寿万年，祚百世。','',''),('quantangshi-41225','梁郊祀乐章 庆和 五','趙光逢','quantangshi','','卷42','惟德动天，有感必通。
秉兹一德，禋于六宗。
钦夤宝命，恭肃礼容。
来顾来享，永穆皇风。','',''),('quantangshi-41226','梁郊祀乐章 庆和 六','趙光逢','quantangshi','','卷42','天惟佑德，辟乃奉天。
交感斯在，昭事罔愆。
岁功已就，王道无偏。
于焉报本，是用告虔。','',''),('quantangshi-41227','梁郊祀乐章 庆顺','趙光逢','quantangshi','','卷42','圣皇戾止，天步舒迟。
干干睿相，穆穆皇仪。
进退必肃，陟降是祗。
六变克协，万灵协随。','',''),('quantangshi-41228','梁郊祀乐章 庆平','趙光逢','quantangshi','','卷42','天命降鉴，帝德惟馨。
享祀不忒，礼容孔明。
奠璧布币，荐纯献精。
神佑以答，敷锡永宁。','',''),('quantangshi-41229','宫词百首 一','和凝','quantangshi','','卷42','紫燎光销大驾归，御楼初见赭黄衣。
千声鼓定将宣赦，竿上金鸡翅欲飞。','',''),('quantangshi-41230','宫词百首 二','和凝','quantangshi','','卷42','北阙晴分五凤楼，嵩山秀色护神州。
洛河自契千年运，更拟波中出九畴。','',''),('quantangshi-41231','宫词百首 三','和凝','quantangshi','','卷42','中兴殿上晓光融，一炷天香舞瑞风。
百辟虔心齐稽首，卷帘遥见御衣红。','',''),('quantangshi-41232','宫词百首 四','和凝','quantangshi','','卷42','日和风暖御楼时，万姓齐瞻八彩眉。
瑞气祥烟笼细仗，合门宣赦四方知。','',''),('quantangshi-41233','宫词百首 五','和凝','quantangshi','','卷42','凤吹鸾歌晓日明，丰年观稼出神京。
封人争献南山寿，五色云中御辇平。','',''),('quantangshi-41234','宫词百首 六','和凝','quantangshi','','卷42','圣主临轩待晓时，穿花宫漏正迟迟。
鸡人一唱干坤晓，百辟分班俨羽仪。','',''),('quantangshi-41235','宫词百首 七','和凝','quantangshi','','卷42','朦胧西月照池亭，初夜椒房掩画屏。
宫女相呼有何事，上楼同看老人星。','',''),('quantangshi-41236','宫词百首 八','和凝','quantangshi','','卷42','红泥椒殿缀珠璫，帐蹙金龙窣地长。
红兽慢然天色暖，凤炉时复爇沈香。','',''),('quantangshi-41237','宫词百首 九','和凝','quantangshi','','卷42','九重楼殿簇丹青，高柳含烟覆井亭。
宫内不知今日几，自来阶下数尧蓂。','',''),('quantangshi-41238','宫词百首 十','和凝','quantangshi','','卷42','寝殿香浓玉漏严，云随凉月下西南。
帐前宫女低声道，主上还应梦傅岩。','',''),('quantangshi-41239','宫词百首 十一','和凝','quantangshi','','卷42','遶殿钩栏压玉阶，内人轻语凭葱薹。
皆言明主垂衣理，不假朱云傍槛来。','',''),('quantangshi-41240','宫词百首 十二','和凝','quantangshi','','卷42','颟顸冰面莹池心，风刮瑶阶腊雪深。
怪得宫中无兽炭，步摇钗是辟寒金。','',''),('quantangshi-41241','宫词百首 十三','和凝','quantangshi','','卷42','兰殿春融自靘笙，玉颜风透象纱明。
金簧如语莺声滑，可使云和独得名。','',''),('quantangshi-41242','宫词百首 十四','和凝','quantangshi','','卷42','兰烛时将凤髓添，寒星遥映夜光帘。
龙楼露着鸳鸯瓦，谁近螭头掷玉签。','',''),('quantangshi-41243','宫词百首 十五','和凝','quantangshi','','卷42','玉甃莲池春水平，小鱼双竝锦鳞行。
内中知是黄河样，九曲今年彻底清。','',''),('quantangshi-41244','宫词百首 十六','和凝','quantangshi','','卷42','真珠帘外静无尘，耿耿凉天景象新。
金殿夜深银烛晃，宫嫔来奏月重轮。','',''),('quantangshi-41245','宫词百首 十七','和凝','quantangshi','','卷42','鱼犀月掌夜通头，自着盘莺锦臂韝。
多把沈檀配龙麝，宫中掌浸十香油。','',''),('quantangshi-41246','宫词百首 十八','和凝','quantangshi','','卷42','香云双颭玉蝉轻，侍从君王苑里行。
嘉瑞忽逢连理木，一时跪拜贺文明。','',''),('quantangshi-41247','宫词百首 十九','和凝','quantangshi','','卷42','金鸾双立紫檀槽，暖殿无风韵自高。
含笑试弹红蘂调，君王宣赐酪樱桃。','',''),('quantangshi-41248','宫词百首 二十','和凝','quantangshi','','卷42','斑簟如霞可殿铺，更开新进瑞莲图。
谁人筑损珊瑚架，子细看时认沥苏。','',''),('quantangshi-41249','宫词百首 二十一','和凝','quantangshi','','卷42','金盆初晓洗纤纤，银鸭香焦特地添。
