INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-41292','宫词百首 六十四','和凝','quantangshi','','卷42','圣日垂科委所司，英才咸喜遇明时。
