兰殿春晴鹦鹉睡，结条钗颭落花风。','',''),('quantangshi-41315','宫词百首 八十七','和凝','quantangshi','','卷42','晓光初入右银台，鸳鹭分班启沃来。
如水如鱼何际会，尽言金鼎得盐梅。','',''),('quantangshi-41316','宫词百首 八十八','和凝','quantangshi','','卷42','立名金马近尧阶，尽是家传八斗才。
麻尾尚犹龙字湿，便从天上凤衔来。','',''),('quantangshi-41317','宫词百首 八十九','和凝','quantangshi','','卷42','狻猊镇角舞筵张，鸾凤花分十六行。
