花下贪忙寻百草，不知遗却蹙金蝉。','',''),('quantangshi-41320','宫词百首 九十二','和凝','quantangshi','','卷42','兰省初除傅粉郎，静端霜简入鸳行。
明庭转制浑无事，朝下空余鸡舌香。','',''),('quantangshi-41321','宫词百首 九十三','和凝','quantangshi','','卷42','采访宁遗草泽人，诏搜无不降蒲轮。
