两个瑶池小仙子，此时夺却柘枝名。','',''),('quantangshi-41334','题鹰猎兔画','和凝','quantangshi','','卷42','虽是丹青物，沈吟亦可伤。
君夸鹰眼疾，我悯兔心忙。
岂动骚人兴，惟增猎客狂。
鲛绡百余尺，争及制衣裳。','',''),('quantangshi-41335','醴泉院','和凝','quantangshi','','卷42','万山岚霭簇洋城，数处禅斋尽有名。
