暂游颇爱闲滋味，久住翻嫌俗性情。
珍重支公每相勉，我于儒行也修行。','',''),('quantangshi-41336','兴势观','和凝','quantangshi','','卷42','山名兴势镇梁洋，俨有真风福此方。
