盛德安疲俗，仁风扇极边。
前程问成纪，此去尚三千。','',''),('quantangshi-41340','和蜀后主题劒门','王仁裕','quantangshi','','卷42','孟阳曾有语，刊在白云棱。
李杜常挨托，孙刘亦恃凭。
庸才安可守，上德始堪矜。
暗指长天路，浓峦蔽几层。','',''),('quantangshi-41341','荆南席上咏胡琴妓二首 一','王仁裕','quantangshi','','卷42','红妆齐抱紫檀槽，一抹朱弦四十条。
湘水淩波惭鼓瑟，秦楼明月罢吹箫。
寒敲白玉声偏婉，暖逼黄莺语自娇。
丹禁旧臣来侧耳，骨清神爽似闻韶。','',''),('quantangshi-41342','荆南席上咏胡琴妓二首 二','王仁裕','quantangshi','','卷42','玉纤挑落折冰声，散入秋空韵转清。
二五指中句塞雁，十三弦上啭春莺。
谱从陶室偷将妙，曲向秦楼写得成。
无限细腰宫里女，就中偏惬楚王情。','',''),('quantangshi-41343','题麦积山天堂','王仁裕','quantangshi','','卷42','蹑尽悬空万仞梯，等闲身共白云齐。
檐前下视羣山小，堂上平分落日低。
绝顶路危人少到，古岩松健鹤频栖。
天边为要留名姓，拂石殷勤身自题。','',''),('quantangshi-41344','题斗山观','王仁裕','quantangshi','','卷42','霞衣欲举醉陶陶，不觉全家住绛霄。
