三清辽廊抛尘梦，八景云烟事早朝。
为有故林苍柏健，露华凉叶锁金飙。','',''),('quantangshi-41345','题孤云絶顶淮阴祠','王仁裕','quantangshi','','卷42','一握寒天古木深，路人犹说汉淮阴。
孤云不掩兴亡策，两角曾悬去住心。
不是冕旒轻布素，岂劳丞相远追寻。
当时若放还西楚，尺寸中华未可侵。','',''),('quantangshi-41346','和韩昭从驾过白卫岭','王仁裕','quantangshi','','卷42','龙斾飘颻指极边，到时犹更二三千。
登高晓蹋巉岩石，冒冷朝冲断续烟。
自学汉皇开土宇，不同周穆好神仙。
秦民莫遣无恩及，大散关东别有天。','',''),('quantangshi-41347','贺王溥入相','王仁裕','quantangshi','','卷42','一战文场拔赵旗，便调金鼎佐无为。
白麻骤降恩何极，黄发初闻喜可知。
跋勅案前人到少，筑沙堤上马归迟。
立班始得遥相见，亲洽争如未贵时。','',''),('quantangshi-41348','与诸门生春日会饮繁台赋','王仁裕','quantangshi','','卷42','柳阴如雾絮成堆，又引门生饮古台。
淑景即随风雨去，芳樽宜命管弦开。
谩夸列鼎鸣钟贵，宁免朝乌夜兔催。
烂醉也须诗一首，不能空放马头回。','',''),('quantangshi-41349','示诸门生','王仁裕','quantangshi','','卷42','二百一十四门生，春风初长羽毛成。
