何辛不才逢圣世，偶将疎网罩羣英。
衰翁渐老儿孙小，异日知谁略有情。','',''),('quantangshi-41350','过平戎谷吊胡翽','王仁裕','quantangshi','','卷42','立马荒郊满目愁，伊人何罪死林丘。
