莫道文章为众嫉，只应轻薄是身讐。
不缘魂寄孤山下，此地堪名鹦鹉洲。','',''),('quantangshi-41351','奉诏赋劒州途中鸷兽','王仁裕','quantangshi','','卷42','劒牙钉舌血毛腥，窥算劳心岂暂停。
不与大朝除患难，惟余当路食生灵。
从将户口资嚵口，未委三丁税几丁。
今日帝王亲出狩，白云岩下好藏形。','',''),('quantangshi-41352','放猿','王仁裕','quantangshi','','卷42','放尔丁宁复故林，旧来行处好追寻。
