渐来子细窥行客，认得依稀是野宾。
月宿从劳羁絏梦，松餐非复稻粱身。
数声肠断和云呌，识是前时旧主人。','',''),('quantangshi-41354','句','王仁裕','quantangshi','','卷42','铁锁寨门扃白日，大张旗帜插青天。','',''),('quantangshi-41355','天道','馮道','quantangshi','','卷42','穷达皆由命，何劳发叹声。
但知行好事，莫要问前程。
冬去冰须泮，春来草自生。
请君观此理，天道甚分明。','',''),('quantangshi-41356','偶作','馮道','quantangshi','','卷42','莫为危时便怆神，前程往往有期因。
须知海岳归明主，未必干坤陷吉人。
道德几时曾去世，舟车何处不通津？
但教方寸无诸恶，狼虎丛中也立身。','',''),('quantangshi-41357','北使还京作','馮道','quantangshi','','卷42','去年今日奉皇华，只为朝廷不为家。
殿上一杯天子泣，门前双节国人嗟。
龙荒冬往时时雪，兔苑春归处处花。
上下一行如骨肉，几人身死掩风沙。','',''),('quantangshi-41358','赠窦十','馮道','quantangshi','','卷42','燕山窦十郎，教子有义方。
灵椿一株老，丹桂五枝芳。','',''),('quantangshi-41359','放鱼书所钥户','馮道','quantangshi','','卷42','高却垣墙钥却门，监丞从此罢垂纶。
池中鱼鳖应相贺，从此方知有主人。','',''),('quantangshi-41360','句','馮道','quantangshi','','卷42','朝披四袄专藏手，夜覆三衾怕露头。
牛头偏得赐，象笏更容持。
已落地花方遣埽，未经霜草莫教锄。
视草北来唐学士，拥旄西去汉将军。','',''),('quantangshi-41361','后唐宗庙乐舞辞','盧文紀','quantangshi','','卷42','仁君御宇，环海谧清。
运符武德，道协文明。
九成式敍，百度惟成。
金门积庆，玉叶传荣。','',''),('quantangshi-41362','后唐宗庙乐舞辞','崔居儉','quantangshi','','卷42','艰难王业，返正皇唐。
