功成德茂，率祀无疆。','',''),('quantangshi-41363','春社从李昉乞酒','李濤','quantangshi','','卷42','社公今日没心情，为乞治聋酒一瓶。
恼乱玉堂将欲徧，依稀巡到第三厅。','',''),('quantangshi-41364','句','李濤','quantangshi','','卷42','溪声长在耳，山色不离门。
扫地树留影，拂妆琴有声。
一言寤主宁复听，三谏不从归去来。','',''),('quantangshi-41365','灵溪老松歌','盧士衡','quantangshi','','卷42','灵溪古观坛西角，千尺鳞皴栋梁朴。
横出一枝戛楼阁，直上一枝扫寥廊。
白石苍苔拥根脚，月明风憾寒光落。
有时风雨晦瞑，摆撼若黑龙之腾跃。
合生于象外峰峦，枉滞乎人间山岳。
安得巨灵受请托，拔向青桂白榆边安着。','',''),('quantangshi-41366','游灵溪观','盧士衡','quantangshi','','卷42','云藏宝殿风尘外，粉壁松轩入看初。
话久仙童颜色老，病来玄鹤羽毛疎。
樵翁接引寻红术，道士留连说紫书。
不为壮心降未得，便堪从此翫清虚。','',''),('quantangshi-41367','寄天台道友','盧士衡','quantangshi','','卷42','相思遥指玉霄峰，怅望江上阻万重。
曾隔晓窗闻法鼓，几同寒榻听疎钟。
别来知子长餐栢，吟处将谁对倚松。
且住人间行圣教，莫思天路便登龙。','',''),('quantangshi-41368','花落','盧士衡','quantangshi','','卷42','迎风啸未已，和雨落谷谷。
千枝与万枝，不如一竿竹。','',''),('quantangshi-41369','钟陵铁柱','盧士衡','quantangshi','','卷42','千年埋没竟何为，变化宜将万物齐。
安得风胡借方便，铸成神剑斩鲸鲵。','',''),('quantangshi-41370','僧房听雨','盧士衡','quantangshi','','卷42','古寺松轩雨声别，寒窗听久诗魔发。
记得年前在赤城，石楼梦觉三更雪。','',''),('quantangshi-41371','题牡丹','盧士衡','quantangshi','','卷42','万叶红绡翦尽春，丹青任写不如真。
风光九十无多日，难惜尊前折赠人。','',''),('quantangshi-41372','祖龙词','熊皦','quantangshi','','卷42','平吞六国更何求，童女童男问十洲。
沧海不回应怅望，始知徐福解风流。','',''),('quantangshi-41373','谪居海上','熊皦','quantangshi','','卷42','家临泾水隔秦川，来往关河路八千。
堪恨此身何处老，始皇桥畔又经年。','',''),('quantangshi-41374','冬日原居酬光上人见访','熊皎','quantangshi','','卷42','吾道丧已久，吾师何此来。
门无尘事闭，卷有国风开。
野迥霜先白，庭荒叶自堆。
寒暄吟罢后，犹喜话天台。','',''),('quantangshi-41375','早梅','熊皎','quantangshi','','卷42','江南近腊时，已亚雪中枝。
一夜欲开尽，百花犹未知。
人情皆共惜，天意欲教迟。
莫讶无浓艳，芳筵正好吹。','',''),('quantangshi-41376','怀三茅道友','熊皎','quantangshi','','卷42','尘事何年解客嘲，十年容易到三茅。
长思碧洞云窗下，曾借黄庭雪夜抄。
丹桂有心凭至论，五峰无信问深交。
杏坛仙侣应相笑，只为浮名未肯抛。','',''),('quantangshi-41377','赠胥尊师','熊皎','quantangshi','','卷42','绿发童颜羽服轻，天台王屋几经行。
云程去速因风起，酒债还迟待药成。
房闭十洲烟浪阔，箓开三洞鬼神惊。
他年华表重归日，却恐桑田已变更。','',''),('quantangshi-41378','句','熊皎','quantangshi','','卷42','山前犹见月，陌上未逢人。
果熟秋先落，禽寒夜未栖。
深逢野草皆为药，静见樵人恐是仙。
厌听啼鸟梦醒后，慵扫落花春尽时。
废土有人耕不畏，古厅无讼醉何妨。','',''),('quantangshi-41379','塞上','趙延壽','quantangshi','','卷42','黄沙风卷半空抛，云动阴山雪满郊。
探水人回移帐就，射雕箭落着弓抄。
鸟逢霜果饥还啄，马渡冰河渴自跑。
占得高原肥草地，夜深生火折林梢。','',''),('quantangshi-41380','棊','高輦','quantangshi','','卷42','野客围棊坐，搘颐向暮秋。
不言如守默，设计似平雠。
决胜虽关勇，防危亦合忧。
看他终一局，白却少年头。','',''),('quantangshi-41381','句','高輦','quantangshi','','卷42','飘飘送下遥天雪，飒飒吹干旅舍烟。','',''),('quantangshi-41382','与李专美','韓昭裔','quantangshi','','卷42','昭裔登庸汝未登，凤池鸡树冷如冰。
何如且作宣徽使，免被人呼粥饭僧。','',''),('quantangshi-41383','题龙窝洞','張仁溥','quantangshi','','卷42','折花携酒看龙窝，镂玉长旌俊彦过。
他日各为云外客，碧纱笼却又如何。','',''),('quantangshi-41384','留题座主和凝旧阁','李瀚','quantangshi','','卷42','座主登庸归凤阙，门生批诏立鳌头。
玉堂旧阁多珍玩，可作西斋润笔不。','',''),('quantangshi-41385','题家园','楊昭儉','quantangshi','','卷42','池莲憔悴无颜色，园竹低垂减翠阴。
园竹池莲莫惆怅，相看恰似主人心。','',''),('quantangshi-41386','书从事厅屏上','劉坦','quantangshi','','卷42','金殿试回新折桂，将军留辟向江城。
思量一醉犹难得，辜负扬州管记名。','',''),('quantangshi-41387','题施璘画竹图','韋遵','quantangshi','','卷42','枯箨危根缴石头，千竿交映近清流。
堪珍仲宝穷幽笔，留得荆湘一片秋。','',''),('quantangshi-41388','陪游凤皇台献诗','齊丘','quantangshi','','卷42','嵯峨压洪泉，岝峉撑碧落。
宜哉秦始皇，不驱亦不凿。
上有布政台，八顾背城郭。
山蹙龙虎健，水黑螭蜃作。
白虹欲吞人，赤骥相𤍿㩧。
画栋泥金碧，石路盘墝埆。
倒挂哭月猿，危立思天鹤。
凿池养蛟龙，栽桐栖鸑鷟。
梁间燕教雏，石罅蛇悬壳。
养花如养贤，去草如去恶。
日晚严城鼓，风来萧寺铎。
扫地驱尘埃，翦蒿除鸟雀。
金桃带叶摘，绿李和衣嚼。
贞竹无盛衰，媚柳先摇落。
尘飞景阳井，草合临春阁。
芙蓉如佳人，回首似调谑。
当轩有直道，无人肯驻脚。
夜半鼠窸窣，天阴鬼敲啄。
松孤不易立，石丑难安着。
自怜啄木鸟，去蠹终不错。
晚风吹梧桐，树头鸣嚗嚗。
峨峨江令石，青苔何淡薄。
不话兴亡事，举首思眇邈。
吁哉未到此，褊劣同尺蠖。
笼鹤羡凫毛，猛虎爱蜗角。
一日贤太守，与我观橐龠。
往往独自语，天帝相唯诺。
风云偶不来，寰宇销一略。
我欲烹长鲸，四海为鼎镬。
我欲取大鹏，天地为矰缴。
安得生羽翰，雄飞上寥廓。','',''),('quantangshi-41389','赠仰山慧度禅师','齊丘','quantangshi','','卷42','初闻如自解，及见胜初闻。
两鬓堆残雪，一身披断云。
道应齐古佛，高不揖吾君。
稽首清凉月，萧然万象分。','',''),('quantangshi-41390','陪华林园试小妓羯鼓','齊丘','quantangshi','','卷42','切断牙牀镂紫金，最宜平稳玉槽深。
因逢淑景开佳宴，为出花奴奏雅音。
掌底轻璁孤鹊噪，枝头干快乱蝉吟。
开元天子曾如此，今日将军好用心。','',''),('quantangshi-41391','句','齊丘','quantangshi','','卷42','大似贤臣扶社稷，遇明则见暗还藏。','',''),('quantangshi-41392','早朝','馮延巳','quantangshi','','卷42','铜壶滴漏初昼，高阁鸡鸣半空。
催启五门金锁，犹垂三殿帘栊。
阶前御柳摇绿，仗下宫花散红。
鸳瓦数行晓日，鸾旗百尺春风。
侍臣踏舞重拜，圣寿南山永同。','',''),('quantangshi-41393','句','馮延巳','quantangshi','','卷42','青楼阿监应相笑，书记登坛又却回。','',''),('quantangshi-41394','感怀诗二章 一','韓熙載','quantangshi','','卷42','仆本江北人，今作江南客。
再去江北游，举目无相识。
金风吹我寒，秋月为谁白。
不如归去来，江南有人忆。','',''),('quantangshi-41395','感怀诗二章 二','韓熙載','quantangshi','','卷42','未到故乡时，将为故乡好。
及至亲得归，争如身不到。
目前相识无一人，出入空伤我怀抱。
风雨萧萧旅馆秋，归来窗下和衣倒。
梦中忽到江南路，寻得花边旧居处。
桃脸蛾眉笑出门，争向前头拥将去。','',''),('quantangshi-41396','溧水无相寺赠僧','韓熙載','quantangshi','','卷42','无相景幽远，山屏四面开。
凭师领鹤去，待我挂冠来。
药为依时采，松宜绕舍栽。
林泉自多兴，不是效刘雷。','',''),('quantangshi-41397','书歌妓泥金带','韓熙載','quantangshi','','卷42','风柳摇摇无定枝，阳台云雨梦中归。
他年蓬岛音尘断，留取尊前旧舞衣。','',''),('quantangshi-41398','送徐铉流舒州','韓熙載','quantangshi','','卷42','昔年凄断此江湄，风满征帆泪满衣。
今日重怜鹡鸰羽，不堪波上又分飞。','',''),('quantangshi-41399','句','韓熙載','quantangshi','','卷42','几人平地上，看我半天中。','',''),('quantangshi-41400','登祝融峰','李徵古','quantangshi','','卷42','欲上祝融峰，先登古石桥。
凿开巇嶮处，取路到丹霄。','',''),('quantangshi-41401','七岁吟','潘佑','quantangshi','','卷42','朝游沧海东，暮归何太速。
祗因骑折白龙腰，谪向人间三十六。','',''),('quantangshi-41402','送许处士坚往茅山','潘佑','quantangshi','','卷42','天坛云似雪，玉洞水如琴。
白云与流水，千载清人心。
君携布囊去，路长风满林。
一入华阳洞，千秋那可寻。','',''),('quantangshi-41403','送人往宣城','潘佑','quantangshi','','卷42','江畔送行人，千山生暮氛。
谢安团扇上，为画敬亭云。','',''),('quantangshi-41404','失题','潘佑','quantangshi','','卷42','谁家旧宅春无主，深院帘垂杏花雨。
香飞绿琐人未归，巢燕承尘默无语。','',''),('quantangshi-41405','句','潘佑','quantangshi','','卷42','劝君此醉直须欢，明朝又是花狼藉。','',''),('quantangshi-41406','寄孟宾于','李昉','quantangshi','','卷42','初携书劒别湘潭，金榜标名第十三。
昔日声名喧洛下，近来诗价满江南。
长为邑令情终屈，纵处曹郎志未甘。
莫学冯唐便休去，明君晚事未为惭。','',''),('quantangshi-41407','送孟宾于','馬致恭','quantangshi','','卷42','曾闻洛下缀神仙，火树南栖几十年。
白首自忻丹桂在，诗名已得四方传。
行随秋渚将归雁，吟傍梅花欲雪天。
今日还家莫惆怅，不同初上渡头船。','',''),('quantangshi-41408','奉和圣制元日大雪登楼','張義方','quantangshi','','卷42','恰当岁日纷纷落，天宝瑶花助物华。
自古最先标瑞牒，有谁轻拟比杨花。
密飘粉署光同冷，静压青松势欲斜。
岂但小臣添兴咏，狂歌醉舞一家家。','',''),('quantangshi-41409','中酒寄刘行军','李建勳','quantangshi','','卷42','甚矣频频醉，神昏体亦虚。
肺伤徒问药，发落不盈梳。
恋寝嫌明室，修生愧道书。
西峯老僧语，相劝合何如。','',''),('quantangshi-41410','白雁','李建勳','quantangshi','','卷42','东溪一白雁，毛羽何皎洁。
薄暮浴清波，斜阳共明灭。
差池失羣久，幽独依人切。
旅食赖菰蒲，单栖怯霜雪。
边风昨夜起，顾影空哀咽。
不及墙上乌，相将绕双阙。','',''),('quantangshi-41411','早春寄怀','李建勳','quantangshi','','卷42','家山归未得，又是看春过。
老觉光阴速，闲悲世路多。
风和吹岸柳，雪尽见庭莎。
欲向东溪醉，狂眠一放歌。','',''),('quantangshi-41412','春日东山正堂作','李建勳','quantangshi','','卷42','身闲赢得出，天气渐暄和。
蜀马登山稳，南朝古寺多。
早花微弄色，新酒欲生波。
从此唯行乐，闲愁奈我何。','',''),('quantangshi-41413','春日小园晨看兼招同舍','李建勳','quantangshi','','卷42','最有杏花繁，枝枝若手抟。
须知一春促，莫厌百回看。
鸟啭风潜息，蜂迟露未干。
可容排饮否，兼折赠头冠。','',''),('quantangshi-41414','惜花寄孙员外','李建勳','quantangshi','','卷42','朝始一枝开，暮复一枝落。
只恐雨淋漓，又见春萧索。
侵晨结驷携酒徒，寻芳踏尽长安衢。
思量少壮不自乐，他日白头空叹吁。','',''),('quantangshi-41415','春日病中','李建勳','quantangshi','','卷42','才得归闲去，还教病卧频。
无由全胜意，终是负青春。
绿柳渐拂地，黄莺如唤人。
方为医者劝，断酒已经旬。','',''),('quantangshi-41416','殴妓','李建勳','quantangshi','','卷42','自为专房甚，怱怱有所伤。
当时心已悔，彻夜手犹香。
恨枕堆云髻，啼襟揾月黄。
起来犹忍恶，剪破绣鸳鸯。','',''),('quantangshi-41417','踏青罇前','李建勳','quantangshi','','卷42','期君速行乐，不要旋还家。
永日虽无雨，东风自落花。
诗毫黏酒淡，歌袖向人斜。
薄暮忘归路，垂杨噪乱鵶。','',''),('quantangshi-41418','正月晦日','李建勳','quantangshi','','卷42','莫倦寻春去，都无百日游。
更堪正月过，已是一分休。
泉暖声才出，云寒势未收。
晚来重作雪，翻为杏花愁。','',''),('quantangshi-41419','惜花','李建勳','quantangshi','','卷42','白发今如此，红芳莫更催。
预愁多日谢，翻怕十分开。
点滴无时雨，荒凉满地苔。
闲堦一杯酒，惟待故人来。','',''),('quantangshi-41420','金谷园落花','李建勳','quantangshi','','卷42','愁见清明后，纷纷盖地红。
惜看难过日，自落不因风。
蝶散余香在，莺啼半树空。
堪悲一尊酒，从此似西东。','',''),('quantangshi-41421','柳花寄宋明府','李建勳','quantangshi','','卷42','每爱江城里，青春向尽时。
一回新雨歇，是处好风吹。
破石黏虫网，高楼扑酒旗。
遥知陶令宅，五树正离披。','',''),('quantangshi-41422','送人','李建勳','quantangshi','','卷42','相见未逾月，堪悲远别离。
非君谁顾我，万里又南之。
雨逼清明日，花阴杜宇时。
愁看挂帆处，鸥鸟共迟迟。','',''),('quantangshi-41423','闲游','李建勳','quantangshi','','卷42','携酒复携觞，朝朝一似忙。
马谙频到路，僧借旧眠牀。
道胜他图薄，身闲白日长。
扁舟动归思，高处见沧浪。','',''),('quantangshi-41424','栢梁隔句韵诗','李建勳','quantangshi','','卷42','不喜长亭柳，枝枝拟送君。
惟怜北窗□，树树解留人。
圆缺都如月，东西只似云。
愁看离席散，归盖动行尘。','',''),('quantangshi-41425','赠赵学士','李建勳','quantangshi','','卷42','常钦赵夫子，远作五侯宾。
见面到今日，操心如古人。
醉同华席少，吟访野僧频。
寂寂长河畔，荒斋与庙隣。','',''),('quantangshi-41426','春阴','李建勳','quantangshi','','卷42','老雨不肯休，东风势还作。
未放草蒙茸，已遣花萧索。
浮生何苦劳，触事妨行乐。
寄语达生人，须知酒胜药。','',''),('quantangshi-41427','春日金谷园','李建勳','quantangshi','','卷42','火急召亲宾，欢游莫厌频。
日长徒似岁，花过即非春。
晚雨来何定，东风自不匀。
须知三个月，不是负芳晨。','',''),('quantangshi-41428','夏日酬祥松二公见访','李建勳','quantangshi','','卷42','多谢空门客，时时出草堂。
从容非有约，淡薄不相忘。
池映春篁老，檐垂夏果香。
西峯正清霁，自与拂吟牀。','',''),('quantangshi-41429','怀赠操禅师','李建勳','quantangshi','','卷42','尝忆曹溪子，龛居面碧嵩。
杉松新夏后，雨雹夜禅中。
道匪因经悟，心能向物空。
秋来得音信，又在剡山东。','',''),('quantangshi-41430','闲居秋思呈祥松二字','李建勳','quantangshi','','卷42','秋光虽即好，客思转悠哉。
去国身将老，流年雁又来。
叶红堆晚径，菊冷藉空罍。
不得师相访，难将道自开。','',''),('quantangshi-41431','赋得冬日青溪草堂四十字','李建勳','quantangshi','','卷42','莫道无幽致，常来到日西。
地虽当北阙，天与设东溪。
疎苇寒多折，惊凫去不齐。
坐中皆作者，长爱觅分题。','',''),('quantangshi-41432','溪斋','李建勳','quantangshi','','卷42','水木遶吾庐，搴帘晚槛虚。
衰条寒露鹊，幽果落惊鱼。
爱酒贫还甚，趋时老更疎。
乖慵自有素，不是忽簪裾。','',''),('quantangshi-41433','留题爱敬寺','李建勳','quantangshi','','卷42','野性竟未改，何以居朝廷。
空为百官首，但爱千峯青。
南风新雨后，与客携觞行。
斜阳惜归去，万壑啼鸟声。','',''),('quantangshi-41434','小园','李建勳','quantangshi','','卷42','小园吾所好，栽植忘劳形。
晚果经秋赤，寒蔬近社青。
竹萝荒引蔓，土井浅生萍。
更欲从人劝，凭高置草亭。','',''),('quantangshi-41435','宿山房','李建勳','quantangshi','','卷42','石窗灯欲尽，松槛月还明。
就枕浑无睡，披衣却出行。
岩高泉乱滴，林动鸟时惊。
倏忽山钟曙，喧喧仆马声。','',''),('quantangshi-41436','金陵所居青溪草堂闲兴','李建勳','quantangshi','','卷42','窗外皆连水，杉松欲作林。
自怜趋竞地，独有爱闲心。
素壁题看遍，危冠醉不簪。
江僧暮相访，帘卷见秋岑。','',''),('quantangshi-41437','阙下偶书寄孙员外','李建勳','quantangshi','','卷42','长安驱驰地，贵贱共悠悠。
白日谁相促，劳生自不休。
凤翔双阙晓，蝉噪六街秋。
独有南宫客，时来话钓舟。','',''),('quantangshi-41438','寄魏郎中','李建勳','quantangshi','','卷42','碌碌但随羣，蒿兰任不分。
未尝矜有道，求遇向吾君。
逸驾秋寻寺，长歌醉望云。
高斋纸屏古，尘暗北山文。','',''),('quantangshi-41439','病中书怀寄王二十六','李建勳','quantangshi','','卷42','落叶满山州，闲眠病未瘳。
窗阴连竹枕，药气染茶瓯。
路匪人遮去，官须自觅休。
焉宜更羸老，扶杖作公侯。','',''),('quantangshi-41440','采菊','李建勳','quantangshi','','卷42','簇簇竟相鲜，一枝开几番。
味甘资麴糵，香好胜兰荪。
古道风摇远，荒篱露压繁。
盈筐时采得，服饵近知门。','',''),('quantangshi-41441','送王郎中之官吉水','李建勳','quantangshi','','卷42','南望庐陵郡，山连五岭长。
吾君怜远俗，从事辍名郎。
移户多无土，春蚕不满筐。
惟应劳赞画，溪峒况彊梁。','',''),('quantangshi-41442','孤雁','李建勳','quantangshi','','卷42','欲食不敢食，合栖犹未栖。
闻风亦惊过，避缴恨飞低。
水阔缘湘因，云寒过碛迷。
悲鸣感人意，不见夜乌啼。','',''),('quantangshi-41443','赠送致仕郎中','李建勳','quantangshi','','卷42','鹤立瘦棱棱，髭长白似银。
衣冠皆古制，气貌异常人。
听雪添诗思，看山滞酒巡。
西峯重归路，唯许野僧亲。','',''),('quantangshi-41444','宿友人山居寄司徒相公 一','李建勳','quantangshi','','卷42','雨雪正霏霏，令人不忆归。
地炉僧坐暖，山枿火声肥。
隔纸烘茶蘂，移铛剥芋衣。
知君在霄汉，此兴得还稀。','',''),('quantangshi-41445','宿友人山居寄司徒相公 二','李建勳','quantangshi','','卷42','郢客相寻夜，荒庭雪洒篙。
虚堂看向曙，吟坐共忘劳。
溪冻声全减，灯寒焰不高。
他人莫相笑，未易会吾曹。','',''),('quantangshi-41446','感故府二首 一','李建勳','quantangshi','','卷42','戚戚复戚戚，期怀安可释。
百年金石心，中路生死隔。
新坟应草合，旧地空苔色。
白日灯荧荧，凝尘满几席。','',''),('quantangshi-41447','感故府二首 二','李建勳','quantangshi','','卷42','悒悒复悒悒，思君安可及。
永日在堦前，披衣随风立。
高楼暮角断，远树寒鸦集。
惆怅几行书，遗踪墨犹湿。','',''),('quantangshi-41448','田家三首 一','李建勳','quantangshi','','卷42','毕岁知无事，兵销复旧丁。
竹门桑径狭，春日稻畦青。
犬吠隈篱落，鸡飞上碓桯。
归田起□思，蛙叫草冥冥。','',''),('quantangshi-41449','田家三首 二','李建勳','quantangshi','','卷42','不识城中路，熙熙乐有年。
木盘擎社酒，瓦鼓送神钱。
霜落牛归屋，禾收雀满田。
遥陂过秋水，闲阁钓鱼船。','',''),('quantangshi-41450','田家三首 三','李建勳','quantangshi','','卷42','长爱田家事，时时欲一过。
垣篱皆树槿，厅院亦堆禾。
病果因风落，寒蔬向日多。
遥闻数声笛，牛晚下前坡。','',''),('quantangshi-41451','新竹','李建勳','quantangshi','','卷42','袅袅薰风软，娟娟湛露光。
参差仙子仗，迤逦羽林枪。
迥去侵花地，斜来破藓墙。
箨干犹抱翠，粉腻若涂装。
迳曲茎难数，阴疎叶未长。
嬾嫌吟客倚，甘畏夏虫伤。
映水如争立，当轩自着行。
北庭尊酒兴，还为此君狂。','',''),('quantangshi-41452','归燕词','李建勳','quantangshi','','卷42','羽翼势虽微，云霄亦可期。
飞翻自有路，鸿鹄莫相嗤。
待侣临书幌，寻泥傍藻池。
冲人穿柳径，捕蝶遶花枝。
广厦来应徧，深宫去不疑。
雕梁声上下，烟浦影参差。
旧地人潜换，新巢雀谩窥。
双双暮归处，疎雨满江湄。','',''),('quantangshi-41453','题魏坛二首 一','李建勳','quantangshi','','卷42','不遇至真传道要，曾看真诰亦何为。
旧碑经乱沈荒涧，灵篆因耕出故基。
蛙黾自喧浇药井，牛羊闲过放生池。
萧条夕景空坛畔，朽桧枝斜绿蔓垂。','',''),('quantangshi-41454','题魏坛二首 二','李建勳','quantangshi','','卷42','一寻遗迹到仙乡，云鹤沈沈思渺茫。
丹井岁深生草木，芝田春废卧牛羊。
雨淋残画摧荒壁，鼠引饥虵落坏梁。
薄暮欲归仍伫立，菖蒲风起水泱泱。','',''),('quantangshi-41455','东楼看雪','李建勳','quantangshi','','卷42','一上高楼醉复醒，日西江雪更冥冥。
化风吹火全无气，平望惟松少露青。
腊内不妨南地少，夜长应得小窗听。
因思旧隐匡庐日，闲看杉柽掩石扃。','',''),('quantangshi-41456','落花','李建勳','quantangshi','','卷42','惜花无计又花残，独遶芳丛不忍看。
暖艳动随莺翅落，冷香愁杂燕泥干。
绿珠倚槛魂初散，巫峡归云梦又阑。
忍把一尊重命乐，送春招客亦何欢。','',''),('quantangshi-41457','春雪','李建勳','quantangshi','','卷42','南国春寒朔气回，霏霏还阻百花开。
全移暖律何方去，似误新莺昨日来。
平野旋销难蔽草，远林高缀却遮梅。
不知金勒谁家子，只待晴明赏帝台。','',''),('quantangshi-41458','重戏和春雪寄沈员外','李建勳','quantangshi','','卷42','谁道江南要雪难，半春犹得倚楼看。
却遮迟日偷莺暖，密洒西风借鹤寒。
散漫不容梨艳去，轻明应笑玉华干。
和来琼什虽无敌，且是侬家比兴残。','',''),('quantangshi-41459','春日尊前示从事','李建勳','quantangshi','','卷42','州中案牍鱼鳞密，界上军书竹节稠。
眼底好花浑似雪，瓮头春酒漫如油。
东君不为留迟日，清镜唯知促白头。
最觉此春无气味，不如庭草解忘忧。','',''),('quantangshi-41460','尊前','李建勳','quantangshi','','卷42','官为将相复何求，世路多端早合休。
渐老更知春可惜，正欢唯怕客难留。
雨催草色还依旧，晴放花枝始自由。
莫厌百壶相劝倒，免教无事结闲愁。','',''),('quantangshi-41461','蔷薇二首 一','李建勳','quantangshi','','卷42','万蘂争开照槛光，诗家何物可相方。
锦江风撼云霞碎，仙子衣飘黼黻香。
裛露早英浓压架，背人狂蔓暗穿墙。
彩牋蛮榼旬休日，欲召亲宾看一场。','',''),('quantangshi-41462','蔷薇二首 二','李建勳','quantangshi','','卷42','拂檐拖地对前墀，蝶影蜂声烂熳时。
万倍馨香胜玉蘂，一生颜色笑西施。
忘归醉客临高架，恃宠佳人索好枝。
将并舞腰谁得及，惹衣伤手尽从伊。','',''),('quantangshi-41463','残牡丹','李建勳','quantangshi','','卷42','肠断题诗如执别，芳茵愁更绕阑铺。
风飘金蘂看全落，露滴檀英又暂苏。
失意婕妤妆渐薄，背身妃子病难扶。
回看池馆春休也，又是迢迢看画图。','',''),('quantangshi-41464','春雨二首 一','李建勳','quantangshi','','卷42','春霖未免妨游赏，唯到诗家自有情。
花径不通新草合，兰舟初动曲池平。
净缘高树莓苔色，饥集虚廊燕雀声。
闲忆昔年为客处，闷留山馆阻行行。','',''),('quantangshi-41465','春雨二首 二','李建勳','quantangshi','','卷42','萧萧春雨密还疎，景象三时固不如。
寒入远林莺翅重，暖抽新麦土膏虚。
细蒙台榭微兼日，潜涨涟漪欲动鱼。
唯称乖慵多睡者，掩门中酒览闲书。','',''),('quantangshi-41466','醉中惜花更书与诸从事','李建勳','quantangshi','','卷42','公退寻芳已是迟，莫因他事更来稀。
未经旬日唯忧落，算有开时不合归。
歌槛宴余风褭褭，闲园吟散雨霏霏。
高楼鼓绝重门闭，长为抛回恨解衣。','',''),('quantangshi-41467','和判官喜雨','李建勳','quantangshi','','卷42','去祷山川尚未还，云雷寻作远声寒。
人情便似秋登悦，天色休劳夜起看。
高槛气浓藏柳郭，小庭流拥没花坛。
须知太守重墙内，心极农夫望处欢。','',''),('quantangshi-41468','离阙下日感恩','李建勳','quantangshi','','卷42','二年尘冒处中台，喜得南归退不才。
即路敢期皇子送，出关犹有御书来。
未知天地恩何报，翻对江山思莫开。
斜日苇汀凝立处，远波微扬翠如苔。','',''),('quantangshi-41469','细雨遥怀故人','李建勳','quantangshi','','卷42','江云未散东风暖，溟蒙正在高楼见。
细柳缘堤少过人，平芜隔水时飞燕。
我有近诗谁与和，忆君狂醉愁难破。
昨夜南窗不得眠，闲堦点滴回灯坐。','',''),('quantangshi-41470','春水','李建勳','quantangshi','','卷42','万派争流雨过时，晚来春静更逶迤。
轻鸥散遶夫差国，远树微分夏禹祠。
青岸渐平濡柳带，旧溪应暖负莼丝。
风鬟倚檝谁家子，愁看鸳鸯望所之。','',''),('quantangshi-41471','蝶','李建勳','quantangshi','','卷42','粉蝶翩翩若有期，南园长是到春归。
闲依柳带参差起，困傍桃花独自飞。
潜被燕惊还散乱，偶因人逐入帘帏。
晚来欲雨东风急，回看池塘影渐稀。','',''),('quantangshi-41472','中春写怀寄沈彬员外','李建勳','quantangshi','','卷42','省从骑竹学讴吟，便殢光阴役此心。
寓目不能闲一日，闭门长胜得千金。
窗悬夜雨残灯在，庭掩春风落絮深。
唯有故人同此兴，近来何事嬾相寻。','',''),('quantangshi-41473','钟山寺避暑勉二三子','李建勳','quantangshi','','卷42','楼台虽少景何深，满地青苔胜布金。
松影晚留僧共坐，水声闲与客同寻。
清凉会拟归莲社，沈湎终须弃竹林。
长爱寄吟经案上，石窗秋霁向千岑。','',''),('quantangshi-41474','道林寺','李建勳','quantangshi','','卷42','虽向钟峯数寺连，就中奇胜出其间。
不教幽树妨闲地，别着高窗向远山。
莲沼水从双涧入，客堂僧自九华还。
无因得结香灯社，空向王门玷玉班。','',''),('quantangshi-41475','和致仕沈郎中','李建勳','quantangshi','','卷42','欲谋休退尚因循，且向东溪种白苹。
谬应星辰居四辅，终期冠褐作闲人。
城中隔日趋朝嬾，楚外千峯入梦频。
残照晚庭沈醉醒，静吟斜倚老松身。','',''),('quantangshi-41476','醉中咏梅花','李建勳','quantangshi','','卷42','十月清霜尚未寒，雪英重叠已如抟。
还悲独咏东园里，老作南州刺史看。
北客见皆惊节气，郡僚痴欲望杯盘。
交亲罕至长安远，一醉如泥岂自欢。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-41477','闲出书怀','李建勳','quantangshi','','卷42','闲游何用问东西，寓兴皆非有所期。
断酒只携僧共去，看山从听马行迟。
溪田雨涨禾生耳，原野莺啼黍熟时。
应有交亲长笑我，独轻人事鬓将衰。','',''),('quantangshi-41478','寺居陆处士相访感怀却寄二三友人','李建勳','quantangshi','','卷42','湘寺闲居亦半年，就中昨夜好潸然。
人归远岫疎钟后，雪打高杉古屋前。
投足正逢他国乱，冥心未解祖师禅。
炉烟向冷孤灯下，唯有寒吟到曙天。','',''),('quantangshi-41479','春雪','李建勳','quantangshi','','卷42','随风竟日势漫漫，特地繁于故岁看。
幽榭冻黏花屋重，短檐斜湿燕巢寒。
闲听不寐诗魂爽，净吃无厌酒肺干。
莫道便为桑麦药，亦胜焦涸到春残。','',''),('quantangshi-41480','惜花','李建勳','quantangshi','','卷42','淡淡西园日又垂，一尊何忍负芳枝。
莫言风雨长相促，直是晴明得几时。
心破只愁莺践落，眼穿唯怕客来迟。
年年使我成狂叟，肠断红牋几首诗。','',''),('quantangshi-41481','梅花寄所亲','李建勳','quantangshi','','卷42','一气才新物未知，每慙青律与先吹。
雪霜迷素犹嫌早，桃杏虽红且后时。
云鬓自黏飘处粉，玉鞭谁指出墙枝。
老夫多病无风味，只向尊前咏旧诗。','',''),('quantangshi-41482','登升元阁','李建勳','quantangshi','','卷42','登高始觉太虚宽，白雪须知唱和难。
云渡琐窗金牓湿，月移珠箔水精寒。
九天星象帘前见，六代城池直下观。
唯有上层人未到，金乌飞过拂阑干。','',''),('quantangshi-41483','雪有作','李建勳','quantangshi','','卷42','霏霏奕奕满寒空，况是难逢值腊中。
未白已堪张宴会，渐繁偏好去帘栊。
庭莎易集看盈地，池柳难装旋逐风。
长爱清华入诗句，预愁迟日放消融。','',''),('quantangshi-41484','宫词','李建勳','quantangshi','','卷42','自远凝旒守上阳，舞衣顿减旧朝香。
帘垂粉阁春将尽，门掩梨花日渐长。
草色深浓封辇路，水声低咽转宫墙。
君王一去不回驾，皓齿青蛾空断肠。','',''),('quantangshi-41485','晚春送牡丹','李建勳','quantangshi','','卷42','携觞邀客遶朱阑，肠断残春送牡丹。
风雨数来留不得，离披将谢忍重看。
氛氲兰麝香初减，零落云霞色渐干。
借问少年能几许，不须推酒厌杯盘。','',''),('quantangshi-41486','岁暮晚泊望庐山不见因怀岳僧呈察判','李建勳','quantangshi','','卷42','贪程只为看庐阜，及到停舟恨颇浓。
云暗半空藏万仞，雪迷双瀑在中峯。
林端莫辨曾游路，鸟际微闻向暮钟。
长愧昔年招我入，共寻香社见芙蓉。','',''),('quantangshi-41487','重台莲','李建勳','quantangshi','','卷42','斜倚秋风绝比伦，千英和露染难匀。
自为祥瑞生南国，谁把丹青寄北人。
明月几宵同绿水，牡丹无路出红尘。
怜伊不算多时立，赢得馨香暗上身。','',''),('quantangshi-41488','迎神','李建勳','quantangshi','','卷42','攂蛮鼍，吟塞笛，女巫结束分行立。
空中再拜神且来，满奠椒浆齐献揖。
阴风窣窣吹纸钱，妖巫瞑目传神言。
与君降福为丰年，莫教赛祀亏常筵。','',''),('quantangshi-41489','春词','李建勳','quantangshi','','卷42','日高闲步下堂阶，细草春莎没绣鞋。
折得玫瑰花一朵，凭君簪向凤皇钗。','',''),('quantangshi-41490','独夜作','李建勳','quantangshi','','卷42','佳人一去无消息，梦觉香残愁复入。
空庭悄悄月如霜，独倚阑干伴花立。','',''),('quantangshi-41491','竹','李建勳','quantangshi','','卷42','琼节高吹宿凤枝，风流交我立忘归。
最怜瑟瑟斜阳下，花影相和满客衣。','',''),('quantangshi-41492','清明日','李建勳','quantangshi','','卷42','他皆携酒寻芳去，我独关门好静眠。
唯有杨花似相觅，因风时复到牀前。','',''),('quantangshi-41493','宫词','李建勳','quantangshi','','卷42','宫门长闭舞衣闲，略识君王鬓便斑。
却羡落花春不管，御沟流得到人间。','',''),('quantangshi-41494','送喻炼师归茅山','李建勳','quantangshi','','卷42','休粮知几载，脸色似桃红。
半醉离城去，单衣行雪中。
水声茅洞晓，云影石房空。
莫学秦时客，音书便不通。','',''),('quantangshi-41495','和元宗元日大雪登楼','李建勳','quantangshi','','卷42','纷纷忽降当元曾，着物轻明似月华。
狂洒玉墀初散絮，密黏宫树未妨花。
迥封双阙千寻峭，冷压南山万仞斜。
宁意传来中使出，御题先赐老僧家。','',''),('quantangshi-41496','游栖霞寺','李建勳','quantangshi','','卷42','养花天气近平分，瘦马来敲白下门。
晓色未开山意远，春容犹淡月华昏。
琅琊冷落存遗迹，篱舍稀疎带旧村。
此地几经人聚散，只今王谢独名存。','',''),('quantangshi-41497','答汤悦','李建勳','quantangshi','','卷42','司空犹不作，那敢作司徒。
幸有山翁号，如何不见呼。','',''),('quantangshi-41498','金山','李建勳','quantangshi','','卷42','不嗟白发曾游此，不叹征帆无了期。
尽日凭阑谁会我，祗悲不见韩垂诗。','',''),('quantangshi-41499','送李冠','李建勳','quantangshi','','卷42','匀如春涧长流水，怨似秋枝欲断蝉。
可惜人间容易听，清声不到御楼前。','',''),('quantangshi-41500','游宋兴寺东岩','李建勳','quantangshi','','卷42','几年不到东岩下，旧住僧亡屋亦无。
寒日萧条何物在，朽松经烧石池枯。','',''),('quantangshi-41501','批周宗书后','李建勳','quantangshi','','卷42','偶罢阿衡来典郡，固无闲可物应官。
凭君为报羣胥道，莫作循州刺史看。','',''),('quantangshi-41502','题信果观壁','李建勳','quantangshi','','卷42','春来涨水流而活，晓色西山势似行。
玉洞主人经劫在，携竿步步就长生。','',''),('quantangshi-41503','送八分书与友人继以诗','李建勳','quantangshi','','卷42','跁跒为诗跁跒书，不封将去寄仙都。
仙翁拍手应相笑，得似秦朝次仲无。','',''),('quantangshi-41504','句','李建勳','quantangshi','','卷42','桃花流水须长信，不学刘郎去又来。
粟多未必全为计，师老须防有伏兵。
徧寻云壑重题石，欲下山门更倚松。','',''),('quantangshi-41505','蟠溪怀古','孟賓于','quantangshi','','卷42','良哉吕尚父，深隐始归周。
钓石千年在，春风一水流。
松根盘藓石，花影卧沙鸥。
谁更怀韬术，追思古渡头。','',''),('quantangshi-41506','怀连上旧居','孟賓于','quantangshi','','卷42','闲思连上景难齐，树绕仙乡路绕溪。
明月夜舟渔父唱，春风平野鹧鸪啼。
城边寄信归云外，花下倾杯到日西。
更忆海阳垂钓侣，昔年相遇草萋萋。','',''),('quantangshi-41507','公子行','孟賓于','quantangshi','','卷42','锦衣红夺彩霞明，侵晓春游向野庭。
不识农夫辛苦力，骄骢蹋烂麦青青。','',''),('quantangshi-41508','湘江亭','孟賓于','quantangshi','','卷42','独宿大中年里寺，樊笼得出事无心。
寒山梦觉一声磬，霜叶满林秋正深。','',''),('quantangshi-41509','题梅仙馆','孟賓于','quantangshi','','卷42','仙界路遥云缥渺，古坛风冷叶萧骚。
后来岂合言淹滞，一尉升腾道最高。','',''),('quantangshi-41510','题颜氏亭宇','孟賓于','quantangshi','','卷42','园林萧洒闻来久，欲访因循二十秋。
今日开襟吟不尽，碧山重叠水长流。','',''),('quantangshi-41511','晚眺','孟賓于','quantangshi','','卷42','倚杖残秋里，吟中四顾频。
西风天际雁，落日渡头人。
草色衰平野，山阴歛暮尘。
却寻苔径去，明月照村邻。','',''),('quantangshi-41512','献主司','孟賓于','quantangshi','','卷42','那堪雨后更闻蝉，溪隔重湖路七千。
忆昔故园杨柳岸，全家送上渡头船。','',''),('quantangshi-41513','句','孟賓于','quantangshi','','卷42','远树连沙静，闲舟入浦迟。
帘垂羣吏散，苔长讼庭闲。
去年曾折处，今日又垂条。
早知落处随疎雨，悔得开时顺暖风。
千家帘幕春空在，几处楼台月自明。
腊雪化为流水去，春风吹出好山来。
昔日声尘喧洛下，近年诗句满江南。
匝地人家凭槛见，远山秋色卷帘看。
蟾宫空手下，泽国更谁来。
水国二亲应探榜，龙门三月又伤春。
仙鸟却回空说梦，清朝未达自嫌身。
失意从他桃李春，嵩阳经过歇行尘。
云僧不见城中事，问是今年第几人。
因逢日者教重应，忍被云僧劝却归。','',''),('quantangshi-41514','九日陪董内召登高','廖匡圖','quantangshi','','卷42','祝融峰下逢嘉节，相对那能不怆神。
烟里共寻幽磵菊，樽前俱是异乡人。
遥山带日应连越，孤雁来时想别秦。
自古登高尽惆怅，茱萸休笑泪盈巾。','',''),('quantangshi-41515','赠泉陵上人','廖匡圖','quantangshi','','卷42','暂把枯藤倚碧根，禅堂初创楚江濆。
直疑松小难留鹤，未信山低住得云。
草接寺桥牛笛近，日衔村树鸟行分。
每来共忆曾游处，万壑泉声绝顶闻。','',''),('quantangshi-41516','和人赠沈彬','廖匡圖','quantangshi','','卷42','冥鸿迹在烟霞上，燕雀休夸大厦巢。
名利最为浮世重，古今能有几人抛。
逼真但使心无着，混俗何妨手强抄。
深喜卜居连岳色，水边竹下得论交。','',''),('quantangshi-41517','松','廖匡圖','quantangshi','','卷42','曾于西晋封中散，又向东吴作大夫。
浓翠自知千古在，清声谁道四时无。
枝柯偃后龙蛇老，根脚盘来爪距粗。
直待素秋摇落日，始将凡木鬬荣枯。','',''),('quantangshi-41518','句','廖匡圖','quantangshi','','卷42','正悲世上事无限，细看水中尘更多。','',''),('quantangshi-41519','中秋月','廖凝','quantangshi','','卷42','九十日秋色，今宵已半分。
孤光含列宿，四面绝纤云。
众木排疎影，寒流叠细纹。
遥遥望丹桂，心绪正纷纷。','',''),('quantangshi-41520','闻蝉','廖凝','quantangshi','','卷42','一声初应侯，万木已西风。
便感异乡客，先于离塞鸿。
日斜金谷静，雨过石城空。
此处不堪听，萧条千古同。','',''),('quantangshi-41521','彭泽解印','廖凝','quantangshi','','卷42','五斗徒劳谩折腰，三年两鬓为谁焦。
今朝官满重归去，还挈来时旧酒瓢。','',''),('quantangshi-41522','句','廖凝','quantangshi','','卷42','满汀沤不散，一局黑全输。
猎回千帐雪，探密大河冰。
落尽最高树，始知松柏青。
饭僧春岭蕨，醒酒雪潭鱼。
风清竹阁留僧宿，雨湿莎庭放吏衙。
红踯躅繁金殿暖，碧芙蓉笑水宫秋。','',''),('quantangshi-41523','赠廖凝','韋鼎','quantangshi','','卷42','君与白云邻，生涯久忍贫。
姓名高雅道，寰海许何人。
岳气秋来早，亭寒果落新。
几回吟石畔，孤鹤自相亲。','',''),('quantangshi-41524','寄庐山白上人','左偃','quantangshi','','卷42','潦倒门前客，闲眠岁又残。
连天数峰雪，终日与谁看。
万丈高松古，千寻落水寒。
仍闻有新作，嬾寄入长安。','',''),('quantangshi-41525','寄韩侍郎','左偃','quantangshi','','卷42','谋身谋隐两无成，拙计深慙负耦耕。
渐老可堪怀故国，多愁翻觉厌浮生。
言诗幸遇明公许，守朴甘遭俗者轻。
今日况闻搜草泽，独悲顦顇卧升平。','',''),('quantangshi-41526','汉宫词','左偃','quantangshi','','卷42','寒烛照清夜，笙歌隔藓墙。
一从飞燕入，便不见君王。','',''),('quantangshi-41527','送君去','左偃','quantangshi','','卷42','关河月未晓，行子心已急。
佳人无一言，独背残灯泣。','',''),('quantangshi-41528','秋晚野望','左偃','quantangshi','','卷42','倚筇聊一望，何处是秦川？草色初晴路，鸿声欲暮天。','',''),('quantangshi-41529','郊原晚望怀李秘书','左偃','quantangshi','','卷42','归鸟入平野，寒云在远村。
徒令睇望久，不复见王孙。','',''),('quantangshi-41530','言怀别同志','左偃','quantangshi','','卷42','惭老将谁托，劳生每自慙。
何当重携手，风雨满江南。','',''),('quantangshi-41531','江上晚泊','左偃','quantangshi','','卷42','寒云淡淡天无际，片帆落处沙鸥起。
水阔风高日复斜，扁舟独宿芦花里。','',''),('quantangshi-41532','寄鉴上人','左偃','quantangshi','','卷42','一从携手阻戈鋋，屈指如今已十年。
长记二林同宿夜，竹斋听雨共忘眠。','',''),('quantangshi-41533','送人','左偃','quantangshi','','卷42','一茎二茎华发生，千枝万枝梨花白。
春色江南独未归，今朝又送还乡客。','',''),('quantangshi-41534','句','左偃','quantangshi','','卷42','胡笳闻欲死，汉月望还生。
日华离碧海，云影散青霄。','',''),('quantangshi-41535','景阳台怀古','陳貺','quantangshi','','卷42','景阳六朝地，运极自依依。
一会皆同是，到头谁论非。
酒浓沈远虑，花好失前机。
见此尤宜戒，正当家国肥。','',''),('quantangshi-41536','石城怀古','劉洞','quantangshi','','卷42','石城古岸头，一望思悠悠。
几许六朝事，不禁江水流。','',''),('quantangshi-41537','句','劉洞','quantangshi','','卷42','千里长江皆渡马，十年养士得何人。
翻忆潘郎章奏内，愔愔日暮好沾巾。
百骸同草木，万象入心灵。','',''),('quantangshi-41538','旅怀','江爲','quantangshi','','卷42','迢迢江汉路，秋色又堪惊。
半夜闻鸿雁，多年别弟兄。
高风云影断，微雨菊花明。
欲寄东归信，裴回无限情。','',''),('quantangshi-41539','江行','江爲','quantangshi','','卷42','越信隔年稀，孤舟几梦归。
月寒花露重，江晚水烟微。
峰直帆相望，沙空鸟自飞。
何时洞庭上，春雨满蓑衣。','',''),('quantangshi-41540','登润州城','江爲','quantangshi','','卷42','天末江城晚，登临客望迷。
春潮平岛屿，残雨隔虹霓。
鸟与孤帆远，烟和独树低。
乡山何处是，目断广陵西。','',''),('quantangshi-41541','岳阳楼','江爲','quantangshi','','卷42','倚楼高望极，展转念前途。
晚叶红残楚，秋江碧入吴。
云中来雁急，天末去帆孤。
明月谁同我，悠悠上帝都。','',''),('quantangshi-41542','送客','江爲','quantangshi','','卷42','明月孤舟远，吟髭镊更华。
天形围泽国，秋色露人家。
水馆萤交影，霜洲橘委花。
何当寻旧隐，泉石好生涯。','',''),('quantangshi-41543','临刑诗','江爲','quantangshi','','卷42','街鼓侵人急，西倾日欲斜。
黄泉无旅店，今夜宿谁家。','',''),('quantangshi-41544','塞下曲','江爲','quantangshi','','卷42','万里黄云冻不飞，碛烟烽火夜深微。
胡儿移帐寒笳绝，雪路时闻探马归。','',''),('quantangshi-41545','隋堤柳','江爲','quantangshi','','卷42','锦缆龙舟万里来，醉乡繁盛忽尘埃。
空余两岸千株柳，雨叶风花作恨媒。','',''),('quantangshi-41546','句','江爲','quantangshi','','卷42','吟登萧寺旃檀阁，醉倚王家玳瑁筵。
远远朝宗出白云，方圆随处性长存。','',''),('quantangshi-41547','咏鹰','高越','quantangshi','','卷42','雪爪星眸世所稀，摩天专待振毛衣。
虞人莫谩张罗网，未肯平原浅草飞。','',''),('quantangshi-41548','惜花','張泌','quantangshi','','卷42','蝶散莺啼尚数枝，日斜风定更离披。
看多记得伤心事，金谷楼前委地时。','',''),('quantangshi-41549','寄人 一','張泌','quantangshi','','卷42','别梦依依到谢家，小廊回合曲阑斜。
多情只有春庭月，犹为离人照落花。','',''),('quantangshi-41550','寄人 二','張泌','quantangshi','','卷42','酷怜风月为多情，还到春时别恨生。
倚柱寻思倍惆怅，一场春梦不分明。','',''),('quantangshi-41551','边上','張泌','quantangshi','','卷42','戍楼吹角起征鸿，猎猎寒旌背晚风。
千里暮烟愁不尽，一川秋草恨无穷。
山河惨澹关城闭，人物萧条市井空。
只此旅魂招未得，更堪回首夕阳中。','',''),('quantangshi-41552','长安道中早行','張泌','quantangshi','','卷42','客离孤馆一灯残，牢落星河欲曙天。
鸡唱未沈函谷月，雁声新度灞陵烟。
浮生已悟庄周蝶，壮志仍输祖逖鞭。
何事悠悠策羸马，此中辛苦过流年。','',''),('quantangshi-41553','洞庭阻风','張泌','quantangshi','','卷42','空江浩荡景萧然，尽日菰蒲泊钓船。
青草浪高三月渡，绿杨花扑一溪烟。
情多莫举伤春目，愁极兼无买酒钱。
犹有渔人数家住，不成村落夕阳边。','',''),('quantangshi-41554','春日旅泊桂州','張泌','quantangshi','','卷42','暖风芳草竟芊绵，多病多愁负少年。
弱柳未胜寒食雨，好花争奈夕阳天。
溪边物色堪图画，林畔莺声似管弦。
独有离人开泪眼，强凭杯酒亦澘然。','',''),('quantangshi-41555','晚次（一作“歇”）湘源县','張泌','quantangshi','','卷42','烟郭遥闻向晚鸡，水平舟静浪声齐。
高林带雨杨梅熟，曲岸笼云谢豹啼。
二女庙荒汀（一作“宫”）树老，九疑山碧楚天低。
湘南自古多离怨，莫动哀吟易惨凄。','',''),('quantangshi-41556','惆怅吟','張泌','quantangshi','','卷42','秋风丹叶动荒城，惨澹云遮日半明。
昼梦却因惆怅得，晚愁多为别离生。
江淹彩笔空留恨，庄叟玄谭未及情。
千古怨魂销不得，一江寒浪若为平。','',''),('quantangshi-41557','秋晚过洞庭','張泌','quantangshi','','卷42','征帆初挂酒初酣，暮景离情两不堪。
千里晚霞云梦北，一洲霜橘洞庭南。
溪风送雨过秋寺，磵石惊龙落夜潭。
莫把羁魂吊湘魄，九疑愁绝销烟岚。','',''),('quantangshi-41558','题华严寺木塔','張泌','quantangshi','','卷42','六街晴色动秋光，雨霁凭高只易伤。
一曲晚烟浮渭水，半桥斜日照咸阳。
休将世路悲尘事，莫指云山认故乡。
回首汉宫楼阁暮，数声钟鼓自微茫。','',''),('quantangshi-41559','经旧游','張泌','quantangshi','','卷42','暂到高唐晓又还，丁香结梦水潺潺。
不知云雨归何处，历历空留十二山。','',''),('quantangshi-41560','碧户','張泌','quantangshi','','卷42','碧户扃鱼鏁，兰窗掩镜台。
落花疑怅望，归燕自裴回。
咏絮知难敌，伤春不易裁。
恨从芳草起，愁为晚风来。
衣惹湘云薄，眉分楚岫开。
香浓眠旧枕，梦好醉春杯。
小障明金凤，幽屏点翠苔。
宝筝横塞雁，怨笛落江梅。
卓氏仍多酒，相如正富才。
莫教琴上意，翻作鹤声哀。','',''),('quantangshi-41561','芍药','張泌','quantangshi','','卷42','香清粉澹怨残春，蝶翅蜂须恋蘂尘。
闲倚晚风生怅望，静留迟日学因循。
休将薜荔为青琐，好与玫瑰作近邻。
零落若教随暮雨，又应愁杀别离人。','',''),('quantangshi-41562','春晚谣','張泌','quantangshi','','卷42','雨微微，烟霏霏，小庭半拆红蔷薇。
钿筝斜倚画屏曲，零落几行金雁飞。
萧关梦断无寻处，万叠春波起南浦。
凌乱杨花扑绣帘，晚窗时有流莺语。','',''),('quantangshi-41563','所思','張泌','quantangshi','','卷42','空塘水碧春雨微，东风散漫杨柳飞。
依依南浦梦犹在，脉脉高唐云不归。
江头日暮多芳草，极目伤心烟悄悄。
隔江红杏一枝明，似玉佳人俯清沼。
休向春台更回望，销魂自古因惆怅。
银河碧海共无情，两处悠悠起风浪。','',''),('quantangshi-41564','春夕言怀','張泌','quantangshi','','卷42','风透疎帘月满庭，倚栏无事倍伤情。
烟垂柳带纤腰软，露滴花房怨脸明。
愁逐野云销不尽，情随春浪去难平。
幽窗谩结相思梦，欲化西园蝶未成。','',''),('quantangshi-41565','春江雨','張泌','quantangshi','','卷42','雨溟溟，风泠泠，老松瘦竹临烟汀。
空江冷落野云重，村中鬼火微如星。
夜惊溪上渔人起，滴沥篷声满愁耳。
子规叫断独未眠，罨岸春涛打船尾。','',''),('quantangshi-41566','送容州中丞赴镇','張泌','quantangshi','','卷42','交趾同星坐，龙泉佩斗文。
烧香翠羽帐，看舞郁金裙。
鷁首冲泷浪，犀渠拂岭云。
莫教铜柱北，祗说马将军。','',''),('quantangshi-41567','赠韩道士','張泌','quantangshi','','卷42','日暮秋风吹野花，上清归客意无涯。
桃源寂寂烟霞闭，天路悠悠星汉斜。
还似世人生白发，定知仙骨变黄芽。
东城南陌频相见，应是壶中别有家。','',''),('quantangshi-41568','甘露寺','孫魴','quantangshi','','卷42','寒暄皆有景，孤绝画难形。
地拱千寻嶮，天垂四面青。
昼灯笼雁塔，夜磬彻渔汀。
最爱僧房好，波光满户庭。','',''),('quantangshi-41569','题金山寺','孫魴','quantangshi','','卷42','万古波心寺，金山名目新。
天多剩得月，地少不生尘。
过樐妨僧定，惊涛溅佛身。
谁言张处士，题后更无人。','',''),('quantangshi-41570','杨柳枝词五首 一','孫魴','quantangshi','','卷42','灵和风暖太昌春，舞线摇丝向昔人。
何似晓来江雨后，一行如画隔遥津。','',''),('quantangshi-41571','杨柳枝词五首 二','孫魴','quantangshi','','卷42','彭泽初栽五树时，只应闲看一枝垂。
不知天意风流处，要与佳人学画眉。','',''),('quantangshi-41572','杨柳枝词五首 三','孫魴','quantangshi','','卷42','暖傍离亭静拂桥，入流穿槛绿阴摇。
不知落日谁相送，魂断千条与万条。','',''),('quantangshi-41573','杨柳枝词五首 四','孫魴','quantangshi','','卷42','春来绿树遍天涯，未见垂杨未可夸。
晴日万株烟一阵，闲坊兼是莫愁家。','',''),('quantangshi-41574','杨柳枝词五首 五','孫魴','quantangshi','','卷42','十首当年有旧词，唱青歌翠几无遗。
未曾得向行人道，不谓离情莫折伊。','',''),('quantangshi-41575','句','孫魴','quantangshi','','卷42','游子未归去，野花愁破心。
划多灰渐冷，坐久席成痕。
结宇孤峰上，安禅巨浪间。
分开朝海浪，留住过江云。
划多灰杂苍虬迹，坐久烟消宝鸭香。','',''),('quantangshi-41576','入塞二首 一','沈彬','quantangshi','','卷42','欲为皇王服远戎，万人金甲鼓鼙中。
阵云黯塞三边黑，兵血愁天一片红。
半夜翻营旗搅月，深秋防戍劒磨风。
谤书未及明君爇，卧骨将军已殁功。','',''),('quantangshi-41577','入塞二首 二','沈彬','quantangshi','','卷42','苦战沙门卧箭痕，戍楼闲上望星文。
生希国泽分偏将，死夺河源答圣君。
鸢覰败兵眠白草，马惊边鬼哭阴云。
功多地远无人纪，汉阁笙歌日又曛。','',''),('quantangshi-41578','塞下三首 一','沈彬','quantangshi','','卷42','塞叶声悲秋欲霜，寒山数点下牛羊。
映霞旅雁随疎雨，向碛行人带夕阳。
边骑不来沙路失，国恩深后海城荒。
胡儿向化新成长，犹自千回问汉王。','',''),('quantangshi-41579','塞下三首 二','沈彬','quantangshi','','卷42','贵主和亲杀气沉，燕山闲猎鼓鼙音。
旗分雪草偷边马，箭入寒云落塞禽。
陇月尽牵乡思动，战衣谁寄泪痕深。
金钗谩作封侯别，劈破佳人万里心。','',''),('quantangshi-41580','塞下三首 三','沈彬','quantangshi','','卷42','月冷榆关过雁行，将军寒笛老思乡。
贰师骨恨千夫壮，李广魂飞一劒长。
戍角就沙催落日，阴云分碛护飞霜。
谁知汉武轻中国，闲夺天山草木荒。','',''),('quantangshi-41581','秋日','沈彬','quantangshi','','卷42','秋含砧杵捣斜阳，笛引西风颢气凉。
薜荔惹烟笼蟋蟀，芰荷翻雨泼鸳鸯。
当年酒贱何妨醉，今日时难不易狂。
肠断旧游从一别，潘安惆怅满头霜。','',''),('quantangshi-41582','金陵杂题二首 一','沈彬','quantangshi','','卷42','王气生秦四百年，晋元东渡浪花船。
正慙海内皆涂地，来保江南一片天。
古树着行临远岸，暮山相亚出微烟。
千征万战英雄尽，落日牛羊食野田。','',''),('quantangshi-41583','金陵杂题二首 二','沈彬','quantangshi','','卷42','暮潮声落草光沉，贾客来帆宿岸阴。
一笛月明何处酒，满城秋色几家砧。
时清曾恶桓温盛，山翠长牵谢傅心。
今日到来何物在，碧烟和雨锁寒林。','',''),('quantangshi-41584','麻姑山','沈彬','quantangshi','','卷42','绀殿松萝太古山，仙人曾此话桑田。
闲倾云液十分日，已过浮生一万年。
花洞路中逢鹤信，水帘岩底见龙眠。
我来游礼酬心愿，欲共怡神契自然。','',''),('quantangshi-41585','题苏仙山','沈彬','quantangshi','','卷42','眼穿林罅见郴州，井里交连侧局揪。
味道不来闲处坐，劳生更欲几时休。
苏仙宅古烟霞老，义帝坟荒草木愁。
千古是非无处问，夕阳西去水东流。','',''),('quantangshi-41586','洪州解至长安初举纳省卷梦仙谣','沈彬','quantangshi','','卷42','□□□□□□□，□□□□□□□。
玉殿大开从客入，金桃烂熟没人偷。
凤惊宝扇频翻翅，龙惧金鞭不转头。
□□□□□□□，□□□□□□□。','',''),('quantangshi-41587','忆仙谣','沈彬','quantangshi','','卷42','白榆风飒九天秋，王母朝回宴玉楼。
日月渐长双凤睡，桑田欲变六鳌愁。
云翻箫管相随去，星触旌幢各自流。
诗酒近来狂不得，骑龙却忆上清游。','',''),('quantangshi-41588','纳省卷赠为首刘象','沈彬','quantangshi','','卷42','曾应大中天子举，四朝风月鬓萧疎。
不随世祖重携劒，却为文皇再读书。
十载战尘销旧业，满城春雨坏贫居。
一枝何事于君借，仙桂年年幸有余。','',''),('quantangshi-41589','赠王定保','沈彬','quantangshi','','卷42','仙桂曾攀第一枝，薄游湘水阻佳期。
皋桥已失齐眉愿，萧寺行逢落发师。
废苑露寒兰寂寞，丹山云断凤参差。
闻公已有平生约，谢绝女萝依兔丝。','',''),('quantangshi-41590','结客少年场行','沈彬','quantangshi','','卷42','重义轻生一劒知，白虹贯日报雠归。
片心惆怅清平世，酒市无人问布衣。','',''),('quantangshi-41591','阳朔碧莲峰','沈彬','quantangshi','','卷42','陶潜彭泽五株柳，潘岳河阳一县花。
两处争如阳朔好，碧莲峰里住人家。','',''),('quantangshi-41592','再过金陵','沈彬','quantangshi','','卷42','玉树歌终王气收，雁行高送石城秋。
江山不管兴亡事，一任斜阳伴客愁。','',''),('quantangshi-41593','都门送别','沈彬','quantangshi','','卷42','岸柳萧疎野荻秋，都门行客莫回头。
一条灞水清如劒，不为离人割断愁。','',''),('quantangshi-41594','吊边人','沈彬','quantangshi','','卷42','杀声沈后野风悲，汉月高时望不归。
白骨已枯沙上草，家人犹自寄寒衣。','',''),('quantangshi-41595','句','沈彬','quantangshi','','卷42','尺素隐清辉，一毫分险阻。
金翅动身摩日月，银河转浪洗干坤。
须知手笔安排定，不怕山河整顿难。
九衢冠盖暗争路，四海干戈多异心。
地隈一水巡城转，天约羣山附郭来。
数家鱼网疎云外，一岸残阳细雨中。
松欹晚影离坛草，钟撼秋声入殿风。
压低吴楚遥涵水，约破云霞独倚天。
半身落日离秦树，一路平芜入楚烟。
清占月中三峡水，丽偷云外十洲春。
幽鸟唤人穿竹去，野猨寻果出云来。','',''),('quantangshi-41596','僻居谢何明府见访','伍喬','quantangshi','','卷42','公退琴堂动逸怀，闲披烟霭访微才。
马嘶穷巷蛙声息，辙到衡门草色开。
风引柳花当坐起，日将林影入庭来。
满斋尘土一牀藓，多谢从容水饭回。','',''),('quantangshi-41597','冬日道中','伍喬','quantangshi','','卷42','去去天涯无定期，瘦童羸马共依依。
暮烟江口客来绝，寒叶岭头人住稀。
带雪野风吹旅思，入云山火照行衣。
钓台吟阁沧洲在，应为初心未得归。','',''),('quantangshi-41598','僻居酬友人','伍喬','quantangshi','','卷42','僻居虽爱近林泉，幽径闲居碧藓连。
向竹掩扉随鹤息，就溪安石学僧禅。
古琴带月音声亮，山果经霜气味全。
多谢故交怜朴野，隔云时复寄佳篇。','',''),('quantangshi-41599','游西山龙泉禅寺','伍喬','quantangshi','','卷42','叠巘层峰坐可观，枕门流水更潺湲。
晓钟声彻洞溪远，夏木影笼轩槛寒。
幽径乍寻衣屦润，古堂频宿梦魂安。
因嗟城郭营营事，不得长游空鬓残。','',''),('quantangshi-41600','宿灊山','伍喬','quantangshi','','卷42','一入仙山万虑宽，夜深宁厌倚虚栏。
鹤和云影宿高木，人带月光登古坛。
芝术露浓溪坞白，薜萝风起殿廊寒。
更陪羽客论真理，不觉初钟叩晓残。','',''),('quantangshi-41601','游西禅','伍喬','quantangshi','','卷42','远岫当轩列翠光，高僧一衲万缘忘。
碧松影里地长润，白藕花中水亦香。
云自雨前生净石，鹤于钟后宿长廊。
游人恋此吟终日，盛暑楼台早有凉。','',''),('quantangshi-41602','寄史处士','伍喬','quantangshi','','卷42','长羡闲居一水湄，吟情高古有谁知。
石楼待月横琴久，渔浦经风下钓迟。
僻坞落花多掩径，旧山残烧几侵篱。
松门别后无消息，早晚重应蹑屐随。','',''),('quantangshi-41603','僻居秋思寄友人','伍喬','quantangshi','','卷42','门巷秋归更寂寥，雨余闲砌委兰苗。
梦回月夜虫吟壁，病起茅斋药满瓢。
泽国旧游关远思，竹林前会负佳招。
身名未立犹辛苦，何许流年晚鬓凋。','',''),('quantangshi-41604','寄落星史虚白处士','伍喬','quantangshi','','卷42','白云峰下古溪头，曾与提壶烂熳游。
登阁共看彭蠡水，围炉相忆杜陵秋。
棊玄不厌通高品，句妙多容隔岁酬。
别后相思时一望，暮山空碧水空流。','',''),('quantangshi-41605','九江旅夜寄山中故人','伍喬','quantangshi','','卷42','弱柳风高远漏沈，坐来难便息愁吟。
江城雪尽寒犹在，客舍灯孤夜正深。
尘土积年粘旅服，关山无处寄归心。
此时遥羡闲眠侣，静掩云扉卧一林。','',''),('quantangshi-41606','闻杜牧赴阙','伍喬','quantangshi','','卷42','旧隐匡庐一草堂，今闻携策谒吾皇。
峡云难卷从龙势，古劒终腾出土光。
开翅定期归碧落，濯缨宁肯问沧浪。
他时得意交知仰，莫忘裁诗寄钓乡。','',''),('quantangshi-41607','题西林寺水阁','伍喬','quantangshi','','卷42','竹翠苔花遶槛浓，此亭幽致讵曾逢。
水分林下清泠派，山峙云间峭峻峰。
怪石夜光寒射烛，老杉秋韵冷和钟。
不知来往留题客，谁约重寻莲社踪。','',''),('quantangshi-41608','林居喜崔三博远至','伍喬','quantangshi','','卷42','几日区区在远程，晚烟林径喜相迎。
姿容虽有尘中色，巾屦犹多岳上清。
野石静排为坐榻，溪茶深煮当飞觥。
留连话与方经宿，又欲携书别我行。','',''),('quantangshi-41609','观华夷图','伍喬','quantangshi','','卷42','别手应难及此精，须知攒簇自心灵。
始于毫末分诸国，渐见图中列四溟。
关路欲伸通楚势，蜀山俄耸入秦青。
笔端尽现寰区事，堪把长悬在户庭。','',''),('quantangshi-41610','庐山书堂送祝秀才还乡','伍喬','quantangshi','','卷42','束书辞我下重巅，相送同临楚岸边。
归思几随千里水，离情空寄一枝蝉。
园林到日酒初熟，庭户开时月正圆。
莫使蹉跎恋疎野，男儿酬志在当年。','',''),('quantangshi-41611','暮冬送何秀才毗陵','伍喬','quantangshi','','卷42','匹马嘶风去思长，素琴孤劒称戎装。
路涂多是过残岁，杯酒无辞到醉乡。
云傍水村凝冷片，雪连山驿积寒光。
毗陵城下饶嘉景，回日新诗应满堂。','',''),('quantangshi-41612','龙潭张道者','伍喬','quantangshi','','卷42','碧洞幽岩独息心，时人何路得相寻。
养生不说凭诸药，适意惟闻在一琴。
石径扫稀山藓合，竹轩开晚野云深。
他年功就期飞去，应笑吾徒多苦吟。','',''),('quantangshi-41613','晚秋同何秀才溪上','伍喬','quantangshi','','卷42','闲步秋光思杳然，荷藜因共过林烟。
期收野药寻幽路，欲采溪菱上小船。
云吐晚阴藏霁岫，柳含余霭咽残蝉。
倒尊尽日忘归处，山磬数声敲暝天。','',''),('quantangshi-41614','送江少府授延陵后寄','伍喬','quantangshi','','卷42','五老云中勤学者，遇时能不困风尘。
束书西上谒明主，捧檄南归慰老亲。
别馆友朋留醉久，去程烟月入吟新。
莫因官小慵之任，自古鸾栖有异人。','',''),('quantangshi-41615','观山水障子','伍喬','quantangshi','','卷42','功绩精妍世少伦，图时应倍用心神。
不知草木承何异，但见江山长带春。
云势似离岩底石，浪花如动岸边苹。
更疑独泛渔舟者，便是其中旧隐人。','',''),('quantangshi-41616','寄张学士洎','伍喬','quantangshi','','卷42','不知何处好消忧，公退携壶即上楼。
职事久参侯伯幕，梦魂长遶帝王州。
黄山向晚盈轩翠，黟水含春绕槛流。
遥想玉堂多暇日，花时谁伴出城游。','',''),('quantangshi-41617','句','伍喬','quantangshi','','卷42','积霭沈诸壑，微阳在半峰。','',''),('quantangshi-41618','塞下曲 一','陳陶','quantangshi','','卷42','边头能走马，猨臂李将军。
射虎羣胡伏，开弓绝塞闻。
海山谙向背，攻守别风云。
只为坑降罪，轻车未转勋。','',''),('quantangshi-41619','塞下曲 二','陳陶','quantangshi','','卷42','望湖关下战，杂虏丧全师。
鸟啄豺狼将，沙埋日月旗。
牛羊奔赤狄，部落散燕耆。
都护凌晨出，铭功瘗死尸。','',''),('quantangshi-41620','胡无人行','陳陶','quantangshi','','卷42','十万羽林儿，临洮破郅支。
杀添胡地骨，降足汉营旗。
塞阔牛羊散，兵休帐幕移。
空流陇头水，呜咽向人悲。','',''),('quantangshi-41621','悲哉行','陳陶','quantangshi','','卷42','中岳仇先生，遗余饵松方。
服之一千日，肢体生异香。
步履如风旋，天涯不赍粮。
仍云为地仙，不得朝虚皇。
狡兔有三穴，人生又何常。
悲哉二廉士，饿死于首阳。','',''),('quantangshi-41622','涂山怀古','陳陶','quantangshi','','卷42','落拓书剑晚，清秋鹰正笼。
涂山间来上，敬爱如登龙。
览古觉神王，翛然天地空。
东南更何有，一醉先王风。
惟昔放勋世，阴晦彻成洪。
皇图化鱼鳖，天道漂无踪。
帝乃命舟檝，掇芳儒素中。
高陈九州力，百道驱归东。
旧物复光明，洪炉再埏镕。
经门不私子，足知天下公。
亮曰那并生，唐虞禅华虫。
兹山朝万国，一赋寰海同。
十载有区宇，秋豪皆帝功。
垂衣不骄德，子桀如何聋。
握发闻礼贤，葺茅见卑宫。
凡夫色难事，神圣安能恭。
道隐三千年，遗芳播笙镛。
当时执圭处，佳气仍童童。
海屿俨清庙，天人盛只供。
玄恩及花木，丹谶名崆峒。
异代草泽臣，何由树勋庸。
尧阶未曾识，谁信平生忠。
恨不当际会，预为执鞭僮。
劳歌下山去，怀德心无穷。','',''),('quantangshi-41623','游子吟','陳陶','quantangshi','','卷42','栖乌喜林曙，惊蓬伤岁阑。
关河三尺雪，何处是天山？
朔风无重衣，仆马饥且寒。
惨戚别妻子，迟回出门难。
男儿值休明，岂是长泥蟠。
何者为木偶，何人侍金銮。
郁郁守贫贱，悠悠亦无端。
进不图功名，退不处岩峦。
穷通在何日，光景如跳丸。
富贵苦不早，令人摧心肝。
誓期春之阳，一振摩霄翰。','',''),('quantangshi-41624','怀仙吟二首 一','陳陶','quantangshi','','卷42','丹陵五牙客，昨日罗浮归。
赤斧寻不得，烟霞空满衣。
试于华阳问，果遇三茅知。
采药向十洲，同行牧羊儿。
十洲隔八海，浩渺不可期。
留空双白鹤，巢在长松枝。','',''),('quantangshi-41625','怀仙吟二首 二','陳陶','quantangshi','','卷42','云溪古流水，春晚桃花香。
忆与我师别，片帆归沧浪。
沧浪在何许，相思泪如雨。
黄鹤不复来，云深难别处。
石渠泉泠泠，三见菖蒲生。
日夜劳梦魂，随波注东溟。
空怀别时惠，长读消魔经。','',''),('quantangshi-41626','海昌望月','陳陶','quantangshi','','卷42','何处无今夕，岂期在海头。
贾客不爱月，婵娟闲沧洲。
浩然伤岁华，独望湖边楼。
烟岛青历历，蓝田白悠悠。
谁无破镜期，繄我信虚舟。
谁无桂枝念，繄我方摧輈。
始见弯环春，又逢团圆秋。
莫厌绫扇夕，百年多银钩。
今盘谁雕镌，玉窟难冥搜。
重轮运时节，三五不自由。
疑抛云上锅，欲搂天边球。
孀居应寒冷，捣药青冥愁。
兔子树下蹲，虾𢋙池中游。
如何名金波，不共水东流。
天花辟膻腥，野云无边陬。
蚌蛤乘大运，含珠相对醻。
夜鹊思南乡，露华清东瓯。
百宝安可覰，老龙锁深湫。
究究如情人，盗者即仇雠。
海涯上皎洁，九门更清幽。
亭亭劝金尊，夜久喘吴牛。
夷俗皆轻掷，北山思今游。
雁声故乡来，客泪堕南洲。
平生烟霞志，读书觅封侯。
四海尚白身，岂无故乡羞。
壈坎何足叹，壮如水中虬。
猎猎谷底兰，摇摇波上鸥。
中途丧资斧，两地生繁忧。
一杯太阴君，鹪鹩岂无求。
明日将片叶，三山东南浮。','',''),('quantangshi-41627','蒲门戍观海作','陳陶','quantangshi','','卷42','廓落溟涨晓，蒲门郁苍苍。
登楼礼东君，旭日生扶桑。
毫厘见蓬瀛，含吐金银光。
草木露未曦，蜃楼气若藏。
欲游蟠桃国，虑涉魑魅乡。
徐市惑秦朝，何人在岩廊。
惜哉千童子，葬骨于眇茫。
恭闻槎客言，东池接天潢。
即此聘牛女，曰祈长寿方。
灵津水清浅，余亦慕修航。','',''),('quantangshi-41628','番禺道中作','陳陶','quantangshi','','卷42','博罗程远近，海塞愁先入。
瘴雨出虹蝀，蛮江渡山急。
常闻岛夷俗，犀象满城邑。
雁至草犹春，潮回樯半湿。
丹丘凤皇隐，水庙蛟龙集。
何处树能言，几乡珠是泣。
千年赵佗国，霸气委原隰。
龌龊笑终军，长缨祸先及。','',''),('quantangshi-41629','赠江西周大夫','陳陶','quantangshi','','卷42','否极生大贤，九元降灵气。
独立正始风，蔚然中兴瑞。
渊伦照三古，磊落涵泾渭。
真貌月悬秋，雄词雷出地。
具瞻先皇宠，欲践东华贵。
咫尺时不来，千秋鼎湖泪。
因分三辅职，进领南平位。
报政黄霸慙，提兵吕蒙醉。
岁星临斗牛，水国嘉祥至。
不独苍生苏，仍兼六驺喜。
恭闻庙堂畧，欲断匈奴臂。
刬释自宸衷，平戍在连帅。
时康簪笏宂，世梗忠良议。
丘壑非无人，松香有私志。
三朝倚天剑，十万浮云骑。
可使河曲清，羣公信儿戏。
沧溟用谦德，百谷走童稚。
御众付深人，参筹须伟器。
他年蓬荜贱，愿附鵷鸾翅。','',''),('quantangshi-41630','旅次铜山途中先寄温州韩使君','陳陶','quantangshi','','卷42','乱山沧海曲，中有横阳道。
束马过铜梁，苕华坐堪老。
鸠鸣高崖裂，熊鬬深树倒。
绝壑无坤维，重林失苍昊。
跻攀寡俦侣，扶接念舆皂。
俛仰栗嵌空，无因掇灵草。
梯穷闻戍鼓，魂续赖丘祷。
敞豁天地归，萦纡村落好。
悠悠思蒋径，扰扰愧商皓。
驰想永嘉侯，应伤此怀抱。','',''),('quantangshi-41631','种兰','陳陶','quantangshi','','卷42','种兰幽谷底，四远闻馨香。
春风长养深，枝叶趁人长。
智水润其根，仁锄护其芳。
蒿藜不生地，恶鸟弓已藏。
椒桂夹四隅，茅茨居中央。
左邻桃花坞，右接莲子塘。
一月薰手足，两月薰衣裳。
三月薰肌骨，四月薰心肠。
幽人饥如何，采兰充糇粮。
幽人渴如何，酝兰为酒浆。
地无青苗租，白日如散王。
不尝仙人药，端坐红霞房。
日夕望美人，佩花正煌煌。
美人久不来，佩花徒生光。
刈获及葳蕤，无令见雪霜。
清芬信神鬼，一叶岂可忘。
举头愧青天，鼓腹咏时康。
下有贤公卿，上有圣明王。
无阶答风雨，愿献兰一筐。','',''),('quantangshi-41632','草木言','陳陶','quantangshi','','卷42','何生我苍苍，何育我黄黄。
草木无知识，幸君同三光。
始自受姓名，葳蕤立衣裳。
山河既分丽，齐首乳青阳。
甘辛各有荣，好丑不相防。
常忧刀斧劫，窃慕仁寿乡。
愿天雨无暴，怨地风无狂。
雨足因衰惫，风多因夭伤。
在山不为桂，徒辱君高冈。
在水不为莲，徒占君深塘。
勿轻培塿阜，或有奇栋梁。
勿轻蒙胧泽，或有奇馨香。
涓毫可蔍差，朝菌寿为长。
拥肿若无取，大椿命为伤。
婆娑不材生，苒苒向秋荒。
幸遭薰风日，有得皆簸扬。
所愧雨露恩，愿效幽微芳。
希君频采择，勿使枯雪霜。','',''),('quantangshi-41633','题僧院紫竹','陳陶','quantangshi','','卷42','喜游蛟井寺，复见炎州竹。
杳霭万丈间，啸风清独速。
江南正霜霰，吐秀弄颛顼。
似瑞惊坚贞，如魔试金粟。
笋非孝子泣，文异湘灵哭。
金碧谁与邻，萧森自成族。
新闻赤帝种，子落毛人谷。
远祖赐鹪鹏，遗芳遍南陆。
对烟苏麻丑，夹涧篔簹伏。
美誉动丹青，瓌姿艳秦蜀。
因缘鹿苑识，想像虵丘斸。
几叶别黄茅，何年依白足。
龙树蛰一花，砌瑶扫云屋。
色静曼仙花，名高给孤独。
青葱太子树，洒落观音目。
法雨每霑濡，玉毫时照烛。
离居鸾节变，住冷金颜缩。
岂念葛陂荣，幸无祖父辱。
光摇水精串，影送莲花轴。
江鹜日相寻，野鹗时寄宿。
幽香入茶竈，静翠直碁局。
肯羡垣上蒿，自多篱下菊。
从来道生一，况伴龟藏六。
栖托讵星回，檀栾已云矗。
霞杯传缥叶，羽管吹紫玉。
久绝钓竿歌，聊裁竹枝曲。
愧生黄金地，千秋为师绿。','',''),('quantangshi-41634','早发始兴','陳陶','quantangshi','','卷42','云里山已曙，舟中火初爇。
绿浦待行桡，玄猨催落月。
沿流信多美，况复秋风发。
挂席借前期，晨鸡莫嘲异常。','',''),('quantangshi-41635','寄元孚道人','陳陶','quantangshi','','卷42','梵宇章句客，佩兰三十年。
长乘碧云马，时策翰林鞭。
曩事五岳游，金衣曳祥烟。
高攀桐君手，左倚鸑鷟肩。
哭玉秋雨中，摘星春风前。
横輈截洪偃，凭几见广宣。
尔来寤华胥，石壁孤云眠。
龙降始得偈，龟老方巢莲。
内殿无文僧，驱虞谁能牵。
因之问楚水，吊屈几潺湲。','',''),('quantangshi-41636','和西江李助副使早登开元寺阁','陳陶','quantangshi','','卷42','虚豁登宝阁，三休极层构。
独立天地间，烟云满襟袖。
鳌荒初落日，剑野呈绮绣。
秋槛祝融微，阴轩九江凑。
拂檐皇姑舍，错落白榆秀。
倚砌天竺祠，蛟龙蟠古甃。
翛然观六合，一指齐宇宙。
书剑忽若□，青云日方昼。
南朝空苍莽，楚泽稀耕耨。
万事溺颓波，一航安可涭。
徒云寄麟泣，六五终难就。
资斧念余生，湖光隐圭窦。
早闻羣黄鹤，飘举此江岫。
陵谷空霭然，人樵已雏𪆪。
燕宫豸冠客，凭览发清奏。
珠玉难嗣音，摐辕愧孤陋。','',''),('quantangshi-41637','将归钟陵留赠南海李尚书','陳陶','quantangshi','','卷42','楚国有田舍，炎州长梦归。
怀恩似秋燕，屡遶玉堂飞。
越酒岂不甘，海鱼宁无肥。
山裘醉歌舞，事与初心违。
晔晔文昌公，英灵世间稀。
长江浩无际，龙蜃皆归依。
贱子感一言，草茅发光辉。
从来鸡凫质，得假凤皇威。
常欲讨玄珠，青云报巍巍。
龙门竟多故，双泪别旍旗。','',''),('quantangshi-41638','宿岛径夷山舍','陳陶','quantangshi','','卷42','百里遵鸟径，蓬征信邅回。
暝依渔樵宿，似过黄金台。
缺啮心未理，寥寥夜猨哀。
山深石牀冷，海近腥气来。
主人意不浅，屡献流霞杯。
对月抚长剑，愁襟纷莫开。
九衢平如水，胡为涉崔崽。
一饭未遑饱，鹏图信悠哉。
山涛谑细君，吾岂厌蓬莱。
明发又驱马，客思一裴回。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-41639','避世翁','陳陶','quantangshi','','卷42','海上一蓑笠，终年垂钓丝。
沧洲有深意，冠尽何由知。
直钩不营鱼，蜗室无妻儿。
渴饮寒泉水，饥飡紫术芝。
鹤发披两肩，高怀如澄陂。
曾闻仙老言，云是古鸱夷。
石窦閟雷雨，金潭养蛟螭。
乘槎上玉津，骑鹿游峨嵋。
以人为语默，与世为雄雌。
兹焉乃磻溪，豹变应须时。
自古隐沦客，无非王者师。','',''),('quantangshi-41640','冬夜吟','陳陶','quantangshi','','卷42','黑夜天寒愁散玉，东皇海上张仙烛。
侯家歌舞按梨园，石氏宾寮醉金谷。
鲁家襜褕暗披水，雪花灯下甘垂翅。
散帙高编折桂枝，披纱密甃青云地。
霜白溪松转斜尽，铜龙唤曙咽声细。
八埏蝼蚁厌寒栖，早晚青旗引春帝。
展转城乌啼紫天，曈曚千骑衙楼前。','',''),('quantangshi-41641','西川座上听金五云唱歌','陳陶','quantangshi','','卷42','蜀王殿上华筵开，五云歌从天上来。
满堂罗绮悄无语，喉音止驻云裴回。
管弦金石还依转，不随歌出灵和殿。
白云飘颻席上闻，贯珠历历声中见。
旧样钗箆浅澹衣，元和梳洗青黛眉。
低丛小鬓腻䰀鬌，碧牙镂掌山参差。
曲终暂起更衣过，还向南行座头坐。
低眉欲语谢贵侯，檀脸双双泪穿破。
自言本是宫中嫔，武皇改号承恩新。
中丞御史不足比，水殿一声愁杀人。
武皇铸鼎登真箓，嫔御蒙恩免幽辱。
茂陵弓剑不得亲，嫁与卑官到西蜀。
卑官到官年未周，堂衡禄罢东西游。
蜀江水急驻不得，复此萍蓬二十秋。
今朝得侍王侯宴，不觉途中妾身贱。
愿持巵酒更唱歌，歌是伊州第三遍。
唱着右丞征戍词，更闻闺月添相思。
如今声韵尚如在，何况宫中年少时。
五云处处可怜许，明朝道向襃中去。
须臾宴罢各东西，雨散云飞莫知处。','',''),('quantangshi-41642','飞龙引','陳陶','quantangshi','','卷42','有熊之君好神仙，飡霞炼石三千年。
一旦黄龙下九天，骑龙枿枿升紫烟。
万姓攀髯髯堕地，啼呼弓剑飘寒水。
紫鸾八九堕玉笙，金镜空留照魑魅。
羽幢䙰褷银汉秋，六宫望断芙蓉愁。
应龙下挥中园笑，泓泓水遶青苔洲。
瑞风飒遝天光浅，瑶阙峨峨横露苑。
沆瀣楼头紫凤歌，三株树下青牛饭。
鸿胧九阙相玉皇，钧天乐引金华郎。
散花童子鹤衣短，投壶姹女蛾眉长。
彤庭侍宴瑶池席，老兔春高桂宫白。
蓬莱下国赐分圭，阿母金桃容小摘。
仙流万缄虫篆春，三十六洞交风云。
千年小兆一蝉蜕，丹台职亚扶桑君。
金乌试浴青门水，下界蜉蝣几回死。','',''),('quantangshi-41643','谪仙词','陳陶','quantangshi','','卷42','牧龙丈人病高秋，羣童击节星汉愁。
瑶台凤辇不胜恨，太古一声龙白头。
玉气兰光久摧折，上清鸡犬音书绝。
霓旌失手远于天，三岛空云对秋月。
人间磊磊浮沤客，鸑鷟蜻蜓飞自隔。
不应冠盖逐黄埃，长梦真君旧恩泽。','',''),('quantangshi-41644','步虚引','陳陶','quantangshi','','卷42','小隐山人十洲客，莓苔为衣双耳白。
青编为我忽降书，暮雨虹霓一千尺。
赤城门闭六丁直，晓日已烧东海色。
朝天半夜闻玉鸡，星斗离离碍龙翼。','',''),('quantangshi-41645','独摇手','陳陶','quantangshi','','卷42','汉宫新燕矜蛾眉，春台艳妆莲一枝。
迎春侍宴瑶华池，游龙七盘娇欲飞。
冶袖莺鸾拂朝曦，摩烟褭雪金碧遗。
愁鸿连翾蚕曳丝，飒遝明珠掌中移。
仙人龙凤云雨吹，朝哀暮愁引哑吚。
鸳鸯翡翠承宴私，南山一笑君无辞。
仙蛾泣月清露垂，六宫烧烛愁风欷。','',''),('quantangshi-41646','空城雀','陳陶','quantangshi','','卷42','古城蒙蒙花覆水，昔日住人今住鬼。
野雀荒台遗子孙，千年饮啄枯桑根。
不随海燕栢梁去，应无玉环衔报恩。
近村红栗香压枝，嗷嗷黄口诉朝饥。
生来未见凤皇语，欲飞常怕蜘蛛丝。
断肠四隅天四绝，清泉绿蒿无恐疑。','',''),('quantangshi-41647','鸡鸣曲','陳陶','quantangshi','','卷42','鸡声春晓上林中，一声惊落虾蟆宫。
二声唤破枕边梦，三声行人烟海红。
平旦慵将百雏语，蓬松锦绣当阳处。
愧君饮食长相呼，为君昼鸣下高树。','',''),('quantangshi-41648','小笛弄','陳陶','quantangshi','','卷42','一尺玲珑握中翠，仙娥月浦呼龙子。
五夜流珠粲梦卿，九青鸾倚洪崖醉。
丹穴饥儿笑风雨，娲皇碧玉星星语。
蛇蝎愁闻骨髓寒，江山恨老眠秋雾。
绮席鸳鸯冷朱翠，星流露泫谁驱使。
江南一曲罢伶伦，芙蓉水殿春风起。','',''),('quantangshi-41649','将进酒','陳陶','quantangshi','','卷42','金尊莫倚青春健，龌龊浮生如走电。
琴瑟盘倾从世珠，黄泥局泻流年箭。
麻姑爪秃瞳子昏，东皇肉角生鱼鳞。
灵鳌柱骨半枯朽，骊龙德悔愁耕人。
周孔蓍龟久沦没，黄蒿谁认贤愚骨。
兔苑词才去不还，兰亭水石空明月。
姮娥弄箫香雨收，江滨迸瑟鱼龙愁。
灵芝九折楚莲醉，翾风一叹梁庭秋。
醁亚蛮觥奉君寿，玉山三献春红透。
银鸭金鹅言待谁，隋家岳渎皇家有。
珊瑚座上凌香云，凤𦢙龙炙猩猩唇。
芝兰此日不倾倒，南山白石皆贤人。
文康调笑麒麟起，一曲飞龙寿天地。','',''),('quantangshi-41650','钱塘对酒曲','陳陶','quantangshi','','卷42','风天雁悲西陵愁，使君红旗弄涛头。
东海神鱼骑未得，江天大笑闲悠悠。
嵯峨吴山莫夸碧，河阳经年一宵白。
南州彩凤为君生，古狱愁蛇待恩泽。
三清羽童来何迟，十二玉楼胡蝶飞。
炎荒翡翠九门去，辽东白鹤无归期。
鸱夷公子休悲悄，六鳌如镜天始老。
尊前事去月团圆，琥珀无情忆苏小。','',''),('quantangshi-41651','巫山高','陳陶','quantangshi','','卷42','玉峰青云十二枝，金母和云赐瑶姬。
花宫磊砢楚宫外，列仙八面星斗垂。
秀色无双怨三峡，春风几梦襄王猎。
青鸾不在嬾吹箫，斑竹题诗寄江妾。
飘颻丝散巴子天，苔裳玉辔红霞幡。
归时白帝掩青琐，琼枝草草遗湘烟。','',''),('quantangshi-41652','赠别离','陳陶','quantangshi','','卷42','碧玉飞天星坠地，玉剑分风交合水。
杨柳听歌莫向隅，鸡鸣一石留髠醉。
蹄轮送客沟水东，月娥挥手崦嵫峰。
蛮天列嶂俨相待，风官扫道迎游龙。
天姥翦霞铺晓空，漴漴大帝开明宫。
文鲸掉尾四海通，分明瀑布收灵桐。
山妖水魅骑旋风，魇梦啮魂黄瘴中。
借君郎鉴入崆峒，灵光草照闲花红。','',''),('quantangshi-41653','关山月','陳陶','quantangshi','','卷42','昔年嫖姚护羌月，今照嫖姚双鬓雪。
青冢曾无尺寸归，锦书多记穷荒骨。
百战金疮体沙碛，乡心一片悬秋碧。
汉城应期破镜时，胡尘万里婵娟隔。
度碛冲云朔风起，边笳欲晚生青珥。
陇上横吹霜色刀，何年断得匈奴臂。','',''),('quantangshi-41654','殿前生桂树','陳陶','quantangshi','','卷42','仙娥玉宫秋夜明，桂枝拂槛参差琼。
香风下天漏丁丁，牛渚翠梁横浅清羽帐不眠恨吹笙。
栖乌暗惊仙子落，步月鬃云堕金雀。
蕙楼凉簟翠波空，银缕香寒凤皇薄。
东海即为郎斟酌，绮疏长悬七星杓。','',''),('quantangshi-41655','古镜篇','陳陶','quantangshi','','卷42','紫皇玉镜蟾蜍字，堕地千年光不死。
发匣身沈古井寒，悬台日照愁成水。
海户山窗几梳绾，菱花开落何人见。
野老曾耕太白星，神狐夜哭秋天片。
下国青铜旋磨灭，回鸾万影成枯骨。
会待搏风雨泬寥，长恐莓苔蚀明月。','',''),('quantangshi-41656','自归山','陳陶','quantangshi','','卷42','海岳南归远，天门北望深。
暂为青琐客，难换白云心。
富贵老闲事，猨猱思旧林。
清平无乐志，尊酒有瑶琴。','',''),('quantangshi-41657','渡浙江','陳陶','quantangshi','','卷42','适越一轻艘，凌兢截鹭涛。
曙光金海近，晴雪玉峰高。
静寇思投笔，伤时欲钓鳌。
壮心殊未展，登涉漫劳劳。','',''),('quantangshi-41658','清源途中旅思','陳陶','quantangshi','','卷42','古木闽州道，驱羸落照间。
投村碍野水，问店隔荒山。
身事几时了，蓬飘何日闲。
看花滞南国，乡月十湾环。','',''),('quantangshi-41659','南海送韦七使君赴象州任','陳陶','quantangshi','','卷42','一鹗韦公子，新恩颁郡符。
岛夷通荔浦，龙节过苍梧。
地理金城近，天涯玉树孤。
圣朝朱绂贵，从此展雄图。','',''),('quantangshi-41660','送沈次鲁南游','陳陶','quantangshi','','卷42','高台赠君别，满握轩辕风。
落日一挥手，金鹅云雨空。
鳌洲石梁外，剑浦罗浮东。
兹兴不可接，翛翛烟际鸿。','',''),('quantangshi-41661','南海石门戍怀古','陳陶','quantangshi','','卷42','汉家征百越，落地丧貔貅。
大野朱旗没，长江赤血流。
鬼神寻覆族，宫庙变荒丘。
唯有朝台月，千年照戍楼。','',''),('quantangshi-41662','赋得池塘生春草','陳陶','quantangshi','','卷42','谢公遗咏处，池水夹通津。
古往人何在，年来草自春。
色宜波际绿，香异雨中新。
今日青青意，空悲行路人。','',''),('quantangshi-41663','题居上人法华新院','陳陶','quantangshi','','卷42','浮名深般若，方寺设莲华。
钟呗成僧国，湖山称法家。
一尘多宝塔，千佛大牛车。
能诱泥犂客，超然识聚沙。','',''),('quantangshi-41664','送秦炼师','陳陶','quantangshi','','卷42','紫府静沈沈，松轩思别吟。
水流宁有意，云泛本无心。
锦洞桃花远，青山竹叶深。
不因时卖药，何路更相寻。','',''),('quantangshi-41665','哭宝月三藏大禅师','陳陶','quantangshi','','卷42','五峰习圣罢，干竺化身归。
帝子传真印，门人哭宝衣。
一囊穷海没，三藏故园稀。
无复天花落，悲风满铁围。','',''),('quantangshi-41666','湓城赠别','陳陶','quantangshi','','卷42','楚岸青枫树，长随送远心。
九江春水阔，三峡暮云深。
气调桓伊笛，才华蔡琰琴。
迢迢嫁湘汉，谁不重黄金。','',''),('quantangshi-41667','赠别','陳陶','quantangshi','','卷42','海国一尺绮，冰壶万缕丝。
以君西攀桂，赠此金莲枝。
高鸟思茂林，穷鱼乐洿池。
平生握中宝，无使岁寒移。','',''),('quantangshi-41668','赠温州韩使君','陳陶','quantangshi','','卷42','康乐风流五百年，永嘉铃阁又登贤。
严城鼓动鱼惊海，华屋尊开月下天。
内使笔锋光案牍，鄢陵诗句满山川。
今来谁似韩家贵，越绝髦幢雁影连。','',''),('quantangshi-41669','闲居寄太学卢景博士','陳陶','quantangshi','','卷42','无路青冥夺锦袍，耻随黄雀住蓬蒿。
碧云梦后山风起，珠树诗成海月高。
久滞鼎书求羽翼，未忘龙阙致波涛。
闲来长得留侯癖，罗列樝梨校六韬。','',''),('quantangshi-41670','赠漳州张怡使君','陳陶','quantangshi','','卷42','旧德徐方天下闻，当年熊轼继清芬。
井田异政光蛮竹，符节深恩隔瘴云。
已见嘉祥生北户，尝嫌夷貊蠹南薰。
几时徴拜征西越，学着缦胡从使君。','',''),('quantangshi-41671','赠容南韦中丞','陳陶','quantangshi','','卷42','普宁都护军威重，九驿梯航压要津。
十二铜鱼尊画戟，三千犀甲拥朱轮。
风云已静西山寇，闾井全移上国春。
不独来苏发歌咏，天涯半是泣珠人。','',''),('quantangshi-41672','投赠福建路罗中丞','陳陶','quantangshi','','卷42','越艳听谣不厌听，楼船高卧静南溟。
未闻建水窥龙剑，应喜家山接女星。
三捷楷模光典策，一生封爵笑丹青。
皇恩几日西归去，玉树扶疎正满庭。','',''),('quantangshi-41673','赠江南李偕副使','陳陶','quantangshi','','卷42','世禄三朝压凤池，杜陵公子汉庭知。
雷封始贺堂溪剑，花府寻邀玉树枝。
几日坐谈诛叛逆，列城归美见歌诗。
从军莫厌千场醉，即是金銮宠命时。','',''),('quantangshi-41674','贺容府韦中丞大府贤兄新除黔南经略','陳陶','quantangshi','','卷42','蓬瀛簪笏旧联行，紫极差池降宠章。
列国山河分雁字，一门金玉尽龙骧。
耿家符节朝中美，袁氏芝兰阃外香。
烽戍悠悠限巴越，伫听歌咏两甘棠。','',''),('quantangshi-41675','和容南韦中丞题瑞亭白燕白鼠六眸龟嘉莲','陳陶','quantangshi','','卷42','伏波恩行动南夷，交趾喧传四瑞诗。
燕鼠孕灵褒上德，龟莲增耀答无私。
回翔雪侣窥檐处，照映红巢出水时。
尽写流传在轩槛，嘉祥从此百年知。','',''),('quantangshi-41676','题豫章西山香城寺','陳陶','quantangshi','','卷42','十地严宫礼竺皇，栴檀楼阁半天香。
只园树老梵声小，雪岭花香灯影长。
霄汉落泉供月界，蓬壶灵鸟侍云房。
何年七七金人降，金锡珠坛满上方。','',''),('quantangshi-41677','送江西周尚书赴滑台','陳陶','quantangshi','','卷42','楚谣襦袴整三千，喉舌新恩下九天。
天角雄都分节钺，蛟龙旧国罢楼船。
昆河已在兵钤内，棠树空留鹤岭前。
多病无因酬一顾，鄢陵千骑去翩翩。','',''),('quantangshi-41678','闽中送任畹端公还京','陳陶','quantangshi','','卷42','燕台下榻玉为人，月桂曾输次第春。
几日酬恩坐炎瘴，九秋高驾拂星辰。
汉庭凤进鵷行喜，隋国珠还水府贫。
多少嘉谟奏风俗，斗牛孤剑在平津。','',''),('quantangshi-41679','豫章江楼望西山有怀','陳陶','quantangshi','','卷42','水护星坛列太虚，烟霓十八上仙居。
时人未识辽东鹤，吾祖曾传宝鼎书。
终日章江催白鬓，何年丹竈见红蕖。
桃花谷口春深浅，欲访仙生赤鲤鱼。','',''),('quantangshi-41680','经徐穉墓','陳陶','quantangshi','','卷42','郏鄏妖兴炎汉衰，先生南国卧明夷。
凤皇屡降玄纁礼，琼石终藏烈火诗。
禁掖衣冠加宋鹊，湖山耕钓没尧时。
千年壠树何人哭，寂寞苍苔内史碑。','',''),('quantangshi-41681','钟陵道中作','陳陶','quantangshi','','卷42','原隰经霜蕙草黄，塞鸿消息怨流芳。
秋山落照见麋鹿，南国异花开雪霜。
烟火近通盘瓠俗，水云深入武陵乡。
曾逢啮缺话东海，长忆萧家青玉牀。','',''),('quantangshi-41682','旅泊涂江','陳陶','quantangshi','','卷42','烟雨南江一叶微，松潭渔父夜相依。
断沙雁起金精出，孤岭猨愁木客归。
楚国柑橙劳梦想，丹陵霞鹤间音徽。
无因得似沧溟叟，始忆离巢已倦飞。','',''),('quantangshi-41683','上建溪','陳陶','quantangshi','','卷42','崆垌一派泻苍烟，长揖丹丘逐水仙。
云树杳冥通上界，峰峦回合下闽川。
侵星愁过蛟龙国，采碧时逢婺女船。
已判猨催鬓先白，几重滩濑在秋天。','',''),('quantangshi-41684','冬日暮旅泊庐陵','陳陶','quantangshi','','卷42','螺亭倚棹哭飘蓬，白浪欺船自向东。
楚国蕙兰增怅望，番禺筐篚旅虚空。
江城雪落千家梦，汀渚冰生一夕风。
弃置侯鲭任羇束，不劳龟瓦问穷通。','',''),('quantangshi-41685','登宝历寺阁','陳陶','quantangshi','','卷42','金碧高层世界空，凭霓长啸八銮风。
横轩水壮蛟龙府，倚栋星开牛斗宫。
三楚故墟残景北，六朝荒苑断山东。
不堪怀古劳悲笑，安得鹏抟颢气中。','',''),('quantangshi-41686','寄兵部任畹郎中','陳陶','quantangshi','','卷42','常思剑浦越清尘，豆蔻花红十二春。
昆玉已成廊庙器，涧松犹是薜萝身。
虽同橘柚依南土，终愧魁罡近北辰。
好向昌时荐遗逸，莫教千古吊灵均。','',''),('quantangshi-41687','赠江南从事张侍郎','陳陶','quantangshi','','卷42','平南门馆凤皇毛，二十华轩立最高。
几处谈天致云雨，早时文海得鲸鳌。
姻联紫府萧窗贵，职称青钱绣服豪。
江徼无虞才不展，衔杯终日咏离骚。','',''),('quantangshi-41688','剑池','陳陶','quantangshi','','卷42','秦帝南巡厌火精，苍黄埋剑故丰城。
霸图缭戾金龙螫，坤道扶摇紫气生。
星斗卧来闲窟穴，雌雄飞去变澄泓。
永怀惆怅中宵作，不见春雷发匣声。','',''),('quantangshi-41689','洛城见贺自真飞升','陳陶','quantangshi','','卷42','子晋鸾飞古洛川，金桃再熟贺郎仙。
三清乐奏嵩丘下，五色云屯御苑前。
朱顶舞低迎绛节，青鬟歌对驻香軿。
谁能白昼相悲泣，太极光阴亿万年。','',''),('quantangshi-41690','谪仙吟赠赵道士','陳陶','quantangshi','','卷42','汗漫东游黄鹤雏，缙云仙子住清都。
三元麟凤推高座，六甲风雷閟小壶。
日月暗资灵寿药，山河拟作化生符。
若为失意居蓬岛，鳌足尘飞桑树枯。','',''),('quantangshi-41691','夜别温商梓州','陳陶','quantangshi','','卷42','凤皇城里花时别，玄武江边月下逢。
客舍莫辞先买酒，相门曾忝旧登龙。
迎风骚屑千家竹，隔水悠扬午夜钟。
明日又行西蜀去，不堪天际远山重。','',''),('quantangshi-41692','题赠高闲上人','陳陶','quantangshi','','卷42','檐卜花间客，轩辕席上珍。
笔江秋菡萏，僧国瑞麒麟。
内殿初招隐，曹溪得后尘。
龙蛇惊粉署，花雨对金轮。
白马方依汉，朱星又入秦。
剧谈凌凿齿，清论倒波旬。
拂石先天古，降龙旧国春。
珠还合浦老，龙去玉州贫。
鸳鹭输黄绢，场坛遶白萍。
