炼石医元气，屠鳌正昊苍。
扫原铺一德，驱祲立三光。
大道重苏息，真风再发扬。
芟夷逾旧迹，神圣掩前王。
郊酒酣寥廓，鸿恩受渺茫。
地图龟负出，天诰凤衔将。
杂贡来山峙，羣夷入雁行。
紫泥搜海岱，鸿笔富岩廊。
鹰象敷宸极，寰瀛作瑞坊。
泥丸封八表，金镜照中央。
构殿基麟趾，开藩表凤翔。
銮舆亲稼穑，朱幌务蚕桑。
戎羯输天马，灵仙侍玉房。
宫仪水搜甲，门卫绿沈枪。
陶铸超三古，车书混万方。
时巡望虞舜，搜狩法殷汤。
化合讴谣满，年丰鬼蜮藏。
政源归牧马，宫法付神羊。
宝鼎无灵应，金瓯肯破伤。
封山昭茂绩，祠执答嘉祥。
在昔宫闱僭，仍罹羿浞殃。
牝鸡何譈䜕，猘犬漫匡勷。
苗祷三灵怒，桓偷九族亡。
鲸鲵寻挂网，魑魅旋投荒。
松栢霜逾翠，芝兰露更香。
圣谟流祚远，仙系发源长。
岛屿征徭薄，漪澜泛稻凉。
凫鱼餍飡啖，荷薜足衣裳。
寤寐华胥国，嬉游太素乡。
鹰鹯飞接翼，忠孝住连墙。
有叟能调鼎，无媒隐钓璜。
干坤资识量，江海入文章。
野鹤思蓬阙，山麋忆庙堂。
泥沙空淬砺，星斗屡低昂。
历草何因见，衢尊岂暂忘。
终随嘉橘赋，霄汉谒羲皇。','',''),('quantangshi-41695','续古二十九首 一','陳陶','quantangshi','','卷42','大尧登宝位，麟凤焕宸居。
