离居渐觉笙歌懒，君逐嫖姚已十年。','',''),('quantangshi-41767','水调词十首 十','陳陶','quantangshi','','卷42','万里轮台音信稀，传闻移帐护金微。
会须麟阁留踪迹，不斩天骄莫议归。','',''),('quantangshi-41768','送谢山人归江夏','陳陶','quantangshi','','卷42','黄鹤春风二千里，山人佳期碧江水。
携琴一醉杨柳堤，日暮龙沙白云起。','',''),('quantangshi-41769','闲居杂兴五首 一','陳陶','quantangshi','','卷42','虞韶九奏音犹在，只是巴童自弃遗。
闲卧清秋忆师旷，好风摇动古松枝。','',''),('quantangshi-41770','闲居杂兴五首 二','陳陶','quantangshi','','卷42','一顾成周力有余，白云闲钓五溪鱼。
中原莫道无麟凤，自是皇家结网疎。','',''),('quantangshi-41771','闲居杂兴五首 三','陳陶','quantangshi','','卷42','长爱真人王子乔，五松山月伴吹箫。
从他浮世悲生死，独驾苍鳞入九霄。','',''),('quantangshi-41772','闲居杂兴五首 四','陳陶','quantangshi','','卷42','越里娃童锦作襦，艳歌声压郢中姝。
无人说向张京兆，一曲江南十斛珠。','',''),('quantangshi-41773','闲居杂兴五首 五','陳陶','quantangshi','','卷42','云堆西望贼连营，分阃何当举义兵。
莫道羔裘无壮节，古来成事尽书生。','',''),('quantangshi-41774','泉州刺桐花咏兼呈赵使君 一','陳陶','quantangshi','','卷42','仿髴三株植世间，风光满地赤城闲。
无因秉烛看奇树，长伴刘公醉玉山。','',''),('quantangshi-41775','泉州刺桐花咏兼呈赵使君 二','陳陶','quantangshi','','卷42','海曲春深满郡霞，越人多种刺桐花。
可怜虎竹西楼色，锦帐三千阿母家。','',''),('quantangshi-41776','泉州刺桐花咏兼呈赵使君 三','陳陶','quantangshi','','卷42','石氏金园无此艳，南都旧赋乏灵材。
只因赤帝宫中树，丹凤新衔出世来。','',''),('quantangshi-41777','泉州刺桐花咏兼呈赵使君 四','陳陶','quantangshi','','卷42','猗猗小艳夹通衢，晴日熏风笑越姝。
只是红芳移不得，刺桐屏幛满中都。','',''),('quantangshi-41778','泉州刺桐花咏兼呈赵使君 五','陳陶','quantangshi','','卷42','不胜攀折怅年华，红树南看见海涯。
故国春风归去尽，何人堪寄一枝花。','',''),('quantangshi-41779','泉州刺桐花咏兼呈赵使君 六','陳陶','quantangshi','','卷42','赤帝常闻海上游，三千幢盖拥炎州。
今来树似离宫色，红翠斜欹十二楼。','',''),('quantangshi-41780','投赠福建桂常侍二首 一','陳陶','quantangshi','','卷42','后来台席更何人，都护朝天拜近臣。
长笑当时汉卿士，等闲恩泽画麒麟。','',''),('quantangshi-41781','投赠福建桂常侍二首 二','陳陶','quantangshi','','卷42','匝地歌钟镇海隅，城池鞅掌旧名都。
不知珠履三千外，更许侯嬴寄食无。','',''),('quantangshi-41782','陇西行四首 一','陳陶','quantangshi','','卷42','汉主东封报太平，无人金阙议边兵。
纵饶夺得林胡塞，碛地桑麻种不生。','',''),('quantangshi-41783','陇西行四首 二','陳陶','quantangshi','','卷42','誓扫匈奴不顾身，五千貂锦丧胡尘。
可怜无定河边骨，犹是春闺梦里人。','',''),('quantangshi-41784','陇西行四首 三','陳陶','quantangshi','','卷42','陇戍三看塞草青，楼烦新替护羌兵。
同来死者伤离别，一夜孤魂哭旧营。','',''),('quantangshi-41785','陇西行四首 四','陳陶','quantangshi','','卷42','黠虏生擒未有涯，黑山营阵识龙蛇。
自从贵主和亲后，一半胡风似汉家。','',''),('quantangshi-41786','答莲花妓','陳陶','quantangshi','','卷42','近来诗思清于水，老去风情薄似云。
已向升天得门户，锦衾深愧卓文君。','',''),('quantangshi-41787','镜道中吹箫','陳陶','quantangshi','','卷42','金栏白的善篸𥰭，双凤夜伴江南栖。
十洲人听玉楼晓，空向千山桃杏枝。','',''),('quantangshi-41788','赠野老','陳陶','quantangshi','','卷42','何年种芝白云里，人传先生老莱子。
消磨世上名利心，澹若岩间一流水。','',''),('quantangshi-41789','酬元亨上人','陳陶','quantangshi','','卷42','一衲净居云梦合，秋来诗思祝融高。
何因知我津涯阔，远寄东溟六巨鳌。','',''),('quantangshi-41790','题徐穉湖亭','陳陶','quantangshi','','卷42','伏龙山横洲渚地，人如白苹自生死。
洪崖成道二千年，唯有徐君播青史。','',''),('quantangshi-41791','鄱阳秋夕','陳陶','quantangshi','','卷42','忆昔鄱阳旅游日，曾听南家争捣衣。
今夜重开旧砧杵，当时还见雁南飞。','',''),('quantangshi-41792','飞龙引','陳陶','quantangshi','','卷42','长洲茂苑朝夕池，映日含风结细漪。
坐当伏槛红莲披，雕轩洞户青苹吹。
轻幌芳烟郁金馥，绮檐花簟桃李枝。
苕苕翡翠但相逐，桂树鸳鸯恒并宿。','',''),('quantangshi-41793','句','陳陶','quantangshi','','卷42','蝉声将月短，草色与秋长。
比屋歌黄竹，何人撼白榆。
好看如镜夜，莫笑似弓时。
江湖水清浅，不足掉鲸尾。
饮水狼子瘦，思日鹧鸪寒。
一鼎雄雌金液火，十年寒暑鹿麑裘。
寄语东流任斑鬓，向隅终守铁梭飞。
干坤见了文章懒，龙虎成来印绶疎。
近来世上无徐庶，谁向桑麻识卧龙。','',''),('quantangshi-41794','春日作','李中','quantangshi','','卷42','和气来无象，物情还暗新。
干坤一夕雨，草木万方春。
染水烟光媚，催花鸟语频。
高台旷望处，歌咏属诗人。','',''),('quantangshi-41795','寒江暮泊寄左偃','李中','quantangshi','','卷42','维舟芦荻岸，离恨若为宽。
烟火人家远，汀洲暮雨寒。
天涯孤梦去，篷底一灯残。
不是凭骚雅，相思写亦难。','',''),('quantangshi-41796','喜春雨有寄','李中','quantangshi','','卷42','青春终日雨，公子莫思晴。
任阻西园会，且观南亩耕。
最怜滋壠麦，不恨湿林莺。
父老应相贺，丰年兆已成。','',''),('quantangshi-41797','魏夫人坛','李中','quantangshi','','卷42','仙坛遗迹在，苔合落花明。
绛节何年返，白云终日生。
旋新芳草色，依旧偃松声。
欲问希夷事，音尘隔上清。','',''),('quantangshi-41798','访洞神宫邵道者不遇','李中','quantangshi','','卷42','闲来仙观问希夷，云满星坛水满池。
羽客不知何处去，洞前花落立多时。','',''),('quantangshi-41799','寄赠致仕沈彬郎中','李中','quantangshi','','卷42','鹤氅换朝服，逍遥云水乡。
有时乘一叶，载酒入三湘。
尘梦年来息，诗魔老亦狂。
莼羮与鲈鲙，秋兴最宜长。','',''),('quantangshi-41800','赠别','李中','quantangshi','','卷42','行杯酌罢歌声歇，不觉前汀月又生。
自是离人魂易断，落花芳草本无情。','',''),('quantangshi-41801','送刘恭游庐山兼寄令上人','李中','quantangshi','','卷42','松桂烟霞蔽梵宫，诗流闲去访支公。
石堂磬断相逢夜，五老月生溪影空。','',''),('quantangshi-41802','宿庐山白云峰重道者院','李中','quantangshi','','卷42','绝顶松堂喜暂游，一宵玄论接浮丘。
云开碧落星河近，月出沧溟世界秋。
尘里年光何急急，梦中强弱自悠悠。
他时书劒酬恩了，愿逐鸾车看十洲。','',''),('quantangshi-41803','海上从事秋日书怀','李中','quantangshi','','卷42','悠悠旅宦役尘埃，旧业那堪信未回。
千里梦随残月断，一声蝉送早秋来。
壶倾浊酒终难醉，匣锁青萍久不开。
唯有搜吟遣怀抱，凉风时复上高台。','',''),('quantangshi-41804','访蔡文庆处士留题','李中','quantangshi','','卷42','幽人栖息处，一到涤尘心。
藓色花阴阔，棊声竹径深。
篱根眠野鹿，池面戏江禽。
多谢相留宿，开樽拂素琴。','',''),('quantangshi-41805','寄庐岳鉴上人','李中','quantangshi','','卷42','岳寺栖瓶锡，常人亲亦难。
病披青衲重，晚剃白髭寒。
烘壁茶烟暗，填沟木叶干。
昔年皆礼谒，频到碧云端。','',''),('quantangshi-41806','书小斋壁','李中','quantangshi','','卷42','其谁肯见寻，冷淡少知音。
尘土侵闲榻，烟波隔故林。
竹风醒晚醉，窗月伴秋吟。
道在唯求己，明时岂陆沈。','',''),('quantangshi-41807','怀王道者','李中','quantangshi','','卷42','闲思王道者，逸格世难羣。
何处眠青嶂，从来爱白云。
酒沽应独醉，药熟许谁分。
正作趋名计，如何得见君。','',''),('quantangshi-41808','桃花','李中','quantangshi','','卷42','祗应红杏是知音，灼灼偏宜间竹阴。
几树半开金谷晓，一溪齐绽武陵深。
艳舒百叶时皆重，子熟千年事莫寻。
谁步宋墙明月下，好香和影上衣襟。','',''),('quantangshi-41809','思旧游有感','李中','quantangshi','','卷42','长忆衔杯处，酕醄尚未阑。
江南正烟雨，楼上恰春寒。
好树藏莺密，平芜彻野宽。
如今无处觅，音信隔波澜。','',''),('quantangshi-41810','依韵和智谦上人送李相公赴昭武军','李中','quantangshi','','卷42','暂别庙堂上，雄藩去豁情。
秋风生雁渚，晚雾湿龙旌。
吟里过侯服，梦中归帝城。
下车军庶乐，千里月华清。','',''),('quantangshi-41811','姑苏怀古 一','李中','quantangshi','','卷42','阖闾兴霸日，繁盛复风流。
歌舞一场梦，烟波千古愁。
樵人归野径，渔笛起[扁]舟。
触目牵伤感，将行又驻留。','',''),('quantangshi-41812','姑苏怀古 二','李中','quantangshi','','卷42','苏台踪迹在，旷望向江滨。
往事谁堪问，连空草自春。
花疑西子脸，涛想伍胥神。
吟尽情难尽，斜阳照路尘。','',''),('quantangshi-41813','赠史虚白','李中','quantangshi','','卷42','致主嘉谋尚未伸，慨然深志与谁论。
唤回古意琴开匣，陶出真情酒满樽。
明月过溪吟钓艇，落花堆席睡僧轩。
九重梦卜时终在，莫向深云独闭门。','',''),('quantangshi-41814','赠蒯亮处士','李中','quantangshi','','卷42','着得新书义更幽，负琴何处不遨游。
玄宫寄宿月华冷，羽客伴吟松韵秋。
满户烟霞思紫阁，一帆风雨忆沧洲。
吾君侧席求贤切，未可悬瓢枕碧流。','',''),('quantangshi-41815','春夕偶作','李中','quantangshi','','卷42','早是春愁触目生，那堪春夕酒初醒。
贯珠声罢人归去，半落桃花月在庭。','',''),('quantangshi-41816','子规','李中','quantangshi','','卷42','暮春滴血一声声，花落年年不忍听。
带月莫啼江畔树，酒醒游子在离亭。','',''),('quantangshi-41817','书王秀才壁','李中','quantangshi','','卷42','茅舍何寥落，门庭长绿芜。
贫来卖书劒，病起忆江湖。
对枕暮山碧，伴吟凉月孤。
前贤多晚达，莫叹有霜须。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-41818','春日途中作','李中','quantangshi','','卷42','干禄趋名者，迢迢别故林。
春风短亭路，芳草异乡心。
雨过江山出，莺啼村落深。','',''),('quantangshi-41819','依韵和蠡泽王去微秀才见寄','李中','quantangshi','','卷42','咫尺风骚客，难谐面继酬。
相思对烟雨，一雁下汀洲。
花影谁家坞，笛声何处楼？
搘筇朗吟罢，搔首独迟留。','',''),('quantangshi-41820','送孙孔二秀才游庐山','李中','quantangshi','','卷42','庐山多胜景，偏称二君游。
松径苍苔合，花阴碧涧流。
倾壶同坐石，搜句共登楼。
莫学天台客，逢山即驻留。','',''),('quantangshi-41821','春日野望怀故人','李中','quantangshi','','卷42','野外登临望，苍苍烟景昏。
暖风医病草，甘雨洗荒村。
云散天边野，潮回岛上痕。
故人不可见，倚杖役吟魂。','',''),('quantangshi-41822','游玄真观','李中','quantangshi','','卷42','闲吟游古观，静虑想神仙。
上景非难度，阴功不易全。
醮坛松作盖，丹井藓成钱。
浩浩红尘里，谁来叩自然。','',''),('quantangshi-41823','劒客','李中','quantangshi','','卷42','恩酬期必报，岂是輙轻生。
神劒冲霄去，谁为平不平。','',''),('quantangshi-41824','鹤','李中','quantangshi','','卷42','警露精神异，冲天羽翼新。
千年一归日，谁识令威身。','',''),('quantangshi-41825','送致仕沈彬郎中游茅山','李中','quantangshi','','卷42','挂却朝冠披鹤氅，羽人相伴恣遨游。
忽因风月思茅岭，便挈琴樽上叶舟。
野寺宿时魂梦冷，海门吟处水云秋。
华阳洞府年光永，莫向仙乡拟驻留。','',''),('quantangshi-41826','题庐山东寺远大师影堂','李中','quantangshi','','卷42','远公遗迹在东林，往事名存动苦吟。
杉桧已依灵塔老，烟霞空锁影堂深。
入帘轻吹催香印，落石幽泉杂磬音。
十八贤人消息断，莲池千载月沈沈。','',''),('quantangshi-41827','庭苇','李中','quantangshi','','卷42','品格清于竹，诗家景最幽。
从栽向池沼，长似在汀洲。
玩好招溪叟，栖堪待野鸥。
影疎当夕照，花乱正深秋。
韵细堪清耳，根牢好系舟。
故溪高岸上，冷淡有谁游。','',''),('quantangshi-41828','寄左偃','李中','quantangshi','','卷42','每病风骚路，荒凉人莫游。
惟君还似我，成癖未能休。
舍寐缘孤月，忘形为九秋。
垂名如不朽，那恨雪生头。','',''),('quantangshi-41829','宿山店书怀寄东林令图上人','李中','quantangshi','','卷42','一宿山前店，旅情安可穷。
猨声乡梦后，月影竹窗中。
南楚征途阔，东吴旧业空。
虎溪莲社客，应笑此飘蓬。','',''),('quantangshi-41830','途中闻子规','李中','quantangshi','','卷42','春残杜宇愁，越客思悠悠。
雨歇孤村里，花飞远水头。
微风声渐咽，高树血应流。
因此频回首，家山隔几州。','',''),('quantangshi-41831','春日书怀','李中','quantangshi','','卷42','千峰雪尽鸟声春，日永孤吟野水滨。
霄汉路岐升未得，花时空拂满衣尘。','',''),('quantangshi-41832','所思代人','李中','quantangshi','','卷42','巫峡云深湘水遥，更无消息梦空劳。
梦回深夜不成寐，起立闲庭花月高。','',''),('quantangshi-41833','春晚过明氏闲居','李中','quantangshi','','卷42','寥寥陋巷独扃门，自乐清虚不厌贫。
数局棊中消永日，一罇酒里送残春。
雨催绿藓铺三径，风送飞花入四邻。
羡尔朗吟无外事，沧洲何必去垂纶。','',''),('quantangshi-41834','赠重安寂道者','李中','quantangshi','','卷42','寒松肌骨鹤心情，混俗陶陶隐姓名。
白发只闻悲短景，红尘谁解信长生。
壶中日月存心近，岛外烟霞入梦清。
每许相亲应计分，琴余常见话蓬瀛。','',''),('quantangshi-41835','江边吟','李中','quantangshi','','卷42','风暖汀洲吟兴生，远山如画雨新晴。
残阳影里水东注，芳草烟中人独行。
闪闪酒帘招醉客，深深绿树隐啼莺。
盘桓渔舍忘归去，云静高空月又明。','',''),('quantangshi-41836','献张义方常侍','李中','quantangshi','','卷42','雄飞看是逼嵓廊，逸思常闻不暂忘。
公署静眠思水石，古屏闲展看潇湘。
老来酒病虽然减，秋杪诗魔更是狂。
乘兴有时招羽客，横琴移月启茅堂。','',''),('quantangshi-41837','赠永真杜作翺少府','李中','quantangshi','','卷42','蓝袍竹简佐琴堂，县僻人稀觉日长。
爱静不嫌官况冷，苦吟从听鬓毛苍。
闲寻野寺听秋水，寄睡僧窗到夕阳。
骞翥会应霄汉去，渔竿休更恋沧浪。','',''),('quantangshi-41838','献中书韩舍人','李中','quantangshi','','卷42','丹墀朝退后，静院即冥搜。
尽日卷帘坐，前峰当槛秋。
烹茶留野客，展画看沧洲。
见说东林夜，寻常秉烛游。','',''),('quantangshi-41839','献徐舍人','李中','quantangshi','','卷42','清名喧四海，何止并南金。
奥学羣英伏，多才万乘钦。
秩参金殿峻，步历紫微深。
顾闻承中旨，丝纶演帝心。
褒雄饶义路，贾马避词林。
下直无他事，开门对远岑。
轩窗来晚吹，池沼歇秋霖。
藓点生棊石，茶烟过竹阴。
希夷元已达，躁竞岂能侵。
羽客闲陪饮，诗人伴静吟。
自渐为滞物，多幸辱虚襟。
此日重遭遇，心期出陆沈。','',''),('quantangshi-41840','新秋有感','李中','quantangshi','','卷42','门巷凉秋至，高梧一叶惊。
渐添衾簟爽，顿觉梦魂清。
暗促莲开艳，乍催蝉发声。
雨降炎气减，竹引冷烟生。
戍客添归思，行人怯远程。
未逢征雁下，渐听夜砧鸣。
张翰思鲈兴，班姬咏扇情。
音尘两难问，蛩砌月空明。','',''),('quantangshi-41841','秋雨','李中','quantangshi','','卷42','竟日散如丝，吟看半掩扉。
秋声在梧叶，润气逼书帏。
曲涧泉承去，危檐燕带归。
寒蛩悲旅壁，乱藓滑渔矶。
爽欲除幽簟，凉须换熟衣。
疎篷谁梦断，荒径独游稀。
偏称江湖景，不妨鸥鹭飞。
最怜为瑞处，南亩稻苗肥。','',''),('quantangshi-41842','寄庐山白大师','李中','quantangshi','','卷42','长忆寻师处，东林寓泊时。
一秋同看月，无夜不论诗。
泉美茶香异，堂深磬韵迟。
鹿驯眠藓径，猨苦叫霜枝。
别后音尘隔，年来鬓发衰。
趋名方汲汲，未果再游期。','',''),('quantangshi-41843','访龙光智谦上人','李中','quantangshi','','卷42','忽起寻师兴，穿云不觉劳。
相留看山雪，尽日论风骚。
竹影摇禅榻，茶烟上毳袍。
梦魂曾去否，旧国阻波涛。','',''),('quantangshi-41844','送仙客','李中','quantangshi','','卷42','危言危行是男儿，倚伏相牵岂足悲。
莫向汀洲时独立，悠悠斜日照江蓠。','',''),('quantangshi-41845','祀风师迎神曲','李中','quantangshi','','卷42','太皥御气，勾芒肇功。
苍龙青旗，爰候祥风。
律以和应，□以感通。
鼎徂修蠁，时惟礼崇。','',''),('quantangshi-41846','柳二首 一','李中','quantangshi','','卷42','春来无树不青青，似共东风别有情。
闲忆旧居湓水畔，数枝烟雨属啼莺。','',''),('quantangshi-41847','柳二首 二','李中','quantangshi','','卷42','最爱青青水国中，莫愁门外间花红。
纤纤无力胜春色，撼起啼莺恨晚风。','',''),('quantangshi-41848','送庐阜僧归山阳','李中','quantangshi','','卷42','山阳旧社终经梦，容易言归不可留。
瓶贮瀑泉离五老，锡摇江雨上孤舟。
鱼行细浪分沙觜，雁逆高风下苇洲。
遥想枚臯宅边寺，不知凉月共谁游。','',''),('quantangshi-41849','投所知','李中','quantangshi','','卷42','孤琴尘翳劒慵磨，自顾泥蟠欲奈何。
千里交亲消息断，一庭风雨梦魂多。
题桥未展相如志，叩角谁怜宁戚歌。
唯赖明公怜道在，敢携蓑笠钓烟波。','',''),('quantangshi-41850','寄左偃','李中','quantangshi','','卷42','萧条陋巷绿苔侵，何事君心似我心。
贫户懒开元爱静，病身才起便思吟。
闲留好鸟庭柯密，暗养鸣蛩砌草深。
况是清朝重文物，无愁当路少知音。','',''),('quantangshi-41851','游北山洞神宫','李中','quantangshi','','卷42','闷见尘中光景促，仙乡来礼紫阳君。
人居淡寂应难老，道在虚无不可闻。
松桧稳栖三岛鹤，楼台闲锁九霄云。
羡师向此朝星斗，一炷清香午夜焚。','',''),('quantangshi-41852','思简寂观旧游寄重道者','李中','quantangshi','','卷42','闲忆当年游物外，羽人曾许驻仙乡。
溪头烘药烟霞暖，花下围棊日月长。
偷摘蟠桃思曼倩，化成蝴蝶学蒙庄。
俗缘未断归浮世，空望林泉意欲狂。','',''),('quantangshi-41853','云','李中','quantangshi','','卷42','悠悠离洞壑，冉冉上天津。
捧日终为异，从龙自有因。
高行四海雨，暖拂万山春。
静与霞相近，闲将鹤最亲。
帝乡归莫问，楚殿梦曾频。
白向封中起，碧从诗里新。
冷容横钓浦，轻缕绊蟾轮。
不滞浓还淡，无心卷复伸。
非烟聊拟议，干吕在逡巡。
会作五般色，为祥覆紫宸。','',''),('quantangshi-41854','徐司徒池亭','李中','quantangshi','','卷42','亭榭跨池塘，泓澄入座凉。
扶疎皆竹柏，冷淡似潇湘。
萍嫩铺波面，苔深锁岸傍。
朝回游不厌，僧到赏难忘。
最称收残雨，偏宜带夕阳。
吟堪期谢朓，醉好命嵇康。
奢侈心难及，清虚趣最长。
月明垂钓兴，何必忆沧浪。','',''),('quantangshi-41855','赋得江边草','李中','quantangshi','','卷42','岸春芳草合，几处思缠绵。
向暮江蓠雨，初晴杜若烟。
静宜幽鹭立，远称碧波连。
送别王孙处，萋萋南浦边。','',''),('quantangshi-41856','江行夜泊','李中','quantangshi','','卷42','扁舟倦行役，寂寂宿江干。
半夜风雷过，一天星斗寒。
潮平沙觜没，霜苦雁声残。
渔父何疎逸，扣舷歌未阑。','',''),('quantangshi-41857','访山叟留题','李中','quantangshi','','卷42','策杖寻幽客，相携入竹扃。
野云生晚砌，病鹤立秋庭。
茶美睡心爽，琴清尘虑醒。
轮蹄应少到，门巷草青青。','',''),('quantangshi-41858','江行晚泊寄湓城知友','李中','quantangshi','','卷42','孤舟相忆久，何处倍关情。
野渡帆初落，秋风蝉一声。
江浮残照阔，云散乱山横。
渐去湓城远，那堪新月生。','',''),('quantangshi-41859','秋夕书怀','李中','quantangshi','','卷42','功名未立诚非晚，骨肉分飞又入秋。
枕上不堪残梦断，壁蛩窗月夜悠悠。','',''),('quantangshi-41860','感兴','李中','quantangshi','','卷42','渔休渭水兴周日，龙起南阳相蜀时。
不遇文王与先主，经天才业拟何为。','',''),('quantangshi-41861','舟中望九华山','李中','quantangshi','','卷42','排空苍翠异，辍棹看崔嵬。
一面雨初歇，九峰云正开。
当时思水石，便欲上楼台。
隐去心难遂，吟余首懒回。
僧休传紫阁，屏歇写天台。
中有忘机者，逍遥不可陪。','',''),('quantangshi-41862','渔父','李中','quantangshi','','卷42','烟冷暮江滨，高歌散诞身。
移舟过蓼岸，待月正丝纶。
亦与樵翁约，同游酒市春。
白头云水上，不识独醒人。','',''),('quantangshi-41863','赠上都紫极宫刘日新先生','李中','quantangshi','','卷42','道德吾君重，含贞本去华。
因知炼神骨，何必在烟霞。
棊散庭花落，诗成海月斜。
瀛洲旧仙侣，应许寄丹砂。','',''),('quantangshi-41864','勉同志','李中','quantangshi','','卷42','读书与磨劒，旦夕但忘疲。
傥若功名立，那愁变化迟。
尘从侵砚席，苔任满庭墀。
明代搜扬切，升沈莫问龟。','',''),('quantangshi-41865','寄刘钧秀才','李中','quantangshi','','卷42','掩户当春昼，知君志在诗。
闲花半落处，幽客未来时。
野鸟穿莎径，江雪过竹篱。
会须明月夜，与子水边期。','',''),('quantangshi-41866','离亭前思有寄','李中','quantangshi','','卷42','酒醒江亭客，缠绵恨别离。
笙歌筵散后，风月夜长时。
耿耿看灯暗，悠悠结梦迟。
若无骚雅分，何计达相思。','',''),('quantangshi-41867','赠上都先业大师','李中','quantangshi','','卷42','懒向人前着紫衣，虚堂闲倚一条藜。
虽承雨露居龙阙，终忆烟霞梦虎溪。
睡起晓窗风淅淅，病来深院草萋萋。
有时乘兴寻师去，煮茗同吟到日西。','',''),('quantangshi-41868','思九江旧居三首 一','李中','quantangshi','','卷42','结茅曾在碧江隈，多病贫身养拙来。
雨歇汀洲垂钓去，月当门巷访僧回。
静临窗下开琴匣，闷向牀头泼酒醅。
游宦等闲千里隔，空余魂梦到渔台。','',''),('quantangshi-41869','思九江旧居三首 二','李中','quantangshi','','卷42','门前烟水似潇湘，放旷优游兴味长。
虚阁静眠听远浪，扁舟闲上泛残阳。
鹤翘碧藓庭除冷，竹引清风枕簟凉。
犬吠疎篱明月上，隣翁携酒到茅堂。','',''),('quantangshi-41870','思九江旧居三首 三','李中','quantangshi','','卷42','无机终日狎沙鸥，得意高吟景且幽。
槛底江流偏称月，檐前山朵最宜秋。
遥村处处吹横笛，曲岸家家系小舟。
别后再游心未遂，设屏惟画白苹洲。','',''),('quantangshi-41871','赠东林白大师','李中','quantangshi','','卷42','虎溪久驻灵踪，禅外诗魔尚浓。
卷宿吟销永日，移牀坐对千峰。
苍苔冷鏁幽径，微风闲坐古松。
自说年来老病，出门渐觉疎慵。','',''),('quantangshi-41872','春晓','李中','quantangshi','','卷42','残烛犹存月尚明，几家帏幌梦魂惊。
星河渐没行人动，历历林梢百舌声。','',''),('quantangshi-41873','听郑羽人弹琴','李中','quantangshi','','卷42','仙乡景已清，仙子启琴声。
秋月空山寂，淳风一夜生。
莎间虫罢响，松顶鹤初惊。
因感浮华世，谁怜太古情。','',''),('quantangshi-41874','秋夕书事寄友人','李中','quantangshi','','卷42','信断关河远，相思秋夜深。
砌蛩声咽咽，檐月影沈沈。
未遂青云志，那堪素发侵。
吟余成不寐，彻曙四邻砧。','',''),('quantangshi-41875','秋日途中','李中','quantangshi','','卷42','竹林已萧索，客思正如雠。
旧业吴江外，新蝉楚驿头。
遥天疎雨过，列岫乱云收。
今夕谁家宿，孤吟月色秋。','',''),('quantangshi-41876','秋夜吟寄左偃','李中','quantangshi','','卷42','与君诗兴素来狂，况入清秋夜景长。
溪阁共谁看好月，莎堦应独听寒螿。
卷中新句诚堪喜，身外浮名不足忙。
会约垂名继前哲，任他玄发尽如霜。','',''),('quantangshi-41877','竹','李中','quantangshi','','卷42','森森移得自山庄，植向空庭野兴长。
便有好风来枕簟，更无闲梦到潇湘。
荫来砌藓经疎雨，引下溪禽带夕阳。
闲约羽人同赏处，安排棊局就清凉。','',''),('quantangshi-41878','怀庐岳旧游寄刘钧因感鉴上人','李中','quantangshi','','卷42','昔年庐岳闲游日，乘兴因寻物外僧。
寄宿爱听松叶雨，论诗惟对竹窗灯。
各拘片禄寻分别，高谢浮名竟未能。
一念支公安可见，影堂何处暮云凝。','',''),('quantangshi-41879','依韵酬智谦上人见寄','李中','quantangshi','','卷42','性拙才非逸，同心友亦稀。
风昏秋病眼，霜湿夜吟衣。
莺谷期犹负，兰陔养不违。
吾师惠佳句，胜得楚金归。','',''),('quantangshi-41880','落花','李中','quantangshi','','卷42','年年三月暮，无计惜残红。
酷恨西园雨，生憎南陌风。
片随流水远，色逐断霞空。
怅望丛林下，悠悠饮兴穷。','',''),('quantangshi-41881','题柳','李中','quantangshi','','卷42','折向离亭畔，春光满手生。
群花岂无艳，柔质自多情。
夹岸笼溪月，兼风撼野莺。
隋堤三月暮，飞絮想纵横。','',''),('quantangshi-41882','赠谦明上人','李中','quantangshi','','卷42','虽寄上都眠竹寺，逸情终忆白云端。
闲登钟阜林泉晚，梦去沃洲风雨寒。
新试茶经煎有兴，旧婴诗病舍终难。
常闻秋夕多无寐，月在高台独凭栏。','',''),('quantangshi-41883','书蔡隐士壁','李中','quantangshi','','卷42','病后霜髭出，衡门寂寞中。
蠹侵书帙损，尘覆酒罇空。
池暗菰蒲雨，径香兰蕙风。
幽闲已得趣，不见卜穷通。','',''),('quantangshi-41884','赠钟尊师游茅山','李中','quantangshi','','卷42','筇杖担琴背俗尘，路寻茅岭有谁群。
仙翁物外应相遇，灵药壶中必许分。
香入肌肤花洞酒，冷侵魂梦石牀云。
伊予亦有朝修志，异日遨游愿见君。','',''),('quantangshi-41885','访徐长史留题水阁','李中','quantangshi','','卷42','君家池阁静，一到且淹留。
坐听蒹葭雨，如看岛屿秋。
杯盘深有兴，吟笑迥忘忧。
更爱幽奇处，双双下野鸥。','',''),('quantangshi-41886','夕阳','李中','quantangshi','','卷42','影未沈山水面红，遥天雨过促征鸿。
魂销举子不回首，闲照槐花驿路中。','',''),('quantangshi-41887','鸂鶒','李中','quantangshi','','卷42','流品是鸳鸯，翻飞云水乡。
风高离极浦，烟暝下方塘。
比鹭行藏别，穿荷羽翼香。
双双浴轻浪，谁见在潇湘。','',''),('quantangshi-41888','所思','李中','quantangshi','','卷42','离思春来切，谁能慰寂寥。
花飞寒食过，云重楚山遥。
耿耿梦徒往，悠悠鬓易凋。
那堪对明月，独立水边桥。','',''),('quantangshi-41889','春闺辞二首 一','李中','quantangshi','','卷42','卷帘迟日暖，睡起思沈沈。
辽海音尘远，春风旅馆深。
疎篁留鸟语，曲砌转花阴。
寄语长征客，流年不易禁。','',''),('quantangshi-41890','春闺辞二首 二','李中','quantangshi','','卷42','不得辽阳信，春心何以安。
鸟啼窗树晓，梦断碧烟残。
绿鉴开还懒，红颜驻且难。
相思谁可诉，时取旧书看。','',''),('quantangshi-41891','腊中作','李中','quantangshi','','卷42','冬至虽云远，浑疑朔漠中。
劲风吹大野，密雪翳高空。
泉冻如顽石，人藏类蛰虫。
豪家应不觉，兽炭满炉红。','',''),('quantangshi-41892','海城秋日书怀寄朐山孙明府','李中','quantangshi','','卷42','槐柳蝉声起渡头，海城孤客思悠悠。
青云展志知何日，皓月牵吟又入秋。
鉴里渐生潘岳鬓，风前犹着卜商裘。
鸣琴良宰挥毫士，应笑蹉跎身未酬。','',''),('quantangshi-41893','题柴司徒亭假山','李中','quantangshi','','卷42','叠石峨峨象翠微，远山魂梦便应稀。
从教藓长添峰色，好引泉来作瀑飞。
萤影夜攒疑烧起，茶烟朝出认云归。
知君创得兹幽致，公退吟看到落晖。','',''),('quantangshi-41894','都下寒食夜作','李中','quantangshi','','卷42','香尘未歇暝烟收，城满笙歌事胜游。
自是离人睡长早，千家帘卷月当楼。','',''),('quantangshi-41895','客中春思','李中','quantangshi','','卷42','又听黄鸟绵蛮，目断家乡未还。
春水引将客梦，悠悠遶遍关山。','',''),('quantangshi-41896','所思','李中','quantangshi','','卷42','门掩残花寂寂，帘垂斜月悠悠。
纵有一庭萱草，何曾与我忘忧。','',''),('quantangshi-41897','江馆秋思因成自勉','李中','quantangshi','','卷42','江边候馆幽，汀鸟暝烟收。
客思虽悲月，诗魔又爱秋。
声名都是幻，穷达未能忧。
散逸怜渔父，波中漾小舟。','',''),('quantangshi-41898','赠朐山杨宰','李中','quantangshi','','卷42','讼闲徴赋毕，吏散卷帘时。
听雨入秋竹，留僧覆旧棋。
得诗书落叶，煮茗汲寒池。
化俗功成后，烟霄会有期。','',''),('quantangshi-41899','庐山','李中','quantangshi','','卷42','控厌浔阳景，崔嵬古及今。
势雄超地表，翠盛接天心。
湓浦春烟列，星湾晚景沈。
图经宜细览，题咏卒难任。
靖节门遥对，庾公楼俯临。
参差含积雪，隐映见归禽。
峭拔推双劒，清虚数二林。
白莲池宛在，翠辇事难寻。
天近星河冷，龙归洞穴深。
谷春攒锦绣，石润叠琼琳。
玄鹤传仙拜，青猨伴客吟。
泉通九江远，云出几州阴。
冬有灵汤溢，夏无炎暑侵。
他年如遂隐，五老是知音。','',''),('quantangshi-41900','送孙霁书记赴寿阳[辟]命','李中','quantangshi','','卷42','辟命羡君赴，其如怆别情。
酒阑汀树晚，帆展野风生。
淮静寒烟歛，村遥夜火明。
醉沈朐岭梦，吟达寿春城。
旧友摇鞭接，元戎扫榻迎。
雪晴莲幕启，云散桂山横。
王粲从军画，陈琳草檄名。
知君提健笔，重振此嘉声。','',''),('quantangshi-41901','听蝉寄朐山孙明府','李中','quantangshi','','卷42','忽听新蝉发，客情其奈何。
西风起槐柳，故国阻烟波。
壠笛悲犹少，巴猨恨未多。
不知陶靖节，还动此心麽。','',''),('quantangshi-41902','秋江夜泊寄刘钧正字','李中','quantangshi','','卷42','闲忆诗人思倍劳，维舟清夜泥风骚。
鱼龙不动澄江远，云雾皆收皎月高。
潮满钓舟迷浦屿，霜繁野树叫猨猱。
此时吟苦君知否，双鬓从他有二毛。','',''),('quantangshi-41903','赠朐山孙明府','李中','quantangshi','','卷42','县庭无事似山斋，满砌青青旋长苔。
闲抚素琴曹吏散，自烹新茗海僧来。
买将病鹤劳心养，移得闲花用意栽。
几度访君留我醉，瓮香皆值酒新开。','',''),('quantangshi-41904','赠海上书记张济员外','李中','quantangshi','','卷42','鹏霄休叹志难伸，贫病虽萦道且存。
阮瑀不能专笔砚，嵇康唯要乐琴尊。
春风满院空欹枕，芳草侵堦独闭门。
劒有尘埃书有蠹，昔年心事共谁论。','',''),('quantangshi-41905','对竹','李中','quantangshi','','卷42','懒穿幽径冲鸣鸟，忍踏清阴损翠苔。
不似闭门欹枕听，秋声如雨入轩来。','',''),('quantangshi-41906','送朐山孙明府赴寿阳幕府辟命','李中','quantangshi','','卷42','堪羡元戎虚右席，便承纶綍起金台。
菊丛憔悴陶潜去，莲幕光辉阮瑀来。
好向尊罍陈妙画，定应书檄播雄才。
预愁别后相思处，月入闲窗远梦回。','',''),('quantangshi-41907','经废宅','李中','quantangshi','','卷42','一梦奢华去不还，断墙花发岂堪看。
玉纤素绠知何处，金井梧枯碧甃寒。','',''),('quantangshi-41908','溪边吟','李中','quantangshi','','卷42','鸂鶒双飞下碧流，蓼花苹穗正含秋。
茜裙二八采莲去，笑冲微雨上兰舟。','',''),('quantangshi-41909','得故人消息','李中','quantangshi','','卷42','多难分离久，相思每泪垂。
梦归残月晓，信到落花时。
未必乖良会，何当有后期。
那堪楼上望，烟水接天涯。','',''),('quantangshi-41910','芳草','李中','quantangshi','','卷42','二月正绵绵，离情被尔牵。
四邻初过雨，万里正铺烟。
眷恋残花惹，留连醉客眠。
飘香是杜若，最忆楚江边。','',''),('quantangshi-41911','江南春','李中','quantangshi','','卷42','千家事胜游，景物可忘忧。
水国楼台晚，春郊烟雨收。
鹧鸪啼竹树，杜若媚汀洲。
永巷歌声远，王孙会莫愁。','',''),('quantangshi-41912','悼亡','李中','quantangshi','','卷42','巷深芳草细，门静绿杨低。
室迩人何处，花残月又西。
武陵期已负，巫峡梦终迷。
独立销魂久，双双好鸟啼。','',''),('quantangshi-41913','春晏寄从弟德润','李中','quantangshi','','卷42','相思禁烟近，楼上动吟魂。
水国春寒在，人家暮雨昏。
朱桥通竹树，香径匝兰荪。
安得吾宗会，高歌醉一尊。','',''),('quantangshi-41914','赠致仕沈彬郎中','李中','quantangshi','','卷42','自言婚嫁毕，尘事不关心。
老去诗魔在，春来酒病深。
山翁期采药，海月伴鸣琴。
多谢维舟处，相留接静吟。','',''),('quantangshi-41915','忆溪居','李中','quantangshi','','卷42','竹轩临水静无尘，别后凫鹥入梦频。
杜若菰蒲烟雨歇，一溪春色属何人。','',''),('quantangshi-41916','登下蔡县楼','李中','quantangshi','','卷42','长涯烟水又含秋，吏散时时独上楼。
信断兰台乡国远，依稀王粲在荆州。','',''),('quantangshi-41917','下蔡春偶作','李中','quantangshi','','卷42','旅馆飘飘类断蓬，悠悠心绪有谁同。
一宵风雨花飞后，万里乡关梦自通。
多难不堪容鬓改，沃愁惟怕酒杯空。
采兰扇沈何时遂，洗虑焚香叩上穹。','',''),('quantangshi-41918','再游洞神宫怀邵羽人有感','李中','quantangshi','','卷42','重向烟萝省旧游，因寻遗迹想浮丘。
峰头鹤去三清远，坛畔月明千古秋。
泉落小池清复咽，云从高峤起还收。
自慙未得冲虚术，白发无情渐满头。','',''),('quantangshi-41919','秋雨二首 一','李中','quantangshi','','卷42','飘洒当穷巷，苔深落叶铺。
送寒来客馆，滴梦在庭梧。
逼砌蛩声断，侵窗竹影孤。
遥思渔叟兴，蓑笠在江湖。','',''),('quantangshi-41920','秋雨二首 二','李中','quantangshi','','卷42','竟日声萧飒，兼风不暂阑。
竹窗秋睡美，荻浦夜渔寒。
地僻苔生易，林疎鸟宿难。
谁知苦吟者，坐听一灯残。','',''),('quantangshi-41921','经古观有感','李中','quantangshi','','卷42','古观寥寥枕碧溪，偶思前事立残晖。
漆园化蝶名空在，柱史犹龙去不归。
丹井泉枯苔锁合，醮坛松折鹤来稀。
回头因叹浮生事，梦里光阴疾若飞。','',''),('quantangshi-41922','吉水春暮访蔡文庆处士留题','李中','quantangshi','','卷42','无事无忧鬓任苍，浊醪闲酌送韶光。
溟蒙雨过池塘暖，狼藉花飞砚席香。
好古未尝疎典册，悬图时要看潇湘。
恋君清话难留处，归路迢迢又夕阳。','',''),('quantangshi-41923','烈祖孝高挽歌二首 一','李中','quantangshi','','卷42','谁解叩干关，音容去不还。
位方尊北极，寿忽殒南山。
凤辇应难问，龙髯不可攀。
千秋遗恨处，云物锁桥山。','',''),('quantangshi-41924','烈祖孝高挽歌二首 二','李中','quantangshi','','卷42','仙驭归何处，苍苍问且难。
华夷喧道德，陵壠葬衣冠。
御水穿城咽，宫花泣露寒。
九疑消息断，空望白云端。','',''),('quantangshi-41925','赠海上观音院文依上人','李中','quantangshi','','卷42','烟霞海边寺，高卧出门慵。
白日少来客，清风生古松。
虚窗从燕入，坏屐任苔封。
几度陪师话，相留到暮钟。','',''),('quantangshi-41926','秋夕病中作','李中','quantangshi','','卷42','卧病当秋夕，悠悠枕上情。
不堪抛月色，无计避虫声。
煎药惟忧澁，停灯又怕明。
晓临清鉴里，应有白髭生。','',''),('quantangshi-41927','寄黄鹗秀才','李中','quantangshi','','卷42','长忆狂游日，惜春心恰同。
预愁花片落，不遣酒壶空。
草软眠难舍，莺娇听莫穷。
如今千里隔，骚首对秋风。','',''),('quantangshi-41928','春日书怀寄朐山孙明府','李中','quantangshi','','卷42','一作边城客，闲门两度春。
莺花深院雨，书劒满牀尘。
紫阁期终负，青云道未伸。
犹怜陶靖节，诗酒每相亲。','',''),('quantangshi-41929','柴司徒宅牡丹','李中','quantangshi','','卷42','暮春栏槛有佳期，公子开颜乍拆时。
翠幄密笼莺未识，好香难掩蝶先知。
愿陪妓女争调乐，欲赏宾朋预课诗。
只恐却随云雨去，隔年还是动相思。','',''),('quantangshi-41930','赠王道者','李中','quantangshi','','卷42','混俗从教鬓似银，世人无分得相亲。
槎流海上波涛阔，酒满壶中天地春。
功就不看丹竈火，性闲时拂玉琴尘。
仙家变化谁能测，只恐洪崖是此身。','',''),('quantangshi-41931','春闺辞二首 一','李中','quantangshi','','卷42','尘昏菱鉴懒修容，双脸桃花落尽红。
玉塞梦归残烛在，晓莺窗外啭梧桐。','',''),('quantangshi-41932','春闺辞二首 二','李中','quantangshi','','卷42','边无音信暗消魂，茜袖香裙积泪痕。
海燕归来门未掩，悠悠花落又黄昏。','',''),('quantangshi-41933','暮春怀故人','李中','quantangshi','','卷42','池馆寂寥三月尽，落花重叠盖莓苔。
惜春眷恋不忍扫，感物心情无计开。
梦断美人沈信息，目穿长路倚楼台。
琅玕绣段安可得，流水浮云共不回。','',''),('quantangshi-41934','秋日登润州城楼','李中','quantangshi','','卷42','虚楼一望极封疆，积雨晴来野景长。
水接海门铺远色，稻连京口发秋香。
鸣蝉历历空相续，归鸟翩翩自着行。
吟罢倚栏深有思，清风留我到斜阳。','',''),('quantangshi-41935','晚春客次偶吟','李中','quantangshi','','卷42','暂驻征轮野店间，悠悠时节又春残。
落花风急宿酲解，芳草雨昏春梦寒。
慙逐利名头易白，欲眠云水志犹难。
却怜村寺僧相引，闲上虚楼共倚栏。','',''),('quantangshi-41936','对雨寄朐山林番明府','李中','quantangshi','','卷42','竟日如丝不暂停，莎堦闲听滴秋声。
斜飘虚阁琴书润，冷逼幽窗梦寐清。
开户只添搜句味，看山还阻上楼情。
遥知公退琴堂静，坐对萧骚饮兴生。','',''),('quantangshi-41937','落花','李中','quantangshi','','卷42','残红引动诗魔，怀古牵情奈何。
半落铜台月晓，乱飘金谷风多。
悠悠旋逐流水，片片轻黏短莎。
谁见长门深锁，黄昏细雨相和。','',''),('quantangshi-41938','燕','李中','quantangshi','','卷42','豪家五色泥香，衔得营巢太忙。
喧觉佳人昼梦，双双犹在雕梁。','',''),('quantangshi-41939','莺','李中','quantangshi','','卷42','羽毛特异诸禽，出谷堪听好音。
薄暮欲栖何处，雨昏杨柳深深。','',''),('quantangshi-41940','宿山中寺','李中','quantangshi','','卷42','寄宿深山寺，惟逢老病僧。
风吹几世树，云暗暮秋灯。
瞑目忘尘虑，谈空入上乘。
明晨返名路，何计恋南能。','',''),('quantangshi-41941','海上载笔依韵酬左偃见寄','李中','quantangshi','','卷42','都城分别后，海峤梦魂迷。
吟兴疎烟月，边情起鼓鼙。
戍旗风颭小，营柳雾笼低。
草檄无余刃，难将阮瑀齐。','',''),('quantangshi-41942','春晚招鲁从事','李中','quantangshi','','卷42','衮衮利名役，常嗟聚会稀。
有心游好景，无术驻残晖。
南陌草争茂，西园花乱飞。
期君举杯酒，不醉莫言归。','',''),('quantangshi-41943','和易秀才春日见寄','李中','quantangshi','','卷42','每恨多流落，吾徒不易亲。
相逢千里客，共醉百花春。
小槛山当面，闲堦柳拂尘。
何时卜西上，明月桂枝新。','',''),('quantangshi-41944','送黄秀才','李中','quantangshi','','卷42','雨余飞絮乱，相别思难任。
酒罢河桥晚，帆开烟水深。
蟾宫须展志，渔艇莫牵心。
岐路从兹远，双鱼信勿沈。','',''),('quantangshi-41945','庭竹','李中','quantangshi','','卷42','偶自山僧院，移归傍砌栽。
好风终日起，幽鸟有时来。
筛月牵诗兴，笼烟伴酒杯。
南窗睡轻起，萧飒雨声回。','',''),('quantangshi-41946','送戴秀才','李中','quantangshi','','卷42','已是殊乡客，送君重惨然。
河桥乍分首，槐柳正鸣蝉。
短棹离幽浦，孤帆触远烟。
清朝重文物，变化莫迁延。','',''),('quantangshi-41947','病中作','李中','quantangshi','','卷42','闲斋病初起，心绪复悠悠。
开箧羣书蠹，听蝉满树秋。
诗魔还渐动，药债未能酬。
为忆前山色，扶持上小楼。','',''),('quantangshi-41948','离家','李中','quantangshi','','卷42','送别人归春日斜，独鞭羸马指天涯。
月生江上乡心动，投宿怱忙近酒家。','',''),('quantangshi-41949','村行','李中','quantangshi','','卷42','极目青青壠麦齐，野塘波阔下凫鹥。
阳乌景暖林桑密，独立闲听戴胜啼。','',''),('quantangshi-41950','献乔侍郎','李中','quantangshi','','卷42','位望谁能并，当年志已伸。
人间传凤藻，天上演龙纶。
贾马才无敌，褒雄誉益臻。
除奸深系念，致主迥忘身。
谏疏纵横上，危言果敢陈。
忠贞虽贯世，消长岂由人。
慷慨辞朝阙，迢遥涉路尘。
千山明夕照，孤棹渡长津。
杜宇声方切，江蓠色正新。
卷舒唯合道，喜愠不劳神。
蝉客陪清论，渔翁作近邻。
静吟穷野景，狂醉养天真。
格论思名士，舆情渴直臣。
九霄恩复降，比户意皆忻。
却入鸳鸾序，终身顾问频。
漏残丹禁晓，日暖玉墀春。
鉴物心如水，忧时鬓若银。
惟期康庶事，永要叙彝伦。
贵贱知无间，孤寒必许亲。
几多沈滞者，拭目望陶钧。','',''),('quantangshi-41951','献中书张舍人','李中','quantangshi','','卷42','仙桂从攀后，人间播大名。
飞腾谐素志，霄汉是前程。
持宪威声振，司言品秩清。
帘开春酒醒，月上草麻成。
丹陛凌晨对，青云逐步生。
照人裴玉莹，鉴物宪陂明。
下直无他事，闲游恣逸情。
林僧开户接，溪叟扫苔迎。
煮茗山房冷，垂纶野艇轻。
神清宜放旷，诗苦益纵横。
余刃时皆仰，嘉谋众伫行。
四方观启沃，毕竟念孤平。','',''),('quantangshi-41952','海上和郎戬员外赴倅职','李中','quantangshi','','卷42','宋玉逢秋何起悲，新恩委寄好开眉。
班升鸳鹭频经岁，任佐龚黄必暂时。
乍对烟霞吟海峤，应思苹蓼梦江湄。
一朝凤诏仲征入，鹏化那教尺鷃知。','',''),('quantangshi-41953','又送赴关','李中','quantangshi','','卷42','心似白云归帝乡，暂停良画别龚黄。
烟波乍晓浮兰棹，魂梦先飞近御香。
一路伴吟汀草绿，几程清思水风凉。
想应敷对忠言后，不放乡云离太阳。','',''),('quantangshi-41954','书郭判官幽斋壁','李中','quantangshi','','卷42','不妨公退尚清虚，剏得幽斋兴有余。
要引好风清户牖，旋栽新竹满庭除。
倾壶待客花开后，煮茗留僧月上初。
更有野情堪爱处，石牀苔藓似匡庐。','',''),('quantangshi-41955','石棊局献时宰','李中','quantangshi','','卷42','得从岳叟诚堪重，却献臯夔事更宜。
公退启枰书院静，日斜收子竹阴移。
适情岂待樵柯烂，罢局还应屐齿隳。
预想幽窗风雨夜，一灯闲照覆图时。','',''),('quantangshi-41956','海城秋夕寄怀舍弟','李中','quantangshi','','卷42','鸟栖庭树夜悠悠，枕上谁知泪暗流。
千里梦魂迷旧业，一城砧杵捣残秋。
窗闲寂寂灯犹在，帘外萧萧雨未休。
早晚莱衣同着去，免悲流落在边州。','',''),('quantangshi-41957','和夏侯秀才春日见寄','李中','quantangshi','','卷42','绵蛮黄鸟不堪听，触目离愁怕酒醒。
云散碧山当晚槛，雨催青藓匝春庭。
寻芳懒向桃花坞，垂钓空思杜若汀。
昼梦不成吟有兴，挥毫书在枕边屏。','',''),('quantangshi-41958','送夏侯秀才','李中','quantangshi','','卷42','江村摇落暮蝉鸣，执手临岐动别情。
古岸相看残照在，片帆难驻好风生。
牵吟一路逢山色，醒睡长汀对月明。
况是清朝至公在，预知乔木定迁莺。','',''),('quantangshi-41959','江南重会友人感旧二首 一','李中','quantangshi','','卷42','江南重会面，聊话十年心。
共立黄花畔，空惊素发侵。
斜阳浮远水，归鸟下疎林。
牵动诗魔处，凉风村落砧。','',''),('quantangshi-41960','江南重会友人感旧二首 二','李中','quantangshi','','卷42','长江落照天，物景似当年。
忆昔携村酒，相将上钓船。
狂歌红蓼岸，惊起白鸥眠。
今日趋名急，临风一黯然。','',''),('quantangshi-41961','己未岁冬捧宣头离下蔡','李中','quantangshi','','卷42','诏下如春煦，巢南志不违。
空将感恩泪，滴尽冒寒衣。
覆载元容善，形骸果得归。
无心渐季路，负米觐亲闱。','',''),('quantangshi-41962','哭舍弟二首 一','李中','quantangshi','','卷42','鸿雁离群后，成行忆日存。
谁知归故里，只得奠吟魂。
虫蠹书盈箧，人稀草拥门。
从兹长恸后，独自奉晨昏。','',''),('quantangshi-41963','哭舍弟二首 二','李中','quantangshi','','卷42','浮生多夭枉，惟尔最堪悲。
同气未归日，慈亲临老时。
旧诗传海峤，新冢枕江湄。
遗稚呜呜处，黄昏绕穗帷。','',''),('quantangshi-41964','书情寄诗友','李中','quantangshi','','卷42','默默谁知我，裴回野水边。
诗情长若旧，吾事更无先。
芳草人稀地，残阳雁过天。
静思吟友外，此意复谁怜。','',''),('quantangshi-41965','读蜀志','李中','quantangshi','','卷42','鼎分天地日，先主力元微。
鱼水从相得，山河遂有归。
任贤无间忌，报国尽神机。
草昧争雄者，君臣似此稀。','',''),('quantangshi-41966','献张拾遗','李中','quantangshi','','卷42','官资清贵近丹墀，性格孤高世所稀。
金殿日开亲凤扆，古幈时展看渔矶。
酒醒虚阁秋帘卷，吟对疎篁夕鸟归。
献替频陈忠誉播，鹏霄万里展雄飞。','',''),('quantangshi-41967','献中书汤舍人','李中','quantangshi','','卷42','庆云呈瑞为明时，演畅丝纶在紫微。
銮殿对时亲舜日，鲤庭过处着莱衣。
闲寻竹寺听啼鸟，吟倚江楼恋落晖。
隔座银屏看是设，一门清贵古今稀。','',''),('quantangshi-41968','海上太守新剏东亭','李中','quantangshi','','卷42','使君心智杳难同，选胜开亭景莫穷。
高敞轩窗迎海月，预栽花木待春风。
静披典籍堪师古，醉拥笙歌不碍公。
满径苔纹疎雨后，入檐山色夕阳中。
偏宜下榻延徐孺，最称登门礼孔融。
事简岂妨频赏翫，况当为政有余功。','',''),('quantangshi-41969','宫词二首 一','李中','quantangshi','','卷42','门鏁帘垂月影斜，翠华咫尺隔天涯。
香铺罗幌不成梦，背壁银缸落尽花。','',''),('quantangshi-41970','宫词二首 二','李中','quantangshi','','卷42','金波寒透水精帘，烧尽沈檀手自添。
风递笙歌门已掩，翠华何处夜厌厌。','',''),('quantangshi-41971','采莲女','李中','quantangshi','','卷42','晚凉含笑上兰舟，波底红妆影欲浮。
陌上少年休植足，荷香深处不回头。','',''),('quantangshi-41972','钟陵春思','李中','quantangshi','','卷42','沈沈楼影月当午，冉冉风香花正开。
芳草迢迢满南陌，王孙何处不归来。','',''),('quantangshi-41973','赠夏秀才','李中','quantangshi','','卷42','轩车紫陌竞寻春，独掩衡门病起身。
步月怕伤三径藓，取琴因拂一牀尘。
明时傥有丹枝分，青鉴从他素发新。
况是青云知己在，原思生计莫忧贫。','',''),('quantangshi-41974','夏日书依上人壁','李中','quantangshi','','卷42','门外尘飞暑气浓，院中萧索似山中。
最怜煮茗相留处，疎竹当轩一榻风。','',''),('quantangshi-41975','下蔡春暮旅怀','李中','quantangshi','','卷42','柳过春霖絮乱飞，旅中怀抱独[凄凄]。
月生淮上云初散，家在江南梦去迷。
发白每慙清鉴启，心孤长怯子规啼。
拜恩为养慈亲急，愿向明朝捧紫泥。','',''),('quantangshi-41976','捧宣头许归侍养','李中','quantangshi','','卷42','泥书捧处圣恩新，许觐庭闱养二亲。
蝼蚁至微宁足数，未知何处答穹旻。','',''),('quantangshi-41977','途中作','李中','quantangshi','','卷42','烟波涉历指家林，欲到家林惧却深。
得信慈亲疴瘵减，当时宽勉采兰心。','',''),('quantangshi-41978','都下再会友人','李中','quantangshi','','卷42','谁言多难后，重会喜淹留。
欲话关河梦，先惊鬓发秋。
浮云空冉冉，远水自悠悠。
多谢开青眼，携壶共上楼。','',''),('quantangshi-41979','登毗陵青山楼','李中','quantangshi','','卷42','高楼闲上对晴空，豁目开襟半日中。
千里吴山清不断，一边辽海浸无穷。
人生歌笑开花雾，世界兴亡落叶风。
吟罢倚栏何限意，回头城郭暮烟笼。','',''),('quantangshi-41980','晋陵罢任寓居依韵和陈锐秀才见寄','李中','quantangshi','','卷42','掩门三径莓苔绿，车马谁来陋巷间。
卧弃琴书公干病，笑迎风月步兵闲。
当秋每谢蛬清耳，渐老多慙酒借颜。
济物未能伸一术，敢于明代爱青山。','',''),('quantangshi-41981','春苔','李中','quantangshi','','卷42','春霖催得锁烟浓，竹院莎斋径小通。
谁爱落花风味处，莫愁门巷衬残红。','',''),('quantangshi-41982','夏云','李中','quantangshi','','卷42','如峰形状在西郊，未见从龙上泬寥。
多谢好风吹起后，化为甘雨济田苗。','',''),('quantangshi-41983','书夏秀才幽居壁','李中','quantangshi','','卷42','永巷苔深户半开，牀头书劒积尘埃。
最怜小槛疎篁晩，幽鸟双双何处来。','',''),('quantangshi-41984','红花','李中','quantangshi','','卷42','红花颜色掩千花，任是猩猩血未加。
染出轻罗莫相贵，古人崇俭诫奢华。','',''),('quantangshi-41985','安福县秋吟寄陈锐秘书','李中','quantangshi','','卷42','县庭事简得余功，诗兴秋来不可穷。
卧听寒蛬莎砌月，行冲落叶水村风。
愁髭渐去人前白，醉面犹怜鉴里红。
苦恨交亲多契阔，未知良会几时同。','',''),('quantangshi-41986','新喻县酬王仲华少府见贻','李中','quantangshi','','卷42','事简开樽有逸情，共忻官舍月华清。
每慙花欠河阳景，长愧琴无单父声。
未泰黎元惭旷职，纵行谦直是虚名。
与君尽力行公道，敢向昌朝俟陟明。','',''),('quantangshi-41987','暮春有感寄宋维员外','李中','quantangshi','','卷42','杜宇声中老病心，此心无计驻光阴。
西园雨过好花尽，南陌人稀芳草深。
喧梦却嫌莺语老，伴吟惟怕月轮沈。
明年才候东风至，结驷期君预去寻。','',''),('quantangshi-41988','题吉水县厅前新栽小松','李中','quantangshi','','卷42','斸开幽涧藓苔斑，移得孤根植砌前。
影小未遮官舍月，翠浓犹带旧山烟。
群花解笑香宁久，众木虽高节不坚。
输我婆娑栏槛内，晚风萧飒学幽泉。','',''),('quantangshi-41989','赠念法华经绶上人','李中','quantangshi','','卷42','五更初起扫松堂，瞑目先焚一炷香。
念彻莲经谁得见，千峰岩外晓苍苍。','',''),('quantangshi-41990','秋日途中','李中','quantangshi','','卷42','信步腾腾野岸边，离家都为利名牵。
疎林一路斜阳里，飒飒西风满耳蝉。','',''),('quantangshi-41991','宿韦校书幽居','李中','quantangshi','','卷42','溪上高眠与鹤闲，开樽留我待柴关。
园林月白秋霖歇，一夜泉声似故山。','',''),('quantangshi-41992','依韵和友人秋夕见寄','李中','quantangshi','','卷42','夕风庭叶落，谁见此时情。
不作关河梦，空闻砧杵声。
会须求至理，何必叹无成。
好约高僧宿，同看海月生。','',''),('quantangshi-41993','吉水作尉酬高援秀才见赠','李中','quantangshi','','卷42','佐邑慙无术，敢言贫与清。
风骚谁是主，烟月自关情。
卷箔当山色，开窗就竹声。
怜君惠嘉句，资我欲垂名。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-41994','送智雄上人','李中','quantangshi','','卷42','忽起游方念，飘然不可留。
未知携一锡，乘兴向何州。
古岸春云散，遥天晚雨收。
想应重会面，风月又清秋。','',''),('quantangshi-41995','览友人卷','李中','quantangshi','','卷42','新诗开卷处，造化竭精英。
雪霁楚山碧，月高湘水清。
初吟尘虑息，再味古风生。
自此寰区内，喧腾二雅名。','',''),('quantangshi-41996','送人南游','李中','quantangshi','','卷42','浪迹天涯去，南荒必动情。
草青虞帝庙，云暗夜郎城。
越鸟惊乡梦，蛮风解宿酲。
早思归故里，华发等闲生。','',''),('quantangshi-41997','晋陵县夏日作','李中','quantangshi','','卷42','事简公庭静，开帘暑气中。
依经煎绿茗，入竹就清风。
至论招禅客，忘机忆钓翁。
晚凉安枕簟，海月出墙东。','',''),('quantangshi-41998','邮亭早起','李中','quantangshi','','卷42','邮舍残灯在，村林鸡唱频。
星河吟里晓，川陆望中春。
旧友青云贵，殊乡素发新。
悠悠念行计，难更驻征轮。','',''),('quantangshi-41999','客中寒食','李中','quantangshi','','卷42','旅次经寒食，思乡泪湿巾。
音书天外断，桃李雨中春。
欲饮都无绪，唯吟似有因。
输他郊郭外，多少踏青人。','',''),('quantangshi-42000','旅馆秋夕','李中','quantangshi','','卷42','寥寥山馆里，独坐酒初醒。
旧业多年别，秋霖一夜听。
砌蛬声渐息，窗烛影犹停。
早晚无他事，休如泛水萍。','',''),('quantangshi-42001','宿青溪米处士幽居','李中','quantangshi','','卷42','寄宿溪光里，夜凉高士家。
养风窗外竹，叫月水中蛙。
静虑同搜句，清神旋煮茶。
唯忧晓鸡唱，尘里事如麻。','',''),('quantangshi-42002','维舟秋浦逢故人张矩同泊','李中','quantangshi','','卷42','卸帆清夜碧江滨，冉冉凉风动白苹。
波上正吟新霁月，岸头恰见故乡人。
共惊别后霜侵鬓，互说年来疾逼身。
且饮一壶销百恨，会须遭遇识通津。','',''),('quantangshi-42003','代别','李中','quantangshi','','卷42','明日鸣鞭天一涯，悠悠此夕怯分离。
红楼有恨金波转，翠黛无言玉筯垂。
浮蚁不能迷远意，回纹从此寄相思。
花时定是慵开鉴，独向春风忍扫眉。','',''),('quantangshi-42004','悼怀王丧妃','李中','quantangshi','','卷42','花绽花开事可惊，暂来浮世返蓬瀛。
楚宫梦断云空在，洛浦神归月自明。
香解返魂成浪语，胶能续断是虚名。
音容寂寞春牢落，谁会楼中独立情。','',''),('quantangshi-42005','酒醒','李中','quantangshi','','卷42','睡觉花阴芳草软，不知明月出墙东。
杯盘狼藉人何处，聚散空惊似梦中。','',''),('quantangshi-42006','送虞道士','李中','quantangshi','','卷42','烟霞聚散通三岛，星斗分明在一壶。
笑说余杭沽酒去，蔡家重要会麻姑。','',''),('quantangshi-42007','怀旧夜吟寄赵杞','李中','quantangshi','','卷42','长笛声中海月飞，桃花零落满庭墀。
魂销事去无寻处，酒醒孤吟不寐时。
萱草岂能忘积恨，尺书谁与达相思。
悠悠方寸何因解，明日江楼望渺弥。','',''),('quantangshi-42008','宿临江驿','李中','quantangshi','','卷42','候馆寥寥辍棹过，酒醒无奈旅愁何。
雨昏郊郭行人少，苇暗汀洲宿雁多。
干禄已悲凋发鬓，结茅终愧负烟萝。
篇章早晚逢知己，苦志忘形自有魔。','',''),('quantangshi-42009','途中柳','李中','quantangshi','','卷42','翠色晴来近，长亭路去遥。
无人折烟缕，落日拂溪桥。','',''),('quantangshi-42010','隔墙花','李中','quantangshi','','卷42','颜色尤难近，馨香不易通。
朱门金锁隔，空使怨春风。','',''),('quantangshi-42011','广陵寒食夜','李中','quantangshi','','卷42','广陵寒食夜，豪贵足佳期。
紫陌人归后，红楼月上时。
绮罗香未歇，丝竹韵犹迟。
明日踏青兴，输他轻薄儿。','',''),('quantangshi-42012','寄庐山庄隐土','李中','quantangshi','','卷42','烟萝拥竹关，物外自求安。
逼枕溪声近，当檐岳色寒。
药苗应自采，琴调对谁弹。
待了浮名后，依君共挂冠。','',''),('quantangshi-42013','吉水寄阎侍御','李中','quantangshi','','卷42','何处怀君切，令人欲白头。
偶寻花外寺，独立水边楼。
不得论休戚，何因校献酬。
吟余兴难尽，风笛起渔舟。','',''),('quantangshi-42014','送张惟贞少府之江阴','李中','quantangshi','','卷42','相送烟汀畔，酒阑登小舟。
离京梅雨歇，到邑早蝉秋。
俗必期康济，诗谁互唱酬。
晚凉诸吏散，海月入虚楼。','',''),('quantangshi-42015','钟陵禁烟寄从弟','李中','quantangshi','','卷42','落絮飞花日又西，踏青无侣草萋萋。
交亲书断竟不到，忍听黄昏杜宇啼。','',''),('quantangshi-42016','夜泊江渚','李中','quantangshi','','卷42','水乡明月上晴空，汀岛香生杜若风。
不是当年独醒客，且沽村酒待渔翁。','',''),('quantangshi-42017','吉水县依韵酬华松秀才见寄','李中','quantangshi','','卷42','官况萧条在水村，吏归无事好论文。
