诗情冷淡知音少，独喜江臯得见君。','',''),('quantangshi-42018','贻庐山清溪观王尊师','李中','quantangshi','','卷42','霞帔星冠复杖藜，积年修炼住灵溪。
松轩睡觉冷云起，石磴坐来春日西。
采药每寻岩径远，弹琴常到月轮低。
鼎中龙虎功成后，海上三山去不迷。','',''),('quantangshi-42019','王昭君','李中','quantangshi','','卷42','蛾眉翻自累，万里陷穷边。
滴泪胡风起，宽心汉月圆。
飞尘长翳日，白草自连天。
谁贡和亲策，千秋汚简编。','',''),('quantangshi-42020','送姚端先辈归宁','李中','quantangshi','','卷42','知君归觐省，称意涉通津。
解缆汀洲晓，张帆烟水春。
牵吟芳草远，贳酒乱花新。
拜庆庭闱处，蟾枝香满身。','',''),('quantangshi-42021','江村晚秋作','李中','quantangshi','','卷42','高秋水村路，隔岸见人家。
好是经霜叶，红于带露花。
