可惜穿针方有兴，纤纤初月苦难留。','',''),('quantangshi-42029','吉水作尉时酬阎侍御见寄','李中','quantangshi','','卷43','谬佐驱鸡任，常思赋鵩人。
未谐林下约，空感病来身。
鏁径青苔老，铺阶红叶新。
相思不可见，犹喜得书频。','',''),('quantangshi-42030','清溪逢张惟贞秀才','李中','quantangshi','','卷43','洞隐红霞外，房开碧嶂根。
昔年同炼句，几夜共听猨。
考古书千卷，忘忧酒一樽。
如今归建业，雅道喜重论。','',''),('quantangshi-42031','送阎侍御归阙','李中','quantangshi','','卷43','羡君乘紫诏，归路指通津。
