趋朝丹禁晓，耸辔九衢春。
自愧湮沈者，随轩未有因。','',''),('quantangshi-42032','甲子岁罢吉水县过钟陵时暮春维舟江渚谒柴太尉席上作','李中','quantangshi','','卷43','公侯延驻暂踟蹰，况值风光三月初。
乱落杯盘花片小，静笼池阁柳阴疎。
