秋爽鼓琴兴，月清搜句魂。
与君同此志，终待至公论。','',''),('quantangshi-42043','访澄上人','李中','quantangshi','','卷43','寻师来静境，神骨觉清凉。
一饷逢秋雨，相留坐竹堂。
石渠堆败叶，莎砌咽寒螿。
