殷勤留我宿溪上，钓艇归来明月高。','',''),('quantangshi-42068','旅次闻砧','李中','quantangshi','','卷43','砧杵谁家夜捣衣，金风淅淅露微微。
月中独坐不成寐，旧业经年未得归。','',''),('quantangshi-42069','寄杨先生','李中','quantangshi','','卷43','仙翁别后无信，应共烟霞卜隣。
莫把壶中祕诀，轻传尘里游人。
浮生日月自急，上境莺花正春。
安得一招琴酒，与君共泛天津。','',''),('quantangshi-42070','对酒招陈昭用','李中','quantangshi','','卷43','花开叶落堪悲，似水年光暗移。
