幸有一壶清酒，且来闲语希夷。','',''),('quantangshi-42071','旅夜闻笛','李中','quantangshi','','卷43','长笛起谁家，秋凉夜漏赊。
一声来枕上，孤客在天涯。
木末风微动，窗前月渐斜。
暗牵诗思苦，不独落梅花。','',''),('quantangshi-42072','送绍明上人之毗陵','李中','quantangshi','','卷43','忽起毗陵念，飘然不可留。
听蝉离古寺，携锡上扁舟。
月出沙汀冷，风高苇岸秋。
回期端的否，千里路悠悠。','',''),('quantangshi-42073','再到山阳寻故人不遇二首 一','李中','quantangshi','','卷43','维舟登野岸，因访故人居。
