别后或惊如梦觉，音尘难问水茫茫。','',''),('quantangshi-42082','泉','李中','quantangshi','','卷43','潺潺青嶂底，来处一何长。
漱石苔痕滑，侵松鹤梦凉。
泛花穿竹坞，泻月下莲塘。
想得归何处，天涯助渺茫。','',''),('quantangshi-42083','题徐五教池亭','李中','quantangshi','','卷43','多士池塘好，尘中景恐无。
年来养鸥鹭，梦不去江湖。
泉脉通深涧，风声起短芦。
惊鱼跳藻荇，戏蝶上菰蒲。
泛泛容渔艇，闲闲载酒壶。
涨痕山雨过，翠积岸苔铺。
花影沈波底，烟光入座隅。
晓香怜杜若，夜浸爱[蟾]蜍。
步逸心难厌，看吟兴不辜。
凭君命奇笔，为我写成图。','',''),('quantangshi-42084','遥赋义兴潜泉','李中','quantangshi','','卷43','见说灵泉好，潺湲兴莫穷。
谁当秋霁后，独听月明中。
溅石苔花润，随流木叶红。
何当化霖雨，济物显殊功。','',''),('quantangshi-42085','和毗陵尉曹昭用见寄','李中','quantangshi','','卷43','决狱多余暇，冥搜万家空。
卷帘疎雨后，鏁印夕阳中。
还往多名士，编题尚古风。
宦途知此味，能有几人同。','',''),('quantangshi-42086','梅花','李中','quantangshi','','卷43','羣木方憎雪，开花长在先。
流莺与舞蝶，不见许因缘。','',''),('quantangshi-42087','舟次吉水逢蔡文庆秀才','李中','quantangshi','','卷43','别后音尘断，相逢又共吟。
雪霜今日鬓，烟月旧时心。
舣棹夕阳在，听鸿秋色深。
一尊开口笑，不必话升沈。','',''),('quantangshi-42088','新喻县偶寄彭仁正字','李中','quantangshi','','卷43','经年离象魏，孤宦在南荒。
酒醒公斋冷，雨多归梦长。
志难酬国泽，术欠致民康。
吾子应相笑，区区道未光。','',''),('quantangshi-42089','和彭正字喜雪见寄','李中','quantangshi','','卷43','千门忻应瑞，偏称上楼看。
密洒虚窗晓，狂飘大野寒。
园深宜竹树，帘卷洽杯盘。
已作丰年兆，黎民意尽安。','',''),('quantangshi-42090','海上和柴军使清明书事','李中','quantangshi','','卷43','清明时节好烟光，英杰高吟兴味长。
捧日即应还禁卫，当春何惜醉朐阳。
千山过雨难藏翠，百卉临风不藉香。
却是旅人凄屑甚，夜来魂梦到家乡。','',''),('quantangshi-42091','壬申岁承命之任淦阳再过庐山国学感旧寄刘钧明府','李中','quantangshi','','卷43','三十年前共苦辛，囊萤曾寄此烟岑。
读书灯暗嫌云重，搜句石平怜藓深。
各历宦途悲聚散，几看时辈或浮沈。
再来物景还依旧，风冷松高猨狖吟。','',''),('quantangshi-42092','留题胡参卿秀才幽居','李中','quantangshi','','卷43','竹荫亭除藓色浓，道心安逸寂寥中。
扣门时有栖禅客，洒酒多招采药翁。
江近好听菱芡雨，径香偏爱蕙兰风。
我慙名宦犹拘束，脱屣心情未得同。','',''),('quantangshi-42093','放鹭鸶','李中','quantangshi','','卷43','池塘多谢久淹留，长得霜翎放自由。
好去蒹葭深处宿，月明应认旧江秋。','',''),('quantangshi-42094','柳絮','李中','quantangshi','','卷43','年年二月暮，散乱杂飞花。
雨过微风起，狂飘千万家。','',''),('quantangshi-42095','早春','李中','quantangshi','','卷43','一种和风至，千花未放妍。
草心并柳眼，长是被恩先。','',''),('quantangshi-42096','春云','李中','quantangshi','','卷43','阴去为膏泽，晴来媚晓空。
无心亦无滞，舒卷在东风。','',''),('quantangshi-42097','送姚端秀才游毗陵','李中','quantangshi','','卷43','毗陵嘉景太湖边，才子经游称少年。
风弄轻帘沽酒市，月明红袖采莲船。
若耶罨画应相似，越岫吴峰尽接连。
此去高吟须早返，广寒丹桂莫迁延。','',''),('quantangshi-42098','和朐阳载笔鲁裕见寄','李中','quantangshi','','卷43','燕台多事每开颜，相许论交淡薄间。
饮兴共怜芳草岸，吟情同爱夕阳山。
露浓小径蛩声咽，月冷空庭竹影闲。
何事此时攀忆甚，与君俱是别乡关。','',''),('quantangshi-42099','叙吟二首 一','李中','quantangshi','','卷43','往哲搜罗妙入神，隋珠和璧未为珍。
而今所得慙难继，谬向平生着苦辛。','',''),('quantangshi-42100','叙吟二首 二','李中','quantangshi','','卷43','成僻成魔二雅中，每逢知己是亨通。
言之无罪终难厌，欲把风骚继古风。','',''),('quantangshi-42101','贻毗陵正勤禅院奉长老','李中','quantangshi','','卷43','随缘驻瓶锡，心已悟无生。
默坐烟霞散，闲观水月明。
竹深风倍冷，堂迥磬偏清。
愿作传灯者，忘言学净名。','',''),('quantangshi-42102','冬日书怀寄惟真大师','李中','quantangshi','','卷43','自别吾师后，风骚道甚孤。
雪霜侵鬓发，音信隔江湖。
扰扰悲时世，悠悠役梦途。
向公期尽节，多病怕倾壶。
贱迹虽慙滞，幽情忍使辜。
诗成天外句，棊覆夜中图。
落壁灯花碎，飘窗雪片麤。
煮茶烧栗兴，早晚复围炉。','',''),('quantangshi-42103','献中书潘舍人','李中','quantangshi','','卷43','运叶半千数，天钟许国臣。
鹏霄开羽翼，凤阙演丝纶。
顾问当清夜，从容向紫宸。
立言成雅诰，正意叙彝伦。
朴素偕前哲，馨香越搢绅。
褒辞光万代，优旨重千钧。
公退谁堪接，清闲道是邻。
世间身属幻，物外意通津。
吊往兼春梦，文高赋复新。
琴弹三峡水，屏画十洲春。
庭冷铺苔色，池寒浸月轮。
竹风来枕簟，药气上衣巾。
茶谱传溪叟，棊经受羽人。
清虚虽得趣，献替不妨陈。
杞梓呈才后，神仙入侍频。
孤寒皆有赖，中外亦同忻。
有士曾多难，无门得望尘。
忙忙罹险阻，往往耗精神。
寻果巢枝愿，终全负米身。
[遭]逢敦孝治，蹇塞值通津。
最庆清朝禄，还霑白发亲。
甘柔心既遂，虚薄报何因。
远宦联绵历，卑栖夙夜勤。
良时空爱惜，末路每悲辛。
骨立驹犹病，颜凋女尚贫。
而今谐顾遇，尺蠖愿求伸。','',''),('quantangshi-42104','早春左省寓直','徐鉉','quantangshi','','卷43','旭景鸾台上，微云象阙间。
时清政事少，日永直官闲。
远籁飞箫管，零冰响佩环。
终军年二十，默坐叩玄关。','',''),('quantangshi-42105','寒食宿陈公塘上','徐鉉','quantangshi','','卷43','垂杨界官道，茅屋倚高坡。
月下春塘水，风中牧竖歌。
折花闲立久，对酒远情多。
今夜孤亭梦，悠扬奈尔何。','',''),('quantangshi-42106','将去广陵别史员外南斋','徐鉉','quantangshi','','卷43','家声曾与金张辈，官署今居何宋间。
起得高斋临静曲，种成奇树学他山。
鸳鸾终日同醒醉，萝薜常时共往还。
贱子今朝独南去，不堪回首望清闲。','',''),('quantangshi-42107','将过江题白沙馆','徐鉉','quantangshi','','卷43','少长在维扬，依然认故乡。
金陵佳丽地，不道少风光。
稍望吴台远，行登楚塞长。
殷勤语江岭，归梦莫相妨。','',''),('quantangshi-42108','登甘露寺北望','徐鉉','quantangshi','','卷43','京口潮来曲岸平，海门风起浪花生。
人行沙上见日影，舟过江中闻橹声。
芳草远迷杨子渡，宿烟深映广陵城。
游人乡思应如橘，相望须含两地情。','',''),('quantangshi-42109','山路花','徐鉉','quantangshi','','卷43','不共垂杨映绮寮，倚山临路自娇饶。
游人过去知香远，谷鸟飞来见影摇。
半隔烟岚遥隐隐，可堪风雨暮萧萧。
城中春色还如此，几处笙歌按舞腰。','',''),('quantangshi-42110','京口江际弄水','徐鉉','quantangshi','','卷43','退公求静独临川，杨子江南二月天。
百尺翠屏甘露阁，数帆晴日海门船。
波澄濑石寒如玉，草接汀苹绿似烟。
安得乘槎更东去，十洲风外弄潺湲。','',''),('quantangshi-42111','早春旬假独直寄江舍人','徐鉉','quantangshi','','卷43','省署皆归沐，西垣公事稀。
咏诗前砌立，听漏向申归。
远思风醒酒，余寒雨湿衣。
春光已堪探，芝盖共谁飞。','',''),('quantangshi-42112','从驾东幸呈诸公','徐鉉','quantangshi','','卷43','吴公台下旧京城，曾掩衡门过十春。
别后不知新景象，信来空问故交亲。
宦游京口无高兴，习隐钟山限俗尘。
今日喜为华表鹤，况陪鵷鹭免迷津。','',''),('quantangshi-42113','重游木兰亭','徐鉉','quantangshi','','卷43','缭绕长堤带碧浔，昔年游此尚青衿。
兰桡破浪城阴直，玉勒穿花苑树深。
宦路尘埃成久别，仙家风景有谁寻。
那知年长多情后，重凭栏干一独吟。','',''),('quantangshi-42114','赋得彩燕','徐鉉','quantangshi','','卷43','缕彩成飞燕，迎和启蛰时。
翠翘生玉指，绣羽拂文楣。
讵费衔泥力，无劳剪爪期。
化工今在此，翻怪社来迟。','',''),('quantangshi-42115','送魏舍人仲甫为蕲州判官','徐鉉','quantangshi','','卷43','从事蕲春兴自长，蕲人应识紫薇郎。
山资足后抛名路，蒓菜秋来忆故乡。
以道卷舒犹自适，临戎谈笑固无妨。
如闻郡阁吹横笛，时望青溪忆野王。','',''),('quantangshi-42116','题殷舍人宅木芙蓉','徐鉉','quantangshi','','卷43','怜君庭下木芙蓉，袅袅纤枝淡淡红。
晓吐芳心零宿露，晚摇娇影媚清风。
似含情态愁秋雨，暗减馨香借菊丛。
默饮数杯应未称，不知歌管与谁同。','',''),('quantangshi-42117','送史馆高员外使岭南','徐鉉','quantangshi','','卷43','东观时闲暇，还修喻蜀书。
双旌驰县道，百越从轺车。
桂蠹晨餐罢，贪泉访古初。
春江多好景，莫使醉吟疎。','',''),('quantangshi-42118','春日紫岩山期客不至','徐鉉','quantangshi','','卷43','郊外春华好，人家带碧溪。
浅莎藏鸭戏，轻霭隔鸡啼。
掩映红桃谷，夤缘翠柳堤。
王孙竟不至，芳草自萋萋。','',''),('quantangshi-42119','宿蒋帝庙明日游山南诸寺','徐鉉','quantangshi','','卷43','便返城闉尚未甘，更从山北到山南。
花枝似雪春虽半，桂魄如眉日始三。
松盖遮门寒黯黯，柳丝妨路翠𣯶𣯶。
登临莫怪偏留恋，游宦多年事事谙。','',''),('quantangshi-42120','赋得有所思','徐鉉','quantangshi','','卷43','所思何在杳难寻，路远山长水复深。
衰草满庭空伫立，清风吹袂更长吟。
忘情好醉青田酒，寄恨宜调绿绮琴。
落日鲜云偏聚散，可能知我独伤心。','',''),('quantangshi-42121','赠王贞素先生','徐鉉','quantangshi','','卷43','先生尝已佩真形，绀发朱颜骨气清。
道祕未传鸿宝术，院深时听步虚声。
辽东几度悲城郭，吴市终应变姓名。
三十六天皆有籍，他年何处问归程。','',''),('quantangshi-42122','春夜月','徐鉉','quantangshi','','卷43','幽人春望本多情，况是花繁月正明。
竟夕无言亦无寐，绕堦芳草影随行。','',''),('quantangshi-42123','爱敬寺有老僧尝游长安言秦雍间事历历可听因赠此诗兼示同行客','徐鉉','quantangshi','','卷43','白首栖禅者，尝谈灞浐游。
能令过江客，偏起失乡愁。
室倚桃花崦，门临杜若洲。
城中无此景，将子剩淹留。','',''),('quantangshi-42124','游蒋山题辛夷花寄陈奉礼','徐鉉','quantangshi','','卷43','今岁游山已恨迟，山中仍喜见辛夷。
簪缨且免全为累，桃李犹堪别作期。
晴后日高偏照灼，晚来风急渐离披。
山郎不作同行伴，折得何由寄所思。','',''),('quantangshi-42125','和殷舍人萧员外春雪','徐鉉','quantangshi','','卷43','万里春阴乍履端，广庭风起玉尘干。
梅花岭上连天白，蕙草堦前特地寒。
晴去便为经岁别，兴来何惜彻宵看。
此时鸳侣皆闲暇，赠答诗成禁漏残。','',''),('quantangshi-42126','寄蕲州高郎中','徐鉉','quantangshi','','卷43','贾傅栖迟楚泽东，兰皋三度换秋风。
纷纷世事来无尽，黯黯离魂去不通。
直道未能胜社鼠，孤飞徒自叹冥鸿。
知君多少思乡恨，并在山城一笛中。','',''),('quantangshi-42127','寄和州韩舍人','徐鉉','quantangshi','','卷43','急景骎骎度，遥怀处处生。
风头乍寒暖，天色半阴晴。
久别魂空断，终年道不行。
殷勤云上雁，为过历阳城。','',''),('quantangshi-42128','从兄龙武将军没于边戍过旧营宅作','徐鉉','quantangshi','','卷43','前年都尉没边城，帐下何人领旧兵。
徼外瘴烟沉鼓角，山前秋日照铭旌。
笙歌却返乌衣巷，部曲皆还细柳营。
今日园林过寒食，马蹄犹拟入门行。','',''),('quantangshi-42129','景阳台怀古','徐鉉','quantangshi','','卷43','后主忘家不悔，江南异代长春。
今日景阳台上，闲人何用伤神。','',''),('quantangshi-42130','春分日','徐鉉','quantangshi','','卷43','仲春初四日，春色正中分。
绿野徘徊月，晴天断续云。
燕飞犹个个，花落已纷纷。
思妇高楼晚，歌声不可闻。','',''),('quantangshi-42131','寄驾部郎中','徐鉉','quantangshi','','卷43','贱子乖慵性，频为省直牵。
交亲每相见，多在相门前。
君独疎名路，为郎过十年。
炎风久成别，南望思悠然。','',''),('quantangshi-42132','和王庶子寄题兄长建州廉使新亭','徐鉉','quantangshi','','卷43','谢守高斋结构新，一方风景万家情。
羣贤讵减山阴会，远俗初闻正始声。
水槛片云长不去，讼庭纤草转应生。
阿连诗句偏多思，遥想池塘昼梦成。','',''),('quantangshi-42133','谢文靖墓下作','徐鉉','quantangshi','','卷43','越徼稽天讨，周京乱虏尘。
苍生何可奈，江表更无人。
岂惮寻荒垄，犹思认后身。
春风白杨里，独步泪霑巾。','',''),('quantangshi-42134','观人读春秋','徐鉉','quantangshi','','卷43','日觉儒风薄，谁将霸道羞。
乱臣无所惧，何用读春秋。','',''),('quantangshi-42135','秋日雨中与萧赞善访殷舍人于翰林座中作','徐鉉','quantangshi','','卷43','野出西垣步步迟，秋光如水雨如丝。
铜龙楼下逢闲客，红药堦前访旧知。
乱点乍滋承露处，碎声因想滴蓬时。
银台钥入须归去，不惜余欢尽酒巵。','',''),('quantangshi-42136','送和州张员外为江都令','徐鉉','quantangshi','','卷43','经年相望隔重湖，一旦相逢在上都。
塞诏官班聊慰否，埋轮意气尚存无。
由来圣代怜才子，始觉清风激懦夫。
若向西冈寻胜赏，旧题名处为踌躇。','',''),('quantangshi-42137','和明道人宿山寺','徐鉉','quantangshi','','卷43','闻道经行处，山前与水阳。
磐声深小院，灯影逈高房。
落宿依楼角，归云拥殿廊。
羡师闲未得，早起逐班行。','',''),('quantangshi-42138','晚归','徐鉉','quantangshi','','卷43','暑服道情出，烟街薄暮还。
风清飘短袂，马健弄连环。
水静闻归橹，霞明见远山。
过从本无事，从此涉旬间。','',''),('quantangshi-42139','月真歌','徐鉉','quantangshi','','卷43','扬州胜地多丽人，其间丽者名月真。
月真初年十四五，能弹琵琶善歌舞。
风前弱柳一枝春，花里娇莺百般语。
扬州帝京多名贤，其间贤者殷德川。
德川初秉纶闱笔，职近名高常罕出。
花前月下或游从，一见月真如旧识。
闲庭深院资贤宅，宅门严峻无凡客。
垂帘偶坐唯月真，调弄琵琶郎为拍。
殷郎一旦过江去，镜中嬾作孤鸾舞。
朝云暮雨镇相随，石头城下还相遇。
二月三月江南春，满城蒙蒙起香尘。
隔墙试听歌一曲，乃是资贤宅里人。
绿窗绣幌天将晓，残烛依依香褭褭。
离肠却恨苦多情，輭障薰笼空悄悄。
殷郎去冬入翰林，九霄官署转深沉。
人间想望不可见，唯向月真存旧心。
我慙闒茸何为者，长感余光每相假。
陋巷萧条正掩扉，相携访我衡茅下。
我本山人愚且贞，歌筵歌席常无情。
自从一见月真后，至今赢得颠狂名。
殷郎月真听我语，少壮光阴能几许。
良辰美景数追随，莫教长说相思苦。','',''),('quantangshi-42140','走笔送义兴令赵宣辅','徐鉉','quantangshi','','卷43','闻君孤棹泛荆溪，陇首云随别恨飞。
杜牧旧居凭买取，他年藜杖愿同归。','',''),('quantangshi-42141','天阙山绝句','徐鉉','quantangshi','','卷43','散诞爱山客，凄凉怀古心。
寒风天阙晚，尽日倚轩吟。','',''),('quantangshi-42142','除夜','徐鉉','quantangshi','','卷43','寒灯耿耿漏迟迟，送故迎新了不欺。
往事并随残历日，春风宁识旧容仪。
预慙岁酒难先饮，更对乡傩羡小儿。
吟罢明朝赠知己，便须题作去年诗。','',''),('quantangshi-42143','寄钟谟','徐鉉','quantangshi','','卷43','看看潘鬓二毛生，昨日林梢又转莺。
欲对春风忘世虑，敢言尊酒召时英。
假中西阁应无事，筵上南威幸有情。
不得车公终不乐，已教红袖出门迎。','',''),('quantangshi-42144','正初答钟郎中见招','徐鉉','quantangshi','','卷43','高斋迟景雪初晴，风拂乔枝待早莺。
南省郎官名籍籍，东邻妓女字英英。
流年倏忽成陈事，春物依稀有旧情。
新岁相思自过访，不烦虚左远相迎。','',''),('quantangshi-42145','闻雁寄故人','徐鉉','quantangshi','','卷43','久作他乡客，深慙薄宦非。
不知云上雁，何得每年归。
夜静声弥怨，天空影更微。
往年离别泪，今夕重霑衣。','',''),('quantangshi-42146','江舍人宅筵上有妓唱和州韩舍人歌辞因以寄','徐鉉','quantangshi','','卷43','良宵丝竹偶成欢，中有佳人俯翠鬟。
白雪飘颻传乐府，阮郎憔悴在人间。
清风朗月长相忆，佩蕙纫兰早晚还。
深夜酒空筵欲散，向隅惆怅鬓堪斑。','',''),('quantangshi-42147','寒食日作','徐鉉','quantangshi','','卷43','厨冷烟初禁，门闲日更斜。
东风不好事，吹落满庭花。
过社纷纷燕，新晴淡淡霞。
京都盛游观，谁访子云家。','',''),('quantangshi-42148','贺殷游二舍人入翰林江给事拜中丞','徐鉉','quantangshi','','卷43','清晨待漏独徘徊，霄汉悬心不易裁。
阁老深严归翰苑，夕郎威望拜霜台。
青绫对覆蓬壶晚，赤棒前驱道路开。
犹有西垣厅记在，莫忘同草紫泥来。','',''),('quantangshi-42149','欧阳太监雨中视决堤因堕水明日见于省中因戏之','徐鉉','quantangshi','','卷43','闻道张晨盖，徘徊石首东。
浚川非伯禹，落水异三公。
衣湿仍愁雨，冠欹更怯风。
今朝复相见，疑是葛仙翁。','',''),('quantangshi-42150','送吴郎中为宣州推官知泾县','徐鉉','quantangshi','','卷43','征虏亭边月，鸡鸣伴客行。
可怜何水部，今事谢宣城。
风物聊供赏，班资莫系情。
同心不同载，留滞为浮名。','',''),('quantangshi-42151','寄舒州杜员外','徐鉉','quantangshi','','卷43','信到得君书，知君已下车。
粉闱情在否，莲幕兴何如。
人望征贤入，余思从子居。
灊山真隐地，凭为卜茅庐。','',''),('quantangshi-42152','九月十一日寄陈郎中','徐鉉','quantangshi','','卷43','我多吏事君多病，寂绝过从又几旬。
前日龙山烟景好，风前落帽是何人。','',''),('quantangshi-42153','和司门郎中陈彦','徐鉉','quantangshi','','卷43','衡门寂寂逢迎少，不见仙郎向五旬。
莫问龙山前日事，菊花开却为闲人。','',''),('quantangshi-42154','赋得捣衣','徐鉉','quantangshi','','卷43','江上多离别，居人夜捣衣。
拂砧知露滴，促杵恐霜飞。
漏转声频断，愁多力自微。
裁缝依梦见，腰带定应非。','',''),('quantangshi-42155','九月三十夜雨寄故人','徐鉉','quantangshi','','卷43','独听空堦雨，方知愁事悲。
寂寥旬假日，萧飒夜长时。
别念纷纷起，寒更故故迟。
情人如不醉，定是两相思。','',''),('quantangshi-42156','寄抚州钟郎中','徐鉉','quantangshi','','卷43','去载分襟后，寻闻在建安。
封疆正多事，尊俎若为欢。
都护空遗镞，明君欲舞干。
绕朝时不用，非是杀身难。','',''),('quantangshi-42157','送欧阳太监游庐山','徐鉉','quantangshi','','卷43','家家门外庐山路，唯有夫君乞假游。
案牍乍抛公署晚，林泉已近暑天秋。
海潮尽处逢陶石，江月圆时上庾楼。
此去萧然好长往，人间何事不悠悠。','',''),('quantangshi-42158','立秋后一日与朱舍人同直','徐鉉','quantangshi','','卷43','一宿秋风未觉凉，数声宫漏日犹长。
林泉无计消残暑，虚向华池费稻粱。','',''),('quantangshi-42159','赋得霍将军辞第','徐鉉','quantangshi','','卷43','汉将承恩久，图勋肯顾私。
匈奴犹未灭，安用以家为。
郢匠虽闻诏，衡门竟不移。
宁烦张老颂，无待晏婴辞。
甲乙人徒费，亲邻我自持。
悠悠千载下，常作帅臣师。','',''),('quantangshi-42160','和元帅书记萧郎中观习水师','徐鉉','quantangshi','','卷43','元帅楼船出治兵，落星山外火旗明。
千帆日助江陵势，万里风驰下濑声。
杀气晓严波上鷁，凯歌遥骇海边鲸。
仲宣一作从军咏，回顾儒衣自不平。','',''),('quantangshi-42161','秋日卢龙村舍','徐鉉','quantangshi','','卷43','置却人间事，闲从野老游。
树声村店晚，草色古城秋。
独鸟飞天外，闲云度陇头。
姓名君莫问，山木与虚舟。','',''),('quantangshi-42162','和萧郎中小雪日作','徐鉉','quantangshi','','卷43','征西府里日西斜，独试新炉自煮茶。
篱菊尽来低覆水，塞鸿飞去远连霞。
寂寥小雪闲中过，斑驳轻霜鬓上加。
算得流年无奈处，莫将诗句祝苍华。','',''),('quantangshi-42163','中书相公溪亭闲宴依韵','徐鉉','quantangshi','','卷43','雨霁秋光晚，亭虚野兴回。
沙鸥掠岸去，溪水上堦来。
客傲风欹帻，筵香菊在杯。
东山长许醉，何事忆天台。','',''),('quantangshi-42164','寄饶州王郎中效李白体','徐鉉','quantangshi','','卷43','珍重王光嗣，交情尚在不。
芜城连宅住，楚塞并车游。
别后官三改，年来岁六周。
银钩无一字，何以缓离愁。','',''),('quantangshi-42165','寄歙州吕判官','徐鉉','quantangshi','','卷43','任公郡占好山川，溪水萦回路屈盘。
南国自来推胜境，故人此地作郎官。
风光适意须留恋，禄秩资贫且喜欢。
莫忆班行重回首，是非多处是长安。','',''),('quantangshi-42166','宣威苗将军贬官后重经故宅','徐鉉','quantangshi','','卷43','蒋山南望近西坊，亭馆依然锁院墙。
天子未尝过细柳，将军寻已戍炖煌。
敧倾怪石山无色，零落圆荷水不香。
为将为儒皆寂寞，门前愁杀马中郎。','',''),('quantangshi-42167','附池州薛郎中书因寄歙州张员外','徐鉉','quantangshi','','卷43','新安从事旧台郎，直气多才不可忘。
一旦江山驰别梦，几年簪绂共周行。
岐分出处何方是，情共穷通此义长。
因附邻州寄消息，接舆今日信为狂。','',''),('quantangshi-42168','寄江都路员外','徐鉉','quantangshi','','卷43','吾兄失意在东都，闻说襟怀任所如。
已纵乖慵为傲吏，有何关键制豪胥。
县斋晓闭多移病，南亩秋荒忆遂初。
知道故人相忆否，嵇康不得嬾修书。','',''),('quantangshi-42169','张员外好茅山风景求为句容令作此送','徐鉉','quantangshi','','卷43','句曲山前县，依依数舍程。
还同适勾漏，非是厌承明。
柳谷供诗景，华阳契道情。
金门容傲吏，官满且还城。','',''),('quantangshi-42170','送应之道人归江西','徐鉉','quantangshi','','卷43','曾骑竹马傍洪厓，二十余年变物华。
客梦等闲过驿阁，归帆遥羡指龙沙。
名垂小篆矜垂露，诗作吴吟对绮霞。
岁暮定知回未得，信来凭为寄梅花。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-42171','送元帅书记高郎中出为婺源建威军使','徐鉉','quantangshi','','卷43','寒风萧瑟楚江南，记室戎装挂锦帆。
倚马未曾妨笑傲，斩牲先要厉威严。
危言昔日尝无隐，壮节今来信不凡。
惟有杯盘思上国，酒醪甜淡菜蔬甘。','',''),('quantangshi-42172','游方山宿李道士房','徐鉉','quantangshi','','卷43','从来未面李先生，借我西窗卧月明。
二十三家同愿识，素骡何日暂还城。','',''),('quantangshi-42173','题画石山','徐鉉','quantangshi','','卷43','彼美巉岩石，谁施黼藻功。
回岩明照地，绝壁烂临空。
锦段鲜须濯，罗屏展易穷。
不因秋藓绿，非假晚霞红。
羽客藏书洞，樵人取箭风。
灵踪理难问，仙路去何通。
返驾归尘里，留情向此中。
回瞻画图畔，遥羡面山翁。','',''),('quantangshi-42174','临石步港','徐鉉','quantangshi','','卷43','崎岸堕萦带，微风起细涟。
绿阴三月后，倒影乱峰前。
吹浪游鳞小，黏苔碎石圆。
会将腰下组，换取钓鱼船。','',''),('quantangshi-42175','病题二首 一','徐鉉','quantangshi','','卷43','性灵慵嬾百无能，唯被朝参遣夙兴。
圣主优容恩未答，丹经疎阔病相陵。
脾伤对客偏愁酒，眼暗看书每愧灯。
进与时乖不知退，可怜身计谩腾腾。','',''),('quantangshi-42176','病题二首 二','徐鉉','quantangshi','','卷43','人间多事本难论，况是人间嬾慢人。
不解养生何怪病，已能知命敢辞贫。
向空咄咄烦书字，举世滔滔莫问津。
金马门前君识否，东方曼倩是前身。','',''),('quantangshi-42177','寄江州萧给事','徐鉉','quantangshi','','卷43','夕郎忧国不忧身，今向天涯作逐臣。
魂梦暗驰龙阙曙，啸吟闲绕虎溪春。
朝车载酒过山寺，谏纸题诗寄野人。
惆怅懦夫何足道，自离羣后已同尘。','',''),('quantangshi-42178','和江州江中丞见寄','徐鉉','quantangshi','','卷43','贾傅南迁久，江关道路遥。
北来空见雁，西去不如潮。
鼠穴依城社，鸿飞在泬寥。
高低各有处，不拟更相招。','',''),('quantangshi-42179','和钟郎中送朱先辈还京垂寄','徐鉉','quantangshi','','卷43','分司洗马无人问，辞客殷勤辍棹歌。
苍藓满庭行径小，高梧临槛雨声多。
春愁尽付千杯酒，乡思遥闻一曲歌。
且共胜游消永日，西冈风物近如何。','',''),('quantangshi-42180','送郝郎中为浙西判官','徐鉉','quantangshi','','卷43','大藩从事本优贤，幕府仍当北固前。
花绕楼台山倚郭，寺临江海水连天。
恐君到即忘归日，忆我游曾历二年。
若许他时作闲伴，殷勤为买钓鱼船。','',''),('quantangshi-42181','翰林游舍人清明日入院中途见过余明日亦入西省上直因寄游君','徐鉉','quantangshi','','卷43','榆柳开新焰，梨花发故枝。
辎軿隘城市，圭组坐曹司。
独对芝泥检，遥怜白马儿。
禁林还视草，气味两相知。','',''),('quantangshi-42182','陪王庶子游后湖涵虚阁','徐鉉','quantangshi','','卷43','悬圃清虚乍过秋，看山寻水上兹楼。
轻鸥的的飞难没，红叶纷纷晚更稠。
风卷微云分远岫，浪摇晴日照中洲。
跻攀况有承华客，如在南皮奉胜游。','',''),('quantangshi-42183','柳枝辞十二首 一','徐鉉','quantangshi','','卷43','把酒凭君唱柳枝，也从丝管递相随。
逢春只合朝朝醉，记取秋风落叶时。','',''),('quantangshi-42184','柳枝辞十二首 二','徐鉉','quantangshi','','卷43','南园日暮起春风，吹散杨花雪满空。
不惜杨花飞也得，愁君老尽脸边红。','',''),('quantangshi-42185','柳枝辞十二首 三','徐鉉','quantangshi','','卷43','陌上朱门柳映花，帘钩半卷绿阴斜。
凭郎暂驻青骢马，此是钱塘小小家。','',''),('quantangshi-42186','柳枝辞十二首 四','徐鉉','quantangshi','','卷43','夹岸朱栏柳映楼，绿波平幔带花流。
歌声不出长条密，忽地风回见彩舟。','',''),('quantangshi-42187','柳枝辞十二首 五','徐鉉','quantangshi','','卷43','老大逢春总恨春，绿杨阴里最愁人。
旧游一别无因见，嫩叶如眉处处新。','',''),('quantangshi-42188','柳枝辞十二首 六','徐鉉','quantangshi','','卷43','蒙蒙堤畔柳含烟，疑是阳和二月天。
醉里不知时节改，漫随儿女打秋千。','',''),('quantangshi-42189','柳枝辞十二首 七','徐鉉','quantangshi','','卷43','水阁春来乍减寒，晓妆初罢倚栏干。
长条乱拂春波动，不许佳人照影看。','',''),('quantangshi-42190','柳枝辞十二首 八','徐鉉','quantangshi','','卷43','柳岸烟昏醉里归，不知深处有芳菲。
重来已见花飘尽，唯有黄莺啭树飞。','',''),('quantangshi-42191','柳枝辞十二首 九','徐鉉','quantangshi','','卷43','此去仙源不是遥，垂杨深处有朱桥。
共君同过朱桥去，索映垂杨听洞箫。','',''),('quantangshi-42192','柳枝辞十二首 十','徐鉉','quantangshi','','卷43','暂别扬州十度春，不知光景属何人。
一帆归客千条柳，肠断东风杨子津。','',''),('quantangshi-42193','柳枝辞十二首 十一','徐鉉','quantangshi','','卷43','仙乐春来按舞腰，清声偏似傍娇饶。
应缘莺舌多情赖，长向双成说翠条。','',''),('quantangshi-42194','柳枝辞十二首 十二','徐鉉','quantangshi','','卷43','凤笙临槛不能吹，舞袖当筵亦自疑。
唯有美人多意绪，解依芳态画双眉。','',''),('quantangshi-42195','贬官泰州出城作','徐鉉','quantangshi','','卷43','浮名浮利信悠悠，四海干戈痛主忧。
三谏不从为逐客，一身无累似虚舟。
满朝权贵皆曾忤，绕郭林泉已徧游。
惟有恋恩终不改，半程犹自望城楼。','',''),('quantangshi-42196','过江','徐鉉','quantangshi','','卷43','别路知何极，离肠有所思。
登舻望城远，摇樐过江迟。
断岸烟中失，长天水际垂。
此心非橘柚，不为两乡移。','',''),('quantangshi-42197','经东都太子桥','徐鉉','quantangshi','','卷43','纶闱放逐知何道，桂苑风流且暂归。
莫问升迁桥上客，身谋疎拙旧心违。','',''),('quantangshi-42198','赠维扬故人','徐鉉','quantangshi','','卷43','东京少长认维桑，书劒谁教入帝乡。
一事无成空放逐，故人相见重凄凉。
楼台寂寞官河晚，人物稀疎驿路长。
莫怪临风惆怅久，十年春色忆维扬。','',''),('quantangshi-42199','泰州道中却寄东京故人','徐鉉','quantangshi','','卷43','风紧雨凄凄，川回岸渐低。
吴州林外近，隋苑雾中迷。
聚散纷如此，悲欢岂易齐。
料君残酒醒，还听子规啼。','',''),('quantangshi-42200','得浙西郝判官书未及报闻燕王移镇京口因寄此诗问方判官田书记消息','徐鉉','quantangshi','','卷43','秋风海上久离居，曾得刘公一纸书。
淡水心情长若此，银钩踪迹更无如。
尝忧座侧飞鸮鸟，未暇江中觅鲤鱼。
今日京吴建朱邸，问君谁共曳长裾。','',''),('quantangshi-42201','赠陶使君求梨','徐鉉','quantangshi','','卷43','昨宵宴罢醉如泥，惟忆张公大谷梨。
白玉花繁曾缀处，黄金色嫩乍成时。
冷侵肺腑醒偏早，香惹衣襟歇倍迟。
今旦中山方酒渴，唯应此物最相宜。','',''),('quantangshi-42202','陈觉放还至泰州以诗见寄作此答之','徐鉉','quantangshi','','卷43','朱云曾为汉家忧，不怕交亲作世仇。
壮气未平空咄咄，狂言无騐信悠悠。
今朝我作伤弓鸟，却羡君为不系舟。
劳寄新诗平宿憾，此生心气贯清秋。','',''),('quantangshi-42203','王三十七自京垂访作此送之','徐鉉','quantangshi','','卷43','失乡迁客在天涯，门掩苔垣向水斜。
只就鳞鸿求远信，敢言车马访贫家。
烟生柳岸将垂缕，雪压梅园半是花。
惆怅明朝尊酒散，梦魂相送到京华。','',''),('quantangshi-42204','陶使君挽歌二首 一','徐鉉','quantangshi','','卷43','太守今何在，行春去不归。
筵空收管吹，郊逈俨骖騑。
营外星才落，园中露已稀。
伤心梁上燕，犹解向人飞。','',''),('quantangshi-42205','陶使君挽歌二首 二','徐鉉','quantangshi','','卷43','始忆花前宴，笙歌醉夕阳。
那堪城外送，哀挽逐归艎。
铃阁朝犹闭，风亭日已荒。
唯余迁客泪，霑洒后池傍。','',''),('quantangshi-42206','雪中作','徐鉉','quantangshi','','卷43','赋分多情客，经年去国心。
疎钟寒郭晚，密雪水亭深。
影逈鸿投渚，声愁雀噪林。
他乡一尊酒，独坐不成斟。','',''),('quantangshi-42207','赋得风光草际浮','徐鉉','quantangshi','','卷43','宿露依芳草，春郊古陌旁。
风轻不尽偃，日早未曦阳。
耿耿依平远，离离入望长。
映空无定彩，飘迳有余光。
颭若荷珠乱，纷如爝火扬。
诗人多感物，凝思绕池塘。','',''),('quantangshi-42208','寒食成判官垂访因赠','徐鉉','quantangshi','','卷43','常年寒食在京华，今岁清明在海涯。
远巷蹋歌深夜月，隔墙吹管数枝花。
鸳鸾得路音尘阔，鸿雁分飞道里赊。
不是多情成二十，断无人解访贫家。','',''),('quantangshi-42209','送客至城西望图山因寄浙西府中','徐鉉','quantangshi','','卷43','牧叟邹生笑语同，莫嗟江上听秋风。
君看逐客思乡处，犹在图山更向东。','',''),('quantangshi-42210','送写真成处士入京','徐鉉','quantangshi','','卷43','传神踪迹本来高，泽畔形容愧彩毫。
京邑功臣多伫望，凌烟阁上莫辞劳。','',''),('quantangshi-42211','九日雨中','徐鉉','quantangshi','','卷43','茱萸房重雨霏微，去国逢秋此恨稀。
目极暂登台上望，心遥长向梦中归。
荃蘪路远愁霜早，兄弟乡遥羡雁飞。
唯有多情一枝菊，满杯颜色自依依。','',''),('quantangshi-42212','寄外甥苗武仲','徐鉉','quantangshi','','卷43','放逐今来涨海边，亲情多在凤台前。
且将聚散为闲事，须信华枯是偶然。
蝉噪疎林村倚郭，鸟飞残照水连天。
此中唯欠韩康伯，共对秋风咏数篇。','',''),('quantangshi-42213','寄从兄宪兼示二弟','徐鉉','quantangshi','','卷43','别路吴将楚，离忧弟与兄。
断云惊晚吹，秋色满孤城。
信远鸿初下，乡遥月共明。
一枝栖未稳，回首望三京。','',''),('quantangshi-42214','附书与钟郎中因寄京妓越宾','徐鉉','quantangshi','','卷43','暮春桥下手封书，寄向江南问越姑。
不道诸郎少欢笑，经年相别忆侬无。','',''),('quantangshi-42215','代钟答','徐鉉','quantangshi','','卷43','一幅轻绡寄海滨，越姑长感昔时恩。
欲知别后情多少，点点凭君看泪痕。','',''),('quantangshi-42216','亚元舍人不替深知猥贻佳作三篇清绝不敢轻酬因为长歌聊以为报未竟复得子乔校书示问故兼寄陈君庶资一笑耳','徐鉉','quantangshi','','卷43','海陵城里春正月，海畔朝阳照残雪。
城中有客独登楼，遥望天边白银阙。
白银阙下何英英，雕鞍绣毂趋承明。
阊门晓辟旌旗影，玉墀风细佩环声。
此处追飞皆俊彦，当年何事容疵贱。
怀铅昼坐紫微宫，焚香夜直明光殿。
王言简静官司闲，朋好殷勤多往还。
新亭风景如东洛，邙岭林泉似北山。
光阴暗度杯盂里，职业未妨谈笑间。
有时邀宾复携妓，造门不问都非是。
酣歌呌笑惊四邻，赋笔纵横动千字。
任他银箭转更筹，不怕金吾司夜吏。
可怜诸贵贤且才，时情物望两无猜。
伊余独禀狂狷性，褊量多言仍薄命。
吞舟可漏岂无恩，负乘自贻非不幸。
一朝削迹为迁客，旦暮青云千里隔。
离鸿别雁各分飞，折柳攀花两无色。
卢龙渡口问迷津，瓜步山前送暮春。
白沙江上曾行路，青林花落何纷纷。
汉皇昔幸回中道，极目牛羊卧芳草。
旧宅重游尽隟荒，故人相见多衰老。
禅智寺，山光桥，风瑟瑟兮雨萧萧。
行杯已醒残梦断，征途未极离魂消。
海陵郡中陶太守，相逢本是随行旧。
乍申拜起已开眉，却问辛勤还执手。
精庐水榭最清幽，一税征车聊驻留。
闭门思过谢来客，知恩省分宽离忧。
郡斋胜境有后池，山亭菌阁互参差。
有时虚左来相召，举白飞觞任所为。
多才太守能挝鼓，醉送金船间歌舞。
酒酣耳热眼生花，暂似京华欢会处。
归来旅馆还端居，清风朗月夜窗虚。
骎骎流景岁云暮，天涯望断故人书。
春来凭槛方叹息，仰头忽见南来翼。
足系红笺堕我前，引颈长鸣如有言。
开缄试读相思字，乃是多情乔亚元。
短韵三篇皆丽绝，小梅寄意情偏切。
金兰投分一何坚，银钩置袖终难灭。
醉后狂言何足奇，感君知己不相遗。
长卿曾作美人赋，玄成今有责躬诗。
报章欲托还京信，笔拙纸穷情未尽。
珍重芸香陈子乔，亦解贻书远相问。
宁须买药疗羁愁，只恨无书消鄙吝。
游处当时靡不同，欢娱今日两成空。
天子尚应怜贾谊，时人未要嘲杨雄。
曲终笔阁缄封已，翩翩驿骑行尘起。
寄向中朝谢故人，为说相思意如此。','',''),('quantangshi-42217','送蒯司录归京','徐鉉','quantangshi','','卷43','早年闻有蒯先生，二十余年道不行。
抵掌曾论天下事，折腰犹悟俗人情。
老还上国欢娱少，贫聚归资结束轻。
迁客临流倍惆怅，冷风黄叶满山城。','',''),('quantangshi-42218','闻查建州陷贼寄钟郎中','徐鉉','quantangshi','','卷43','闻道将军轻壮图，螺江城下委犀渠。
旌旗零落沉荒服，簪履萧条返故居。
皓首应全苏武节，故人谁得李陵书。
自怜放逐无长策，空使卢谌泪满裾。','',''),('quantangshi-42219','还过东都留守周公筵上赠座客','徐鉉','quantangshi','','卷43','贾生三载在长沙，故友相思道路赊。
已分终年甘寂寞，岂知今日还京华。
麟符上相恩偏厚，隋苑留欢日欲斜。
明旦江头倍惆怅，远山芳草映残霞。','',''),('quantangshi-42220','送杨郎中唐员外奉使湖南','徐鉉','quantangshi','','卷43','江边微雨柳条新，握节含香二使臣。
两绶对悬云梦日，方舟齐泛洞庭春。
今朝草木逢新律，昨日山川满战尘。
同是多情怀古客，不妨为赋吊灵均。','',''),('quantangshi-42221','表弟包颍见寄','徐鉉','quantangshi','','卷43','常思帝里奉交亲，别后光阴屈指频。
兰佩却归纶阁下，荆枝犹寄楚江滨。
十程山水劳幽梦，满院烟花醉别人。
料得此生强健在，会须重赏昔年春。','',''),('quantangshi-42222','寄萧给事','徐鉉','quantangshi','','卷43','危言危行古时人，归向西山卧白云。
买宅尚寻徐处士，餐霞终访许真君。
容颜别后应如故，诗咏年来更不闻。
今日城中春又至，落梅愁绪共纷纷。','',''),('quantangshi-42223','赋石奉送钟德林少尹员外','徐鉉','quantangshi','','卷43','我爱他山石，中含绝代珍。
烟披寒落落，沙浅静磷磷。
翠色辞文陛，清声出泗滨。
扁舟载归去，知是泛槎人。','',''),('quantangshi-42224','赠泰州掾令狐克己','徐鉉','quantangshi','','卷43','念子才多命且奇，乱中抛掷少年时。
深藏七泽衣如雪，却见中朝鬓似丝。
旧德在人终远大，扁舟为吏莫推辞。
孤芳自爱凌霜处，咏取文公白菊诗。','',''),('quantangshi-42225','送荻栽与秀才朱观','徐鉉','quantangshi','','卷43','羡子清吟处，茅斋面碧流。
解憎莲艳俗，唯欠荻花幽。
鹭立低枝晚，风惊折叶秋。
赠君须种取，不必树忘忧。','',''),('quantangshi-42226','使浙西先寄献燕王侍中','徐鉉','quantangshi','','卷43','京江风静喜乘流，极目遥瞻万岁楼。
喜气茏葱甘露晚，水烟波淡海门秋。
五年不见鸾台长，明日将陪兔苑游。
欲问平台门下吏，相君还许吐茵不。','',''),('quantangshi-42227','常州驿中喜雨','徐鉉','quantangshi','','卷43','飒飒旱天雨，凉风一夕回。
远寻南亩去，细入驿亭来。
蓑唱牛初牧，渔歌棹正开。
盈庭顿无事，归思酌金罍。','',''),('quantangshi-42228','驿中七夕','徐鉉','quantangshi','','卷43','七夕雨初霁，行人正忆家。
江天望河汉，水馆折莲花。
独坐凉何甚，微吟月易斜。
今年不乞巧，钝拙转堪嗟。','',''),('quantangshi-42229','赠浙西顾推官','徐鉉','quantangshi','','卷43','盛府宾寮八十余，闭门高卧兴无如。
梁王苑里相逢早，润浦城中得信疎。
狼藉杯盘重会面，风流才调一如初。
愿君百岁犹强健，他日相寻隐士庐。','',''),('quantangshi-42230','赠浙西妓亚仙','徐鉉','quantangshi','','卷43','翠黛嚬如怨，朱颜醉更春。
占将南国貌，恼杀别家人。
粉汗沾巡盏，花钿逐舞茵。
明朝绮窗下，离恨两殷勤。','',''),('quantangshi-42231','回至瓜洲献侍中','徐鉉','quantangshi','','卷43','紫微垣里旧宾从，来向吴门谒府公。
奉使谬持严助节，登门初识鲁王宫。
笙歌隐隐违离后，烟水茫茫怅望中。
日暮瓜洲江北岸，两行情泪滴西风。','',''),('quantangshi-42232','邵伯埭下寄高邮陈郎中','徐鉉','quantangshi','','卷43','故人相别动经年，候馆相逢倍惨然。
顾我饮冰难辍棹，感君扶病为开筵。
河湾水浅翘秋鹭，柳岸风微噪暮蝉。
欲识酒醒魂断处，谢公祠畔客亭前。','',''),('quantangshi-42233','谪居舒州累得韩高二舍人书作此寄之','徐鉉','quantangshi','','卷43','三峰烟霭碧临溪，中有骚人理钓丝。
会友少于分袂日，谪居多却在朝时。
丹心历历吾终信，俗虑悠悠尔不知。
珍重韩君与高子，殷勤书札寄相思。','',''),('quantangshi-42234','和张先辈见寄二首 一','徐鉉','quantangshi','','卷43','去国离羣掷岁华，病容憔悴愧丹砂。
溪连舍下衣长润，山带城边日易斜。
几处垂钩依野岸，有时披褐到邻家。
故人书札频相慰，谁道西京道路赊。','',''),('quantangshi-42235','和张先辈见寄二首 二','徐鉉','quantangshi','','卷43','清时沦放在山州，邛竹纱巾处处游。
野日苍茫悲鵩舍，水风阴湿弊貂裘。
鸡鸣候旦宁辞晦，松节凌霜几换秋。
两首新诗千里道，感君情分独知丘。','',''),('quantangshi-42236','印秀才至舒州见寻别后寄诗依韵和','徐鉉','quantangshi','','卷43','羁游白社身虽屈，高步辞场道不卑。
投分共为知我者，相寻多愧谪居时。
离怀耿耿年来梦，厚意勤勤别后诗。
今日溪边正相忆，雪晴山秀柳丝垂。','',''),('quantangshi-42237','行园树','徐鉉','quantangshi','','卷43','松节凌霜久，蓬根逐吹频。
羣生各有性，桃李但争春。','',''),('quantangshi-42238','题雷公井','徐鉉','quantangshi','','卷43','揜霭愚公谷，萧寥羽客家。
俗人知处所，应为有桃花。','',''),('quantangshi-42239','送彭秀才','徐鉉','quantangshi','','卷43','贾生去国已三年，短褐闲行皖水边。
尽日野云生舍下，有时京信到门前。
无人与和投湘赋，愧子来浮访戴船。
满袖新诗好回去，莫随骚客醉林泉。','',''),('quantangshi-42240','移饶州别周使君','徐鉉','quantangshi','','卷43','正怜东道感贤侯，何幸南冠脱楚囚。
睆伯台前收别宴，乔公亭下舣行舟。
四年去国身将老，百郡征兵主尚忧。
更向鄱阳湖上去，青衫憔悴泪交流。','',''),('quantangshi-42241','避难东归依韵和黄秀才见寄','徐鉉','quantangshi','','卷43','戚戚逢人问所之，东流相送向京畿。
自甘逐客纫兰佩，不料平民着战衣。
树带荒村春冷落，江澄霁色雾霏微。
时危道丧无才术，空手徘徊不忍归。','',''),('quantangshi-42242','酬郭先辈','徐鉉','quantangshi','','卷43','太原郭夫子，行高文炳蔚。
弱龄负世誉，一举游月窟。
仙籍第三人，时人故称屈。
昔余吏西省，倾盖名籍籍。
及我窜羣舒，向风心郁郁。
归来暮江上，云雾一披拂。
雷雨不下施，犹作池中物。
念君介然气，感时思奋发。
示我数篇文，与古争驰突。
彩褥粲英华，理深刮肌骨。
古诗尤精奥，史论皆宏拔。
举此措诸民，何忧民不活。
吁嗟吾道薄，与世长迂阔。
顾我徒有心，数奇身正绌。
论兵属少年，经国须儒术。
夫子无自轻，苍生正愁疾。','',''),('quantangshi-42243','和集贤钟郎中','徐鉉','quantangshi','','卷43','石渠册府神仙署，当用明朝第一人。
腰下别悬新印绶，座中皆是故交亲。
龙池树色供清景，浴殿香风接近邻。
从此翻飞应更远，徧寻三十六天春。','',''),('quantangshi-42244','送刘山阳','徐鉉','quantangshi','','卷43','旧族知名士，朱衣宰楚城。
所嗟吾道薄，岂是主恩轻。
战鼓何时息，儒冠独自行。
此心多感激，相送若为情。','',''),('quantangshi-42245','题伏龟山北隅','徐鉉','quantangshi','','卷43','兹山信岑寂，阴崖积苍翠。
水石何必多，宛有千岩意。
孰知近人境，旦暮含佳气。
池影摇轻风，林光澹新霁。
支颐藉芳草，自足忘世事。
未得归去来，聊为宴居地。','',''),('quantangshi-42246','送黄梅江明府','徐鉉','quantangshi','','卷43','封疆多难正经纶，台阁如何不用君。
江上又劳为小邑，箧中徒自有雄文。
书生胆气人谁信，远俗歌谣主不闻。
一首新诗无限意，再三吟味向秋云。','',''),('quantangshi-42247','咏梅子真送郭先辈','徐鉉','quantangshi','','卷43','忠臣本爱君，仁人本爱民。
宁知贵与贱，岂计名与身。
梅生为一尉，献疏来君门。
君门深万里，金虎重千钧。
向永且不用，况复论子真。
拂衣遂长往，高节邈无邻。
至今仙籍中，谓之梅真人。
郭生负逸气，百代继遗尘。
进退生自知，得丧吾不陈。
斯民苟有幸，期子一朝伸。','',''),('quantangshi-42248','和萧郎中午日见寄','徐鉉','quantangshi','','卷43','细雨轻风采药时，褰帘隐几更何为。
岂知泽畔纫兰客，来赴城中角黍期。
多罪静思如锉蘖，赦书才听似含饴。
谢公制胜常闲暇，愿接西州敌手棊。','',''),('quantangshi-42249','送黄秀才姑孰辟命','徐鉉','quantangshi','','卷43','世乱离情苦，家贫色养难。
水云孤棹去，风雨暮春寒。
幕府才方急，骚人泪未干。
何时王道泰，万里看鹏抟。','',''),('quantangshi-42250','送王四十五归东都','徐鉉','quantangshi','','卷43','海内兵方起，离筵泪易垂。
怜君负米去，惜此落花时。
想忆看来信，相宽指后期。
殷勤手中柳，此是向南枝。','',''),('quantangshi-42251','和太常萧少卿近郊马上偶吟','徐鉉','quantangshi','','卷43','田园经雨绿分畦，飞盖闲行九里堤。
拂袖清风尘不起，满川芳草路如迷。
林开始觉晴天逈，潮上初惊浦岸齐。
怪得仙郎诗句好，断霞残照远山西。','',''),('quantangshi-42252','又和太常萧少卿近郊马上偶吟','徐鉉','quantangshi','','卷43','抱瓮何人灌药畦，金衔为尔驻平堤。
村桥野店景无限，绿水晴天思欲迷。
横笛乍随轻吹断，归帆疑与远山齐。
凤城回望真堪画，万户千门蒋峤西。','',''),('quantangshi-42253','抛球乐辞二首 一','徐鉉','quantangshi','','卷43','歌舞送飞球，今觥碧玉筹。
管弦桃李月，帘幕凤凰楼。
一笑千场醉，浮生任白头。','',''),('quantangshi-42254','抛球乐辞二首 二','徐鉉','quantangshi','','卷43','灼灼传花枝，纷纷度画旗。
不知红烛下，照见彩球飞。
借势因期尅，巫山暮雨归。','',''),('quantangshi-42255','离歌辞五首 一','徐鉉','quantangshi','','卷43','莫折红芳树，但知尽意看。
狂风幸无意，那忍折教残。','',''),('quantangshi-42256','离歌辞五首 二','徐鉉','quantangshi','','卷43','朝日城南路，旌旗照绿芜。
使君何处去，桑下觅罗敷。','',''),('quantangshi-42257','离歌辞五首 三','徐鉉','quantangshi','','卷43','事与年俱往，情将分共深。
莫惊容鬓改，只是旧时心。','',''),('quantangshi-42258','离歌辞五首 四','徐鉉','quantangshi','','卷43','暂别劳相送，佳期愿莫违。
朱颜不须老，留取待郎归。','',''),('quantangshi-42259','离歌辞五首 五','徐鉉','quantangshi','','卷43','拂匣收珠佩，回灯拭薄妆。
莫嫌春夜短，匹似楚襄王。','',''),('quantangshi-42260','梦游三首 一','徐鉉','quantangshi','','卷43','魂梦悠扬不奈何，夜来还在故人家。
香蒙蜡烛时时暗，户映屏风故故斜。
檀的慢调银字管，云鬟低缀折枝花。
天明又作人间别，洞口春深道路赊。','',''),('quantangshi-42261','梦游三首 二','徐鉉','quantangshi','','卷43','绣幌银屏杳霭间，若非魂梦到应难。
窗前人静偏宜夜，户内春浓不识寒。
蘸甲遰觞纤似玉，含词忍笑腻于檀。
锦书若要知名字，满县花开不姓潘。','',''),('quantangshi-42262','梦游三首 三','徐鉉','quantangshi','','卷43','南国佳人字玉儿，芙蓉双脸远山眉。
仙郎有约长相忆，阿母何猜不得知。
梦里行云还倏忽，暗中携手乍疑迟。
因思别后闲窗下，织得回文几首诗。','',''),('quantangshi-42263','和萧少卿见庆新居','徐鉉','quantangshi','','卷43','湘浦怀沙已不疑，京城赐第岂前期。
鼓声到晚知坊远，山色来多与静宜。
簪屦尚应怜故物，稻粱空自愧华池。
新诗问我偏饶思，还念鹪鹩得一枝。','',''),('quantangshi-42264','又和萧少卿见庆新居','徐鉉','quantangshi','','卷43','惊蓬偶驻知多幸，断雁重联惬素期。
当户小山如旧识，上墙幽藓最相宜。
清风不去因栽竹，隙地无多也凿池。
更喜良邻有嘉树，绿阴分得近南枝。','',''),('quantangshi-42265','送勋道人之建安','徐鉉','quantangshi','','卷43','下国兵方起，君家义独闻。
若为轻世利，归去卧溪云。
挂席冲岚翠，携筇破藓纹。
离情似霜叶，江上正纷纷。','',''),('quantangshi-42266','送许郎中歙州判官兼黟县','徐鉉','quantangshi','','卷43','尝闻黟县似桃源，况是优游冠玳筵。
遗爱非遥应卧理，祖风犹在好寻仙。
朝衣旧识熏香史，禄米初营种秫田。
大抵宦游须自适，莫辞离别二三年。','',''),('quantangshi-42267','送彭秀才南游','徐鉉','quantangshi','','卷43','问君孤棹去何之，玉笥春风楚水西。
山上断云分翠霭，林间晴云入澄溪。
琴心酒趣神相会，道士仙童手共携。
他日时清更随计，莫如刘阮洞中迷。','',''),('quantangshi-42268','和明上人除夜见寄','徐鉉','quantangshi','','卷43','酌酒围炉久，愁襟默自增。
长年逢岁暮，多病见兵兴。
夜色开庭燎，寒威入砚冰。
汤师无别念，吟坐一灯凝。','',''),('quantangshi-42269','正初和鄂州边郎中见寄','徐鉉','quantangshi','','卷43','潦倒含香客，凄凉赋鵩人。
未能全卷舌，终拟学垂纶。
故友暌离久，音书问讯频。
相思俱老大，又见一年新。','',''),('quantangshi-42270','送刘司直出宰','徐鉉','quantangshi','','卷43','之子有雄文，风标秀不羣。
低飞从墨绶，逸志在青云。
柳色临流动，春光到县分。
贤人多静理，未爽醉醺醺。','',''),('quantangshi-42271','送从兄赴临川幕','徐鉉','quantangshi','','卷43','梁王籍宠就东藩，还召邹枚坐兔园。
今日好论天下事，昔年同受主人恩。
石头城下春潮满，金柅亭边绿树繁。
唯有音书慰离别，一杯相送别无言。','',''),('quantangshi-42272','送龚员外赴江州幕','徐鉉','quantangshi','','卷43','烦君更上筑金台，世难民劳藉俊才。
自有声名驰羽檄，不妨谈笑奉尊罍。
元规楼迥清风满，匡俗山春画障开。
莫忘故人离别恨，海潮回处寄书来。','',''),('quantangshi-42273','送朱先辈尉庐陵','徐鉉','quantangshi','','卷43','我重朱夫子，依然见古人。
成名无愧色，得禄及慈亲。
莫叹官资屈，宁论活计贫。
平生心气在，终任静边尘。','',''),('quantangshi-42274','送钟德林郎中学士赴东府诗 得酒','徐鉉','quantangshi','','卷43','酌此杯中物，茱萸满把秋。
今朝将送别，他日是忘忧。
世乱方多事，年加易得愁。
政成频一醉，亦未减风流。','',''),('quantangshi-42275','送陈先生之洪井寄萧少卿','徐鉉','quantangshi','','卷43','闻君仙袂指洪厓，我忆情人别路赊。
知有欢娱游楚泽，更无书札到京华。
云开驿阁连江静，春满西山倚汉斜。
此处相逢应见问，为言搔首望龙沙。','',''),('quantangshi-42276','送龚明府九江归宁','徐鉉','quantangshi','','卷43','茂宰隳官去，扁舟着彩衣。
湓城春酒熟，匡阜野花稀。
解缆垂杨绿，开帆宿鹭飞。
一朝吾道泰，还逐落潮归。','',''),('quantangshi-42277','和江西萧少卿见寄二首 一','徐鉉','quantangshi','','卷43','亡羊岐路愧司南，二纪穷通聚散三。
老去何妨从笑傲，病来看欲嬾朝参。
离肠似线常忧断，世态如汤不可探。
珍重加餐省思虑，时时斟酒压山岚。','',''),('quantangshi-42278','和江西萧少卿见寄二首 二','徐鉉','quantangshi','','卷43','身遥上国三千里，名在朝中二十春。
金印不须辞入幕，麻衣曾此叹迷津。
卷舒由我真齐物，忧喜忘心即养神。
世路风波自飜覆，虚舟无计得沉沦。','',''),('quantangshi-42279','送薛少卿赴青阳','徐鉉','quantangshi','','卷43','我爱陶靖节，吏隐从弦歌。
我爱费征君，高卧归九华。
清风激颓波，来者无以加。
我志两不遂，漂沦浩无涯。
数奇时且乱，此图今愈赊。
贤哉薛夫子，高举凌晨霞。
安民即是道，投足皆为家。
功名与权位，悠悠何用夸。
携朋出远郊，酌酒藉平沙。
云收远天静，江阔片帆斜。
离怀与企羡，南望长咨嗟。','',''),('quantangshi-42280','送高起居之泾县','徐鉉','quantangshi','','卷43','右史罢朝归，之官句水湄。
别我行千里，送君倾一巵。
酒罢长叹息，此叹君应悲。
乱中吾道薄，卿族旧人稀。
胡为佩铜墨，去此白玉墀。
吏事岂所堪，民病何可医。
藏用清其心，此外慎勿为。
县郭有佳境，千峰溪水西。
云树杳回合，岩峦互蔽亏。
弹琴坐其中，世事吾不知。
时时寄书札，以慰长相思。','',''),('quantangshi-42281','宿茅山寄舍弟','徐鉉','quantangshi','','卷43','茅许禀灵气，一家同上宾。
仙山空有庙，举世更无人。
独往诚违俗，浮名亦累真。
当年各自勉，云洞镇长春。','',''),('quantangshi-42282','晚憇白鹤庙寄句容张少府','徐鉉','quantangshi','','卷43','日入林初静，山空暑更寒。
泉鸣细岩窦，鹤泪眇云端。
拂榻安棊局，焚香戴道冠。
望君殊不见，终夕凭栏干。','',''),('quantangshi-42283','题紫阳观','徐鉉','quantangshi','','卷43','南朝名士富仙才，追步东卿遂不回。
丹井自深桐暗老，祠宫长在鹤频来。
岩边桂树攀仍倚，洞口桃花落复开。
惆怅霓裳太平事，一函真迹锁昭台。','',''),('quantangshi-42284','赠奚道士','徐鉉','quantangshi','','卷43','先生曾有洞天期，犹傍天坛摘紫芝。
处世自能心混沌，全真谁见德支离。
玉霄尘闭人长在，全鼎功成俗未知。
他日飙轮谒茅许，愿同鸡犬去相随。','',''),('quantangshi-42285','题碧岩亭赠孙尊师','徐鉉','quantangshi','','卷43','绝境何人识，高亭万象含。
凭轩临树杪，送目极天南。
积霭生泉洞，归云锁石龛。
丹霞披翠巘，白鸟带晴岚。
仙去留虚室，龙归涨碧潭。
幽岩君独爱，玄味我曾耽。
世上愁何限，人间事久谙。
终须脱羁鞅，来此会空谈。','',''),('quantangshi-42286','题白鹤庙','徐鉉','quantangshi','','卷43','平生心事向玄关，一入仙乡似旧山。
白鹤泪空晴眇眇，丹沙流涧暮潺潺。
尝嗟多病嫌中药，拟问真经乞小还。
满洞烟霞互陵乱，何峰台榭是萧闲。','',''),('quantangshi-42287','步虚词五首 一','徐鉉','quantangshi','','卷43','气为还元正，心由抱一灵。
凝神归罔象，飞步入青冥。
整服乘三素，旋纲蹑九星。
琼章开后学，稽首奉真经。','',''),('quantangshi-42288','步虚词五首 二','徐鉉','quantangshi','','卷43','天帝黄金阙，真人紫锦书。
霓裳纷蔽景，羽服迥凌虚。
白鹤能为使，班麟解驾车。
灵符终愿借，转共世情疎。','',''),('quantangshi-42289','步虚词五首 三','徐鉉','quantangshi','','卷43','圣主过幽谷，虚皇在蘂宫。
五千宗物母，七字祕神童。
世上金壶远，人间玉龠空。
唯余养身法，修此与天通。','',''),('quantangshi-42290','步虚词五首 四','徐鉉','quantangshi','','卷43','何处求玄解，人间有洞天。
勤行皆是道，谪下尚为仙。
蔽景乘朱凤，排虚驾紫烟。
不嫌园吏傲，愿在玉宸前。','',''),('quantangshi-42291','步虚词五首 五','徐鉉','quantangshi','','卷43','三素霏霏远，盟威凛凛寒。
火铃空灭没，星斗晓阑干。
佩响流虚殿，炉烟在醮坛。
萧寥不可极，骖驾上云端。','',''),('quantangshi-42292','留题仙观','徐鉉','quantangshi','','卷43','瑶坛醮罢晚云开，羽客分飞俗士回。
为报移文不须勒，未曾游处待重来。','',''),('quantangshi-42293','和陈洗马山庄新泉','徐鉉','quantangshi','','卷43','已开山馆待抽簪，更要岩泉欲洗心。
常被松声迷细韵，忽流花片落高岑。
便疏浅濑穿莎径，始有清光映竹林。
何日煎茶酝香酒，沙边同听暝猨吟。','',''),('quantangshi-42294','奉和七夕应令','徐鉉','quantangshi','','卷43','今宵星汉共晶光，应笑罗敷嫁侍郎。
斗柄易倾离恨促，河流不尽后期长。
静闻天籁疑鸣佩，醉折荷花想艳妆。
谁见宣猷堂上宴，一篇清韵振金铛。','',''),('quantangshi-42295','又和八日','徐鉉','quantangshi','','卷43','微云疎雨淡新秋，晓梦依稀十二楼。
故作别离应有以，拟延更漏共无由。
那教人世长多恨，未必天仙不解愁。
博望苑中残酒醒，香风佳气独迟留。','',''),('quantangshi-42296','和印先辈及第后献座主朱舍人郊居之作','徐鉉','quantangshi','','卷43','成名郊外掩柴扉，树影蝉声共息机。
积雨暗封青藓径，好风轻透白{糹朿}衣。
嘉鱼始赋人争诵，荆玉频收国自肥。
独坐公厅正烦暑，喜吟新咏见玄微。','',''),('quantangshi-42297','和致仕张尚书新创道院','徐鉉','quantangshi','','卷43','梓泽成新致，金丹有旧情。
挂冠朝睡足，隐几暮江清。
药圃分轻绿，松窗起细声。
养高宁厌病，默坐对诸生。','',''),('quantangshi-42298','和尉迟赞善秋暮僻居','徐鉉','quantangshi','','卷43','登高节物最堪怜，小岭疎林对槛前。
轻吹断时云缥缈，夕阳明处水澄鲜。
江城秋早催寒事，望苑朝稀足晏眠。
庭有菊花尊有酒，若方陶令愧前贤。','',''),('quantangshi-42299','和陈赞善致仕还京口','徐鉉','quantangshi','','卷43','海门山下一渔舟，中有高人未白头。
已驾安车归故里，尚通闺籍在龙楼。
泉声漱玉窗前落，江色和烟槛外流。
今日君臣厚终始，不须辛苦画双牛。','',''),('quantangshi-42300','京使回自临川得从兄书寄诗依韵和','徐鉉','quantangshi','','卷43','珍重还京使，殷勤话故人。
别离长挂梦，宠禄不关身。
趣向今成道，声华旧绝尘。
莫嗟客鬓老，诗句逐时新。','',''),('quantangshi-42301','陪郑王相公赋筵前垂冰应教依韵','徐鉉','quantangshi','','卷43','窗外虚明雪乍晴，檐前垂溜尽成冰。
长廊瓦叠行行密，晚院风高寸寸增。
玉指乍拈簪尚愧，金阶时坠磬难胜。
晨餐堪醒曹参酒，自恨空肠病不能。','',''),('quantangshi-42302','送礼部潘尚书致仕还建安','徐鉉','quantangshi','','卷43','名遂功成累复轻，鲈鱼因起旧乡情。
履声初下金华省，帆影看离石首城。
化劒津头寻故老，同亭会上问仙卿。
冥鸿高举真难事，相送何须泪满缨。','',''),('quantangshi-42303','和尉迟赞善病中见寄','徐鉉','quantangshi','','卷43','仙郎移病暑天过，却似冥鸿避罻罗。
昼梦乍惊风动竹，夜吟时觉露霑莎。
情亲稍喜贫居近，性嬾犹嫌上直多。
望苑恩深期勿药，青云岐路未蹉跎。','',''),('quantangshi-42304','池州陈使君见示游齐山诗因寄','徐鉉','quantangshi','','卷43','往岁曾游弄水亭，齐峰浓翠暮轩横。
哀猨出槛心虽喜，伤鸟闻弦势易惊。
病后簪缨殊寡兴，老来泉石倍关情。
今朝池口风波静，遥贺山前有颂声。','',''),('quantangshi-42305','再领制诰和王明府见贺','徐鉉','quantangshi','','卷43','蹇步还依列宿边，拱辰重认旧云天。
自嗟多难飘零困，不似当年胆气全。
鸡树晚花疎向日，龙池轻浪细含烟。
从来不解为身计，一叶悠悠任大川。','',''),('quantangshi-42306','送高舍人使岭南','徐鉉','quantangshi','','卷43','西掖官曹近，南溟道路遥。
使星将渡汉，仙棹乍乘潮。
柳映灵和折，梅依大庾飘。
江帆风淅淅，山馆雨萧萧。
陆贾真迂阔，终童久寂寥。
送君何限意，把酒一长谣。','',''),('quantangshi-42307','和王明府见寄','徐鉉','quantangshi','','卷43','时情世难消吾道，薄宦流年危此身。
莫叹京华同寂寞，曾经兵革共漂沦。
对山开户唯求静，贳酒留宾不道贫。
善政空多尚淹屈，不知谁是解忧民。','',''),('quantangshi-42308','和方泰州见寄','徐鉉','quantangshi','','卷43','逐客凄凄重入京，旧愁新恨两难胜。
云收楚塞千山雪，风结秦淮一尺冰。
置醴筵空情岂尽，投湘文就思如凝。
更残月落知孤坐，遥望船窗一点星。','',''),('quantangshi-42309','文献太子挽歌词五首 一','徐鉉','quantangshi','','卷43','国有承祧重，人知秉哲尊。
清风来望苑，遗烈在东藩。
此日升缑岭，何因到寝门。
天高不可问，烟霭共昏昏。','',''),('quantangshi-42310','文献太子挽歌词五首 二','徐鉉','quantangshi','','卷43','夏启吾君子，周储上帝宾。
音容一飘忽，功业自纷纶。
露泣承华月，风惊丽正尘。
空余商岭客，行泪下宜春。','',''),('quantangshi-42311','文献太子挽歌词五首 三','徐鉉','quantangshi','','卷43','出处成交让，经纶有大功。
泪碑瓜步北，棠树蒜山东。
百揆方时叙，重离遂不融。
故臣偏感咽，曾是叹三穷。','',''),('quantangshi-42312','文献太子挽歌词五首 四','徐鉉','quantangshi','','卷43','甲观光阴促，园陵天地长。
箫笳咽无韵，宾御哭相将。
盛烈传彝鼎，遗文被乐章。
君臣知己分，零泪乱无行。','',''),('quantangshi-42313','文献太子挽歌词五首 五','徐鉉','quantangshi','','卷43','彩仗清晨出，非同齿胄时。
愁烟锁平甸，朔吹绕寒枝。
楚客来何补，缑山去莫追。
回瞻飞盖处，掩袂不胜悲。','',''),('quantangshi-42314','送王员外宰德安','徐鉉','quantangshi','','卷43','家世朱门贵，官资粉署优。
今为百里长，应好五峰游。
柳影连彭泽，湖光接庾楼。
承明须再入，官满莫淹留。','',''),('quantangshi-42315','以端溪砚酬张员外水精珠兼和来篇','徐鉉','quantangshi','','卷43','请以端溪润，酬君水玉明。
方圆虽异器，功用信俱呈。
自得山川秀，能分日月精。
巾箱各珍重，所贵在交情。','',''),('quantangshi-42316','奉使九华山中途遇青阳薛郎中','徐鉉','quantangshi','','卷43','故人相别动相思，此地相逢岂素期。
九子峰前闲未得，五溪桥上坐多时。
甘泉从幸余知忝，宣室征还子未迟。
且饮一杯消别恨，野花风起渐离披。','',''),('quantangshi-42317','奉命南使经彭泽','徐鉉','quantangshi','','卷43','远使程途未一分，离心常要醉醺醺。
那堪彭泽门前立，黄菊萧疎不见君。','',''),('quantangshi-42318','南都遇前嘉鱼刘令言游闽岭作此与之','徐鉉','quantangshi','','卷43','我持使节经韶石，君作闲游过武夷。
两地山光成独赏，隔年乡思暗相知。
洪厓坛上长岑寂，孺子亭前自别离。
珍重分岐一杯酒，强加餐饭数吟诗。','',''),('quantangshi-42319','阁皂山','徐鉉','quantangshi','','卷43','殿影高低云掩映，松阴缭绕步徘徊。
从今莫厌簪裾累，不是乘轺不得来。','',''),('quantangshi-42320','玉笥山留题','徐鉉','quantangshi','','卷43','仙乡会应远，王事知何极。
征传莫辞劳，玉峰聊一息。
形骸已销散，心想都凝寂。
真气自清虚，非关好松石。
九仙皆积学，洞壑多遗迹。
游子归去来，胡为但征役。','',''),('quantangshi-42321','庐陵别朱观先辈','徐鉉','quantangshi','','卷43','桂籍知名有几人，翻飞相续上青云。
解怜才子宁唯我，远作卑官尚见君。
岭外独持严助节，宫中谁荐长卿文。
新诗试为重高咏，朝汉台前不可闻。','',''),('quantangshi-42322','文彧少卿文山郎中交好深至二纪已余暌别数年二子长逝奉使岭表途次南康吊孙氏之孤于其家覩文彧手书于僧室慷慨悲叹留题此诗','徐鉉','quantangshi','','卷43','孙家虚坐吊诸孤，张叟僧房见手书。
二纪欢游今若此，满衣零泪欲何如。
腰间金印从如斗，镜里霜华已满梳。
珍重远公应笑我，尘心唯此未能除。','',''),('quantangshi-42323','朱处士相与有山水之愿见送至南康作此以别之','徐鉉','quantangshi','','卷43','怜君送我至南康，更忆梅花庾岭芳。
多少仙山共游在，愿君百岁尚康强。','',''),('quantangshi-42324','清明日清远峡作','徐鉉','quantangshi','','卷43','岭外春过半，途中火又新。
殷勤清远峡，留恋北归人。','',''),('quantangshi-42325','回至南康题紫极宫里道士房','徐鉉','quantangshi','','卷43','王事信靡盬，饮冰安足辞。
胡为拥征传，乃至天南陲。
天南非我乡，留滞忽逾时。
还经羽人家，豁若云雾披。
何以宽吾怀，老庄有微词。
达士无不可，至人岂偏为。
客愁勿复道，为君吟此诗。','',''),('quantangshi-42326','和歙州陈使君见寄','徐鉉','quantangshi','','卷43','新安风景好，时令肃辕门。
身贵心弥下，功多口不言。
韬钤家法在，儒雅素风存。
簪履陪游盛，乡闾俗化敦。
临窗山色秀，绕郭水声喧。
织络文章丽，矜严道义尊。
楼台秋月静，京庾晚云屯。
晓吹传衙鼓，晴阳展信幡。
一篇贻友好，千里倍心论。
未见归骖动，空能役梦魂。','',''),('quantangshi-42327','和贾员外戬见赠玉蘂花栽','徐鉉','quantangshi','','卷43','琼瑶一簇带花来，便斸苍苔手自栽。
喜见唐昌旧颜色，为君判病酌金罍。','',''),('quantangshi-42328','光穆皇后挽歌三首 一','徐鉉','quantangshi','','卷43','仙驭期难改，坤仪道自光。
閟宫新表德，沙麓旧膺祥。
素帟尧门掩，凝笳毕陌长。
东风惨陵树，无复见亲桑。','',''),('quantangshi-42329','光穆皇后挽歌三首 二','徐鉉','quantangshi','','卷43','永乐留虚位，长陵启夕扉。
返虞严吉杖，复土掩空衣。
功业投三母，光灵极四妃。
唯应彤史在，不与露花曦。','',''),('quantangshi-42330','光穆皇后挽歌三首 三','徐鉉','quantangshi','','卷43','隐隐阊门路，烟云晓更愁。
空瞻金辂出，非是濯龙游。
德感人伦正，风行内职修。
还随偶物化，同此思轩丘。','',''),('quantangshi-42331','严相公宅牡丹','徐鉉','quantangshi','','卷43','但是豪家重牡丹，争如丞相阁前看。
凤楼日暖开偏早，鸡树阴浓谢更难。
数朵已应迷国艳，一枝何幸上尘冠。
不知更许凭栏否，烂熳春光未肯残。','',''),('quantangshi-42332','侍宴赋得归雁','徐鉉','quantangshi','','卷43','夜静羣动息，翩翩一雁归。
清音天际远，寒影月中微。
何处云同宿，长空雪共飞。
阳和常借便，免与素心违。','',''),('quantangshi-42333','又赋早春书事','徐鉉','quantangshi','','卷43','苑里芳华早，皇家胜事多。
弓声达春气，弈思养天和。
暖酒红炉火，浮舟绿水波。
雪晴农事起，击壤听赓歌。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-42334','依韵和令公大王蔷薇诗','徐鉉','quantangshi','','卷43','绿树成阴后，羣芳稍歇时。
谁将新濯锦，挂向最长枝。
卷箔香先入，凭栏影任移。
赏频嫌酒渴，吟苦怕霜髭。
架迥笼云幄，庭虚展绣帷。
有情萦舞袖，无力罥游丝。
嫩蘂莺偷采，柔条柳伴垂。
荀池波自照，梁苑客尝窥。
玉李寻皆谢，金桃亦暗衰。
花中应独贵，庭下故开迟。
委艳妆苔砌，分华借槿篱。
低昂匀灼烁，浓淡叠参差。
幸植王宫里，仍逢宰府知。
芳心向谁许，醉态不能支。
芍药天教避，玫瑰众共嗤。
光明烘昼景，润腻裛轻𩅰。
丽似期神女，珍如重卫姬。
君王偏属咏，七子尽搜奇。','',''),('quantangshi-42335','和门下殷侍郎新茶二十韵','徐鉉','quantangshi','','卷43','暖吹入春园，新芽竞粲然。
才教鹰觜拆，未放雪花妍。
荷杖青林下，携筐旭景前。
孕灵资雨露，钟秀自山川。
碾后香弥远，烹来色更香。
名随土地贵，味逐水泉迁。
力藉流黄暖，形模紫笋圆。
正当钻柳火，遥想涌金泉。
任道时新物，须依古法煎。
轻瓯浮绿乳，孤竈散余烟。
甘荠非予匹，宫槐让我先。
竹孤空冉冉，荷弱谩田田。
解渴消残酒，清神感夜眠。
十浆何足馈，百榼尽堪捐。
采撷唯忧晚，营求不计钱。
任公因焙显，陆氏有经传。
爱甚真成癖，尝多合得仙。
亭台虚静处，风月艳阳天。
自可临泉石，何妨杂管弦。
东山似蒙顶，愿得从诸贤。','',''),('quantangshi-42336','春雪应制','徐鉉','quantangshi','','卷43','繁阴连曙景，瑞雪洒芳辰。
势密犹疑腊，风和始觉春。
萦林开玉蘂，飘座裛香尘。
欲识宸心悦，云谣慰兆人。','',''),('quantangshi-42337','进雪诗','徐鉉','quantangshi','','卷43','欲使新正识有年，故飘轻絮伴春还。
近看琼树笼银阙，远想瑶池带玉关。
润逐麳麰铺绿野，暖随杯酒上朱颜。
朝来花萼楼中宴，数曲赓歌雅颂间。','',''),('quantangshi-42338','自题山亭三首 一','徐鉉','quantangshi','','卷43','簪组非无累，园林未是归。
世喧长不到，何必故山薇。','',''),('quantangshi-42339','自题山亭三首 二','徐鉉','quantangshi','','卷43','小舫行乘月，高斋卧看山。
退公聊自足，争敢望长闲。','',''),('quantangshi-42340','自题山亭三首 三','徐鉉','quantangshi','','卷43','跂石仍临水，披襟复挂冠。
机心忘未得，棊局与鱼竿。','',''),('quantangshi-42341','和陈表用员外求酒','徐鉉','quantangshi','','卷43','暑天频雨亦频晴，帘外闲云重复轻。
珍重一壶酬绝唱，向风遥想醉吟声。','',''),('quantangshi-42342','奉和右省仆射西亭高卧作','徐鉉','quantangshi','','卷43','院静苍苔积，庭幽怪石欹。
蝉声当槛急，虹影向檐垂。
昼漏犹怜永，丛兰未觉衰。
疎篁巢翡翠，折苇覆鸬鷀。
对酒襟怀旷，围棊旨趣迟。
景皆随所尚，物各遂其宜。
道与时相会，才非世所羇。
赋诗贻座客，秋事尔何悲。','',''),('quantangshi-42343','忆新淦觞池寄孟宾于员外','徐鉉','quantangshi','','卷43','往年淦水驻行轩，引得清流似月圆。
自有溪光还碧甃，不劳人力递金船。
润滋苔藓欺茵席，声入杉松当管弦。
珍重诗人频管领，莫教尘土咽潺潺。','',''),('quantangshi-42344','右省仆射后湖亭闲宴铉以宿直先归赋诗留献','徐鉉','quantangshi','','卷43','湖上一阳生，虚亭启高宴。
枫林烟际出，白鸟波心见。
主人忘贵达，座客容疵贱。
独慙残照催，归宿明光殿。','',''),('quantangshi-42345','送孟宾于员外还新淦','徐鉉','quantangshi','','卷43','暂来城阙不从容，却佩银鱼隐玉峰。
双涧水边欹醉石，九仙台下听风松。
题诗翠壁称逋客，采药春畦狎老农。
野鹤乘轩云出岫，不知何日再相逢。','',''),('quantangshi-42346','孟君别后相续寄书作此酬之','徐鉉','quantangshi','','卷43','多病怯烦暑，短才忧近职。
跂足北窗风，遥怀浩无极。
故人易成别，诗句空相忆。
尺素寄天涯，淦江秋水色。','',''),('quantangshi-42347','纳后夕侍宴','徐鉉','quantangshi','','卷43','天上轩星正，云间湛露垂。
礼容过渭水，宴喜胜瑶池。
彩雾笼花烛，升龙肃羽仪。
君臣欢乐日，文物盛明时。
帘卷银河转，香凝玉漏迟。
华封倾祝意，觞酒与声诗。','',''),('quantangshi-42348','又三绝 一','徐鉉','quantangshi','','卷43','时平物茂岁功成，重翟排云到玉京。
四海未知春色至，今宵先入九重城。','',''),('quantangshi-42349','又三绝 二','徐鉉','quantangshi','','卷43','银烛金炉禁漏移，月轮初照万年枝。
造舟已似文王事，卜世应同八百期。','',''),('quantangshi-42350','又三绝 三','徐鉉','quantangshi','','卷43','汉主承干帝道光，天家花烛宴昭阳。
六衣盛礼如金屋，彩笔分题似柏梁。','',''),('quantangshi-42351','北苑侍宴杂咏诗 竹','徐鉉','quantangshi','','卷43','劲节生宫苑，虚心奉豫游。
自然名价重，不羡渭川侯。','',''),('quantangshi-42352','北苑侍宴杂咏诗 松','徐鉉','quantangshi','','卷43','细韵风中远，寒青雪后浓。
繁阴堪避雨，効用待东封。','',''),('quantangshi-42353','北苑侍宴杂咏诗 水','徐鉉','quantangshi','','卷43','碧草垂低岸，东风起细波。
横汾从游宴，何谢到天河。','',''),('quantangshi-42354','北苑侍宴杂咏诗 风','徐鉉','quantangshi','','卷43','昨朝才解冻，今日又开花。
帝力无人识，谁知玩物华。','',''),('quantangshi-42355','北苑侍宴杂咏诗 菊','徐鉉','quantangshi','','卷43','细丽披金彩，氛氲散远馨。
泛杯频奉赐，缘解制颓龄。','',''),('quantangshi-42356','柳枝词十首 一','徐鉉','quantangshi','','卷43','金马辞臣赋小诗，梨园弟子唱新词。
君恩还似东风意，先入灵和蜀柳枝。','',''),('quantangshi-42357','柳枝词十首 二','徐鉉','quantangshi','','卷43','百草千花共待春，绿杨颜色最惊人。
天边雨露年年在，上苑芳华岁岁新。','',''),('quantangshi-42358','柳枝词十首 三','徐鉉','quantangshi','','卷43','长爱龙池二月时，𣯶𣯶金线弄春姿。
假饶叶落枝空后，更有梨园笛里吹。','',''),('quantangshi-42359','柳枝词十首 四','徐鉉','quantangshi','','卷43','绿水成文柳带摇，东风初到不鸣条。
龙舟欲过偏留恋，万缕轻丝拂御桥。','',''),('quantangshi-42360','柳枝词十首 五','徐鉉','quantangshi','','卷43','百尺长条婉麴尘，诗题不尽画难真。
凭君折向人间种，还似君恩处处春。','',''),('quantangshi-42361','柳枝词十首 六','徐鉉','quantangshi','','卷43','风暖云开晚照明，翠条深映凤皇城。
人间欲识灵和态，听取新词玉管声。','',''),('quantangshi-42362','柳枝词十首 七','徐鉉','quantangshi','','卷43','醉折垂杨唱柳枝，金城三月走金羁。
年年为爱新条好，不觉苍华也似丝。','',''),('quantangshi-42363','柳枝词十首 八','徐鉉','quantangshi','','卷43','新春花柳竞芳姿，偏爱垂杨拂地枝。
天子徧教词客赋，宫中要唱洞箫词。','',''),('quantangshi-42364','柳枝词十首 九','徐鉉','quantangshi','','卷43','凝碧池头蘸翠涟，凤皇楼畔簇晴烟。
新词欲咏知难咏，说与双成入管弦。','',''),('quantangshi-42365','柳枝词十首 十','徐鉉','quantangshi','','卷43','侍从甘泉与未央，移舟偏要近垂杨。
樱桃未绽梅花老，折得柔条百尺长。','',''),('quantangshi-42366','奉和宫傅相公怀旧见寄四十韵','徐鉉','quantangshi','','卷43','谢傅功成德望全，鸾台初下正萧然。
抟风乍息三千里，感旧重怀四十年。
西掖新官同贾马，南朝兴运似开天。
文辞职业分工拙，流辈班资让后先。
每愧陋容劳刻画，长慙顽石费雕镌。
晨趋纶掖吟春永，夕会精庐待月圆。
立马有时同草昭，联镳几处共成篇。
闲歌柳叶翻新曲，醉咏桃花促绮筵。
少壮况逢时世好，经过宁虑岁华迁。
云龙得路须腾跃，社栎非材合弃捐。
再谒湘江犹是幸，两还宣室竟何缘。
已知瑕玷劳磨莹，又有官司重接连。
听漏分宵趋建礼，从游同召赴甘泉。
云开阊阖分台殿，风过华林度管弦。
行止不离宫仗影，衣裾尝惹御炉烟。
师资稷契论中礼，依止山公典小铨。
多谢天波垂赤管，敢教晨景过华塼。
翾飞附骥方经远，巨楫垂风遂济川。
玉烛调时钧轴正，台阶平处德星悬。
岩廊礼绝威容肃，布素情深友好偏。
长拟营巢安大厦，忽惊操钺领中权。
吴门日丽龙衔节，京口沙晴鷁画船。
盖代名高方赫赫，恋恩心切更干干。
袁安辞气忠仍恳，吴汉精诚直且专。
却许丘明师纪传，更容疎广奉周旋。
朱门自得施行马，厚禄何妨食万钱。
密疏尚应劳献替，清谈唯见论空玄。
东山妓乐供闲步，北牖风凉足晏眠。
玄武湖边林隐见，五城桥下棹洄沿。
曾移苑树开红药，新凿家池种白莲。
不遣前驺妨野逸，别寻逋客互招延。
棊枰寂静陈虚阁，诗笔沉吟劈彩牋。
往事偶来春梦里，闲愁因动落花前。
青云旧侣嗟谁在，白首亲情倍见怜。
尽日凝思殊怅望，一章追叙信精研。
韶颜莫与年争竞，世虑须凭道节宣。
幸喜书生为将相，定由阴德致神仙。
羊公剩有登临兴，尚子都无嫁娶牵。
退象天山镇浮竞，起为霖雨润原田。
从容自保君臣契，何必扁舟始是贤。','',''),('quantangshi-42367','右省仆射相公垂览和诗复贻长句輙次来韵','徐鉉','quantangshi','','卷43','西院春归道思深，披衣闲听暝猨吟。
铺陈政事留黄阁，偃息神机在素琴。
玉柄暂时疎末座，瑶华频复惠清音。
开晴便作东山约，共赏烟霞放旷心。','',''),('quantangshi-42368','九日落星山登高','徐鉉','quantangshi','','卷43','秋暮天高稻穟成，落星山上会诸宾。
黄花泛酒依流俗，白发满头思古人。
岩影晚看云出岫，湖光遥见客垂纶。
风烟不改年长度，终待林泉老此身。','',''),('quantangshi-42369','十日和张少监','徐鉉','quantangshi','','卷43','重阳高会古平台，吟徧秋光始下来。
黄菊后期香未减，新诗捧得眼还开。
每因佳节知身老，却忆前欢似梦回。
且喜清时屡行乐，是非名利尽悠哉。','',''),('quantangshi-42370','御筵送邓王','徐鉉','quantangshi','','卷43','禁里秋光似水清，林烟池影共离情。
暂移黄阁只三载，却望紫垣都数程。
满座清风天子送，随车甘雨郡人迎。
绮霞阁上诗题在，从此还应有颂声。','',''),('quantangshi-42371','和张少监晚菊','徐鉉','quantangshi','','卷43','忆共庭兰倚砌裁，柔条轻吹独依隈。
自知佳节终堪赏，为惜流光未忍开。
采撷也须盈掌握，馨香还解满尊罍。
今朝旬假犹无事，更好登临泛一杯。','',''),('quantangshi-42372','送冯侍郎','徐鉉','quantangshi','','卷43','闻君竹马戏毗陵，谁道观风自六卿。
今日声明光旧物，共看旌斾拥书生。
斩蛟桥下溪烟碧，射虎亭边草路清。
应念筵中倍离恨，老来偏重十年兄。','',''),('quantangshi-42373','又绝句寄题毗陵驿','徐鉉','quantangshi','','卷43','曾持使节驻毗陵，长与州人有旧情。
为向驿桥风月道，舍人髭鬓白千茎。','',''),('quantangshi-42374','陈侍郎宅观花烛','徐鉉','quantangshi','','卷43','今夜银河万里秋，人言织女嫁牵牛。
佩声寥亮和金奏，烛影荧煌映玉钩。
座客亦从天子赐，更筹须为主人留。
世间盛事君知否，朝下鸾台夕凤楼。','',''),('quantangshi-42375','送萧尚书致仕归庐陵','徐鉉','quantangshi','','卷43','江海分飞二十春，重论前事不堪闻。
主忧臣辱谁非我，曲突徙薪唯有君。
金紫满身皆外物，雪霜垂领便离羣。
鹤归华表望不尽，玉笥山头多白云。','',''),('quantangshi-42376','赋得秋江晚照','徐鉉','quantangshi','','卷43','落日照平流，晴空万里秋。
轻明动枫叶，点的乱沙鸥。
罾网鱼梁静，籉簦稻穗收。
不教行乐倦，冉冉下城楼。','',''),('quantangshi-42377','奉和子龙大监与舍弟赠答之什','徐鉉','quantangshi','','卷43','石渠东观两优贤，明主知臣岂偶然。
鸳鹭分行皆接武，金兰同好共忘年。
怀恩未遂林泉约，窃位空慙组绶悬。
多少深情知不尽，好音相慰强成篇。','',''),('quantangshi-42378','史馆庭梅见其毫末历载三十今已半枯尝僚诸公唯相公与铉在耳覩物兴感率成短篇谨书献上伏惟垂览','徐鉉','quantangshi','','卷43','东观婆娑树，曾怜甲坼时。
繁英共攀折，芳岁几推移。
往事皆陈迹，清香亦暗衰。
相看宜自喜，双鬓合垂丝。','',''),('quantangshi-42379','太傅相公深感庭梅再成绝唱曲垂借示倍认知怜谨用旧韵攀和','徐鉉','quantangshi','','卷43','禁省繁华地，含芳自一时。
雪英开复落，红药植还移。
静想分今昔，频吟叹盛衰。
多情共如此，争免鬓成丝。','',''),('quantangshi-42380','太傅相公以庭梅二篇许舍弟同赋再迂藻思曲有虚称谨依韵奉和庶申感谢','徐鉉','quantangshi','','卷43','旧眷终无替，流光自足悲。
攀条感花萼，和曲许埙篪。
前会成春梦，和人更己知。
缘情聊借喻，争取道言诗。','',''),('quantangshi-42381','和钟大监泛舟同游见示','徐鉉','quantangshi','','卷43','潮沟横趣北山阿，一月三游未是多。
老去交亲难暂舍，闲中滋味更无过。
溪桥树映行人渡，村径风飘牧竖歌。
孤棹乱流偏有兴，满川晴日弄微波。','',''),('quantangshi-42382','又和游光睦院','徐鉉','quantangshi','','卷43','寺门山水际，清浅照孱颜。
客棹晚维岸，僧房犹掩关。
日华穿竹静，云影过堦闲。
箕踞一长啸，忘怀物我间。','',''),('quantangshi-42383','和张少监舟中望蒋山','徐鉉','quantangshi','','卷43','溪路向还背，前山高复重。
纷披红叶树，间断白云峰。
尽日慵移棹，何年醉倚松。
自知闲未得，不敢笑周颙。','',''),('quantangshi-42384','茱萸诗','徐鉉','quantangshi','','卷43','万物庆西成，茱萸独擅名。
芳排红结小，香透夹衣轻。
宿露霑犹重，朝阳照更明。
长和菊花酒，高宴奉西清。','',''),('quantangshi-42385','奉和御制茱萸','徐鉉','quantangshi','','卷43','台畔西风御果新，芳香精彩丽萧辰。
柔条细叶妆治好，紫蔕红芳点缀匀。
几朵得陪天上宴，千株长作洞中春。
今朝圣藻偏流咏，黄菊无由更敢邻。','',''),('quantangshi-42386','蒙恩赐酒旨令醉进诗以谢','徐鉉','quantangshi','','卷43','明光殿里夜迢迢，多病逢秋自寂寥。
蜡炬乍传丹凤诏，御题初认白云谣。
今宵幸识衢尊味，明日知停入合朝。
为感君恩判一醉，不烦辛苦解金貂。','',''),('quantangshi-42387','秋日泛舟赋苹花','徐鉉','quantangshi','','卷43','素艳拥行舟，清香覆碧流。
远烟分的的，轻浪泛悠悠。
雨歇平湖满，风凉运渎秋。
今朝流咏处，即是白苹洲。','',''),('quantangshi-42388','题梁王旧园','徐鉉','quantangshi','','卷43','梁王旧馆枕潮沟，共引垂藤系小舟。
树倚荒台风淅淅，草埋欹石[雨]修修。
门前不见邹枚醉，池上时闻雁鹜愁。
节士逢秋多感激，不须频向此中游。','',''),('quantangshi-42389','奉酬度支陈员外','徐鉉','quantangshi','','卷43','古来贤达士，驰鹜唯羣书。
非礼誓弗习，违道无与居。
儒家若迂阔，遂将世情疎。
吾友嗣世德，古风蔼有余。
幸遇汉文皇，握兰佩金鱼。
俯视长沙赋，凄凄将焉如。','',''),('quantangshi-42390','明道人归西林求题院额作此送之','徐鉉','quantangshi','','卷43','昔从岐阳狩，簪缨满翠微。
十年劳我梦，今日送师归。
曳尾龟应乐，乘轩鹤谩肥。
含情题小篆，将去挂岩扉。','',''),('quantangshi-42391','送宣州丘判官','徐鉉','quantangshi','','卷43','宪署游从阻，平台道路赊。
喜君驰后乘，于此会仙槎。
缓酌迟飞盖，微吟望绮霞。
相迎在春渚，暂别莫咨嗟。','',''),('quantangshi-42392','北使还襄邑道中作','徐鉉','quantangshi','','卷43','九月三十日，独行梁宋道。
河流激似飞，林叶翻如扫。
程遥苦昼短，野逈知寒早。
还家亦不闲，要且还家了。','',''),('quantangshi-42393','禁中新月','徐鉉','quantangshi','','卷43','今夕拜新月，沈沈禁署中。
玉绳疎间彩，金掌静无风。
节换知身老，时平见岁功。
吟看北墀暝，兰烬坠微红。','',''),('quantangshi-42394','观吉王从谦花烛','徐鉉','quantangshi','','卷43','王门嘉礼万人观，况是新承置醴欢。
花烛喧阗丞相府，星辰摇动远游冠。
歌声暂阕闻宫漏，云影初开见露盘。
帝里佳期频赋颂，长留故事在金銮。','',''),('quantangshi-42395','棊赌赋诗输刘起居','徐鉉','quantangshi','','卷43','刻烛知无取，争先素未精。
本图忘物我，何必计输赢。
赌墅终规利，焚囊亦近名。
不如相视笑，高咏两三声。','',''),('quantangshi-42396','春尽日游后湖赠刘起居','徐鉉','quantangshi','','卷43','今朝湖上送春归，万顷澄波照白髭。','',''),('quantangshi-42397','送察院李侍御使庐陵因寄孟员外','徐鉉','quantangshi','','卷43','绣衣乘驿急如星，山水何妨寄野情。
肯向九仙台下歇，闲听孟叟醉吟声。','',''),('quantangshi-42398','后湖访古各赋一题得西邸','徐鉉','quantangshi','','卷43','南朝藩阃地，八友旧招寻。
事往山光在，春晴草色深。
曲池鱼自乐，丛桂鸟频吟。
今日中兴运，犹怀翰墨林。','',''),('quantangshi-42399','送德迈道人之豫章','徐鉉','quantangshi','','卷43','禅灵桥畔落残花，桥上离情对日斜。
顾我乘轩慙组绶，羡师飞锡指烟霞。
楼中西岭真君宅，门外南州处士家。
莫道空谈便无事，碧云诗思更无涯。','',''),('quantangshi-42400','送陈祕监归泉州','徐鉉','quantangshi','','卷43','风满潮沟木叶飞，水边行客驻骖騑。
三朝恩泽冯唐老，万里乡关贺监归。
世路穷通前事远，半生谈笑此心违。
离歌不识高堂庆，特地令人泪满衣。','',''),('quantangshi-42401','又听霓裳羽衣曲送陈君','徐鉉','quantangshi','','卷43','清商一曲远人行，桃叶津头月正明。
此是开元太平曲，莫教偏作别离声。','',''),('quantangshi-42402','又题白鹭洲江鸥送陈君','徐鉉','quantangshi','','卷43','白鹭洲边江路斜，轻鸥按翼满平沙。
吾徒来送远行客，停舟为尔长叹息。
酒旗鱼艇两无猜，月影芦花镇相得。
离筵一曲怨复清，满座销魂鸟不惊。
人生不及水禽乐，安用虚名上麟阁。
同心携手今如此，金鼎丹砂何寂寞。
天涯后会眇难期，从此又应添白髭。
愿君不忘分飞处，长保翩翩洁白姿。','',''),('quantangshi-42403','哭刑部侍郎乔公诗','徐鉉','quantangshi','','卷43','举世重文雅，夫君更质真。
曾嗟混鸡鹤，终日异淄磷。
词赋离骚客，封章谏诤臣。
襟怀道家侣，标格古时人。
逸老诚云福，遗形未免贫。
求文空得草，埋玉遂为尘。
静想忘年契，冥思按武晨。
连宵洽杯酒，分日掌丝纶。
蠹简书陈事，遗孤托世亲。
前贤同此叹，非我独霑巾。','',''),('quantangshi-42404','送程德琳郎中学士','徐鍇','quantangshi','','卷43','瓜步妖氛灭，昆冈草树青。
终朝空望极，今日送君行。
报政秋云静，微吟晓月生。
楼中长可见，特用灭离情。','',''),('quantangshi-42405','太傅相公以东观庭梅西垣旧植昔陪盛赏今独家兄唱和之余俾令攀和輙依本韵伏愧斐然','徐鍇','quantangshi','','卷43','静对含章树，闲思共有时。
香随荀令在，根异武昌移。
物性虽摇落，人心岂变衰。
唱酬胜笛曲，来往韵朱[丝]。','',''),('quantangshi-42406','太傅相公与家兄梅花酬唱许缀末篇再赐新诗俯光拙句谨奉清韵用感钧私伏惟采览','徐鍇','quantangshi','','卷43','重叹梅花落，非关塞笛悲。
论文叨接萼，末曲愧吹篪。
枝逐清风动，香因白雪知。
陶钧敷左悌，更赋邵公诗。','',''),('quantangshi-42407','同家兄哭乔侍郎','徐鍇','quantangshi','','卷43','诸公长者郑当时，事事无心性坦夷。
但是登临皆有作，未尝相见不伸眉。
生前适意无过酒，身后遗言只要诗。
三日笑谈成理命，一篇投吊尚应知。','',''),('quantangshi-42408','秋词','徐鍇','quantangshi','','卷43','井梧纷堕砌，寒雁远横空。
雨久[莓]苔紫，霜浓薜荔红。','',''),('quantangshi-42409','和徐鼎臣见寄','包頴','quantangshi','','卷43','平生中表最情亲，浮世那堪聚散频。
谢朓去吟归省阁，刘桢犹自卧漳滨。
旧游半似前生事，要路多逢后进人。
且喜新吟报强健，明年相望杏园春。','',''),('quantangshi-42410','贻耀州将','鍾謨','quantangshi','','卷43','翩翩归尽塞垣鸿，隐隐惊开蛰户虫。
渭北离愁春色里，江南家事战尘中。
还同逐客纫兰佩，谁听缧囚奏土风。
多谢贤侯振吾道，免令搔首泣途穷。','',''),('quantangshi-42411','献周世宗','鍾謨','quantangshi','','卷43','三年耀武羣雄服，一日回銮万国春。
南北通欢永无事，谢恩归去老陪臣。','',''),('quantangshi-42412','代京妓越宾答徐铉','鍾謨','quantangshi','','卷43','一幅轻绡寄海滨，越姑长感昔时恩。
欲知别后情多少，点点凭君看泪痕。','',''),('quantangshi-42413','寄麻姑仙坛道士','查文徽','quantangshi','','卷43','别后相思鹤信稀，郡楼南望远峰迷。
人归仙洞云连地，花落春林水满溪。
白发只应悲镜镊，丹砂犹待寄刀圭。
方平车驾今何在，常苦尘中日易西。','',''),('quantangshi-42414','赠韩定辞','馬彧','quantangshi','','卷43','燧林芳草绵绵思，尽日相携陟丽谯。
别后巏嵍山上望，羡君时复见王乔。','',''),('quantangshi-42415','答马彧','韓定辭','quantangshi','','卷43','崇霞台上神仙客，学辨痴龙艺最多。
盛德好将银管述，丽词堪与雪儿歌。','',''),('quantangshi-42416','题杨克俭池馆','何昌齡','quantangshi','','卷43','经旬因雨不重来，门有蛛丝径有苔。
再向白莲亭上望，不知花木为谁开。','',''),('quantangshi-42417','献江淮郡守卢公','李羽','quantangshi','','卷43','塞诏东来淝水滨，时情惟望秉陶钧。
将军一阵为功业，忍见沙塲百战人。','',''),('quantangshi-42418','南山池','梁藻','quantangshi','','卷43','翡翠戏翻荷叶雨，鹭鸶飞破竹林烟。
时沽村酒临轩酌，拟摘新茶靠石煎。','',''),('quantangshi-42419','嘲庐山道士','陳沆','quantangshi','','卷43','啖肉先生欲上升，黄云踏破紫云崩。
龙腰鹤背无多力，传与麻姑借大鹏。','',''),('quantangshi-42420','句','陳沆','quantangshi','','卷43','罢却儿女戏，放他花木生。
扫地云黏箒，耕山鸟怕牛。
点入旱云千国仰，力浮尘世一毫轻。','',''),('quantangshi-42421','赠织锦人','李詢','quantangshi','','卷43','札札机声晓复晡，眼穿力尽竟何如。
美人一曲成千赐，心里犹嫌花样疎。','',''),('quantangshi-42422','题金山','韓垂','quantangshi','','卷43','灵山一峰秀，岌然殊众山。
盘根大江底，插影浮云间。
雷霆常间作，风雨时往还。
象外悬清影，千载长跻攀。','',''),('quantangshi-42423','后湖','朱存','quantangshi','','卷43','雷轰叠鼓火翻旗，三异翩翩试水师。
惊起黑龙眠不得，狂风猛雨不多时。','',''),('quantangshi-42424','和徐舍人九月十一日见寄','陳彥','quantangshi','','卷43','衡门寂寂逢迎少，不见仙郎向五旬。
莫问龙山前日事，菊花开却为闲人。','',''),('quantangshi-42425','登游齐山','許堅','quantangshi','','卷43','星使南驰入楚重，此山偏得驻行踪。
落花满地月华冷，寂寞旧山三四峰。','',''),('quantangshi-42426','游溧阳下山寺','許堅','quantangshi','','卷43','地枕吴溪与越峰，前朝恩锡灵泉额。
竹林晴见雁塔高，石室曾栖几禅伯。
荒碑字没秋苔深，古池香泛荷花白。
客有经年说别林，落日啼猨情脉脉。','',''),('quantangshi-42427','题幽栖观','許堅','quantangshi','','卷43','仙翁上升去，丹井寄晴壑。
山色接天台，湖光照寥廓。
玉洞绝无人，老桧犹栖鹤。
我欲掣青蛇，他时冲碧落。','',''),('quantangshi-42428','上舍人徐铉','許堅','quantangshi','','卷43','几宵烟月锁楼台，欲寄侯门荐下才。
满面尘埃人不识，谩随流水出山来。','',''),('quantangshi-42429','题茅山观','許堅','quantangshi','','卷43','常恨清风千载郁，洞天令得恣游遨。
松楸古色玉坛静，鸾鹤不来青汉高。
茅氏井寒丹已化，玄宗碑断梦仍劳。
分明有个长生路，休向红尘叹二毛。','',''),('quantangshi-42430','建州节帅更代筵上献诗','王感化','quantangshi','','卷43','旌旗赴天台，溪山晓色开。
万家悲更喜，迎佛送如来。','',''),('quantangshi-42431','奉元宗命咏苑中白野鹊','王感化','quantangshi','','卷43','碧岩深洞恣游遨，天与芦花作羽毛。
要识此来栖宿处，上林琼树一枝高。','',''),('quantangshi-42432','句','王感化','quantangshi','','卷43','草中误认将军虎，山上曾为道士羊。','',''),('quantangshi-42433','元宗钓鱼无获进诗','李家明','quantangshi','','卷43','玉甃垂钩兴正浓，碧池春暖水溶溶。
凡鳞不敢吞香[饵]，知是君王合钓龙。','',''),('quantangshi-42434','咏卧牛','李家明','quantangshi','','卷43','曾遭甯戚鞭敲角，又被田单火燎身。
闲向斜阳嚼枯草，近来问喘为无人。','',''),('quantangshi-42435','题纸鸢止宋齐丘哭子','李家明','quantangshi','','卷43','安排唐祚革强吴，尽是先生作计谟。
一个孩儿{扌弃}不得，让皇百口合何如。','',''),('quantangshi-42436','咏皖公山','李家明','quantangshi','','卷43','龙舟轻颭锦帆风，正值宸游望远空。
回首皖公山色翠，影斜不到寿杯中。','',''),('quantangshi-42437','奉和圣制送邓王牧宣城','湯悅','quantangshi','','卷43','千里陵阳同[陕]服，凿门胙土寄亲贤。
曙烟已别黄金殿，晚照重登白玉筵。
江上浮光宜雨后，郡中远岫列窗前。
天心待报期年政，留与工师播管弦。','',''),('quantangshi-42438','早春寄华下同志','湯悅','quantangshi','','卷43','正是花时节，思君寝复兴。
市沽终不醉，春梦亦无凭。
岳面悬清雨，河心走浊冰。
东门一条路，离恨正相仍。','',''),('quantangshi-42439','鼎臣学士侍郎以东馆庭梅昔翰苑之毫末今复半枯向时同僚零落都尽素𩬇垂领兹唯二人感旧伤怀发于吟咏惠然好我不能无言輙次来韵攀和','湯悅','quantangshi','','卷43','忆见萌芽日，还怜合抱时。
旧欢如梦想，物态暗还移。
素艳今无几，朱颜亦自衰。
树将人共老，何暇更悲丝。','',''),('quantangshi-42440','再次前韵代梅答','湯悅','quantangshi','','卷43','托植经多稔，顷筐向盛时。
枝条虽已故，情分不曾移。
莫向堦前老，还同镜里衰。
更应怜堕叶，残吹挂虫丝。','',''),('quantangshi-42441','鼎臣学士侍郎楚金舍人学士以再伤庭梅诗同垂宠和清绝感叹情致俱深因成四十字陈谢','湯悅','quantangshi','','卷43','人物同迁谢，重成念旧悲。
连华得琼玖，合奏发埙篪。
余枿虽无取，残芳尚获知。
问君何所似，珍重杜[秋]诗。','',''),('quantangshi-42442','送钟员外','蕭彧','quantangshi','','卷43','丽汉金波满，当筵玉斚倾。
因思频聚散，几复换亏盈。
光彻离襟冷，声符别管清。
那堪还目此，两地倚楼情。','',''),('quantangshi-42443','送德林郎中学士赴东府','蕭彧','quantangshi','','卷43','离情折杨柳，此别异春哉。
含露东篱艳，泛香南浦杯。
惜持行次赠，留插醉中回。
暮齿如能制，玉山甘判颓。','',''),('quantangshi-42444','送钟员外','孫峴','quantangshi','','卷43','万物中萧洒，修篁独逸羣。
贞姿曾冒雪，高节欲凌云。
细韵风初发，浓烟日正曛。
因题偏惜别，不可暂无君。','',''),('quantangshi-42445','送钟员外','謝仲宣','quantangshi','','卷43','送人多折柳，唯我独吟松。
若保岁寒在，何妨霜雪重。
森梢逢静境，廓落见孤峰。
还似君高节，亭亭尠继踪。','',''),('quantangshi-42446','别诸同志','鍾蒨','quantangshi','','卷43','随阳来万里，点点度遥空。
影落长江水，声悲半夜风。
残秋辞绝漠，无定似惊蓬。
我有离羣恨，飘飘类此鸿。','',''),('quantangshi-42447','送德林郎中学士赴东府','喬舜','quantangshi','','卷43','掺袂向江头，朝宗势未休。
何人乘桂楫，之子过扬州。
飒飒翘沙雁，漂漂逐浪鸥。
欲知离别恨，半是泪和流。','',''),('quantangshi-42448','送钟员外','王沂','quantangshi','','卷43','静追苹末兴，况复值萧条。
猛势资新雁，寒声伴暮潮。
过山云散乱，经树叶飘颻。
今日烟江上，征帆望望遥。','',''),('quantangshi-42449','送德林郎中学士赴东府','陳元裕','quantangshi','','卷43','上善湛然秋，恩波洽帝猷。
谩言生险浪，岂爽见安流。
泛去星槎远，澄来月练浮。
滔滔对离酌，入洛称仙舟。','',''),('quantangshi-42450','宿山寺','孟貫','quantangshi','','卷43','溪山尽日行，方听远钟声。
入院逢僧定，登楼见月生。
露垂群木润，泉落一岩清。
此景关吾事，通宵寐不成。','',''),('quantangshi-42451','赠栖隐洞谭先生','孟貫','quantangshi','','卷43','先生双鬓华，深谷卧云霞。
不伐有巢树，多移无主花。
石泉春酿酒，松火夜煎茶。
因问山中事，如君有几家。','',''),('quantangshi-42452','归雁','孟貫','quantangshi','','卷43','春至衡阳雁，思归塞路长。
汀洲齐奋翼，霄汉共成行。
雪尽翻风暖，寒收度月凉。
直应到秋日，依旧返潇湘。','',''),('quantangshi-42453','春江送人','孟貫','quantangshi','','卷43','春江多去情，相去枕长汀。
数雁别湓浦，片帆离洞庭。
雨余沙草绿，云散岸峰青。
谁共观明月，渔歌夜好听。','',''),('quantangshi-42454','过秦岭','孟貫','quantangshi','','卷43','古今传此岭，高下势峥嵘。
安得青山路，化为平地行。
苍苔留虎迹，碧树障溪声。
欲过一回首，踟蹰无限情。','',''),('quantangshi-42455','送吴梦誾归闽','孟貫','quantangshi','','卷43','瓯闽在天末，此去整行衣。
久客逢春尽，思家冒暑归。
海云添晚景，山瘴灭晴晖。
相忆吟偏苦，不堪书信稀。','',''),('quantangshi-42456','山中夏日','孟貫','quantangshi','','卷43','深山宜避暑，门户映岚光。
夏木荫溪路，昼云埋石牀。
心源澄道静，衣葛蘸泉凉。
算得红尘里，谁知此兴长。','',''),('quantangshi-42457','宿故人江居','孟貫','quantangshi','','卷43','渡口树冥冥，南山渐隐青。
渔舟归旧浦，鸥鸟宿前汀。
静榻悬灯坐，闲门对浪扃。
相思频到此，几番醉还醒。','',''),('quantangshi-42458','寄伍乔','孟貫','quantangshi','','卷43','蹉跎春又晚，天末信来迟。
长忆分携日，正当摇落时。
独游饶旅恨，多事失归期。
君看前溪树，山禽巢几枝。','',''),('quantangshi-42459','山中访人不遇','孟貫','quantangshi','','卷43','负琴兼杖藜，特地过岩西。
已见竹轩闭，又闻山鸟啼。
长松寒倚谷，细草暗连溪。
久立无人事，烟霞归路迷。','',''),('quantangshi-42460','赠隐者','孟貫','quantangshi','','卷43','世路争名利，深山独结茅。
安情自得所，非道岂相交。
百尺松当户，千年鹤在巢。
知君于此景，未欲等闲抛。','',''),('quantangshi-42461','寄暹上人','孟貫','quantangshi','','卷43','闻罢城中讲，来安顶上禅。
夜灯明石室，清磐出岩泉。
欲访慙多事，相思恨隔年。
终期息尘虑，接话虎溪边。','',''),('quantangshi-42462','江边闲步','孟貫','quantangshi','','卷43','闲来南渡口，迤逦看江枫。
一路波涛畔，数家芦苇中。
远汀排晚树，深浦漾寒鸿。
吟罢慵回首，此情谁与同。','',''),('quantangshi-42463','过王逸人园林','孟貫','quantangshi','','卷43','谷口何时住，烟霞一径深。
水声离远洞，山色出疎林。
雪彩从沾鬓，年光不计心。
自言人少到，犹喜我来寻。','',''),('quantangshi-42464','寄李处士','孟貫','quantangshi','','卷43','僧话磻溪叟，平生重赤松。
夜堂悲蟋蟀，秋水老芙蓉。
吟坐倦垂钓，闲行多倚筇。
闻名来已久，未得一相逢。','',''),('quantangshi-42465','夏日寄史处士','孟貫','quantangshi','','卷43','掩关苔满地，终日坐腾腾。
暑气冷衣葛，暮云催烛灯。
寂寥知得趣，疎嬾似无能。
还忆旧游否，何年别杜陵。','',''),('quantangshi-42466','夏日登瀑顶寺因寄诸知己','孟貫','quantangshi','','卷43','曾于尘里望，此景在烟霄。
岩静水声近，山深暑气遥。
杖藜青石路，煮茗白云樵。
寄语为郎者，谁能访寂寥。','',''),('quantangshi-42467','怀果上人','孟貫','quantangshi','','卷43','拥锡南游去，名香几处焚。
别来无远信，多恐在深云。
好月曾同步，幽香省共闻。
相思不相见，林下叶纷纷。','',''),('quantangshi-42468','寄故园兄弟','孟貫','quantangshi','','卷43','久与乡关阻，风尘损旧衣。
水思和月泛，山忆共僧归。
林想添邻舍，溪应改钓矶。
弟兄无苦事，不用别庭闱。','',''),('quantangshi-42469','早秋吟眺','孟貫','quantangshi','','卷43','新秋初雨后，独立对遥山。
去鸟望中没，好云吟里还。
长年慙道薄，明代取身闲。
从有西征思，园林嬾闭关。','',''),('quantangshi-42470','送江为归岭南','孟貫','quantangshi','','卷43','旧山临海色，归路到天涯。
此别各多事，重逢是几时。
江行晴望远，岭宿夜吟迟。
珍重南方客，清风失所思。','',''),('quantangshi-42471','山中答友人','孟貫','quantangshi','','卷43','偶爱春山在，因循值暑时。
风尘非所愿，泉石本相宜。
坐久松阴转，吟余蝉韵移。
自慙疎野甚，多失故人期。','',''),('quantangshi-42472','山斋早秋雨中','孟貫','quantangshi','','卷43','深居少往还，卷箔早秋间。
雨洒吟蝉树，云藏啸狖山。
炎蒸如便退，衣葛亦堪闲。
静坐得无事，酒巵聊畅颜。','',''),('quantangshi-42473','送人游南越','孟貫','quantangshi','','卷43','孑然南越去，替尔畏前程。
见说路岐嶮，不通车马行。
瘴烟迷海色，岭树带猨声。
独向山家宿，多应乡思生。','',''),('quantangshi-42474','酬东溪史处士','孟貫','quantangshi','','卷43','咫尺东溪路，年来偶访迟。
泉声迷夜雨，花片落空枝。
石径逢僧出，山牀见鹤移。
贫斋有琴酒，曾许月圆期。','',''),('quantangshi-42475','秋江送客','孟貫','quantangshi','','卷43','秋风楚江上，送子话游遨。
远水宿何处，孤舟春夜涛。
浦云沈雁影，山月照猨嗥。
莫为饥寒苦，便成名利劳。','',''),('quantangshi-42476','寄山中高逸人','孟貫','quantangshi','','卷43','烟霞多放旷，吟啸是寻常。
猨共摘山果，僧邻住石房。
蹑云双屐冷，采药一身香。
我忆相逢夜，松潭月色凉。','',''),('quantangshi-42477','怀友人','孟貫','quantangshi','','卷43','浮世况多事，飘流每叹君。
路岐何处去，消息几时闻。
吟里落秋叶，望中生暮云。
孤怀谁慰我，夕鸟自成群。','',''),('quantangshi-42478','送人归别业','孟貫','quantangshi','','卷43','别业五湖上，春残去路赊。
还寻旧山水，重到故人家。
门径掩芳草，园林落异花。
君知钓矶在，犹喜有生涯。','',''),('quantangshi-42479','冬日登江楼','孟貫','quantangshi','','卷43','高楼临古岸，野步晚来登。
江水因寒落，山云为雪凝。
远村虽入望，危槛不堪凭。
亲老未归去，乡愁徒自兴。','',''),('quantangshi-42480','寄张山人','孟貫','quantangshi','','卷43','草堂南涧边，有客啸云烟。
扫叶林风后，拾薪山雨前。
野桥通竹径，流水入芝田。
琴月相亲夜，更深恋不眠。','',''),('quantangshi-42481','杜鹃花','成彥雄','quantangshi','','卷43','杜鹃花与鸟，怨艳两何赊。
疑是口中血，滴成枝上花。
一声寒食夜，数朵野僧家。
谢豹出不出，日迟迟又斜。','',''),('quantangshi-42482','江上枫','成彥雄','quantangshi','','卷43','江枫自蓊郁，不竞松筠力。
一叶落渔家，残阳带秋色。','',''),('quantangshi-42483','夜夜曲','成彥雄','quantangshi','','卷43','自从君去夜，锦幌孤兰麝。
欹枕对银缸，秦筝绿窗下。','',''),('quantangshi-42484','村行','成彥雄','quantangshi','','卷43','暧暧村烟暮，牧童出深坞。
骑牛不顾人，吹笛寻山去。','',''),('quantangshi-42485','煎茶','成彥雄','quantangshi','','卷43','岳寺春深睡起时，虎跑泉畔思迟迟。
蜀茶倩个云僧碾，自拾枯松三四枝。','',''),('quantangshi-42486','松','成彥雄','quantangshi','','卷43','大夫名价古今闻，盘屈孤贞更出羣。
将谓岭头闲得了，夕阳犹挂数枝云。','',''),('quantangshi-42487','新燕','成彥雄','quantangshi','','卷43','才离海岛宿江滨，应梦笙歌作近邻。
减省雕梁竝头语，画堂中有未归人。','',''),('quantangshi-42488','会友不至','成彥雄','quantangshi','','卷43','王孙还是负佳期，玉马追游日渐西。
独上郊原人不见，鹧鸪飞过落花溪。','',''),('quantangshi-42489','惜花','成彥雄','quantangshi','','卷43','忘餐为恋满枝红，锦障频移护晚风。
客散酒酣归未得，栏边独立月明中。','',''),('quantangshi-42490','中秋月','成彥雄','quantangshi','','卷43','王母妆成镜未收，倚栏人在水精楼。
笙歌莫占清光尽，留与溪翁一钓舟。','',''),('quantangshi-42491','暮春日宴溪亭','成彥雄','quantangshi','','卷43','寒食寻芳游不足，溪亭还醉绿杨烟。
谁家花落临流树，数片残红到槛前。','',''),('quantangshi-42492','晓','成彥雄','quantangshi','','卷43','列宿回元朝北极，爽神曦露滴楼台。
佳人卷箔临阶砌，笑指庭花昨夜开。','',''),('quantangshi-42493','夕','成彥雄','quantangshi','','卷43','台榭沈沈禁漏初，麝烟红蜡透虾须。
雕笼鹦鹉将栖宿，不许鵶鬟转辘轳。','',''),('quantangshi-42494','露','成彥雄','quantangshi','','卷43','银河昨夜降醍醐，洒遍坤维万象苏。
疑是鲛人曾泣处，满池荷叶捧真珠。','',''),('quantangshi-42495','游紫阳宫','成彥雄','quantangshi','','卷43','古殿烟霞簇画屏，直疑踪迹到蓬瀛。
碧桃满地眠花鹿，深院松窗捣药声。','',''),('quantangshi-42496','除夜','成彥雄','quantangshi','','卷43','铜龙看却送春来，莫惜颠狂酒百杯。
吟鬓就中专拟白，那堪更被二更催。','',''),('quantangshi-42497','元日','成彥雄','quantangshi','','卷43','戴星先捧祝尧觞，镜里堪惊两鬓霜。
好是灯前偷失笑，屠苏应不得先尝。','',''),('quantangshi-42498','寒夜吟','成彥雄','quantangshi','','卷43','洞房脉脉寒宵永，烛影香消金凤冷。
猧儿睡魇唤不醒，满窗扑落银蟾影。','',''),('quantangshi-42499','柳枝辞九首 一','成彥雄','quantangshi','','卷43','轻笼小径近谁家，玉马追风翠影斜。
爱把长条恼公子，惹他头上海棠花。','',''),('quantangshi-42500','柳枝辞九首 二','成彥雄','quantangshi','','卷43','鹅黄剪出小花钿，缀上芳枝色转鲜。
饮散无人收拾得，月明阶下伴秋千。','',''),('quantangshi-42501','柳枝辞九首 三','成彥雄','quantangshi','','卷43','东君爱惜与先春，草泽无人处也新。
委嘱露华并细雨，莫教迟日惹风尘。','',''),('quantangshi-42502','柳枝辞九首 四','成彥雄','quantangshi','','卷43','句践初迎西子年，琉璃为箒扫溪烟。
至今不改当时色，留与王孙系酒船。','',''),('quantangshi-42503','柳枝辞九首 五','成彥雄','quantangshi','','卷43','绿杨移傍小亭栽，便拥穠烟拨不开。
谁把金刀为删掠，放教明月入窗来。','',''),('quantangshi-42504','柳枝辞九首 六','成彥雄','quantangshi','','卷43','远接关河高接云，雨余洗出半天津。
牡丹不用相轻薄，自有清阴覆得人。','',''),('quantangshi-42505','柳枝辞九首 七','成彥雄','quantangshi','','卷43','掩映莺花媚有余，风流才调比应无。
朝朝奉御临池上，不羡青松拜大夫。','',''),('quantangshi-42506','柳枝辞九首 八','成彥雄','quantangshi','','卷43','王孙宴罢曲江池，折取春光伴醉归。
怪得美人争鬬乞，要他穠翠染罗衣。','',''),('quantangshi-42507','柳枝辞九首 九','成彥雄','quantangshi','','卷43','残照林梢袅数枝，能折醉客上金堤。
马娇如练缨如火，瑟瑟阴中步步嘶。','',''),('quantangshi-42508','句','成彥雄','quantangshi','','卷43','莎草放茵深护砌，海榴喷火巧横墙。
纹鳞引子跳银海，紫燕呼雏语画梁。','',''),('quantangshi-42509','寄禅月大师','周庠','quantangshi','','卷43','昨日尘游到几家，就中偏省近宣麻。
水田铺座时移画，金地谭空说尽沙。
傍竹欲添犀浦石，栽松更碾味江茶。
有时捻得休公卷，倚柱闲吟见落霞。','',''),('quantangshi-42510','寄禅月大师','張格','quantangshi','','卷43','龙华咫尺断来音，日夕空驰咏德心。
禅月字清师号别，寿春诗古帝恩深。
画成罗汉惊三界，书似张颠直万金。
莫倚名高忘故旧，晓晴闲步一相寻。','',''),('quantangshi-42511','赠禅月大师','王鍇','quantangshi','','卷43','长爱吾师性自然，天心白月水中莲。
神通力遍恒沙外，诗句名高八米前。
寻访不闻朝振锡，修行唯说夜安禅。
太平时节俱无事，莫惜时来话草玄。','',''),('quantangshi-42512','奉诏赋蜀主降唐','牛希濟','quantangshi','','卷43','满城文武欲朝天，不觉邻师犯塞烟。
唐主再悬新日月，蜀王难保旧山川。
非干将相扶持拙，自是君臣数尽年。
古往今来亦如此，几曾欢笑几潸然。','',''),('quantangshi-42513','蜀犸引 一','馮涓','quantangshi','','卷43','昂藏大步蚕丛国，曲颈微伸高九尺。
卓女窥窗莫我知，严仙据案何曾识。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-42514','蜀犸引 二','馮涓','quantangshi','','卷43','自古皆传蜀道难，尔何能过拔蛇山。
忽惊登得鸡翁碛，又恐碍着鹿头关。','',''),('quantangshi-42515','句','馮涓','quantangshi','','卷43','不随俗物皆成土，只待良时却补天。
釜鱼化作池中物，木履浮为天际船。','',''),('quantangshi-42516','从幸秦川赋鸷兽诗','李浩弼','quantangshi','','卷43','岩下年年自寝讹，生灵餐尽意如何。
爪牙众后民随减，溪壑深来骨已多。
天子纪纲犹被弄，客人穷独固难过。
长途莫怪无人迹，尽被山王棱杀他。','',''),('quantangshi-42517','批子弟理旧居状','楊玢','quantangshi','','卷43','四邻侵我我从伊，毕竟须思未有时。
试上含元殿基望，秋风秋草正离离。','',''),('quantangshi-42518','登慈恩寺塔','楊玢','quantangshi','','卷43','紫云楼下曲江平，鸦噪残阳麦陇青。
莫上慈恩最高处，不堪看又不堪听。','',''),('quantangshi-42519','遣歌妓','楊玢','quantangshi','','卷43','垂老无端用意乖，谁知道侣厌清斋。
如今又采蘼芜去，辜负张君绣靸鞋。','',''),('quantangshi-42520','和题劒门','韓昭','quantangshi','','卷43','闭关防老寇，孰敢振威棱。
险固疑天设，山河自古凭。
三川奚所赖，双劒最堪矜。
鸟道微通处，烟霞锁百层。','',''),('quantangshi-42521','从幸秦川过白卫献诗','韓昭','quantangshi','','卷43','吾王巡狩为安边，此去秦亭尚数千。
夜照路岐山店火，晓通消息戍瓶烟。
为云巫峡虽神女，跨凤秦楼是谪仙。
八骏似龙人似虎，何愁飞过大漫天。','',''),('quantangshi-42522','记皂江堕水事','楊鼎夫','quantangshi','','卷43','青城山峭皂江寒，欲度当时作等闲。
棹逆狂风趋近岸，舟逢怪石碎前湾。
手携弱杖仓皇处，命出洪涛顷刻间。
今日深恩无以报，令人羞记雀衔环。','',''),('quantangshi-42523','题张道隐太山祠画龙','蔣貽恭','quantangshi','','卷43','世人空解竞丹青，惟子通玄得墨灵。
应有鬼神看下笔，岂无风雨助成形。
威疑喷浪归沧海，势欲拏云上杳冥。
静闭绿堂深夜后，晓来帘幕似闻腥。','',''),('quantangshi-42524','咏蚕','蔣貽恭','quantangshi','','卷43','辛勤得茧不盈筐，灯下缫丝恨更长。
着处不知来处苦，但贪衣上绣鸳鸯。','',''),('quantangshi-42525','渔父歌三首 一','李珣','quantangshi','','卷43','水接衡门十里余，信船归去卧看书。
轻爵禄，慕玄虚，莫道渔人只为鱼。','',''),('quantangshi-42526','渔父歌三首 二','李珣','quantangshi','','卷43','避世垂纶不记年，官高争得似君闲。
倾白酒，对青山，笑指柴门待月还。','',''),('quantangshi-42527','渔父歌三首 三','李珣','quantangshi','','卷43','棹警鸥飞水溅袍，影侵潭面柳垂条。
终日醉，绝尘劳，曾见钱塘八月涛。','',''),('quantangshi-42528','感秃鹙潜吟','顧敻','quantangshi','','卷43','昔日曾看瑞应图，万般祥端不如无。
摩诃池上分明见，仔细看来是那鹕。','',''),('quantangshi-42529','与杜光庭','張令問','quantangshi','','卷43','试问朝中为宰相，何如林下作神仙。
一壶美酒一炉药，饱听松风白昼眠。','',''),('quantangshi-42530','题黄居寀秋山图','徐光溥','quantangshi','','卷43','天与黄筌艺奇绝，笔精回感重瞳悦。
运思潜通造化工，挥毫定得神仙诀。
秋来奉诏写秋山，写在轻绡数幅间。
高低向背无遗势，重峦叠嶂何孱颜。
目想心存妙尤极，研巧核能状不得。
珍禽异兽皆自驯，奇花怪木非因植。
崎岖石磴绝游踪，薄雾冥冥藏半峰。
娑萝掩映迷仙洞，薜荔累垂缴古松。
月槛参桥□，僧老坐搘筇。
屈原江上婵娟竹，陶潜篱下芳菲菊。
良宵祗恐鹧鸪啼，晴波但见鸳鸯浴。
暮烟羃羃鏁村坞，一叶扁舟横野度。
飒飒白苹欲起风，黯黯红蕉犹带雨。
曲沼芙蓉香馥郁，长汀芦荻花{艹/糓}蓛。
雁过孤峰帖远青，鹿傍小溪饮残绿。
秋山秀兮秋江静，江光山色相辉映。
雪迸飞泉溅钓矶，云分落叶拥樵径。
张璪松石徒称奇，边鸾花鸟何足窥。
白旻鹰逞凌风势，薛稷鹤夸警露姿。
方原画山空巉岩，峭壁枯槎人见嫌。
孙位画水多汹涌，惊湍怒涛人见恐。
若教对此定妍媸，必定伏膺怀愧悚。
再三展向冕旒侧，便是移山回磵力。
大李小李灭声华，献之恺之无颜色。
仿髴垂纶渭水滨，吾皇覩之思良臣。
依稀荷锸傅岩野，吾皇覩之求贤者。
从兹仄展复悬旌，宵衣旰食安天下。
才当老人星应候，愿与南山俱献寿。
微臣稽首贡长歌，丹青景化同天和。','',''),('quantangshi-42531','同刘侍郎咏笋','徐光溥','quantangshi','','卷43','迸出班犀数十株，更添幽景向蓬壶。
出来似有凌云势，用作丹梯得也无。','',''),('quantangshi-42532','贯休应梦罗汉画歌','歐陽炯','quantangshi','','卷43','西岳高僧名贯休，孤情峭拔凌清秋。
天教水墨画罗汉，魁岸古容生笔头。
时捎大绢泥高壁，闭目焚香坐禅室。
忽然梦里见真仪，脱下袈裟点神笔。
高握节腕当空掷，窸窣毫端任狂逸。
逡巡便是两三躯，不似画工虚费日。
怪石安拂嵌复枯，真僧列坐连跏[趺]。
形如瘦鹤精神健，顶似伏犀头骨麤。
倚松根，傍岩缝，曲录腰身长欲动。
看经弟子拟闻声，瞌睡山童疑有梦。
不知夏腊几多年，一手搘颐偏袒肩。
口开或若共人语，身定复疑初坐禅。
案前卧象低垂鼻，崖畔戏猿斜展臂。
芭蕉花里刷轻红，苔藓文中晕深翠。
硬筇杖，矮松牀，雪色眉毛一寸长。
绳开梵夹两三片，线补衲衣千万行。
林间乱叶纷纷堕，一印残香断烟火。
皮穿木屐不曾拖，笋织蒲团镇长坐。
休公休公逸艺无人加，声誉喧喧遍海涯。
五七字句一千首，大小篆书三十家。
唐朝历历多名士，萧子云兼吴道子。
若将书画比休公，只恐当时浪生死。
休公休公始自江南来入秦，于今到蜀无交亲。
诗名画手皆奇绝，覰你凡人争是人。
瓦棺寺里维摩诘，舍卫城中辟支佛。
若将此画比量看，总在人间为第一。','',''),('quantangshi-42533','题景焕画应天寺壁天王歌','歐陽炯','quantangshi','','卷43','锦城东北黄金地，故迹何人兴此寺。
白眉长老重名公，曾识会稽山处士。
寺门左壁图天王，威仪部从来何方。
鬼神怪异满壁走，当檐飒飒生秋光。
我闻天王分理四天下，水晶宫殿琉璃瓦。
彩杖时驱狒𤝞装，金鞭频策骐驎马。
毗沙大像何光辉，手擎巨塔凌云飞。
地神对出宝瓶子，天女倒披金缕衣。
唐朝说着名公画，周昉毫端善图写。
张僧繇是有神人，吴道子称无敌者。
奇哉妙手传孙公，能如此地留神踪。
斜窥小鬼怒双目，直倚越狼高半胸。
宝冠动总生威容，趋跄左右来倾恭。
臂横鹰爪尖纤利，腰缠虎皮斑剥红。
飘飘但恐入云中，步骤还疑归海东。
蟒蛇拖得浑身堕，精魅搦来双眼空。
当时此艺实难有，镇在宝坊称不朽。
东边画了空西边，留与后人教敌手。
后人见者皆心惊，尽为名公不敢争。
谁知未满三十载，或有异人来间生。
匡山处士名称朴，头骨高奇连五岳。
曾持象简累为官，又有蛇珠常在握。
昔年长老遇奇踪，今日门师识景公。
兴来便请泥高壁，乱抢笔头如疾风。
逡巡队仗何颠逸，散漫奇形皆涌出。
交加器械满虚空，两面或然如鬬敌。
圣王怒色览东西，劒刃一挥皆整齐。
腕头狮子咬金甲，脚底夜叉击络鞮。
马头壮健多筋节，乌觜弯环如屈铁。
遍身虵虺乱纵横，遶颔髑髅干孑裂。
眉麤眼竖发如锥，怪异令人不可知。
科头巨卒欲生鬼，半面女郎安小儿。
况闻此寺初兴置，地脉沈沈当正气。
如何请得二山人，下笔咸成千古事。
君不见明皇天宝年，画龙致雨非偶然。
包含万象藏心里，变现百般生眼前。
后来画品列名贤，唯此二人堪比肩。
人间是物皆求得，此样欲于何处传。
尝忧壁底生云雾，揭起寺门天上去。','',''),('quantangshi-42534','渔父歌二首 一','歐陽炯','quantangshi','','卷43','摆脱尘机上钓船，免教荣辱有流年。
无系绊，没愁煎，须信船中有散仙。','',''),('quantangshi-42535','渔父歌二首 二','歐陽炯','quantangshi','','卷43','风浩寒溪照胆明，小君山上玉蟾生。
荷露坠，翠烟轻，拨刺游鱼几处惊。','',''),('quantangshi-42536','大游仙诗','歐陽炯','quantangshi','','卷43','赤城霞起武陵春，桐柏先生解守真。
白石桥高曾纵步，朱阳馆静每存神。
囊中隐诀多仙术，肘后方书济俗人。
自领蓬莱都水监，只忧沧海变成尘。','',''),('quantangshi-42537','杨柳枝','歐陽炯','quantangshi','','卷43','软碧摇烟似送人，映花时把翠蛾嚬。
青青自是风流主，慢飒金丝待洛神。','',''),('quantangshi-42538','句','歐陽炯','quantangshi','','卷43','古人重到今人爱，万局都无一局同。','',''),('quantangshi-42539','感怀诗','劉義度','quantangshi','','卷43','昨日方髽髻，如今满颔髯。
紫阁无心恋，青山有意潜。','',''),('quantangshi-42540','同徐学士咏笋','劉羲叟','quantangshi','','卷43','徐徐出土非人种，枝叶难投日月壶。
为是因缘生此地，从他长养譬如无。','',''),('quantangshi-42541','复留侯从効问南汉刘岩改名䶮字音义','詹敦仁','quantangshi','','卷43','伏羲初画卦，苍氏乃制字。
点画有偏旁，阴阳贵协比。
古者不嫌名，周公始称讳。
始讳犹未酷，后习转多忌。
或援他代易，或变文回避。
滥觞久滋蔓，伤心日益炽。
孙休命子名，吴国尊王意。
𩅦𦯶𩅔{覀/升}僻，{壴臣}昷𥨆𡚕异。
梁复踵已非，时亦迹旧事。
𡽏杰自其一，蜀闯是其二。
鄙哉化䁈名，陋矣𡏜䵎义。
大唐有天下，武后拥神器。
私制迄无取，古音实相类。
●●●囝星，●●{厓厂=}●埊。
●圀及曌●，作史难详备。
唐祚值倾危，刘䶮怀僭伪。
吁嗟毒蛟辈，睥睨飞龙位。
䶮岩虽同音，形体殊乖致。
废学愧未弘，来问辱不弃。
奇字难雄博，摛文伏韩智。
因诵鄙所闻，敢布诸下吏。','',''),('quantangshi-42542','柳堤诗','詹敦仁','quantangshi','','卷43','种稻三十顷，种柳百余[株]。
稻可供飦粥，柳可爨庖厨。
息耒柳阴下，读书稻田隅。
以乐尧舜道，同是耕莘夫。','',''),('quantangshi-42543','劝王氏入贡宠予以官作辞命篇','詹敦仁','quantangshi','','卷43','争霸图王事总非，中原失统可伤悲。
从来宾主如邮传，胜负干戈似局棊。
周粟纵荣宁忍食，葛庐频顾谩劳思。
江山有待早归去，好向鹪林择一枝。','',''),('quantangshi-42544','余迁泉山城留侯招游郡圃作此','詹敦仁','quantangshi','','卷43','当年巧匠制茅亭，台馆翚飞匝郡城。
万竈貔貅戈甲散，千家罗绮管弦鸣。
柳腰舞罢香风度，花脸妆匀酒晕生。
试问亭前花与柳，几番衰谢几番荣。','',''),('quantangshi-42545','留侯受南唐节度使知郡事辟予为属以诗谢之','詹敦仁','quantangshi','','卷43','晋江江畔趁春风，耕破云山几万重。
两足一犂无外事，使君何啻五侯封。','',''),('quantangshi-42546','遣子访刘乙','詹敦仁','quantangshi','','卷43','扫石耕山旧子真，布衣草履自随身。
石崖壁立题诗处，知是当年凤阁人。','',''),('quantangshi-42547','永嘉乱衣冠南度流落南泉作忆昔吟','詹琲','quantangshi','','卷43','忆昔永嘉际，中原板荡年。
衣冠坠涂炭，舆辂染腥膻。
国势多危厄，宗人苦播迁。
南来频洒泪，渴骥每思泉。','',''),('quantangshi-42548','癸卯闽乱从弟监察御史敬凝迎仕别作','詹琲','quantangshi','','卷43','一别几经春，栖迟晋水滨。
鹡鸰长在念，鸿雁忽来宾。
五斗嫌腰折，朋山刺眼新。
善辞如复我，四海五湖身。','',''),('quantangshi-42549','追和秦隐君辞荐之韵上陈侯乞归凤山','詹琲','quantangshi','','卷43','谁言悦口是甘肥，独酌鹅儿噉翠微。
蝇利薄于青纸扇，羊裘暖甚紫罗衣。
心随倦鸟甘栖宿，目送征鸿远奋飞。
击壤太平朝野客，凤山深处□生辉。','',''),('quantangshi-42550','云','幸夤遜','quantangshi','','卷43','因登巨石知来处，勃勃元生绿藓痕。
静即等闲藏草木，动时顷刻遍干坤。
横天未必朋元恶，捧日还曾瑞至尊。
不独朝朝在巫峡，楚王何事谩劳魂。','',''),('quantangshi-42551','句','幸夤遜','quantangshi','','卷43','苦教作镇居中国，争得泥金在泰山。
才闻暖律先偷眼，既待和风始展眉。
蒙君知重惠琼实，薄起金刀钉玉深。
嚼处春冰敲齿冷，咽时雪液沃心寒。
深妆玉瓦平无壠，乱拂芦花细有声。
日回禽影穿疎木，风递猨声入小楼。','',''),('quantangshi-42552','诗','丁元和','quantangshi','','卷43','九重天子人中贵，五等诸侯阃外尊。
争似布衣云水客，不将名字挂干坤。','',''),('quantangshi-42553','咏蜀都城上芙蓉花','張立','quantangshi','','卷43','四十里城花发时，锦囊高下照坤维。
虽妆蜀国三秋色，难入豳风七月诗。','',''),('quantangshi-42554','又咏蜀都城上芙蓉花','張立','quantangshi','','卷43','去年今日到城都，城上芙蓉锦绣舒。
今日重来旧游处，此花顦顇不如初。','',''),('quantangshi-42555','句','張立','quantangshi','','卷43','朝廷不用忧巴蜀，称霸何曾是蜀人。','',''),('quantangshi-42556','括苍山','劉昭禹','quantangshi','','卷43','尽日行方半，诸山直下看。
白云随步起，危径极天盘。
瀑顶桥形小，溪边店影寒。
往来空太息，玄鬓改非难。','',''),('quantangshi-42557','忆天台山','劉昭禹','quantangshi','','卷43','常记游灵境，道人情不低。
岩房容偃息，天路许相携。
霞散曙峰外，虹生凉瀑西。
何当尘役了，重去听猨啼。','',''),('quantangshi-42558','冬日暮国清寺留题','劉昭禹','quantangshi','','卷43','天台山下寺，冬暮景如屏。
树密风长在，年深像有灵。
高钟疑到月，远烧欲连星。
因共真僧话，心中万虑宁。','',''),('quantangshi-42559','灵溪观','劉昭禹','quantangshi','','卷43','鳌海西边地，宵吟景象宽。
云开孤月上，瀑喷一山寒。
人异发常绿，草灵秋不干。
无由此栖息，魂梦在长安。','',''),('quantangshi-42560','怀华山隐者','劉昭禹','quantangshi','','卷43','先生入太华，杳杳绝良音。
秋梦有时见，孤云无处寻。
神清峰顶立，衣冷瀑边吟。
应笑干名者，六街尘土深。','',''),('quantangshi-42561','赠惠律大师','劉昭禹','quantangshi','','卷43','秋是忆山日，禅窗露洒余。
几悬华顶梦，应寄沃洲书。
风月资吟笔，杉篁笼静居。
满城谁不重，见着紫衣初。','',''),('quantangshi-42562','经费冠卿旧隐','劉昭禹','quantangshi','','卷43','节高终不起，死恋九华山。
圣主情何切，孤云性本闲。
名传中国外，坟在乱松间。
依约曾栖处，斜阳鸟自还。','',''),('quantangshi-42563','闻蝉','劉昭禹','quantangshi','','卷43','一雨一番晴，山林冷落青。
莫侵残日噪，正在异乡听。
孤馆宿漳浦，扁舟离洞庭。
年年当此际，那免鬓凋零。','',''),('quantangshi-42564','送休公归衡','劉昭禹','quantangshi','','卷43','草履初登南岳船，铜瓶犹贮北山泉。
衡阳旧寺春归晚，门锁寒潭几树蝉。','',''),('quantangshi-42565','句','劉昭禹','quantangshi','','卷43','句向夜深得，心从天外归。
危楼聊侧耳，高柳又鸣蝉。
藓色围波井，花阴上竹楼。
对面电瞋树，当街雨趁人。
春光怀玉阙，万里起初程。
江上呼风去，天边挂席飞。
漆灯寻黑洞，之字上危峰。','',''),('quantangshi-42566','铜柱辞','李宏臯','quantangshi','','卷43','招灵铸柱垂英烈，手执干戈征百越。
诞今铸柱庇黔黎，指画风雷开五溪。
五溪之险不足恃，我旅争登若平地。
五溪之众不足平，我师轻蹑如春冰。
溪人畏威思纳质，弃污归明求立誓。
誓山川兮告鬼神，保子孙兮千万春。','',''),('quantangshi-42567','题桃源','李宏臯','quantangshi','','卷43','山翠参差水渺茫，秦人昔在楚封[疆]。
当时避世干坤窄，此地安家日月长。
草色几经坛杏老，岩花犹带涧桃香。
他年倘遂平生志，来着霞衣侍玉皇。','',''),('quantangshi-42568','李臯试诗','何仲舉','quantangshi','','卷43','似玉来投狱，抛家去就枷。
可怜两片木，夹却一枝花。','',''),('quantangshi-42569','句','何仲舉','quantangshi','','卷43','碧云章句才离手，紫府神仙尽点头。
树迎高鸟归深野，云傍斜阳过远山。','',''),('quantangshi-42570','畊夫谣','徐仲雅','quantangshi','','卷43','张绪逞风流，王衍事轻薄。
出门逢畊夫，颜色必不乐。
肥肤如玉洁，力拗丝不折。
半日无畊夫，此辈总饿杀。','',''),('quantangshi-42571','赠齐己','徐仲雅','quantangshi','','卷43','我唐有僧号齐己，未出家时宰相器。
爰见梦中逢五丁，毁形自学无生理。
骨瘦神清风一襟，松老霜天鹤病深。
一言悟得生死海，芙蓉吐出琉璃心。
闷见有唐风雅缺，敲破冰天飞白雪。
清塞清江却有灵，遗魂泣对荒郊月。
格何古，天工未生谁知主。
混沌凿开鸡子黄，散作纯风如胆苦。
意何新，织女星机挑白云。
真宰夜来调暖律，声声吹出嫩青春。
调何雅，涧底孤松秋雨洒。
嫦娥月里学步虚，桂风吹落玉山下。
语何奇，血泼干坤龙战时。
祖龙跨海日方出，一鞭风雨万山飞。
己公己公道如此，浩浩寰中如独自。
一簟松风冷如冰，长伴巢由伸脚睡。','',''),('quantangshi-42572','赠江处士','徐仲雅','quantangshi','','卷43','门在松阴里，山僧几度过。
药灵丸不大，棊妙子无多。
薄雾笼寒径，残风恋绿萝。
金乌兼玉兔，年几奈公何。','',''),('quantangshi-42573','东华观偃松','徐仲雅','quantangshi','','卷43','半已化为石，有灵通碧湘。
生逢尧雨露，老直汉风霜。
月滴蟾心水，龙遗脑骨香。
始于毫末后，曾见几兴亡。','',''),('quantangshi-42574','咏椶树','徐仲雅','quantangshi','','卷43','叶似新蒲绿，身如乱锦缠。
任君千度剥，意气自冲天。','',''),('quantangshi-42575','宫词','徐仲雅','quantangshi','','卷43','内人晓起怯春寒，轻揭珠帘看牡丹。
一把柳丝收不得，和风搭在玉栏杆。','',''),('quantangshi-42576','句','徐仲雅','quantangshi','','卷43','屋面尽生人耳朵，篱头多是老翁须。
平分造化双苞去，拆破春风两面开。
云路半开千里月，洞门斜掩一天春。
凿开青帝春风国，移下姮娥夜月楼。
珠玑影冷偏黏草，兰麝香浓却损花。
山色晓堆罗黛雨，草梢春戛麝香风。
衰兰寂寞含愁绿，小杏妖娆弄色红。
旁搜水脉湘心满，遍揭泉根梵底通。
水□滴残青□瘦，石脂倾尽白云空。
深浦送回芳草日，急滩牵断绿杨风。
藕梢逆入银塘里，苹迹潜来玉井中。
败菊篱疎临野渡，落梅村冷隔江枫。
剪开净涧分苗稼，划破涟漪下钓筒。','',''),('quantangshi-42577','分水岭','伍彬','quantangshi','','卷43','前贤功及物，禹后杳难俦。
不改古今色，平分南北流。
寒冲山影岸，清绕荻花洲。
尽是朝宗去，潺潺早晚休。','',''),('quantangshi-42578','句','伍彬','quantangshi','','卷43','稚子出看莎径没，渔翁来报竹桥流。
踪迹未辞鸳鹭客，梦魂先到鹧鸪村。','',''),('quantangshi-42579','留宿廖融山斋','楊徽之','quantangshi','','卷43','清和春尚在，欢醉日何长。
谷鸟随柯转，庭花夺酒香。
初晴岩翠滴，向晚树阴凉。
别有堪吟处，相留宿草堂。','',''),('quantangshi-42580','句','楊徽之','quantangshi','','卷43','新霜染枫叶，皎月借芦花。
废宅寒塘水，荒坟宿草烟。','',''),('quantangshi-42581','登祝融峰','王元','quantangshi','','卷43','草叠到孤顶，身齐高鸟翔。
势疑撞翼轸，翠欲滴潇湘。
云湿幽崖滑，风梳古木香。
晴空聊纵目，杳杳极穷荒。','',''),('quantangshi-42582','怀翁宏','王元','quantangshi','','卷43','独夜思君切，无人知此情。
沧州归未得，华发别来生。
孤馆木初落，高空月正明。
远书多隔岁，独念没前程。','',''),('quantangshi-42583','听琴','王元','quantangshi','','卷43','拂尘开素匣，有客独伤时。
古调俗不乐，正声君自知。
寒泉出涧涩，老桧倚风悲。
纵有来听者，谁堪继子期。','',''),('quantangshi-42584','哭李韶','王元','quantangshi','','卷43','韶也命何奇，生前与世违。
贫栖古梵刹，终着旧麻衣。
雅句僧抄遍，孤坟客吊稀。
故园今孰在，应见梦中归。','',''),('quantangshi-42585','题邓真人遗址','王元','quantangshi','','卷43','三千功满仙升去，留得山前旧隐基。
但见白云长掩映，不知浮世几兴衰。
松稍风触霓旌动，椶叶霜霑鹤翅垂。
近代无人寻异事，野泉喷月泻秋池。','',''),('quantangshi-42586','句','王元','quantangshi','','卷43','伴行惟瘦鹤，寻步入深云。','',''),('quantangshi-42587','谢翁宏以诗百篇见示','廖融','quantangshi','','卷43','高奇一百篇，造化见工全。
积思游沧海，冥搜入洞天。
神珠迷罔象，端玉匪雕镌。
休叹不得力，离骚千古传。','',''),('quantangshi-42588','赠天台逸人','廖融','quantangshi','','卷43','移桧托禅子，携家上赤城。
拂琴天籁寂，欹枕海涛生。
云白寒峰晚，鸟歌春谷晴。
又闻求桂檝，载月十洲行。','',''),('quantangshi-42589','古桧','廖融','quantangshi','','卷43','何人见植初，老树梵王居。
山鬼暗栖托，樵夫难破除。
声高秋汉迥，影倒月潭虚。
尽日无僧倚，清风长有余。','',''),('quantangshi-42590','题伍彬屋壁','廖融','quantangshi','','卷43','圆塘绿水平，鱼跃紫莼生。
要路贫无力，深村老退耕。
犊随原草远，蛙傍堑篱鸣。
拨棹茶川去，初逢谷雨晴。','',''),('quantangshi-42591','梦仙谣','廖融','quantangshi','','卷43','琪木扶疎系辟邪，麻姑夜宴紫皇家。
银河旌节摇波影，珠阁笙箫吸月华。
翠凤引游三岛路，赤龙齐驾五云车。
星稀犹倚虹桥立，拟就张骞搭汉槎。','',''),('quantangshi-42592','退宫妓','廖融','quantangshi','','卷43','神仙风格本难俦，曾从前皇翠辇游。
红踯躅繁金殿暖，碧芙蓉笑水宫秋。
宝筝钿剥阴尘覆，锦帐香消画烛幽。
一旦色衰归故里，月明犹梦按梁州。','',''),('quantangshi-42593','句','廖融','quantangshi','','卷43','圭竈先知晓，盆池别见天。
古寺寻僧饭，寒岩衣鹿裘。
云穿捣药屋，雪压钓鱼舟。','',''),('quantangshi-42594','赠廖融','王正己','quantangshi','','卷43','病起正当秋阁迥，酒醒迎对夜涛寒。
炉中药熟分僧饭，枕上琴闲借客弹。','',''),('quantangshi-42595','句','王正己','quantangshi','','卷43','洗盂秋涧日华动，捣药夜坐秋气深。','',''),('quantangshi-42596','送廖融处士南游','翁宏','quantangshi','','卷43','病卧瘴云间，莓苔渍竹关。
孤吟牛渚月，老忆洞庭山。
壮志潜消尽，淳风竟未还。
今朝忽相遇，执手一开颜。','',''),('quantangshi-42597','春残','翁宏','quantangshi','','卷43','又是春残也，如何出翠帏。
落花人独立，微雨燕双飞。
寓目魂将断，经年梦亦非。
那堪向愁夕，萧飒暮蝉辉。','',''),('quantangshi-42598','秋残','翁宏','quantangshi','','卷43','又是秋残也，无聊意若何。
客程江外远，归思夜深多。
岘首飞黄叶，湘湄走白波。
仍闻汉都护，今岁合休戈。','',''),('quantangshi-42599','句','翁宏','quantangshi','','卷43','万木横秋里，孤舟半夜猨。
漏光残井甃，缺影背山椒。
风回山火断，潮落岸冰高。','',''),('quantangshi-42600','过衡山赠廖处士','張觀','quantangshi','','卷43','未向漆园为傲吏，定应明代作征君。
传家奕世无金玉，乐道经年有典坟。
带雨小舟横别涧，隔花幽犬吠深云。
到头终为苍生起，休恋耕烟楚水濆。','',''),('quantangshi-42601','竹枝词二首 一','孫光憲','quantangshi','','卷43','门前春水白苹花，岸上无人小艇斜。
商女经过江欲暮，散抛残食饲神鸦。','',''),('quantangshi-42602','竹枝词二首 二','孫光憲','quantangshi','','卷43','乱绳千结绊人深，越罗万丈表长寻。
杨柳在身垂意绪，藕花落尽见莲心。','',''),('quantangshi-42603','杨柳枝词四首 一','孫光憲','quantangshi','','卷43','阊门风暖落花干，飞遍江城雪不寒。
独有晚来临水驿，闲人多凭赤栏干。','',''),('quantangshi-42604','杨柳枝词四首 二','孫光憲','quantangshi','','卷43','有池有榭即蒙蒙，浸润翻成长养功。
恰似有人长点检，着行排立向春风。','',''),('quantangshi-42605','杨柳枝词四首 三','孫光憲','quantangshi','','卷43','根柢虽然傍浊河，无妨终日近笙歌。
毵毵金带谁堪比，还共黄莺不较多。','',''),('quantangshi-42606','杨柳枝词四首 四','孫光憲','quantangshi','','卷43','万株枯槁怨亡隋，似吊吴台各自垂。
好是淮阴明月里，酒楼横笛不胜吹。','',''),('quantangshi-42607','采莲','孫光憲','quantangshi','','卷43','菡萏香连十顷陂，小姑贪戏采莲迟。
晚来弄水船头湿，更脱红裙裹鸭儿。','',''),('quantangshi-42608','八拍蛮','孫光憲','quantangshi','','卷43','孔雀尾拖金线长，怕人飞起入丁香。
越女沙头争拾翠，相呼归去背斜阳。','',''),('quantangshi-42609','句','孫光憲','quantangshi','','卷43','晚厨烹淡菜，春杼种幢花。','',''),('quantangshi-42610','咏蒲鞋','劉章','quantangshi','','卷43','吴江浪浸白蒲春，越女初挑一样新。
才自绣窗离玉指，便随罗袜上香尘。
石榴裙下从容久，玳瑁筵前整顿频。
今日高楼鸳瓦上，不知抛掷是何人。','',''),('quantangshi-42611','夜坐','路洵美','quantangshi','','卷43','帘卷竹轩清，四邻无语声。
漏从吟里转，月自坐来明。
草木露华湿，衣裳寒气生。
难逢知鉴者，空悦此时情。','',''),('quantangshi-42612','荆台道院','梁震','quantangshi','','卷43','桑田一变赋归来，爵禄焉能凂我哉。
黄犊依然花竹外，清风万古凛荆台。','',''),('quantangshi-42613','宁州道中','楊夔','quantangshi','','卷43','城枕萧关路，胡兵日夕临。
唯凭一炬火，以慰万人心。
春老雪犹重，沙寒草不深。
如何驱匹马，向此独闲吟。','',''),('quantangshi-42614','寻九华王山人','楊夔','quantangshi','','卷43','下马扣荆扉，相寻春半时。
扪萝盘磴险，叠石度溪危。
松夹莓苔迳，花藏薜荔篱。
卧云情自逸，名姓厌人知。','',''),('quantangshi-42615','金陵逢张乔','楊夔','quantangshi','','卷43','殊乡会面时，辛苦两情知。
有志年空过，无媒命共奇。
吟余春漏急，语旧酒巡迟。
天爵如堪倚，休惊鬓上丝。','',''),('quantangshi-42616','送邹尊师归洞庭','楊夔','quantangshi','','卷43','众岛在波心，曾居旧隐林。
近闻飞檄急，转忆卧云深。
卖药唯供酒，归舟只载琴。
遥知明月夜，坐石自开襟。','',''),('quantangshi-42617','送日东僧游天台','楊夔','quantangshi','','卷43','一瓶离日外，行指赤城中。
去自重云下，来从积水东。
攀萝跻石径，挂锡憩松风。
回首鸡林道，唯应梦想通。','',''),('quantangshi-42618','题甘露寺','楊夔','quantangshi','','卷43','高殿拂云霓，登临想虎溪。
风匀帆影众，烟乱鸟行迷。
北倚波涛阔，南窥井邑低。
满城尘漠漠，隔岸草萋萋。
虚阁延秋磐，澄江响暮鼙。
客心还惜去，新月挂楼西。','',''),('quantangshi-42619','送张相公出征','楊夔','quantangshi','','卷43','得意在当年，登坛秉国权。
汉推周勃重，晋让赵宣贤。
儒德尼丘降，兵钤太白传。
援毫飞凤藻，发匣吼龙泉。
历火金难耗，零霜桂益坚。
从来称玉洁，此更让朱妍。
鸳鹭臻门下，貔貅拥帐前。
去知清朔漠，行不费陶甄。
献画符中旨，推诚契上玄。
愿将班固笔，书颂勒燕然。','',''),('quantangshi-42620','题郑山人郊居','楊夔','quantangshi','','卷43','谷口今逢避世才，入门潇洒绝尘埃。
渔舟下钓乘风去，药酝留宾待月开。
数片石从青嶂得，一条泉自白云来。
竹轩相对无言语，尽日南山不欲回。','',''),('quantangshi-42621','题宣州延庆寺益公院','楊夔','quantangshi','','卷43','嘿坐能除万种情，腊高兼有赐衣荣。
讲经旧说倾朝听，登殿曾闻降辇迎。
幽迳北连千嶂碧，虚窗东望一川平。
长年门外无尘客，时见元戎驻斾旌。','',''),('quantangshi-42622','寄当阳袁皓明府','楊夔','quantangshi','','卷43','高人为县在南京，竹遶琴堂水遶城。
地古既资携酒兴，务闲偏长看山情。
松轩待月僧同坐，药圃寻花鹤伴行。
百里甚堪留惠爱，莫教空说鲁恭名。','',''),('quantangshi-42623','送杜郎中入茶山修贡','楊夔','quantangshi','','卷43','一道澄澜彻底清，仙郎轻棹出重城。
采苹虚得当时称，述职那同此日荣。
剑戟步经高障黑，绮罗光动百花明。
谢公携妓东山去，何似乘春奉昭行。','',''),('quantangshi-42624','送郑谷','楊夔','quantangshi','','卷43','春江潋潋清且急，春雨蒙蒙密复疎。
一曲狂歌两行泪，送君兼寄故乡书。','',''),('quantangshi-42625','自叙','杜建徽','quantangshi','','卷43','中剑斫耳缺，被箭射胛过。
为将须有胆，有胆即无贾。','',''),('quantangshi-42626','游西湖','沈韜文','quantangshi','','卷43','□□□□□□□，菰米苹花似故乡。
不是不归归未得，好风明月一思量。','',''),('quantangshi-42627','赠和龙妙空禅师','王繼勳','quantangshi','','卷43','白面山南灵庆院，茅斋道者雪峰禅。
只栖云树两三亩，不下烟萝四五年。
猨鸟认声呼唤易，龙神降伏住持坚。
谁知今日秋江畔，独步医王阐法筵。','',''),('quantangshi-42628','题建造寺','王繼勳','quantangshi','','卷43','曾看画图劳健羡，如今亲见画犹麄。
减除天半石初泐，欠却几株松未枯。
题像阁人渔浦叟，集生台鸟谢城乌。
我来一听支公论，自是吾身幻得吾。','',''),('quantangshi-42629','句','王繼勳','quantangshi','','卷43','扫石云随帚，耕山鸟傍人。','',''),('quantangshi-42630','和赠和龙妙空禅师','夏鴻','quantangshi','','卷43','翰林遗迹镜潭前，孤峭高僧此处禅。
出为信门兴化日，坐当吾国太平年。
身同莹澈尼珠净，语并锋铓慧劒坚。
道果已圆名已遂，即看千匝遶香筵。','',''),('quantangshi-42631','题青草湖神祠','劉山甫','quantangshi','','卷43','坏墙风雨几经春，草色盈庭一座尘。
自是神明无感应，盛衰何得却由人。','',''),('quantangshi-42632','汉宗庙乐舞辞','張昭','quantangshi','','卷43','高庙明灵再启图，金根玉辂幸神都。
巢阿丹凤衔书命，入昴飞星献宝符。
正抚薰弦娱赤子，忽登仙驾泣苍梧。
荐樱鹤馆笳箫咽，酌鬯金楹劒佩趋。
星俎云罍兼鲁礼，朱干象箾杂巴渝。
氤氲龙麝交青琐，仿髴锡銮下蘂珠。
荐豆奉觞亲玉几，配天合祖耀璇枢。
受厘饮酒皇欢洽，仰俟余灵泰九区。','',''),('quantangshi-42633','农家','顏仁郁','quantangshi','','卷43','夜半呼儿趁晓耕，羸牛无力渐艰行。
时人不识农家苦，将谓田中谷自生。','',''),('quantangshi-42634','山居','顏仁郁','quantangshi','','卷43','栢树松阴覆竹斋，罢烧药竈纵高怀。
世间应少山间景，云遶青松水遶堦。','',''),('quantangshi-42635','春日寓感','王延彬','quantangshi','','卷43','两衙前后讼堂清，软锦披袍拥鼻行。
雨后绿苔侵履迹，春深红杏锁莺声。
因携久酝松醪酒，自煮新抽竹笋羹。
也解为诗也为政，侬家何似谢宣城。','',''),('quantangshi-42636','哭徐夤','王延彬','quantangshi','','卷43','延寿溪头叹逝波，古今人事半销磨。
昔除正字今何在，所谓人生能几何。','',''),('quantangshi-42637','塞上 一','譚用之','quantangshi','','卷43','秋风汉北雁飞天，单骑那堪遶贺兰。
碛暗更无岩树影，地平时有野烧瘢。
貂披寒色和衣冷，劒佩胡霜隔匣寒。
早晚横戈似飞尉，拥旄深入异田单。','',''),('quantangshi-42638','塞上 二','譚用之','quantangshi','','卷43','钵略城边日欲西，游人却忆旧山归。
牛羊集水烟黏步，雕鹗盘空雪满围。
猎骑静逢边气薄，戍楼寒对暮烟微。
横行总是男儿事，早晚重来似汉飞。','',''),('quantangshi-42639','赠索处士','譚用之','quantangshi','','卷43','不将桂子种诸天，长得寻君水石边。
玄豹夜寒和雾隐，骊龙春暖抱珠眠。
山中宰相陶弘景，洞里真人葛稚川。
一度相思一惆怅，水寒烟澹落花前。','',''),('quantangshi-42640','别雒下一二知己','譚用之','quantangshi','','卷43','金鼎光辉照雪袍，雒阳春梦忆波涛。
尘埃满眼人情异，风雨前程马足劳。
接塞峨眉通蜀险，过山仙掌倚秦高。
别来无限幽求子，应笑区区味六韬。','',''),('quantangshi-42641','约张处士游梁','譚用之','quantangshi','','卷43','莫学区区老一经，夷门关吏旧书生。
晋朝灭后无中散，韩国亡来绝上卿。
龙变洞中千谷冷，劒横天外八风清。
好携长策干时去，免逐渔樵度太平。','',''),('quantangshi-42642','送友人归青社','譚用之','quantangshi','','卷43','雕鹗途程在碧天，彩衣东去复何言。
二千宾客旧知己，十二山河新故园。
吟看桂生溪月上，醉听鲲化海涛翻。
好期圣代重相见，莫学袁生老竹轩。','',''),('quantangshi-42643','送丁道士归南中','譚用之','quantangshi','','卷43','孤云无定鹤辞巢，自负焦桐不说劳。
服药几年期碧落，验符何处呪丹毫。
子陵山晓红云密，青草湖平雪浪高。
从此人稀见踪迹，还应选地种仙桃。','',''),('quantangshi-42644','月夜怀寄友人','譚用之','quantangshi','','卷43','劒气徒劳望斗牛，故人别后阻仙舟。
残春谩道深倾酒，好月那堪独上楼。
何处是非随马足，由来得丧白人头。
清风未许重携手，几度高吟寄水流。','',''),('quantangshi-42645','闲居寄陈山人','譚用之','quantangshi','','卷43','闲居何处得闲名，坐掩衡茅损性灵。
破梦晓钟闻竹寺，沁心秋雨浸莎庭。
瓮边难负千杯绿，海上终眠万仞青。
珍重先生全太古，应看名利似浮[萍]。','',''),('quantangshi-42646','忆南中','譚用之','quantangshi','','卷43','碧江头与白云门，别后秋霜点鬓根。
长记学禅青石寺，最思共醉落花村。
林间竹有湘妃泪，窗外禽多杜宇魂。
未棹扁舟重回首，采薇收橘不堪论。','',''),('quantangshi-42647','寄友人','譚用之','quantangshi','','卷43','病多慵引架书看，官职无才思已阑。
穴凤瑞时来却易，人龙别后见何难。
琴樽风月闲生计，金玉松筠旧岁寒。
早晚烟村碧江畔，挂罾重对蓼花滩。','',''),('quantangshi-42648','别江上一二友生','譚用之','quantangshi','','卷43','国风千载务重华，须逐浮云背若耶。
无地可归堪种玉，有天教上且乘槎。
白纶巾卸苏门月，红锦衣裁御苑花。
他日成都却回首，东山看取谢鲲家。','',''),('quantangshi-42649','寄岐山林逢吉明府','譚用之','quantangshi','','卷43','岐山高与陇山连，制锦无私服晏眠。
鹦鹉语中分百里，凤凰声里过三年。
秦无旧俗云烟媚，周有遗风父老贤。
莫役生灵种杨柳，一枝枝折灞桥边。','',''),('quantangshi-42650','感怀呈所知','譚用之','quantangshi','','卷43','十年流落赋归鸿，谁傍昏衢驾烛龙。
竹屋乱烟思梓泽，酒家疎雨梦临邛。
千年别恨调琴懒，一片年光览镜慵。
早晚休歌白石烂，放教归去卧羣峰。','',''),('quantangshi-42651','江上闻笛','譚用之','quantangshi','','卷43','谁为梅花怨未平，一声高唤百龙惊。
风当阊阖庭初静，月在姑苏秋正明。
曲尽绿杨涵野渡，管吹青玉动江城。
临流不欲殷勤听，芳草王孙旧有情。','',''),('quantangshi-42652','寄孟进士','譚用之','quantangshi','','卷43','依旧池边草色芳，故人何处忆山阳。
书回科斗江帆暮，曲罢驺虞海树苍。
吟望晓烟思桂渚，醉依残月梦余杭。
别来南国知谁在，空对襜褕一断肠。','',''),('quantangshi-42653','寄阎记室','譚用之','quantangshi','','卷43','织锦歌成下翠微，岂劳西去问搘机。
未开水府珠先见，不掘丰城劒自辉。
鳌逐玉蟾攀桂上，马随青帝踏花归。
相逢半是云霄客，应笑歌牛一布衣。','',''),('quantangshi-42654','幽居寄李祕书','譚用之','quantangshi','','卷43','几年帝里阻烟波，敢向明时叩角歌。
看尽好花春卧稳，醉残红日夜吟多。
印开夕照垂杨柳，画破寒潭老芰荷。
昨夜前溪有龙鬬，石桥风雨少人过。','',''),('quantangshi-42655','贻钓鱼李处士','譚用之','quantangshi','','卷43','罢吟鹦鹉草芊芊，又泛鸳鸯水上天。
一棹冷涵杨柳雨，片帆香挂芰荷烟。
绿摇江澹萍离岸，红点云疎橘满川。
何处邈将归画府，数茎红蓼一渔船。','',''),('quantangshi-42656','河桥楼赋得羣公夜宴','譚用之','quantangshi','','卷43','芙蓉帘幕扇秋红，蛮府新郎夜宴同。
满座马融吹笛月，一楼张翰过江风。
杯黏紫酒金螺重，谈转雕璫玉麈空。
深荷良宵慰顦顇，德星池馆在江东。','',''),('quantangshi-42657','寄左先辈','譚用之','quantangshi','','卷43','狂歌白鹿上青天，何似兰塘钓紫烟。
万卷祖龙坑外物，一泓孙楚耳中泉。
翩翾蛮榼薰晴浦，毂辘鱼车响夜船。
学取青莲李居士，一生杯酒在神仙。','',''),('quantangshi-42658','贻费道人','譚用之','quantangshi','','卷43','谁如南浦傲烟霞，白葛衣青称帽纱。
碧玉蜉蝣迎客酒，黄金毂辘钓鱼车。
吟歌云鸟归樵谷，卧爱神仙入画家。
他日凤书何处觅，武陵烟树半桃花。','',''),('quantangshi-42659','寄许下前管记王侍御','譚用之','quantangshi','','卷43','昔年南去得娱宾，顿逊杯前共好春。
螘泛羽觞蛮酒腻，凤衔瑶句蜀牋新。
花怜游骑红随辔，草恋征车碧遶轮。
别后青青郑南陌，不知风月属何人。','',''),('quantangshi-42660','秋日圃田送人随计','譚用之','quantangshi','','卷43','仆射陂前是传邮，去程雕鹗弄高秋。
吟抛芍药裁诗圃，醉下茱萸饮酒楼。
向日迥飞驹皎皎，临风谁和鹿呦呦。
明年二月仙山下，莫遣桃花逐水流。','',''),('quantangshi-42661','途次宿友人别墅','譚用之','quantangshi','','卷43','千里崤函一梦劳，岂知云馆共萧骚。
半帘绿透偎寒竹，一榻红侵坠晚桃。
蛮酒客稀知味长，蜀琴风定觉弦高。
感君岩下闲招隐，细缕金盘鲙错刀。','',''),('quantangshi-42662','春日期巢湖旧事','譚用之','quantangshi','','卷43','暖掠红香燕燕飞，五云仙佩晓相携。
花开鹦鹉韦郎曲，竹亚虬龙白帝溪。
富贵万场归紫酒，是非千载逐芳泥。
不知多少开元事，露泣春丛向日低。','',''),('quantangshi-42663','再游韦曲山寺','譚用之','quantangshi','','卷43','鹊岩烟断玉巢欹，罨画春塘太白低。
马踏翠开垂柳寺，人耕红破落花蹊。
千年胜概咸原上，几代荒凉绣岭西。
碧吐红芳旧行处，岂堪回首草萋萋。','',''),('quantangshi-42664','寄徐拾遗','譚用之','quantangshi','','卷43','长竿一系白龙吟，谁和驺虞发素琴。
野客碧云魂易断，故人芳草梦难寻。
天从补后星辰稳，海自潮来岛屿深。
好向明庭拾遗事，莫教玄豹老泉林。','',''),('quantangshi-42665','秋宿湘江遇雨','譚用之','quantangshi','','卷43','江上阴云锁梦魂，江边深夜舞刘琨。
秋风万里芙蓉国，暮雨千家薜荔村。
乡思不堪悲橘柚，旅游谁肯重王孙。
渔人相见不相问，长笛一声归岛门。','',''),('quantangshi-42666','贻南康陈处士陶','譚用之','quantangshi','','卷43','白玉堆边蒋迳横，空涵二十四滩声。
老无征战轩辕国，贫有茅茨帝舜城。
丹凤昼飞羣木冷，一龙秋卧九江清。
时人莫笑非经济，还待中原致太平。','',''),('quantangshi-42667','渭城春晚','譚用之','quantangshi','','卷43','秦树朦胧春色微，香风烟暖树依依。
边城夜静月初上，芳草路长人未归。
折柳且堪吟晚槛，弄花何处醉残晖。
钓乡千里断消息，满目碧云空自飞。','',''),('quantangshi-42668','山中春晚寄贾员外','譚用之','quantangshi','','卷43','不随黄鹤起烟波，应笑无成返薜萝。
看尽好花春卧稳，醉残红日夜吟多。
高添雅兴松千尺，暗养清音竹数科。
珍重仙曹旧知己，往来星骑一相过。','',''),('quantangshi-42669','贻净居寺新及第','譚用之','quantangshi','','卷43','秋池云下白莲香，池上吟仙寄竹房。
闲颂国风文字古，静消心火梦魂凉。
三春蓬岛花无限，八月银河路更长。
此境空门不曾有，从头好语与医王。','',''),('quantangshi-42670','江边秋夕','譚用之','quantangshi','','卷43','千钟紫酒荐菖蒲，松岛兰舟潋滟居。
曲内橘香江客笛，字中岚气岳僧书。
吟期汗漫驱金虎，坐约丹青跨玉鱼。
七色花虬一声鹤，几时乘兴上清虚。','',''),('quantangshi-42671','送僧中孚南归','譚用之','quantangshi','','卷43','琵琶峡口月溪边，玉乳头佗忆旧川。
一锡冷涵兰径路，片帆香挂橘洲烟。
苔封石锦栖霞室，水迸衣珠喷玉蝉。
莫道翩翩去如梦，本来吟鸟在林泉。','',''),('quantangshi-42672','江馆秋夕','譚用之','quantangshi','','卷43','耿耿银河雁半横，梦欹金碧辘轳轻。
满窗谢练江风白，一枕齐纨海月明。
杨柳败梢飞叶响，芰荷香柄折秋鸣。
谁人更唱阳关曲，牢落烟霞梦不成。','',''),('quantangshi-42673','秋夜同友人话旧','譚用之','quantangshi','','卷43','露下银河雁度频，囊中垆火几时真。
数茎白发生浮世，一盏寒灯共故人。
云外簟凉吟峤月，岛边花暖钓江春。
何当归去重携手，依旧红霞作近邻。','',''),('quantangshi-42674','古剑','譚用之','quantangshi','','卷43','铸时天匠待英豪，紫焰寒星匣倍牢。
三尺何年拂尘土，四溟今日绝波涛。
雄应垓下收蛇阵，滞想溪头伴豹韬。
惜是真龙懒抛掷，夜来冲斗气何高。','',''),('quantangshi-42675','寄王侍御','譚用之','quantangshi','','卷43','鸟尽弓藏良可哀，谁知归钓子陵台。
炼多不信黄金耗，吟苦须惊白发催。
喘月吴牛知夜至，嘶风胡马识秋来。
燕歌别后休惆怅，黍已成畦菊已开。','',''),('quantangshi-42676','别何处士陵俊老','譚用之','quantangshi','','卷43','三皇上人春梦醒，东侯老大麒麟生。
洞连龙穴全山冷，窗透鳌波尽室清。
计拙耻居岩麓老，气狂慙与斗牛平。
谁人为向青编上，直傍巢由写一名。','',''),('quantangshi-42677','句','譚用之','quantangshi','','卷43','流水物情谙世态，落花春梦压尘劳。
织槛锦纹苔乍结，堕书花印菊初残。
光阴老去无成事，富贵不来争奈何。
眠云无限好知己，应笑不归花满樽。','',''),('quantangshi-42678','泊姑熟口','王周','quantangshi','','卷43','杳杳金陵路，难禁欲断魂。
雨晴山有态，风晚水无痕。
远色千樯岸，愁声一笛村。
如何遣怀抱，诗毕自开尊。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-42679','湖口县','王周','quantangshi','','卷43','柴桑分邑载图经，屈曲山光展画屏。
最是芦洲东北望，人家残照隔烟汀。','',''),('quantangshi-42680','岳州众湖阻风二首 一','王周','quantangshi','','卷43','众湖湖口系兰船，睡起中餐又却眠。
风伯如何解回怒，数宵樯倚碧芦烟。','',''),('quantangshi-42681','岳州众湖阻风二首 二','王周','quantangshi','','卷43','偶系扁舟枕绿莎，旋移深处避惊波。
晓来闲共渔人话，此去巴陵路几多。','',''),('quantangshi-42682','问春','王周','quantangshi','','卷43','游丝垂幄雨依依，枝上红香片片飞。
把酒问春因底意，为谁来后为谁归。','',''),('quantangshi-42683','春答','王周','quantangshi','','卷43','花枝千万趁春开，三月瓓珊即自回。
剩向东园种桃李，明年依旧为君来。','',''),('quantangshi-42684','西塞山二首 一','王周','quantangshi','','卷43','西塞名山立翠屏，浓岚横入半江青。
千寻铁鏁无由问，石壁空存道者形。','',''),('quantangshi-42685','西塞山二首 二','王周','quantangshi','','卷43','匹妇顽然莫问因，匹夫何去望千春。
翻思岵屺传诗什，举世曾无化石人。','',''),('quantangshi-42686','使风','王周','quantangshi','','卷43','风起即千里，风回翻问津。
沈思宦游者，何啻使风人。','',''),('quantangshi-42687','石首山','王周','quantangshi','','卷43','首出崔嵬占上游，迥存浓翠向荆州。
空闻别有回山力，却见长江曲尺流。','',''),('quantangshi-42688','金口步','王周','quantangshi','','卷43','两山鬬咽喉，羣石矗牙齿。
行客无限怨，横吞一江水。','',''),('quantangshi-42689','采桑女二首 一','王周','quantangshi','','卷43','渡水采桑归，蚕老催上机。
扎扎得盈尺，轻素何人衣。','',''),('quantangshi-42690','采桑女二首 二','王周','quantangshi','','卷43','采桑知蚕饥，投梭惜夜迟。
谁夸罗绮丛，新画学月眉。','',''),('quantangshi-42691','渡溪','王周','quantangshi','','卷43','渡溪溪水急，水溅罗衣湿。
日暮犹未归，盈盈水边立。','',''),('quantangshi-42692','落叶','王周','quantangshi','','卷43','素律铄欲脆，青女妒复稀。
月冷天风吹，叶叶干红飞。','',''),('quantangshi-42693','宿疎陂驿','王周','quantangshi','','卷43','秋染棠梨叶半红，荆州东望草平空。
谁知孤宦天涯意，微雨萧萧古驿中。','',''),('quantangshi-42694','再经秭归二首 一','王周','quantangshi','','卷43','总角曾随上峡船，寻思如梦可凄然。
夜来孤馆重来宿，枕底滩声似旧年。','',''),('quantangshi-42695','再经秭归二首 二','王周','quantangshi','','卷43','秭归城邑昔曾过，旧识无人奈老何。
独有凄清难改处，月明闻唱竹枝歌。','',''),('quantangshi-42696','霞','王周','quantangshi','','卷43','拂拂生残晖，层层如裂绯。
天风翦成片，疑作仙人衣。','',''),('quantangshi-42697','巫山公署壁有无名氏戏书二韵','王周','quantangshi','','卷43','南陵直上路盘盘，平地凌云势万端。
堪笑巴民不厌足，更嫌山少画山看。','',''),('quantangshi-42698','道院','王周','quantangshi','','卷43','白日人稀到，帘垂道院深。
雨苔生古壁，雪雀聚寒林。
忘虑凭三乐，消闲信五禽。
谁知是官府，烟缕满炉沈。','',''),('quantangshi-42699','会哙岑山人','王周','quantangshi','','卷43','渝州江上忽相逢，说隐西山最上峰。
略坐移时又分别，片云孤鹤一枝筇。','',''),('quantangshi-42700','巴江','王周','quantangshi','','卷43','巴江江水色，一带浓蓝碧。
仙女瑟瑟衣，风梭晚来织。','',''),('quantangshi-42701','小园桃李始花偶以成咏','王周','quantangshi','','卷43','桃李栽成艳格新，数枝留得小园春。
半红半白无风雨，随分夭容解笑人。','',''),('quantangshi-42702','公居','王周','quantangshi','','卷43','公居门馆静，旅寄万州城。
山共秋烟紫，霜并夜月清。
无愁干酒律，有句入诗评。
何必须林下，方驰吏隐名。','',''),('quantangshi-42703','富池口','王周','quantangshi','','卷43','扁舟闲引望，望极更盘桓。
山密碍江曲，雨多饶地寒。
短莎烟苒苒，惊浪雪漫漫。
难写愁何限，乡关在一端。','',''),('quantangshi-42704','夔州病中','王周','quantangshi','','卷43','隐几经旬疾未痊，孤灯孤驿若为眠。
郡楼昨夜西风急，一一更筹到枕前。','',''),('quantangshi-42705','题厅壁','王周','quantangshi','','卷43','永日无他念，孤清吏隐心。
竹声并雪碎，溪色共烟深。
数息闲凭几，缘情默寄琴。
谁知同寂寞，相与结知音。','',''),('quantangshi-42706','过武宁县','王周','quantangshi','','卷43','行过武宁县，初晴物景和。
岸回惊水急，山浅见天多。
细草浓蓝泼，轻烟匹练拖。
晚来何处宿，一笛起渔歌。','',''),('quantangshi-42707','路次覆盆驿','王周','quantangshi','','卷43','曾上青泥蜀道难，架空成路入云寒。
如何却向巴东去，三十六盘天外盘。','',''),('quantangshi-42708','藕池阻风寄同行抚牧裘驾','王周','quantangshi','','卷43','船樯相望荆江中，岸芦汀树烟蒙蒙。
路闻堤缺水如箭，未知何日生南风。','',''),('quantangshi-42709','无题二首 一','王周','quantangshi','','卷43','冰雪肌肤力不胜，落花飞絮遶风亭。
不知何事秋千下，蹙破愁眉两点青。','',''),('quantangshi-42710','无题二首 二','王周','quantangshi','','卷43','梨花如雪已相迷，更被惊乌半夜啼。
帘卷玉楼人寂寂，一钩新月未沈西。','',''),('quantangshi-42711','泊巴东','王周','quantangshi','','卷43','偶泊巴东古县前，宦情乡思两绵绵。
不堪蜡炬烧残泪，雨打船窗半夜天。','',''),('quantangshi-42712','道中未开木杏花','王周','quantangshi','','卷43','粉英香萼一般般，无限行人立马看。
村女浴蚕桑柘绿，枉将颜色忍春寒。','',''),('quantangshi-42713','西山晚景','王周','quantangshi','','卷43','公局长清淡，池亭晚景中。
蔗竿闲倚碧，莲朵静淹红。
半引弯弯月，微生飋飋风。
无思复无虑，此味几人同。','',''),('quantangshi-42714','自和','王周','quantangshi','','卷43','一片残阳景，朦胧淡月中。
兰芽纡嫩紫，棃颊抹生红。
琴阮资清格，冠簪养素风。
烟霄半知足，吏隐少相同。','',''),('quantangshi-42715','齿落词','王周','quantangshi','','卷43','己卯至庚辰，仲夏晦之暮。
吾齿右排上，一齿脱而去。
呼吸缺吾防，咀嚼欠吾助。
年龠惜不返，日驭走为蠹。
唇亡得无寒，舌在从何诉。
辅车宜长依，发肤可增惧。
不须考前古，聊且为近喻。
有如云中雨，雨散绝回顾。
有如枝上叶，叶脱难再附。
白发非独愁，红颜岂私驻。
何必郁九回，何必牵百虑。
开尊复开怀，引笔作长句。','',''),('quantangshi-42716','淘金碛','王周','quantangshi','','卷43','画船晚过淘金碛，不见黄金惟见石。
犹恐黄金价未高，见得锱铢几多力。','',''),('quantangshi-42717','施南路偶书','王周','quantangshi','','卷43','大石岭南梅欲发，南陵陂上雪初飞。
苦无酒解愁成阵，又附兰桡向秭归。','',''),('quantangshi-42718','大石岭驿梅花','王周','quantangshi','','卷43','仙中姑射接瑶姬，成阵清香拥路岐。
半出驿墙谁画得，雪英相倚两三枝。','',''),('quantangshi-42719','赠怤师','王周','quantangshi','','卷43','水中有片月，照耀婵娟姿。
庭前有孤栢，竦秀岁寒期。
坚然物莫迁，寂焉心为师。
声发响必答，形存影即随。
雪花安结子，雪叶宁附枝。
兰死不改香，井寒岂生澌。
晨炉烟褭褭，病发霜丝丝。
丈室冰凛冽，一衲云离披。
顾此名利场，得不慙冠绥。','',''),('quantangshi-42720','游仙都观','王周','quantangshi','','卷43','冷杉枯栢路盘空，毛发生寒略略风。
两汉真仙在何处，巡香行遶蘂珠宫。','',''),('quantangshi-42721','志峡船具诗 梢','王周','quantangshi','','卷43','制之居首尾，俾之辨斜正。
首动尾聿随，斜取正为定。
有如提吏笔，有如执时柄。
有如秉师律，有如宣命令。
守彼方与直，得其刚且劲。
既能济险难，何畏涉辽敻。
招招俾作主，泛泛实司命。
风乌愧斟酌，画鷁空辉映。
古人存丰规，猗欤聊引证。','',''),('quantangshi-42722','志峡船具诗 橹','王周','quantangshi','','卷43','用之大曰舻，冠乎小者楫。
通津既能济，巨浸即横涉。
身之使者颊，虎之拏者爪。
鱼之拨者鬣，弩之进者策。
此实为相须，相须航一叶。','',''),('quantangshi-42723','志峡船具诗 戙','王周','quantangshi','','卷43','箭飞峡中水，锯立峡中石。
峡与水为隘，水与石相击。
濆为生险艰，声发甚霹雳。
三老航一叶，百丈空千尺。
苍黄徒尔为，倏忽何可测。
篙之小难制，戙之独有力。
猗嗟戙之为，彬彬坚且直。
有如用武人，森森矗戈戟。
有如敢言士，落落吐胸臆。
拯危居坦夷，济险免兢惕。
志彼哲匠心，俾其来者识。','',''),('quantangshi-42724','志峡船具诗 百丈','王周','quantangshi','','卷43','少尝侍先君，余闲诵白氏。
始得入峡诗，深味作诗旨。
云有万仞山，云有千丈水。
自念坎壈时，尤多兢慎理。
山束峡如口，水漱石如齿。
孤舟行其中，薄冰犹坦履。
孱颜屹焉立，汹涌勃然起。
百丈为前牵，万险即平砥。
破之以篔簹，续之以麻枲。
砺之坚以节，引之直如矢。
杼轴连半空，长短随两涘。
铁锁枉驰名，锦缆谩称美。
长绳岂能系，朽索何足拟。
苟非𦁤之为，胡可力行此。','',''),('quantangshi-42725','早春西园','王周','quantangshi','','卷43','引步携筇竹，西园小径通。
雪欹梅蔕绿，春入杏梢红。
静意崖穿溜，孤愁笛破空。
如何将此景，收拾向图中。','',''),('quantangshi-42726','金盘草诗','王周','quantangshi','','卷43','今春从南陵，得草名金盘。
金盘有仁性，生在林一端。
根节岁一节，食之甘而酸。
风俗竞采掇，俾人防急难。
巴中虵虺毒，解之如走丸。
巨叶展六出，软干分长竿。
摇摇绿玉活，褭褭香荷寒。
世云暑酷月，郁有神物看。
天之产于此，意欲生民安。
今之为政者，何不反此观。
知彼苛且猛，慎勿虐而残。
一物苟失所，万金惟可叹。
莫并蒿与莱，岂羡芝及兰。
勤渠护根本，栽植当庭栏。
寄言好生者，休说神仙丹。','',''),('quantangshi-42727','和程刑部三首 公会亭','王周','quantangshi','','卷43','公事公言地，标名姓必臧。
江山如得助，谈笑若为妨。
均赋乡原肃，详刑郡邑康。
官箴居座右，夙夜算难忘。','',''),('quantangshi-42728','和程刑部三首 碧鲜亭','王周','quantangshi','','卷43','飋飋笼清籁，萧萧鏁翠阴。
向高思尽节，从直美虚心。
迥砌滋苍藓，幽窗伴素琴。
公余时引步，一径静中深。','',''),('quantangshi-42729','和程刑部三首 清涟合','王周','quantangshi','','卷43','照影翻窗绮，层纹滉额波。
丝青迷岸柳，茸绿蘸汀莎。
片雪翘饥鹭，孤香卷嫩荷。
凭栏堪入画，时听竹枝歌。','',''),('quantangshi-42730','自喻','王周','quantangshi','','卷43','予念天之生，生本空疎器。
五岁禀慈训，愤悱读书志。
七岁辨声律，勤苦会诗赋。
九岁执公卷，倜傥干名意。
乞荐乡老书，幸会春官试。
折桂愧巍峩，依莲何气味。
性拙绝不佞，才短无余地。
前年会知己，荐章实非据。
宁见民说平，空荷君恩寄。
瞿唐抵巴渝，往来名揽辔。
孤舟一水中，艰险实可畏。
羣操百丈牵，临难无苟避。
濆向江底发，水在石中沸。
槌鼓称打宽，系纫呼下纬。
善恶胡可分，死生何足讳。
骑衡与垂堂，非不知前喻。
临渊与履冰，非不知深虑。
我今縻搢绅，善地谁人致。
城孤与社鼠，巧佞谁从庇。
奴颜与婢膝，丑直谁从媚。
妻儿敻限越，容颜几憔悴。
致身霄汉人，呝嚱尽贤智。','',''),('quantangshi-42731','巫山庙','王周','quantangshi','','卷43','庙前溪水流潺潺，庙中修竹声珊珊。
襄王一梦杳难问，晚晴天气归云闲。','',''),('quantangshi-42732','下瞿塘寄时同年','王周','quantangshi','','卷43','春寒天气下瞿塘，大壤溪前柳线长。
须信孤云是孤宦，莫将乡思附归艎。','',''),('quantangshi-42733','和杜运使巴峡地暖节物与中土异黯然有感诗三首 一','王周','quantangshi','','卷43','随柳参差破绿芽，此中依约欲飞花。
春光是处伤离思，何况归期未有涯。','',''),('quantangshi-42734','和杜运使巴峡地暖节物与中土异黯然有感诗三首 二','王周','quantangshi','','卷43','始看菊蘂开篱下，又见梅花寄岭头。
揽辔巴西官局冷，几凭春酒沃乡愁。','',''),('quantangshi-42735','和杜运使巴峡地暖节物与中土异黯然有感诗三首 三','王周','quantangshi','','卷43','花品姚黄冠洛阳，巴中春早羡孤芳。
不知别有栽培力，流咏新诗与激昂。','',''),('quantangshi-42736','施南太守以猨儿为寄作诗答之','王周','quantangshi','','卷43','虞人初获酉江西，长臂难将意马齐。
今日未啼头已白，不堪深入白云啼。','',''),('quantangshi-42737','巫庙','王周','quantangshi','','卷43','巴水走若箭，峡山开如屏。
汹涌匹练白，𡷾崒浓蓝青。
崖空蓄云雨，滩恶惊雷霆。
神仙宅幽邃，庙貌横杳冥。
隐约可一梦，缥缈余千龄。
名利有所役，舟楫无暂停。
悉宰垂[肸]蠁，祠祷希安宁。
鵶鵶尔何物，飞飞来庙庭。
纷纷扬寥泬，远近随虚舲。
铁石砺觜爪，金碧辉光翎。
翔集托阴险，鹐啄贪膻腥。
日既恃威福，岁久为精灵。
依草与附木，诬诡殊不经。
城狐与社鼠，琐细何足听。
况乎人假人，心阔吞沧溟。','',''),('quantangshi-42738','贵游','劉兼','quantangshi','','卷43','绣衣公子宴池塘，淑景融融万卉芳。
珠翠照天春未老，管弦临水日初长。
风飘柳线金成穗，雨洗梨花玉有香。
醉后不能离绮席，拟凭青帝系斜阳。','',''),('quantangshi-42739','梦归故园 一','劉兼','quantangshi','','卷43','桐叶飞霜落井栏，菱花藏雪助衰颜。
夜窗飒飒摇寒竹，秋枕迢迢梦故山。
临水钓舟横荻岸，隔溪禅侣启柴关。
觉来依旧三更月，离绪乡心起万端。','',''),('quantangshi-42740','梦归故园 二','劉兼','quantangshi','','卷43','旧馆秋寒夜梦长，水帘疎影入回塘。
宦情率尔拖鱼艇，客恨依然在燕梁。
白鹭独飘山面雪，红蕖全谢镜心香。
起来不语无人会，醉倚东轩半夕阳。','',''),('quantangshi-42741','蜀都春晚感怀','劉兼','quantangshi','','卷43','蜀都春色渐离披，梦断云空事莫追。
宫阙一城荒作草，王孙犹自醉如泥。
谁家玉笛吹残照，柳市金丝拂旧堤。
可惜锦江无锦濯，海棠花下杜鹃啼。','',''),('quantangshi-42742','对雨','劉兼','quantangshi','','卷43','幽庭凝碧亦涟漪，檐溜声繁聒梦归。
半岫金乌才委照，一川石燕又交飞。
濯枝霢霂榴花吐，吹渚飘颻暑气微。
因忆故园闲钓处，苍苔斑驳满渔矶。','',''),('quantangshi-42743','春霁','劉兼','quantangshi','','卷43','春霁江山似画图，醉垂鞭袂出康衢。
猖狂乱打貔貅鼓，懒慢迟修鸳鹭书。
老色渐来欺鬓发，闲晴将欲傲簪裾。
苔钱遍地知多少，买得花枝不落无。','',''),('quantangshi-42744','秋夕书怀 一','劉兼','quantangshi','','卷43','荒僻淹留岁已深，解龟无计恨难任。
守方半会蛮夷语，贺厦全忘燕雀心。
夜静倚楼悲月笛，秋寒欹枕泣霜砧。
宦情总逐愁肠断，一筯鲈鱼直万金。','',''),('quantangshi-42745','秋夕书怀 二','劉兼','quantangshi','','卷43','直气从来不入时，掩关慵更钓磻溪。
斯文未丧宣尼叹，吾道将穷阮籍悲。
轻粉覆霜凝夜砌，乱金铺菊织秋篱。
南阳卧久无人问，薄命非才有可疑。','',''),('quantangshi-42746','春霄','劉兼','quantangshi','','卷43','春云春日共朦胧，满院梨花半夜风。
宿酒未醒珠箔卷，艳歌初阕玉楼空。
五湖范蠡才堪重，六印苏秦道不同。
再取素琴聊假寐，南柯灵梦莫相通。','',''),('quantangshi-42747','秋夕书怀呈戎州郎中 一','劉兼','quantangshi','','卷43','素律初回枕簟凉，松风飘泊入华堂。
谭鸡寂默纱窗静，梦蝶萧条玉漏长。
归去水云多阻隔，别来情绪足悲伤。
霜砧月笛休相引，只有离襟泪两行。','',''),('quantangshi-42748','秋夕书怀呈戎州郎中 二','劉兼','quantangshi','','卷43','风送秋荷满鼻香，竹声敲玉近虚廊。
梦回故国情方黯，月过疎帘夜正凉。
菱镜也知移艳态，锦书其奈隔年光。
鸾胶处处难寻觅，断尽相思寸寸肠。','',''),('quantangshi-42749','晚楼寓怀','劉兼','quantangshi','','卷43','薄暮疎林宿鸟还，倚楼垂袂复凭栏。
月沈江底珠轮净，云锁峰头玉叶寒。
刘毅暂贫虽壮志，冯唐将老自低颜。
无言独对秋风立，拟把朝簪换钓竿。','',''),('quantangshi-42750','征妇怨','劉兼','quantangshi','','卷43','金闺寂寞罢妆台，玉筯阑干界粉腮。
花落掩关春欲暮，月圆欹枕梦初回。
鸾胶岂续愁肠断，龙劒难挥别绪开。
曾寄锦书无限意，塞鸿何事不归来。','',''),('quantangshi-42751','对镜','劉兼','quantangshi','','卷43','青镜重磨照白须，白须拈闲意何如。
故园迢遰千山外，荒郡淹留四载余。
风送竹声侵枕簟，月移花影过庭除。
秋霜满领难消释，莫读离骚失意书。','',''),('quantangshi-42752','春燕','劉兼','quantangshi','','卷43','多时窗外语呢喃，只要佳人卷绣帘。
大厦已成须庆贺，高门频入莫憎嫌。
花间舞蝶和香趁，江畔春泥带雨衔。
栖息数年情已厚，营巢争肯傍他檐。','',''),('quantangshi-42753','春晚寓怀','劉兼','quantangshi','','卷43','一承兑泽莅方州，八度春光照郡楼。
好景几将官吏醉，名山时领管弦游。
空花任尔频侵眼，老雪从他渐满头。
归去杜陵池阁在，只能欢笑不能愁。','',''),('quantangshi-42754','中春宴游','劉兼','quantangshi','','卷43','二月风光似洞天，红英翠萼簇芳筵。
楚王云雨迷巫峡，江令文章媚蜀笺。
歌黛入颦春袖敛，舞衣新绣晓霞鲜。
酒阑香袂初分散，笑指渔翁钓暮烟。','',''),('quantangshi-42755','春晚闲望','劉兼','quantangshi','','卷43','东风满地是梨花，只把琴心殢酒家。
立处晚楼横短笛，望中春草接平沙。
雁行断续晴天远，燕翼参差翠幕斜。
归计未成头欲白，钓舟烟浪思无涯。','',''),('quantangshi-42756','秋夕书事','劉兼','quantangshi','','卷43','摇落江天万木空，雁行斜戛塞垣风。
征闺捣月离愁远，旧馆眠云旅梦通。
郢客岂能陪下里，臯禽争肯恋樊笼。
此心旷荡谁相会，尽在南华十卷中。','',''),('quantangshi-42757','莲塘霁望','劉兼','quantangshi','','卷43','新秋菡萏发红英，向晚风飘满郡馨。
万叠水纹罗乍展，一双鸂鶒绣初成。
采莲女散吴歌阕，拾翠人归楚雨晴。
远岸牧童吹短笛，蓼花深处信牛行。','',''),('quantangshi-42758','送从弟舍人入蜀','劉兼','quantangshi','','卷43','嘉陵江畔饯行车，离袂难分十里余。
慷慨莫夸心似铁，留连不觉泪成珠。
风光川谷梅将发，音信云天雁未疎。
立马举鞭无限意，会稀别远拟何如。','',''),('quantangshi-42759','新回车院筵上作','劉兼','quantangshi','','卷43','回车院子未回车，三载疲民咏袴襦。
借寇已承英主诏，乞骸须上老臣书。
黄金蜀柳笼朱户，碧玉湘筠映绮疏。
因问满筵诗酒客，锦江何处有鲈鱼。','',''),('quantangshi-42760','寄长安郑员外','劉兼','quantangshi','','卷43','屈指良交十四人，隙驹风烛渐为尘。
当初花下三秦客，只有天涯二老身。
乘醉几同游北内，寻芳多共谒东隣。
此时阻隔关山远，月满江楼泪满巾。','',''),('quantangshi-42761','咸阳怀古','劉兼','quantangshi','','卷43','高秋咸镐起霜风，秦汉荒陵树叶红。
七国鬬鸡方贾勇，中原逐鹿更争雄。
南山漠漠云常在，渭水悠悠事旋空。
立马举鞭遥望处，阿房遗址夕阳东。','',''),('quantangshi-42762','春怨','劉兼','quantangshi','','卷43','绣林红岸落花钿，故去新来感自然。
绝塞杪春悲汉月，长林深夜泣缃弦。
锦书雁断应难寄，菱镜鸾孤貌可怜。
独倚画屏人不会，梦魂才别戍楼边。','',''),('quantangshi-42763','登楼寓望','劉兼','quantangshi','','卷43','凭高多是偶丸澜，红叶何堪照病颜。
万叠云山供远恨，一轩风物送秋寒。
背琴鹤客归松径，横笛牛童卧蓼滩。
独倚郡楼无限意，夕阳西去水东还。','',''),('quantangshi-42764','江岸独步','劉兼','quantangshi','','卷43','醉卓寒筇傍水行，渔翁不会独吟情。
龟能顾印谁相重，鹤偶乘轩自可轻。
簪组百年终长物，文章千古亦虚名。
是非得丧皆闲事，休向南柯与梦争。','',''),('quantangshi-42765','江楼望乡寄内','劉兼','quantangshi','','卷43','独上江楼望故乡，泪襟霜笛共凄凉。
云生陇首秋虽早，月在天心夜已长。
魂梦只能随蛱蝶，烟波无计学鸳鸯。
蜀笺都有三千幅，总写离情寄孟光。','',''),('quantangshi-42766','命妓不至','劉兼','quantangshi','','卷43','琴中难挑孰怜才，独对良宵酒数杯。
苏子黑貂将已尽，宋弘青鸟又空回。
月穿净牖霜成隙，风卷残花锦作堆。
欹枕梦魂何处去，醉和春色入天台。','',''),('quantangshi-42767','宣赐锦袍设上赠诸郡客','劉兼','quantangshi','','卷43','十月芙蓉花满枝，天庭驿骑赐寒衣。
将同玉蝶侵肌冷，也遣金鹏遍体飞。
夜卧始知多忝窃，昼行方觉转光辉。
深冬若得朝丹阙，太华峰前衣锦归。','',''),('quantangshi-42768','晨鸡','劉兼','quantangshi','','卷43','朱冠金距彩毛身，昧爽高声已报晨。
作瑞莫惭先贡楚，擅塲须信独推秦。
淮南也伴升仙犬，函谷曾容借晓人。
此日卑栖随饮啄，宰君驱我亦相驯。','',''),('quantangshi-42769','芳春','劉兼','quantangshi','','卷43','微雨微风隔昼帘，金炉檀炷冷慵添。
桃花满地春牢落，柳絮成堆雪弃嫌。
宝瑟不能邀卓氏，彩毫何必梦江淹。
宦情归兴休相挠，隼斾渔舟总未厌。','',''),('quantangshi-42770','春游 一','劉兼','quantangshi','','卷43','柳成金穗草如茵，载酒寻花共赏春。
先入醉乡君莫问，十年风景在三秦。','',''),('quantangshi-42771','春游 二','劉兼','quantangshi','','卷43','摇摇离绪不能持，满郡花开酒熟时。
羞听黄莺求善友，强随绿柳展愁眉。
隔云故国山千叠，傍水芳林锦万枝。
圣主未容归北阙，且将勤俭抚南夷。','',''),('quantangshi-42772','重阳感怀 一','劉兼','quantangshi','','卷43','重阳不忍上高楼，寒菊年年照暮秋。
万叠故山云总隔，两行乡泪血和流。
黄茅莽莽连边郡，红叶纷纷落钓舟。
归计未成年渐老，茱萸羞戴雪霜头。','',''),('quantangshi-42773','重阳感怀 二','劉兼','quantangshi','','卷43','载花乘酒上高山，四望秋空八极宽。
蜀国江山存不得，刘家豚犬取何难。
张仪旧壁苍苔厚，葛亮荒祠古木寒。
独对斜阳更惆怅，锦江东注似波澜。','',''),('quantangshi-42774','宴游池馆','劉兼','quantangshi','','卷43','绮筵金碧照芳菲，酒满瑶巵水满池。
去岁南岐离郡日，今春东蜀看花时。
俭莲发脸当筹着，绪柳生腰按柘枝。
座客半酣言笑狎，孔融怀抱正怡怡。','',''),('quantangshi-42775','寄高书记','劉兼','quantangshi','','卷43','齐朝庆裔祖敖曹，麟角无双凤九毛。
声价五侯争辟命，文章一代振风骚。
醉琴自寄陶家意，梦枕谁听益郡刀。
补衮应星曾奏举，北山南海孰为高。','',''),('quantangshi-42776','再见从弟舍人','劉兼','quantangshi','','卷43','屈指依稀十五年，鸾台秘阁位相悬。
分飞淮甸雁行断，重见江楼蟾影圆。
滞迹未偕朝北阙，高才方命入西川。
愿君通理须还早，拜庆慈亲几杖前。','',''),('quantangshi-42777','春昼醉眠','劉兼','quantangshi','','卷43','朱栏芳草绿纤纤，欹枕高堂卷昼帘。
处处落花春寂寂，时时中酒病恹恹。
塞鸿信断虽堪讶，梁燕词多且莫嫌。
自有卷书销永日，霜华未用鬓边添。','',''),('quantangshi-42778','中夏昼卧','劉兼','quantangshi','','卷43','寂寂无聊九夏中，傍檐依壁待清风。
壮图奇策无人问，不及南阳一卧龙。','',''),('quantangshi-42779','春夕寓兴','劉兼','quantangshi','','卷43','忘忧何必在庭萱，是事悠悠竟可宽。
酒病未能辞锦里，春狂又拟入桃源。
风吹杨柳丝千缕，月照梨花雪万团。
闲泥金徽度芳夕，幽泉石上自潺湲。','',''),('quantangshi-42780','春夜','劉兼','quantangshi','','卷43','薄薄春云笼皓月，杏花满地堆香雪。
醉垂罗袂倚朱栏，小数玉仙歌未阕。','',''),('quantangshi-42781','访饮妓不遇招酒徒不至','劉兼','quantangshi','','卷43','小桥流水接平沙，何处行云不在家。
毕卓未来轻竹叶，刘晨重到殢桃花。
琴樽冷落春将尽，帏幌萧条日又斜。
回首却寻芳草路，金鞍拂柳思无涯。','',''),('quantangshi-42782','春宴河亭','劉兼','quantangshi','','卷43','柳摆轻丝拂嫩黄，槛前流水满池塘。
一筵金翠临芳岸，四面烟花出粉墙。
舞袖逐风翻绣浪，歌尘随燕下雕梁。
蛮笺象管休凝思，且放春心入醉乡。','',''),('quantangshi-42783','蜀都道中','劉兼','quantangshi','','卷43','劒关云栈乱峥嵘，得丧何由险与平。
千载龟城终失守，一堆鬼录漫留名。
季年必不延昏主，薄赏那堪激懦兵。
李特后来多二世，纳降归拟尽公卿。','',''),('quantangshi-42784','万葛树','劉兼','quantangshi','','卷43','叶如羽盖岂堪论，百步清阴锁绿云。
善政已闻思召伯，英风偏称号将军。
静铺讲席麟经润，高拂□枝兔影分。
更有岁寒霜雪操，莫将樗栎拟相羣。','',''),('quantangshi-42785','春夕遣怀','劉兼','quantangshi','','卷43','穷通分定莫凄凉，且放欢情入醉乡。
范蠡扁舟终去相，冯唐半世只为郎。
风飘玉笛梅初落，酒泛金樽月未央。
休把虚名挠怀抱，九原丘陇尽侯王。','',''),('quantangshi-42786','西斋','劉兼','quantangshi','','卷43','西斋新竹两三茎，也有风敲碎玉声。
莫恨移来栏槛远，譬如元本此间生。','',''),('quantangshi-42787','新蝉','劉兼','quantangshi','','卷43','齐女屏帏失旧容，侍中冠冕有芳踪。
翅翻晚鬓寻香露，声引秋丝逐远风。
旅馆听时髭欲白，戍楼闻处叶多红。
只知送恨添愁事，谁见凌霄羽蜕功。','',''),('quantangshi-42788','寄滑州文秀大师','劉兼','quantangshi','','卷43','分飞屈指十三年，菡萏峰前别社莲。
薄宦偶然来左蜀，孤云何事在南燕。
一封瑶简音初达，两处金沙色共圆。
珍重汤休惠佳句，郡斋吟久不成眠。','',''),('quantangshi-42789','中春登楼 一','劉兼','quantangshi','','卷43','金杯不以涤愁肠，江郡芳时忆故乡。
两岸烟花春富贵，一楼风月夜凄凉。
王章莫耻牛衣泪，潘岳休惊鹤鬓霜。
归去莲花归未得，白云深处有茅堂。','',''),('quantangshi-42790','中春登楼 二','劉兼','quantangshi','','卷43','古今通塞莫咨嗟，谩把霜髯敌岁华。
失手已慙蛇有足，用心休为鼠无牙。
九天云净方怜月，一夜风高便厌花。
独倚郡楼人不会，钓舟春浪接平沙。','',''),('quantangshi-42791','自遣','劉兼','quantangshi','','卷43','未上亨衢独醉吟，赋成无处博黄金。
家人莫问张仪舌，国士须知豫让心。
照乘始堪沽善价，阳春争忍混凡音。
鵾鹏鳞翼途程在，九万风云海浪深。','',''),('quantangshi-42792','偶有下殇因而自遣','劉兼','quantangshi','','卷43','彭寿殇龄共两空，幻泡缘影梦魂中。
缺圆宿会长如月，飘忽浮生疾似风。
修短百年先后定，贤愚千古是非同。
南柯太守知人意，休问陶陶塞上翁。','',''),('quantangshi-42793','倦学','劉兼','quantangshi','','卷43','乐广亡来冰镜稀，宓妃嫫母混妍媸。
且于雾里藏玄豹，休向窗中问碧鸡。
百氏典坟空自苦，一堆萤雪竟谁知。
门前春色芳如昼，好掩书斋任所之。','',''),('quantangshi-42794','去年今日','劉兼','quantangshi','','卷43','去年今日到荣州，五骑红尘入郡楼。
貔虎只知迎太守，蛮夷不信是儒流。
奸豪已息时将泰，疲瘵全苏岁又周。
圣主若容辞重禄，便归烟水狎羣鸥。','',''),('quantangshi-42795','昼寝','劉兼','quantangshi','','卷43','花落青苔锦数重，书淫不觉避春慵。
[恣]情枕上飞庄蝶，任尔云间骋陆龙。
玉液未能消气魄，牙签方可涤昏蒙。
起来已被诗魔引，窗外寒敲翠竹风。','',''),('quantangshi-42796','郡斋寓兴','劉兼','quantangshi','','卷43','依约樊川似旭川，郡斋风物尽萧然。
秋庭碧藓铺云锦，晚阁红蕖簇水仙。
醉笔语狂挥粉壁，歌梁尘乱拂花钿。
情怀放荡无羁束，地角天涯亦信缘。','',''),('quantangshi-42797','郡楼闲望书怀','劉兼','quantangshi','','卷43','郡城楼阁绕江滨，风物清秋入望频。
铜鼓祭龙云塞庙，芦花飘市雪黏人。
莲披净沼羣香散，鹭点寒烟玉片新。
归去杜陵池馆在，且将朝服拂埃尘。','',''),('quantangshi-42798','玉烛花','劉兼','quantangshi','','卷43','袅袅香英三四枝，亭亭红艳照阶墀。
正当晚槛初开处，却似春闱就试时。
少女不吹方熠爚，东君偏惜未离披。
夜深斜倚朱栏外，拟把邻光借与谁。','',''),('quantangshi-42799','从弟舍人惠茶','劉兼','quantangshi','','卷43','曾求芳茗贡芜词，果沐颁霑味甚奇。
龟背起纹轻炙处，云头翻液乍烹时。
老丞倦闷偏宜矣，旧客过从别有之。
珍重宗亲相寄惠，水亭山阁自携持。','',''),('quantangshi-42800','再看光福寺牡丹','劉兼','quantangshi','','卷43','去年曾看牡丹花，蛱蝶迎人傍彩霞。
今日再游光福寺，春风吹我入仙家。
当筵芬馥歌唇动，倚槛娇羞醉眼斜。
来岁未朝金阙去，依前和露载归衙。','',''),('quantangshi-42801','海棠花','劉兼','quantangshi','','卷43','淡淡微红色不深，依依偏得似春心。
烟轻虢国颦歌黛，露重长门敛泪衿。
低傍绣帘人易折，密藏香蘂蝶难寻。
良宵更有多情处，月下芬芳伴醉吟。','',''),('quantangshi-42802','新竹','劉兼','quantangshi','','卷43','近窗卧砌两三丛，佐静添幽别有功。
影镂碎金初透月，声敲寒玉乍摇风。
无凭费叟烟波碧，莫信湘妃泪点红。
自是子猷偏爱尔，虚心高节雪霜中。','',''),('quantangshi-42803','木芙蓉','劉兼','quantangshi','','卷43','素灵失律诈风流，强把芳菲半载偷。
是叶葳蕤霜照夜，此花烂熳火烧秋。
谢莲色淡争堪种，陶菊香穠亦合羞。
谁道金风能肃物，因何厚薄不相侔。','',''),('quantangshi-42804','送二郎君归长安','劉兼','quantangshi','','卷43','我儿辞去泪双流，蜀郡秦川两处愁。
红叶满山归故国，黄茅徧地住他州。
荷衣晓挂慙官吏，菱镜秋窥讶鬓髹。
好向云泉营旧隐，莫教庄叟畏牺牛。','',''),('quantangshi-42805','送文英大师','劉兼','quantangshi','','卷43','屈指平阳别社莲，蟾光一百度曾圆。
孤云自在知何处，薄宦参差亦信缘。
山郡披风方穆若，花时分袂更凄然。
摇鞭相送嘉陵岸，回首羣峰隔翠烟。','',''),('quantangshi-42806','酬勾评事','劉兼','quantangshi','','卷43','闲庭欹枕正悲秋，忽觉新编浣远愁。
才薄只愁安雁户，年高空忆复渔舟。
鹭翘皓雪临汀岸，莲袅红香匝郡楼。
对景却慙无藻思，南金荆玉卒难酬。','',''),('quantangshi-42807','初至郡界','劉兼','quantangshi','','卷43','嘉陵江畔接荣川，两畔旌旗下濑船。
郡印已分炎瘴地，朝衣犹惹御炉烟。
莲塘小饮香随艇，月榭高吟水压天。
锦字莫嫌归路远，华夷一统太平年。','',''),('quantangshi-42808','到郡后有寄','劉兼','quantangshi','','卷43','蜀路新修尽坦平，交亲深幸再逢迎。
正当返袂思乡国，却似归家见弟兄。
霑泽只慙尧綍重，溯流还喜范舟轻。
欲将感恋裁书旨，多少渔笺写得成。','',''),('quantangshi-42809','长春节','劉兼','quantangshi','','卷43','圣朝佳节遇长春，跪捧金炉祝又焚。
宝藏发来天地秀，兵戈销后帝皇尊。
太平基址千年永，混一车书万古存。
更有馨香满芳槛，和风迟日在兰荪。','',''),('quantangshi-42810','登郡楼书事','劉兼','quantangshi','','卷43','偶奉纶书莅旭川，郡楼嘉致尽依然。
松欹鸟道云藏寺，月满渔舟水浸天。
望帝古祠花簇簇，锦城归路草芊芊。
有时倚槛垂双袂，故国风光似眼前。','',''),('quantangshi-42811','旭川祁宰思家而卒因述意呈秦川知己','劉兼','quantangshi','','卷43','岁稔民康绝讼论，政成公暇自由身。
朝看五马闲如社，夜拥双姬暖似春。
家计不忧凭冢子，官资无愧是朝臣。
岂同龌龊祁员外，至死悲凉一妇人。','',''),('quantangshi-42812','登郡楼书怀 一','劉兼','quantangshi','','卷43','烟雨楼台渐晦冥，锦江澄碧浪花平。
卞和未雪荆山耻，庄舃空伤越国情。
天际寂寥无雁下，云端依约有僧行。
登高欲继离骚咏，魂断愁深写不成。','',''),('quantangshi-42813','登郡楼书怀 二','劉兼','quantangshi','','卷43','边郡荒凉悲且歌，故园迢遰隔烟波。
琴声背俗终如是，剑气冲星又若何。
朝客渐通书信少，钓舟频引梦魂多。
北山更有移文者，白首无尘归去麽。','',''),('quantangshi-42814','登郡楼书怀 三','劉兼','quantangshi','','卷43','莫嗔阮氏哭途穷，万代深沈恨亦同。
瑞玉岂知将抵鹊，铅刀何事却屠龙。
九夷欲适嗟吾道，五柳终归效古风。
独倚郡楼无限意，满江烟雨正冥蒙。','',''),('quantangshi-42815','偶闻官吏举请辄有一篇寄从弟舍人','劉兼','quantangshi','','卷43','官吏潜陈借寇词，宦情乡梦两相违。
青城锦水无心住，紫阁莲峯有意归。
张翰鲈鱼因醉忆，孟光书信近春稀。
黄茅瘴色看看起，贪者犹疑别是机。','',''),('quantangshi-42816','诫是非','劉兼','quantangshi','','卷43','巧舌如簧总莫听，是非多自爱憎生。
三人告母虽投[杼]，百犬闻风只吠声。
辨玉且宽和氏罪，诬金须认不疑情。
因思畴昔游谈者，六国交驰亦受烹。','',''),('quantangshi-42817','简竖儒','劉兼','quantangshi','','卷43','蹄涔岂信有沧浪，萤火何堪竝太阳。
渊奥未曾探禹穴，矜夸便拟越丘墙。
小巫神气终须怯，下里音声必不长。
近日冰壶多晦昧，虎皮羊质也观光。','',''),('quantangshi-42818','贻诸学童','劉兼','quantangshi','','卷43','横经叉手步还趋，积善方知庆有余。
五个小雏离学院，一行新雁入贫居。
攘羊告罪言何直，舐犊牵情理岂虚。
劝汝立身须苦志，月中丹桂自扶疎。','',''),('quantangshi-42819','吴 黄金车','孫元晏','quantangshi','','卷43','分擘山河即渐开，许昌基业已倾颓。
黄金车与斑斓耳，早个须知入谶来。','',''),('quantangshi-42820','吴 赤壁','孫元晏','quantangshi','','卷43','会猎书来举国惊，祗应周鲁不教迎。
曹公一战奔波后，赤壁功传万古名。','',''),('quantangshi-42821','吴 鲁肃指囷','孫元晏','quantangshi','','卷43','破产移家事亦难，佐吴从此霸江山。
争教不立功勋得，指出千囷如等闲。','',''),('quantangshi-42822','吴 甘宁斫营','孫元晏','quantangshi','','卷43','夜深偷入魏军营，满寨惊忙火似星。
百口宝刀千匹绢，也应消得与甘宁。','',''),('quantangshi-42823','吴 徐盛','孫元晏','quantangshi','','卷43','欲把江山鼎足分，邢真衔册到江南。
当时将相谁堪重，徐盛将军最不甘。','',''),('quantangshi-42824','吴 鲁肃','孫元晏','quantangshi','','卷43','斫案兴言断众疑，鼎分从此定雄雌。
若无子敬心相似，争得乌林破魏师。','',''),('quantangshi-42825','吴 武昌','孫元晏','quantangshi','','卷43','西塞山高截九垓，谶谣终日自相催。
武昌鱼美应难恋，历数须归建业来。','',''),('quantangshi-42826','吴 顾雍','孫元晏','quantangshi','','卷43','赞国经纶更有谁，蔡公相叹亦相师。
贵为丞相封侯了，归后家人总不知。','',''),('quantangshi-42827','吴 吕蒙','孫元晏','quantangshi','','卷43','幼小家贫实可哀，愿征行去志难回。
不探虎穴求身达，争得人间富贵来。','',''),('quantangshi-42828','吴 介象','孫元晏','quantangshi','','卷43','好道君王遇亦难，变通灵异几多般。
介先生有神仙术，钓得鲈鱼在玉盘。','',''),('quantangshi-42829','吴 濡须坞','孫元晏','quantangshi','','卷43','风揭洪涛响若雷，枕波为垒险相隈。
莫言有个濡须坞，几度曹公失志回。','',''),('quantangshi-42830','吴 周泰','孫元晏','quantangshi','','卷43','名与诸公又不同，金疮痕在满身中。
不将御盖宣恩泽，谁信将军别有功。','',''),('quantangshi-42831','吴 张纮','孫元晏','quantangshi','','卷43','东部张公与众殊，共施经畧赞全吴。
陈琳漫自称雄伯，神气应须怯大巫。','',''),('quantangshi-42832','吴 太史慈','孫元晏','quantangshi','','卷43','圣德招贤远近知，曹公心计却成欺。
陈韩昔日尝投楚，岂是当归召得伊。','',''),('quantangshi-42833','吴 孙坚后','孫元晏','quantangshi','','卷43','委存张公翊圣材，几将贤德赞文台。
争教不霸江山得，日月征曾入梦来。','',''),('quantangshi-42834','吴 陆统','孫元晏','quantangshi','','卷43','将军身殁有儿孤，虎子为名教读书。
更向宫中教骑马，感君恩重合何如。','',''),('quantangshi-42835','吴 青盖','孫元晏','quantangshi','','卷43','历数将终势已摧，不修君德更堪哀。
被他青盖言相误，元是须教入晋来。','',''),('quantangshi-42836','晋 七宝鞭','孫元晏','quantangshi','','卷43','天命须知岂偶然，乱臣徒欲用兵权。
圣谟庙畧还应别，浑不消他七宝鞭。','',''),('quantangshi-42837','晋 庾悦鹅炙','孫元晏','quantangshi','','卷43','春暖江南景气新，子鹅炙美就中珍。
庾家厨盛刘公困，浑弗相贻也恼人。','',''),('quantangshi-42838','晋 谢玄','孫元晏','quantangshi','','卷43','百万兵来逼合肥，谢玄为将统雄师。
旌旗首尾千余里，浑不消他一局棊。','',''),('quantangshi-42839','晋 谢混','孫元晏','quantangshi','','卷43','尚主当初偶未成，此时谁合更关情。
可怜谢混风华在，千古翻传禁脔名。','',''),('quantangshi-42840','晋 陆玩','孫元晏','quantangshi','','卷43','陆公高论亦由衷，谦让还慙未有功。
天下忠良人欲尽，始应交我作三公。','',''),('quantangshi-42841','晋 王坦之','孫元晏','quantangshi','','卷43','晋祚安危只此行，坦之何必苦忧惊。
谢公合定寰区在，争遣当时事得成。','',''),('quantangshi-42842','晋 蒲葵扇','孫元晏','quantangshi','','卷43','抛舍东山岁月遥，几施经畧挫雄豪。
若非名德喧寰宇，争得蒲葵价数高。','',''),('quantangshi-42843','晋 王郎','孫元晏','quantangshi','','卷43','太尉门庭亦甚高，王郎名重礼相饶。
自家妻父犹如此，谁更逢君得折腰。','',''),('quantangshi-42844','晋 刘毅','孫元晏','quantangshi','','卷43','遶牀堪壮喝卢声，似铁容仪众尽惊。
二十七人同举义，几人全得旧功名。','',''),('quantangshi-42845','晋 王恭','孫元晏','quantangshi','','卷43','春风濯濯柳容仪，鹤氅神情举世推。
可惜教君仗旄钺，枉将心地托牢之。','',''),('quantangshi-42846','晋 谢公赌墅','孫元晏','quantangshi','','卷43','发遣将军欲去时，畧无情挠只贪棊。
自从乞与羊昙后，赌墅功成更有谁。','',''),('quantangshi-42847','晋 苻坚投棰','孫元晏','quantangshi','','卷43','投棰填江语未终，谢安乘此立殊功。
三台星烂干坤在，且与张华死不同。','',''),('quantangshi-42848','晋 卫玠','孫元晏','quantangshi','','卷43','叔宝羊车海内稀，山家女壻好风姿。
江东士女无端甚，看杀玉人浑不知。','',''),('quantangshi-42849','晋 郭璞脱襦','孫元晏','quantangshi','','卷43','吟坐因思郭景纯，每言穷达似通神。
到头分命难移改，解脱清襦与别人。','',''),('quantangshi-42850','晋 庾楼','孫元晏','quantangshi','','卷43','江州楼上月明中，从事同登眺远空。
玉树忽薶千载后，有谁重此继清风。','',''),('quantangshi-42851','晋 新亭','孫元晏','quantangshi','','卷43','容易乘虚逼帝畿，满江艛橹与旌旗。
卢循若解新亭上，胜负还应未可知。','',''),('quantangshi-42852','宋 大岘','孫元晏','quantangshi','','卷43','大岘才过喜可知，指空言已副心期。
公孙计策嗟无用，天与南朝作霸基。','',''),('quantangshi-42853','宋 放宫人','孫元晏','quantangshi','','卷43','纳谏廷臣免犯颜，自然恩可霸江山。
姚兴侍女方承宠，放出宫闱若等闲。','',''),('quantangshi-42854','宋 借南苑','孫元晏','quantangshi','','卷43','人主词应不偶然，几人曾说笑掀天。
不知南苑今何在，借与张公三百年。','',''),('quantangshi-42855','宋 谢澹云霞友','孫元晏','quantangshi','','卷43','仗气凌人岂可亲，只将范泰是知闻。
缘何唤作云霞友，却恐云霞未似君。','',''),('quantangshi-42856','宋 乌衣巷','孫元晏','quantangshi','','卷43','古迹荒基好叹嗟，满川吟景只烟霞。
乌衣巷在何人住，回首令人忆谢家。','',''),('quantangshi-42857','宋 袁粲','孫元晏','quantangshi','','卷43','负才尚气满朝知，高卧闲吟见客稀。
独步何人识袁尹，白杨郊外醉方归。','',''),('quantangshi-42858','宋 刘伯龙','孫元晏','quantangshi','','卷43','位重何如不厌贫，伯龙孤子只修身。
固知生计还须有，穷鬼临时也笑人。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-42859','宋 王方平','孫元晏','quantangshi','','卷43','拂衣耕钓已多时，江上山前乐可知。
着却貂裘将采药，任他人唤作渔师。','',''),('quantangshi-42860','宋 黄罗襦','孫元晏','quantangshi','','卷43','戚属羣臣尽见猜，预忧身后又堪哀。
到头委付何曾是，虚把罗襦与彦回。','',''),('quantangshi-42861','宋 谢朏','孫元晏','quantangshi','','卷43','谢家诸子尽兰香，各震芳名满帝乡。
惟有千金更堪重，只将高卧向齐王。','',''),('quantangshi-42862','宋 羊玄保','孫元晏','quantangshi','','卷43','运命将来各有期，好官才阙即思之。
就中堪爱羊玄保，偏受君王分外知。','',''),('quantangshi-42863','齐 谢朏','孫元晏','quantangshi','','卷43','解玺传呼诏侍中，却来高卧岂疏慵。
此时忠节还希有，堪羡君王特地容。','',''),('quantangshi-42864','齐 小儿执烛','孫元晏','quantangshi','','卷43','谢公情量已难量，忠宋心诚岂暂忘。
执烛小儿浑放去，略无言语与君王。','',''),('quantangshi-42865','齐 王僧佑','孫元晏','quantangshi','','卷43','肯与公卿作等伦，澹然名德只推君。
任他车骑来相访，箫鼓盈庭似不闻。','',''),('quantangshi-42866','齐 王僧虔','孫元晏','quantangshi','','卷43','位高名重不堪疑，恳让仪同帝亦知。
不学常流争进取，却忧门有二台司。','',''),('quantangshi-42867','齐 明帝裹蒸','孫元晏','quantangshi','','卷43','至尊尊贵异人间，御膳天厨岂等闲。
惜得裹蒸无用处，不如安霸取江山。','',''),('quantangshi-42868','齐 郁林王','孫元晏','quantangshi','','卷43','强哀强惨亦从伊，归到私庭喜可知。
喜字漫书三十六，到头能得几多时。','',''),('quantangshi-42869','齐 何氏小山','孫元晏','quantangshi','','卷43','显达何曾肯系心，筑居郊外好园林。
赚他谢朏出山去，赢得高名直至今。','',''),('quantangshi-42870','齐 王伦之','孫元晏','quantangshi','','卷43','豫章太守重词林，图画陈蕃与华歆。
更奠子将并孺子，为君千载作知音。','',''),('quantangshi-42871','齐 潘妃','孫元晏','quantangshi','','卷43','曾步金莲宠绝伦，岂甘今日委埃尘。
玉儿还有怀恩处，不肯将身嫁小臣。','',''),('quantangshi-42872','齐 王亮','孫元晏','quantangshi','','卷43','后见梁王未免哀，奈何无计拯倾颓。
若教彼相颠扶得，争遣明公到此来。','',''),('quantangshi-42873','梁 分宫女','孫元晏','quantangshi','','卷43','涤荡齐宫法令新，分张宫女二千人。
可怜无限如花貌，重见世间桃李春。','',''),('quantangshi-42874','梁 马仙埤','孫元晏','quantangshi','','卷43','齐朝太守不甘降，忠节当时动四方。
义士要教天下见，且留君住待袁昂。','',''),('quantangshi-42875','梁 勍敌','孫元晏','quantangshi','','卷43','传闻天子重儒才，特为皇华绮宴开。
今日方惊遇勍敌，此人元自北朝来。','',''),('quantangshi-42876','梁 蔡撙','孫元晏','quantangshi','','卷43','紫茄白苋以为珍，守任清真转更贫。
不饮吴兴郡中水，古今能有几多人。','',''),('quantangshi-42877','梁 楚祠','孫元晏','quantangshi','','卷43','曾与萧侯醉玉杯，此时神影尽倾颓。
莫云千古无灵圣，也向西川助敌来。','',''),('quantangshi-42878','梁 谢朏小舆','孫元晏','quantangshi','','卷43','小舆升殿掌钧台，不免无憀却忆回。
应恨被他何胤误，悔先容易出山来。','',''),('quantangshi-42879','梁 八关斋','孫元晏','quantangshi','','卷43','依凭金地甚虔诚，忍溺空王为圣明。
内殿设斋申祷祝，岂无功德及台城。','',''),('quantangshi-42880','梁 庾信','孫元晏','quantangshi','','卷43','苦心词赋向谁谈，沦落周朝志岂甘。
可惜多才庾开府，一生惆怅忆江南。','',''),('quantangshi-42881','陈 王僧辨','孫元晏','quantangshi','','卷43','彼此英雄各有名，石头高卧拟争衡。
当时堪笑王僧辨，待欲将心托圣明。','',''),('quantangshi-42882','陈 武帝蚌盘','孫元晏','quantangshi','','卷43','金翠丝黄略不舒，蚌盘清宴意何如。
岂知三阁繁华日，解为君王妙破除。','',''),('quantangshi-42883','陈 虞居士','孫元晏','quantangshi','','卷43','苦谏将军总不知，几随烟焰作尘飞。
东山居士何人识，惟有君王却许归。','',''),('quantangshi-42884','陈 姚察','孫元晏','quantangshi','','卷43','曾佐徐陵向北游，剖陈疑事动名流。
却归掌选清何甚，一匹花綀不肯收。','',''),('quantangshi-42885','陈 宣帝伤将卒','孫元晏','quantangshi','','卷43','前后兵师战胜回，百余城垒尽归来。
当时将卒应知感，况得君王为举哀。','',''),('quantangshi-42886','陈 临春阁','孫元晏','quantangshi','','卷43','临春高阁上侵云，风起香飘数里闻。
自是君王正沈醉，岂知消息报隋军。','',''),('quantangshi-42887','陈 [结]绮阁','孫元晏','quantangshi','','卷43','结绮高宜眺海涯，上凌丹汉拂云霞。
一千朱翠同居此，争奈恩多属丽华。','',''),('quantangshi-42888','陈 望仙阁','孫元晏','quantangshi','','卷43','多少沈檀结筑成，望仙为号倚青冥。
不知孔氏何形状，醉得君主不解醒。','',''),('quantangshi-42889','陈 三阁','孫元晏','quantangshi','','卷43','三阁相通绮宴开，数千朱翠遶周回。
只知断送君王醉，不道韩擒已到来。','',''),('quantangshi-42890','陈 狎客','孫元晏','quantangshi','','卷43','八宫妃尽赋篇章，风揭歌声锦绣香。
选得十人为狎客，有谁能解谏君王。','',''),('quantangshi-42891','陈 淮水','孫元晏','quantangshi','','卷43','文物衣冠尽入秦，六朝繁盛忽埃尘。
自从淮水干枯后，不见王家更有人。','',''),('quantangshi-42892','陈 江令宅','孫元晏','quantangshi','','卷43','不向南朝立谏名，旧居基在事分明。
令人惆怅江中令，只作篇章过一生。','',''),('quantangshi-42893','陈 后庭舞','孫元晏','quantangshi','','卷43','嬿婉回风态若飞，丽华翘袖玉为姿。
后庭一曲从教舞，舞破江山君未知。','',''),('quantangshi-42894','班倢伃','嚴識玄','quantangshi','','卷43','贱妾如桃李，君王若岁时。
秋风一已劲，摇落不胜悲。
寂寂苍苔满，沈沈绿草滋。
繁华非此日，指辇竞何辞。','',''),('quantangshi-42895','赋得御制句朔野阵云飞','何象','quantangshi','','卷43','塞日穿痕断，边鸿背影飞。
缥缈浮黄屋，阴沈护御衣。','',''),('quantangshi-42896','宿金河戍','張震','quantangshi','','卷43','朝发铁麟驿，夕宿金河戍。
奔波急王程，一日千里路。
但见容鬓改，不知岁华暮。
悠悠沙漠行，王事弥多故。','',''),('quantangshi-42897','补新宫 一','丘光庭','quantangshi','','卷43','奂奂新宫，礼乐其融。
尔德惟贤，尔□维忠。
为忠以公，斯筵是同。
人之醉我，与我延宾。','',''),('quantangshi-42898','补新宫 二','丘光庭','quantangshi','','卷43','奂奂新宫，既奂而轮。
其固如山，其俨如云。
其寝斯安，□□□分。
我既考落，以燕羣臣。','',''),('quantangshi-42899','补新宫 三','丘光庭','quantangshi','','卷43','奂奂新宫，既祭既延。
我□□镛，于以醉贤。
有礼无愆，我有斯宫。
斯宫以安，康后万年。','',''),('quantangshi-42900','补茅鸱 一','丘光庭','quantangshi','','卷43','茅鸱茅鸱，无集我冈。
汝食汝饱，莫我为祥。
愿弹去汝，来彼凤凰。
来彼凤凰，其仪有章。','',''),('quantangshi-42901','补茅鸱 二','丘光庭','quantangshi','','卷43','茅鸱茅鸱，无啄我雀。
汝食汝饱，莫我肯略。
愿弹去汝，来彼瑞鹊。
来彼瑞鹊，其音可乐。','',''),('quantangshi-42902','补茅鸱 三','丘光庭','quantangshi','','卷43','茅鸱茅鸱，无搏鷅鶹。
汝食汝饱，莫我为休。
愿弹去汝，来彼鳲鸠。
来彼鳲鸠，食子其周。','',''),('quantangshi-42903','补茅鸱 四','丘光庭','quantangshi','','卷43','茅鸱茅鸱，无㗲我陵。
汝食汝饱，莫我好声。
愿弹去汝，来彼苍鹰。
来彼苍鹰，祭鸟是征。','',''),('quantangshi-42904','瑕瑜不相掩','武翊黃','quantangshi','','卷43','抱璞应难辨，妍媸每自融。
贞姿偏特达，微玷遇磨砻。
泾渭流终异，瑕瑜自不同。
半曾光透石，未掩气如虹。
缜密诚为智，包藏岂谓忠。
停看分美恶，今得值良工。','',''),('quantangshi-42905','袁江口怀王司勋王吏部','李祜','quantangshi','','卷43','京华不啻三千里，客泪如今一万双。
若个最为相忆处，青枫黄竹入袁江。','',''),('quantangshi-42906','赠进士李守微','韓嶼','quantangshi','','卷43','一定童颜老岁华，贫寒游历贵人家。
炼成正气功应大，养得元神道不差。
舃曳鹤毛干毾𣬬，杖携筇节瘦槎牙。
如何蓬阆不归去，落尽蟠桃几度花。','',''),('quantangshi-42907','马上有见','李茂復','quantangshi','','卷43','行尽疎林见小桥，绿杨深处有红蕉。
无端眼界无分别，安置心头不肯销。','',''),('quantangshi-42908','自叹','李茂復','quantangshi','','卷43','落日西山近一竿，世间恩爱极难𢬵。
近来不作颠狂事，免被冤家恶眼看。','',''),('quantangshi-42909','赠吴圆','李曜','quantangshi','','卷43','经年理郡少欢娱，为习干戈间饮徒。
今日临行尽交割，分明收取媚川珠。','',''),('quantangshi-42910','答李曜','吳圓','quantangshi','','卷43','曳履优容日日欢，须言达德倍丸澜。
韶光今已输先手，领得蠙珠掌上看。','',''),('quantangshi-42911','和訾家洲宴游','陸弘休','quantangshi','','卷43','新春蘂绽訾家洲，信是南方最胜游。
酒满百分殊不怕，人添一岁更堪愁。
莺声暗逐歌声艳，花态还随舞态羞。
莫惜今朝同酩酊，任他龟鹤与蜉蝣。','',''),('quantangshi-42912','题贾岛墓','安錡','quantangshi','','卷43','倚恃才难继，昂藏貌不恭。
骑驴冲大尹，夺卷忤宣宗。
驰誉超先辈，居官下我侬。
司仓旧曹署，一见一心忡。','',''),('quantangshi-42913','赠别营妓卿卿','油蔚','quantangshi','','卷43','怜君无那是多情，枕上相看直到明。
日照绿窗人去住，鸦啼红粉泪纵横。
愁肠只向金闺断，白发应从玉塞生。
为报花时少惆怅，此生终不负卿卿。','',''),('quantangshi-42914','巢燕','胡玢','quantangshi','','卷43','燕来巢我檐，我屋非高大。
所贵儿童善，保尔无殃祸。
莫巢孀妇家，孀妇怨孤坐。
妬尔长双飞，打尔危巢破。','',''),('quantangshi-42915','庐山桑落洲','胡玢','quantangshi','','卷43','莫问桑田事，但看桑落洲。
数家新住处，昔日大江流。
古岸崩欲尽，平沙长未休。
想应百年后，人世更悠悠。','',''),('quantangshi-42916','石楠树','胡玢','quantangshi','','卷43','本自清江石上生，移栽此处称闲情。
青云士尽识珍木，白屋人多唤俗名。
重布绿阴滋藓色，深藏好鸟引雏声。
余今一日千回看，每度看来眼益明。','',''),('quantangshi-42917','句','胡玢','quantangshi','','卷43','轮中别有物，光外更无空。','',''),('quantangshi-42918','酒胡子','盧注','quantangshi','','卷43','同心相遇思同欢，擎出酒胡当玉盘。
盘中臲卼不自定，四座清宾注意看。
可亦不在心，否亦不在面，徇客随时自圆转。
酒胡五藏属他人，十分亦是无情劝。
尔不耕，亦不饥。
尔不蚕，亦有衣。
有眼不能分黼黻，有口不能明是非。
鼻何尖，眼何碧，仪形本非天地力。
雕镌匠意苦多端，翠帽朱衫巧妆饰。
长安斗酒十千酤，刘伶平生为酒徒。
刘伶虚向酒中死，不得酒池中拍浮。
酒胡一滴不入眼，空令酒胡名酒胡。','',''),('quantangshi-42919','西施','盧注','quantangshi','','卷43','惆怅兴亡系绮罗，世人犹自选青娥。
越王解破夫差国，一个西施已是多。','',''),('quantangshi-42920','题西施浣纱石','胡幽貞','quantangshi','','卷43','一朝入紫宫，万古遗芳尘。
至今溪边花，不敢娇青春。','',''),('quantangshi-42921','归四明','胡幽貞','quantangshi','','卷43','海色连四明，仙舟去容易。
天籍岂輙问，不是卑朝士。','',''),('quantangshi-42922','送人游邵州','狄煥','quantangshi','','卷43','春江正渺渺，送别两依依。
烟里棹将远，渡头人未归。
渔家侵叠浪，岛树挂残晖。
况入湖湘路，那堪花乱飞。','',''),('quantangshi-42923','题柳','狄煥','quantangshi','','卷43','天南与天北，此处影婆娑。
翠色折不尽，离情生更多。
雨余笼灞岸，烟暝夹隋河。
自有佳名在，秦松继得麽。','',''),('quantangshi-42924','咏南岳径松','狄煥','quantangshi','','卷43','一阵雨声归岳峤，两条寒色下潇湘。
客吟晚景停孤棹，僧踏清阴彻上方。','',''),('quantangshi-42925','句','狄煥','quantangshi','','卷43','数点当秋霁，不知何处峰？更无声接续，空有影相随。','',''),('quantangshi-42926','浔阳观水','韓溉','quantangshi','','卷43','朝宗汉水接阳台，唅呀填坑吼作雷。
莫见九江平稳去，还从三峡嶮巇来。
南经梦泽宽浮日，西出岷山劣泛杯。
直至沧溟涵贮尽，沈深不动浸昭回。','',''),('quantangshi-42927','水','韓溉','quantangshi','','卷43','方圆不定性空求，东注沧溟早晚休。
高截碧塘长耿耿，远飞青嶂更悠悠。
潇湘月浸千年色，梦泽烟含万古愁。
别有岭头呜咽处，为君分作断肠流。','',''),('quantangshi-42928','松','韓溉','quantangshi','','卷43','倚空高槛冷无尘，往事闲征梦欲分。
翠色本宜霜后见，寒声偏向月中闻。
啼猿想带苍山雨，归鹤应和紫府云。
莫向东园竞桃李，春光还是不容君。','',''),('quantangshi-42929','柳','韓溉','quantangshi','','卷43','雪尽青门弄影微，暖风迟日早莺归。
如凭细叶留春色，须把长条系落晖。
彭泽有情还郁郁，隋堤无主自依依。
世间惹恨偏饶此，可是行人折赠稀。','',''),('quantangshi-42930','竹','韓溉','quantangshi','','卷43','树色连云万叶开，王孙不厌满庭栽。
凌霜尽节无人见，终日虚心待凤来。
谁许风流添兴咏，自怜潇洒出尘埃。
朱门处处多闲地，正好移阴覆翠苔。','',''),('quantangshi-42931','鹊','韓溉','quantangshi','','卷43','才见离巢羽翼开，尽能轻扬出尘埃。
人间树好纷纷占，天上桥成草草回。
几度送风临玉户，一时传喜到妆台。
若教颜色如霜雪，应与清平作瑞来。','',''),('quantangshi-42932','灯','韓溉','quantangshi','','卷43','分影由来恨不同，绿窗孤馆两何穷。
荧煌短焰长疑暗，零落残花旋委空。
几处隔帘愁夜雨，谁家当户怯秋风。
莫言明灭无多重，曾比人生一世中。','',''),('quantangshi-42933','句','韓溉','quantangshi','','卷43','门掩落花人别后，窗含残月酒醒时。','',''),('quantangshi-42934','春怨','昌緒','quantangshi','','卷43','打起黄莺儿，莫教枝上啼。
啼时惊妾梦，不得到辽西。','',''),('quantangshi-42935','放猨','曾麻幾','quantangshi','','卷43','孤猨锁槛岁年深，放出城南百丈林。
绿水任从联臂饮，青山不用断肠吟。','',''),('quantangshi-42936','观兄弟同夜成婚','鄭軌','quantangshi','','卷43','棠棣开双萼，夭桃照两花。
分庭含佩响，隔扇偶妆华。
迎风俱似雪，映绮共如霞。
今宵二神女，并在一仙家。','',''),('quantangshi-42937','夏弹琴','劉戩','quantangshi','','卷43','碧山本岑寂，素琴何清幽。
弹为风入松，崖谷飒已秋。
庭鹤舞白雪，泉鱼跃洪流。
予欲娱世人，明月难暗投。
感叹未终曲，泪下不可收。
呜呼钟子期，零落归荒丘。
死而若有知，魂兮从我游。','',''),('quantangshi-42938','过函谷关','楊齊哲','quantangshi','','卷43','地险崤函北，途经分陕东。
逶迤众山尽，荒凉古塞空。
河光流晓日，树影散朝风。','',''),('quantangshi-42939','伤死奴','劉夷道','quantangshi','','卷43','丹籍生涯浅，黄泉归路深。
不及江陵树，千秋长作林。','',''),('quantangshi-42940','侍宴赋得起坐弹鸣琴二首 一','楊希道','quantangshi','','卷43','北林鹊夜飞，南轩月初进。
调弦发清征，荡心怯褊恡。
变作离鸿声，还入思归引。
长叹未终极，秋风飘素鬓。','',''),('quantangshi-42941','侍宴赋得起坐弹鸣琴二首 二','楊希道','quantangshi','','卷43','丝传园客意，曲奏楚妃情。
罕有知音者，空劳流水声。','',''),('quantangshi-42942','咏琴','楊希道','quantangshi','','卷43','久擅龙门质，孤竦峄阳名。
齐[娥]初发弄，赵女正调声。
嘉客勿遽反，繁弦曲未成。','',''),('quantangshi-42943','咏笙','楊希道','quantangshi','','卷43','短长插凤翼，洪细摹鸾音。
能令楚妃叹，复使荆王吟。
切切孤竹管，来应云和琴。','',''),('quantangshi-42944','咏舞','楊希道','quantangshi','','卷43','二八如同雪，三春类早花。
分行向烛转，一种逐风斜。','',''),('quantangshi-42945','咏妓','王勣','quantangshi','','卷43','妖姬饰靓妆，窈窕出兰房。
日照当轩影，风吹满路香。
早时歌扇薄，今日舞衫长。
不应令曲误，持此试周郎。','',''),('quantangshi-42946','益州城西张超亭观妓','王勣','quantangshi','','卷43','落日明歌席，行云逐舞人。
江前飞暮雨，梁上下轻尘。
冶服看疑画，妆台望似春。
高车勿遽返，长袖欲相亲。','',''),('quantangshi-42947','辛司法宅观妓','王勣','quantangshi','','卷43','南国佳人至，北堂罗荐开。
长裙随凤管，促柱送鸾杯。
云光身后落，雪态掌中回。
到愁金谷晚，不怪玉山颓。','',''),('quantangshi-42948','秋池一枝莲','郭恭','quantangshi','','卷43','秋至皆零落，凌波独吐红。
托根方得所，未肯即随风。','',''),('quantangshi-42949','婕妤怨','張烜','quantangshi','','卷43','贱妾裁纨扇，初摇明月姿。
君王看舞席，坐起秋风时。
玉树清御路，金陈翳垂丝。
昭阳无分理，愁寂任前期。','',''),('quantangshi-42950','长门怨','張修之','quantangshi','','卷43','长门落景尽，洞房秋月明。
玉阶草露积，金屋网尘生。
妾妒今应改，君恩昔未平。
寄语临邛客，何时作赋成。','',''),('quantangshi-42951','王昭君','梁獻','quantangshi','','卷43','图画失天真，容华坐误人。
君恩不可再，妾命在和亲。
泪点关山月，衣销边塞尘。
一闻阳鸟至，思绝汉宫春。','',''),('quantangshi-42952','芳树','符子珪','quantangshi','','卷43','芳树宜三月，曈曈艳绮年。
香交珠箔气，阴占绿庭烟。
小叶风吹长，繁花露濯鲜。
遂令穠李儿，折取簪花钿。','',''),('quantangshi-42953','观妓','李何','quantangshi','','卷43','向晚小乘游，朝来新上头。
从来许长袖，未有客难留。','',''),('quantangshi-42954','邯郸侠少年','鄭鏦','quantangshi','','卷43','夜渡浊河津，衣中劒满身。
兵符劫晋鄙，匕首刺秦人。
执事非无胆，高堂念有亲。
昨缘秦苦赵，来往大梁频。','',''),('quantangshi-42955','玉阶怨','鄭鏦','quantangshi','','卷43','昔日同飞燕，今朝似伯劳。
情深争掷果，宠罢怨残桃。
别殿春心断，长门夜树高。
虽能不自悔，谁见旧衣褒。','',''),('quantangshi-42956','婕妤怨','鄭鏦','quantangshi','','卷43','南国承欢日，东方候晓时。
那能妒褒姒，祗爱笑唐儿。
宝叶随云髻，珠丝锻履綦。
不知飞燕意，何事苦相疑。','',''),('quantangshi-42957','入塞曲','鄭鏦','quantangshi','','卷43','留滞边庭久，归思岁月赊。
黄云同入塞，白首独还家。
宛马随秦草，胡人问汉花。
还伤李都尉，独自没黄沙。','',''),('quantangshi-42958','赏残花','紇干著','quantangshi','','卷43','零落多依草，芳香散着人。
低檐一枝在，犹占满堂春。','',''),('quantangshi-42959','古仙词','紇干著','quantangshi','','卷43','珠幡绛节晓霞中，汉武清斋待少翁。
不向人间恋春色，桃花自满紫阳宫。','',''),('quantangshi-42960','感春词','紇干著','quantangshi','','卷43','未得鸣珂谒汉宫，江头寂寞向春风。
悲歌一曲心应醉，万叶千花泪眼中。','',''),('quantangshi-42961','灞上','紇干著','quantangshi','','卷43','鸣鞭晚日禁城东，渭水晴烟灞岸风。
都傍柳阴回首望，春天楼阁五云中。','',''),('quantangshi-42962','凌云寺','李習','quantangshi','','卷43','古寺临江间碧波，石梯深入白云窠。
僧禅寂寂无人迹，满地落花春又过。','',''),('quantangshi-42963','凤栖怨','顏舒','quantangshi','','卷43','佳人名莫愁，珠箔上花钩。
清镜鸳鸯匣，新妆翡翠楼。
捣衣明月夜，吹管白云秋。
惟恨金吾子，年年向陇头。','',''),('quantangshi-42964','春女怨','朱絳','quantangshi','','卷43','独坐纱窗刺绣迟，紫荆花下啭黄鹂。
欲知无限伤春意，尽在停针不语时。','',''),('quantangshi-42965','失题','徐璧','quantangshi','','卷43','双燕今朝至，何时发海滨？窥檐向人语，如道故乡春。','',''),('quantangshi-42966','催妆','徐安期','quantangshi','','卷43','传闻烛下调红粉，明镜台前别作春。
不须面上浑妆却，留着双眉待画人。','',''),('quantangshi-42967','隔壁闻奏伎','裴延','quantangshi','','卷43','徒闻管弦切，不见舞腰回。
赖有歌梁合，尘飞一半来。','',''),('quantangshi-42968','咏翦花','裴延','quantangshi','','卷43','花寒未聚蝶，色艳已惊人。
悬知陌上柳，应妒手中春。','',''),('quantangshi-42969','叹美人照镜','陳述','quantangshi','','卷43','插花枝共动，含笑靥俱生。
衫分两处色，钏响一边声。
就中还妒影，恐夺可怜名。','',''),('quantangshi-42970','开缄怨','朱琳','quantangshi','','卷43','夫婿边庭久，幽闺恨几重。
玉琴知别日，金镜识愁容。
懒寄云中服，慵开海上封。
年年得衣惯，且试莫裁缝。','',''),('quantangshi-42971','杂言','謝陶','quantangshi','','卷43','天不与人言，祸福能自至。
水火虽活人，暂不得即死。
蹈之焚斯须，凭之溺容易。
水火与祸福，岂有先言耳。','',''),('quantangshi-42972','书事','何贊','quantangshi','','卷43','果决生涯向路中，西投知己话从容。
云遮剑阁三千里，水隔瞿塘十二峰。
阔步文翁坊里月，闲寻杜老宅边松。
到头须卜林泉隐，自愧无能继卧龙。','',''),('quantangshi-42973','雁塔','解彥融','quantangshi','','卷43','峥嵘澈倒景，刻峭俯无地。
勇进攀有缘，即嶮恐迷坠。
窅然丧五蕴，蠢尔怀万类。
实际罔他寻，波罗必可致。
南山缭上苑，只树连岩翠。
北斗临帝城，扶宫切太清。
餐和裨日用，味道懿天明。
绿野冷风浃，紫微佳气晶。
驯禽演法要，忍草藉经行。
本愿从兹适，方知物世轻。','',''),('quantangshi-42974','昭君怨','董初','quantangshi','','卷43','新年犹尚小，那堪远聘秦。
裾衫沾马汗，眉黛染胡尘。
举眼无相识，路逢皆异人。
唯有梅将李，犹带故乡春。','',''),('quantangshi-42975','南山','賀朝清','quantangshi','','卷43','湖北雨初晴，湖南山尽见。
岩岩石帆影，如得海风便。
仙穴茅山峰，彩云时一见。
邀君共探此，异箓残几卷。','',''),('quantangshi-42976','赋得游人久不归','賀朝清','quantangshi','','卷43','乡关眇天末，引领怅怀归。
羁旅久淫滞，物色屡芳菲。
稍觉私意尽，行看鬔鬓稀。
如何千里外，伫立霑裳衣。','',''),('quantangshi-42977','白紵辞 一','楊衡','quantangshi','','卷43','玉缨翠佩杂轻罗，香汗微渍朱颜酡，为君起唱白紵歌。
清声褭云思繁多，凝笳哀琴时相和。
金壶半倾芳夜促，梁尘霏霏暗红烛。
令君安坐听终曲，坠叶飘花难再复。','',''),('quantangshi-42978','白紵辞 二','楊衡','quantangshi','','卷43','蹑珠履，步琼筵。
轻身起舞红烛前，芳姿艳态妖且妍。
回眸转袖暗催弦，凉风萧萧漏水急。
月华泛溢红莲湿，牵裙揽带翻成泣。','',''),('quantangshi-42979','还渭南感旧二首 一','暄','quantangshi','','卷43','寝室悲长簟，妆楼泣镜台。
独悲桃李节，不共一时开。
魂兮若有感，仿髴梦中来。','',''),('quantangshi-42980','还渭南感旧二首 二','暄','quantangshi','','卷43','常时华室静，笑语度更筹。
恍惚人事改，冥漠委荒丘。
阳原叹薤露，阴壑悼藏舟。
清夜妆台月，空想画眉愁。','',''),('quantangshi-42981','赠亡妻张氏','暄','quantangshi','','卷43','峄阳桐半死，延津劒一沈。
如何宿昔内，空负百年心。','',''),('quantangshi-42982','题司空山观','李韶','quantangshi','','卷43','梁代真人上紫微，水盘山脚五云飞。
松杉老尽无消息，犹得千年一度归。','',''),('quantangshi-42983','戏题盱眙壁','韋鵬翼','quantangshi','','卷43','岂肯闲寻竹径行，却嫌丝管好蛙声。
自从煮鹤烧琴后，背却青山卧月明。','',''),('quantangshi-42984','题杨少卿书后','安鴻漸','quantangshi','','卷43','端溪石砚宣城管，王屋松烟紫兔毫。
更得孤卿老书札，人间无此五般高。','',''),('quantangshi-42985','自紫阳观至华阳洞宿侯尊师草堂简同游','李延陵','quantangshi','','卷43','石林媚烟景，句曲盘江甸。
南向佳气浓，峰峰遥隐见。
渐临华阳口，微路入葱蒨。
七曜悬洞宫，五云抱山殿。
银函意谁发，金液徒堪荐。
千载桃花春，秦人深不见。
东溪喜相遇，贞白如会面。
青鸟来去闲，红霞朝夕变。
一从化真骨，万里乘飞电。
萝月延步虚，松花醉闲宴。
幽人即长往，茂宰应交战。
明发归琴堂，知君嬾为县。','',''),('quantangshi-42986','题钟雅青纱枕','秦尚運','quantangshi','','卷43','阴香装艳入青纱，还与欹眠好事家。
梦里却成山色雨，沈山不敢鬬青华。','',''),('quantangshi-42987','题搔口','張仲謀','quantangshi','','卷43','尝闻烧尾便拏空，只过天门更一重。
大禹未生门未凿，可能天下总无龙。','',''),('quantangshi-42988','山寺见杨少卿书壁因题其尾','馮少吉','quantangshi','','卷43','少卿真迹满僧居，祗恐钟王也不如。
为报远公须爱惜，此书书后更无书。','',''),('quantangshi-42989','经杜甫旧宅','殷陶','quantangshi','','卷43','浣花溪里花多处，为忆先生在蜀时。
万古只应留旧宅，千金无复换新诗。
沙棚水槛鸥飞尽，树压村桥马过时。
山月不知人事变，夜来江上与谁期。','',''),('quantangshi-42990','行县至浮查寺','羅炯','quantangshi','','卷43','二十年前此布衣，鹿鸣西上虎符归。
行时宾从光前事，到处松杉长旧围。
野老竞遮官道拜，沙鸥遥避隼旟飞。
春风一宿琉璃地，自有泉声惬素机。','',''),('quantangshi-42991','敕和元相公家园即事寄王相公','韓雄','quantangshi','','卷43','共列中台贵，能齐物外心。
回车青阁晚，解带碧芳深。
夜水随畦入，晴花度竹寻。
题诗更相应，一字重千金。','',''),('quantangshi-42992','仲秋太常寺观公辂车拜陵','苗仲方','quantangshi','','卷43','南宫初开律，金风已戒凉。
拜陵将展敬，车辂俨成行。
士庶观祠礼，公卿习旧章。
郊原佳气引，园寝瑞烟长。
卤簿辞丹阙，威仪列太常。
圣心何所寄，惟德在无忘。','',''),('quantangshi-42993','寻易尊师不遇','陳嶰','quantangshi','','卷43','烂熳红霞光照衣，苔封白石路微微。
华阳洞里何人在，落尽松花不见归。','',''),('quantangshi-42994','早过棃岭喜雪书情呈崔判官','張起','quantangshi','','卷43','度岭逢朝雪，行看马迹深。
轻标南国瑞，寒慰北人心。
皎洁停丹嶂，飘颻映绿林。
共君歌乐土，无作白头吟。','',''),('quantangshi-42995','春情','張起','quantangshi','','卷43','画阁余寒在，新年旧燕归。
梅花犹带雪，未得试春衣。','',''),('quantangshi-42996','赠窦蔡二记室入蜀','陳政','quantangshi','','卷43','昆山积良宝，大厦构众材。
马卿委官去，邹子背淮来。
风流信多美，朝夕豫平台。
逸翮独不羣，清才复遒上。
六辅昔推名，二江今振响。
英华虽外发，磨琢终内朗。
四海奋羽仪，清风久播驰。
沈郁林难厕，青山翻易阻。
回首望烟霞，谁知慕俦侣。
飘然不系舟，为情自可求。
若奉西园夜，浩想北园愁。
无因逐萍藻，从尔泛清流。','',''),('quantangshi-42997','采菊','李建業','quantangshi','','卷43','簇簇竟相鲜，一枝开几番。
味甘资麴{艹/糪}，香好胜兰荪。
古道风摇远，荒篱露压繁。
盈筐时采得，服饵近知门。','',''),('quantangshi-42998','水精环','羅維','quantangshi','','卷43','王室符长庆，环中得水精。
任圆循不极，见素质仍贞。
信是天然瑞，非因朴斲成。
无瑕胜玉美，至洁过冰清。
未肯齐珉价，宁同杂佩声。
能衔任黄雀，亦欲应时明。','',''),('quantangshi-42999','看牡丹','殷益','quantangshi','','卷43','拥毳对芳丛，由来趣不同。
发从今日白，花是去年红。
艳色随朝露，馨香逐晚风。
何须待零落，然后始知空。','',''),('quantangshi-43000','赋得垣衣','李得','quantangshi','','卷43','漠漠复霏霏，为君垣上衣。
昭阳辇下草，应笑此生非。
掩蔼青春去，苍茫白露稀。
犹胜萍逐水，流浪不相依。','',''),('quantangshi-43001','冬晚对雪忆胡处士','王邵','quantangshi','','卷43','寒更传唱晚，清镜览衰颜。
隔牖风惊竹，开帘雪满山。
洒空深巷静，积素广庭闲。
借问袁安舍，翛然尚闭关。','',''),('quantangshi-43002','池上','曹脩古','quantangshi','','卷43','荷叶罩芙蓉，圆青映嫩红。
佳人南陌上，翠盖立春风。','',''),('quantangshi-43003','对赵颖歌','朱子真','quantangshi','','卷43','人间几日变桑田，谁识神仙洞里天。
短促虽知有殊异，且须欢醉在生前。','',''),('quantangshi-43004','赋百舌鸟','嚴郭','quantangshi','','卷43','此禽轻巧少同伦，我听长疑舌满身。
星未没河先报晓，柳犹粘雪便迎春。
频嫌海燕巢难定，却讶林莺语不真。
莫倚清风更多事，玉楼还有晏眠人。','',''),('quantangshi-43005','孤雁','張子明','quantangshi','','卷43','只影翩翩下碧湘，傍池鸳鹭宿银塘。
虽逢夜雨迷深浦，终向晴天着旧行。
忆伴几回思片月，蜕翎多为系繁霜。
江南塞北俱关念，两地飞归是故乡。','',''),('quantangshi-43006','水殿抛球曲二首 一','李謹言','quantangshi','','卷43','侍宴黄昏晓未休，玉阶夜色月如流。
朝来自觉承恩最，笑倩傍人认绣球。','',''),('quantangshi-43007','水殿抛球曲二首 二','李謹言','quantangshi','','卷43','堪恨隋家几帝王，舞裀揉尽绣鸳鸯。
如今重到抛球处，不是金炉旧日香。','',''),('quantangshi-43008','铜雀妓','吳燭','quantangshi','','卷43','秋色西陵满绿芜，繁弦急管强欢娱。
长舒罗袖不成舞，却向风前承泪珠。','',''),('quantangshi-43009','戏示诸妓','張保嗣','quantangshi','','卷43','绿罗裙上标三棒，红粉腮边泪两行。
抄手向前咨大使，这回不敢恼儿郎。','',''),('quantangshi-43010','末秋到家','潘圖','quantangshi','','卷43','归来无所利，骨肉亦不喜。
黄犬却有情，当门卧摇尾。','',''),('quantangshi-43011','送人往宣城','潘佐','quantangshi','','卷43','江畔送行人，千山生暮氛。
谢安团扇上，为画敬亭云。','',''),('quantangshi-43012','洛阳河亭奉酬留守郡公追送','李逸','quantangshi','','卷43','离亭饯落晖，腊酒减征衣。
岁晚烟霞重，川寒云树微。
戎装千里至，旧路十年归。
还似汀洲雁，相逢又背飞。','',''),('quantangshi-43013','送道士曾昭莹','沈麟','quantangshi','','卷43','南北东西事，人间会也无。
昔曾栖玉笥，今也返玄都。
雪片随天阔，泉声落石孤。
丹霄人有约，去采石菖蒲。','',''),('quantangshi-43014','赠别徐侃','安鳳','quantangshi','','卷43','一自离乡国，十年在咸秦。
泣尽卞和血，不逢一故人。
今日旧友别，羞此漂泊身。
离情吟诗处，麻衣掩泪频。
泪别各分袂，且及来年春。','',''),('quantangshi-43015','顾城','李倫','quantangshi','','卷43','世久荒墟在，白云几代耕。
市廛新草绿，里社故烟轻。
不谨罹天讨，来苏岂忿兵。
谁云殷鉴远，今古在人程。','',''),('quantangshi-43016','金钱花','盧子發','quantangshi','','卷43','轮廓休夸四字书，红窠写出对庭除。
时时买得佳人笑，本色金钱却不如。','',''),('quantangshi-43017','故白岩禅师院','王夢周','quantangshi','','卷43','能师还世名还在，空闭禅堂满院苔。
花树不随人寂寞，数株犹自出墙来。','',''),('quantangshi-43018','题九天使者庙','孫咸','quantangshi','','卷43','独入玄宫礼至真，焚香不为贱贫身。
秦淮两岸沙埋骨，湓浦千家血染尘。
庐阜烟霞谁是主，虎溪风月属何人。
九江太守勤王事，好放天兵渡要津。','',''),('quantangshi-43019','房公旧竹亭闻琴','李澣','quantangshi','','卷43','石室寒飙警，孙枝雅器裁。
坐来山水操，弦断吊尘埃。','',''),('quantangshi-43020','清溪馆作','錢戭','quantangshi','','卷43','指途清溪里，左右唯深林。
云蔽望乡处，雨愁为客心。
遇人多物役，听鸟时幽音。
何必沧浪水，庶兹浣尘襟。','',''),('quantangshi-43021','晚春宴','韋道遜','quantangshi','','卷43','日斜宾馆晚，春轻麦候初。
帘暄巢幕燕，池跃戏莲鱼。
石声随流响，桐影傍岩疎。
谁能千里外，独寄八行书。','',''),('quantangshi-43022','长沙六快诗','王揆','quantangshi','','卷43','湖外风物奇，长沙信难续。
衡峰排古青，湘水湛寒绿。
舟檝通大江，车轮会平陆。
昔贤官是邦，仁泽流丰沃。
今贤官是邦，刳啖人脂肉。
怀昔甘棠花，伤今猛虎毒。
然此一郡内，所乐人才六。
漕与二宪僚，守连两通属。
高堂日暮会，深夜继以烛。
帏幕皆绮纨，器皿尽金玉。
歌喉若珠累，舞腰如素束。
千态与万状，六人欢不足。
因成快活诗，荐之尧舜目。','',''),('quantangshi-43023','广州王园寺伏日即事寄北中亲友','王言史','quantangshi','','卷44','南越逢初伏，东林度一朝。
曲池煎畏景，高阁绝微飙。
竹簟移先洒，蒲葵破复摇。
地偏毛瘴近，山毒火威饶。
裛汗絺如濯，亲牀枕并烧。
堕枝伤翠羽，萎叶惜红蕉。
且困流金炽，难成独酌谣。
望霖窥润础，思吹候纤条。
旅恨生乌浒，乡心系浴桥。
谁怜在炎客，一夕壮容销。','',''),('quantangshi-43024','春日','雍','quantangshi','','卷44','轻花细叶满林端，昨夜春风晓色寒。
黄鸟不堪愁里听，绿杨宜向雨中看。','',''),('quantangshi-43025','失题','雍','quantangshi','','卷44','斜雨飞丝织晚风，疎帘半卷野亭空。
荷花开尽秋光晚，零落残红绿沼中。','',''),('quantangshi-43026','古意','戴休珽','quantangshi','','卷44','穷秋朔风起，沧海愁阴涨。
虏骑掠河南，汉兵屯灞上。
羽书惊沙漠，刁斗喧亭障。
关塞何苍茫，遥烽递相望。
弱龄负奇节，侠客多招访。
投笔弃繻生，提戈逐飞将。
拔劒照霜白，怒发冲冠壮。
会立万里功，视君封侯相。','',''),('quantangshi-43027','勖曹生','盧鉟','quantangshi','','卷44','桑扈交飞百舌忙，祖亭闻乐倍思乡。
尊前有恨惭卑宦，席上无憀爱艳妆。
莫为狂花迷眼界，须求真理定心王。
游蜂采掇何时已，祗恐多言议短长。','',''),('quantangshi-43028','琴歌','趙摶','quantangshi','','卷44','绿琴制自桐孙枝，十年窗下无人知。
清声不与众乐杂，所以屈受尘埃欺。
七弦脆断虫丝朽，辨别不曾逢好手。
琴声若似琵琶声，卖与时人应已久。
玉徽冷落无光彩，堪恨钟期不相待。
凤啭吟幽鹤舞时，拈弄铮摐声亦在。
向曾守贫贫不彻，贱价与人人不别。
前回忍泪却收来，泣向秋风两条血。
乃知凡俗难可名，轻者却重重者轻。
真龙不圣土龙圣，凤皇哑舌鸱枭鸣。
何殊此琴哀怨苦，寂寞沈埋在幽户。
万重山水不肯听，俗耳乐闻人打鼓。
知君立身待分义，驱喝风雷在平地。
一生从事不因人，健步窣云皆自致。
不辞重拂弦上尘，市廛不买多谗人。
莫辞憔悴与买取，为君一曲号青春。','',''),('quantangshi-43029','废长行','趙摶','quantangshi','','卷44','紫牙镂合方如斗，二十四星衔月口。
贵人迷此华筵中，运木手交如阵鬬。
不算劳神运枯木，且废为官恤惸独。
门前有吏吓孤穷，欲诉门深抱冤哭。
耳厌人催坐衙早，才闻此戏身先到。
理人似爱长行心，天下安平多草草。
何当化局为明镜，挂在高堂辨邪正。
何当化子作笔锋，常在手中行法令。
莫令终日迷如此，不治生民负天子。','',''),('quantangshi-43030','玉女词','張安石','quantangshi','','卷44','绮荐银屏空积尘，柳眉桃脸暗销春。
不须更学阳台女，为雨为云趁恼人。','',''),('quantangshi-43031','苦别','張安石','quantangshi','','卷44','向前不信别离苦，而今自到别离处。
两行粉泪红阑干，一朵芙蕖带残露。','',''),('quantangshi-43032','石城','蔣吉','quantangshi','','卷44','系缆石城下，恣吟怀暂开。
江人桡艇子，将谓莫愁来。','',''),('quantangshi-43033','汉东道中','蔣吉','quantangshi','','卷44','九十九冈遥，天寒雪未消。
羸童牵瘦马，不敢过危桥。','',''),('quantangshi-43034','高溪有怀','蔣吉','quantangshi','','卷44','驻马高溪侧，旅人千里情。
雁山山下水，还作此泉声。','',''),('quantangshi-43035','寄进士贾希','蔣吉','quantangshi','','卷44','恨苦泪不落，耿然东北心。
空囊与瘦马，羁绁意应深。','',''),('quantangshi-43036','出塞','蔣吉','quantangshi','','卷44','瘦马羸童行背秦，暮鸦撩乱入残云。
北风吹起寒营角，直至榆关人尽闻。','',''),('quantangshi-43037','旅泊','蔣吉','quantangshi','','卷44','霜月正高鹦鹉洲，美人清唱发红楼。
乡心暗逐秋江水，直到吴山脚下流。','',''),('quantangshi-43038','次青云驿','蔣吉','quantangshi','','卷44','马转栎林山鸟飞，商溪流水背残晖。
行人几在青云路，底事风尘犹满衣。','',''),('quantangshi-43039','大庾驿有怀','蔣吉','quantangshi','','卷44','一囊书重百余斤，邮吏宁知去计贫。
莫讶偏吟望乡句，明朝便见岭南人。','',''),('quantangshi-43040','题商山修路僧院','蔣吉','quantangshi','','卷44','此地修行山几枯，草堂生计只瓶盂。
支郎既解除艰险，试看人心平得无。','',''),('quantangshi-43041','题长安僧院','蔣吉','quantangshi','','卷44','出门争走九衢尘，总是浮生不了身。
惟有水田衣下客，大家忙处作闲人。','',''),('quantangshi-43042','次商于感旧寄卢中丞','蔣吉','quantangshi','','卷44','昔年簪组隘丘门，今日旌幢一院存。
何事商于泪如雨，小儒偏受陆家恩。','',''),('quantangshi-43043','樵翁','蔣吉','quantangshi','','卷44','独入深山信脚行，惯当貙虎不曾惊。
路傍花发无心看，惟见枯枝刮眼明。','',''),('quantangshi-43044','四老庙','蔣吉','quantangshi','','卷44','无端舍钓学干名，不得溪山养性情。
自省此身非达者，今朝羞拜四先生。','',''),('quantangshi-43045','昭君冢','蔣吉','quantangshi','','卷44','曾为汉帝眼中人，今作狂胡陌上尘。
身死不知多少载，冢花犹带洛阳春。','',''),('quantangshi-43046','闻歌竹枝','蔣吉','quantangshi','','卷44','巡堤听唱竹枝词，正是月高风静时。
独向东南人不会，弟兄俱在楚江湄。','',''),('quantangshi-43047','重门曲','周濆','quantangshi','','卷44','憔悴容华怯对春，寂寥宫殿锁闲门。
此身却羡宫中树，不失芳时雨露恩。','',''),('quantangshi-43048','山下水','周濆','quantangshi','','卷44','背云冲石出深山，浅碧泠泠一带寒。
不独有声流出此，会归沧海助波澜。','',''),('quantangshi-43049','逢邻女','周濆','quantangshi','','卷44','日高邻女笑相逢，慢束罗裙半露胸。
莫向秋池照绿水，参差羞杀白芙蓉。','',''),('quantangshi-43050','废宅','周濆','quantangshi','','卷44','牢落画堂空锁尘，荒凉庭树暗消春。
豪家莫笑此中事，曾见此中人笑人。','',''),('quantangshi-43051','奉和登会昌山应制','趙起','quantangshi','','卷44','睿想入希夷，真游到具茨。
玉鸾登嶂远，云辂出花迟。
泉壑凝神处，阳和布泽时。
六龙多顺动，四海正雍熙。','',''),('quantangshi-43052','冬日与羣公泛舟焦山 一','王瓚','quantangshi','','卷44','江外水不冻，今年寒复迟。
众芳且未歇，近腊仍裌衣。
载酒适我情，兴来趣渐微。
方舟大川上，环酌对落晖。
两片青石棱，波际无因依。
三山安可到，欲到风引归。
沧溟壮观多，心目豁暂时。
况得穷日夕，乘槎何所之。','',''),('quantangshi-43053','冬日与羣公泛舟焦山 二','王瓚','quantangshi','','卷44','纵步不知远，夕阳犹未回。
好花随处发，流水趂人来。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-43054','度揭鸿岭','慕容韋','quantangshi','','卷44','闽越曾为塞，将军旧置营。
我歌空感慨，西北望神京。','',''),('quantangshi-43055','湘江','黃文','quantangshi','','卷44','潇湘江头三月春，柳条弄日摇黄金。
鹧鸪一声在何许，黄陵庙前烟霭深。
丹青欲画无好手，稳提玉勒沈吟久。
马蹄不为行客留，心挂长林屡回首。','',''),('quantangshi-43056','题龙阳县青草湖','溫如','quantangshi','','卷44','西风吹老洞庭波，一夜湘君白发多。
醉后不知天在水，满船清梦压星河。','',''),('quantangshi-43057','訾家洲','歐陽賓','quantangshi','','卷44','旧业分明桂水头，人归业尽水东流。
春风日暮江头立，不及渔人有钓舟。','',''),('quantangshi-43058','题吉州龙溪','何敬','quantangshi','','卷44','龙溪之山秀而峙，龙溪之水清无底。
狂风激烈翻春涛，薄雾冥蒙溢清泚。
奔流百折银河通，落花滚滚浮霞红。
四时佳境不可穷，彷佛直与桃源通。','',''),('quantangshi-43059','过睦州青溪渡','楊彝','quantangshi','','卷44','天阔衔江雨，冥冥上客衣。
潭清鱼可数，沙晚雁争飞。
川谷留云气，鹈鹕傍钓矶。
瓢零江海客，欹侧一帆归。','',''),('quantangshi-43060','阖闾城怀古','裴瑤','quantangshi','','卷44','五湖春水接遥天，国破君亡不记年。
惟有妖娥曾舞处，古台寂寞起愁烟。','',''),('quantangshi-43061','苇谷','鄭玉','quantangshi','','卷44','水会三川漾碧波，雕阴人唱采花歌。
旧时白翟今荒壤，苇谷凄凄风雨多。','',''),('quantangshi-43062','登岳阳楼','麻溫其','quantangshi','','卷44','湖边景物属秋天，楼上风光似去年。
仙侣缑生留福地，湘娥帝子寄哀弦。
云门自统轩台外，木叶偏飞楚客前。
极目江山何处是，一帆万里信归船。','',''),('quantangshi-43063','经望湖驿','韋鎰','quantangshi','','卷44','大漠无屯云，孤峰出乱柳。
前驱白登道，顾失飞狐口。
遥忆代王城，俯临恒山后。
累累多古墓，寂寞为墟久。
岂不固金汤，终闻击铜斗。
交懽初仗信，接宴翻贻咎。
埋宝贼夫人，磨笄伤彼妇。
功成行且薄，义立名不朽。
莫慎纤微端，其何社稷守。
身殁国遂亡，此立人君丑。','',''),('quantangshi-43064','杪秋洞庭怀王道士','謝太虛','quantangshi','','卷44','漂泊日复日，洞庭今更秋。
青桃亦何意，此夜催人愁。
惆怅客中月，裴回江上楼。
心知楚天远，目送沧波流。
谢客久已灭，微言无处求。
空余白云在，客兴随孤舟。
千里杳难尽，一身常独游。
故园复何许，江汉徒迟留。','',''),('quantangshi-43065','君山祠','周岳秀','quantangshi','','卷44','万顷湖波浸碧天，旌封香火几千年。
风涛澎湃鱼龙舞，栋宇峥嵘燕雀迁。
远岫光中浓淡树，斜阳影里往来船。
江河愿借吹嘘便，应有神功在目前。','',''),('quantangshi-43066','新乐府','馬逢','quantangshi','','卷44','温谷春生至，宸游近甸荣。
云随天上转，风入御筵轻。
翠盖浮佳气，朱楼依太清。
朝臣冠劒退，宫女管弦迎。','',''),('quantangshi-43067','部落曲','馬逢','quantangshi','','卷44','蕃军傍塞游，代马喷风秋。
老将垂金甲，阏支着锦裘。
雕戈蒙豹尾，红斾插狼头。
日暮天山下，鸣笳汉使愁。','',''),('quantangshi-43068','从军','馬逢','quantangshi','','卷44','汉马千蹄合一羣，单于鼓角隔山闻。
沙塠风起红楼下，飞上胡天作阵云。','',''),('quantangshi-43069','宫词二首 一','馬逢','quantangshi','','卷44','金吾持戟护轩檐，天乐传教万姓瞻。
楼上美人相倚看，红妆透出水晶帘。','',''),('quantangshi-43070','宫词二首 二','馬逢','quantangshi','','卷44','玉楼天半起笙歌，风送宫人笑语和。
月影殿开闻晓漏，水晶帘卷近秋河。','',''),('quantangshi-43071','长门失宠','蕭意','quantangshi','','卷44','自从别銮殿，长门几度春。
不知金屋里，更贮若为人。','',''),('quantangshi-43072','下山逢故夫','徐之才','quantangshi','','卷44','踟蹰下山妇，共申别离久。
为问织缣人，何必长相守。','',''),('quantangshi-43073','虏患','張陵','quantangshi','','卷44','今日汉家探使回，蚁叠胡兵来未歇。
春风渭水不敢流，总作六军心上血。','',''),('quantangshi-43074','夏日闺怨','蔡瓌','quantangshi','','卷44','桃径李蹊绝芳园，炎氛炽日满愁轩。
枝上鸟惊朱槿落，池中鱼戏绿苹翻。
君恋京师久留滞，妾怨高楼积年岁。
非关曾入楚王宫，直为相思腰转细。
卧簟乘闲乍逐凉，熏炉畏热嬾焚香。
雨霑柳叶如啼眼，露滴莲花似汗妆。
全由独自羞看影，艳是孤眠疑夜永。
无情拂镜不成妆，有时却扇还风静。
近日书来道欲归，鸳鸯文锦字息机。
但恐愁容不相识，为教恒着别时衣。','',''),('quantangshi-43075','咏破扇','怡','quantangshi','','卷44','轮如明月尽，罗似薄云穿。
无由重掩笑，分在秋风前。','',''),('quantangshi-43076','述怀','怡','quantangshi','','卷44','万事皆零落，平生不可思。
惟余酒中趣，不减少年时。','',''),('quantangshi-43077','咏烛寄人','潘求仁','quantangshi','','卷44','烛与人相似，通宵遽白煎。
不应须下泪，祗是为人然。','',''),('quantangshi-43078','薛王花烛行','閻德隱','quantangshi','','卷44','王子仙车下凤台，紫缨金勒驭龙媒。
□□□□□□出，环佩锵锵天上来。
鳷鹊楼前云半卷，鸳鸯殿上月裴回。
玉盘错落银灯照，珠帐𤫩珑宝扇开。
盈盈二八谁家子，红粉新妆胜桃李。
从来六行比齐姜，自许千门奉楚王。
楚王宫里能服饰，顾盼倾城复倾国。
合欢锦带蒲萄花，连理香裙石榴色。
金炉半夜起氛氲，翡翠被重苏合熏。
不学曹王遇神女，莫言罗敷邀使君。
同心婉娩若琴瑟，更笑天河有灵匹。
一朝福履盛王门，百代光辉增帝室。
富贵荣华实可怜，路傍观者谓神仙。
祗应早得淮南术，会见双飞入紫烟。','',''),('quantangshi-43079','三月歌','閻德隱','quantangshi','','卷44','洛阳城路九春衢，洛阳城外柳千株。
能得来时作眼觅，天津桥侧锦屠苏。','',''),('quantangshi-43080','妾薄命','劉元叔','quantangshi','','卷44','自从离别守空闺，遥闻征战赴云梯。
夜夜思君辽海北，年年弃妾渭桥西。
阳春白日照空暖，紫燕衔花向庭满。
彩鸾琴里怨声多，飞鹊镜前妆梳断。
谁家夫壻不从征，应是渔阳别有情。
莫道红颜燕地少，家家还似洛阳城。
旦逐新人殊未归，还令秋至夜霜飞。
北斗星前横旅雁，南楼月下捣寒衣。
夜深闻雁肠欲绝，独坐缝衣灯又灭。
暗啼罗帐空自怜，梦度阳关向谁说。
每怜容貌宛如神，如何薄命不如人。
待君朝夕燕山至，好作明年杨柳春。','',''),('quantangshi-43081','古别离','常理','quantangshi','','卷44','君御狐白裘，妾居缃绮帱。
粟钿金夹膝，花错玉搔头。
离别生庭草，征衣断戍楼。
蟏蛸网清曙，菡萏落红秋。
小胆空房怯，长眉满镜愁。
为传儿女意，不用远封侯。','',''),('quantangshi-43082','妾薄命','常理','quantangshi','','卷44','十五玉童色，双蛾青弯弯。
鸟衔樱桃花，此时刺绣闲。
娇小恣所爱，误人金指环。
艳花句引落，灭烛屏风关。
妾怕愁中画，君偷薄里还。
初谓来心平若案，谁知别意险如山。
乍啼罗袖娇遮面，不忍看君莫惜颜。','',''),('quantangshi-43083','虞姬怨','馮待徵','quantangshi','','卷44','妾本江南采莲女，君是江东学劒人。
逢君游侠英雄日，值妾年华桃李春。
年华灼灼艳桃李，结发簪花配君子。
行逢楚汉正相持，辞家上马从君起。
岁岁年年事征战，侍君帷幕损红颜。
不惜罗衣沾马汗，不辞红粉着刀环。
相期相许定关中，鸣銮鸣佩入秦宫。
谁误四面楚歌起，果知五星汉道雄。
天时人事有兴灭，智穷计屈心摧折。
泽中马力先战疲，帐下蛾眉□□□。
君王是日无神彩，贱妾此时容貌改。
拔山意气都已无，渡江面目今何在。
终天隔地与君辞，恨似流波无息时。
使妾本来不相识，岂见中途怀苦悲。','',''),('quantangshi-43084','越溪怨','冷朝光','quantangshi','','卷44','越王宫里如花人，越水溪头采白苹。
白苹未尽人先尽，谁见江南春复春。','',''),('quantangshi-43085','吴宫怨','衛萬','quantangshi','','卷44','君不见吴王宫阁临江起，不见珠帘见江水。
晓气晴来双阙间，潮声夜落千门里。
句践城中非旧春，姑苏台下起黄尘。
祗今唯有西江月，曾照吴王宫里人。','',''),('quantangshi-43086','春游吟','李章','quantangshi','','卷44','初春徧芳甸，十里蔼盈瞩。
美人摘新英，步步翫春绿。
所思杳何处，宛在吴江曲。
可怜不得共芳菲，日暮归来泪满衣。','',''),('quantangshi-43087','婕妤怨','王沈','quantangshi','','卷44','长信梨花暗欲栖，应门上钥草萋萋。
春风吹花乱扑户，[班]绝车声不至啼。','',''),('quantangshi-43088','夜夜曲','王偃','quantangshi','','卷44','北斗星移银汉低，班姬愁思凤城西。
青槐陌上行人绝，明月楼前乌夜啼。','',''),('quantangshi-43089','明君词','王偃','quantangshi','','卷44','北望单于日半斜，明君马上泣胡沙。
一双泪滴黄河水，应得东流入汉家。','',''),('quantangshi-43090','拟古东飞伯劳歌','李暇','quantangshi','','卷44','秦王龙劒燕后琴，珊瑚宝匣镂双心。
谁家女儿抱香枕，开衾灭烛愿侍寝。
琼窗半上金镂帱，轻罗掩面不遮羞。
青绮帏中坐相忆，红鸾镜里见愁色。
檐花照月莺对栖，空将可怜暗中啼。','',''),('quantangshi-43091','怨诗三首 一','李暇','quantangshi','','卷44','罗敷初总髻，蕙芳正娇小。
月落始归船，春眠恒着晓。','',''),('quantangshi-43092','怨诗三首 二','李暇','quantangshi','','卷44','何处期郎游，小苑花台间。
相忆不可见，且复乘月还。','',''),('quantangshi-43093','怨诗三首 三','李暇','quantangshi','','卷44','别前花照路，别后露垂叶。
歌舞须及时，如何坐悲妾。','',''),('quantangshi-43094','碧玉歌','李暇','quantangshi','','卷44','碧玉上官妓，出入千花林。
