思君如满月，夜夜减容辉。','',''),('quantangshi-43098','又自君之出矣','辛弘智','quantangshi','','卷44','自君之出矣，宝镜为谁明。
思君如陇水，常闻呜咽声。','',''),('quantangshi-43099','题春梦秋归故里','吉師老','quantangshi','','卷44','故国归路赊，春晚在天涯。
