不羡一囊钱，唯重心襟会。','',''),('quantangshi-43166','塞下曲','楊達','quantangshi','','卷44','秋日并州路，黄榆落故关。
孤城吹角罢，数骑射雕还。
帐幕遥临水，牛羊自下山。
行人正垂泪，烽火起云间。','',''),('quantangshi-43167','明妃怨','楊達','quantangshi','','卷44','汉国明妃去不还，马驼弦管向阴山。
匣中纵有菱花镜，羞对单于照旧颜。','',''),('quantangshi-43168','送邹尊师归洞庭','楊逵','quantangshi','','卷44','众岛在波心，曾居旧隐林。
近闻飞檄急，转忆卧云深。
卖药唯供酒，归舟只载琴。
遥知明月夜，坐石自开襟。','',''),('quantangshi-43169','送张兵曹赴营田','魏兼恕','quantangshi','','卷44','河曲今无战，王师每务农。
选才当重委，足食乃深功。
草色孤城外，云阴绝漠中。
萧关休叹别，归望在乘騘。','',''),('quantangshi-43170','晚霁登汝南大云阁','賈彥璋','quantangshi','','卷44','禅宫新歇雨，香阁晚登临。
邑树晴光起，川苗佳气深。
水包城下岸，云细郢中岑。
自叹牵卑日，聊开望远心。','',''),('quantangshi-43171','宿香山阁','賈彥璋','quantangshi','','卷44','暝望香山阁，梯云宿半空。
轩窗闭潮海，枕席拂烟虹。
朱网防栖鸽，纱灯护夕虫。
一闻鸡唱晓，已见日曈曈。','',''),('quantangshi-43172','苏着作山池','賈彥璋','quantangshi','','卷44','水树子云家，峯瀛宛不赊。
芥浮舟是叶，莲发岫为花。
酌蚁开春瓮，观鱼凭海查。
游苏多石友，题赠满瑶华。','',''),('quantangshi-43173','王龙骧墓','賈彥璋','quantangshi','','卷44','昔擅登坛宠，爰光典午朝。
刀悬临益梦，龙启渡江谣。
茂绩当年举，英魂此地销。
唯余孤壠上，日夕起松飙。','',''),('quantangshi-43174','折杨柳','歐陽瑾','quantangshi','','卷44','垂柳拂妆台，葳蕤叶半开。
年华枝上见，边思曲中来。
嫩色宜新雨，轻花伴落梅。
朝朝倦攀折，征戍几时回。','',''),('quantangshi-43175','江南曲','李叔卿','quantangshi','','卷44','湖上女，江南花，无双越女春浣纱。
风似箭，月如弦，少年吴儿晓进船。
郗家子弟谢家郎，乌巾白袷紫香囊。
菱歌思欲绝，楚舞断人肠。
歌舞未终涕双陨，旧宫坡陁才嶙隐。
西山暮雨过江来，北渚春云沿海尽。
渡口水流缓，妾归宵剩迟。
含情为君再理曲，月华照出澄江时。','',''),('quantangshi-43176','芳树','李叔卿','quantangshi','','卷44','春看玫瑰树，西邻即宋家。
门深重暗叶，墙近度飞花。
影拂桃阴浅，香传李迳斜。
靓妆愁日暮，流涕向窗纱。','',''),('quantangshi-43177','送杨谏议赴河西节度判官兼呈韩王二侍御','熊曜','quantangshi','','卷44','贤哉征西将，幕府多俊人。
筹议秉刀尺，话言在经纶。
先鞭羡之子，走马辞咸秦。
庭论许名实，数公当即真。
行行弄文翰，婉婉光使臣。
今者所从谁，不闻歌苦辛。
黄云萧关道，白日惊沙尘。
虏寇有时猎，汉兵行复巡。
王师已无战，传檄奉良臣。','',''),('quantangshi-43178','登巴陵开元寺西阁赠衡岳僧方外','李賓','quantangshi','','卷44','衡岳有开士，五峰秀贞骨。
见君万里心，海水照秋月。
大臣南溟去，问道皆请谒。
洒以甘露言，清凉润肌发。
湖海落天镜，香阁凌银阙。
登眺餐惠风，心花期启发。','',''),('quantangshi-43179','登瓦官寺阁','李賓','quantangshi','','卷44','晨登瓦官阁，极眺金陵城。
钟山对北户，淮水入南荣。
漫漫雨花落，嘈嘈天乐鸣。
两廊振法鼓，四角吹风筝。
杳无霄汉上，仰攀日月行。
山空霸气灭，地古寒阴生。
寥廓云海晚，苍茫宫观平。
门余阊阖字，楼识凤凰名。
雷作百川动，神扶万栱倾。
灵光一向贵，长此镇吴京。','',''),('quantangshi-43180','金陵怀古','堯臣','quantangshi','','卷44','晋末英雄起，神器沦荒服。
胡月蚀中原，白日升阳谷。
金陵实形胜，关山固重复。
巨壑隍北壖，长江堑西隩。
凿山拟嵩华，穿地象伊谷。
草昧席罗图，荜路戴黄屋。
一时因地险，五世享天禄。
礼乐何煌煌，文章纷郁郁。
多士春林秀，作颂清风穆。
出入三百年，朝事几翻覆。
搀抢如云勃，鲸鲵旋自曝。
倦闻金鼎移，骤覩灵龟卜。
吁嗟王气尽，坐悲天运倏。
天道何茫茫，善淫乃相复。
行路偏衣半，遂亡大梁族。
日隐汀洲上，登舻𦪇川陆。
月回吴山树，风闻楚江鹄。
因依兰蕙藂，采撷不盈掬。','',''),('quantangshi-43181','咏浮沤为辛明府作','鄭縉','quantangshi','','卷44','行潦散轻沤，清规吐未收。
雨来波际合，风起浪中浮。
晶晃明苔砌，参差绕芥舟。
影疑星泛晓，光似露涵秋。
皎皎珠同净，漂漂梗共流。
洁容无变染，圆知有谦柔。
欲作微涓效，先从淡水游。','',''),('quantangshi-43182','莺','鄭縉','quantangshi','','卷44','欲啭声犹涩，将飞羽未调。
高风不借便，何处得迁乔。','',''),('quantangshi-43183','鹦鹉','吳英秀','quantangshi','','卷44','莫把金笼闭鹦鹉，个个聪明解人语。
忽然更向君前言，三十六宫愁几许。','',''),('quantangshi-43184','马','陳凝','quantangshi','','卷44','未明龙骨骏，幸得到神州。
自有千金价，宁忘伯乐酬。
虽知殊欵段，莫敢比骅骝。
若遇追风便，当轩一举头。','',''),('quantangshi-43185','凤','伊夢昌','quantangshi','','卷44','好是山家凤，歌成非楚鸡。
毫光洒风雨，纹彩动云霓。
竹实不得饱，桐孙何足栖。
岐阳今好去，律吕正凄凄。','',''),('quantangshi-43186','送韦员外赴朔方','鄭嚴','quantangshi','','卷44','白露边秋早，皇华戎事催。
已推仙省妙，更是幕中才。
出饯倾朝列，深功伫帝台。
坐闻长策利，终见勒铭回。','',''),('quantangshi-43187','险竿行','柳曾','quantangshi','','卷44','山险惊摧輈，水险能覆舟。
奈何平地不肯立，走上百尺高竿头。
我不知尔是人耶复猱耶？
使我为尔长叹嗟。
我闻孝子不许国，忠臣不爱家。
尔今轻命重黄金，忠孝两亏徒尔夸。
始以险技悦君目，终以贪心媚君禄。
百尺高竿百度缘，一足参差一家哭。
险竿儿，听我语，更有险徒险于汝。
重于权者失君恩，落向天涯海边去。
险竿儿，尔须知，险途欲往尔可思。
上得不下下不得，我谓此辈险于险竿儿。','',''),('quantangshi-43188','琵琶行','牛殳','quantangshi','','卷44','何人斸得一片木，三尺春冰五音足。
一弹决破真珠囊，迸落金盘声断续。
飘飘颻颻寒丁丁，虫豸出蛰神鬼惊。
秋鸿叫侣代云黑，猩猩夜啼蛮月明。
潏潏汩汩声不定，胡雏学汉语未正。
若似长安月蚀时，满城敲鼓声噒噒。
青山飞起不压物，野水流来欲湿人。
伤人忆得陈后主，春殿半酣细腰舞。
黄莺百舌正相呼，玉树后庭花带雨。
二妃哭处山重重，二妃没后云溶溶。
夜深霜露锁空庙，零落一丛斑竹风。
金谷园中草初绿，石崇一弄思归曲。
当时二十四友人，手把金杯听不足。
又似贾客蜀道间，千铎万磬鸣空山。
未若此调呦呦兮啁啁，嘈嘈兮啾啾。
引之于山，兽不能走。
吹之于水，鱼不能游。
方知此艺不可有，人间万事凭双手。
若何为我再三弹，送却花前一尊酒。','',''),('quantangshi-43189','方响歌','牛殳','quantangshi','','卷44','乐中何乐偏堪赏，无过夜深听方响。
缓击急击曲未终，暴雨飘飘生坐上。
铿铿铛铛寒重重，盘涡蹙派鸣蛟龙。
高楼漏滴金壶水，碎电打着山寺钟。
又似公卿入朝去，环佩鸣玉长街路。
忽然碎打入破声，石崇推倒珊瑚树。
长短参差十六片，敲击宫商无不遍。
此乐不教外人闻，寻常只向堂前宴。','',''),('quantangshi-43190','经太华','衛光一','quantangshi','','卷44','太华五千寻，重岩合沓起。
势飞白云外，影倒黄河里。
上有千莲叶，服之久不死。
山高采难得，叹息徒仰止。','',''),('quantangshi-43191','季夏入北山','林璠','quantangshi','','卷44','整驾俟明发，逶迤历险途。
天形逼峰尽，地势入溪无。
树绕圆潭密，云横叠障孤。
谁怜后时者，六月未南图。','',''),('quantangshi-43192','适思','顏胄','quantangshi','','卷44','芳岁不我与，飒然凉风生。
繁华扫地歇，蟋蟀充堂鸣。
感物增忧思，奋衣出游行。
行值古墓林，白骨下纵横。
田竖鞭髑髅，村童扫精灵。
精灵无奈何，像设安所荣。
石人徒瞑目，表柱烧无声。
试读碑上文，乃是昔时英。
位极君诏葬，勋高盈忠贞。
宠终禁樵采，立嗣修坟茔。
运否前政缺，羣盗多蚊䖟。
即此丘壠坏，铁心为霑缨。
当其崇树日，岂意侵夺并。
冥漠生变故，凄凉结幽明。
悲端岂自我，外物纷相萦。
所适非所见，前登江上城。
倚楼临绿水，一望解伤情。','',''),('quantangshi-43193','古意','邢象玉','quantangshi','','卷44','家中酒新熟，园里叶初荣。
伫杯欲取醉，悒然思友生。
忽闻有奇客，何姓复何名。
嗜酒陶彭泽，能琴阮步兵。
何须问寒暑，径共坐山亭。
举袂祛啼鸟，扬巾扫落英。
心神无俗累，歌咏有新声。
新声是何曲，沧浪之水清。','',''),('quantangshi-43194','采莲曲','張敬徽','quantangshi','','卷44','游女泛江晴，莲红水复清。
竞多愁日暮，争疾畏船倾。
波动疑钗落，风生觉袖轻。
相看未尽意，归浦棹歌声。','',''),('quantangshi-43195','采莲','徐玄之','quantangshi','','卷44','越艳荆姝惯采莲，兰桡画檝满长川。
秋来江水澄如练，映水红妆如可见。
此时莲浦珠翠光，此日荷风罗绮香。
纤手周游不暂息，红英烂熳殊未极。
夕鸟栖林人欲稀，长歌哀怨采莲归。','',''),('quantangshi-43196','同崔员外温泉宫即事','郭汭','quantangshi','','卷44','辇辂移双阙，宸游整六师。
天回紫微座，日转羽林旗。
雷气寒戈戟，军容壮武貔。
弓鸣射雁处，泉暖跃龙时。
惠化成观俗，讴谣入赋诗。
同欢王道盛，相与咏雍熙。','',''),('quantangshi-43197','题沈黎城','權徹','quantangshi','','卷44','苏子卧北海，马翁渡南洲。
迹恨事乃立，功达名遂休。
夜闻羽书至，召募此边州。
铁骑耀楚甲，玉匣横吴钩。
雪厚羣山冻，蓬飞荒塞秋。
久戍曷辞苦，数战期封侯。
不学竖儒辈，谈经空白头。','',''),('quantangshi-43198','登乐游原怀古','豆盧回','quantangshi','','卷44','缅惟汉宣帝，初谓皇曾孙。
虽在襁褓中，亦遭巫蛊冤。
至哉丙廷尉，感激义弥敦。
驰逐莲勺道，出入诸陵门。
一朝风云会，竟登天位尊。
握符升宝历，负扆御华轩。
赫奕文物备，葳蕤休瑞繁。
卒为中兴主，垂名于后昆。
雄图奄已谢，余址空复存。
昔为乐游苑，今为狐兔园。
朝见牧竖集，夕闻栖鸟喧。
萧条灞亭岸，寂寞杜陵原。
羃䍥野烟起，苍茫岚气昏。
二曜屡回薄，四时更凉温。
天道尚如此，人理安可论。','',''),('quantangshi-43199','静女歌','張南容','quantangshi','','卷44','静女乐于静，动合古人则。
妙年工诗书，弱岁勤组织。
端居愁若痴，谁复理容色。
十五坐幽闺，四邻不相识。
夭夭邻家子，百花装首餙。
日月淇上游，笑人不逾阈。
河水自浊济自清，仙台蛾眉秦镜明。
为照齐王门下丑，何如汉帝掌中轻。','',''),('quantangshi-43200','古兴二首 一','沈徽','quantangshi','','卷44','蔓草自细微，女萝始夭夭。
夤缘至百尺，荣耀非一朝。
敷色高碧岭，流芳薄丹霄。
如何摧秀木，正为余波漂。
茎叶落岩迹，英蕤从风飙。
洪柯不足恃，况乃托陵苕。','',''),('quantangshi-43201','古兴二首 二','沈徽','quantangshi','','卷44','长安富豪右，信是天下枢。
戚里笙歌发，禁门冠盖趋。
攀云无丑士，唾地尽成珠。
日晏下双阙，烟花乱九衢。
恩荣在片言，零落亦须臾。
何意还自及，曲池今已芜。','',''),('quantangshi-43202','晚望','林琨','quantangshi','','卷44','清晨孤亭里，极目对前岑。
远与天水合，长霞生夕林。
苍然平楚意，杳霭半秋阴。
落日川上尽，关城云外深。
方予事岩壑，及此欲抽簪。
诗就蓬山道，还兹契宿心。','',''),('quantangshi-43203','阳春歌','吳象之','quantangshi','','卷44','帘低晓露湿，帘卷莺声急。
欲起把箜篌，如凝彩弦涩。
孤眠愁不转，点泪声相及。
净扫阶上花，风来更吹入。','',''),('quantangshi-43204','少年行','吳象之','quantangshi','','卷44','承恩借猎小平津，使气常游中贵人。
一掷千金浑是胆，家无四壁不知贫。','',''),('quantangshi-43205','晚至乡亭','鄭德玄','quantangshi','','卷44','长亭日已暮，驻马暂盘桓。
山川杳不极，徒侣默相看。
云夕荆台暗，风秋郢路寒。
客心一如此，谁复采芳兰。','',''),('quantangshi-43206','舟行旦发','張軫','quantangshi','','卷44','夜帆时未发，同侣暗相催。
山晓月初下，江鸣潮欲来。
稍分扬子岸，不辨越王台。
自客水乡里，舟行知几回。','',''),('quantangshi-43207','奉和夏日游山应制','蔡文恭','quantangshi','','卷44','首夏林壑清，薄暮烟霞上。
连岩耸百仞，绝壑临千丈。
照灼晚花鲜，潺湲夕流声。
悠然动睿思，息驾寻真赏。
掞彼涡川作，怀兹洛滨想。
窃吹等齐竽，何用承恩奖。','',''),('quantangshi-43208','旅泊江津言怀','賈宗','quantangshi','','卷44','征途几迢遰，客子倦西东。
乘流如泛梗，逐吹似惊蓬。
飘颻万里外，辛苦百年中。
异县心期阻，他乡风月同。
云归全岭暗，日落半江红。
自然堪迸泪，非是泣途穷。','',''),('quantangshi-43209','大梁行','堯客','quantangshi','','卷44','客有成都来，为我弹鸣琴。
前弹别鹤操，后奏大梁吟。
大梁伤客情，荒台对古城。
版筑有陈迹，歌吹舞遗声。
雄哉魏公子，畴日好罗英。
秀士三千人，煌煌列众星。
金槌夺晋鄙，白刃刎侯嬴。
邯郸救赵北，函谷走秦兵。
君子荣且昧，忠信莫之明。
间谍忽来及，雄图靡克成。
千龄万化尽，但见汴水清。
旧国多孤垒，夷门荆棘生。
苍梧彩云没，湘浦绿池平。
闻有东山去，萧萧班马鸣。
河洲搴宿莽，日夕泪霑缨。
因之唁公子，慷慨此歌行。','',''),('quantangshi-43210','秋日送别','朱晦','quantangshi','','卷44','荒郊古陌时时断，野水浮云处处秋。
唯有河边衰柳树，蝉声相送到扬州。','',''),('quantangshi-43211','送人归山','石召','quantangshi','','卷44','相逢唯道在，谁不共知贫。
归路分残雨，停舟别故人。
霜明松岭晓，花暗竹房春。
亦有栖闲意，何年可寄身。','',''),('quantangshi-43212','早行遇雪','石召','quantangshi','','卷44','荒郊昨夜雪，羸马又须行。
四顾无人迹，鸡鸣第一声。','',''),('quantangshi-43213','送安养阎主簿还竹寺','林珝','quantangshi','','卷44','分手怨河梁，南征历汉阳。
江山追宋玉，云雨梦襄王。
醉里宜城近，歌中郢路长。
更寻栖枳处，犹是念仇香。','',''),('quantangshi-43214','晚投南村','衛葉','quantangshi','','卷44','客行逢日暮，原野散秋晖。
南陌人初断，西林鸟尽归。
暗蓬沙上转，寒叶月中飞。
村落无多在，声声近捣衣。','',''),('quantangshi-43215','题季子庙','李季華','quantangshi','','卷44','季子让社稷，又能听国风。
宁知千载后，苹藻冷祠宫。','',''),('quantangshi-43216','听琴','王玄','quantangshi','','卷44','拂尘开按匣，何事独颦眉。
古调俗不乐，正声君自知。','',''),('quantangshi-43217','失鹭鹚','李歸唐','quantangshi','','卷44','惜养来来岁月深，笼开不见意沈吟。
也知祗在秋江上，明月芦花何处寻。','',''),('quantangshi-43218','铜雀妓','朱光弼','quantangshi','','卷44','魏王铜雀妓，日暮管弦清。
一见西陵树，心悲舞不成。','',''),('quantangshi-43219','宫词','朱光弼','quantangshi','','卷44','梦里君王近，宫中河汉高。
秋风能再热，团扇不辞劳。','',''),('quantangshi-43220','惆怅诗九首 一','顧甄遠','quantangshi','','卷44','魂黯黯兮情脉脉，帘风清兮窗月白。
梦惊枕上炉烬销，不见蘂珠宫里客。','',''),('quantangshi-43221','惆怅诗九首 二','顧甄遠','quantangshi','','卷44','禁漏声稀蟾魂冷，纱厨筠簟波光净。
独坐愁吟暗断魂，满窗风动芭蕉影。','',''),('quantangshi-43222','惆怅诗九首 三','顧甄遠','quantangshi','','卷44','别恨离肠空恻恻，风动虚轩池水白。
莫言灵圃步难寻，有心终效偷桃客。','',''),('quantangshi-43223','惆怅诗九首 四','顧甄遠','quantangshi','','卷44','秋遇人间好风景，焦桐韵满华堂静。
鉴鸾钗燕恨何穷，忍向银牀空抱影。','',''),('quantangshi-43224','惆怅诗九首 五','顧甄遠','quantangshi','','卷44','绿槐影里傍青楼，陌上行人空举头。
烟水露花无处问，摇鞭凝睇不胜愁。','',''),('quantangshi-43225','惆怅诗九首 六','顧甄遠','quantangshi','','卷44','役尽心神销尽骨，恩情未断忽分离。
平生此恨无言处，只有衣襟泪得知。','',''),('quantangshi-43226','惆怅诗九首 七','顧甄遠','quantangshi','','卷44','浓醪艳唱愁难破，骨瘦魂消病已成。
若为多罗年少死，始甘人道有风情。','',''),('quantangshi-43227','惆怅诗九首 八','顧甄遠','quantangshi','','卷44','泪满罗衣酒满巵，一声歌断怨伤离。
如今两地心中事，直是瞿昙也不知。','',''),('quantangshi-43228','惆怅诗九首 九','顧甄遠','quantangshi','','卷44','横泥杯觞醉复醒，愁牵时有小诗成。
早知惹得千般恨，悔不天生解薄情。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-43229','登清居台','魏巒','quantangshi','','卷44','迤逦清居台，连延白云外。
侧聆天上语，下视飞鸟背。','',''),('quantangshi-43230','游昌化精舍','柳明獻','quantangshi','','卷44','宝台侵汉远，金地接霞高。
何必游天外，忻此契卢敖。','',''),('quantangshi-43231','善卷先生坛','蔡崑','quantangshi','','卷44','几到坛边登阁望，因思遗迹咏今朝。
当时为有重华出，不是先生傲帝尧。','',''),('quantangshi-43232','句','蔡崑','quantangshi','','卷44','飘飘随暮雨，飒飒落秋山。','',''),('quantangshi-43233','题鄜州相思铺','令狐挺','quantangshi','','卷44','谁把相思号此河，塞垣车马往来多。
只应自古征人泪，洒向空川作逝波。','',''),('quantangshi-43234','凤归云二首 一','滕潛','quantangshi','','卷44','金井栏边见羽仪，梧桐枝上宿寒枝。
五陵公子怜文彩，画与佳人刺绣衣。','',''),('quantangshi-43235','凤归云二首 二','滕潛','quantangshi','','卷44','饮啄蓬山最上头，和烟飞下禁城秋。
曾将弄玉归云去，金翿斜开十二楼。','',''),('quantangshi-43236','药圃','夏侯子雲','quantangshi','','卷44','绿叶红英遍，仙经自讨论。
偶移岩畔菊，锄断白云根。','',''),('quantangshi-43237','读孝经','方愚','quantangshi','','卷44','星彩满天朝北极，源流是处赴东溟。
为臣为子不忠孝，辜负宣尼一卷经。','',''),('quantangshi-43238','赠葛氏小娘子','潘雍','quantangshi','','卷44','曾闻仙子住天台，欲结灵姻愧短才。
若许随君洞中住，不同刘阮却归来。','',''),('quantangshi-43239','送孙舍人归湘州','梁陟','quantangshi','','卷44','盛才倾世重，清论满朝归。
作隼他年计，为鸳此日飞。
比肩移日近，抗首出郊畿。
为报清漳水，分明照锦衣。','',''),('quantangshi-43240','再登河阳城怀古','朱延','quantangshi','','卷44','客游倦旅思，憩驾陟崇墉。
元凯标奇迹，安仁擅美踪。
远近浊河流，出没青山峰。
伫想空不极，怀古怅无从。','',''),('quantangshi-43241','题莹上人院','寇埴','quantangshi','','卷44','舍筏求香偈，因泉演妙音。
是明捐俗网，何独在山林。
缭绕藤轩密，逶迤竹径深。
为传同学志，兹宇可清心。','',''),('quantangshi-43242','燕衔泥','馮渚','quantangshi','','卷44','双燕碌碌飞入屋，屋中老人喜燕归，裴回绕我牀头飞。
去年为尔逐黄雀，雨多屋漏泥土落。
尔莫厌老翁茅屋低，梁头作窠梁下栖。
尔不见东家黄𪅏鸣啧啧，虵盘瓦沟鼠穿壁。
豪家大屋尔莫居，骄儿少妇采尔雏。
井旁写水泥自足，衔泥上屋随尔欲。','',''),('quantangshi-43243','日暖万年枝','王約','quantangshi','','卷44','霭霭彤庭里，沈沈玉砌陲。
初升九华日，潜暖万年枝。
煦妪光偏好，青葱色转宜。
每因韶景丽，长沐惠风吹。
隐映当龙阙，氛氲隔凤池。
朝阳光照处，唯有近臣知。','',''),('quantangshi-43244','日暖万年枝','郭求','quantangshi','','卷44','旭日升溟海，芳枝散曙烟。
温仁临树久，煦妪在条偏。
阳德符君惠，嘉名表圣年。
若承恩渥厚，常属栋梁贤。
生植虽依地，光华只信天。
不才堪仄陋，徒望向荣先。','',''),('quantangshi-43245','日暖万年枝','鄭師貞','quantangshi','','卷44','禁树敷荣早，偏将丽日宜。
光摇连北阙，影泛满南枝。
得地方知照，逢时异赫曦。
叶和盈数积，根是永年移。
宵露犹残润，薰风更共吹。
余晖诚可托，况近凤凰池。','',''),('quantangshi-43246','日华川上动','石殷士','quantangshi','','卷44','曙霞攒旭日，浮景弄晴川。
晃曜层潭上，悠扬极浦前。
岸高时拥媚，波远渐澄鲜。
萍实空随浪，珠胎不照渊。
早暄依曲渚，微动触轻涟。
孰假咸池望，幽情得古篇。','',''),('quantangshi-43247','闻击壤','石殷士','quantangshi','','卷44','尧年听野老，击壤复何云。
自谓欢由己，宁知德在君。
气平闲易畅，声贺作难分。
耕凿方随日，恩威比望云。
篑桴均下调，和木等南薰。
无落于吾事，谁将帝力闻。','',''),('quantangshi-43248','初日照华清宫','柴宿','quantangshi','','卷44','灵山初照泽，远近见离宫。
影动参差里，光分缥缈中。
鲜飙收晚翠，佳气满晴空。
林润温泉入，楼深复道通。
璇题生烱晃，珠缀引𦝰胧。
凤辇何时幸，朝朝此望同。','',''),('quantangshi-43249','瑜不掩瑕','柴宿','quantangshi','','卷44','朗玉微瑕在，分明异璞瑜。
坚贞宁可杂，美恶自能殊。
待价知弥久，称忠定不诬。
光辉今见黜，毫发外呈符。
岂假良工指，堪为达士模。
他山傥磨琢，慕爱是洪炉。','',''),('quantangshi-43250','秋日悬清光','陶拱','quantangshi','','卷44','秋至云容歛，天中日景清。
悬空寒色净，委照曙光盈。
泫泫看弥上，辉辉望最明。
烟霞轮乍透，葵藿影初生。
鉴下应无极，升高自有程。
何当回盛彩，一为表精诚。','',''),('quantangshi-43251','三让月成魄','劉𤤺','quantangshi','','卷44','为礼依天象，周旋逐月成。
教人三让美，为客一宵生。
初进轮犹暗，终辞影渐明。
幸陪宾主位，取舍任亏盈。','',''),('quantangshi-43252','海上生明月','朱華','quantangshi','','卷44','皎皎秋中月，团圆海上生。
影开金镜满，轮抱玉壶清。
渐出三山𡵒，将凌一汉横。
素娥尝药去，乌鹊遶枝惊。
照水光偏白，浮云色最明。
此时尧砌下，蓂荚自将荣。','',''),('quantangshi-43253','月夜梧桐叶上见寒露','戴察','quantangshi','','卷44','萧疎桐叶上，月白露初团。
滴沥清光满，荧煌素彩寒。
风摇愁玉坠，枝动惜珠干。
气冷疑秋晚，声微觉夜阑。
凝空流欲遍，润物净宜看。
莫厌窥临倦，将曦聚更难。','',''),('quantangshi-43254','清露被臯兰','孫顧','quantangshi','','卷44','九臯兰叶茂，八月露华清。
稍与秋阴合，还将晓色并。
向空罗细影，临水泫微明。
的皪添幽兴，芊绵动远情。
夕芳人未采，初降鹤先惊。
为感生成惠，心同葵藿倾。','',''),('quantangshi-43255','宿烟含白露','孫頠','quantangshi','','卷44','㭊㭊有新意，微微曙色幽。
露含疎月净，光与晓烟浮。
迥野遥凝素，空林望已秋。
着霜寒未结，凝叶滴还流。
比玉偏清洁，如珠讵可收。
裴回阡陌上，瞻想但淹留。','',''),('quantangshi-43256','送薛大夫和蕃','孫頠','quantangshi','','卷44','亚相独推贤，乘轺向远边。
一心倾汉日，万里望胡天。
忠信皇恩重，要荒圣德传。
戎人方屈膝，塞月复婵娟。
别思流莺晚，归朝候雁先。
当书外垣传，回奏赤墀前。','',''),('quantangshi-43257','风光草际浮','陳璀','quantangshi','','卷44','春风泛摇草，旭日遍神州。
已向花间积，还来叶上浮。
晓光缘圃丽，芳气满街流。
澹荡依朱萼，颻扬带玉沟。
向空看转媚，临水见弥幽。
况被崇兰色，王孙正可游。','',''),('quantangshi-43258','风光草际浮','裴杞','quantangshi','','卷44','澹荡和风至，芊绵碧草长。
徐吹遥扑翠，半偃乍浮光。
叶似翻宵露，藂疑扇夕阳。
逶迤明曲渚，照耀满回塘。
白芷生还暮，崇兰泛更香。
谁知揽结处，含思向余芳。','',''),('quantangshi-43259','风光草际浮','陳祜','quantangshi','','卷44','香发王孙草，春生君子风。
光摇低偃处，影散艳阳中。
稍稍移苹末，微微转蕙丛。
浮烟倾绿野，远色澹晴空。
泛彩池塘媚，含芳景气融。
清晖谁不挹，几许赏心同。','',''),('quantangshi-43260','风光草际浮','吳秘','quantangshi','','卷44','草色春沙里，风光晓正幽。
轻明摇不散，郁昱丽仍浮。
吹缓苗难转，晖闲叶本柔。
碧凝烟彩入，红是日华流。
耐可披襟对，谁应满掬收。
恭闻掇芳客，为此尚淹留。','',''),('quantangshi-43261','风光草际浮','張復元','quantangshi','','卷44','纤纤春草长，迟日度风光。
靃靡含新彩，霏微笼远芳。
殊姿媚原野，佳色满池塘。
最好垂清露，偏宜带艳阳。
浅深浮嫩绿，轻丽拂余香。
好助莺迁势，乘时冀便翔。','',''),('quantangshi-43262','冬至日祥风应候','穆寂','quantangshi','','卷44','节逢清景至，占气二仪中。
独喜登台日，先知应候风。
呈祥光舜化，表庆感尧聪。
既与乘时叶，还将入律同。
微微万井遍，习习九门通。
更绕炉烟起，殷勤报岁功。','',''),('quantangshi-43263','清风戒寒','穆寂','quantangshi','','卷44','风清物候残，萧洒报将寒。
扫得天衢静，吹来眼界宽。
条鸣方有异，虫思乱无端。
就树收鲜腻，冲池起涩澜。
过山岚可掬，度月色宜看。
华实从兹始，何嗟岁序殚。','',''),('quantangshi-43264','风草不留霜','王景中','quantangshi','','卷44','繁霜当永夜，寒草正惊风。
飘素衰苹末，流光晚蕙丛。
悠扬方泛影，皎洁却飞空。
不定离披际，难凝蘙荟中。
低昂闲散质，肃杀想成功。
独感玄晖咏，依依此夕同。','',''),('quantangshi-43265','春云','鄧倚','quantangshi','','卷44','摇曳自西东，依林又逐风。
势移青道里，影泛绿波中。
夕霁方明日，朝阳复蔽空。
度关随去马，出塞引归鸿。
色任寒暄变，光将远近同。
为霖如见用，还得助成功。','',''),('quantangshi-43266','登云梯','湯洙','quantangshi','','卷44','谢客常游处，层峦枕碧溪。
经过殊俗境，登陟象云梯。
步步劳山屐，行行蹑涧霓。
迥临天路广，俯眺夕阳低。
赏咏情弥惬，风尘事已暌。
前修如可慕，投足固思齐。','',''),('quantangshi-43267','登云梯','殷琮','quantangshi','','卷44','碧落远澄澄，青山路可升。
身轻疑易蹋，步独觉难凭。
逦迤排将近，回翔势渐登。
上宁愁屈曲，高更喜超腾。
江树遥分蔼，山岚宛若凝。
赤城容许到，敢惮百千层。','',''),('quantangshi-43268','秋山极天净','朱延齡','quantangshi','','卷44','雨洗高秋净，天临大野闲。
葱茏清万象，缭绕出层山。
日落千峯上，云销万壑间。
绿萝霜后翠，红叶雨来殷。
散彩辉吴甸，分形压楚关。
欲寻霄汉路，延首愿登攀。','',''),('quantangshi-43269','春台晴望','鄭蕡','quantangshi','','卷44','追赏层台迥，登临四望频。
熙熙山雨霁，处处柳条新。
草长秦城夕，花明汉苑春。
晴林翻去鸟，紫陌阅行人。
旅客风尘厌，山家梦寐亲。
迁莺思出谷，骞翥待芳辰。','',''),('quantangshi-43270','天骥呈材','鄭蕡','quantangshi','','卷44','毛骨合天经，拳奇步骤轻。
曾邀于阗驾，新出贰师营。
喷勒金铃响，追风汗血生。
酒亭留去迹，吴坂认嘶声。
力可通衢试，材堪圣代呈。
王良如故盻，垂耳欲长鸣。','',''),('quantangshi-43271','律中应钟','裴元','quantangshi','','卷44','律穷方数寸，室暗在三重。
伶管灰先动，秦正节已逢。
商声辞玉笛，羽调入金钟。
密叶翻霜彩，轻冰歛水容。
望鸿南去绝，迎气北来浓。
愿托无凋性，寒林自比松。','',''),('quantangshi-43272','闰月定四时','杜周士','quantangshi','','卷44','得闰因贞岁，吾君敬授时。
体元承夏道，推历法尧咨。
直取归余改，非如再失欺。
葭灰初变律，斗柄正当离。
寒暑功前定，春秋气可推。
更怜幽谷羽，鸣跃尚须期。','',''),('quantangshi-43273','闰月定四时','樂伸','quantangshi','','卷44','圣代承尧历，恒将闰正时。
六旬余可借，四序应如期。
分至宁愆素，盈虚信不欺。
斗杓重指甲，灰琯再推离。
羲氏兼和氏，行之又则之。
愿言符大化，永永作元龟。','',''),('quantangshi-43274','闰月定四时','徐至','quantangshi','','卷44','积数归成闰，羲和职旧司。
分铢标斗建，盈缩正人时。
节候潜相应，星辰自合期。
寸阴宁越度，长历信无欺。
定向铜壶辨，还从玉律推。
高明终不谬，委鉴本无私。','',''),('quantangshi-43275','新阳改故阴','紇干諷','quantangshi','','卷44','律管才推候，寒郊忽变阴。
微和方应节，积惨已辞林。
暗觉余澌断，潜惊丽景侵。
禁城佳气换，北陆翠烟深。
有截知遐布，无私荷照临。
韶光如可及，莺谷免幽沈。','',''),('quantangshi-43276','春水绿波','朱休','quantangshi','','卷44','芳时淑气和，春水澹烟波。
滉漾滋兰杜，沦涟长芰荷。
晚光扶翠潋，潭影写青莎。
归雁追飞尽，纤鳞游泳多。
朝宗终到海，润下每盈科。
愿假中流便，从兹发棹歌。','',''),('quantangshi-43277','海水不扬波','李沛','quantangshi','','卷44','明朝崇大道，寰海免波扬。
既合千年圣，能安百谷王。
天心随泽广，水德共灵长。
不挠鱼弥乐，无澜苇可航。
化流霑率土，恩浸及殊方。
岂只朝宗国，惟闻有越裳。','',''),('quantangshi-43278','四水合流','李沛','quantangshi','','卷44','禹凿山川地，因通四水流。
萦回过凤阙，会合出皇州。
天影长波里，寒声古度头。
入河无昼夜，归海有谦柔。
顺物宜投石，逢时可载舟。
羡鱼犹未已，临水欲垂钩。','',''),('quantangshi-43279','登圣善寺阁望龙门','成㟧','quantangshi','','卷44','高阁聊登望，遥分禹凿门。
刹连多宝塔，树满给孤园。
香境超三界，清流振陆浑。
报慈弘孝理，行道得真源。
空净祥烟霁，时光受日温。
愿从初地起，长奉下生尊。','',''),('quantangshi-43280','秋霁望庐山瀑布','夏侯楚','quantangshi','','卷44','常思瀑布幽，晴晀喜逢秋。
一带连青嶂，千寻倒碧流。
湿云应悞鹤，飜浪定惊鸥。
星浦虹初下，炉峰烟未收。
岩高时褭褭，天净起悠悠。
傥见朝宗日，还须济巨舟。','',''),('quantangshi-43281','济川用舟檝','胡權','quantangshi','','卷44','渺渺水连天，归程想几千。
孤舟辞曲岸，轻檝济长川。
迥指波涛雪，回瞻岛屿烟。
心迷沧海上，目断白云边。
泛滥虽无定，维持且自专。
还如圣明代，理国用英贤。','',''),('quantangshi-43282','洛出书','郭邕','quantangshi','','卷44','德合天贶呈，龙飞圣人作。
光宅被寰区，图书荐河洛。
象登四气顺，文辟九畴错。
氤氲瑞彩浮，左右灵仪廓。
微造功不宰，神行利攸博。
一见皇家庆，方知禹功薄。','',''),('quantangshi-43283','洛出书','張欽敬','quantangshi','','卷44','浮空九洛水，瑞圣千年质。
奇象八卦分，图书九畴出。
含微卜筮远，抱数阴阳密。
中得天地心，傍探鬼神吉。
昔闻夏禹代，今献唐尧日。
谬此叙彝伦，寰宇贺清谧。','',''),('quantangshi-43284','洛出书','叔孫玄觀','quantangshi','','卷44','清洛含温溜，玄龟荐宝书。
波开绿字出，瑞应紫宸居。
物着羣灵首，文成列卦初。
美珍翔阁凤，庆迈跃舟鱼。
俾姒惟何远，休皇复在诸。
东都主人意，歌颂望乘舆。','',''),('quantangshi-43285','玉壶冰','王季友','quantangshi','','卷44','玉壶知素结，止水复中澄。
坚白能虚受，清寒得自凝。
分形同晓镜，照物掩宵灯。
璧映圆光入，人惊爽气凌。
金罍何足贵，瑶席几回升。
正值求圭瓒，提携共饮冰。','',''),('quantangshi-43286','美玉','南巨川','quantangshi','','卷44','抱玉将何适，良工正在斯。
有瑕宁自掩，匪石幸君知。
雕琢嗟成器，缁磷志不移。
饰罇光宴赏，入佩奉威仪。
象德曾留记，如虹窃可奇。
终希逢善价，还得桂林枝。','',''),('quantangshi-43287','琢玉','丁居晦','quantangshi','','卷44','卞玉何时献，初疑尚在荆。
琢来闻制器，价炫胜连城。
虹气冲天白，云浮入信贞。
佩为廉节德，杯作侈奢名。
露璞方期辨，雕文幸既成。
他山岂无石，宁及此时呈。','',''),('quantangshi-43288','白圭无玷','辛宏','quantangshi','','卷44','片玉表坚贞，逢时宝自呈。
色鲜同雪白，光润夺冰清。
皎皎无瑕玷，锵锵有佩声。
昆山标重价，垂棘振香名。
抱璞心常苦，全真道未行。
琢磨忻大匠，还冀动连城。','',''),('quantangshi-43289','鲛人潜织','康翊仁','quantangshi','','卷44','珠馆冯夷室，灵鲛信所潜。
幽闲云碧牖，滉漾水精帘。
机动龙梭跃，丝萦藕淬添。
七襄牛女恨，三日大人嫌。
透手击吴练，凝冰笑越缣。
无因听札札，空想濯纤纤。','',''),('quantangshi-43290','瑕瑜不相掩','陳中師','quantangshi','','卷44','出石温然玉，瑕瑜素在中。
妍媸因异彩，音韵信殊风。
让美心方竝，求疵意本同。
光华开缜密，清润仰磨砻。
秀质非攘善，贞姿肯废忠。
今来傥成器，分别在良工。','',''),('quantangshi-43291','戛玉有余声','管雄甫','quantangshi','','卷44','戛玉音难尽，凝人思转清。
依稀流户牖，仿髴在檐楹。
更逐松风起，还将涧水并。
乐中和旧曲，天际转余声。
漂渺浮烟远，温柔入耳轻。
想如君子佩，时得上堂鸣。','',''),('quantangshi-43292','珠还合浦','鄧陟','quantangshi','','卷44','至宝含冲粹，清虚映浦湾。
素辉明荡漾，圆彩色玢㻞。
昔逐诸侯去，今随太守还。
影摇波里月，光动水中山。
鱼目徒相比，骊龙乍可攀。
愿将车饰用，长得耀君颜。','',''),('quantangshi-43293','浊水求珠','呂價','quantangshi','','卷44','至宝诚难得，潜光在浊流。
深沈当处晦，皎洁庶来求。
缀履将还用，褰裳必更收。
蚌胎应自别，鱼目岂能俦。
日彩逢高鉴，星光讵暗投。
不因今日取，泥滓出无由。','',''),('quantangshi-43294','暗投明珠','苑䛆','quantangshi','','卷44','至宝欣怀日，良兹岂可俦。
神光非易鉴，夜色信难投。
错落珍寰宇，圆明隔浅流。
精灵辞合浦，素彩耀神州。
抱影希人识，承时望帝求。
谁言按劒者，猜忌却生讐。','',''),('quantangshi-43295','暗投明珠','羅泰','quantangshi','','卷44','媚川时未识，在掌共传名。
报德能欺暗，投人自欲明。
月临幽室朗，星没晓河倾。
的皪骊龙颔，荧煌彩凤呈。
守恩辞合浦，擅美掩连城。
鱼目应难近，谁知按劒情。','',''),('quantangshi-43296','暗投明珠','崔藩','quantangshi','','卷44','至宝看怀袖，明珠出后收。
向人光不定，离掌势难留。
皎澈虚临夜，孤圆冷莹秋。
乍来惊月落，疾转怕星流。
有泪甘瑕弃，无媒自暗投。
今朝感恩处，将欲报隋侯。','',''),('quantangshi-43297','泗滨得石磬','李勳','quantangshi','','卷44','浮磬潜清深，依依呈碧浔。
出水见贞质，在悬含玉音。
对此喜还叹，几秋还到今。
器古契良觌，韵和谐宿心。
何为值明鉴，适得离幽沈。
自兹入清庙，无复泥沙侵。','',''),('quantangshi-43298','玄元皇帝应见贺圣祚无疆','趙鐸','quantangshi','','卷44','圣主今司契，神功格上玄。
岂唯求[傅]野，更有叶钧天。
审梦西山下，焚香北阙前。
道光尊圣日，福应集灵年。
咫尺真容近，巍峩大象悬。
觞从百寮献，形为万方传。
声教唯皇矣，英威固邈然。
惭无美周颂，徒上祝尧篇。','',''),('quantangshi-43299','太常寺观舞圣寿乐','徐元鼎','quantangshi','','卷44','舞字传新庆，人文迈旧章。
冲融和气洽，悠远圣功长。
盛德流无外，明时乐未央。
日华增顾眄，风物助低昂。
翥凤方齐首，高鸿忽断行。
云门与兹曲，同是奉陶唐。','',''),('quantangshi-43300','太清宫闻滴漏','嚴巨川','quantangshi','','卷44','玉漏移中禁，齐车入太清。
渐知催辨色，复听续余声。
乍逐微风转，时因杂佩轻。
青楼人罢梦，紫陌骑将行。
残魄栖初尽，余寒滴更生。
惭非朝谒客，空有振衣情。','',''),('quantangshi-43301','仲秋太常寺观公卿辂车拜陵','嚴巨川','quantangshi','','卷44','南吕初开律，金风已戒凉。
拜陵将展敬，车辂俨成行。
士庶观祠礼，公卿习旧章。
郊原佳气引，园寝瑞烟长。
卤簿辞丹阙，威仪列太常。
圣心何所寄，惟德在无忘。','',''),('quantangshi-43302','贡举人谒先师闻雅乐','呂炅','quantangshi','','卷44','礼圣来羣彦，观光在此时。
闻歌音乍远，合乐和还迟。
调朗能谐竹，声微又契丝。
轻泠流簨簴，缭绕动缨緌。
九变将随节，三终必尽仪。
国风由是正，王化自雍熙。','',''),('quantangshi-43303','望凌烟阁','劉公興','quantangshi','','卷44','画阁凌虚构，遥瞻在九天。
丹楹崇壮丽，素壁绘勋贤。
霭霭浮元气，亭亭出瑞烟。
近看分百辟，远揖误羣仙。
图列青云外，仪刑紫禁前。
望中空霁景，骧首几留连。','',''),('quantangshi-43304','观北番谒庙','王卓','quantangshi','','卷44','肃肃层城里，巍巍祖庙清。
圣恩覃布濩，异域献精诚。
冠盖分行列，戎夷变姓名。
礼终齐百拜，心洁尽忠贞。
瑞气千重色，箫韶九奏声。
仗移迎日转，斾动逐风轻。
休运威仪盛，丰年俎豆盈。
不堪惭颂德，空此望簪缨。','',''),('quantangshi-43305','舞干羽两阶','石倚','quantangshi','','卷44','干羽能柔远，前阶舞正陈。
欲称文德盛，先表乐声新。
肃肃行初列，森森气益振。
动容和律吕，变曲静风尘。
化美超千古，恩波及七旬。
已知天下服，不独有苗人。','',''),('quantangshi-43306','御制段太尉碑','葉元良','quantangshi','','卷44','多难全高节，时清轸圣君。
园茔标石篆，雨露降天文。
义激忠贞没，词伤兰蕙焚。
国人皆堕泪，王府已铭勋。
揭出临新陌，长留对古坟。
睿情幽感处，应使九泉闻。','',''),('quantangshi-43307','恩赐魏文贞公诸孙旧第以导直臣','裴大章','quantangshi','','卷44','邢茅虽旧锡，邸第是初荣。
迹往伤遗事，恩深感直声。
云孙方庆袭，池馆忽春生。
古甃开泉井，新禽绕画楹。
自然垂带砺，况复激忠贞。
必使千年后，长书竹帛名。','',''),('quantangshi-43308','恩赐耆老布帛','崔宗','quantangshi','','卷44','涣汗中天发，殊私海外存。
衰颜逢圣代，华发受皇恩。
烛物明尧日，垂衣辟禹门。
惜时悲落景，赐帛慰余魂。
厚泽沾祥咏，微生保子孙。
盛明今尚齿，欢洽九衢罇。','',''),('quantangshi-43309','东都父老望幸','鄭馥','quantangshi','','卷44','銮舆秦地久，羽卫洛阳空。
彼土虽凭固，兹川乃得中。
龙颜觐白日，鹤发仰清风。
望幸诚逾邈，怀来意不穷。
昔因封泰岳，今伫蹑维嵩。
天地心无异，神只理亦同。
翠华翔渭北，玉检候关东。
众愿其难阻，明君早勒功。','',''),('quantangshi-43310','言行相顾','吳叔達','quantangshi','','卷44','圣人垂政教，万古请常传。
立志言为本，修身行乃先。
相须宁得阙，相顾在无偏。
荣辱当于己，忠贞必动天。
大名如副宝，至道亦通玄。
千里犹能应，何云迩者焉。','',''),('quantangshi-43311','言行相顾','孟翺','quantangshi','','卷44','将使言堪复，常闻行欲先。
比圭斯不玷，修己直如弦。
跬步非全进，吹嘘禀自然。
当令夫子察，无宿仲由贤。
正遇兴邦际，因怀入署年。
坐知清监下，相顾有人焉。','',''),('quantangshi-43312','人不易知','鄭昉','quantangshi','','卷44','如面诚非一，深心岂易知。
入秦书十上，投楚岁三移。
和玉翻为泣，齐竽或滥吹。
周行虽有置，殷鉴在前规。
寅亮推多士，清通固赏奇。
病诸方号哲，敢相反成疵。
冬日承余爱，霜云喜暂披。
无令见瞻后，回照复云疲。','',''),('quantangshi-43313','早春送郎官出宰','袁求賢','quantangshi','','卷44','仙郎今出宰，圣主下忧民。
紫陌轩车送，丹墀雨露新。
趋程犹犯雪，行县正逢春。
粉署时回首，铜章已在身。
鸣琴化欲展，起草恋空频。
今日都门外，悠悠别汉臣。','',''),('quantangshi-43314','饯王将军赴云中','孟匡明','quantangshi','','卷44','一师凭庙畧，分阃佐元戎。
势亚彤弓宠，时推金印雄。
关山横代北，旌节壮河东。
日转前茅影，春生细柳风。
饮冰君命速，挥涕饯筵空。
伫听阴山静，谁争万里功。','',''),('quantangshi-43315','西戎即叙','李子昂','quantangshi','','卷44','悬首藁街中，天兵破犬戎。
营收低陇月，旗偃度湟风。
肃杀三边劲，萧条万里空。
元戎咸服罪，余孽尽输忠。
圣理符轩化，仁恩契禹功。
降逾洞庭险，枭拟郅支穷。
已散军容捷，还资庙算通。
今朝观即叙，非与献獒同。','',''),('quantangshi-43316','禁中春松','員南溟','quantangshi','','卷44','郁郁贞松树，阴阴在紫宸。
葱茏偏近日，青翠更宜春。
雅韵风来起，轻烟霁后新。
叶深栖语鹤，枝亚拂朝臣。
全节长依地，凌云欲致身。
山苗荫不得，生植荷陶钧。','',''),('quantangshi-43317','玉烛','員南溟','quantangshi','','卷44','历象璇玑正，休征玉烛明。
四时佳气满，五纬太阶平。
律吕风光至，烟云瑞色呈。
年和知岁稔，道泰喜秋成。
寰海皇恩被，干坤至化清。
自怜同野老，帝力讵能名。','',''),('quantangshi-43318','文宣王庙古松','李胄','quantangshi','','卷44','列植成均里，分行古庙前。
阴森非一日，苍翠自何年。
寒影烟霜暗，晨光枝叶妍。
近檐阴更静，临砌色相鲜。
每愧闻钟磬，多惭接豆笾。
更宜教胄子，于此学贞坚。','',''),('quantangshi-43319','华林园早梅','鄭述誠','quantangshi','','卷44','晓日东楼路，林端见早梅。
独凌寒气发，不逐众花开。
素彩风前艳，韶光雪后催。
蘂香霑紫陌，枝亚拂青苔。
止渴曾为用，和羹旧有才。
含情欲攀折，瞻望几裴回。','',''),('quantangshi-43320','龙池春草','迪','quantangshi','','卷44','凤阙韶光遍，龙池草色匀。
烟波全让绿，堤柳不争新。
翻叶迎红日，飘香借白苹。
幽姿偏占暮，芳意欲留春。
已胜生金埓，长思藉玉轮。
翠华如见幸，正好及兹辰。','',''),('quantangshi-43321','龙池春草','万俟造','quantangshi','','卷44','暖积龙池绿，晴连御苑春。
迎风茎未偃，裛露色犹新。
苒苒分阶砌，离离杂荇苹。
细丛依远渚，疎影落轻沦。
迟引萦花蝶，偏宜拾翠人。
那怜献赋者，惆怅惜兹辰。','',''),('quantangshi-43322','贡院楼北新栽小松','錢衆仲','quantangshi','','卷44','爱此凌霜操，移来独占春。
贞心初得地，劲节始依人。
笼月烟犹薄，当轩色转新。
枝低无宿羽，叶静不留尘。
每与芝兰近，常慙雨露均。
幸因逢顾盼，生植及兹辰。','',''),('quantangshi-43323','玉壶冰','錢衆仲','quantangshi','','卷44','冬律初阴结，寒冰贮玉壶。
霜姿虽异禀，虹气亦相符。
对月光宜竝，临池影不孤。
贞坚方共济，同处岂殊途。
色莹连城璧，形分照乘珠。
提携今在此，抱素节宁渝。','',''),('quantangshi-43324','潘安仁戴星看河阳花发','呂敞','quantangshi','','卷44','行春潘令至，勤恤戴星光。
为政宵忘寝，临人俗冀康。
晓花迎径发，新蘂满城香。
秀色霑轻露，鲜辉丽早阳。
津桥见来往，空雾拂衣裳。
桃李今无数，从兹愿比方。','',''),('quantangshi-43325','龟兹闻莺','呂敞','quantangshi','','卷44','边树正参差，新莺复陆离。
娇非胡俗变，啼是汉音移。
绣羽花间覆，繁声风外吹。
人言曾不辨，鸟语却相知。
出谷情何寄，迁乔义取斯。
今朝乡陌伴，几处坐高枝。','',''),('quantangshi-43326','好鸟鸣高枝','鄭衮','quantangshi','','卷44','养翮非无待，迁乔信自卑。
影高迟日度，声远好风随。
云拂千寻直，花催百啭奇。
惊人时向晚，求友听应知。
委质经三岁，先鸣在一枝。
上林如可托，弱羽愿差池。','',''),('quantangshi-43327','金谷园花发怀古','張公乂','quantangshi','','卷44','今日春风至，花开石氏园。
未全红艳折，半与素光翻。
点缀疎林遍，微明古径繁。
窥临莺欲语，寂寞李无言。
谷变迷铺锦，台余认树萱。
川流人事共，千载竟谁论。','',''),('quantangshi-43328','织鸟','張何','quantangshi','','卷44','季春三月里，戴胜下桑来。
映日华冠动，迎风绣羽开。
候惊蚕事晚，织向女工裁。
旅宿依花定，轻飞遶树回。
欲过高阁柳，更拂小庭梅。
所寄一枝在，宁忧弋者猜。','',''),('quantangshi-43329','出笼鹘','濮陽瓘','quantangshi','','卷44','玉镞分花袖，金铃出彩笼。
摇心长捧日，逸翰镇生风。
一点青霄里，千声碧落中。
星眸随狡兔，霜爪落飞鸿。
每念提携力，常怀搏击功。
以君能惠好，不敢没遥空。','',''),('quantangshi-43330','试越裳贡白雉','王若嵒','quantangshi','','卷44','素翟宛昭彰，遥遥自越裳。
冰晴朝映日，玉羽夜含霜。
岁月三年远，山川九泽长。
来从碧海路，入见白云乡。
作瑞兴周后，登歌美汉皇。
朝天资孝理，惠化且无疆。','',''),('quantangshi-43331','勅赐三相马','張隨','quantangshi','','卷44','上苑骅骝出，中宫诏命传。
九天班锡礼，三相代劳年。
顾主声犹发，追风力正全。
鸣珂龙阙下，喷玉凤池前。
四足疑云灭，双瞳比镜悬。
为因能致远，今日表求贤。','',''),('quantangshi-43332','河中献捷','張隨','quantangshi','','卷44','叛将忘恩久，王师不战通。
凯歌千里内，喜气二仪中。
寇尽条山下，兵回汉苑东。
将军初执讯，明主欲论功。
落日烟尘静，寒郊壁垒空。
苍生幸无事，自此乐尧风。','',''),('quantangshi-43333','天骥呈材','徐仁嗣','quantangshi','','卷44','至德符天道，龙媒应圣明。
追风奇质异，喷玉彩毛轻。
躞蹀形难状，连拳势乍呈。
効材矜逸态，绝影表殊名。
岐路宁辞远，关山岂惮行。
盐车虽不驾，今日亦长鸣。','',''),('quantangshi-43334','天骥呈材','盧征','quantangshi','','卷44','异产应尧年，龙媒顺制牵。
权奇初得地，躞蹀欲行天。
讵假调金埒，宁须动玉鞭。
嘶风深有恋，逐日定无前。
周满夸常驭，燕昭恨不传。
应知流赭汗，来自海西偏。','',''),('quantangshi-43335','云夜听猨吟','顧偉','quantangshi','','卷44','寒岩飞暮雪，绝壁夜猨吟。
历历和羣雁，寥寥思客心。
绕枝犹避箭，过岭却投林。
风冷声偏苦，山寒响更深。
听时无有定，静里固难寻。
一宿扶桑月，聊看怀好音。','',''),('quantangshi-43336','寒蝉树','沈鵬','quantangshi','','卷44','一叶初飞日，寒蝉益易惊。
入林慙织细，依树愧身轻。
大干时容息，乔枝或借鸣。
心由饮露静，响为逐风清。
忝有翩翾分，应怜嘒唳声。
不知微薄影，早晚挂緌缨。','',''),('quantangshi-43337','临川羡鱼','薛少殷','quantangshi','','卷44','曾是归家客，今年且未旋。
游鳞方有待，织网岂能捐。
向水烟波夕，吟风岁月迁。
莓苔生古岸，葭菼变清川。
不逐沧波叟，还宗内外篇。
良辰难自掷，此日愿忘筌。','',''),('quantangshi-43338','临川羡鱼','張元正','quantangshi','','卷44','有客百愁侵，求鱼正在今。
广川何渺漫，高岸几登临。
风水宁相阻，烟霞岂惮深。
不应同逐鹿，讵肯比从禽。
结网非无力，忘筌自有心。
永存芳饵在，伫立思沈沈。','',''),('quantangshi-43339','答王无功入长安咏秋蓬见示','辛學士','quantangshi','','卷44','托根虽异所，飘叶早相依。
因风若有便，更共入云飞。','',''),('quantangshi-43340','哭李远','盧尚書','quantangshi','','卷44','昨日舟还浙水湄，今朝丹旐欲何为。
才收北浦一竿钓，未了西斋半局棊。
洛下已传平子赋，临川争写谢公诗。
不堪旧里经行处，风木萧萧邻笛悲。','',''),('quantangshi-43341','湘中怨讽','鄭僕射','quantangshi','','卷44','青鷁苦幽独，隔江相对稀。
夜寒芦叶雨，空作一声归。','',''),('quantangshi-43342','登汾上阁','鄭中丞','quantangshi','','卷44','汾桂秋水阔，宛似到阊门。
惆怅江湖思，惟将南客论。','',''),('quantangshi-43343','为御史衔命出关谳狱道中看华山有诗','韓常侍','quantangshi','','卷44','野麋蒙象暂如犀，心不惊鸥角骇鸡。
一路好山无伴看，断肠烟景寄猨啼。','',''),('quantangshi-43344','寄织锦篇与薛郎中','韓常侍','quantangshi','','卷44','锦字龙梭织锦篇，凤皇文采间非烟。
并他时世新花样，虚费工夫不直钱。','',''),('quantangshi-43345','和人忆鹤','韓常侍','quantangshi','','卷44','拂拂云衣冠紫烟，已为丁令一千年。
留君且伴居山客，幸有松梢明月天。','',''),('quantangshi-43346','句','韓常侍','quantangshi','','卷44','情多不似家山水，夜夜声声旁枕流。','',''),('quantangshi-43347','赠米都知','梁補闕','quantangshi','','卷44','供奉三朝四十年，圣时流落发衰残。
贪将乐府歌明代，不把清吟换好官。','',''),('quantangshi-43348','题安国观','盧尚書','quantangshi','','卷44','夕照纱窗起暗尘，青松遶殿不知春。
君看白首诵经者，半是宫中歌舞人。','',''),('quantangshi-43349','自商山宿隐居','蘇廣文','quantangshi','','卷44','闻道桃源堪避秦，寻幽数日不逢人。
烟霞洞里无鸡犬，风雨林中有鬼神。
黄公石上三芝秀，陶令门前五柳春。
醉卧白云闲入梦，不知何物是吾身。','',''),('quantangshi-43350','夜归华川因寄幕府','蘇廣文','quantangshi','','卷44','山村寥落野人稀，竹里衡门掩翠微。
溪路夜随明月入，亭臯春伴白云归。
嵇康懒慢仍耽酒，范蠡逋逃又拂衣。
汀畔数鸥闲不起，只应知我已忘机。','',''),('quantangshi-43351','春日过田明府遇焦山人','蘇廣文','quantangshi','','卷44','陶公归隐白云溪，买得春泉溉药畦。
夜静林间风虎啸，月明竹上露禽栖。
陈仓邑吏惊烽火，太白山人讶鼓鼙。
相见只言秦汉事，武陵溪里草萋萋。','',''),('quantangshi-43352','题升山','任生','quantangshi','','卷44','城外升山寺，城中望宛然。
及登无半日，欲到已经年。','',''),('quantangshi-43353','投曹文姬诗','任生','quantangshi','','卷44','玉皇前殿掌书仙，一染尘心下九天。
莫怪浓香薰骨腻，云衣曾惹御炉烟。','',''),('quantangshi-43354','绝句','吳公','quantangshi','','卷44','去国投兹土，编茅隐旧踪。
年年秋水上，独对数株松。','',''),('quantangshi-43355','献卢常侍','曹生','quantangshi','','卷44','拜玉亭前闲送客，此时孤恨感离乡。
寻思往岁绝缨事，肯向朱门泣夜长。','',''),('quantangshi-43356','赋新月','繆氏子','quantangshi','','卷44','初月如弓未上弦，分明挂在碧霄边。
时人莫道蛾眉小，三五团圆照满天。','',''),('quantangshi-43357','悼妓诗','京兆韋氏子','quantangshi','','卷44','惆怅金泥簇蝶裙，春来犹见伴行云。
不教布施刚留得，浑似初逢李少君。','',''),('quantangshi-43358','长宁公主宅流杯','景龍文館學士','quantangshi','','卷44','凭高瞰逈足怡心，[菌]阁桃源不暇寻。
余雪依林成玉树，残霙点岫即瑶岑。','',''),('quantangshi-43359','侍宴桃园咏桃花应制','神龍從臣','quantangshi','','卷44','源水丛花无数开，丹跗红萼间青梅。
从今结子三千岁，预喜仙游复摘来。','',''),('quantangshi-43360','玉龙子诗','天寶時人','quantangshi','','卷44','圣运潜符瑞玉龙，自兴云雨更无踪。
不如渭水沙中得，争保銮舆复九重。','',''),('quantangshi-43361','寄兄','僖宗朝北省官','quantangshi','','卷44','涉江今日恨偏多，援笔长吁欲奈何。
倘使泪流西去得，便应添作锦江波。','',''),('quantangshi-43362','题屈原祠','洪州將軍','quantangshi','','卷44','苍藤古木几经春，旧祀祠堂小水滨。
行客谩陈三酎酒，大夫元是独醒人。','',''),('quantangshi-43363','题端正树','貞元文士','quantangshi','','卷44','昔日偏霑雨露荣，德皇西幸赐嘉名。
马嵬此去无多地，合向杨妃冢上生。','',''),('quantangshi-43364','寄内诗','河北士人','quantangshi','','卷44','握笔题诗易，荷戈征戍难。
惯从鸳被暖，怯向雁门寒。
瘦尽宽衣带，啼多渍枕檀。
试留青黛着，回日画眉看。','',''),('quantangshi-43365','代妻答诗','河北士人','quantangshi','','卷44','蓬鬓荆钗世所稀，布裙犹是嫁时衣。
胡麻好种无人种，合是归时底不归。','',''),('quantangshi-43366','丙申岁诗','和舉子','quantangshi','','卷44','元和天子丙申年，三十三人同得仙。
袍似烂银文似锦，相将白日上青天。','',''),('quantangshi-43367','刺安南事诗','懿宗朝舉子','quantangshi','','卷44','南荒不择吏，致我交趾覆。
联绵三四年，致我交趾辱。
儒者鬬则退，武者兵益黩。
军容满天下，战将多金玉。
刮得齐民疮，分为猛士禄。
雄雄许昌师，忠武冠其族。
去为万骑风，住为一川肉。
时有残卒回，千门万户哭。
哀声动闾里，怨气成山谷。
谁能听鼓声，不忍看金镞。
念此堪泪流，悠悠颍川绿。','',''),('quantangshi-43368','歌','白衫舉子','quantangshi','','卷44','执板狂歌乞个钱，尘中流浪且随缘。
直饶到老常如此，犹胜危时弄化权。','',''),('quantangshi-43369','覩野花思京师旧游','末朝士','quantangshi','','卷44','曾过街西看牡丹，牡丹才谢便心阑。
如今变作村园眼，鼓子花开也喜欢。','',''),('quantangshi-43370','哥舒歌','西鄙人','quantangshi','','卷44','北斗七星高，哥舒夜带刀。
至今窥牧马，不敢过临洮。','',''),('quantangshi-43371','答人','太上隱君','quantangshi','','卷44','偶来松树下，高枕石头眠。
山中无历日，寒尽不知年。','',''),('quantangshi-43372','向竹吟','黃山隱','quantangshi','','卷44','积尘为太山，掬水成东海。
富贵有时乖，希夷无日改。
绛节出崆峒，霓衣发光彩。
古者有七贤，六个今何在。','',''),('quantangshi-43373','歌','婺州山中人','quantangshi','','卷44','静居青嶂里，高啸紫烟中。
尘世连仙界，琼田前路通。','',''),('quantangshi-43374','五子之歌 一','同谷子','quantangshi','','卷44','邦惟固本自安宁，临下常须驭朽惊。
何事十旬游不返，祸胎从此召殷兵。','',''),('quantangshi-43375','五子之歌 二','同谷子','quantangshi','','卷44','酒色声禽号四荒，那堪峻宇又雕墙。
静思今古为君者，未或因兹不灭亡。','',''),('quantangshi-43376','五子之歌 三','同谷子','quantangshi','','卷44','唯彼陶唐有冀方，少年都不解思量。
如今算得当时事，首为盘游乱纪纲。','',''),('quantangshi-43377','五子之歌 四','同谷子','quantangshi','','卷44','明明我祖万邦君，典则贻将示子孙。
惆怅太康荒坠后，覆宗绝祀灭其门。','',''),('quantangshi-43378','五子之歌 五','同谷子','quantangshi','','卷44','仇讐万姓遂无依，颜厚何曾解忸怩。
五子既歌邦已失，一场前事悔难追。','',''),('quantangshi-43379','献公佐诗','崔公佐客','quantangshi','','卷44','破额幞头衫也穿，使君犹许对华筵。
今朝幸倚文章守，遮莫青蛾笑揭天。','',''),('quantangshi-43380','赠妓茂英','洛中舉子','quantangshi','','卷44','忆昔当初过柳楼，茂英年小尚娇羞。
隔窗未省闻高语，对镜曾窥学上头。
一别中原俱老大，再来南国见风流。
弹弦酌酒话前事，零落碧云生暮愁。','',''),('quantangshi-43381','又赠妓茂英','洛中舉子','quantangshi','','卷44','少插花枝少下筹，须防女伴妬风流。
坐中若打占相令，除却尚书莫点头。','',''),('quantangshi-43382','寄故姬','江陵士子','quantangshi','','卷44','阴云羃羃下阳台，惹着襄王更不回。
五度看花空有泪，一心如结不曾开。
纤萝自合依芳树，覆水宁思返旧杯。
惆怅高丽坡底宅，春光无复下山来。','',''),('quantangshi-43383','吟','織錦人','quantangshi','','卷44','学织缭绫功未多，乱拈机杼错抛梭。
莫教官锦行家见，把此文章笑杀他。','',''),('quantangshi-43384','句','織錦人','quantangshi','','卷44','如今不重文章士，莫把文章夸向人。','',''),('quantangshi-43385','送南中尉','吏部選人','quantangshi','','卷44','羡君初拜职，嗟我独无名。
且是正员尉，全胜兼试卿。','',''),('quantangshi-43386','题紫微观','建業卜者','quantangshi','','卷44','昨日朝天过紫微，醮坛风冷杏花稀。
碧桃泥我传消息，何事人间更不归。','',''),('quantangshi-43387','题邓仙客墓','天嶠遊人','quantangshi','','卷44','鹤老芝田鸡在笼，上清那与俗尘同。
既言白日升仙去，何事人间有殡宫。','',''),('quantangshi-43388','题故翠微宫','驪山遊人','quantangshi','','卷44','翠微寺本翠微宫，楼阁亭台几十重。
天子不来僧又去，樵夫时倒一株松。','',''),('quantangshi-43389','吟','衡州舟子','quantangshi','','卷44','野鹊滩西一棹孤，月光遥接洞庭湖。
堪嗟回雁峰前过，望断家山一字无。','',''),('quantangshi-43390','月夜','華山老人','quantangshi','','卷44','涧水泠泠声不绝，溪流茫茫野花发。
自去自来人不知，归时常对空山月。','',''),('quantangshi-43391','终南','終南山翁','quantangshi','','卷44','霜鹤鸣时夕风急，乱鸦又向寒林集。
此君辍棹悲且吟，独对莲花一峰立。','',''),('quantangshi-43392','大庆堂赐宴元璫有诗呈吴越王','吳越失姓名人','quantangshi','','卷44','非为亲贤展绮筵，恒常宁敢恣游盘。
绿搓杨柳绵初软，红晕樱桃粉未干。
谷鸟乍啼声似涩，甘霖方霁景犹寒。
笙歌风紧人酣醉，却遶珍丛烂熳看。','',''),('quantangshi-43393','又和大庆堂赐宴元璫有诗呈吴越王','吳越失姓名人','quantangshi','','卷44','樱桃花下会亲贤，风远铜壶转露盘。
蝶下粉墙梅乍折，蚁浮金斝酒难干。
云和缓奏泉声咽，珠箔低垂水影寒。
狂简斐然吟咏足，却邀羣彦重吟看。','',''),('quantangshi-43394','再和大庆堂赐宴元璫有诗呈吴越王','吳越失姓名人','quantangshi','','卷44','我有嘉宾宴乍欢，画帘纹细凤双盘。
影笼沼沚修篁密，声透笙歌羯鼓干。
散后便依书箧寐，渴来潜想玉壶寒。
樱桃零落红桃媚，更俟旬余共醉看。','',''),('quantangshi-43395','重和大庆堂赐宴元璫有诗呈吴越王','吳越失姓名人','quantangshi','','卷44','冷宴殷勤展小园，舞鞇柔软彩虬盘。
篸花尽日疑头重，病酒经宵觉口干。
嘉树倚楼青琐暗，晚云藏雨碧山寒。
文章天子文章别，八采卢郎未可看。','',''),('quantangshi-43396','御制春游长句','吳越失姓名人','quantangshi','','卷44','天意分明道已光，春游嘉景胜仙乡。
玉炉烟直风初静，银汉云销日正长。
柳带似眉全展绿，杏苞似脸半开香。
黄莺历历啼红树，紫燕关关语画梁。
低槛晚晴笼翡翠，小池波暖浴鸳鸯。
马嘶广陌贪新草，人醉花堤怕夕阳。
比屋管弦呈妙曲，连营罗绮鬬时妆。
全吴霸越千年后，独此升平显万方。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-43397','明月湖醉后蔷薇花歌','無名氏','quantangshi','','卷44','万朵当轩红灼灼，晚阴照水尘不着。
西施醉后情不禁，侍儿扶下蘂珠阁。
柔条嫩蘂轻𩸬鳃，一低一昂合又开。
深红浅绿状不得，日斜池畔香风来。
红能柔，绿能软，浓淡参差相宛转。
舞蝶双双谁唤来，轻绡片片何人剪。
白发使君思帝乡，驱妻领女游花傍。
持杯忆着曲江事，千花万叶垂宫墙。
复有同心初上第，日暮华筵移水际。
笙歌日日征教坊，倾国名倡尽佳丽。
我曾此处同诸生，飞盂落盏纷纵横。
将欲得到上天路，刚向直道中行去。
一朝失势当如此，万事如灰壮心死。
谁知奏御数万言，翻割龟符四千里。
丈夫达则贤，穷则愚，胡为紫，胡为朱。
莫思身外穷通事，且醉花前一百壶。','',''),('quantangshi-43398','春二首 一','無名氏','quantangshi','','卷44','褭褭东风吹水国，金鸦影暖南山北。
蒲抽小劒割湘波，柳拂长眉舞春色。
白铜堤下烟苍苍，林端细蘂参差香。
绿桑枝下见桃叶，回看青云空断肠。','',''),('quantangshi-43399','春二首 二','無名氏','quantangshi','','卷44','乌足迟迟日宫里，天门击鼓龙蛇起。
风师剪翠换枯条，青帝挼蓝染江水。
蜂蝶缤纷抱香蘂，锦鳞跳掷红云尾。
绣衣白马不归来，双成倚槛春心醉。','',''),('quantangshi-43400','夏','無名氏','quantangshi','','卷44','赤帝旗迎火云起，南山石裂吴牛死。
绣楹夜夜箔鰕须，象榻重重簟湘水。
彤彤日脚烧冰井，古陌尘飞野烟静。
汉帝高堂汗若珠，班姬明月无停影。','',''),('quantangshi-43401','秋','無名氏','quantangshi','','卷44','月色驱秋下穹昊，梁间燕语辞巢早。
古苔凝紫贴瑶堦，露槿啼红堕江草。
越客羁魂挂长道，西风欲揭南山倒。
粉娥恨骨不胜衣，映门楚碧蝉声老。','',''),('quantangshi-43402','冬','無名氏','quantangshi','','卷44','苍茫枯碛阴云满，古木号空昼光短。
云拥三峯岳色低，冰坚九曲河声断。
浩汗霜风刮天地，温泉火井无生意。
泽国龙蛇冻不伸，南山瘦柏销残翠。','',''),('quantangshi-43403','鸡头','無名氏','quantangshi','','卷44','湖浪参差叠寒玉，水仙晓展钵盘绿。
淡黄根老栗皱圆，染青刺短金罂熟。
紫罗小囊光紧蹙，一掬真珠藏猬腹。
丛丛引觜傍莲洲，满川恐作天鸡哭。','',''),('quantangshi-43404','红蔷薇','無名氏','quantangshi','','卷44','九天碎霞明泽国，造化工夫潜剪刻。
浅碧眉长约细枝，深红刺短钩春色。
晴日当楼晓香歇，锦带盘空欲成结。
谢豹声催麦陇秋，春风吹落猩猩血。','',''),('quantangshi-43405','斑竹簟','無名氏','quantangshi','','卷44','龙鳞满牀波浪湿，血光点点湘娥泣。
一片晴霞冻不飞，深沈尽讶蛟人立。
百朵排花蜀缬明，珊瑚枕滑葛衣轻。
闲窗独卧晓不起，冷浸羁魂锦江里。','',''),('quantangshi-43406','听琴','無名氏','quantangshi','','卷44','六律铿锵间宫征，伶伦写入梧桐尾。
七条瘦玉叩寒星，万派流泉哭纤指。
空山雨脚随云起，古木灯青啸山鬼。
田文堕泪曲未终，子规啼血哀猿死。','',''),('quantangshi-43407','石榴','無名氏','quantangshi','','卷44','蝉啸秋云槐叶齐，石榴香老庭枝低。
流霞色染紫罂粟，黄蜡纸苞红瓠犀。
玉刻冰壶[含]露湿，斒斑似带湘娥泣。
萧娘初嫁嗜甘酸，嚼破水精千万粒。','',''),('quantangshi-43408','秦家行','無名氏','quantangshi','','卷44','彗孛飞光照天地，九天瓦裂屯冤气。
鬼哭声声怨赵高，宫花滴尽扶苏泪。
祸起萧墙不知戢，羽书催筑长城急。
劒上忠臣血未干，沛公已向函关入。','',''),('quantangshi-43409','小苏家','無名氏','quantangshi','','卷44','双月讴䛩辗秋碧，细风斜掩神仙宅。
麦门冬长马鬣青，茱萸蘂绽蝇头赤。
流苏斗帐悬高壁，彩凤盘龙缴香额。
堂内月娥横剪波，倚门肠断鰕须隔。','',''),('quantangshi-43410','斑竹','無名氏','quantangshi','','卷44','浓绿疎茎遶湘水，春风抽出蛟龙尾。
色抱霜花粉黛光，枝撑蜀锦红霞起。
交戛敲欹无俗声，满林风曳刀枪横。
殷痕苦雨洗不落，犹带湘娥泪血腥。
袅娜梢头扫秋月，影穿林下疑残雪。
我今慙愧子猷心，解爱此君名不灭。','',''),('quantangshi-43411','天竺国胡僧水晶念珠','無名氏','quantangshi','','卷44','天竺胡僧踏云立，红精素贯鲛人泣。
细影疑随焰火销，圆光恐滴袈裟湿。
夜梵西天千佛声，指轮次第驱寒星。
若非叶下滴秋露，则是井底圆春冰。
凄清妙丽应难并，眼界真如意珠静。
碧莲花下独提携，坚洁何如幻泡影。','',''),('quantangshi-43412','白雪歌','無名氏','quantangshi','','卷44','皇穹何处飞琼屑，散下人间作春雪。
五花马踏白云衢，七香车碾瑶墀月。
苏岩乳洞拥山家，涧藤古栗盘银虵。
寒郊复叠铺柳絮，古碛烂熳吹芦花。
流泉不下孤汀咽，断臂老猿声欲绝。
鸟啄冰潭玉镜开，风敲檐溜水晶折。
拂户初疑粉蝶飞，看山又讶白鸥归。
孙康冻死读书围，火井不暖温泉微。','',''),('quantangshi-43413','琵琶','無名氏','quantangshi','','卷44','粉胸绣臆谁家女，香拨星星共春语。
七盘岭上走鸾铃，十二峯头弄云雨。
千悲万恨四五弦，弦中甲马声骈阗。
山僧扑破瑠璃钵，壮士击折珊瑚鞭。
珊瑚鞭折声交戛，玉盘倾泻真珠滑。
海神驱趁夜涛回，江娥蹙踏春冰裂。
满坐红妆尽泪垂，望乡之客不胜悲。
曲终调绝忽飞去，洞庭月落孤云归。','',''),('quantangshi-43414','伤哉行','無名氏','quantangshi','','卷44','兔走乌飞不相见，人事依稀速如电。
王母夭桃一度开，玉楼红粉千回变。
车驰马走咸阳道，石家旧宅空荒草。
秋雨无情不惜花，芙蓉一一惊颠倒。
劝君莫谩栽荆棘，秦皇虚费驱山力。
英风一去更无言，白骨沈埋暮山碧。','',''),('quantangshi-43415','留赠偃师主人','無名氏','quantangshi','','卷44','孤城漏未残，徒侣拂征鞍。
洛北去愁远，淮南归梦阑。
晓灯回壁暗，晴雪卷帘寒。
更尽主人酒，出门行路难。','',''),('quantangshi-43416','长门','無名氏','quantangshi','','卷44','怅望黄金屋，恩衰似越逃。
花生针眼刺，月送剪肠刀。
地近欢娱远，天低雨露高。
时看回辇处，泪脸湿夭桃。','',''),('quantangshi-43417','宴李家宅','無名氏','quantangshi','','卷44','画屏深掩瑞云光，罗绮花飞白玉堂。
银榼酒倾鱼尾倒，金炉灰满鸭心香。
轻摇绿水青蛾歛，乱触红丝皓腕狂。
今日恩荣许同听，不辞沈醉一千觞。','',''),('quantangshi-43418','长信宫','無名氏','quantangshi','','卷44','细草侵堦乱碧鲜，宫门深锁绿杨天。
珠帘欲卷抬秋水，罗幌微开动冷烟。
风引漏声过枕上，月移花影到窗前。
独挑残烛魂堪断，却恨青蛾误少年。','',''),('quantangshi-43419','骊山感怀','無名氏','quantangshi','','卷44','武帝寻仙驾海游，禁门高闭水空流。
深宫带日年年色，翠柏凝烟夜夜愁。
鸾凤影沈归万古，歌钟声断梦千秋。
晚来惆怅无人会，云雨能飞傍玉楼。','',''),('quantangshi-43420','绝句','無名氏','quantangshi','','卷44','石沈辽海阔，劒别楚山长。
会合知无日，离心满夕阳。','',''),('quantangshi-43421','听唱鹧鸪','無名氏','quantangshi','','卷44','金谷歌传第一流，鹧鸪清怨碧云愁。
夜来省得曾闻处，万里月明湘水流。','',''),('quantangshi-43422','杂诗 一','無名氏','quantangshi','','卷44','劝君莫惜金缕衣，劝君须惜少年时。
有花堪折直须折，莫待无花空折枝。','',''),('quantangshi-43423','杂诗 二','無名氏','quantangshi','','卷44','青天无云月如烛，露泣梨花白如玉。
子规一夜啼到明，美人独在空房宿。','',''),('quantangshi-43424','杂诗 三','無名氏','quantangshi','','卷44','空赐罗衣不赐恩，一薰香后一销魂。
虽然舞袖何曾舞，常对春风裛泪痕。','',''),('quantangshi-43425','杂诗 四','無名氏','quantangshi','','卷44','不洗残妆凭绣牀，也同女伴绣鸳鸯。
回针刺到双飞处，忆着征夫泪数行。','',''),('quantangshi-43426','杂诗 五','無名氏','quantangshi','','卷44','眼想心思梦里惊，无人知我此时情。
不如池上鸳鸯鸟，双宿双飞过一生。','',''),('quantangshi-43427','杂诗 六','無名氏','quantangshi','','卷44','一去辽阳系梦魂，忽传征骑到中门。
纱窗不肯施红粉，徒遣萧郎问泪痕。','',''),('quantangshi-43428','杂诗 七','無名氏','quantangshi','','卷44','鸎啼露冷酒初醒，罨画楼西晓角鸣。
翠羽帐中人梦觉，宝钗斜坠枕函声。','',''),('quantangshi-43429','杂诗 八','無名氏','quantangshi','','卷44','行人南北分征路，流水东西接御沟。
终日坡前怨离别，谩名长乐是长愁。','',''),('quantangshi-43430','杂诗 九','無名氏','quantangshi','','卷44','偏倚绣床愁不起，双垂玉筯翠鬟低。
卷帘相待无消息，夜合花前日又西。','',''),('quantangshi-43431','杂诗 十','無名氏','quantangshi','','卷44','悔将泪眼向东开，特地愁从望里来。
三十六峯犹不见，况伊如燕这身材。','',''),('quantangshi-43432','杂诗 十一','無名氏','quantangshi','','卷44','满目笙歌一段空，万般离恨总随风。
多情为谢残阳意，与展晴霞片片红。','',''),('quantangshi-43433','杂诗 十二','無名氏','quantangshi','','卷44','两心不语暗知情，灯下裁缝月下行。
行到堦前知未睡，夜深闻放剪刀声。','',''),('quantangshi-43434','杂诗 十三','無名氏','quantangshi','','卷44','近寒食雨草萋萋，着麦苗风柳映堤。
早是有家归未得，杜鹃休向耳边啼。','',''),('quantangshi-43435','杂诗 十四','無名氏','quantangshi','','卷44','水纹珍簟思悠悠，千里佳期一夕休。
从此无心爱良夜，任他明月下西楼。','',''),('quantangshi-43436','杂诗 十五','無名氏','quantangshi','','卷44','数日相随两不忘，郎心如妾妾如郎。
出门便是东西路，把取红牋各断肠。','',''),('quantangshi-43437','杂诗 十六','無名氏','quantangshi','','卷44','无定河边暮角声，赫连台畔旅人情。
函关归路千余里，一夕秋风白发生。','',''),('quantangshi-43438','杂诗 十七','無名氏','quantangshi','','卷44','花落长川草色青，暮山重叠两冥冥。
逢春便觉飘蓬苦，今日分飞一涕零。','',''),('quantangshi-43439','杂诗 十八','無名氏','quantangshi','','卷44','洛阳才子隣箫恨，湘水佳人锦瑟愁。
今昔两成惆怅事，临邛春尽暮江流。','',''),('quantangshi-43440','杂诗 十九','無名氏','quantangshi','','卷44','浙江轻浪去悠悠，望海楼吹望海愁。
莫怪乡心随魄断，十年为客在他州。','',''),('quantangshi-43441','初过汉江','無名氏','quantangshi','','卷44','襄阳好向岘亭看，人物萧条值岁阑。
为报习家多置酒，夜来风雪过江寒。','',''),('quantangshi-43442','读庾信集','無名氏','quantangshi','','卷44','四朝十帝尽风流，建业长安两醉游。
惟有一篇杨柳曲，江南江北为君愁。','',''),('quantangshi-43443','题长乐驿壁','無名氏','quantangshi','','卷44','三十骅骝一烘尘，来时不锁杏园春。
杨花满地如飞雪，应有偷游曲水人。','',''),('quantangshi-43444','绝句','無名氏','quantangshi','','卷44','传闻天子访沈沦，万里怀书西入秦。
早知不用无媒客，恨别江南杨柳春。','',''),('quantangshi-43445','题取经诗','無名氏','quantangshi','','卷44','晋宋齐梁唐代间，高僧求法离长安。
去人成百归无十，后者安知前者难。
路远碧天唯冷结，沙河遮日力疲殚。
后贤如未谙斯旨，往往将经容易看。','',''),('quantangshi-43446','题水心寺水轩','無名氏','quantangshi','','卷44','分飞南渡春风晚，却返家林事业空。
无限离情似杨柳，万条垂向楚江东。','',''),('quantangshi-43447','王昭君','無名氏','quantangshi','','卷44','猗兰恩宠歇，昭阳幸御稀。
朝辞汉阙去，夕见胡尘飞。
寄信秦楼下，因书秋雁归。','',''),('quantangshi-43448','王昭君','無名氏','quantangshi','','卷44','一回望月一回悲，望月月移人不移。
何时得见汉朝使，为妾传书斩画师。','',''),('quantangshi-43449','粉牋题诗','無名氏','quantangshi','','卷44','三月江南花满枝，风轻帘幕燕争飞。
游人休惜夜秉烛，杨柳阴浓春欲归。','',''),('quantangshi-43450','咏美人骑马','無名氏','quantangshi','','卷44','骏马娇仍稳，春风灞岸晴。
促来金镫短，扶上玉人轻。
帽束云鬟乱，鞭笼翠袖明。','',''),('quantangshi-43451','六言诗','無名氏','quantangshi','','卷44','把酒留君听琴，那堪岁暮离心。
霜叶无风自落，秋天不雨多阴。
人愁荒村路远，马怯寒溪水深。','',''),('quantangshi-43452','胡笳曲','無名氏','quantangshi','','卷44','月明星稀霜满野，毡车夜宿阴山下。
汉家自失李将军，单于公然来牧马。','',''),('quantangshi-43453','桃源行送友人','無名氏','quantangshi','','卷44','武陵川径入幽遐，中有鸡犬秦人家，家傍流水多桃花。
桃花两边种来久，流水一道何时有？
垂条落蕊暗春风，夹岸芳菲至山口。
岁岁年年能寂寥，林下青苔日为厚。
时有仙鸟来衔花，曾无世人此携手。
可怜不知若为名，君往从之多所更。
古驿荒桥平路尽，崩湍怪石小溪行。
相见维舟登览处，红堤绿岸宛然成。
多君此去从仙隐，令人晚节悔营营。','',''),('quantangshi-43454','唐衢墓','無名氏','quantangshi','','卷44','京洛先生三尺坟，阴风惨惨土和云。
从来有感君皆哭，今日无君谁哭君。','',''),('quantangshi-43455','宫词','無名氏','quantangshi','','卷44','花萼楼前春正浓，蒙蒙柳絮舞晴空。
金钱掷罢娇无力，笑倚栏干屈曲中。','',''),('quantangshi-43456','抛球诗','無名氏','quantangshi','','卷44','侍宴黄昏未肯休，玉阶夜色月如流。
朝来自诧承恩最，笑倩傍人认绣球。','',''),('quantangshi-43457','艳歌','無名氏','quantangshi','','卷44','月里嫦娥不画眉，只将云雾作罗衣。
不知梦逐青鸾去，犹把花枝盖面归。','',''),('quantangshi-43458','杨柳枝','無名氏','quantangshi','','卷44','万里长江一带开，岸边杨柳几千栽。
锦帆未落西风起，惆怅龙舟去不回。','',''),('quantangshi-43459','河中石刻','無名氏','quantangshi','','卷44','雨滴空堦晓，无心换夕香。
井梧花落尽，一半在银床。','',''),('quantangshi-43460','古砚','無名氏','quantangshi','','卷44','癖性爱古物，终岁求不得。
昨朝得古砚，兰河滩之侧。
波涛所击触，背面生隟隙。
质状朴且丑，令人作不得。','',''),('quantangshi-43461','绝句','無名氏','quantangshi','','卷44','钓罢孤舟系苇梢，酒开新瓮鲊开包。
自从江浙为渔父，二十余年手不扠。','',''),('quantangshi-43462','题童氏画','無名氏','quantangshi','','卷44','林下材华虽可尚，笔端人物更清妍。
如何不出深闺里，能以丹青写外边。','',''),('quantangshi-43463','失题','無名氏','quantangshi','','卷44','春朝散微雨，庭树开芸绿。
上有怀春鸟，间关断复续。
谓言□野中，定是珠城曲。
我自牵时幸，以惭羁旅束。
尔下鸣幽林，来此将何欲。','',''),('quantangshi-43464','姜宣弹小胡笳引歌','無名氏','quantangshi','','卷44','雷氏金徽琴，王君宝重轻千金。
三峡流中将得来，明窗拂席幽匣开。
朱弦宛转盘凤足，骤击数声风雨回。
哀笳慢指董家本，姜宣得之妙思忖。
泛徽胡雁咽萧萧，绕指辘轳圆衮衮。
吞恨含情乍轻激，故国关山心历历。
潺湲疑是舞䴙鹈，砉騞如闻发鸣镝。
流宫变征渐幽咽，别鹤欲飞猨欲绝。
秋霜满树叶辞风，寒雏坠地乌啼血。
哀弦已罢春恨长，恨长何如怀我乡。
我乡安在长城窟，闻君肤奏心飘忽。
何时窄袖短貂裘，胭脂山下弯明月。','',''),('quantangshi-43465','罗浮山','無名氏','quantangshi','','卷44','四百余峯海上排，根连蓬岛荫天台。
百灵若为移中土，嵩华都为一小堆。','',''),('quantangshi-43466','汤周山','無名氏','quantangshi','','卷44','汤周二大仙，庐此得升天。
风俗因兴庙，春秋不记年。
锦云张紫盖，琴溜泻鸣泉。
丹竈犹存鼎，仙花发故园。','',''),('quantangshi-43467','永州舜庙诗','無名氏','quantangshi','','卷44','游湘有余怨，岂是圣人心。
行路猿啼古，祠宫梦草深。
素风传旧俗，异迹闭荒林。
巡狩去不返，烟云愁至今。
九嶷天一半，山尽海沈沈。','',''),('quantangshi-43468','绝句','無名氏','quantangshi','','卷44','绿杨阴转画桥斜，舟有笙歌岸有花。
尽日会稽山色里，蓬莱清浅水仙家。','',''),('quantangshi-43469','三学山盘陀石上刻诗','無名氏','quantangshi','','卷44','拔地山峦秀，排空殿阁斜。
云供数州雨，树献九天花。
夜月摩峰顶，秋钟彻海涯。
长松拂星汉，一一是仙槎。','',''),('quantangshi-43470','合水县玉泉石崖刻','無名氏','quantangshi','','卷44','山脉逗飞泉，泓澄傍岩石。
乱垂寒玉筱，碎洒珍珠滴。
澄波涵万象，明镜泻天色。
有时乘月来，赏咏还自适。','',''),('quantangshi-43471','纪游东观山','無名氏','quantangshi','','卷44','瑰奇恣搜讨，贝阙青瑶房。
才隘疑永巷，俄敞如华堂。
玉梁窈浮溪，琼户正当窗。
仙佛肖彷佛，钟鼓鍧击撞。
贔贔左顾龟，狺狺欲吠[尨]。
丹竈俨亡恙，芝田霭生香。
搏噬千怪聚，绚烂五色光。
更无一尘涴，但觉六月凉。
玲珑穿屡折，诘曲通三湘。
神鬼若剜刻，干坤真混茫。
入如深夜暗，出喜皦日光。
隔世惊瞬息，异境难揣量。','',''),('quantangshi-43472','题焚经台','無名氏','quantangshi','','卷44','门径萧萧长绿苔，一回登此一徘徊。
青牛谩说函关去，白马亲从印土来。
确实是非凭烈焰，要分真伪筑高台。
春风也解嫌狼籍，吹尽当年道教灰。','',''),('quantangshi-43473','日暮山河清','無名氏','quantangshi','','卷44','天高爽气晶，驰景忽西倾。
山列千重静，河流一带明。
想同金镜澈，宁让玉壶清。
纤翳无由出，浮埃不复生。
荣纡分汉苑，表里见秦城。
逸兴终难系，抽毫仰此情。','',''),('quantangshi-43474','秋日悬清光','無名氏','quantangshi','','卷44','寥廓凉天静，晶明白日秋。
圆光含万象，碎影人闲流。
迥与青冥合，遥同江甸浮。
昼阴殊众木，斜影下危楼。
宋玉登高怨，张衡望远愁。
余辉如可托，云路岂悠悠。','',''),('quantangshi-43475','落日山照曜','無名氏','quantangshi','','卷44','裴回空山下，晼晚残阳落。
圆影过峰峦，半规入林薄。
余光澈羣岫，乱彩分重壑。
石镜共澄明，岩光同照灼。
栖禽去杳杳，夕烟生漠漠。
此境谁复知，独怀谢康乐。','',''),('quantangshi-43476','月映清淮流','無名氏','quantangshi','','卷44','淮月秋偏静，含虚夜转明。
桂花窥镜发，蟾影映波生。
澹滟轮初上，裴回魄正盈。
遥塘分草树，近浦写山城。
桐柏流光逐，蠙珠濯景清。
孤舟方利涉，更喜照前程。','',''),('quantangshi-43477','寿星见','無名氏','quantangshi','','卷44','玄象今何应，时和政亦平。
祥为一人寿，色映九霄明。
皎洁垂银汉，光芒近斗城。
合规同月满，表瑞得天清。
甘露盈条降，祥烟向日生。
无如此嘉祉，率土荷秋成。','',''),('quantangshi-43478','华山庆云见','無名氏','quantangshi','','卷44','圣主祠名岳，高风发庆云。
金柯初缭绕，玉叶渐氛氲。
气色含珠日，光明吐翠雰。
依稀来鹤态，仿髴列仙羣。
万树流光影，千潭写锦文。
苍生忻有望，祥瑞在吾君。','',''),('quantangshi-43479','清风戒寒','無名氏','quantangshi','','卷44','萧飒清风至，悠然发思端。
入林翻别叶，绕树败红兰。
晓拂轻霜度，宵分远籁攒。
稍依帘隙静，徧觉坐隅寒。
乍逐惊蓬振，偏催急漏残。
遥知洞庭水，此夕起波澜。','',''),('quantangshi-43480','空水共澄鲜','無名氏','quantangshi','','卷44','悠然四望通，渺渺水无穷。
海鹤飞天际，烟林出镜中。
云消澄徧碧，霞起澹微红。
落日浮光满，遥山翠色同。
樵声喧竹屿，棹唱入莲藂。
远客舟中兴，烦襟暂一空。','',''),('quantangshi-43481','寒流聚细文','無名氏','quantangshi','','卷44','晓野方闲眺，横溪赏乱流。
寒文趋浦急，圆折逐烟浮。
不谓飘疎雨，非关浴远鸥。
观鱼鳞共细，间石影疑稠。
猎猎风泠夕，潺潺濑响秋。
仙槎如共泛，天汉适淹留。','',''),('quantangshi-43482','长安早春','無名氏','quantangshi','','卷44','杳霭三春色，先从帝里芳。
折杨犹恨短，测景已忻长。
莺和红楼乐，花连紫禁香。
跃鱼惊太液，佳气接温汤。
风送飞珂响，尘蒙翠辇光。
熙熙晴煦远，徒欲奉尧觞。','',''),('quantangshi-43483','嘉和合頴','無名氏','quantangshi','','卷44','天祚皇王德，神呈瑞谷嘉。
感时苗特秀，证道叶方华。
气转腾佳色，云披映早霞。
薰风浮合頴，湛露净祥花。
六穗垂兼倒，孤茎袅复斜。
影同唐叔献，称庆比周家。','',''),('quantangshi-43484','膏泽多丰年','無名氏','quantangshi','','卷44','帝德方多泽，莓莓井径同。
八方甘雨布，四远报年丰。
厫庆千厢在，山流万壑通。
候时勤稼穑，击壤乐农功。
畎亩人无惰，田庐岁不空。
何须忧伏腊，千载贺尧风。','',''),('quantangshi-43485','玉壶冰','無名氏','quantangshi','','卷44','玄律阴风劲，坚冰在玉壶。
暗中花更出，晓后色全无。
涸冱谁能伴，凄清讵可渝。
任圆空似璧，照物不成珠。
素质情方契，孤明道岂殊。
幽人若相比，还得咏生刍。','',''),('quantangshi-43486','望禁苑祥光','無名氏','quantangshi','','卷44','佳气生天苑，葱茏几效祥。
树遥三殿际，日映九城傍。
山雾宁同色，卿云未可彰。
眺汾疑鼎气，临渭想荣光。
当并舂陵发，应开圣历长。
微臣时一望，短羽欲飞翔。','',''),('quantangshi-43487','晨光动翠华','無名氏','quantangshi','','卷44','早朝开紫殿，佳气逐清晨。
北阙华旌在，东方曙景新。
影连香雾合，光媚庆云频。
鸟羽飘初定，龙文照转真。
直疑冠佩入，长爱冕旒亲。
摇动祥云里，朝朝映侍臣。','',''),('quantangshi-43488','观南郊回仗','無名氏','quantangshi','','卷44','传警千门寂，南郊彩仗回。
但惊龙再见，谁识日双开。
德泽施云雨，恩光变烬灰。
阅兵貔武振，听乐凤凰来。
候刻移宸辇，尊时集观台。
多慙远臣贱，不得礼容陪。','',''),('quantangshi-43489','谒见日将至双阙','無名氏','quantangshi','','卷44','晓色临双阙，微臣礼位陪。
远惊龙凤覩，谁识冕旒开。
蔼蔼千年盛，颙颙万国来。
天文标日月，时令布云雷。
迥出黄金殿，全分白玉台。
雕虫意何取，瞻恋不知回。','',''),('quantangshi-43490','尚书郎上直闻春漏','無名氏','quantangshi','','卷44','地即尚书省，人惟鸳鹭行。
审时传玉漏，直夜递星郎。
历历闻仙暑，泠泠出建章。
自空来断续，随月散凄锵。
物静知声远，寒轻觉夜长。
听余残月落，曙色满东方。','',''),('quantangshi-43491','华清宫望幸','無名氏','quantangshi','','卷44','骊岫接新丰，岧嶤驾碧空。
凿山开祕殿，隐雾蔽仙宫。
绛阙犹栖凤，雕梁尚带虹。
温泉曾浴日，华馆旧迎风。
肃穆瞻云辇，深沈闭绮栊。
东郊望幸处，瑞气霭蒙蒙。','',''),('quantangshi-43492','御题国子监','無名氏','quantangshi','','卷44','宸翰符玄造，荣题国子门。
笔锋回日月，字势动干坤。
檐下云光绕，梁间鹊影翻。
张英圣莫拟，索靖妙难言。
为着盘龙迹，能彰舞凤蹲。
更随垂露像，常以沐皇恩。','',''),('quantangshi-43493','郊坛听雅乐','無名氏','quantangshi','','卷44','泰坛恭祀事，彩仗下寒坰。
展礼陈嘉乐，斋心动众灵。
韵长飘更远，曲度静宜听。
泛响何清越，随风散杳冥。
彻悬和气聚，旋退晓山青。
本自钧天降，还疑列洞庭。','',''),('quantangshi-43494','册上公太常奏雅乐','無名氏','quantangshi','','卷44','司乐陈金石，逶迤引上公。
奏音人语绝，清韵佩声通。
应律烟云改，来仪鸟兽同。
得贤因举颂，修礼便观风。
圣寿三称内，天欢九奏中。
寂寥高曲尽，犹自满宸聪。','',''),('quantangshi-43495','听霜钟','無名氏','quantangshi','','卷44','渺渺飞霜夜，寥寥远岫钟。
出云疑断续，入户乍舂容。
度枕频惊梦，随风几韵松。
悠扬来不已，杳霭去何从。
仿髴烟岚隔，依俙岩峤重。
此时聊一听，余响绕千峰。','',''),('quantangshi-43496','听霜钟','無名氏','quantangshi','','卷44','寥亮来丰岭，分明辨古钟。
应霜如自击，中节每相从。
静听非闲扣，潜应蕴圣踪。
风间时断续，云外更舂容。
虚警和清籁，雄鸣隔乱峰。
因之论知己，感激更难逢。','',''),('quantangshi-43497','笙磬同音','無名氏','quantangshi','','卷44','笙磬闻何处，凄锵宛在东。
激扬音自彻，高下曲宜同。
历历俱盈耳，泠泠递散空。
兽因繁奏舞，人感至和通。
讵间洪纤韵，能齐搏拊功。
四悬今尽美，一听辨移风。','',''),('quantangshi-43498','玉巵无当','無名氏','quantangshi','','卷44','共惜连城宝，翻为无当巵。
讵慙君子贵，深讶拙工隳。
泛蚁功全少，如虹色不移。
可怜珍砾石，何计辨糟醨。
江海诚难满，盘筵莫妄施。
纵乖斟酌意，犹得奉光仪。','',''),('quantangshi-43499','府试古镜','無名氏','quantangshi','','卷44','旧是秦时镜，今来古匣中。
龙盘初挂月，凤舞欲生风。
石黛曾留殿，朱光适在宫。
应祥知道泰，监物觉神通。
肝胆诚难隐，妍媸信易穷。
幸居君子室，长愿免尘蒙。','',''),('quantangshi-43500','焚裘','無名氏','quantangshi','','卷44','今主临前殿，惩奢爇异裘。
忽看阳焰发，如覩吉光流。
丽彩辞宸扆，余香在御楼。
火随余烬灭，气逐远烟浮。
素朴回风变，凋华逐志休。
永垂恭俭德，千古揖皇猷。','',''),('quantangshi-43501','送薛大夫和蕃','無名氏','quantangshi','','卷44','戎王归汉命，魏绛谕皇恩。
旌斾辞双阙，风沙上五原。
往途遵塞道，出祖耀都门。
策令天文盛，宣威使者尊。
澄波望四海，入贡伫诸蕃。
秋杪迎回骑，无劳枉梦魂。','',''),('quantangshi-43502','观劒南献捷','無名氏','quantangshi','','卷44','遐圻新破虏，名将旧登坛。
戎馘西南至，毡裘长幼观。
边疆氛已息，矛戟血犹残。
紫陌欢声动，丹墀喜气盘。
唐虞方德易，卫霍比功难。
共覩俘囚入，赓歌万国安。','',''),('quantangshi-43503','云母屏风隔坐','無名氏','quantangshi','','卷44','彩障成云母，丹墀隔上公。
才彰二纪盛，荣播一朝同。
近玉初齐白，临花乍散红。
凝姿分缥缈，转佩辨𤫩珑。
意惬恩偏厚，名新宠更崇。
谁知历千古，犹自仰清风。','',''),('quantangshi-43504','白受采','無名氏','quantangshi','','卷44','皛皛金方色，迁移妙不穷。
轻衣尘迹化，净壁缋文通。
沙变蓝溪渍，冰渝墨沼空。
似甘言受和，由礼学资忠。
皎洁形无定，玄黄用莫同。
素心如可教，愿染古人风。','',''),('quantangshi-43505','人不易知','無名氏','quantangshi','','卷44','权衡谅匪易，愚智信难移。
九德皆殊进，三端岂易施。
同称昆岫宝，共握桂林枝。
郑鼠今奚别，齐竽或滥吹。
瑶台有光鉴，屡照不应疲。
片善当无掩，先鸣贵在斯。
龙门峻且极，骥足庶来驰。
太息李元礼，期君幸一知。','',''),('quantangshi-43506','晦日同志昆明池泛舟','無名氏','quantangshi','','卷44','灵沼疑河汉，萧条见斗牛。
烟生知岸近，水净觉天秋。
落月低前树，清辉满去舟。
兴因孤屿起，心为白苹留。
晓吹兼渔笛，闲云伴客愁。
龙津如可上，长啸且乘流。','',''),('quantangshi-43507','礼闱阶前春草生','無名氏','quantangshi','','卷44','河畔虽同色，南宫淑景先。
微开曳履处，常对讲经前。
得地风尘隔，依林雨露偏。
已逢霜候改，初寄日华妍。
影与丛兰杂，荣将众卉连。
哲人如不剃，生意在芳年。','',''),('quantangshi-43508','秋风生桂枝','無名氏','quantangshi','','卷44','寒桂秋风动，萧萧自一枝。
方将击林变，不假舞松移。
散翠幽花落，摇青密叶离。
哀猨惊助褭，花露滴争垂。
遗韵连波聚，流音万木随。
常闻小山里，逋客最先知。','',''),('quantangshi-43509','幽人折芳桂','無名氏','quantangshi','','卷44','厚地生芳桂，遥林耸干长。
叶开风里色，花吐月中光。
曙鸟啼余翠，幽人爱早芳。
动时垂露滴，攀处拂衣香。
古调声犹苦，孤高力自强。
一枝终是折，荣耀在东堂。','',''),('quantangshi-43510','霜菊','無名氏','quantangshi','','卷44','秋尽北风去，律移寒气肃。
淅沥降繁霜，离披委残菊。
华滋尚照灼，幽气含纷郁。
的的冒空园，萋萋被幽谷。
骚人有遗咏，陶令曾盈掬。
傥使怀袖中，犹堪袭余馥。','',''),('quantangshi-43511','金谷园花发怀古','無名氏','quantangshi','','卷44','春风生梓泽，迟景映花林。
欲问当时事，因伤此日心。
繁华人已殁，桃李意何深。
涧咽歌声在，云归盖影沈。
地形同万古，笑价失千金。
遗迹应无限，芳菲不可寻。','',''),('quantangshi-43512','骊龙','無名氏','quantangshi','','卷44','有美为鳞族，潜蟠得所从。
标奇初韫宝，表智即称龙。
大壑长千里，深泉固九重。
奋髯云乍起，矫首浪还冲。
荀氏传高誉，庄生冀绝踪。
仍知流泪在，何幸此相逢。','',''),('quantangshi-43513','鹤鸣九臯','無名氏','quantangshi','','卷44','胎化呈仙质，长鸣在九臯。
排空散清唳，映日委霜毛。
万里思寥廓，千山望郁陶。
香凝光不见，风积韵弥高。
凤侣攀何及，鸡羣思忽劳。
升天如有应，飞舞出蓬蒿。','',''),('quantangshi-43514','霜隼下晴臯','無名氏','quantangshi','','卷44','九臯霜气劲，翔隼下初晴。
风动闲云卷，星驰白草平。
棱棱方厉疾，肃肃自纵横。
掠地秋毫迥，投身逸翮轻。
高墉全失影，逐雀作飞声。
薄暮寒郊外，悠悠万里情。','',''),('quantangshi-43515','河鲤登龙门','無名氏','quantangshi','','卷44','年久还求变，今来有所从。
得名当是鲤，无点可成龙。
备历艰难徧，因期造化容。
泥沙宁不阻，钓饵莫相逢。
击浪因成势，纤鳞莫继踪。
若令摇尾去，雨露此时浓。','',''),('quantangshi-43516','改九子山为九华山联句','李白','quantangshi','','卷44','妙有分二气，灵山开九华。
层标遏迟日，半壁明朝霞。
积雪曜阴壑，飞流歕阳崖。
青莹玉树色，缥缈羽人家。','',''),('quantangshi-43517','夏夜李尚书筵送宇文石首赴县联句','杜甫','quantangshi','','卷44','爱客尚书贵，之官宅相贤。
酒香倾坐侧，帆影驻江边。
翟表郎官瑞，凫看令宰仙。
雨稀云叶断，夜久烛花偏。
数语敧纱帽，高文掷彩笺。
兴饶行处乐，离惜醉中眠。
单父长多暇，河阳实少年。
客居逢自出，为别几凄然。','',''),('quantangshi-43518','登岘山观李左相石尊联句','顏真卿','quantangshi','','卷44','李公登饮处，因石为洼尊。
人事岁年改，岘山今古存。
榛芜掩前迹，苔藓余旧痕。
叔子尚遗德，山公此回轩。
维舟陪高兴，感昔情弥敦。
蔼蔼贤哲事，依依离别言。
岖嵚横道周，迢遰连山根。
余烈暧林野，众芳揖兰荪。
德晖映岩足，胜赏延高原。
远水明匹练，因晴见吴门。
陪游追盛美，揆德欣讨论。
器有成形用，功资造化元。
流霞方泔淡，别鹤遽翩飜。
旧规倾逸赏，新兴丽初暾。
醉后接㒿倒，归时驺骑喧。
迟回向遗迹，离别益伤魂。
览事古兴属，送人归思繁。
怀贤久徂谢，赠远空攀援。
八座钦懿躅，高名播干坤。
松深引闲步，葛弱供险扪。
花气酒中馥，云华衣上屯。
森沈列湖树，牢落望郊园。
白日半岩岫，清风满丘樊。
旌麾间翠幄，箫鼓来朱轓。
闲路蹑云影，清心澄水源。
萍连浦中屿，竹绕山下村。
景落全溪暗，烟凝半岭昏。
去日往如复，换年凉代温。
登临继风骚，义激旧府恩。','',''),('quantangshi-43519','水堂送诸文士戏赠潘丞联句','顏真卿','quantangshi','','卷44','居人未可散，上客须留着。
莫唱阿嚲回，应云夜半乐。
诗教刻烛赋，酒任连盘酌。
从他白眼看，终恋青山郭。
林栖非姓许，寺住那名约。
会异永和年，才同建安作。
何烦问更漏，但遣催弦索。
共说长句能，皆言早归恶。
那知殊出处，还得同笑谑。
雅韵虽暂欢，禅心肯抛却。
一宿同高会，几人归下若。
帘开北陆风，烛焯南枝鹊。
文场苦叨窃，钓渚甘漂泊。
弱质幸见容，菲才诚重诺。','',''),('quantangshi-43520','与耿湋水亭咏风联句','顏真卿','quantangshi','','卷44','清风何处起，拂槛复萦洲。
回入飘华幕，轻来叠晚流。
桃竹今已展，羽翣且从收。
经竹吹弥切，过松韵更幽。
直散青苹末，偏随白浪头。
山山催雨过，浦浦发行舟。
动树蝉争噪，开帘客罢愁。
度弦方解愠，临水已迎秋。
凉为开襟至，清因作颂留。
周回随远梦，骚屑满离忧。
岂独销繁暑，偏能入迥楼。
王风今若此，谁不荷明休。','',''),('quantangshi-43521','又溪馆听蝉联句','顏真卿','quantangshi','','卷44','高树多凉吹，疎蝉足断声。
已催居客感，更使别人惊。
晚夏犹知急，新秋别有情。
危湍和不似，细管学难成。
当斅附金重，无贪曜火明。
青松四面落，白发一重生。
向夕音弥厉，迎风翼更轻。
单嘶出迥树，余响思空城。
嘒唳松间坐，萧寥竹里行。
如何长饮露，高洁未能名。','',''),('quantangshi-43522','送耿湋拾遗联句','顏真卿','quantangshi','','卷44','尧舜逢明主，严徐得侍臣。
分行接三事，高兴柏梁新。
楚国千山道，秦城万里人。
镜中看齿发，河上有烟尘。
望阙飞青翰，朝天忆紫宸。
喜来欢宴洽，愁去咏歌频。
顾盼情非一，睽携处亦频。
吴兴贤太守，临水最殷勤。','',''),('quantangshi-43523','五言月夜啜茶联句','顏真卿','quantangshi','','卷44','泛花邀坐客，代饮引情言。
醒酒宜华席，留僧想独园。
不须攀月桂，何假树庭萱。
御史秋风劲，尚书北斗尊。
流华净肌骨，疏瀹涤心原。
不似春醪醉，何辞绿菽繁。
素瓷传静夜，芳气满闲轩。','',''),('quantangshi-43524','五言夜宴咏灯联句','顏真卿','quantangshi','','卷44','桂酒牵诗兴，兰釭照客情。
讵慙珠乘朗，不让月轮明。
破暗光初白，浮云色转清。
带花疑在树，比燎欲分庭。
顾己慙微照，开帘识近汀。','',''),('quantangshi-43525','三言喜皇甫侍御见过南楼玩月','顏真卿','quantangshi','','卷44','喜嘉客，辟前轩。
天月净，水云昏。
雁声苦，蟾影寒。
闻裛浥，滴檀栾。
欢宴处，江湖间。
卷翠幕，吟嘉句。
恨清光，留不住。
高驾动，清角催。
惜归去，重裴回。
露欲曦，客将醉。
犹宛转，照深意。','',''),('quantangshi-43526','七言重联句','顏真卿','quantangshi','','卷44','顷持宪简推高步，独占诗流横素波。
不是中情深惠好，谁能千里远经过。
诗书宛似陪康乐，少长还同宴永和。
夜酌此时看碾玉，晨趋几日重鸣珂。
万井更深空寂寞，千方雾起隐嵯峨。
荧荧远火分渔浦，历历寒枝露鸟窠。
汉朝旧学君公隐，鲁国今从弟子科。
只自倾心慙煦濡，何曾将口恨蹉跎。
独赏谢吟山照耀，共知殷叹树婆娑。
华毂苦嫌云路隔，衲衣长向雪峰何。','',''),('quantangshi-43527','五言送李侍御联句','顏真卿','quantangshi','','卷44','吾友驻行轮，迟迟惜上春。
东西出饯路，惆怅独归人。
欢会期他日，驱驰恨此身。
须知贡公望，从此愿相因。','',''),('quantangshi-43528','五言翫初月重游联句','顏真卿','quantangshi','','卷44','春溪与岸平，初月出溪明。
璧彩寒仍洁，金波夜转清。
孤光远近满，练色往来轻。
望望随兰棹，依依出柳城。','',''),('quantangshi-43529','五言重送横飞联句','顏真卿','quantangshi','','卷44','春田草未齐，春水满长溪。
出饯风初暖，攀光日渐西。
归期江上远，别思月中迷。','',''),('quantangshi-43530','五言夜集联句','顏真卿','quantangshi','','卷44','寒花护月色，坠叶占风音。
兹夕无尘虑，高云共片心。','',''),('quantangshi-43531','三言拟五杂组联句','顏真卿','quantangshi','','卷44','五杂组，盘上葅。
往复还，头嬾梳。
不得已，罾里鱼。
五杂组，郊外芜。
往复还，枥上驹。
不得已，谷中愚。
五杂组，绣与锦。
往复还，兴又寝。
不得已，病伏枕。
五杂组，酒与肉。
往复还，东篱菊。
不得已，醉便宿。
五杂组，闤闠间。
往复还，门上关。
不得已，鬓毛斑。
五杂组，绣纹线。
往复还，春来燕。
不得已，入征战。','',''),('quantangshi-43532','三言重拟五杂组联句','顏真卿','quantangshi','','卷44','五杂组，四豪客。
往复还，阡与陌。
不得已，长沙谪。
五杂组，五辛盘。
往复还，马上鞍。
不得已，左降官。
五杂组，甘咸醋。
往复还，乌与兔。
不得已，韶光度。
五杂组，五色丝。
往复还，回文诗。
不得已，失喜期。','',''),('quantangshi-43533','七言大言联句','顏真卿','quantangshi','','卷44','高歌阆风步瀛洲，燂鹏爚鲲餐未休。
四方上下无外头，一啜顿涸沧溟流。','',''),('quantangshi-43534','七言小言联句','顏真卿','quantangshi','','卷44','长路迢遥吞吐丝，蟭螟蚊睫察难知。','',''),('quantangshi-43535','七言乐语联句','顏真卿','quantangshi','','卷44','苦河既济真僧喜，新知满座笑相视。
戍客归来见妻子，学生放假偷向市。','',''),('quantangshi-43536','七言嚵语联句','顏真卿','quantangshi','','卷44','拈䭔舐指不知休，欲炙侍立涎交流。
过屠大嚼肯知羞，食店门外强淹留。','',''),('quantangshi-43537','七言滑语联句','顏真卿','quantangshi','','卷44','雨里下山蹋榆皮，莓苔石桥步难移。
芜荑酱醋吃煮葵，缝靴蜡线油涂锥。
急逢龙背须且骑。','',''),('quantangshi-43538','七言醉语联句','顏真卿','quantangshi','','卷44','逢糟遇麯便酩酊，覆车坠马皆不醒。
倒着接㒿发垂领，狂心乱语无人竝。','',''),('quantangshi-43539','建元寺昼公与崔秀才见过联句与郑奉礼部同作','皇甫曾','quantangshi','','卷44','人闲宜岁晚，道者访幽期。
独与寒山别，行当暮雪时。
柏台辞汉主，竹寺寄潜师。
荷策知君待，开门笑我迟。
暮阶县雨足，寒吹绕松枝。
理辩尘心妄，经分梵字疑。
久承黄纸诏，曾赋碧云诗。
然诺惊相许，风流话所思。
筌忘心已默，磬发夜何其。
愿结求羊侣，名山从所之。','',''),('quantangshi-43540','建元寺西院寄李员外纵联句','皇甫曾','quantangshi','','卷44','寄隐霜台客，相思粉署人。
诚知阡陌近，无奈别离频。
夜色迷双树，钟声警四邻。
散才徒仰鲍，归梦远知秦。
雨带清笳发，花惊夕漏春。
招摇随步锡，仿髴听行轮。
要路推高足，空林寄一身。
盛名知独擅，良会忆相亲。
稍涤心中垢，都遗陌上尘。
今宵此堂集，何事少遗民。','',''),('quantangshi-43541','中元日鲍端公宅遇吴天师联句','嚴維','quantangshi','','卷44','道流为柱史，教戒下真仙。
共契中元会，初修内景篇。
游方依地僻，卜室喜墙连。
宝笥开金箓，华池漱玉泉。
怪龙随羽翼，青节降云烟。
昔去遗丹竈，今来变海田。
养形奔二景，炼骨度千年。
骑竹投陂里，携壶挂牖边。
洞中尝入静，河上旧谈玄。
伊洛笙歌远，蓬壶日月偏。
青骡蓟训引，白犬伯阳牵。
法受相君后，心存象帝先。
道成能缩地，功满欲升天。
何意迷孤性，含情恋数贤。','',''),('quantangshi-43542','酒语联句各分一字','嚴維','quantangshi','','卷44','山简酣歌倒接㒿，看朱成碧无所知。
耳鸣目眩驷马驰，口称童羖腹鸱夷。
兀然落帽灌酒巵，太常吏部相对时。
藉糟枕麴浮酒池，瓮间篱下卧不移。
叫呼不应无事悲，千日一醒知是谁。
左倾右倒人避之。','',''),('quantangshi-43543','一字至九字诗联句','嚴維','quantangshi','','卷44','东，西。
步月，寻溪。
鸟已宿，猨又啼。
狂流碍石，迸笋穿磎。
望望人烟远，行行萝径迷。
探题只应尽墨，持赠更欲封泥。
松下流时何岁月，云中幽处屡攀跻。
乘兴不知山路远近，缘情莫问日过高低。
静听林下潺潺足湍濑，厌问城中喧喧多鼓鼙。','',''),('quantangshi-43544','宣上人病中相寻联句','李益','quantangshi','','卷44','策杖迎诗客，归房理病身。
闲收无效药，徧寄有情人。
草木分千品，方书问六陈。
还知一室内，我尔即天亲。','',''),('quantangshi-43545','八月十五夜宣上人独游安国寺山庭院步人迟明将至因话昨宵乘兴联句','李益','quantangshi','','卷44','九重城接天花界，三五秋生一夜风。
行听漏声云散后，遥闻天语月明中。
含凉阁迥通仙掖，承露盘高出上宫。
谁问独愁门外客，清谈不与此宵同。','',''),('quantangshi-43546','重阳夜集兰陵居与宣上人联句','李益','quantangshi','','卷44','蟋蟀催寒服，茱萸滴露房。
酒巡明刻烛，篱菊暗寻芳。
新月和秋露，繁星混夜霜。
登高今夕事，九九是天长。','',''),('quantangshi-43547','与宣供奉携瘿尊归杏溪园联句','李益','quantangshi','','卷44','千畦抱瓮园，一酌瘿尊酒。
唯有沃洲僧，时过杏溪叟。
追欢君适性，独饮我空口。
儒释事虽殊，文章意多偶。','',''),('quantangshi-43548','兰陵僻居联句','李益','quantangshi','','卷44','潘岳闲居赋，陶潜独酌谣。
二贤成往事，三径是今朝。
生幸逢唐运，昌时奉帝尧。
进思谐启沃，退混即渔樵。
蠹简封延阁，雕阑閟上霄。
相从清旷地，秋露挹兰苕。','',''),('quantangshi-43549','天津桥南山中各题一句','李益','quantangshi','','卷44','野坐分苔席，山行绕菊丛。
云衣惹不破，秋色望来空。','',''),('quantangshi-43550','红楼下联句','李益','quantangshi','','卷44','佛刹接重城，红楼切太清。
紫云连照耀，丹槛郁峥嵘。
榱栋烟虹入，轩窗日月平。
参差五陵晚，分背八川明。
松韵风初过，莲陂浪欲倾。
敬瞻疑涌见，围绕学无生。','',''),('quantangshi-43551','赋应门照绿苔','李益','quantangshi','','卷44','宫阙何年月，应门何岁苔。
清光一以照，白露共裴回。
珠履久行绝，玉房重未开。
妾心正如此，昭阳歌吹来。','',''),('quantangshi-43552','寄司空曙李端联句','耿湋','quantangshi','','卷44','长安一分首，万里隔烟波。
海上青山暮，天涯白发多。
寻僧因看竹，访道或求鹅。
云树无猨鸟，阴崖足薜萝。
醉中留越客，兴里眄庭柯。
黄叶身仍逐，丹霄背未摩。
别愁连旦暮，归梦绕关河。
高柳寒蝉对，空阶夜雨和。
年华空荏苒，名宦转蹉跎。
南陌东城路，春来几度过。','',''),('quantangshi-43553','连句多暇赠陆三山人','耿湋','quantangshi','','卷44','一生为墨客，几世作茶仙。
喜是攀阑者，慙非负鼎贤。
禁门闻曙漏，顾渚入晨烟。
拜井孤城里，携笼万壑前。
闲喧悲异趣，语默取同年。
历落惊相偶，衰羸猥见怜。
诗书闻讲诵，文雅接兰荃。
未敢重芳席，焉能弄彩笺。
黑池流研水，径石涩苔钱。
何事亲香案，无端狎钓船。
野中求逸礼，江上访遗编。
莫发搜歌意，予心或不然。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-43554','道州春日感兴','李景儉','quantangshi','','卷44','始见花满枝，又看花满地。
且持增气酒，莫滴伤心泪。
深诚长郁结，芳晨自妍媚。
啸歌聊永日，谁知此时意。','',''),('quantangshi-43555','中秋夜听歌联句','武元衡','quantangshi','','卷44','此夕来奔月，何时去上天。
云鬟方自照，玉腕更呈鲜。
燕婉人间意，飘颻物外缘。
诗裁明月扇，歌索想夫怜。
暗染荀香久，长随楚梦偏。
会当来彩凤，仿髴逐神仙。','',''),('quantangshi-43556','春池泛舟联句','裴度','quantangshi','','卷44','凤池新雨后，池上好风光。
取酒愁春尽，留宾喜日长。
柳丝迎画舸，水镜写雕梁。
潭洞迷仙府，烟霞认醉乡。
莺声随笑语，竹色入壶觞。
晚景含澄澈，时芳得艳阳。
飞凫拂轻浪，绿柳暗回塘。
逸韵追安石，高居胜辟彊。
杯停新令举，诗动彩牋忙。
顾谓同来客，欢游不可忘。','',''),('quantangshi-43557','西池落泉联句','裴度','quantangshi','','卷44','东阁听泉落，能令野兴多。
散时犹带沫，淙处即跳波。
偏洗磷磷石，还惊泛泛鹅。
色清尘不染，光白月相和。
喷雪萦松竹，攒珠溅芰荷。
对吟时合响，触树更摇柯。
照圃红分药，侵阶绿浸莎。
日斜车马散，余韵逐鸣珂。','',''),('quantangshi-43558','首夏犹清和联句','裴度','quantangshi','','卷44','记得谢家诗，清和即此时。
余花数种在，密叶几重垂。
芳谢人人惜，阴成处处宜。
水萍争点缀，梁燕共追随。
乱蝶怜疎蘂，残莺恋好枝。
草香殊未歇，云势渐多奇。
单服初宁体，新篁已出篱。
与春为别近，觉日转行迟。
绕树风光少，侵阶苔藓滋。
惟思奉欢乐，长得在西池。','',''),('quantangshi-43559','蔷薇花联句','裴度','quantangshi','','卷44','似锦如霞色，连春接夏开。
波红分影入，风好带香来。
得地依东阁，当阶奉上台。
浅深皆有态，次第暗相催。
满地愁英落，缘堤惜棹回。
芳浓濡雨露，明丽隔尘埃。
似着胭脂染，如经巧妇裁。
奈花无别计，只有酒残杯。','',''),('quantangshi-43560','喜遇刘二十八偶书两韵联句','裴度','quantangshi','','卷44','病来佳兴少，老去旧游稀。
笑语纵横作，杯觞络绎飞。
清谈如水玉，逸韵贯珠玑。
高位当金铉，虚怀似布衣。
已容狂取乐，仍任醉忘机。
舍眷将何适，留欢便是归。
凤仪常欲附，蚊力自知微。
愿假尊罍末，膺门自此依。','',''),('quantangshi-43561','刘二十八自汝赴左冯涂经洛中相见联句','裴度','quantangshi','','卷44','不归丹掖去，铜竹漫云云。
唯喜因过我，须知未贺君。
诗闻安石咏，香见令公熏。
欲首函关路，来披缑岭云。
貂蝉公独步，鸳鹭我同羣。
插羽先飞酒，交锋便战文。
镇嵩知表德，定鼎为铭勋。
顾鄙容商洛，征欢候汝坟。
频年多谑浪，此夕任喧纷。
故态犹应在，行期未要闻。
游藩荣已久，捧袂惜将分。
讵厌杯行疾，唯愁日向曛。
穷阴初莽苍，离思渐氤氲。
残雪午桥岸，斜阳伊水濆。
上谟尊右掖，全略静东军。
万顷徒称量，沧溟讵有垠。','',''),('quantangshi-43562','度自到洛中与乐天为文酒之会时时构咏乐不可支则慨然共忆梦得而梦得亦分司至止欢惬可知因为联句','裴度','quantangshi','','卷44','成周文酒会，吾友胜邹枚。
唯忆刘夫子，而今又到来。
欲迎先倒屣，亦坐便倾杯。
饮许伯伦右，诗推公干才。
久曾聆郢唱，重喜上燕台。
昼话墙阴转，宵欢斗柄回。
新声还共听，故态复相咍。
遇物皆先赏，从花半未开。
起时乌帽侧，散处玉山颓。
墨客喧东阁，文星犯上台。
咏吟君称首，疎放我为魁。
忆戴何劳访，留髠不用猜。
奉觞承麴糵，落笔捧琼瑰。
醉弁无妨侧，词锋不可摧。
水轩看翡翠，石径践莓苔。
童子能骑竹，佳人解咏梅。
洛中三可矣，邺下七悠哉。
自向风光急，不须弦管催。
乐观鱼踊跃，闲爱鹤裴回。
烟柳青凝黛，波萍绿拨醅。
春榆初改火，律管又飞灰。
红药多迟发，碧松宜乱栽。
马嘶驼陌上，鷁泛凤城隈。
色色时堪惜，些些病莫推。
涸流寻轧轧，余刃转恢恢。
从此知心伏，无因敢自媒。
室随亲客入，席许旧寮陪。
逸兴嵇将阮，交情陈与雷。
洪炉思哲匠，大厦要羣材。
他日登龙路，应知免曝鳃。','',''),('quantangshi-43563','宴兴化池亭送白二十二东归联句','裴度','quantangshi','','卷44','东洛言归去，西园告别来。
白头青眼客，池上手中杯。
离瑟殷勤奏，仙舟委曲回。
征轮今欲动，宾阁为谁开。
坐弄琉璃水，行登绿缛堆。
花低妆照影，萍散酒吹醅。
岸荫新抽竹，亭香欲变梅。
随游多笑傲，遇胜且裴回。
澄澈连天镜，潺湲出地雷。
林塘难共赏，鞍马莫相催。
信及鱼还乐，机忘鸟不猜。
晚晴槐起露，新雨石添苔。
拟作云泥别，尤思顷刻陪。
歌停珠贯断，饮罢玉峰颓。
虽有逍遥志，其如磊落才。
会当重入用，此去肯悠哉。','',''),('quantangshi-43564','西池送白二十二东归兼寄令狐相公联句','裴度','quantangshi','','卷44','促坐宴回塘，送君归洛阳。
彼都留上宰，为我说中肠。
威凤池边别，冥鸿天际翔。
披云见居守，望日拜封章。
春尽年华少，舟通景气长。
送行欢共惜，寄远意难忘。
东道瞻轩盖，西园醉羽觞。
谢公深眷眄，商皓信辉光。
旧德推三友，新篇代八行。','',''),('quantangshi-43565','杏园联句','李絳','quantangshi','','卷44','杏园千树欲随风，一醉同人此暂同。
老态忽忘丝管里，衰颜宜解酒杯中。
曲江日暮残红在，翰苑年深旧事空。
二十四年流落者，故人相引到花丛。','',''),('quantangshi-43566','花下醉中联句','李絳','quantangshi','','卷44','共醉风光地，花飞落酒杯。
残春犹可赏，晚景莫相催。
酒幸年年有，花应岁岁开。
且当金韵掷，莫遣玉山颓。
高会弥堪惜，良时不易陪。
谁能拉花住，争换得春回。
我辈寻常有，佳人早晚来。
寄言三相府，欲散且裴回。','',''),('quantangshi-43567','乐天是月长斋鄙夫此时愁卧里闾非远云雾难披因以寄怀遂为联句所期解闷焉敢惊禅','劉禹錫','quantangshi','','卷44','五月长斋月，文心苦行心。
兰葱不入户，薝卜自成林。
护戒先辞酒，嫌喧亦彻琴。
尘埃宾位静，香火道场深。
我静驯狂象，餐余施众禽。
定知于佛佞，岂复向书淫。
阑药凋红艳，庭槐换绿阴。
风光徒满目，云雾未披襟。
树为清凉倚，池因盥漱临。
苹芳遭燕拂，莲坼待蠭寻。
舍下环流水，窗中列远岑。
苔斑钱剥落，石怪玉嵚岑。
鹊顶迎秋秃，莺喉入夏瘖。
绿杨垂嫩色，綖棘露长针。
散秩身犹幸，趋朝力不任。
官将方共拙，年与病交侵。
徇乐非时选，忘机似陆沈。
鉴容称四皓，扪腹有三壬。
携手慙连璧，同心许断金。
紫芝虽继唱，白雪少知音。
忆罢吴门守，相逢楚水浔。
舟中频曲宴，夜后各加斟。
浊酒销残漏，弦声间远砧。
酡颜舞长袖，密坐接华簪。
持论峰峦峻，战文矛戟森。
笑言诚莫逆，造次必相箴。
往事应如昨，余欢迄至今。
迎君常倒屣，访我辄携衾。
阴魄初离毕，阳光正在参。
待公休一食，纵饮共狂吟。','',''),('quantangshi-43568','秋霖即事联句三十韵','白居易','quantangshi','','卷44','萧索穷秋月，苍茫苦雨天。
泄云生栋上，行潦入庭前。
苔色侵三径，波声想五弦。
井蛙争入户，辙鲋乱归泉。
高𩅸愁晨坐，空阶警夜眠。
鹤鸣犹未已，蚁穴亦频迁。
散漫疎还密，空蒙断复连。
竹霑青玉润，荷滴白珠圆。
地湿灰蛾灭，池添水马怜。
有苗霑霢霂，无月弄潺湲。
篱菊潜开秀，园蔬已罢鲜。
断行随雁翅，孤啸耸鸢肩。
桥柱黏黄菌，墙衣点绿钱。
草荒行药路，沙泛钓鱼船。
长者车犹阻，高人榻且悬。
金乌何日见，玉爵几时传。
近井桐先落，当檐石欲穿。
趋风诚有恋，披雾邈无缘。
廪米陈生醭，庖薪湿起烟。
鸣鸡潜报晓，急景暗雕年。
盖洒高松上，丝繁细柳边。
拂丛时起蝶，堕叶乍惊蝉。
巾角皆争垫，帬裾别似湔。
人多蒙翠被，马尽着连干。
好客无来者，贫家但悄然。
湿泥印鹤迹，漏壁络蜗涎。
蚊聚雷侵室，鸥翻/浪满川。
上楼愁羃羃，绕舍厌溅溅。
律候今秋矣，欢娱久旷焉。
但令高兴在，晴后奉周旋。','',''),('quantangshi-43569','喜晴联句','白居易','quantangshi','','卷44','苦雨晴何喜，喜于未雨时。
气收云物变，声乐鸟乌知。
蕙泛光风圃，兰开皎月池。
千峰分远近，九陌好追随。
白日开天路，玄阴卷地维。
余清在林薄，新照入涟漪。
碧树凉先落，青芜湿更滋。
晒毛经浴鹤，曳尾出泥龟。
舞去商羊速，飞来野马迟。
柱边无润础，台上有游丝。
桥净行尘息，堤长禁柳垂。
宫城开睥睨，观阙丽罘罳。
洛水澄清镇，嵩烟展翠帷。
梁成虹乍见，市散蜃初移。
藉草风犹暖，攀条露已曦。
屋穿添碧瓦，墙缺召金锤。
迥彻来双目，昏烦去四支。
霞文晚焕烂，星影夕参差。
爽助门庭肃，寒摧草木衰。
黄干向阳菊，红洗得霜梨。
假盖闲谁惜，弹弦燥更悲。
散蹄良马稳，炙背野人宜。
洞户晨晖入，空庭宿雾披。
推林出书目，倾笥上衣椸。
道路行非阻，轩车望可期。
无辞访圭窦，且愿见琼枝。
山阁蓬莱客，储宫羽翼师。
每优陪丽句，何暇觌英姿。
翫景方搔首，怀人尚敛眉。
因吟仲文什，高兴尽于斯。','',''),('quantangshi-43570','会昌春连宴即事','白居易','quantangshi','','卷44','元年寒食日，上巳暮春天。
鸡黍三家会，莺花二节连。
光风初澹荡，美景渐暄妍。
簪组兰亭上，车舆曲水边。
松声添奏乐，草色助铺筵。
雀舫宜闲泛，螺杯任漫传。
园蔬香带露，厨柳暗藏烟。
丽句轻珠玉，清谈胜管弦。
陌喧金距鬬，树动彩绳悬。
姹女妆梳艳，游童衣服鲜。
圃香知种蕙，池暖忆开莲。
怪石云疑触，夭桃火欲然。
正欢唯恐散，虽醉未思眠。
啸傲人间世，追随地上仙。
燕来双涎涎，雁去累翩翩。
行乐真吾事，寻芳独我先。
滞周慙太史，入洛继先贤。
昔恨多分手，今欢谬比肩。
病犹陪宴饮，老更奉周旋。
望重青云客，情深白首年。
徧尝珍馔后，许入画堂前。
舞袖翻红炬，歌鬟插宝蝉。
断金多感激，倚玉贵迁延。
说史吞颜注，论诗笑郑笺。
松筠寒不变，胶漆冷弥坚。
兴伴王寻戴，荣同隗在燕。
掷卢夸使气，刻烛鬬成篇。
实艺皆三捷，虚名愧六联。
兴阑犹举白，话静每思玄。
更说归时好，亭亭月正圆。','',''),('quantangshi-43571','仆射来示有三春向晚四者难并之说诚哉是言辄引起题重为联句疲兵再战勍敌难降下笔之时冁然自哂走呈仆射兼简尚书','白居易','quantangshi','','卷44','三春今向晚，四者昔难并。
借问低眉坐，何如携手行。
旧游多过隙，新宴且寻盟。
鹦鹉林须乐，麒麟阁未成。
分阴当爱惜，迟景好逢迎。
林野熏风起，楼台谷雨晴。
墙低山半出，池广水初平。
桥转长虹曲，舟回小鷁轻。
残花犹布绣，密竹自闻笙。
欲过芳菲节，难忘宴慰情。
月轮行似箭，时物始如倾。
见雁随兄去，听莺求友声。
蕙长书带展，菰嫩剪刀生。
坐密衣裳暖，堂虚丝管清。
峰峦侵碧落，草木近朱明。
与点非沂水，陪膺是洛城。
拨醅争绿醑，卧酪待朱樱。
几处能留客，何人唤解酲。
旧仪尊右揆，新命宠春卿。
有喜鹊频语，无机鸥不惊。
青林思小隐，白雪仰芳名。
访旧殊千里，登高赖九城。
酇侯司管钥，疏傅傲簪缨。
纶綍曾同掌，烟霄即上征。
册庭尝接武，书殿忝连衡。
兰室春弥馥，松心晚更贞。
琴招翠羽下，钩掣紫鳞呈。
只愿回乌景，谁能避兕觥。
方知醉兀兀，应是走营营。
凤阁鸾台路，从他年少争。','',''),('quantangshi-43572','城南联句','韓愈','quantangshi','','卷44','竹影金琐碎，泉音玉淙琤。
琉璃翦木叶，翡翠开园英。
流滑随仄步，搜寻得深行。
遥岑出寸碧，远目增双明。
干穟纷拄地，化虫枯局茎。
木腐或垂耳，草珠竞骈睛。
浮虚有新斸，摧扤饶孤撑。
囚飞黏网动，盗啅接弹惊。
脱实自开坼，牵柔谁绕萦。
礼鼠拱而立，骇牛躅且鸣。
蔬甲喜临社，田毛乐宽征。
露萤不自暖，冻蝶尚思轻。
宿羽有先晓，食鳞时半横。
菱飜紫角利，荷折碧圆倾。
楚腻鳣鲔乱，獠羞蠃蟹并。
桑蠖见虚指，穴狸闻鬬狞。
逗翳翅相筑，摆幽尾交搒。
蔓涎角出缩，树啄头敲铿。
修箭褭金饵，羣鲜沸池羹。
岸壳坼玄兆，野麰渐丰萌。
窰烟羃疏岛，沙篆印回平。
㾕肌遭眊刺，啾耳闻鸡生。
奇虑恣回转，遐睎纵逢迎。
颠林戢远睫，缥气夷空情。
归迹归不得，舍心舍还争。
灵麻撮狗虱，村穉啼禽猩。
红皱晒檐瓦，黄团系门衡。
得隽蝇虎健，相残雀豹趟。
束枯樵指秃，刈熟担肩赬。
涩旋皮卷脔，苦开腹彭亨。
机舂潺湲力，吹簸飘颻精。
赛馔木盘簇，靸妖藤索絣。
荒学五六卷，古藏四三茔。
里儒拳足拜，土怪闪眸侦。
蹄道补复破，丝窠扫还成。
暮堂蝙蝠沸，破竈伊威盈。
追此讯前主，答云皆冢卿。
败壁剥寒月，折篁啸遗笙。
袿熏霏霏在，綦迹微微呈。
劒石犹竦槛，兽材尚拏楹。
宝唾拾未尽，玉啼堕犹枪。
窗绡疑閟艳，妆烛已销檠。
绿发抽珉甃，青肤耸瑶桢。
白蛾飞舞地，幽蠹落书棚。
惟昔集嘉咏，吐芳类鸣嘤。
窥奇摘海异，恣韵激天鲸。
肠胃绕万象，精神驱五兵。
蜀雄李杜拔，岳力雷车轰。
大句斡玄造，高言轧霄峥。
芒端转寒燠，神助溢杯觥。
巨细各乘运，湍涠亦腾声。
凌花咀粉蘂，削缕穿珠樱。
绮语洗晴雪，娇辞哢雏莺。
酣欢杂弁珥，繁价流金琼。
菡萏写江调，萎蕤缀蓝瑛。
庖霜脍玄鲫，淅玉炊香稉。
朝馔已百态，春醪又千名。
哀匏蹙驶景，冽唱凝余晶。
解魄不自主，痹肌坐空瞠。
扳援贱蹊绝，炫曜仙选更。
藂巧竞采笑，骈鲜互探婴。
桑变忽芜蔓，樟裁浪登丁。
霞鬬讵能极，风期谁复赓。
臯区扶帝壤，瓌蕴郁天京。
祥色被文彦，良才插杉柽。
隐伏饶气象，兴潜示堆坑。
擘华露神物，拥终储地祯。
訏谟壮缔始，辅弼登阶清。
坌秀恣填塞，呀灵滀渟澄。
益大联汉魏，肇初迈周嬴。
积照涵德镜，传经俪金籯。
食家行鼎鼐，宠族饫弓旌。
奕制尽从赐，殊私得逾程。
飞桥上架汉，缭岸俯规瀛。
潇碧远输委，湖嵌费携擎。
萄苜从大漠，枫槠至南荆。
嘉植鲜危朽，膏理易滋荣。
悬长巧纽翠，象曲善攒珩。
鱼口星浮没，马毛锦斑騂。
五方乱风土，百种分鉏耕。
葩蘖相妬出，菲茸共舒晴。
类招臻倜诡，翼萃伏衿缨。
危望跨飞动，冥升蹑登闳。
春游轹靃靡，彩伴飒嫈嫇。
遗灿飘的皪，淑颜洞精诚。
娇应如在寤，颓意若含酲。
鵷毳翔衣带，鹅肪截佩璜。
文升相照灼，武胜屠欃枪。
割锦不酬价，构云有高营。
通波牣鳞介，疏畹富萧蘅。
买养驯孔翠，远苞树蕉栟。
鸿头排刺芡，鹄𪇄攒瓌橙。
骛广杂良牧，蒙休赖先盟。
罢旄奉环卫，守封践忠贞。
战服脱明介，朝冠飘彩纮。
爵勋逮僮隶，簪笏自怀绷。
乳下秀嶷嶷，椒蕃泣喤喤。
貌鉴清溢匣，眸光寒发硎。
馆儒养经史，缀戚觞孙甥。
考钟馈肴核，戛鼓侑牢牲。
飞膳自北下，函珍极东烹。
如瓜煮大卵，比线茹芳菁。
海岳错口腹，赵燕锡媌娙。
一笑释仇恨，百金交弟兄。
货至貊戎市，呼传鹦鹆令。
顺居无鬼瞰，抑横免官评。
杀候肆凌翦，笼原匝罝紭。
羽空颠雉鷃，血路迸狐麖。
折足去踸踔，蹙鬐怒䰃鬤。
跃犬疾翥鸟，呀鹰甚饥䖟。
算蹄记功赏，裂脑擒摚掁。
猛毙牛马乐，妖残枭鵅惸。
窟穷尚嗔视，箭出方惊抨。
连箱载已实，碍辙弃仍赢。
喘覰锋刃点，困冲株枿盲。
扫净豁旷旷，骋遥略苹苹。
馋杈饱活脔，恶嚼𠽢腥鲭。
岁律及郊至，古音命韶韺。
旗斾流日月，帐庐扶栋甍。
磊落奠鸿璧，参差席香藑。
玄只祉兆姓，黑秬饛丰盛。
庆流蠲瘥疠，威畅捐䡴輣。
灵燔望高冏，龙驾闻敲𩙁。
是惟礼之盛，永用表其宏。
德孕厚生植，恩熙完刖剠。
宅土尽华族，连田间强甿。
荫庾森岭桧，啄场翽祥䳟。
畦肥翦韭●，陶固收盆甖。
利养积余健，孝思事严祊。
掘云破嵽嵲，采月漉坳泓。
寺砌上明镜，僧盂敲晓钲。
泥象对骋怪，铁钟孤舂鍠。
瘿颈闹鸠鸽，蜿垣乱蛷蝾。
葚黑老蚕蠋，麦黄韵鹂鹒。
韶曙迟胜赏，贤明戒先庚。
驰门填逼仄，竞墅辗砯砰。
碎缬红满杏，稠凝碧浮饧。
蹙绳觐娥婺，鬬草撷玑珵。
粉汗泽广额，金星堕连璎。
鼻偷困淑郁，眼剽强盯𥋝。
是节饱颜色，兹疆称都城。
书饶罄鱼茧，纪盛播琴筝。
奚必事远觌，无端逐羇伧。
将身亲魍魅，浮迹侣鸥䴖。
腥味空奠屈，天年徒羡彭。
惊魂见蛇蚓，触齅值虾蟚。
幸得履中气，忝从拂天枨。
归私暂休暇，驱明出庠黉。
鲜意竦轻畅，连辉照琼莹。
陶暄逐风乙，跃视舞晴蜻。
足胜自多诣，心贪敌无勍。
始知乐名教，何用苦拘儜。
毕景任诗趣，焉能守硜硜。','',''),('quantangshi-43573','会合联句','韓愈','quantangshi','','卷44','离别言无期，会合意弥重。
病添儿女恋，老丧丈夫勇。
劒心知未死，诗思犹孤耸。
愁去剧箭飞，欢来若泉涌。
析言多新贯，摅抱无昔壅。
念难须勤追，悔易勿轻踵。
吟巴山荦峃，说楚波堆垄。
马辞虎豹怒，舟出蛟鼍恐。
狂鲸时孤轩，幽狖杂百种。
瘴衣常腥腻，蛮器多疎宂。
剥苔吊斑林，角饭饵沈冢。
忽尔衔远命，归欤舞新宠。
鬼窟脱幽妖，天居觌清栱。
京游步方振，谪梦意犹恟。
诗书夸旧知，酒食接新奉。
嘉言写清越，愈病失肬肿。
夏阴偶高庇，宵魄接虚拥。
雪弦寂寂听，茗盌纤纤捧。
驰辉烛浮萤，幽响泄潜蛬。
诗老独何心，江疾有余尰。
我家本瀍谷，有地介臯巩。
休迹忆沈冥，峨冠慙闒𤾖。
升朝高辔逸，振物羣听悚。
徒言濯幽泌，谁与剃荒茸。
朝绅郁青绿，马饰曜圭珙。
国讐未销铄，我志荡邛陇。
君才诚倜傥，时论方汹溶。
格言多彪蔚，悬解无梏拲。
张生得渊源，寒色拔山冢。
坚如撞羣金，眇若抽独蛹。
伊余何所拟，跛鼈讵能踊。
块然堕岳石，飘尔罥巢氄。
龙斾垂天卫，云韶凝禁甬。
君胡眠安然，朝鼓声汹汹。','',''),('quantangshi-43574','鬬鸡联句','韓愈','quantangshi','','卷44','大鸡昂然来，小鸡竦而待。
峥嵘颠盛气，洗刷凝鲜彩。
高行若矜豪，侧睨如伺殆。
精光目相射，劒戟心独在。
既取冠为胄，复以距为镦。
天时得清寒，地利挟爽垲。
磔毛各噤㾕，怒瘿争碨磊。
俄膺忽尔低，植立瞥而改。
腷膊战声喧，缤飜落羽皠。
中休事未决，小挫势益倍。
妬肠务生敌，贼性专相醢。
裂血失鸣声，啄殷甚饥馁。
对起何急惊，随旋诚巧绐。
毒手饱李阳，神槌困朱亥。
恻心我以仁，碎首尔何罪。
独胜事有然，旁惊汗流浼。
知雄欣动颜，怯负愁看贿。
争观云填道，助叫波飜海。
事爪深难解，嗔睛时未怠。
一喷一醒然，再接再砺乃。
头垂碎丹砂，翼打拖锦彩。
连轩尚贾余，清厉比归凯。
选俊感收毛，受恩慙始隗。
英心甘鬬死，义肉耻庖宰。
君看鬬鸡篇，短韵有可采。','',''),('quantangshi-43575','纳凉联句','韓愈','quantangshi','','卷44','递啸取遥风，微微近秋朔。
金柔气尚低，火老候愈浊。
熙熙炎光流，竦竦高云擢。
闪红惊蚴虬，凝赤耸山岳。
目林恐焚烧，耳井忆瀺灂。
仰惧失交泰，非时结冰雹。
化邓渴且多，奔河诚已慤。
暍道者谁子，叩商者何乐。
洗矣得滂沱，感然鸣鸑鷟。
嘉愿苟未从，前心空缅邈。
清砌千回坐，冷环再三握。
烦怀却星星，高意还卓卓。
龙沈剧煮鳞，牛喘甚焚角。
蝉烦鸣转喝，乌噪饥不啄。
昼蝇食案繁，宵蚋肌血渥。
单絺厌已褫，长䈉倦还捉。
幸兹得佳朋，于此荫华桷。
青荧文簟施，淡澉甘瓜濯。
大壁旷凝净，古画奇驳荦。
凄如羾寒门，皓若攒玉璞。
埽宽延鲜飙，汲冷渍香穱。
篚实摘林珍，盘肴馈禽㲉。
空堂喜淹留，贫馔羞龌龊。
殷勤相劝勉，左右加砻斲。
贾勇发霜硎，争前曜冰槊。
微然草根响，先被诗情觉。
感衰悲旧改，工异逞新貌。
谁言摈朋老，犹自将心学。
危檐不敢凭，朽机惧倾扑。
青云路难近，黄鹤足仍鋜。
未能饮渊泉，立滞叫芳药。
与子昔睽离，嗟余苦屯剥。
直道败邪径，拙谋伤巧诼。
炎湖度氛氲，热石行荦硞。
痟肌夏尤甚，疟渴秋更数。
君颜不可觌，君手无由搦。
今来沐新恩，庶见返鸿朴。
儒庠恣游息，圣籍饱商搉。
危行无低徊，正言免咿喔。
车马获同驱，酒醪欣共欶。
惟忧弃菅蒯，敢望侍帷幄。
此志且何如，希君为追琢。','',''),('quantangshi-43576','秋雨联句','韓愈','quantangshi','','卷44','万木声号呼，百川气交会。
庭飜树离合，牖变景明蔼。
潨泻殊未终，飞浮亦云泰。
牵怀到空山，属听迩惊濑。
檐垂白练直，渠涨清湘大。
甘津泽祥禾，伏润肥荒艾。
主人吟有欢，客子歌无奈。
侵阳日沈玄，剥节风搜兑。
坱圠游峡喧，飕飗卧江汰。
微飘来枕前，高洒自天外。
蛬穴何迫迮，蝉枝埽鸣哕。
楥菊茂新芳，径兰销晚馤。
地镜时昏晓，池星竞漂沛。
讙呶寻一声，灌注咽羣籁。
儒宫烟火湿，市舍煎熬忲。
卧冷空避门，衣寒屡循带。
水怒已倒流，阴繁恐凝害。
忧鱼思舟檝，感禹勤畎浍。
怀襄信可畏，疏决须有赖。
筮命或冯蓍，卜晴将问蔡。
庭商忽惊舞，墉禜亦亲酹。
氛醨稍疎映，雺乱还拥荟。
阴旌时摎流，帝鼓镇訇磕。
枣圃落青玑，瓜畦烂文贝。
贫薪不烛竈，富粟空填廥。
秦俗动言利，鲁儒欲何匄。
深路倒羸骖，弱途拥行軑。
毛羽皆遭冻，离褷不能翽。
飜浪洗虚空，倾涛败藏盖。
吾人犹在陈，僮仆诚自郐。
因思征蜀士，未免湿戎斾。
安得发商飙，廓然吹宿霭。
白日悬大野，幽泥化轻壒。
战场暂一干，贼肉行可脍。
搜心思有效，抽策期称最。
岂惟虑收获，亦以救颠沛。
禽情初啸俦，础色微收霈。
庶几谐我愿，遂止无已太。','',''),('quantangshi-43577','征蜀联句','韓愈','quantangshi','','卷44','日王忿违慠，有命事诛拔。
蜀险豁关防，秦师纵横猾。
风旗匝地扬，雷鼓轰天杀。
竹兵彼皴脆，铁刃我枪䶪。
刑神咤牦旄，阴焰颭犀札。
飜霓纷偃蹇，塞野澒坱圠。
生狞竞掣跌，痴突争填轧。
渴鬬信豗呶，噉奸何噢嗗。
更呼相簸荡，交斫双缺齾。
火发激铓腥，血漂腾足滑。
飞猱无整阵，翩鹘有邪戛。
江倒沸鲸鲲，山摇溃貙䝟。
中离分二三，外变迷七八。
逆颈尽徽索，仇头恣髠鬝。
怒须犹鬇鬡，断臂仍𤬁𤫶。
石潜设奇伏，穴覰骋精察。
中矢类妖㺑，跳锋状惊豽。
蹋飜聚林岭，斗起成埃圿。
斾亡多空杠，轴折鲜联辖。
剟肤浃疮痍，败面碎剠㓤。
浑奔肆狂勷，捷窜脱趫黠。
岩钩踔狙猨，水漉杂鳣螖。
投奅闹䃔䃧，填隍𠋘㑻𠋚。
强睛死不闭，犷眼困逾䀣。
爇堞熇歊熺，抉门呀拗䦪。
天刀封未坼，酋胆慑前揠。
跧梁排郁缩，闯窦揳窋窡。
迫胁闻杂驱，咿呦叫冤{⻊兀}。
穷区指清夷，凶部坐雕铩。
邛文裁斐斖，巴艳收婠妠。
椎肥牛呼牟，载实驼鸣𡇼。
圣灵闵顽嚚，焘养均草䕓。
下书遏雄虓，解罪吊挛瞎。
战血时销洗，劒霜夜清刮。
汉栈罢嚣阗，獠江息澎汃。
戍寒绝朝乘，刁暗歇宵詧。
始去杏飞蠭，及归柳嘶𧉒。
庙献繁馘级，乐声洞椌楬。
台图焕丹玄，郊告俨匏稭。
念齿慰霉黧，视伤悼瘢痆。
休输任讹寝，报力厚麸秳。
公欢钟晨撞，室宴丝晓扴。
杯盂酬酒醪，箱箧馈巾帓。
小臣昧戎经，维用赞勋劼。','',''),('quantangshi-43578','同宿联句','韓愈','quantangshi','','卷44','自从别君来，远出遭巧谮。
斑斑落春泪，浩浩浮秋浸。
毛奇覩象犀，羽怪见鵩鸩。
朝行多危栈，夜卧饶惊枕。
生荣今分逾，死弃昔情任。
鵷行参绮陌，鸡唱闻清禁。
山晴指高标，槐密骛长荫。
直辞一以荐，巧舌千皆𦧈。
匡鼎惟说诗，桓谭不读谶。
逸韵何嘈嗷，高名俟沽赁。
纷葩欢屡填，旷朗忧早渗。
为君开酒肠，颠倒舞相饮。
曦光霁曙物，景曜铄宵祲。
儒门虽大启，奸首不敢闯。
义泉虽至近，盗索不敢沁。
清琴试一挥，白鹤叫相喑。
欲知心同乐，双茧抽作絍。','',''),('quantangshi-43579','莎栅联句','韓愈','quantangshi','','卷44','冰溪时咽绝，风枥方轩举。
此处不断肠，定知无断处。','',''),('quantangshi-43580','雨中寄孟刑部几道联句','韓愈','quantangshi','','卷44','秋潦淹辙迹，高居限参拜。
耿耿蓄良思，遥遥仰嘉话。
一晨长隔岁，百步远殊界。
商听饶清耸，闷怀空抑噫。
美君知道腴，逸步谢天械。
吟馨铄纷杂，抱照莹疑怪。
撞宏声不掉，输邈澜逾杀。
檐泻碎江喧，街流浅溪迈。
念初相遭逢，幸免因媒介。
祛烦类决痈，惬兴剧爬疥。
研文较幽玄，呼博骋雄快。
今君轺方驰，伊我羽已铩。
温存感深惠，琢切奉明诫。
迨兹更凝情，暂阻若婴瘵。
欲知相从尽，灵珀拾纤芥。
欲知相益多，神药销宿惫。
德符仙山岸，永立难欹坏。
气涵秋天河，有朗无惊湃。
祥凤遗蒿鷃，云韶掩夷靺。
争名求鹄徒，腾口甚蝉喝。
未来声已赫，始鼓敌前败。
鬬场再鸣先，遐路一飞届。
东野继奇躅，修纶悬众犗。
穿空细丘垤，照日陋菅蒯。
小生何足道，积慎如触虿。
愔愔抱所诺，翼翼自申戒。
圣书空勘读，盗食敢求嘬。
惟当骑款段，岂望觌圭玠。
弱操愧筠杉，微芳比萧●。
何以验高明，柔中有刚夬。','',''),('quantangshi-43581','远游联句','韓愈','quantangshi','','卷44','别肠车轮转，一日一万周。
离思春冰泮，澜漫不可收。
驰光忽以迫，飞辔谁能留。
取之讵灼灼，此去信悠悠。
楚客宿江上，夜魂栖浪头。
晓日生远岸，水芳缀孤舟。
村饮泊好木，野蔬拾新柔。
独含凄凄别，中结郁郁愁。
人忆旧行乐，鸟吟新得俦。
灵瑟时窅窅，霠猨夜啾啾。
愤涛气尚盛，恨竹泪空幽。
长怀绝无已，多感良自尤。
即路涉献岁，归期眇凉秋。
两欢日牢落，孤悲坐绸缪。
观怪忽荡漾，叩奇独冥搜。
海鲸吞明月，浪岛没大沤。
我有一寸鈎，欲钓千丈流。
良知忽然远，壮志郁无抽。
魍魅暂出没，蛟螭互蟠蟉。
昌言拜舜禹，举颿凌斗牛。
怀糈馈贤屈，乘桴追圣丘。
飘然天外步，岂肯区中囚。
楚些待谁吊，贾辞缄恨投。
翳明弗可晓，祕魂安所求。
气毒放逐域，蓼杂芳菲畴。
当春忽凄凉，不枯亦飕飗。
貉谣众猥款，巴语相咿嚘。
默誓去外俗，嘉愿还中州。
江生行既乐，躬辇自相勠。
饮醇趣明代，味腥谢荒陬。
驰深鼓利檝，趋险惊蜚輶。
系石沈靳尚，开弓射鴅吺。
路暗执屏翳，波惊戮阳侯。
广泛信缥缈，高行恣浮游。
外患萧萧去，中悒稍稍瘳。
振衣造云阙，跪坐陈清猷。
德风变谗巧，仁气销戈矛。
名声照西海，淑问无时休。
归哉孟夫子，归去无夷犹。','',''),('quantangshi-43582','晚秋郾城夜会联句','韓愈','quantangshi','','卷44','从军古云乐，谈笑青油幕。
灯明夜观棊，月暗秋城柝。
羁客方寂历，惊乌时落泊。
语阑壮气衰，酒醒寒砧作。
遇主贵陈力，夷凶匪兼弱。
百牢犒舆师，千户购首恶。
平生耻论兵，末暮不轻诺。
徒然感恩义，谁复论勋爵。
多士被霑汚，小夷施毒蠚。
何当铸劒戟，相与归台阁。
室妇欢鸣鹳，家人祝喜鹊。
终朝考蓍龟，何日亲蒸礿。
间使断津梁，潜军索林薄。
红尘羽书靖，大水沙囊涸。
铭山子所工，插羽余何怍。
未足烦刀俎，祗应输管钥。
雨矢逐天狼，电矛驱海若。
灵诛固无纵，力战谁敢却。
峨峨云梯翔，赫赫火箭着。
连空隳雉堞，照夜焚城郭。
军门宣一令，庙算建三略。
雷鼓揭千枪，浮桥交万筰。
蹂野马云腾，映原旗火铄。
疲氓坠将拯，残虏狂可缚。
摧锋若貙兕，超乘如猱玃。
逢掖服飜慙，缦胡缨可愕。
星陨闻雊雉，师兴随唳鹤。
虎豹贪犬羊，鹰鹯憎鸟雀。
烧陂除积聚，灌垒失依托。
凭轼谕昏迷，执殳征暴虐。
仓空战卒饥，月黑探兵错。
凶徒更蹈藉，逆族相啖嚼。
轴轳亘淮泗，斾旌连夏鄂。
大野纵氐羌，长河浴骝骆。
东西竞角逐，远近施矰缴。
人怨童聚谣，天殃鬼行虐。
汉刑支郡黜，周制闲田削。
侯社退无功，鬼薪惩不恪。
余虽司斧锧，情本尚丘壑。
且待献俘囚，终当返耕获。
藁街陈鈇钺，桃塞兴钱鎛。
地理画封疆，天文埽寥廓。
天子悯疮痍，将军禁卤掠。
策勋封龙頟，归兽获麟脚。
诘诛敬王怒，给复哀人瘼。
泽发解兜鍪，酡颜倾凿落。
安存惟恐晚，洗雪不论昨。
暮鸟已安巢，春蚕看满箔。
声明动朝阙，光宠耀京洛。
旁午降丝纶，中坚拥鼓铎。
密坐列珠翠，高门涂粉雘。
跋朝贺书飞，塞路归鞍跃。
魏阙横云汉，秦关束岩㟧。
拜迎罗櫜鞬，问遗结囊橐。
江淮永清晏，宇宙重开拓。
是日号升平，此年名作噩。
洪赦方下究，武飙亦旁魄。
南据定蛮陬，北攫空朔漠。
儒生惬教化，武士猛刺斫。
吾相两优游，他人双落莫。
印从负鼎佩，门为登坛凿。
再入更显严，九迁弥謇谔。
宾筵尽狐赵，导骑多卫霍。
国史擅芬芳，宫娃分绰约。
丹掖列鵷鹭，洪炉衣狐貉。
摛文挥月毫，讲劒淬霜锷。
命衣备藻火，赐乐兼附搏。
两厢铺𣰽毺，五鼎调勺药。
带垂苍玉佩，辔蹙黄金络。
诱接喻登龙，趋驰状倾藿。
青娥翳长袖，红颊吹鸣龠。
傥不忍辛勤，何由恣欢谑。
惟当早富贵，岂得暂寂寞。
但掷雇笑金，仍祈却老药。
殁庙配尊斝，生堂合毊鑮。
安行庇松篁，高卧枕莞蒻。
洗沐恣兰芷，割烹厌腗臄。
喜颜非忸怩，达志无陨获。
诙谐酒席展，慷慨戎装着。
斩马祭旄纛，包羔礼芒屩。
山多离隐豹，野有求伸蠖。
推选阅羣材，荐延搜一鹗。
左右供谄誉，亲交献谀噱。
名声载揄扬，权势实熏灼。
道旧生感激，当歌发酬酢。
羣孙轻绮纨，下客丰醴酪。
穷天贡琛异，匝海赐酺醵。
作乐鼓还槌，从禽弓始彍。
取欢移日饮，求胜通宵博。
五白气争呼，六奇心运度。
恩泽诚布濩，嚚顽已箫勺。
告成上云亭，考古垂矩矱。
前堂清夜吹，东第良晨酌。
池莲拆秋房，院竹飜夏箨。
五狩朝恒岱，三畋宿杨柞。
农书乍讨论，马法长悬格。
雪下收新息，阳生过京索。
尔牛时寝讹，我仆或歌咢。
帝载弥天地，臣辞劣萤爝。
为诗安能详，庶用存糟粕。','',''),('quantangshi-43583','石鼎联句','韓愈','quantangshi','','卷44','巧匠斲山骨，刳中事煎烹。
直柄未当权，塞口且吞声。
龙头缩菌蠢，豕腹涨彭亨。
外苞干藓文，中有暗浪惊。
在冷足自安，遭焚意弥贞。
谬当鼎鼐间，妄使水火争。
大似烈士胆，圆如战马缨。
上比香炉尖，下与镜面平。
秋瓜未落蔕，冻芋强抽萌。
一块元气闭，细泉幽窦倾。
不值输写处，焉知怀抱清。
方当洪炉然，益见小器盈。
睆睆无刃迹，团团类天成。
遥疑龟负图，出曝晓正晴。
旁有双耳穿，上有孤髻撑。
或讶短尾铫，又似无足铛。
可惜寒食球，掷此傍路坑。
何当出灰灺，无计离瓶罂。
陋质荷斟酌，狭中愧提擎。
岂能煮仙药，但未污羊羹。
形模妇女笑，度量儿童轻。
徒示坚重性，不过升合盛。
傍似废毂仰，侧见折轴横。
时于蚯蚓窍，微作苍蝇鸣。
以兹飜溢愆，实负任使诚。
常居顾盼地，敢有漏泄情。
宁依暖热弊，不与寒凉并。
区区徒自效，琐琐不足呈。
回旋但兀兀，开阖惟[铿铿]。
全胜瑚琏贵，空有口传名。
岂比俎豆古，不为手所撜。
磨砻去圭角，浸润着光精。
愿君莫嘲诮，此物方施行。','',''),('quantangshi-43584','有所思联句','孟郊','quantangshi','','卷44','相思绕我心，日夕千万重。
年光坐婉娩，春泪销颜容。
台镜晦旧晖，庭草滋深茸。
望夫山上石，别劒水中龙。','',''),('quantangshi-43585','遣兴联句','孟郊','quantangshi','','卷44','我心随月光，写君庭中央。
月光有时晦，我心安所忘。
常恐金石契，断为相思肠。
平生无百岁，岐路有四方。
四方各异俗，适异非所将。
驽蹄顾挫秣，逸翮遗稻粱。
时危抱独沈，道泰怀同翔。
独居久寂默，相顾聊慨慷。
慨慷丈夫志，可以曜锋铓。
蘧甯知卷舒，孔颜识行藏。
殷鉴谅不远，佩兰永芬芳。
苟无夫子听，谁使知音扬。','',''),('quantangshi-43586','赠劒客李园联句','孟郊','quantangshi','','卷44','天地有灵术，得之者惟君。
筑炉地区外，积火烧氛氲。
照海铄幽怪，满空歊异氛。
山磨电奕奕，水淬龙蝹蝹。
太一装以宝，列仙篆其文。
可用慑百神，岂惟壮三军。
有时幽匣吟，忽似深潭闻。
风胡久已死，此劒将谁分。
行当献天子，然后致殊勋。
岂知丰城下，空有斗间云。','',''),('quantangshi-43587','过海联句','賈島','quantangshi','','卷44','沙鸟浮还没，山云断复连。
棹穿波底月，船压水中天。','',''),('quantangshi-43588','妓席与杜牧之同咏','張祜','quantangshi','','卷44','骰子逡巡裹手拈，无因得见玉纤纤。
但知报道金钗落，仿髴还应露指尖。','',''),('quantangshi-43589','同赵二十二访张明府郊居联句','杜牧','quantangshi','','卷44','陶潜官罢酒瓶空，门掩杨花一夜风。
古调诗吟山色里，无弦琴在月明中。
远檐高树宜幽鸟，出岫孤云逐晚虹。
别后东篱数枝菊，不知闲醉与谁同。','',''),('quantangshi-43590','游长安诸寺联句 靖恭坊大兴善寺 老松青桐联二十字绝句','段成式','quantangshi','','卷44','有松堪系马，遇钵更投针。
记得汤师句，高禅助朗吟。
乘晴入精舍，语默想东林。
尽是忘机侣，谁惊息影禽。
一雨微尘尽，支郎许数过。
方同齅薝卜，不用算多罗。','',''),('quantangshi-43591','游长安诸寺联句 靖恭坊大兴善寺 蛤像联二十字绝句','段成式','quantangshi','','卷44','相好全如梵，端倪祗为隋。
宁同蚌顽恶，但与鹬相持。
虽因雀变化，不逐月亏盈。
纵有天中匠，神工讵可成。','',''),('quantangshi-43592','游长安诸寺联句 靖恭坊大兴善寺 圣柱联句','段成式','quantangshi','','卷44','天心惟助善，圣迹此开阳。
载恐雷轮重，絙疑电索长。
上冲挟螮蝀，不动束锒铛。
饥鸟未曾啄，乖龙宁敢藏。','',''),('quantangshi-43593','游长安诸寺联句 长乐坊安国寺 红楼联句','段成式','quantangshi','','卷44','重叠碎晴空，余霞更照红。
蝉踪近鳷鹊，鸟道接相风。
苔静金轮路，云轻白日宫。
壁诗传谢客，门牓占休公。','',''),('quantangshi-43594','游长安诸寺联句 长乐坊安国寺 穗柏联句','段成式','quantangshi','','卷44','一院暑难侵，莓苔共影深。
标枝争息鸟，余吹正开襟。
宿雨香添色，残阳石在阴。
乘闲动诗意，助静入禅心。','',''),('quantangshi-43595','游长安诸寺联句 长乐坊安国寺 题璘公院','段成式','quantangshi','','卷44','静，虚。
热际，安居。
龛灯敛，印香除。
东林宾客，西涧图书。
檐外垂青豆，经中发白蕖。
纵辩宗因衮衮，忘言理事如如。
泉台定将入流否，邻笛足疑清梵余。','',''),('quantangshi-43596','游长安诸寺联句 常乐坊赵景公寺 吴画联句','段成式','quantangshi','','卷44','惨澹十堵内，吴生纵狂迹。
风云将逼人，神鬼如脱壁。
其中龙最怪，张甲方汗栗。
黑云夜窸窣，焉知不霹雳。
此际忽仙子，猎猎衣舃奕。
妙瞬乍疑生，参差夺人魄。
往往乘猛虎，冲梁耸奇石。
苍峭束高泉，角膝惊欹侧。
冥狱不可视，毛戴腋流液。
苟能水成河，刹那沈火宅。','',''),('quantangshi-43597','游长安诸寺联句 常乐坊赵景公寺 题约公院','段成式','quantangshi','','卷44','印火荧荧，灯续焰青。
七俱胝咒，四阿含经。
各录佳语，聊事素屏。
丈室安居，延宾不扃。','',''),('quantangshi-43598','游长安诸寺联句 大同坊云华寺 偶联句','段成式','quantangshi','','卷44','共入夕阳寺，因窥甘露门。
清香惹苔藓，忍草杂兰荪。
捷偈飞钳答，新诗倚杖论。
坏幡标古刹，圣画焕崇垣。
岂慕穿笼鸟，难防在牖猿。
一音唯一性，三语更三幡。','',''),('quantangshi-43599','游长安诸寺联句 道政坊宝应寺 僧房联句','段成式','quantangshi','','卷44','古画思匡岭，上方疑傅岩。
蝶闲移忍草，蝉晓揭高杉。
香字消芝印，金经发茝函。
井通松底脉，书坼洞中缄。','',''),('quantangshi-43600','游长安诸寺联句 道政坊宝应寺 小小写真联句','段成式','quantangshi','','卷44','如生小小真，犹自未栖尘。
褕袂将离座，斜柯欲近人。
昔时知出众，情宠占横陈。
不遣游张巷，岂教窥宋邻。
庾楼吹笛裂，弘阁赏歌新。
蝉怯纤腰步，蛾惊半额嚬。
图形谁有术，买笑讵辞贫。
复陇迷村径，重泉隔汉津。
同心知作羽，比目定为鳞。
残月巫山夕，余霞洛浦晨。','',''),('quantangshi-43601','游长安诸寺联句 平康坊菩萨寺 书事联句','段成式','quantangshi','','卷44','悉为无事者，任被俗流憎。
客异干时客，僧非出院僧。
远闻疎牖磬，晓辨密龛灯。
步触珠幡响，吟窥钵水澄。
句饶方外趣，游惬社中朋。
静里已驯鸽，斋中亦好鹰。
金涂笔是褧，彩溜纸非缯。
锡杖已克锻，田衣从怀塍。
占牀暂一胁，卷箔赖长肱。
佛日初开照，魔天破几层。
咒中陈祕计，论处正先登。
勇带绽针石，危防丘井藤。','',''),('quantangshi-43602','游长安诸寺联句 光宅坊光宅寺 中禅师影堂联句','段成式','quantangshi','','卷44','名下固无虚，敖曹貌严毅。
洞达见空王，圆融入佛地。
一言当要害，忽忽醒诸醉。
不动须弥山，多方辩无匮。
坦率对万乘，偈答无所避。
尔如毗沙门，外形如脱履。
但以理为量，不语怪力事。
木石摧贡高，慈悲引贪恚。
当时乏支许，何人契深致。
随宜讵说三，直下开不二。','',''),('quantangshi-43603','游长安诸寺联句 翊善坊保寿寺 光天帧赞联句','段成式','quantangshi','','卷44','观音化身，厥形孔怪。
胣脑淫厉，众魔膜拜。
指梦鸿纷，牓列区界。
其事明张，何不可解。
阎阿德川，大士先天。
众象参罗，福源田田。
百亿花发，百千灯然。
胶如[络绎]，浩汗连緜。
焰摩界戚，洛迦苦霁。
正念皈依，众青如𥶙。
戾滓可汰，痴膜可蜕。
稽首如空，睟容若睇。
阐提墨师，覩而面之。
寸念不生，未遇乎而。','',''),('quantangshi-43604','游长安诸寺联句 宣阳坊静域寺 三阶院联句','段成式','quantangshi','','卷44','密密助堂堂，隋人歌檿桑。
双弧摧孔雀，一矢陨贪狼。
百步望云立，九规看月张。
获蛟徒破浪，中乙漫如墙。
还似贯金鼓，更疑穿石梁。
因添挽河力，为灭射天狂。
绝艺却南牧，英声来鬼方。
丽龟何足敌，殪豕未为长。
龙臂胜猨臂，星芒超箭芒。
虚夸绝高鸟，垂拱议明堂。','',''),('quantangshi-43605','游长安诸寺联句 崇义坊招福院 赠诸上人联句','段成式','quantangshi','','卷44','飜了西天偈，烧余梵宇香。
拈眉愁俗客，支颊背残阳。
洲号惟思沃，山名祗记匡。
辨中摧世智，定里破魔强。
许睿禅心彻，汤休诗思长。
朗吟疎磬断，久语贯珠妨。
乘兴书芭叶，闲来入豆房。
漫题存古壁，怪画匝长廊。','',''),('quantangshi-43606','游长安诸寺联句 招国坊崇济寺 奇松联二十字绝句','段成式','quantangshi','','卷44','杉松何相疎，榆柳方迥屑。
无人擅谈柄，一枝不敢折。
中庭苔藓深，吹余鸣佛禽。
至于摧折枝，凡草犹避阴。
僻径根从露，闲房枝任侵。
一株风正好，来助碧云吟。
时时埽窗声，重露滴寒砌。
风颭一枝遒，闲窥别生势。
偃盖入楼妨，盘根侵井窄。
高僧独惆怅，为与澄岚隔。','',''),('quantangshi-43607','游长安诸寺联句 永安坊永寿寺 闲中好','段成式','quantangshi','','卷44','闲中好，尽日松为侣。
此趣人不知，轻风度僧语。
闲中好，尘务不萦心。
坐对当窗木，看移三面阴。
闲中好，幽磬度声迟。
卷上论题肇，画中僧姓支。','',''),('quantangshi-43608','游长安诸寺联句 崇仁坊资圣寺 诸画联句','段成式','quantangshi','','卷44','吴生画勇矛戟攒，出变奇势千万端。
苍苍鬼怪层壁宽，覩之忽忽毛发寒。
棱伽之力所疲殚，李真周昉优劣难。
活禽生卉推边鸾，花房嫩彩犹未干。
韩干变态如激湍，惜哉壁画世未殚。
后人新画何汗漫。','',''),('quantangshi-43609','北禅院避暑联句','皮日休','quantangshi','','卷44','歊蒸何处避，来入戴颙宅。
逍遥脱单绞，放旷抛轻策。
爬搔林下风，偃仰涧中石。
残蝉烟外响，野鹤沙中迹。
到此失烦襟，萧然揖禅伯。
藤悬叠霜蜕，桂倚支云锡。
清阴竖毛发，爽气舒筋脉。
逐幽随竹书，选胜铺苮席。
鱼跳上紫芡，蝶化缘青壁。
心是玉莲徒，耳为金磬敌。
吾宗昔高尚，志在羲皇易。
岂独断韦编，几将刓铁擿。
天书既屡降，野抱难自适。
一入承明庐，盱衡论今昔。
流光不容寸，斯道甘枉尺。
既起谢儒玄，亦飜商羽翼。
封章帷幄徧，梦寐江湖白。
摆落函谷尘，高欹华阳帻。
诏去云无信，归来鹤相识。
半病夺牛公，全慵捕鱼客。
少微光一点，落此芒磔索。
释子问池塘，门人废幽赜。
堪悲东序宝，忽变西方籍。
不见步兵诗，空怀康乐屐。
高名不可效，胜境徒堪惜。
墨沼转疎芜，玄斋逾阒寂。
迟迟不可去，凉飔满杉柏。
日下洲岛清，烟生苾蒭碧。
俱怀出尘想，共有吟诗癖。
终与净名游，还来雪山觅。','',''),('quantangshi-43610','寂上人院联句','皮日休','quantangshi','','卷44','瘿牀空默坐，清景不知斜。
暗数菩提子，闲看薜茘花。
有情惟墨客，无语是禅家。
背日聊依桂，尝泉欲试茶。
石形蹲玉虎，池影闪金蛇。
经笥安岩匼，瓶囊挂树桠。
书传沧海外，龛寄白云涯。
竹色寒凌箔，灯光静隔纱。
趁幽飜小品，逐胜讲南华。
莎彩融黄露，莲衣染素霞。
水堪伤聚沫，风合落天葩。
若许传心印，何辞古堞赊。','',''),('quantangshi-43611','独在开元寺避暑颇怀鲁望因飞笔联句','皮日休','quantangshi','','卷44','烦署虽难避，僧家自有期。
泉甘于马乳，苔滑似龙漦。
任诞襟全散，临幽榻旋移。
松行将雅拜，篁阵欲交麾。
望塔青𩩉识，登楼白鸽知。
石经森欲动，珠像俨将怡。
筠簟临杉穗，纱巾透雨丝。
静谭蝉噪少，凉步鹤随迟。
烟重回蕉扇，轻风拂桂帷。
对碑吴地说，开卷梵天词。
积水鱼梁坏，残花病枕欹。
怀君潇洒处，孤梦绕罘罳。','',''),('quantangshi-43612','寒夜文宴联句','皮日休','quantangshi','','卷44','文星今夜聚，应在斗牛间。
载石人方至，乘槎客未还。
送觞繁露曲，征句白云颜。
节奏惟听竹，从容只话山。
理穷倾祕藏，论猛折玄关。
酃酒分中绿，巴笺擘处殷。
清言闻后醒，强韵压来艰。
犀柄当风揖，琼枝向月攀。
松吟方㗫㗫，泉梦忆潺潺。
一会文章草，昭明不可删。','',''),('quantangshi-43613','药名联句','皮日休','quantangshi','','卷44','为待防风饼，须添薏苡杯。
香然柏子后，尊泛菊花来。
石耳泉能洗，垣衣雨为裁。
从容犀局静，断续玉琴哀。
白芷寒犹采，青箱醉尚开。
马衔衰草卧，乌啄蠹根回。
雨过兰芳好，霜多桂末摧。
朱儿应作粉，云母讵成灰。
艺可屠龙胆，家曾近燕胎。
墙高牵薜茘，障輭撼玫瑰。
鸓鼠啼书户，蜗牛上研台。
谁能将藁本，封与玉泉才。','',''),('quantangshi-43614','寒夜联句','陸龜蒙','quantangshi','','卷44','静境揖神凝，寒华射林缺。
清知思绪断，爽觉心源彻。
高唱戛金奏，朗咏铿玉节。
我思方泬寥，君词复凄切。
况闻风篁上，摆落残冻雪。
寂尔万籁清，皎然诸霭灭。
西窗客无梦，南浦波应结。
河光正如劒，月魄方似玦。
短烬不禁挑，冷毫看欲折。
何夕重相期，浊醪还为设。','',''),('quantangshi-43615','开元寺楼看雨联句','陸龜蒙','quantangshi','','卷44','海上风雨来，掀轰杂飞电。
登楼一凭槛，满眼蛟龙战。
须臾造化惨，倏忽堪舆变。
万户响戈鋋，千家披组练。
羣飞抛轮石，杂下攻城箭。
点急似摧胸，行斜如中面。
细洒魂空冷，横飘目能眩。
垂檐珂佩喧，㩧瓦珠玑溅。
无言九陔远，瞬息驰应徧。
密处正垂絚，微时又悬线。
写作玉界破，吹为羽林旋。
飜伤列缺劳，却怕丰隆倦。
遥瞻山露色，渐觉云成片。
远树欲鸣蝉，深檐尚藏燕。
残雷隐辚尽，反照依微见。
天光洁似磨，湖彩熟于练。
疎帆逗前渚，晚磬分凉殿。
接思强挥毫，窥词几焚研。
佶栗乌皮几，轻明白羽扇。
毕景好疎吟，余凉可清宴。
君携下高磴，僧引还深院。
驳藓净铺筵，低松湿垂鬋。
斋明乍虚豁，林霁逾葱蒨。
早晚重登临，欲去多离恋。','',''),('quantangshi-43616','报恩寺南池联句','陸龜蒙','quantangshi','','卷44','古岸涵碧落，虚轩明素波。
坐来鱼阵变，吟久菊□多。
秋草分杉露，危桥下竹坡。
远峰青髻竝，□□□髯和。
赵论寒仍讲，支硎僻亦过。
斋心曾养鹤，挥翰好邀鹅。
倚石收奇药，临溪藉浅莎。
桂花晴似拭，荷镜晓如磨。
翠出牛头耸，苔深马迹跛。
繖欹从野醉，巾侧任田歌。
跁跒松形矮，般跚桧樾矬。
香飞僧印火，泉急使镳珂。
菱钿真堪帖，莼丝亦好拖。
几时无一事，相伴着烟萝。','',''),('quantangshi-43617','天台禅院联句','安守範','quantangshi','','卷44','偶到天台院，因逢物外僧。
忘机同一祖，出语离三乘。
树老中庭寂，窗虚外境澄。
片时松影下，联续百千灯。','',''),('quantangshi-43618','讲德联句','晝','quantangshi','','卷44','先王设位，以正邦国。
建立大官，封植有德。
二南敷化，四岳述职。
其言不朽，其仪不忒。
暨于嬴刘，乃创程式。
罢侯置守，剖竹分域。
赫矣皇唐，康哉立极。
精选藩翰，庸资正直。
爰命我公，东土作则。
克己恭俭，疲人休息。
济济闾閈，油油黍稷。
既富既教，足兵足食。
恤其凋瘵，剪其荆棘。
威怀逋叛，扑灭蝥贼。
疾恶如讐，闻善不惑。
哀矜鳏寡，旌礼儒墨。
乃修堤防，乃浚沟洫。
以利通商，以溉嘉谷。
征赋以节，计功以时。
人胥怀惠，吏不能欺。
我政载孚，我邦载绥。
猛兽不暴，嘉鱼维滋。
肃恭明神，齐沐不亏。
岁或骄阳，雨无愆期。
帝嘉有庸，宠命来斯。
紫绂载绥，金章陆离。
资忠履孝，阅礼敦诗。
明德惟馨，自天佑之。','',''),('quantangshi-43619','讲古文联句','晝','quantangshi','','卷44','帝出于震，文明始敷。
山岳降气，龟龙负图。
爰有书契，乃立典谟。
先知孔圣，飞步天衢。
汉承秦弊，尊儒尚学。
百氏六经，九流七略。
屈宋接武，班马继作。
或颂燕然，或赞麟阁。
降及三祖，始变二雅。
仲宣闲和，公干萧洒。
士衡安仁，不史不野。
左张精奥，嵇阮高寡。
暨于江表，其文郁兴。
绮丽争发，繁芜则惩。
词晔春华，思清冬冰。
景纯跌宕，游仙独步。
青云其情，白璧其句。
灵运山水，实多奇趣。
远派孤峰，龙腾凤翥。
陶令田园，匠意真直。
春柳寒松，不凋不饰。
江淹杂体，方见才力。
拟之信工，似而不逼。
鲍昭从军，主意危苦。
气胜其词，雅愧于古。
隐侯似病，创制规矩。
时见琳琅，惜哉榛楛。
谢朓秀发，词理翩翩。
孤标爽迈，深造精研。
惠休翰林，别白离坚。
有会必惬，无惭曩贤。
吴均颇劲，失于典裁。
竟乏波澜，徒工边塞。
彼柳吴兴，高视时辈。
汀洲一篇，风流寡对。
何逊清切，所得必新。
缘情既密，象物又真。
江总征正，未越常伦。
时合风兴，或无淄磷。
二杜繁俗，三刘琐碎。
陈徐之流，阴张之辈。
伊数公者，阃域之外。
吁此以还，有固斯郐。','',''),('quantangshi-43620','项王古祠联句','晝','quantangshi','','卷44','遗庙风尘积，荒途岁月侵。
英灵今寂寞，容卫尚森沈。
霸楚志何在，平秦功亦深。
诸侯归复背，青史古将今。
星聚分已定，天亡力岂任。
采蘩如可荐，举酒沥空林。','',''),('quantangshi-43621','还丹可成诗联句','晝','quantangshi','','卷44','羽化自仙骨，延年资养生。
金经启灵秘，玉液流至精。
八石思共炼，九丹知可成。
吾心苟无妄，神理期合并。
封竈用六一，置门考休京。
浮光含日彩，圆质焕云英。
持此保寿命，服之颐性情。
跂予望仙侣，高咏升天行。
鹤驾方可致，霓裳定将迎。
不因五色药，安着七真名。
挥妙在微密，全功知感诚。
与君弃城市，携手游蓬瀛。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-43622','建安寺西院喜王郎中遘恩命初至联句','晝','quantangshi','','卷44','迹就空门退，官从画省迁。
住持良有愿，朝谒宂无缘。
身净金绳内，心驰玉扆前。
荣添一两日，恩降九霄年。
慕法能轻冕，追非欲佩弦。
栖闲那可久，鸳鹭待行联。','',''),('quantangshi-43623','建安寺夜会对雨怀皇甫侍御曾联句','晝','quantangshi','','卷44','相思非是远，风雨遣情多。
愿欲披云见，难堪候晓过。
夜长同岁月，地近极山河。
戒相初传授，文章旧切磋。
时称洛下咏，人许郢中歌。
惆怅徒延首，其如一水何。','',''),('quantangshi-43624','泛长城东溪暝宿崇光寺寄处士陆羽联句','晝','quantangshi','','卷44','箬水青似箬，玉山碧于玉。
逼霄沓万状，截地分千曲。
萍解深可窥，林豁遥在瞩。
已高物外赏，稍涤区中欲。
野鹤翔又飞，世人羁且局。
沈吟迹所悞，放浪心自足。
缅怀虚舟客，愿寄生刍束。
说诗整颓波，立义激浮俗。
荆吴备登历，风土随编录。
恨与清景别，拟教长路促。
溪鸟语鹂喽，寺花翻踯躅。
印围水坛净，香护莲衣触。
捧经启纱灯，收袵礼金粟。
安得扣关子，玄言对吾属。','',''),('quantangshi-43625','与崔子向泛舟自招橘经箬里宿天居寺忆李侍御㟧渚山春游后期不及联一十六韵以寄之','晝','quantangshi','','卷44','晴日春态深，寄游恣所适。
宁妨花木乱，转学心耳寂。
取性怜鹤高，谋闲任山僻。
倚舷息空曲，舍屦行浅碛。
渚箬入里逢，野梅到村摘。
碑残飞雉岭，井翳潜龙宅。
坏寺邻寿陵，古坛留劫石。
穿阶笋节露，拂瓦松梢碧。
天界细云还，墙阴杂英积。
悬灯寄前焰，遥月升圆魄。
何意清夜期，坐为高峰隔。
茗园可交袂，藤涧好停锡。
微雨听湿巾，迸流从点席。
戏猨隔枝透，惊鹿逢人踯。
覩物赏已奇，感时思弥极。
芳菲如驰箭，望望共君惜。','',''),('quantangshi-43626','渚山春暮会顾丞茗舍联句效小庾体','晝','quantangshi','','卷44','谁是惜暮人，相携送春日。
因君过茗舍，留客开兰室。
湿苔滑行屐，柔草低藉瑟。
鹊喜语成双，花狂落非一。
烟浓山焙动，泉破水舂疾。
莫抝挂瓢枝，会移阆书帙。
颇容樵与隐，岂闻禅兼律。
栏竹不求疎，网藤从更密。
池添逸少墨，园杂庄生漆。
景晏枕犹欹，酒醒头懒栉。
云教淡机虑，地可遗名实。
应待御荈青，幽期踏芳出。','',''),('quantangshi-43627','与李司直令从荻塘联句','晝','quantangshi','','卷44','画舸悠悠荻塘路，真僧与我相随去。
寒花似菊不知名，霜叶如枫是何树。
倦客经秋夜共归，情多语尽明相顾。
遥城候骑来仍少，傍岭哀猨发无数。
心闲清净得禅寂，兴逸纵横问章句。
虫声切切草间悲，萤影纷纷月前度。
撩乱云峰好赋诗，婵娟水月堪为喻。
与君出处本不同，从此还依旧山住。','',''),('quantangshi-43628','远意联句','晝','quantangshi','','卷44','家在炎州往朔方，岂知于阗望潇湘。
曾经陇底复辽阳，更忆东去采扶桑。
楂客三千路未央，烛龙之地日无光。
将游莽苍穷大荒，车辙马足逐周王。','',''),('quantangshi-43629','暗思联句','晝','quantangshi','','卷44','斜风飘雨三十夜，隣女余光不相借。
迹灭尘生古人画，洞房重扉无隟罅。','',''),('quantangshi-43630','乐意联句一首','晝','quantangshi','','卷44','良朋益友自远来，万里乡书对酒开。
子孙蔓衍负奇才，承颜弄鸟咏南陔。
鼓腹击壤歌康哉！。','',''),('quantangshi-43631','恨意联句','晝','quantangshi','','卷44','同心同县不相见，独采蘼芜咏团扇。
莫听东隣捣霜练，远忆征人泪如霰。
长信空阶荒草遍，明妃初别昭阳殿。','',''),('quantangshi-43632','秋日卢郎中使君幼平泛舟联句一首','晝','quantangshi','','卷44','共载清秋客船，同瞻皂盖朝天。
悔使比来相得，如今欲别潸然。
渐惊徒驭分散，愁望云山接连。
魏阙驰心日日，吴城挥手年年。
送远已伤飞雁，裁诗更切嘶蝉。
空怀鄠杜心醉，永望门栏脰捐。
别思无穷无限，还如秋水秋烟。','',''),('quantangshi-43633','重联句一首','晝','quantangshi','','卷44','相将惜别且迟迟，未到新丰欲醉时。
去郡独携程氏酒，入朝可忘习家池。
仍怜故吏依依恋，自有清光处处随。
晚景南徐何处宿，秋风北固不堪辞。
吴中诗酒饶佳兴，秦地关山引梦思。
对酒已伤嘶马去，衔恩只待扫门期。','',''),('quantangshi-43634','与潘述集汤衡宅怀李司直纵联句','晝','quantangshi','','卷44','幽独何以慰，友人顾茅茨。
已忘岁月念，载说清闲时。
旭日舒朱槿，柔风引绿葹。
迢迢青溪路，耿耿芳树枝。
执袵空踯躅，来城自逶迤。
相思寄采掇，景晏独驱驰。','',''),('quantangshi-43635','安吉崔明甫山院联句一首','晝','quantangshi','','卷44','人不扰，政已和。
世虑寡，山情多。
禅客至，墨卿过。
兴既洽，情如何。','',''),('quantangshi-43636','重联句一首','晝','quantangshi','','卷44','肃肃清院，翛翛碧鲜。
已见心远，何关地偏。
自公退食，升堂草玄。
纷纷已隔，云心澹然。','',''),('quantangshi-43637','重联句一首','晝','quantangshi','','卷44','瀑溜闻窗外，晴风逼座间。
挂冠徒有意，芳桂杳难攀。','',''),('quantangshi-43638','重联句一首','晝','quantangshi','','卷44','清高素非宦侣，疎散从来道流。
今日还轻墨绶，知君意在沧洲。
浮云任从飘荡，寄隐也信沈浮。
不似漳南地僻，道安为我淹留。','',''),('quantangshi-43639','重联句一首','晝','quantangshi','','卷44','刘令兴多常步履，柴桑事少但援琴。
闲招法侣从山寺，每掇幽芳傍竹林。
卷帘只爱荆峰色，入坐偏宜郢客吟。
谁许近来轻印绶，因君昨日悟禅心。','',''),('quantangshi-43640','道观中和潘丞观青溪图联句','晝','quantangshi','','卷44','画得青溪样，宜于紫府观。
日明烟霭薄，风落水容宽。
画野高低接，商工井邑攒。
疏川因稼穑，出使问艰难。','',''),('quantangshi-43641','春日对雨联句一首','晝','quantangshi','','卷44','春烟带微雨，漠漠连城邑。
桐叶生微阴，桃花更宜湿。
萧条暗杨柳，散漫下原隰。
归路不我从，遥心空伫立。
林低山影近，岸转水流急。
芳草自堪游，白云如可揖。
寻山禅客意，苦雨陶公什。
游衍情未终，归飞暮相及。
峰高日色转，潭净天光入。
却欲学神仙，空思谢朋执。
为道贵逍遥，趍时多苦集。
琼英若可飱，青紫徒劳拾。','',''),('quantangshi-43642','春日会韩武康章后亭联句','晝','quantangshi','','卷44','后园堪寄赏，日日对春风。
客位繁阴下，公墙细柳中。
坐看青嶂远，心与白云同。
林暗花烟入，池深远水通。
井桃新长蘂，栏药未成丛。
松竹宜禅客，山泉入谢公。
砌香翻芍药，檐静倚梧桐。
外虑宜帘卷，忘情与道空。
楚僧招惠远，蜀客挹杨雄。
便寄柴桑隐，何劳访剡东。','',''),('quantangshi-43643','康录事宅送僧联句','晝','quantangshi','','卷44','莲衣宜着雨，竹锡好随云。
见鹤还应养，逢鸥自作羣。','',''),('quantangshi-43644','与邢端公李台题庭石联句','晝','quantangshi','','卷44','共题诗句遍，争坐藓文稀。','',''),('quantangshi-43645','冬日建安寺西院喜昼公自吴兴至联句一首','晝','quantangshi','','卷44','宗系传康乐，精修学远公。
相寻当暮岁，行李犯寒风。
累积浮生里，机慙半偈中。
传家知业坠，继祖忝声同。
云与轻帆至，山将本寺空。
向来忘起灭，留我宿花宫。','',''),('quantangshi-43646','秋日潘述自长城至霅上与昼公汤评事游集累日时司直李公瑕往苏州有阻良会因与二公联句以寄之','晝','quantangshi','','卷44','离念非前期，秋风忽已至。
芸黄众芳晚，摇荡居人思。
白霜凄以积，高梧飒而坠。
悠然越山川，复此恨离异。
时景易迁谢，懽□难兼遂。
惜分缓回舟，怀遥企归驷。
休澣情自高，来思日云未。','',''),('quantangshi-43647','喜昼公寻山回相遇联句一首','晝','quantangshi','','卷44','几年无此会，今日喜相从。
后夏仍多病，前书达几封。
水华迎暮雨，松吹引疎钟。
出谷随初月，寻僧说五峰。','',''),('quantangshi-43648','送昼公联句','晝','quantangshi','','卷44','相逢情不厌，惜别意难为。
吾道应无住，前期未可知。
轻霜凋古木，寒水缩荒陂。
宾雁依沙屿，浮云惨路岐。
林疎看野迥，岸转觉山移。
寄赏惊摇落，归心叹别离。
草堂思偃蹇，麈尾去相随。
勿谓光阴远，禅房会一窥。','',''),('quantangshi-43649','与罗隐之联句','鄭遨','quantangshi','','卷44','一壶天上有名物，两个世间无事人。
醉却隐之云叟外，不知何处是天真。','',''),('quantangshi-43650','句','李日知','quantangshi','','卷44','所愿暂知居者乐，无使时称主者劳。','',''),('quantangshi-43651','句','趙仁奬','quantangshi','','卷44','令乘骢马去，丞脱绣衣来。','',''),('quantangshi-43652','句','郭廷謂','quantangshi','','卷44','魂逐东流水，坟依独坐山。','',''),('quantangshi-43653','句','韋青','quantangshi','','卷44','三代掌纶诰，一身能唱歌。','',''),('quantangshi-43654','句','尉遲匡','quantangshi','','卷44','明月飞出海，黄河流上天。
芙蓉初出水，桃李忽无言。
夜夜月为青冢镜，年年雪作黑山花。','',''),('quantangshi-43655','句','何涓','quantangshi','','卷44','雁影数行秋半逢，渔歌一声夜深发。','',''),('quantangshi-43656','句','杜偉','quantangshi','','卷44','忽覩邢武辞，泠其金石备。','',''),('quantangshi-43657','句','申堂構','quantangshi','','卷44','霜添柏树冷，气拂桂林寒。','',''),('quantangshi-43658','句','周愿','quantangshi','','卷44','八十年前棠树阴，竟陵太守公先人。','',''),('quantangshi-43659','句','苐五琦','quantangshi','','卷44','阴天闻断雁，夜浦送归人。','',''),('quantangshi-43660','句','顏允南','quantangshi','','卷44','谁言百人会，兄弟也霑陪。','',''),('quantangshi-43661','句','季廣琛','quantangshi','','卷44','刻舟寻已化，弹铗未酬恩。','',''),('quantangshi-43662','句','陳蛻','quantangshi','','卷44','梦里换春秋。','',''),('quantangshi-43663','句','衛準','quantangshi','','卷44','莫言闲话是闲话，往往事从闲话来。
何必剃头为弟子，无家便是出家人。','',''),('quantangshi-43664','句','杜鴻漸','quantangshi','','卷44','常愿追禅理，安能挹化源。','',''),('quantangshi-43665','句','李摯','quantangshi','','卷44','因缘三纪异，契分四般同。','',''),('quantangshi-43666','句','韋綬','quantangshi','','卷44','在室愧屋漏。','',''),('quantangshi-43667','句','馮戡','quantangshi','','卷44','桃花浪里成龙去，竹叶山头退鷁飞。','',''),('quantangshi-43668','句','韓泰','quantangshi','','卷44','庾岭东边吏隐州，溪山竹树亦清幽。','',''),('quantangshi-43669','句','盧幷','quantangshi','','卷44','地灵无俗草，岩静有仙禽。','',''),('quantangshi-43670','句','繆島雲','quantangshi','','卷44','白鸟远行树，玉虹孤饮潭。
四五片霞生绝壁，两三行雁过疎松。
抛芥子降颠狒狒，折杨枝洒醉猩猩。','',''),('quantangshi-43671','句','劉敬之','quantangshi','','卷44','山近衡阳虽少雁，水连巴蜀岂无鱼。','',''),('quantangshi-43672','句','李濤','quantangshi','','卷44','水声长在耳，山色不离门。
扫地树留影，拂牀琴有声。
落日长安道，秋槐满地花。','',''),('quantangshi-43673','句','高元裕','quantangshi','','卷44','中丞为国拔贤才，寒俊欣逢藻鉴开。','',''),('quantangshi-43674','句','韋澳','quantangshi','','卷44','莫将韦监同殷监，错认容身是保身。','',''),('quantangshi-43675','句','王龜','quantangshi','','卷44','珠箔卷繁星，金樽泻月明。','',''),('quantangshi-43676','句','李郁','quantangshi','','卷44','身死为修刘稹表，名高因让陆洿书。','',''),('quantangshi-43677','句','詹雄','quantangshi','','卷44','尘飞遗恨尽，花落古宫平。
红粉笙歌人代远，月明陵树水东流。','',''),('quantangshi-43678','句','任濤','quantangshi','','卷44','露团沙鹤起，人卧钓船流。','',''),('quantangshi-43679','句','劇燕','quantangshi','','卷44','秪向国门安四海，不离乡井拜三公。','',''),('quantangshi-43680','句','王璘','quantangshi','','卷44','芍药花开菩萨面，椶闾叶散野人头。','',''),('quantangshi-43681','句','李蔚','quantangshi','','卷44','虚心纤质雁衔余，凤吹龙吟定不如。','',''),('quantangshi-43682','句','王枳','quantangshi','','卷44','今朝拜贡盈襟泪，不进新芽是进心。','',''),('quantangshi-43683','句','鄭賨','quantangshi','','卷44','万蕴千牌次碧牙，缥牋金字间明霞。','',''),('quantangshi-43684','句','張塋','quantangshi','','卷44','一箭不中鹄，五湖归钓鱼。','',''),('quantangshi-43685','句','吳靄','quantangshi','','卷44','烟随红焰断，化作白云飞。','',''),('quantangshi-43686','句','陳詠','quantangshi','','卷44','隔岸水牛浮鼻渡，傍溪沙鸟点头行。','',''),('quantangshi-43687','句','蔣密','quantangshi','','卷44','绮罗因片叶，桃李谩同时。','',''),('quantangshi-43688','句','符蒙','quantangshi','','卷44','都缘心似水，故以钵为舟。','',''),('quantangshi-43689','句','李景遂','quantangshi','','卷44','路指丹阳分虎节，心存双阙恋龙颜。','',''),('quantangshi-43690','句','李弘茂','quantangshi','','卷44','甜于泉水茶须信，狂似杨花蝶未知。
半窗月在犹煎药，几夜灯闲不照书。','',''),('quantangshi-43691','句','李平','quantangshi','','卷44','至人无梦梦不到，天道恶盈盈有余。
龙髯已断嫔嫱老，豹尾不来岐路长。','',''),('quantangshi-43692','句','胡元龜','quantangshi','','卷44','翻身腾白浪，探爪擢明珠。','',''),('quantangshi-43693','句','蔣鈞','quantangshi','','卷44','因借梦书过竹寺，学耕秋粟绕茆原。
芭蕉叶上无愁雨，自是多情听断肠。','',''),('quantangshi-43694','句','史虛白','quantangshi','','卷44','风雨揭却屋，全家醉不知。','',''),('quantangshi-43695','句','夏寶松','quantangshi','','卷44','孤猨叫落中岩月，野客吟残半夜灯。
