晓来羸驷依前去，目断遥山数点青。','',''),('quantangshi-43696','句','趙慶','quantangshi','','卷44','迈古文章金鸑鷟，出羣行止玉麒麟。','',''),('quantangshi-43697','句','潘天錫','quantangshi','','卷44','风便磬声远，日斜楼影长。','',''),('quantangshi-43698','句','朱勰','quantangshi','','卷44','好是晚来香雨里，担簦亲送绮罗人。','',''),('quantangshi-43699','句','齊鎬','quantangshi','','卷44','莲中花更好，云里月常新。','',''),('quantangshi-43700','句','黃可','quantangshi','','卷44','天下传将舞马赋，门前迎得跨驴宾。','',''),('quantangshi-43701','句','高元矩','quantangshi','','卷44','砚贮寒泉碧，庭堆败叶红。
燕掠琴弦穿静院，吏收诗草下闲庭。','',''),('quantangshi-43702','句','陳貺','quantangshi','','卷44','年年闻尔者，未有不伤情。
出得风尘者，合知岐路人。
拂榻灯未来，开门月先入。
忽生云是匣，高以月为台。
入夜虽无伤物意，向明还有动人心。','',''),('quantangshi-43703','句','趙休','quantangshi','','卷44','金茎来白露，玉宇起清风。','',''),('quantangshi-43704','句','庸仁傑','quantangshi','','卷44','红斾渡江霞蘸水，青蛇出匣雪侵衣。
云散便凝千里望，日斜长占半城阴。
只住此山宁有意，向来求佛本无心。','',''),('quantangshi-43705','句','邵拙','quantangshi','','卷44','万国不得雨，孤云犹在山。','',''),('quantangshi-43706','句','毛炳','quantangshi','','卷44','先生不在此，千载只空山。','',''),('quantangshi-43707','句','陳德誠','quantangshi','','卷44','建水旧传刘夜坐，螺川新有夏江城。','',''),('quantangshi-43708','句','陳甫','quantangshi','','卷44','一雨洗残暑，万家生早凉。
暮鸟归巢急，寒牛下陇迟。
算吟千百首，方得两三联。
