行人折柳[和轻]絮，飞燕衔泥带落花。','',''),('quantangshi-43712','句','屠瓌智','quantangshi','','卷44','轻身都是义，殉主始为忠。','',''),('quantangshi-43713','句','德昭','quantangshi','','卷44','满堂罗绮兼朱紫，四代儿孙奉老翁。','',''),('quantangshi-43714','句','林無隱','quantangshi','','卷44','雪浦二月江湖阔，花发千山道路香。','',''),('quantangshi-43715','句','楊義方','quantangshi','','卷44','海边红日半离水，天外暖风轻到花。
雨声鞭自禁门出，一簇人从天上来。','',''),('quantangshi-43716','句','王廷珪','quantangshi','','卷44','十字水中分岛屿，数重花外见楼台。','',''),('quantangshi-43717','句','歐陽彬','quantangshi','','卷44','无钱将乞樊知客，名纸生毛不为通。
桑柘残阳里，儿孙落叶中。','',''),('quantangshi-43718','句','李堯夫','quantangshi','','卷44','向外疑无地，其中别有天。
方外共推为道友，关中独自占诗家。
炎暑郁蒸无处避，凉风消息几时来。','',''),('quantangshi-43719','句','石文德','quantangshi','','卷44','月沈湘浦冷，花谢汉宫秋。','',''),('quantangshi-43720','句','戴偃','quantangshi','','卷44','须把咽喉吞世界，盖因奢侈致危亡。
若须抛却便抛却，莫待风高更亦深。','',''),('quantangshi-43721','句','張迥','quantangshi','','卷44','夜长灯影灭，天遶鹤声孤。','',''),('quantangshi-43722','句','鍾元章','quantangshi','','卷44','金筈离弦三尺电，星髇破的一声雷。','',''),('quantangshi-43723','句','楊鳧','quantangshi','','卷44','背日流泉生冻早，逆风归鸟入巢迟。','',''),('quantangshi-43724','句','王俊','quantangshi','','卷44','胜日登楼望，山川一半春。','',''),('quantangshi-43725','句','薛沆','quantangshi','','卷44','也知别有风光主，花蕾枝枝似去年。','',''),('quantangshi-43726','句','張顗','quantangshi','','卷44','金殿圣人看纵笔，玉堂词客尽裁诗。','',''),('quantangshi-43727','句','張林','quantangshi','','卷44','菱叶乍翻人采后，芰荷初没舸行时。','',''),('quantangshi-43728','句','盧休','quantangshi','','卷44','春寒酒力迟，冉冉生微红。
自然草木姓，谁祝元化功。
湓浦风生破胆愁，血染剑花明帐幕。
三千车马出渔阳，入门堪笑复堪怜。
三迳苔荒一钓船。','',''),('quantangshi-43729','句','陳嶠','quantangshi','','卷44','小桥风月年年事，争奈潘郎去□何。','',''),('quantangshi-43730','句','李範','quantangshi','','卷44','清猨啼远木，白鸟下前滩。
鹤归秋汉远，人去草堂空。
虽当南北路，不碍往来人。
钓叟无机沙鸟睡，禅师入定白牛闲。
天涯故友无来信，窗外拒霜空落花。','',''),('quantangshi-43731','句','卞震','quantangshi','','卷44','雨壁长秋菌，风枝落病蝉。
老筇搘瘦影，寒木凭吟身。
诗债到春无处避，离愁因醉暂时无。
茶香解睡磨铛煮，山色牵怀着屐登。','',''),('quantangshi-43732','句','林楚才','quantangshi','','卷44','身闲不恨辞官早，诗好常甘得句迟。','',''),('quantangshi-43733','句','孟不疑','quantangshi','','卷44','白日故乡远，青山佳句中。','',''),('quantangshi-43734','句','龐季子','quantangshi','','卷44','冥云生易满，秋草长难高。','',''),('quantangshi-43735','句','郭思','quantangshi','','卷44','落星一石几千年，门外何人扣汉川。','',''),('quantangshi-43736','句','盧載','quantangshi','','卷44','五千里地望皆见，七十二峰中最高。','',''),('quantangshi-43737','句','鄭翱','quantangshi','','卷44','花烧落第眼，雨破到家程。','',''),('quantangshi-43738','句','鄭說','quantangshi','','卷44','架上紫衣闲不着，案头金字坐长看。','',''),('quantangshi-43739','句','史瑜','quantangshi','','卷44','溪从沮水流嶓冢，岭接青泥入剑天。','',''),('quantangshi-43740','句','賀公','quantangshi','','卷44','但存方寸地，留与子孙耕。','',''),('quantangshi-43741','句','米都知','quantangshi','','卷44','小旗村店酒，微雨野塘花。','',''),('quantangshi-43742','句','陳秀才','quantangshi','','卷44','地偏云自起，日暮山更深。','',''),('quantangshi-43743','句','崔李二生','quantangshi','','卷44','恰似传花人饮散，空抛牀下最繁枝。
艳魄香魂如有在，还应羞见堕楼人。','',''),('quantangshi-43744','句','范氏子','quantangshi','','卷44','扫叶随风便，浇花趁日阴。
闲云生不雨，病叶落非秋。','',''),('quantangshi-43745','句','臨川小吏','quantangshi','','卷44','三月能辞千日醉，一生能得几回看。','',''),('quantangshi-43746','句','韓熙載客','quantangshi','','卷44','最是五更留不住，向人枕畔着衣裳。','',''),('quantangshi-43747','句','段義宗','quantangshi','','卷44','悬心秋夜月，万里照乡关。
玉排复道珊瑚殿，金错危椆翡翠楼。
此花不与众花同，为感高僧护法功。','',''),('quantangshi-43748','无名氏之散句','無名氏','quantangshi','','卷44','都来消帝力，全不用兵防。
道远擎空钵，深山踏落花。
船中江上景，晚泊早行时。
山寺钟楼月，江城鼓角风。
雨过花争出，云空月半生。
鸟正啼隋柳，人须入楚山。
高松飘雨雪，一室掩香灯。
遂有冥心者，还寻此境来。
又因风雨夜，重到古松门。
道晦金鸡伏，时来木马鸣。
谁来看山寺，自去扫松门。
此生还自喜，余事不相侵。
白鬓无心镊，青山得意多。
一春能几日，无雨亦多风。
苦雨秋涛涨，狂风野烧翻。
须知三尺剑，只为不平磨。
要路争先进，闲门肯暂过。
已难消永夜，况复听秋霖。
大雪路亦宿，深山水也吞。
卷帘黄叶落，鏁印子规啼。
亡国空流水，孤祠掩落花。
山魅隔窗舞，鵩鸟入帘飞。
万里八九月，一身西北风。
磴危攀薜荔，石滑疎莓苔。
日落无行客，天寒有去鸿。
正思浮世事，又到古城边。
寻常风雨夜，应有鬼神看。
寄宿山中寺，相辞海上僧。
风吹榆荚叶，雨打木瓜花。
是星皆拱北，无水不朝东。
西风起边雁，一一向潇湘。
那堪怀远路，犹自上高楼。
白云风散尽，红叶水流来。
妾如无异意，君弃也甘心。
野过云根阔，山高树影长。
古迹应重别，生缘不暂停。
一个字未稳，数宵心不闲。
别地叶频落，去程山已寒。
但取诗名得，何论下第频。
早起赴前程，邻鸡尚未鸣。
白地一回雨，儿孙拾得金。
轩车在何处，雨雪满前山。
灯微山馆雨，角咽海城秋。
去帆看已远，临水立多时。
家贫为客早，路远得书稀。
瀑布五千仞，草堂瀑布边。
我忆云门寺，门前千万峰。
一瓶居无外，万木老禅中。
秋江洗一钵，寒日晒三衣。
空山行客少，独树晚蝉多。
一片月生海，几家人上楼。
窗寒风渐紧，灯落夜将深。
云梦几行去，潇湘一夜空。
无风来竹院，有月在莎庭。
故园从小别，夜雨近秋闻。
书剑别南州，炎荒万里游。
山盘樵径上，人到雪房迟。
路经秋雨后，人入乱峰来。
独树知秋早，孤舟觉夜寒。
马饥飡落叶，鹤宿晒残阳。
路远春行尽，家贫愁到时。
临水通宵坐，知君此兴同。
江声兼小雨，暝色入啼猨。
藕隐玲珑玉，花藏缥缈容。
红树醉秋色，碧溪弹夜弦。
网断蛛犹织，梁空燕不归。
倒身无着处，呵手不成温。
几多诗弟子，无限酒知闻。
牀上小薰笼，韶州新退红。
看时人步澁，展处蝶争来。
酒味杂莲气，香冷胜于冰。
轮囷如象鼻，潇洒绝青蝇。
太宗皇帝真长策，赚得英雄尽白头。
曾题名处添前字，送出城人乞旧衣。
华阳观里钟声集，建福门前鼓动期。
陇右诸侯供语鸟，日南太守送名花。
八百孤寒齐下泪，一时回首望崖州。
让劫已令多士伏，沽名还得世人闻。
人为子推初禁火，花愁青女再飞霜。
楝花开后风光好，梅子黄时雨意浓。
兰汤备浴传荆俗，水马浮江吊屈魂。
城头椎鼓传花枝，席上抟拳握松子。
鸟向不香花里宿，人从无影月中归。
轻着冻痕销水面，密随和气入花根。
万木尽如花落候，四檐鸣□雨来时。
浓绿万枝红一点，动人春色不须多。
晚菘细切肥牛肚，新笋初尝嫩马蹄。
蝉离楚树鸣犹少，叶到嵩山落更多。
风和日暖方开眼，雨润烟浓不举头。
窗前闲咏鸳鸯句，壁上时观獬廌图。
可能有事关心后，得似无人识面时。
一点孤灯人梦觉，万重寒叶雨声多。
此心只待相逢说，时复登楼看远山。
九江有浪船难济，三峡无猨客有愁。
四海鱼龙精魄冷，五山鸾凤骨毛寒。
谁家绿酒欢留客，何处红楼睡失明。
雨露施恩无厚薄，蓬蒿随分有枯荣。
去年花下留连饮，暖日夭桃莺乱啼。
今日江边容易别，淡烟衰草马频嘶。
蛇蝎性灵生便毒，蕙兰根异死犹香。
三间茅屋无人到，十里松门独自游。
翻忆旧山青碧里，遶庵闲伴野僧禅。
不甘五等诸侯荐，直肯九重天子知。','',''),('quantangshi-43749','离别难','武后宮人','quantangshi','','卷44','此别难重陈，花飞复恋人。
来时梅覆雪，去日柳含春。
物候催行客，归途淑气新。
剡川今已远，魂梦暗相亲。','',''),('quantangshi-43750','袍中诗','開元宮人','quantangshi','','卷44','沙场征戍客，寒苦若为眠。
战袍经手作，知落阿谁边。
蓄意多添线，含情更着绵。
今生已过也，结取后生缘。','',''),('quantangshi-43751','题洛苑梧叶上','天寶宮人','quantangshi','','卷44','旧宠悲秋扇，新恩寄早春。
聊题一片叶，将寄接流人。','',''),('quantangshi-43752','又题洛苑梧叶上','天寶宮人','quantangshi','','卷44','一叶题诗出禁城，谁人酬和独含情。
自嗟不及波中叶，荡漾乘春取次行。','',''),('quantangshi-43753','题花叶诗','德宗宮人','quantangshi','','卷44','一入深宫里，无由得见春。
题诗花叶上，寄与接流人。','',''),('quantangshi-43754','题红叶','宣宗宮人','quantangshi','','卷44','流水何太急，深宫尽日闲。
殷勤谢红叶，好去到人间。','',''),('quantangshi-43755','金锁诗','僖宗宮人','quantangshi','','卷44','玉烛制袍夜，金刀呵手裁。
锁寄千里客，锁心终不开。','',''),('quantangshi-43756','随驾游青城','李舜弦','quantangshi','','卷44','因随八马上仙山，顿隔尘埃物象闲。
只恐西追王母宴，却忧难得到人间。','',''),('quantangshi-43757','蜀宫应制','李舜弦','quantangshi','','卷44','浓树禁花开后庭，饮筵中散酒微醒。
蒙蒙雨草瑶阶湿，钟晓愁吟独倚屏。','',''),('quantangshi-43758','钓鱼不得','李舜弦','quantangshi','','卷44','尽日池边钓锦鳞，芰荷香里暗消魂。
依稀纵有寻香饵，知是金钩不肯吞。','',''),('quantangshi-43759','宫词','李玉簫','quantangshi','','卷44','鸳鸯瓦上瞥然声，昼寝宫娥梦里惊。
元是我王金弹子，海棠花下打流莺。','',''),('quantangshi-43760','太平诗','真德','quantangshi','','卷44','大唐开鸿业，巍巍皇猷昌。
止戈戎衣定，修文继百王。
统天崇雨施，理物体含章。
深仁谐日月，抚运迈时康。
幡旗既赫赫，钲鼓何鍠鍠。
外夷违命者，翦覆被大殃。
和风凝宇宙，遐迩竞呈祥。
四时调玉烛，七曜巡万方。
维岳降宰辅，维帝用忠良。
三五咸一德，昭我皇家唐。','',''),('quantangshi-43761','句','寶曆宮人','quantangshi','','卷44','宝帐香重重，一双红芙蓉。','',''),('quantangshi-43762','宫词 一','花蕊夫人徐氏','quantangshi','','卷44','五云楼阁凤城间，花木长新日月闲。
三十六宫连内苑，太平天子住昆山。','',''),('quantangshi-43763','宫词 二','花蕊夫人徐氏','quantangshi','','卷44','会真广殿约宫墙，楼阁相扶倚太阳。
净甃玉阶横水岸，御炉香气扑龙牀。','',''),('quantangshi-43764','宫词 三','花蕊夫人徐氏','quantangshi','','卷44','龙池九曲远相通，杨柳丝牵两岸风。
长似江南好风景，画船来去碧波中。','',''),('quantangshi-43765','宫词 四','花蕊夫人徐氏','quantangshi','','卷44','东内斜将紫禁通，龙池凤苑夹城中。
晓钟声断严妆罢，院院纱窗海日红。','',''),('quantangshi-43766','宫词 五','花蕊夫人徐氏','quantangshi','','卷44','殿名新立号重光，岛上亭台尽改张。
但是一人行幸处，黄金阁子锁牙牀。','',''),('quantangshi-43767','宫词 六','花蕊夫人徐氏','quantangshi','','卷44','夹城门与内门通，朝罢巡游到苑中。
每日日高祗候处，满堤红艳立春风。','',''),('quantangshi-43768','宫词 七','花蕊夫人徐氏','quantangshi','','卷44','厨船进食簇时新，侍宴无非列近臣。
日午殿头宣索鲙，隔花催唤打鱼人。','',''),('quantangshi-43769','宫词 八','花蕊夫人徐氏','quantangshi','','卷44','立春日进内园花，红蕊轻轻嫩浅霞。
跪到玉阶犹带露，一时宣赐与宫娃。','',''),('quantangshi-43770','宫词 九','花蕊夫人徐氏','quantangshi','','卷44','三面宫城尽夹墙，苑中池水白茫茫。
直从狮子门前入，旋见亭台遶岸傍。','',''),('quantangshi-43771','宫词 十','花蕊夫人徐氏','quantangshi','','卷44','离宫别院遶宫城，金版轻敲合凤笙。
夜夜月明花树底，傍池长有按歌声。','',''),('quantangshi-43772','宫词 十一','花蕊夫人徐氏','quantangshi','','卷44','御制新翻曲子成，六宫才唱未知名。
尽将觱篥来抄谱，先按君王玉笛声。','',''),('quantangshi-43773','宫词 十二','花蕊夫人徐氏','quantangshi','','卷44','旋移红树斲新苔，宣使龙池更凿开。
展得绿波宽似海，水心楼殿胜蓬莱。','',''),('quantangshi-43774','宫词 十三','花蕊夫人徐氏','quantangshi','','卷44','太虚高阁凌虚殿，背倚城墙面枕池。
诸院各分娘子位，羊车到处不教知。','',''),('quantangshi-43775','宫词 十四','花蕊夫人徐氏','quantangshi','','卷44','修仪承宠住龙池，扫地焚香日午时。
等候大家来院里，看教鹦鹉念新诗。','',''),('quantangshi-43776','宫词 十五','花蕊夫人徐氏','quantangshi','','卷44','才人出入每参随，笔砚将行遶曲池。
能向彩笺书大字，忽防御制写新诗。','',''),('quantangshi-43777','宫词 十六','花蕊夫人徐氏','quantangshi','','卷44','六宫官职总新除，宫女安排入画图。
二十四司分六局，御前频见错相呼。','',''),('quantangshi-43778','宫词 十七','花蕊夫人徐氏','quantangshi','','卷44','春风一面晓妆成，偷折花枝傍水行。
却被内监遥觑见，故将红豆打黄莺。','',''),('quantangshi-43779','宫词 十八','花蕊夫人徐氏','quantangshi','','卷44','殿前排宴赏花开，宫女侵晨探几回。
斜望花开遥举袖，传声宣唤近臣来。','',''),('quantangshi-43780','宫词 十九','花蕊夫人徐氏','quantangshi','','卷44','小球场近曲池头，宣唤勋臣试打球。
先向画楼排御幄，管弦声动立浮油。','',''),('quantangshi-43781','宫词 二十','花蕊夫人徐氏','quantangshi','','卷44','供奉头筹不敢争，上棚等唤近臣名。
内人酌酒才宣赐，马上齐呼万岁声。','',''),('quantangshi-43782','宫词 二十一','花蕊夫人徐氏','quantangshi','','卷44','殿前宫女总纤腰，初学乘骑怯又娇。
上得马来才欲走，几回抛鞚抱鞍桥。','',''),('quantangshi-43783','宫词 二十二','花蕊夫人徐氏','quantangshi','','卷44','自教宫娥学打球，玉鞍初跨柳腰柔。
上棚知是官家认，遍遍长赢第一筹。','',''),('quantangshi-43784','宫词 二十三','花蕊夫人徐氏','quantangshi','','卷44','翔鸾阁外夕阳天，树影花光远接连。
望见内家来往处，水门斜过罨楼船。','',''),('quantangshi-43785','宫词 二十四','花蕊夫人徐氏','quantangshi','','卷44','内家追逐采莲时，惊起沙欧两岸飞。
兰棹把来齐拍水，并船相鬬湿罗衣。','',''),('quantangshi-43786','宫词 二十五','花蕊夫人徐氏','quantangshi','','卷44','新秋女伴各相逢，罨画船飞别浦中。
旋折荷花伴歌舞，夕阳斜照满衣红。','',''),('quantangshi-43787','宫词 二十六','花蕊夫人徐氏','quantangshi','','卷44','少年相逐采莲回，罗帽罗衫巧制裁。
每到岸头长拍水，竞提纤手出船来。','',''),('quantangshi-43788','宫词 二十七','花蕊夫人徐氏','quantangshi','','卷44','早春杨柳引长条，倚岸沿堤一面高。
称与画船牵锦缆，暖风搓出彩丝縧。','',''),('quantangshi-43789','宫词 二十八','花蕊夫人徐氏','quantangshi','','卷44','内家宣锡生辰宴，隔夜诸宫进御花。
后殿未闻宫主入，东门先报下金车。','',''),('quantangshi-43790','宫词 二十九','花蕊夫人徐氏','quantangshi','','卷44','端午生衣进御牀，赭黄罗帕覆金箱。
美人捧入南薰殿，玉腕斜封彩缕长。','',''),('quantangshi-43791','宫词 三十','花蕊夫人徐氏','quantangshi','','卷44','选进仙韶第一人，才胜罗绮不胜春。
重教按舞桃花下，只踏残红作地裀。','',''),('quantangshi-43792','宫词 三十一','花蕊夫人徐氏','quantangshi','','卷44','侍女争挥玉弹弓，金丸飞入乱花中。
一时惊起流莺散，踏落残花满地红。','',''),('quantangshi-43793','宫词 三十二','花蕊夫人徐氏','quantangshi','','卷44','七宝阑干白玉除，新开凉殿幸金舆。
一沟泛碧流春水，四面琼钩搭绮疏。','',''),('quantangshi-43794','宫词 三十三','花蕊夫人徐氏','quantangshi','','卷44','山楼彩凤栖寒月，宴殿金麟吐御香。
蜀锦地衣呈队舞，教头先出拜君王。','',''),('quantangshi-43795','宫词 三十四','花蕊夫人徐氏','quantangshi','','卷44','天外明河翻玉浪，楼西凉月涌金盆。
香销甲乙牀前帐，宫锁玲珑闭殿门。','',''),('quantangshi-43796','宫词 三十五','花蕊夫人徐氏','quantangshi','','卷44','细风攲叶撼宫梧，早怯秋寒着绣繻。
玉宇无人双燕去，一弯新月上金枢。','',''),('quantangshi-43797','宫词 三十六','花蕊夫人徐氏','quantangshi','','卷44','夜寒金屋篆烟飞，灯烛分明在紫微。
漏永禁宫三十六，燕回争踏月轮归。','',''),('quantangshi-43798','宫词 三十七','花蕊夫人徐氏','quantangshi','','卷44','晓吹翩翩动翠旗，炉烟千叠瑞云飞。
何人奏对偏移刻，御史天香隔绣衣。','',''),('quantangshi-43799','宫词 三十八','花蕊夫人徐氏','quantangshi','','卷44','金井秋啼络纬声，出花宫漏报严更。
不知谁是金銮直，玉宇沈沈夜气清。','',''),('quantangshi-43800','宫词 三十九','花蕊夫人徐氏','quantangshi','','卷44','内庭秋燕玉池东，香散荷花水殿风。
阿监采菱牵锦缆，月明犹在画船中。','',''),('quantangshi-43801','宫词 四十','花蕊夫人徐氏','quantangshi','','卷44','东宫花烛彩楼新，天上仙桥上锁春。
偏出六宫歌舞奏，嫦娥初到月虚轮。','',''),('quantangshi-43802','宫词 四十一','花蕊夫人徐氏','quantangshi','','卷44','纱幔薄垂金麦穗，帘钩纤挂玉葱条。
楼西别起长春殿，香碧红泥透蜀椒。','',''),('quantangshi-43803','宫词 四十二','花蕊夫人徐氏','quantangshi','','卷44','翠华香重玉炉添，双凤楼头晓日暹。
扇掩红鸾金殿悄，一声清跸卷珠帘。','',''),('quantangshi-43804','宫词 四十三','花蕊夫人徐氏','quantangshi','','卷44','金作蟠龙绣作麟，壶中楼阁禁中春。
君王避暑来游幸，风月横秋气象新。','',''),('quantangshi-43805','宫词 四十四','花蕊夫人徐氏','quantangshi','','卷44','清晓自倾花上露，冷侵宫殿玉蟾蜍。
擘开五色销金纸，碧锁窗前学草书。','',''),('quantangshi-43806','宫词 四十五','花蕊夫人徐氏','quantangshi','','卷44','翠钿贴靥轻如笑，玉凤雕钗褭欲飞。
拂晓贺春皇帝阁，彩衣金胜近龙衣。','',''),('quantangshi-43807','宫词 四十六','花蕊夫人徐氏','quantangshi','','卷44','璅声金彻合门环，帘卷珍珠十二间。
别殿春风呼万岁，中丞新押散朝班。','',''),('quantangshi-43808','宫词 四十七','花蕊夫人徐氏','quantangshi','','卷44','鸡人报晓传三唱，玉井金牀转辘轳。
烟引御炉香绕殿，漏签初刻上铜壶。','',''),('quantangshi-43809','宫词 四十八','花蕊夫人徐氏','quantangshi','','卷44','御按横金殿幄红，扇开云表露天容。
太常奏备三千曲，乐府新调十二钟。','',''),('quantangshi-43810','宫词 四十九','花蕊夫人徐氏','quantangshi','','卷44','宫女熏香进御衣，殿门开锁请金匙。
朝阳初上黄金屋，禁夜春深昼漏迟。','',''),('quantangshi-43811','宫词 五十','花蕊夫人徐氏','quantangshi','','卷44','三月金明柳絮飞，岸花堤草弄春时。
楼船百戏催宣赐，御辇今年不上池。','',''),('quantangshi-43812','宫词 五十一','花蕊夫人徐氏','quantangshi','','卷44','内人稀见水秋千，争擘珠帘帐殿前。
第一锦标谁夺得，右军输却小龙船。','',''),('quantangshi-43813','宫词 五十二','花蕊夫人徐氏','quantangshi','','卷44','夜色楼台月数层，金猊烟穗绕觚棱。
重廊屈折连三殿，密上真珠百宝灯。','',''),('quantangshi-43814','宫词 五十三','花蕊夫人徐氏','quantangshi','','卷44','天门晏闭九重关，楼倚银河气象间。
一点星球垂绛阙，五云仙仗下蓬山。','',''),('quantangshi-43815','宫词 五十四','花蕊夫人徐氏','quantangshi','','卷44','禁里春浓蝶自飞，御蚕眠处弄新丝。
碧窗尽日教鹦鹉，念得君王数首诗。','',''),('quantangshi-43816','宫词 五十五','花蕊夫人徐氏','quantangshi','','卷44','鬬草深宫玉槛前，春蒲如箭荇如钱。
不如红药阑干曲，日暮何人落翠钿。','',''),('quantangshi-43817','宫词 五十六','花蕊夫人徐氏','quantangshi','','卷44','太液波清水殿凉，画船惊起宿鸳鸯。
翠眉不及池边柳，取次飞花入建章。','',''),('quantangshi-43818','宫词 五十七','花蕊夫人徐氏','quantangshi','','卷44','御座垂帘绣额单，冰山重叠贮金盘。
玉清迢遰无尘到，殿角东西五月寒。','',''),('quantangshi-43819','宫词 五十八','花蕊夫人徐氏','quantangshi','','卷44','春心滴破花边漏，晓梦敲回禁里钟。
十二楚山何处是，御楼曾见两三峰。','',''),('quantangshi-43820','宫词 五十九','花蕊夫人徐氏','quantangshi','','卷44','博山夜宿沈香火，帐外时闻暖凤笙。
理遍从头新上曲，殿前龙直未交更。','',''),('quantangshi-43821','宫词 六十','花蕊夫人徐氏','quantangshi','','卷44','春殿千官宴却归，上林莺舌报花时。
宣徽旋进新裁曲，学士争吟应诏诗。','',''),('quantangshi-43822','宫词 六十一','花蕊夫人徐氏','quantangshi','','卷44','钓线沈波漾彩舟，鱼争芳饵上龙钩。
内人急捧金盘接，拨刺红鳞跃未休。','',''),('quantangshi-43823','宫词 六十二','花蕊夫人徐氏','quantangshi','','卷44','蕙炷香销烛影残，御衣熏尽輙更阑。
归来困顿眠红帐，一枕西风梦里寒。','',''),('quantangshi-43824','宫词 六十三','花蕊夫人徐氏','quantangshi','','卷44','东宫降诞挺佳辰，少海星边拥瑞云。
中尉传闻三日宴，翰林当撰洗儿文。','',''),('quantangshi-43825','宫词 六十四','花蕊夫人徐氏','quantangshi','','卷44','酒库新修近水傍，泼醅初熟五云浆。
殿前供御频宣索，追入花间一阵香。','',''),('quantangshi-43826','宫词 六十五','花蕊夫人徐氏','quantangshi','','卷44','白藤花限白银花，合子门当寝殿斜。
近被宫中知了事，每来随驾使煎茶。','',''),('quantangshi-43827','宫词 六十六','花蕊夫人徐氏','quantangshi','','卷44','西球场里打球回，御宴先于苑内开。
宣索教坊诸伎乐，傍池催唤入船来。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-43828','宫词 六十七','花蕊夫人徐氏','quantangshi','','卷44','昭仪侍宴足精神，玉烛抽看记饮巡。
倚赖识书为录事，灯前时复错瞒人。','',''),('quantangshi-43829','宫词 六十八','花蕊夫人徐氏','quantangshi','','卷44','后宫阿监裹罗巾，出入经过苑囿频。
承奉圣颜忧悞失，就中长怕内夫人。','',''),('quantangshi-43830','宫词 六十九','花蕊夫人徐氏','quantangshi','','卷44','管弦声急满龙池，宫女藏钩夜宴时。
好是圣人亲捉得，便将浓墨扫双眉。','',''),('quantangshi-43831','宫词 七十','花蕊夫人徐氏','quantangshi','','卷44','密室红泥地火炉，内人冬日晚传呼。
