寒食内人长白打，库中先散与金钱。','',''),('quantangshi-43915','宫词 一五四','花蕊夫人徐氏','quantangshi','','卷44','众中偏得君王笑，偷把金箱笔砚开。
书破红蛮隔子上，旋推当直美人来。','',''),('quantangshi-43916','宫词 一五五','花蕊夫人徐氏','quantangshi','','卷44','水中芹叶土中花，拾得还将避众家。
总待别人般数尽，袖中拈出郁金芽。','',''),('quantangshi-43917','宫词 一五六','花蕊夫人徐氏','quantangshi','','卷44','玉箫改调筝移柱，催换红罗绣舞筵。
未戴柘枝花帽子，两行宫监在帘前。','',''),('quantangshi-43918','宫词 一五七','花蕊夫人徐氏','quantangshi','','卷44','窗窗户户院相当，总有珠帘玳瑁牀。
虽道君王不来宿，帐中长是炷牙香。','',''),('quantangshi-43919','述国亡诗','花蕊夫人徐氏','quantangshi','','卷44','君王城上竖降旗，妾在深宫那得知。
十四万人齐解甲，宁无一个是男儿。','',''),('quantangshi-43920','新妆诗','楊容華','quantangshi','','卷44','啼鸟惊眠罢，房栊乘晓开。
凤钗金作缕，鸾镜玉为台。
妆似临池出，人疑向月来。
自怜终不见，欲去复裴回。','',''),('quantangshi-43921','赠外','魏氏','quantangshi','','卷44','浮萍依绿水，弱茑寄青松。
与君结大义，移天得所从。
翰林无双鸟，劒水不分龙。
谐和类琴瑟，坚固同胶漆。
义重恩欲深，夷险贵如一。
本自身不令，积多婴痛疾。
朝夕倦牀枕，形体耻巾栉。
游子倦风尘，从官初解巾。
束装赴南郢，脂驾出西秦。
比翼终难遂，衔雌苦未因。
徒悲枫岸远，空对柳园春。
男儿不重旧，丈夫多好新。
新人喜新聘，朝朝临粉镜。
两鸳固无比，双蛾谁与竞。
讵怜愁思人，衔啼嗟薄命。
蕣华不足恃，松枝有余劲。
所愿好九思，勿令亏百行。','',''),('quantangshi-43922','咏破帘','喬氏','quantangshi','','卷44','已漏风声罢，绳持也不禁。
一从经落后，无复有贞心。','',''),('quantangshi-43923','送兄','七歲女子','quantangshi','','卷44','别路云初起，离亭叶正飞。
所嗟人异雁，不作一行归。','',''),('quantangshi-43924','送男左贬诗','林氏','quantangshi','','卷44','他日初投杼，勤王在饮冰。
有辞期不罚，积毁竟相仍。
谪宦今何在，衔冤犹未胜。
天涯分越徼，驿骑速毗陵。
肠断腹非苦，书传写岂能。
泪添江水远，心剧海云蒸。
明月珠难识，甘泉赋可称。
但将忠报主，何惧点青蝇。','',''),('quantangshi-43925','古兴 一','趙氏','quantangshi','','卷44','郁蒸夏将半，暑气扇飞阁。
骤雨满空来，当轩卷罗幕。
度云开夕霁，宇宙何清廓。
明月流素光，轻风换炎铄。
孤鸾伤对影，宝瑟悲别鹤。
君子去不还，遥心欲何托。','',''),('quantangshi-43926','古兴 二','趙氏','quantangshi','','卷44','金菊延清霜，玉壶多美酒。
良人犹不归，芳菲岂常有。
不惜芳菲歇，但伤别离久。
含情罢斟酌，凝怨对窗牖。','',''),('quantangshi-43927','古兴 三','趙氏','quantangshi','','卷44','霁雪舒长野，寒云半幽谷。
严风振枯条，猨啼抱冰木。
所嗟游宦子，少小荷天禄。
前程未云至，凄怆对车仆。
岁寒成咏歌，日暮栖林朴。
不惮行险道，空悲年运促。','',''),('quantangshi-43928','寄夫','郭紹蘭','quantangshi','','卷44','我壻去重湖，临窗泣血书。
殷勤凭燕翼，寄与薄情夫。','',''),('quantangshi-43929','同夫游秦','王韞秀','quantangshi','','卷44','路扫饥寒迹，天哀志气人。
休零离别泪，携手入西秦。','',''),('quantangshi-43930','夫入相寄姨妹','王韞秀','quantangshi','','卷44','相国已随麟阁贵，家风第一右丞诗。
笄年解笑鸣机妇，耻见苏秦富贵时。','',''),('quantangshi-43931','喻夫阻客','王韞秀','quantangshi','','卷44','楚竹燕歌动画梁，春兰重换舞衣裳。
公孙开阁招嘉客，知道浮荣不久长。','',''),('quantangshi-43932','古意','張夫人','quantangshi','','卷44','辘轳晓转素丝绠，桐声夜落苍苔塼。
涓涓吹溜若时雨，濯濯佳蔬非用天。
丈夫不解此中意，抱瓮当时徒自贤。','',''),('quantangshi-43933','拜新月','張夫人','quantangshi','','卷44','拜新月，拜月出堂前。
暗魄初笼桂，虚弓未引弦。
拜新月，拜月妆楼上。
鸾镜始安台，蛾眉已相向。
拜新月，拜月不胜情，庭花风露清。
月临人自老，人望月长明。
东家阿母亦拜月，一拜一悲声断绝。
昔年拜月逞容辉，如今拜月双泪垂。
回看众女拜新月，却忆红闺年少时。','',''),('quantangshi-43934','柳絮','張夫人','quantangshi','','卷44','霭霭芳春朝，雪絮起青条。
或值花同舞，不因风自飘。
过尊浮绿醑，拂幌缀红绡。
那用持愁翫，春怀不自聊。','',''),('quantangshi-43935','拾得韦氏花钿以诗寄赠','張夫人','quantangshi','','卷44','今朝妆阁前，拾得旧花钿。
粉汚痕犹在，尘侵色尚鲜。
曾经纤手里，拈向翠眉边。
能助千金笑，如何忍弃捐。','',''),('quantangshi-43936','诮喜鹊','張夫人','quantangshi','','卷44','畴昔鸳鸯侣，朱门贺客多。
如今无此事，好去莫相过。','',''),('quantangshi-43937','句','張夫人','quantangshi','','卷44','游蜂乍起惊落墀，黄鸟衔来却上枝。
临风重回首，掩泪向庭花。
镜中春色老，枕前秋夜长。','',''),('quantangshi-43938','书石壁','王氏','quantangshi','','卷44','何事潘郎恋别筵，欢情未断妾心悬。
汰王滩下相思处，猨叫山山月满船。','',''),('quantangshi-43939','答微之','裴淑','quantangshi','','卷44','侯门初拥节，御苑柳丝新。
不是悲殊命，唯愁别近亲。
黄莺迁古木，朱履从清尘。
想到千山外，沧江正暮春。','',''),('quantangshi-43940','夫下第','趙氏','quantangshi','','卷44','良人的的有奇才，何事年年被放回。
如今妾面羞君面，君若来时近夜来。','',''),('quantangshi-43941','杂言寄杜羔','趙氏','quantangshi','','卷44','君从淮海游，再过兰杜秋。
归来未须臾，又欲向梁州。
梁州秦岭西，栈道与云齐。
羌蛮万余落，矛戟自高低。
已念寡俦侣，复虑劳攀跻。
丈夫重志气，儿女空悲啼。
临邛滞游地，肯顾浊水泥。
人生赋命有厚薄，君但遨游我寂寞。','',''),('quantangshi-43942','闻夫杜羔登第','趙氏','quantangshi','','卷44','长安此去无多地，郁郁葱葱佳气浮。
良人得意正年少，今夜醉眠何处楼。','',''),('quantangshi-43943','杂言','趙氏','quantangshi','','卷44','上林园中青青桂，折得一枝好夫壻。
杏花如雪柳垂丝，春风荡扬不同枝。','',''),('quantangshi-43944','寄夫 一','張氏','quantangshi','','卷44','久无音信到罗帏，路远迢迢遣问谁。
闻君折得东堂桂，折罢那能不暂归。','',''),('quantangshi-43945','寄夫 二','張氏','quantangshi','','卷44','驿使今朝过五湖，殷勤为我报狂夫。
从来夸有龙泉劒，试割相思得断无。','',''),('quantangshi-43946','赠郑女郎','薛馧','quantangshi','','卷44','艳阳灼灼河洛神，珠帘绣户青楼春。
能弹箜篌弄纤指，愁杀门前少年子。
笑开一面红粉妆，东园几树桃花死。
朝理曲，暮理曲，独坐窗前一片玉。
行也娇，坐也娇，见之令人魂魄销。
堂前锦褥红地炉，绿沈香榼倾屠苏。
解佩时时歇歌管，芙蓉帐里兰麝满。
晚起罗衣香不断，灭烛每嫌秋夜短。','',''),('quantangshi-43947','古意','薛馧','quantangshi','','卷44','昨夜巫山中，失却阳台女。
朝来香阁里，独伴楚王语。','',''),('quantangshi-43948','赠故人','薛馧','quantangshi','','卷44','昔别容如玉，今来鬓若丝。
泪痕应共见，肠断阿谁知。','',''),('quantangshi-43949','句','薛馧','quantangshi','','卷44','寂寞相思处，雕梁落燕泥。','',''),('quantangshi-43950','题奉慈寺','楊德麟','quantangshi','','卷44','日月金轮动，旃檀碧树秋。
塔分鸿雁翅，钟挂凤凰楼。','',''),('quantangshi-43951','述怀','崔氏','quantangshi','','卷44','不怨卢郎年纪大，不怨卢郎官职卑。
自恨妾身生较晚，不及卢郎年少时。','',''),('quantangshi-43952','寄夫','陳玉蘭','quantangshi','','卷44','夫戍边关妾在吴，西风吹妾妾忧夫。
一行书信千行泪，寒到君边衣到无。','',''),('quantangshi-43953','写真寄夫','薛媛','quantangshi','','卷44','欲下丹青笔，先拈宝镜寒。
已经颜索寞，渐觉鬓凋残。
泪眼描将易，愁肠写出难。
恐君浑忘却，时展画图看。','',''),('quantangshi-43954','闻琴','孫氏','quantangshi','','卷44','玉指朱弦轧复清，湘妃愁怨最难听。
初疑飒飒凉风劲，又似萧萧暮雨零。
近比流泉来碧嶂，远如玄鹤下青冥。
夜深弹罢堪惆怅，露湿丛兰月满庭。','',''),('quantangshi-43955','白蜡烛诗','孫氏','quantangshi','','卷44','景胜银釭香比兰，一条白玉逼人寒。
他时紫禁春风夜，醉草天书仔细看。','',''),('quantangshi-43956','谢人送酒','孫氏','quantangshi','','卷44','谢将清酒寄愁人，澄澈甘香气味真。
好是绿窗风月夜，一杯摇荡满怀春。','',''),('quantangshi-43957','诗','張立本女','quantangshi','','卷44','危冠广袖楚宫妆，独步闲庭逐夜凉。
自把玉簪敲砌竹，清歌一曲月如霜。','',''),('quantangshi-43958','绣龟形诗','侯氏','quantangshi','','卷44','暌离已是十秋强，对镜那堪重理妆。
闻雁几回修尺素，见霜先为制衣裳。
开箱叠练先垂泪，拂杵调砧更断肠。
绣作龟形献天子，愿教征客早还乡。','',''),('quantangshi-43959','感夫诗','慎氏','quantangshi','','卷44','当时心事已相关，雨散云飞一饷间。
便是孤帆从此去，不堪重上望夫山。','',''),('quantangshi-43960','谣','薛瑤','quantangshi','','卷44','化云心兮思淑贞，洞寂灭兮不见人。
瑶草芳兮思芬蒀，将奈何兮青春。','',''),('quantangshi-43961','题唐安寺阁壁','王霞卿','quantangshi','','卷44','春来引步暂寻游，愁见风光倚寺楼。
正好开怀对烟月，双眉不觉自如钩。','',''),('quantangshi-43962','答郑殷彝','王霞卿','quantangshi','','卷44','君是烟霄折桂身，圣朝方切用儒珍。
正堪西上文场战，空向途中泥妇人。','',''),('quantangshi-43963','喜卢郎及第','竇梁賓','quantangshi','','卷44','晓妆初罢眼初瞤，小玉惊人踏破帬。
手把红笺书一纸，上头名字有郎君。','',''),('quantangshi-43964','雨中看牡丹','竇梁賓','quantangshi','','卷44','东风未放晓泥干，红药花开不奈寒。
待得天晴花已老，不如携手雨中看。','',''),('quantangshi-43965','书桐叶','任氏','quantangshi','','卷44','拭翠敛蛾眉，郁郁心中事。
搦管下庭除，书成相思字。
此字不书石，此字不书纸。
书在桐叶上，愿逐秋风起。
天下有心人，尽解相思死。
天下负心人，不识相思字。
有心与负心，不知落何地。','',''),('quantangshi-43966','下狱贡诗','黃崇嘏','quantangshi','','卷44','偶辞幽隐在临邛，行止坚贞比涧松。
何事政清如水镜，绊他野鹤在深笼。','',''),('quantangshi-43967','辞蜀相妻女诗','黃崇嘏','quantangshi','','卷44','一辞拾翠碧江湄，贫守蓬茅但赋诗。
自服蓝衫居郡掾，永抛鸾镜画蛾眉。
立身卓尔青松操，挺志铿然白璧姿。
幕府若容为坦腹，愿天速变作男儿。','',''),('quantangshi-43968','答诸姊妹戒饮','蔣氏','quantangshi','','卷44','平生偏好酒，劳尔劝吾餐。
但得杯中满，时光度不难。','',''),('quantangshi-43969','书壁','周仲美','quantangshi','','卷44','爱妾不爱子，为问此何理。
弃官更弃妻，人情宁可已。
永诀泗之滨，遗言空在耳。
三载无朝昏，孤帏泪如洗。
妇人义从夫，一节誓生死。
江乡感残春，肠断晚烟起。
西望太华峰，不知几千里。','',''),('quantangshi-43970','溪口云','張文姬','quantangshi','','卷44','溶溶溪口云，才向溪中吐。
不复归溪中，还作溪中雨。','',''),('quantangshi-43971','池上竹','張文姬','quantangshi','','卷44','此君临此池，枝低水相近。
碧色绿波中，日日流不尽。','',''),('quantangshi-43972','沙上鹭','張文姬','quantangshi','','卷44','沙头一水禽，鼓翼扬清音。
只待高风便，非无云汉心。','',''),('quantangshi-43973','双槿树','張文姬','quantangshi','','卷44','绿影竞扶疎，红姿相照灼。
不学桃李花，乱向春风落。','',''),('quantangshi-43974','狱中书情上使君','程長文','quantangshi','','卷44','妾家本住鄱阳曲，一片贞心比孤竹。
当年二八盛容仪，红牋草隶恰如飞。
尽日闲窗刺绣坐，有时极浦采莲归。
谁道居贫守都邑，幽闺寂寞无人识。
海燕朝归衾枕寒，山花夜落阶墀湿。
强暴之男何所为，手持白刃向帘帏。
一命任从刀下死，千金岂受暗中欺。
我心匪石情难转，志夺秋霜意不移。
血溅罗衣终不恨，疮黏锦袖亦何辞。
县僚曾未知情绪，即便教人絷囹圄。
朱唇滴沥独衔冤，玉筯阑干叹非所。
十月寒更堪思人，一闻击柝一伤神。
高髻不梳云已散，蛾眉罢埽月仍新。
三尺严章难可越，百年心事向谁说。
但看洗雪出圜扉，始信白圭无玷缺。','',''),('quantangshi-43975','铜雀台怨','程長文','quantangshi','','卷44','君王去后行人绝，箫筝不响歌喉咽。
雄劒无威光彩沈，宝琴零落金星灭。
玉阶寂寞坠秋露，月照当时歌舞处。
当时歌舞人不回，化为今日西陵灰。','',''),('quantangshi-43976','春闺怨','程長文','quantangshi','','卷44','[绮]陌香飘柳如线，时光瞬息如流电。
良人何处事功名，十载相思不相见。','',''),('quantangshi-43977','答韩翃','柳氏','quantangshi','','卷44','杨柳枝，芳菲节，可恨年年赠离别。
一叶随风忽报秋，纵使君来岂堪折。','',''),('quantangshi-43978','归李江州后寄别王氏','程洛賓','quantangshi','','卷44','鱼雁回时写报音，难凭锉蘖数年心。
虽然情断沙吒后，争奈平生怨恨深。','',''),('quantangshi-43979','忆崔生','紅綃妓','quantangshi','','卷44','深洞莺啼恨阮郎，偷来花下解珠璫。
碧云飘断音书绝，空倚玉箫愁凤皇。','',''),('quantangshi-43980','寄文茂','晁采','quantangshi','','卷44','花笺制叶寄郎边，的的寻鱼为妾传。
并蒂已看灵鹊报，倩郎早觅买花船。','',''),('quantangshi-43981','秋日再寄','晁采','quantangshi','','卷44','珍簟生凉夜漏余，梦中恍惚觉来初。
魂离不得空成病，面见无由浪寄书。
窗外江村钟响绝，枕边梧叶雨声疎。
此时最是思君处，肠断寒猨定不如。','',''),('quantangshi-43982','春日送夫之长安','晁采','quantangshi','','卷44','思君远别妾心愁，踏翠江边送画舟。
